    public void playHitSound(double intensity) {
        double volume = Math.min(1.0, intensity / 40.0);
        // Heavier hits play slightly lower-pitched so big impacts sound beefier;
        // the random spread keeps rapid combos from sounding machine-gun identical.
        double heaviness = Math.clamp(intensity / 60.0, 0.0, 1.0);
        double baseRate = 1.06 - heaviness * 0.18;
        playManagedSfxVaried(bonkClip, volume, baseRate, 0.10);
    }

    public boolean isSfxEnabled() {
        return sfxEnabled;
    }

    private double sanitizeVolume(double value) {
        if (Double.isNaN(value) || Double.isInfinite(value)) {
            return 0.0;
        }
        return Math.clamp(value, 0.0, 1.0);
    }

    private boolean isMutedVolume(double value) {
        return sanitizeVolume(value) <= 0.0001;
    }

    private String formatVolumePercent(double value) {
        return (int) Math.round(sanitizeVolume(value) * 100.0) + "%";
    }

    private double effectiveMusicVolume() {
        return musicEnabled ? sanitizeVolume(musicVolume) : 0.0;
    }

    private double effectiveSfxVolume() {
        return sfxEnabled ? sanitizeVolume(sfxVolume) : 0.0;
    }

    // Match music ducks under dramatic moments (KO slow-mo, winner focus) and
    // eases back afterward. 1.0 = full volume; updated once per render pulse.
    private double musicDuckLevel = 1.0;

    private void updateMusicDucking() {
        double target = hasShoebillFinalStillnessActive()
                ? 0.0
                : dramaticSlowMoTicks > 0 || (matchEnded && matchEndFocusBird != null) ? 0.35 : 1.0;
        double eased = target <= 0.0 ? 0.0 : musicDuckLevel + (target - musicDuckLevel) * 0.12;
        if (Math.abs(eased - target) < 0.01) {
            eased = target;
        }
        if (eased == musicDuckLevel) {
            return;
        }
        musicDuckLevel = eased;
        if (musicPlayer != null) {
            musicPlayer.setVolume(MATCH_MUSIC_BASE_VOLUME * effectiveMusicVolume() * musicDuckLevel);
        }
    }

    private void applyAudioVolumes() {
        double music = effectiveMusicVolume();
        if (menuMusicPlayer != null) {
            menuMusicPlayer.setVolume(MENU_MUSIC_BASE_VOLUME * music);
        }
        if (victoryMusicPlayer != null) {
            victoryMusicPlayer.setVolume(VICTORY_MUSIC_BASE_VOLUME * music);
        }
        if (defeatMusicPlayer != null) {
            defeatMusicPlayer.setVolume(DEFEAT_MUSIC_BASE_VOLUME * music);
        }
        if (musicPlayer != null) {
            musicPlayer.setVolume(MATCH_MUSIC_BASE_VOLUME * music * musicDuckLevel);
        }
        double sfx = effectiveSfxVolume();
        if (bonkClip != null) bonkClip.setVolume(sfx);
        if (butterClip != null) butterClip.setVolume(sfx);
        if (jalapenoClip != null) jalapenoClip.setVolume(sfx);
        if (swingClip != null) swingClip.setVolume(sfx);
        if (hugewaveClip != null) hugewaveClip.setVolume(sfx);
        if (buttonClickClip != null) buttonClickClip.setVolume(BUTTON_CLICK_BASE_VOLUME * sfx);
        if (steamAchievementClip != null) steamAchievementClip.setVolume(ACHIEVEMENT_SOUND_BASE_VOLUME * sfx);
        if (zombieFallingClip != null) zombieFallingClip.setVolume(sfx);
        if (vaseBreakingClip != null) vaseBreakingClip.setVolume(sfx);
        if (cherrybombClip != null) cherrybombClip.setVolume(sfx);
        if (fightReadyClip != null) fightReadyClip.setVolume(sfx);
        if (rebirthNovaClip != null) rebirthNovaClip.setVolume(sfx);
    }

    private void setMusicVolume(double value) {
        musicVolume = sanitizeVolume(value);
        musicEnabled = !isMutedVolume(musicVolume);
        applyAudioVolumes();
        if (!musicEnabled) {
            disposeGameplayMusicPlayer();
            stopPersistentMusicPlayers();
        }
    }

    private void setSfxVolume(double value) {
        sfxVolume = sanitizeVolume(value);
        sfxEnabled = !isMutedVolume(sfxVolume);
        applyAudioVolumes();
    }

    void playManagedSfx(AudioClip clip, double baseVolume) {
        if (clip == null) return;
        double effective = sanitizeVolume(baseVolume) * effectiveSfxVolume();
        if (effective <= 0.0) return;
        clip.play(effective);
    }

    /**
     * Plays a clip with randomized pitch and slight volume jitter so repeated
     * sounds don't read as identical copies. {@code baseRate} shifts the whole
     * pitch (1.0 = original); {@code pitchSpread} is the +/- random range around it.
     * Uses {@link #audioRandom}, never the sim RNG — audio is presentation only.
     */
    void playManagedSfxVaried(AudioClip clip, double baseVolume, double baseRate, double pitchSpread) {
        if (clip == null) return;
        double effective = sanitizeVolume(baseVolume) * effectiveSfxVolume();
        if (effective <= 0.0) return;
        double rate = baseRate + (audioRandom.nextDouble() * 2.0 - 1.0) * pitchSpread;
        rate = Math.clamp(rate, 0.5, 2.0);
        double volumeJitter = 1.0 - audioRandom.nextDouble() * 0.12;
        clip.play(Math.clamp(effective * volumeJitter, 0.0, 1.0), 0.0, rate, 0.0, 0);
    }

