    private StoryChapter[] activeStoryChapters() {
        return switch (selectedEpisode) {
            case BAT -> batStoryChapters;
            case PELICAN -> pelicanStoryChapters;
            default -> storyChapters;
        };
    }

    private BirdType activeEpisodePlayerType() {
        return switch (selectedEpisode) {
            case BAT -> BirdType.BAT;
            case PELICAN -> BirdType.PELICAN;
            default -> BirdType.PIGEON;
        };
    }

    private String activeEpisodeTitle() {
        return switch (selectedEpisode) {
            case BAT -> BAT_EPISODE_TITLE;
            case PELICAN -> PELICAN_EPISODE_TITLE;
            default -> PIGEON_EPISODE_TITLE;
        };
    }

    private int getEpisodeUnlocked(EpisodeType ep) {
        return switch (ep) {
            case BAT -> batEpisodeUnlockedChapters;
            case PELICAN -> pelicanEpisodeUnlockedChapters;
            default -> pigeonEpisodeUnlockedChapters;
        };
    }

    private boolean isEpisodeCompleted(EpisodeType ep) {
        return switch (ep) {
            case BAT -> batEpisodeCompleted;
            case PELICAN -> pelicanEpisodeCompleted;
            default -> pigeonEpisodeCompleted;
        };
    }

    private void setEpisodeUnlocked(EpisodeType ep, int value) {
        if (ep == EpisodeType.BAT) batEpisodeUnlockedChapters = value;
        else if (ep == EpisodeType.PELICAN) pelicanEpisodeUnlockedChapters = value;
        else pigeonEpisodeUnlockedChapters = value;
    }

    boolean isEpisodeCompletedForBird(BirdType type) {
        if (type == BirdType.BAT) {
            return batEpisodeCompleted;
        }
        if (type == BirdType.PELICAN) {
            return pelicanEpisodeCompleted;
        }
        return type == BirdType.PIGEON && pigeonEpisodeCompleted;
    }

    void setEpisodeCompletedForBird(BirdType type) {
        if (type == BirdType.BAT) {
            batEpisodeCompleted = true;
            return;
        }
        if (type == BirdType.PELICAN) {
            pelicanEpisodeCompleted = true;
            return;
        }
        if (type == BirdType.PIGEON) {
            pigeonEpisodeCompleted = true;
        }
    }

    int episodeChapterCountForBird(BirdType type) {
        if (type == BirdType.BAT) {
            return batStoryChapters.length;
        }
        if (type == BirdType.PELICAN) {
            return pelicanStoryChapters.length;
        }
        return type == BirdType.PIGEON ? storyChapters.length : 0;
    }

    void setEpisodeUnlockedChaptersForBird(BirdType type, int value) {
        if (type == BirdType.BAT) {
            batEpisodeUnlockedChapters = Math.clamp(value, 1, batStoryChapters.length);
            return;
        }
        if (type == BirdType.PELICAN) {
            pelicanEpisodeUnlockedChapters = Math.clamp(value, 1, pelicanStoryChapters.length);
            return;
        }
        if (type == BirdType.PIGEON) {
            pigeonEpisodeUnlockedChapters = Math.clamp(value, 1, storyChapters.length);
        }
    }

    private String episodeBriefing(EpisodeType ep) {
        return switch (ep) {
            case BAT -> "You are the Bat. Use cave ceilings, sonar, and air control to dominate each chapter.";
            case PELICAN ->
                    "You are the Pelican. Expect scripted chaos: tag-team rounds, survival swarms, and multi-boss fights.";
            default -> "You are the Pigeon. Keep pushing through each chapter. Win to unlock the next fight.";
        };
    }

    private StoryChapter[] chaptersForEpisode(EpisodeType ep) {
        return switch (ep) {
            case BAT -> batStoryChapters;
            case PELICAN -> pelicanStoryChapters;
            default -> storyChapters;
        };
    }

    private boolean isBirdUnlocked(BirdType type) {
        return switch (type) {
            case BAT -> batUnlocked;
            case FALCON -> falconUnlocked;
            case HEISENBIRD -> heisenbirdUnlocked;
            case PHOENIX -> phoenixUnlocked;
            case TITMOUSE -> titmouseUnlocked;
            case RAVEN -> ravenUnlocked;
            case ROADRUNNER -> roadrunnerUnlocked;
            case ROOSTER -> roosterUnlocked;
            default -> true;
        };
    }

    private boolean isMapUnlocked(MapType map) {
        // FEATHERDEV is a live entitlement, not a snapshot of whichever map
        // booleans existed when the code was entered.  Bypass every individual
        // unlock gate so old developer saves also receive maps added later.
        if (developerInfiniteBirdCoins) return true;
        if (map == MapType.DESERT) return desertMapUnlocked;
        if (map == MapType.CAVE) return caveMapUnlocked;
        if (map == MapType.BATTLEFIELD) return battlefieldMapUnlocked;
        if (map == MapType.BEACON_CROWN) return beaconCrownMapUnlocked;
        if (map == MapType.DOCK) return dockMapUnlocked;
        if (map == MapType.PRISON) return prisonMapUnlocked;
        if (map == MapType.RESONANCE_HALL || map == MapType.SIGNAL_SPIRE
                || map == MapType.SILENT_AMPHITHEATER) {
            return isClassicCompleted(BirdType.MOCKINGBIRD);
        }
        if (map == MapType.GLASSWIND_CAUSEWAY || map == MapType.WORLDSEAM) {
            return isClassicCompleted(BirdType.RAZORBILL);
        }
        if (map == MapType.MIDNIGHT_WORKSHOP) {
            return isClassicCompleted(BirdType.GRINCHHAWK);
        }
        if (map == MapType.CARRION_EXCHANGE) {
            return isClassicCompleted(BirdType.VULTURE);
        }
        if (map == MapType.ONEIRIC_OBSERVATORY) {
            return isClassicCompleted(BirdType.OPIUMBIRD);
        }
        if (map == MapType.STORMGLASS_REFINERY) {
            return isClassicCompleted(BirdType.HEISENBIRD);
        }
        return true;
    }

    private boolean isMapVariantUnlocked(MapVariant variant) {
        if (developerInfiniteBirdCoins) return true;
        if (variant == null || variant == MapVariant.STANDARD) return true;
        if (variant == MapVariant.ROOFTOP_RELAY) return rooftopRelayUnlocked;
        if (variant == MapVariant.TEMPEST_SUMMIT) return tempestSummitUnlocked;
        if (variant == MapVariant.PEREGRINE_RUN) return peregrineRunUnlocked;
        if (variant == MapVariant.FROZEN_CALDERA) return frozenCalderaUnlocked;
        if (variant == MapVariant.HEARTBLOOM_SANCTUARY) return heartbloomSanctuaryUnlocked;
        if (variant == MapVariant.HARVEST_TRIBUNAL) return harvestTribunalUnlocked;
        if (variant == MapVariant.DAWNWATCH_BASTION) return dawnwatchBastionUnlocked;
        if (variant == MapVariant.REDLINE_CANYON) return redlineCanyonUnlocked;
        if (variant == MapVariant.LAST_ICE_SHELF) return lastIceShelfUnlocked;
        if (variant == MapVariant.STILLWATER_MARSH) return stillwaterMarshUnlocked;
        if (variant == MapVariant.OBSIDIAN_FOUNDRY) return isClassicCompleted(BirdType.RAZORBILL);
        if (variant == MapVariant.GIFT_VAULT || variant == MapVariant.BELLKEEPER_VAULT) {
            return isClassicCompleted(BirdType.GRINCHHAWK);
        }
        if (variant == MapVariant.SORTING_FLOOR || variant == MapVariant.RECLAMATION_CORE) {
            return isClassicCompleted(BirdType.VULTURE);
        }
        if (variant == MapVariant.WAKING_CHAMBER) {
            return isClassicCompleted(BirdType.OPIUMBIRD);
        }
        if (variant == MapVariant.EYE_OF_THE_SUPERCELL) {
            return isClassicCompleted(BirdType.HEISENBIRD);
        }
        return isMapUnlocked(variant.baseMap);
    }

    private boolean isAdventureBirdUnlocked(BirdType type) {
        if (type == null) return true;
        return !adventureUnlocked[type.ordinal()];
    }

    private List<BirdType> adventureAllowedBirds(AdventureBattle battle) {
        List<BirdType> pool = new ArrayList<>();
        if (battle == null) return pool;
        if (battle.requiredPlayerType != null) {
            pool.add(battle.requiredPlayerType);
            return pool;
        }
        for (BirdType bt : BirdType.values()) {
            if (isAdventureBirdUnlocked(bt)) continue;
            if (battle.allowedBirds != null && !battle.allowedBirds.contains(bt)) continue;
            pool.add(bt);
        }
        if (pool.isEmpty()) pool.add(firstAdventureBirdForRoute(selectedAdventureRoute));
        return pool;
    }

    private List<String> adventureSkinOptions(BirdType type) {
        List<String> options = new ArrayList<>();
        options.add(null);
        if (type == null) return options;
        if (type == BirdType.PIGEON) {
            options.add(PREMIUM_PIGEON_SKIN);
            if (cityPigeonUnlocked) options.add("CITY_PIGEON");
            if (noirPigeonUnlocked) options.add("NOIR_PIGEON");
            if (freemanPigeonUnlocked) options.add(FREEMAN_PIGEON_SKIN);
            if (beaconPigeonUnlocked) options.add(BEACON_PIGEON_SKIN);
            if (stormPigeonUnlocked) options.add(STORM_PIGEON_SKIN);
        } else if (type == BirdType.EAGLE) {
            options.add(STOCK_PHOTO_EAGLE_SKIN);
            if (eagleSkinUnlocked) options.add("SKY_KING_EAGLE");
        } else if (type == BirdType.PHOENIX) {
            if (isClassicRewardUnlocked(type)) options.add(classicSkinDataKey(type));
            if (novaPhoenixUnlocked) options.add(NOVA_PHOENIX_SKIN);
            if (ashenSovereignPhoenixUnlocked) options.add(ASHEN_SOVEREIGN_PHOENIX_SKIN);
        } else {
            if (isClassicRewardUnlocked(type)) options.add(classicSkinDataKey(type));
        }
        switch (type) {
            case FALCON -> {
                if (duneFalconUnlocked) options.add(DUNE_FALCON_SKIN);
            }
            case TURKEY -> options.add(STOCK_PHOTO_TURKEY_SKIN);
            case ROADRUNNER -> {
                if (mirageRoadrunnerUnlocked) options.add(MIRAGE_ROADRUNNER_SKIN);
            }
            case PENGUIN -> {
                if (mintPenguinUnlocked) options.add(MINT_PENGUIN_SKIN);
            }
            case TITMOUSE -> {
                options.add(OLD_SPARROW_SKIN);
                if (circuitTitmouseUnlocked) options.add(CIRCUIT_TITMOUSE_SKIN);
            }
            case RAZORBILL -> {
                if (prismRazorbillUnlocked) options.add(PRISM_RAZORBILL_SKIN);
            }
            case PELICAN -> {
                if (auroraPelicanUnlocked) options.add(AURORA_PELICAN_SKIN);
                if (ironcladPelicanUnlocked) options.add(IRONCLAD_PELICAN_SKIN);
            }
            case HUMMINGBIRD -> {
                if (sunflareHummingbirdUnlocked) options.add(SUNFLARE_HUMMINGBIRD_SKIN);
                if (loreAccurateHummingbirdUnlocked) options.add(LORE_ACCURATE_HUMMINGBIRD_SKIN);
            }
            case SHOEBILL -> {
                if (glacierShoebillUnlocked) options.add(GLACIER_SHOEBILL_SKIN);
            }
            case VULTURE -> {
                if (tideVultureUnlocked) options.add(TIDE_VULTURE_SKIN);
            }
            case MOCKINGBIRD -> {
                if (eclipseMockingbirdUnlocked) options.add(ECLIPSE_MOCKINGBIRD_SKIN);
            }
            case BAT -> {
                if (umbraBatUnlocked) options.add(UMBRA_BAT_SKIN);
                if (resonanceBatUnlocked) options.add(RESONANCE_BAT_SKIN);
            }
            case ROOSTER -> {
                if (sunforgeRoosterUnlocked) options.add(SUNFORGE_ROOSTER_SKIN);
            }
            case RAVEN -> {
                if (voidHeraldRavenUnlocked) options.add(VOID_HERALD_RAVEN_SKIN);
            }
            default -> {
            }
        }
        return options;
    }

    private String normalizeAdventureSkinChoice(BirdType type, String skinKey) {
        if (type == null || skinKey == null) return null;
        if (PREMIUM_PIGEON_SKIN.equals(skinKey) && type == BirdType.PIGEON) return skinKey;
        if (OLD_SPARROW_SKIN.equals(skinKey) && type == BirdType.TITMOUSE) return skinKey;
        if ("CITY_PIGEON".equals(skinKey) && type == BirdType.PIGEON && cityPigeonUnlocked) return skinKey;
        if ("NOIR_PIGEON".equals(skinKey) && type == BirdType.PIGEON && noirPigeonUnlocked) return skinKey;
        if (FREEMAN_PIGEON_SKIN.equals(skinKey) && type == BirdType.PIGEON && freemanPigeonUnlocked) return skinKey;
        if (BEACON_PIGEON_SKIN.equals(skinKey) && type == BirdType.PIGEON && beaconPigeonUnlocked) return skinKey;
        if (STORM_PIGEON_SKIN.equals(skinKey) && type == BirdType.PIGEON && stormPigeonUnlocked) return skinKey;
        if (STOCK_PHOTO_EAGLE_SKIN.equals(skinKey) && type == BirdType.EAGLE) return skinKey;
        if (STOCK_PHOTO_TURKEY_SKIN.equals(skinKey) && type == BirdType.TURKEY) return skinKey;
        if ("SKY_KING_EAGLE".equals(skinKey) && type == BirdType.EAGLE && eagleSkinUnlocked) return skinKey;
        if (NOVA_PHOENIX_SKIN.equals(skinKey) && type == BirdType.PHOENIX && novaPhoenixUnlocked) return skinKey;
        if (ASHEN_SOVEREIGN_PHOENIX_SKIN.equals(skinKey) && type == BirdType.PHOENIX && ashenSovereignPhoenixUnlocked) return skinKey;
        if (DUNE_FALCON_SKIN.equals(skinKey) && type == BirdType.FALCON && duneFalconUnlocked) return skinKey;
        if (MINT_PENGUIN_SKIN.equals(skinKey) && type == BirdType.PENGUIN && mintPenguinUnlocked) return skinKey;
        if (CIRCUIT_TITMOUSE_SKIN.equals(skinKey) && type == BirdType.TITMOUSE && circuitTitmouseUnlocked) return skinKey;
        if (PRISM_RAZORBILL_SKIN.equals(skinKey) && type == BirdType.RAZORBILL && prismRazorbillUnlocked) return skinKey;
        if (AURORA_PELICAN_SKIN.equals(skinKey) && type == BirdType.PELICAN && auroraPelicanUnlocked) return skinKey;
        if (IRONCLAD_PELICAN_SKIN.equals(skinKey) && type == BirdType.PELICAN && ironcladPelicanUnlocked) return skinKey;
        if (SUNFLARE_HUMMINGBIRD_SKIN.equals(skinKey) && type == BirdType.HUMMINGBIRD && sunflareHummingbirdUnlocked) return skinKey;
        if (LORE_ACCURATE_HUMMINGBIRD_SKIN.equals(skinKey) && type == BirdType.HUMMINGBIRD && loreAccurateHummingbirdUnlocked) return skinKey;
        if (GLACIER_SHOEBILL_SKIN.equals(skinKey) && type == BirdType.SHOEBILL && glacierShoebillUnlocked) return skinKey;
        if (NULL_ROCK_VULTURE_SKIN.equals(skinKey) && type == BirdType.VULTURE && nullRockVultureUnlocked) return skinKey;
        if (TIDE_VULTURE_SKIN.equals(skinKey) && type == BirdType.VULTURE && tideVultureUnlocked) return skinKey;
        if (ECLIPSE_MOCKINGBIRD_SKIN.equals(skinKey) && type == BirdType.MOCKINGBIRD && eclipseMockingbirdUnlocked) return skinKey;
        if (UMBRA_BAT_SKIN.equals(skinKey) && type == BirdType.BAT && umbraBatUnlocked) return skinKey;
        if (RESONANCE_BAT_SKIN.equals(skinKey) && type == BirdType.BAT && resonanceBatUnlocked) return skinKey;
        if (SUNFORGE_ROOSTER_SKIN.equals(skinKey) && type == BirdType.ROOSTER && sunforgeRoosterUnlocked) return skinKey;
        if (MIRAGE_ROADRUNNER_SKIN.equals(skinKey) && type == BirdType.ROADRUNNER && mirageRoadrunnerUnlocked) return skinKey;
        if (VOID_HERALD_RAVEN_SKIN.equals(skinKey) && type == BirdType.RAVEN && voidHeraldRavenUnlocked) return skinKey;
        if (skinKey.startsWith("CLASSIC_SKIN_") && type != BirdType.PIGEON && type != BirdType.EAGLE) {
            String expected = classicSkinDataKey(type);
            if (skinKey.equals(expected) && isClassicRewardUnlocked(type)) return skinKey;
        }
        return null;
    }

