    private void drawCarrionExchangeSky(GraphicsContext g, boolean core, boolean sorting, double pulse) {
        Color top = Color.web(core ? "#09050C" : sorting ? "#071315" : "#100C18");
        Color horizon = Color.web(core ? "#6A1D12" : sorting ? "#244A43" : "#69341F");
        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0, top), new Stop(0.62, top.interpolate(horizon, 0.46)),
                new Stop(1, horizon)));
        g.fillRect(0.0, 0.0, WORLD_WIDTH, WORLD_HEIGHT);

        // A half-eclipsed industrial sun is the map's distant focal point.
        double halo = 0.10 + pulse * 0.04;
        g.setFill(Color.web(core ? "#FF5A24" : sorting ? "#70E8D3" : "#FFB454", halo));
        g.fillOval(2_205.0, 35.0, 1_590.0, 1_590.0);
        g.setFill(Color.web(core ? "#FF6A2D" : sorting ? "#A9FFF0" : "#FFD17A", 0.62));
        g.fillOval(2_405.0, 235.0, 1_190.0, 1_190.0);
        g.setFill(Color.web("#09070D", 0.98));
        g.fillOval(2_535.0, 150.0, 1_190.0, 1_190.0);
        g.setStroke(Color.web(core ? "#FF6D32" : sorting ? "#76E8D6" : "#E6A74F", 0.42));
        g.setLineWidth(18.0);
        g.strokeOval(2_405.0, 235.0, 1_190.0, 1_190.0);

        for (int cloud = 0; cloud < 11; cloud++) {
            double x = -360.0 + cloud * 650.0;
            double y = 450.0 + Math.floorMod(cloud * 239, 580);
            double width = 620.0 + (cloud % 3) * 180.0;
            g.setFill(Color.web(core ? "#5B1C18" : "#7A5341", 0.12 + (cloud % 2) * 0.03));
            g.fillOval(x, y, width, 125.0 + (cloud % 2) * 45.0);
        }
    }

    private void drawCarrionDeadCity(GraphicsContext g, boolean core, boolean sorting, double pulse) {
        // Far towers receive enough rim light to read as a city, not a black wall.
        for (int building = 0; building < 19; building++) {
            double x = -180.0 + building * 345.0;
            double width = 235.0 + (building % 4) * 44.0;
            double height = 470.0 + Math.floorMod(building * 271, 830);
            double top = GROUND_Y + 310.0 - height;
            Color shell = Color.web(building % 3 == 0 ? "#17151D" : "#11131A", 0.98);
            g.setFill(shell);
            g.fillRect(x, top, width, height + 540.0);
            g.setFill(Color.web(core ? "#FF7043" : sorting ? "#72D9C6" : "#D89B58",
                    0.14 + pulse * 0.025));
            for (double windowY = top + 70.0; windowY < GROUND_Y + 180.0; windowY += 128.0) {
                g.fillRect(x + 38.0, windowY, 30.0, 16.0);
                if (building % 2 == 0) g.fillRect(x + width - 69.0, windowY, 30.0, 16.0);
            }
            g.setStroke(Color.web("#A87950", 0.16));
            g.setLineWidth(7.0);
            g.strokeLine(x + width - 2.0, top, x + width - 2.0, GROUND_Y + 250.0);
        }

        // Closer roofline and aerial bridges break up the old flat silhouette.
        g.setFill(Color.web("#0A0B10", 0.95));
        for (int block = 0; block < 8; block++) {
            double x = block * 850.0 - 260.0;
            double top = GROUND_Y - 520.0 + (block % 3) * 105.0;
            g.fillRect(x, top, 640.0, 760.0);
            g.setStroke(Color.web(core ? "#7A3126" : "#69564A", 0.34));
            g.setLineWidth(12.0);
            g.strokeLine(x + 80.0, top + 60.0, x + 560.0, top + 60.0);
        }
        g.setStroke(Color.web("#9C7657", 0.22));
        g.setLineWidth(18.0);
        g.strokeLine(0.0, GROUND_Y - 380.0, WORLD_WIDTH, GROUND_Y - 380.0);
        g.setLineWidth(6.0);
        for (double x = 90.0; x < WORLD_WIDTH; x += 310.0) {
            g.strokeLine(x, GROUND_Y - 380.0, x + 160.0, GROUND_Y - 505.0);
            g.strokeLine(x + 160.0, GROUND_Y - 505.0, x + 310.0, GROUND_Y - 380.0);
        }
    }

    private void drawCarrionOverheadWorks(GraphicsContext g, Color accent,
                                           boolean core, boolean sorting) {
        Color tower = Color.web("#16161D");
        Color frame = Color.web(core ? "#704638" : sorting ? "#4E746D" : "#806747");
        for (double towerX : new double[]{390.0, 5_390.0}) {
            g.setFill(tower);
            g.fillRoundRect(towerX, 115.0, 230.0, GROUND_Y + 410.0, 24.0, 24.0);
            g.setStroke(frame);
            g.setLineWidth(20.0);
            g.strokeRoundRect(towerX, 115.0, 230.0, GROUND_Y + 410.0, 24.0, 24.0);
            for (double y = 230.0; y < GROUND_Y + 170.0; y += 280.0) {
                g.strokeLine(towerX + 25.0, y, towerX + 205.0, y + 210.0);
                g.strokeLine(towerX + 205.0, y, towerX + 25.0, y + 210.0);
            }
        }

        g.setFill(Color.web("#202028"));
        g.fillRoundRect(330.0, 145.0, 5_340.0, 170.0, 30.0, 30.0);
        g.setStroke(Color.web("#08090D"));
        g.setLineWidth(32.0);
        g.strokeRoundRect(330.0, 145.0, 5_340.0, 170.0, 30.0, 30.0);
        g.setStroke(frame);
        g.setLineWidth(12.0);
        g.strokeRoundRect(330.0, 145.0, 5_340.0, 170.0, 30.0, 30.0);
        for (double x = 430.0; x < 5_520.0; x += 255.0) {
            g.strokeLine(x, 174.0, x + 120.0, 286.0);
            g.strokeLine(x + 120.0, 174.0, x, 286.0);
        }
        g.setFill(accent.deriveColor(0, 0.82, 1.0, 0.72));
        g.fillRect(390.0, 158.0, 5_220.0, 13.0);

        // The marquee makes the location identifiable in gameplay and photos.
        double signWidth = sorting ? 1_540.0 : core ? 1_480.0 : 1_780.0;
        double signX = 3_000.0 - signWidth * 0.5;
        g.setStroke(Color.web("#655746", 0.92));
        g.setLineWidth(14.0);
        g.strokeLine(signX + 140.0, 315.0, signX + 140.0, 455.0);
        g.strokeLine(signX + signWidth - 140.0, 315.0, signX + signWidth - 140.0, 455.0);
        g.setFill(Color.web("#0B0C12", 0.97));
        g.fillRoundRect(signX, 440.0, signWidth, 235.0, 42.0, 42.0);
        g.setStroke(accent.deriveColor(0, 0.90, 1.05, 0.95));
        g.setLineWidth(15.0);
        g.strokeRoundRect(signX, 440.0, signWidth, 235.0, 42.0, 42.0);
        g.setTextAlign(TextAlignment.CENTER);
        g.setFill(Color.web("#FFF0C8"));
        g.setFont(Font.font("Impact", FontWeight.BOLD, 86.0));
        g.fillText(core ? "RECLAMATION CORE" : sorting ? "SORTING FLOOR" : "CARRION EXCHANGE",
                3_000.0, 565.0);
        g.setFill(accent.deriveColor(0, 0.84, 1.08, 0.90));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 29.0));
        g.fillText(core ? "ALL DEBTS RETURN TO THE FURNACE"
                        : sorting ? "WEIGH  •  MARK  •  RECLAIM"
                        : "WE BUY WHAT THE SKY FORGETS",
                3_000.0, 625.0);
        g.setTextAlign(TextAlignment.LEFT);
    }

    private void drawCarrionMarketBackground(GraphicsContext g, Color accent, double pulse) {
        // Five lit trade bays turn the lower skyline into a functioning market.
        for (int stall = 0; stall < 5; stall++) {
            double x = 790.0 + stall * 1_105.0;
            double y = GROUND_Y - 760.0 + (stall % 2) * 60.0;
            g.setFill(Color.web("#17151B", 0.96));
            g.fillRoundRect(x, y, 730.0, 430.0, 42.0, 42.0);
            g.setStroke(Color.web("#8C6847", 0.84));
            g.setLineWidth(14.0);
            g.strokeRoundRect(x, y, 730.0, 430.0, 42.0, 42.0);
            for (int awning = 0; awning < 7; awning++) {
                g.setFill(awning % 2 == 0 ? accent.deriveColor(0, 0.78, 0.78, 0.76)
                        : Color.web("#4D2C2D", 0.90));
                g.fillPolygon(new double[]{x + awning * 104.0, x + (awning + 1) * 104.0,
                                x + awning * 104.0 + 82.0, x + awning * 104.0 + 20.0},
                        new double[]{y, y, y + 92.0, y + 92.0}, 4);
            }
            g.setFill(Color.web("#E9AD5D", 0.18 + pulse * 0.04));
            g.fillRoundRect(x + 70.0, y + 145.0, 590.0, 205.0, 26.0, 26.0);
            g.setStroke(Color.web("#FFD58C", 0.44));
            g.setLineWidth(8.0);
            for (int shelf = 0; shelf < 3; shelf++) {
                double shelfY = y + 205.0 + shelf * 66.0;
                g.strokeLine(x + 95.0, shelfY, x + 635.0, shelfY);
            }
            for (int crate = 0; crate < 6; crate++) {
                double crateX = x + 105.0 + crate * 86.0;
                double crateY = y + 250.0 + (crate % 2) * 55.0;
                g.setFill(Color.web(crate % 3 == 0 ? "#925B39" : "#54444A"));
                g.fillRect(crateX, crateY, 64.0, 58.0);
                g.setStroke(Color.web("#D7AE6D", 0.48));
                g.setLineWidth(5.0);
                g.strokeRect(crateX, crateY, 64.0, 58.0);
            }
        }

        // Recessed airship carcasses provide large, readable salvage shapes.
        for (double centerX : new double[]{1_260.0, 4_740.0}) {
            g.setStroke(Color.web("#8B735B", 0.76));
            g.setLineWidth(16.0);
            g.strokeLine(centerX - 250.0, 315.0, centerX - 120.0, 850.0);
            g.strokeLine(centerX + 250.0, 315.0, centerX + 120.0, 850.0);
            g.setFill(Color.web("#242129", 0.98));
            g.fillOval(centerX - 500.0, 755.0, 1_000.0, 330.0);
            g.setStroke(Color.web("#B37A48", 0.66));
            g.setLineWidth(15.0);
            g.strokeOval(centerX - 500.0, 755.0, 1_000.0, 330.0);
            g.strokeLine(centerX - 360.0, 920.0, centerX + 360.0, 920.0);
            for (double rib = centerX - 260.0; rib <= centerX + 260.0; rib += 130.0) {
                g.strokeLine(rib, 790.0, rib, 1_050.0);
            }
        }
    }

    private void drawCarrionSortingLine(GraphicsContext g, Color accent, double pulse) {
        for (int chute = 0; chute < 4; chute++) {
            double x = 750.0 + chute * 1_390.0;
            g.setStroke(Color.web("#334C49", 0.96));
            g.setLineWidth(44.0);
            g.strokeLine(x + 80.0, 315.0, x + 245.0, 830.0);
            g.strokeLine(x + 245.0, 830.0, x + 500.0, 990.0);
            g.setStroke(accent.deriveColor(0, 0.82, 0.92, 0.76));
            g.setLineWidth(10.0);
            g.strokeLine(x + 80.0, 315.0, x + 245.0, 830.0);
            g.strokeLine(x + 245.0, 830.0, x + 500.0, 990.0);

            g.setFill(Color.web("#11201F", 0.98));
            g.fillRoundRect(x + 80.0, 940.0, 640.0, 390.0, 42.0, 42.0);
            g.setStroke(accent.deriveColor(0, 0.90, 1.0, 0.88));
            g.setLineWidth(14.0);
            g.strokeRoundRect(x + 80.0, 940.0, 640.0, 390.0, 42.0, 42.0);
            g.setFill(accent.deriveColor(0, 0.65, 0.80, 0.15 + pulse * 0.04));
            g.fillRoundRect(x + 115.0, 985.0, 570.0, 300.0, 24.0, 24.0);
            g.setFill(Color.web("#DFFFF8"));
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 78.0));
            g.setTextAlign(TextAlignment.CENTER);
            g.fillText(String.format(Locale.ROOT, "%02d", chute + 1), x + 400.0, 1_135.0);
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 25.0));
            g.fillText(switch (chute) {
                case 0 -> "BONE";
                case 1 -> "BRASS";
                case 2 -> "SIGNAL";
                default -> "UNCLAIMED";
            }, x + 400.0, 1_215.0);
        }
        g.setTextAlign(TextAlignment.LEFT);

        g.setFill(Color.web("#11201F"));
        g.fillRoundRect(720.0, GROUND_Y - 690.0, 4_560.0, 135.0, 28.0, 28.0);
        g.setStroke(accent.deriveColor(0, 0.88, 0.90, 0.78));
        g.setLineWidth(12.0);
        g.strokeRoundRect(720.0, GROUND_Y - 690.0, 4_560.0, 135.0, 28.0, 28.0);
        for (double roller = 820.0; roller < 5_200.0; roller += 145.0) {
            g.setFill(Color.web("#87A9A3", 0.68));
            g.fillOval(roller, GROUND_Y - 645.0, 48.0, 48.0);
            g.setFill(Color.web("#0B1112"));
            g.fillOval(roller + 15.0, GROUND_Y - 630.0, 18.0, 18.0);
        }
    }

    private void drawCarrionReclamationCore(GraphicsContext g, double time,
                                             boolean ambientFx, double pulse) {
        double rotation = ambientFx ? time * 7.0 : 0.0;
        double cx = 3_000.0;
        double cy = 1_360.0;
        g.setFill(Color.web("#030306", 0.92));
        g.fillOval(cx - 1_080.0, cy - 1_080.0, 2_160.0, 2_160.0);
        g.setFill(Color.web("#FF5A1F", 0.09 + pulse * 0.05));
        g.fillOval(cx - 950.0, cy - 950.0, 1_900.0, 1_900.0);

        g.save();
        g.translate(cx, cy);
        g.rotate(rotation);
        for (int ring = 0; ring < 3; ring++) {
            double radius = 590.0 + ring * 175.0;
            g.setStroke(Color.web(ring == 0 ? "#FFB04A" : "#A94B2D", 0.58 - ring * 0.09 + pulse * 0.09));
            g.setLineWidth(42.0 - ring * 7.0);
            g.setLineDashes(110.0 + ring * 25.0, 48.0 + ring * 20.0);
            g.strokeOval(-radius, -radius, radius * 2.0, radius * 2.0);
        }
        g.setLineDashes();
        g.setStroke(Color.web("#A85A39", 0.76));
        g.setLineWidth(22.0);
        for (int spoke = 0; spoke < 12; spoke++) {
            double angle = spoke * Math.PI / 6.0;
            g.strokeLine(Math.cos(angle) * 330.0, Math.sin(angle) * 330.0,
                    Math.cos(angle) * 840.0, Math.sin(angle) * 840.0);
        }
        g.restore();

        g.setFill(Color.web("#171015"));
        g.fillOval(cx - 410.0, cy - 410.0, 820.0, 820.0);
        g.setStroke(Color.web("#FF9B42", 0.86));
        g.setLineWidth(32.0);
        g.strokeOval(cx - 410.0, cy - 410.0, 820.0, 820.0);
        g.setFill(Color.web("#FF4D18", 0.52 + pulse * 0.16));
        g.fillOval(cx - 270.0, cy - 270.0, 540.0, 540.0);
        g.setFill(Color.web("#FFD180", 0.34 + pulse * 0.18));
        g.fillOval(cx - 145.0, cy - 145.0, 290.0, 290.0);

        // Intake pipes visibly connect the engine to the exchange structure.
        g.setStroke(Color.web("#6F3D32", 0.94));
        g.setLineWidth(70.0);
        strokeBezier(g, 610.0, 1_020.0, 1_250.0, 1_020.0, 1_620.0, 1_300.0, 2_170.0, 1_360.0);
        strokeBezier(g, 5_390.0, 1_020.0, 4_750.0, 1_020.0, 4_380.0, 1_300.0, 3_830.0, 1_360.0);
        g.setStroke(Color.web("#D66D3F", 0.64));
        g.setLineWidth(13.0);
        strokeBezier(g, 610.0, 1_020.0, 1_250.0, 1_020.0, 1_620.0, 1_300.0, 2_170.0, 1_360.0);
        strokeBezier(g, 5_390.0, 1_020.0, 4_750.0, 1_020.0, 4_380.0, 1_300.0, 3_830.0, 1_360.0);
    }

    private void drawCarrionExchangePlatforms(GraphicsContext g, Color accent,
                                               boolean core, boolean sorting) {
        Color deck = Color.web(core ? "#3B2220" : sorting ? "#193330" : "#30282A");
        Color frame = Color.web(core ? "#864735" : sorting ? "#4D8178" : "#876847");
        double supportFloor = GROUND_Y + 300.0;
        for (Platform p : platforms) {
            if (p.y >= GROUND_Y + 80.0) continue;
            boolean mainDeck = Math.abs(p.y - battlefieldIslandY) < 2.0 && p.w > 3_000.0;
            double center = p.x + p.w * 0.5;

            if (mainDeck) {
                g.setFill(Color.web("#111117", 0.98));
                g.fillPolygon(new double[]{p.x + 18.0, p.x + p.w - 18.0,
                                p.x + p.w - 170.0, p.x + 170.0},
                        new double[]{p.y + p.h, p.y + p.h, p.y + p.h + 250.0,
                                p.y + p.h + 250.0}, 4);
                g.setStroke(frame.deriveColor(0, 0.86, 0.88, 0.92));
                g.setLineWidth(18.0);
                for (double brace = p.x + 80.0; brace < p.x + p.w - 100.0; brace += 330.0) {
                    g.strokeLine(brace, p.y + p.h + 20.0, brace + 245.0, p.y + p.h + 230.0);
                    g.strokeLine(brace + 245.0, p.y + p.h + 20.0, brace, p.y + p.h + 230.0);
                }
            } else if (p.y < battlefieldIslandY - 65.0) {
                double braceBottom = Math.min(battlefieldIslandY - 28.0, p.y + p.h + 280.0);
                g.setStroke(Color.web("#0A0A0F", 0.96));
                g.setLineWidth(30.0);
                g.strokeLine(p.x + 35.0, p.y + p.h, center, braceBottom);
                g.strokeLine(p.x + p.w - 35.0, p.y + p.h, center, braceBottom);
                g.setStroke(frame.deriveColor(0, 0.82, 0.82, 0.88));
                g.setLineWidth(12.0);
                g.strokeLine(p.x + 35.0, p.y + p.h, center, braceBottom);
                g.strokeLine(p.x + p.w - 35.0, p.y + p.h, center, braceBottom);
                if (p.y < battlefieldIslandY - 250.0) {
                    g.setStroke(Color.web("#88745C", 0.88));
                    g.setLineWidth(14.0);
                    g.strokeLine(center - Math.min(180.0, p.w * 0.24), 315.0, p.x + 42.0, p.y);
                    g.strokeLine(center + Math.min(180.0, p.w * 0.24), 315.0, p.x + p.w - 42.0, p.y);
                }
            } else if (p.y > battlefieldIslandY + 70.0) {
                g.setStroke(frame.deriveColor(0, 0.78, 0.70, 0.78));
                g.setLineWidth(14.0);
                g.strokeLine(p.x + 40.0, p.y + p.h, center, Math.min(supportFloor, p.y + 350.0));
                g.strokeLine(p.x + p.w - 40.0, p.y + p.h, center, Math.min(supportFloor, p.y + 350.0));
            }

            g.setFill(Color.web("#07080C", 0.95));
            g.fillRoundRect(p.x - 14.0, p.y + 9.0, p.w + 28.0, p.h + 26.0, 24.0, 24.0);
            g.setFill(deck);
            g.fillRoundRect(p.x, p.y, p.w, p.h, 20.0, 20.0);
            g.setFill(accent.deriveColor(0, 0.72, 0.70, 0.38));
            g.fillRoundRect(p.x + 17.0, p.y + 8.0, Math.max(0.0, p.w - 34.0),
                    Math.min(19.0, p.h * 0.30), 8.0, 8.0);
            g.setStroke(accent.deriveColor(0, 0.88, 1.0, 0.98));
            g.setLineWidth(mainDeck ? 13.0 : 11.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 20.0, 20.0);

            for (double seam = p.x + 110.0; seam < p.x + p.w - 50.0; seam += 235.0) {
                g.setStroke(Color.web("#0B0C10", 0.70));
                g.setLineWidth(5.0);
                g.strokeLine(seam, p.y + 7.0, seam, p.y + p.h - 7.0);
            }
            for (double rivet = p.x + 45.0; rivet < p.x + p.w - 25.0; rivet += 145.0) {
                g.setFill(Color.web("#FFF0C8", 0.72));
                g.fillOval(rivet - 7.0, p.y + p.h - 21.0, 14.0, 14.0);
            }
        }
    }

    private void drawCarrionMagnet(GraphicsContext g, double x, int index,
                                   boolean warning, boolean active, double pulse,
                                   boolean sorting) {
        Color state = active ? Color.web("#6BE7FF")
                : warning ? Color.web("#FFD166")
                : sorting ? Color.web("#4D9F94") : Color.web("#8A6F4D");
        double headY = battlefieldIslandY - 250.0;

        g.setStroke(Color.web("#17151A"));
        g.setLineWidth(34.0);
        g.strokeLine(x, 315.0, x, headY - 35.0);
        g.setStroke(Color.web("#796A58"));
        g.setLineWidth(9.0);
        g.strokeLine(x, 315.0, x, headY - 35.0);
        for (double linkY = 345.0; linkY < headY - 45.0; linkY += 92.0) {
            g.setStroke(Color.web("#A58B69", 0.66));
            g.setLineWidth(7.0);
            g.strokeOval(x - 19.0, linkY, 38.0, 58.0);
        }

        g.setFill(Color.web("#14151B"));
        g.fillRoundRect(x - 150.0, headY - 30.0, 300.0, 145.0, 34.0, 34.0);
        g.setStroke(Color.web("#05060A"));
        g.setLineWidth(24.0);
        g.strokeRoundRect(x - 150.0, headY - 30.0, 300.0, 145.0, 34.0, 34.0);
        g.setStroke(state.deriveColor(0, 0.92, 1.02, 0.96));
        g.setLineWidth(13.0);
        g.strokeRoundRect(x - 150.0, headY - 30.0, 300.0, 145.0, 34.0, 34.0);

        // Split horseshoe coils communicate a magnetic hazard immediately.
        g.setFill(state.deriveColor(0, 0.82, 0.84, 0.86));
        g.fillRoundRect(x - 112.0, headY + 10.0, 78.0, 150.0, 28.0, 28.0);
        g.fillRoundRect(x + 34.0, headY + 10.0, 78.0, 150.0, 28.0, 28.0);
        g.setFill(Color.web("#090A0E"));
        g.fillRect(x - 33.0, headY + 78.0, 66.0, 96.0);
        g.setStroke(Color.web("#E8F8F6", active ? 0.92 : 0.42));
        g.setLineWidth(8.0);
        for (int coil = 0; coil < 4; coil++) {
            double coilY = headY + 25.0 + coil * 29.0;
            g.strokeLine(x - 102.0, coilY, x - 43.0, coilY);
            g.strokeLine(x + 43.0, coilY, x + 102.0, coilY);
        }

        g.setFill(state.deriveColor(0, 1.0, 1.0, active ? 0.95 : warning ? 0.82 : 0.48));
        g.fillOval(x - 18.0, headY - 9.0, 36.0, 36.0);
        g.setFill(Color.web("#FFF7D6"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 24.0));
        g.setTextAlign(TextAlignment.CENTER);
        g.fillText("M" + (index + 1), x, headY + 66.0);

        if (warning || active) {
            double alpha = active ? 0.22 + pulse * 0.10 : 0.08 + pulse * 0.06;
            g.setFill(state.deriveColor(0, 1.0, 1.0, alpha));
            g.fillOval(x - 390.0, headY + 30.0, 780.0, 320.0);
            g.setStroke(state.deriveColor(0, 1.0, 1.0, active ? 0.72 : 0.45));
            g.setLineWidth(active ? 16.0 : 9.0);
            for (int arc = 0; arc < 3; arc++) {
                double radius = 185.0 + arc * 95.0;
                g.strokeArc(x - radius, headY + 75.0 - radius * 0.31,
                        radius * 2.0, radius * 0.62, 0.0, 180.0, ArcType.OPEN);
            }
        }
        g.setTextAlign(TextAlignment.LEFT);
    }

    private void drawMidnightWorkshopGears(GraphicsContext g, Color accent, double time, boolean ambientFx) {
        for (int gear = 0; gear < 7; gear++) {
            double cx = 470.0 + gear * 850.0;
            double cy = GROUND_Y - 950.0 + (gear % 2) * 270.0;
            double r = 205.0 + (gear % 3) * 45.0;
            double rotation = ambientFx ? time * (gear % 2 == 0 ? 0.10 : -0.08) : 0.0;
            g.setFill(Color.web("#0A0B11", 0.74));
            g.fillOval(cx - r, cy - r, r * 2.0, r * 2.0);
            g.setStroke(Color.web("#9A7544", 0.36));
            g.setLineWidth(28.0);
            g.strokeOval(cx - r, cy - r, r * 2.0, r * 2.0);
            for (int tooth = 0; tooth < 16; tooth++) {
                double a = rotation + tooth * Math.PI / 8.0;
                double inner = r - 12.0;
                double outer = r + 48.0;
                g.strokeLine(cx + Math.cos(a) * inner, cy + Math.sin(a) * inner,
                        cx + Math.cos(a) * outer, cy + Math.sin(a) * outer);
            }
            g.setStroke(accent.deriveColor(0, 0.75, 0.72, 0.25));
            g.setLineWidth(14.0);
            for (int spoke = 0; spoke < 6; spoke++) {
                double a = rotation + spoke * Math.PI / 3.0;
                g.strokeLine(cx, cy, cx + Math.cos(a) * (r - 44.0), cy + Math.sin(a) * (r - 44.0));
            }
            g.setFill(Color.web("#271E28"));
            g.fillOval(cx - 42.0, cy - 42.0, 84.0, 84.0);
            g.setFill(accent.deriveColor(0, 0.72, 0.82, 0.52));
            g.fillOval(cx - 16.0, cy - 16.0, 32.0, 32.0);
        }
    }

    private void drawMidnightWorkshopConveyor(GraphicsContext g, Platform p, Color accent,
                                               boolean giftVault, boolean bellVault) {
        Color casing = Color.web(giftVault ? "#263D3D" : bellVault ? "#342438" : "#29303D");
        g.setFill(Color.web("#07080D", 0.90));
        g.fillRoundRect(p.x - 13.0, p.y + 10.0, p.w + 26.0, p.h + 22.0, 26.0, 26.0);
        g.setFill(casing);
        g.fillRoundRect(p.x, p.y, p.w, p.h, 22.0, 22.0);
        g.setFill(Color.web("#10141C"));
        g.fillRoundRect(p.x + 15.0, p.y + 12.0, p.w - 30.0, Math.min(27.0, p.h * 0.34), 12.0, 12.0);
        g.setStroke(accent.deriveColor(0, 0.90, 1.02, 0.92));
        g.setLineWidth(8.0);
        g.strokeRoundRect(p.x, p.y, p.w, p.h, 22.0, 22.0);
        g.setFill(Color.web("#B0BEC5", 0.48));
        double rollerY = p.y + p.h * 0.68;
        for (double rollerX = p.x + 35.0; rollerX < p.x + p.w - 20.0; rollerX += 84.0) {
            g.fillOval(rollerX - 13.0, rollerY - 13.0, 26.0, 26.0);
            g.setFill(Color.web("#0A0D13"));
            g.fillOval(rollerX - 5.0, rollerY - 5.0, 10.0, 10.0);
            g.setFill(Color.web("#B0BEC5", 0.48));
        }
        g.setStroke(Color.web("#FFF3CF", 0.48));
        g.setLineWidth(4.0);
        g.strokeLine(p.x + 22.0, p.y + 14.0, p.x + p.w - 22.0, p.y + 14.0);
    }

    private void drawMidnightWorkshopPress(GraphicsContext g, double x, boolean warning,
                                            boolean active, double pulse) {
        double headY = active ? GROUND_Y - 510.0 : warning ? 680.0 : 470.0;
        Color stateColor = active ? Color.web("#FF1744")
                : warning ? Color.web("#FFD54F") : Color.web("#806784");
        g.setFill(Color.web("#0A0B11", 0.96));
        g.fillRoundRect(x - 185.0, 190.0, 370.0, 240.0, 32.0, 32.0);
        g.setStroke(stateColor.deriveColor(0, 0.92, 1.0, 0.88));
        g.setLineWidth(12.0);
        g.strokeRoundRect(x - 185.0, 190.0, 370.0, 240.0, 32.0, 32.0);
        g.setFill(Color.web("#37303D"));
        g.fillRoundRect(x - 58.0, 390.0, 116.0, Math.max(60.0, headY - 390.0), 18.0, 18.0);
        g.setFill(stateColor.deriveColor(0, 0.88, 0.90 + pulse * 0.12, 0.96));
        g.fillRoundRect(x - 150.0, headY, 300.0, 112.0, 24.0, 24.0);
        g.setFill(Color.web("#11131A"));
        for (int stripe = -2; stripe <= 2; stripe++) {
            double stripeX = x + stripe * 55.0;
            g.fillPolygon(new double[]{stripeX - 32.0, stripeX - 6.0, stripeX + 32.0, stripeX + 6.0},
                    new double[]{headY + 101.0, headY + 101.0, headY + 11.0, headY + 11.0}, 4);
        }
        if (warning || active) {
            g.setFill(stateColor.deriveColor(0, 1.0, 1.0, active ? 0.18 : 0.08 + pulse * 0.07));
            g.fillRect(x - 145.0, headY + 112.0, 290.0,
                    Math.max(0.0, GROUND_Y - 230.0 - headY - 112.0));
            g.setStroke(stateColor.deriveColor(0, 1.0, 1.0, 0.74));
            g.setLineWidth(active ? 15.0 : 7.0);
            g.strokeLine(x - 145.0, headY + 112.0, x - 145.0, GROUND_Y - 230.0);
            g.strokeLine(x + 145.0, headY + 112.0, x + 145.0, GROUND_Y - 230.0);
        }
    }

    private void drawWorldseamArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.currentTimeMillis() / 1000.0 : 0.0;
        boolean wardenGauntlet = classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.SEAM_WARDEN_GAUNTLET;
        boolean seamreaverBoss = classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS;
        Color leftRift = seamreaverBoss ? Color.web("#FF7043") : Color.web("#00E5FF");
        Color rightRift = seamreaverBoss ? Color.web("#EF5350")
                : wardenGauntlet ? Color.web("#B388FF") : Color.web("#EA80FC");
        for (int band = 0; band < 220; band++) {
            double t = band / 219.0;
            g.setFill(Color.web("#020713").interpolate(seamreaverBoss
                    ? Color.web("#43201F") : Color.web("#0E5260"), t));
            g.fillRect(0, band * WORLD_HEIGHT / 220.0, 3_000.0, WORLD_HEIGHT / 220.0 + 3.0);
            g.setFill(Color.web("#09020F").interpolate(seamreaverBoss
                    ? Color.web("#5A1518") : Color.web("#4D174F"), t));
            g.fillRect(3_000.0, band * WORLD_HEIGHT / 220.0, 3_000.0, WORLD_HEIGHT / 220.0 + 3.0);
        }
        // One half remembers the city; the other has already fractured into impossible spires.
        for (int building = 0; building < 9; building++) {
            double x = building * 370.0 - 160.0;
            double top = 850.0 + Math.floorMod(building * 181, 640);
            g.setFill(Color.web("#071B27", 0.86));
            g.fillRect(x, top, 280.0, GROUND_Y + 180.0 - top);
            g.setFill(Color.web("#69F0E7", 0.20));
            for (double y = top + 70.0; y < GROUND_Y; y += 150.0) {
                g.fillRect(x + 46.0, y, 34.0, 22.0);
                g.fillRect(x + 188.0, y, 34.0, 22.0);
            }
        }
        g.setFill(Color.web("#17081F", 0.90));
        for (int spire = 0; spire < 7; spire++) {
            double x = 3_080.0 + spire * 500.0;
            double top = 580.0 + Math.floorMod(spire * 233, 780);
            g.fillPolygon(new double[]{x - 230.0, x, x + 230.0},
                    new double[]{GROUND_Y + 220.0, top, GROUND_Y + 220.0}, 3);
        }
        double pulse = 0.5 + (ambientFx ? 0.5 * Math.sin(time * 1.35) : 0.0);
        g.setFill(Color.web("#69F0E7", 0.10 + pulse * 0.07));
        g.fillPolygon(new double[]{2_720, 3_280, 3_500, 3_130, 3_420, 2_670, 2_930, 2_500},
                new double[]{0, 0, 650, 1_020, 1_790, 2_140, 1_050, 600}, 8);
        g.setStroke((seamreaverBoss ? Color.web("#FF1744") : Color.web("#7C4DFF"))
                .deriveColor(0, 1, 1, 0.55 + pulse * 0.28));
        g.setLineWidth(28.0 + pulse * 12.0);
        g.strokePolyline(new double[]{2_960, 3_170, 2_900, 3_120, 2_820},
                new double[]{0, 520, 1_020, 1_520, GROUND_Y + 200.0}, 5);

        g.setFill(Color.web("#D1C4E9", 0.28));
        for (int fragment = 0; fragment < 18; fragment++) {
            double angle = fragment * 2.399;
            double radius = 260.0 + (fragment % 5) * 145.0;
            double x = 3_000.0 + Math.cos(angle + time * 0.05) * radius;
            double y = 1_050.0 + Math.sin(angle) * radius * 0.72;
            g.fillPolygon(new double[]{x - 24.0, x + 34.0, x + 8.0},
                    new double[]{y + 20.0, y + 8.0, y - 44.0}, 3);
        }

        drawWorldseamChasm(g, pulse, seamreaverBoss, wardenGauntlet);

        g.setStroke(Color.web("#FFFFFF", 0.16 + pulse * 0.12));
        g.setLineWidth(10.0);
        strokeBezier(g, 1_450.0, GROUND_Y - 440.0, 2_050.0, 360.0,
                3_950.0, 360.0, 4_550.0, GROUND_Y - 440.0);
        for (int side : new int[]{-1, 1}) {
            double gateX = side < 0 ? WORLDSEAM_LEFT_GATE_X : WORLDSEAM_RIGHT_GATE_X;
            Color gateColor = side < 0 ? leftRift : rightRift;
            g.setFill(gateColor.deriveColor(0, 1, 1, 0.10 + pulse * 0.10));
            g.fillOval(gateX - WORLDSEAM_GATE_RADIUS_X, WORLDSEAM_GATE_Y - WORLDSEAM_GATE_RADIUS_Y,
                    WORLDSEAM_GATE_RADIUS_X * 2.0, WORLDSEAM_GATE_RADIUS_Y * 2.0);
            g.setStroke(gateColor.deriveColor(0, 1, 1, 0.72 + pulse * 0.22));
            g.setLineWidth(15.0);
            g.strokeOval(gateX - WORLDSEAM_GATE_RADIUS_X, WORLDSEAM_GATE_Y - WORLDSEAM_GATE_RADIUS_Y,
                    WORLDSEAM_GATE_RADIUS_X * 2.0, WORLDSEAM_GATE_RADIUS_Y * 2.0);
            g.setFill(gateColor.deriveColor(0, 1, 1, 0.72));
            for (double y = WORLDSEAM_GATE_Y - 105.0; y <= WORLDSEAM_GATE_Y + 105.0; y += 70.0) {
                double arrow = side < 0 ? 1.0 : -1.0;
                g.fillPolygon(new double[]{gateX + arrow * 48.0, gateX - arrow * 25.0,
                                gateX - arrow * 25.0},
                        new double[]{y, y - 24.0, y + 24.0}, 3);
            }
            g.setFill(Color.WHITE.deriveColor(0, 1, 1, 0.78));
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 28));
            g.setTextAlign(TextAlignment.CENTER);
            g.fillText(side < 0 ? "I" : "II", gateX,
                    WORLDSEAM_GATE_Y - WORLDSEAM_GATE_RADIUS_Y - 25.0);
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 22));
            g.fillText(side < 0 ? "LINKED TO II  >>>" : "<<<  LINKED TO I",
                    gateX, WORLDSEAM_GATE_Y + WORLDSEAM_GATE_RADIUS_Y + 25.0);
        }
        g.setTextAlign(TextAlignment.LEFT);
        drawWorldseamPlatforms(g);
    }

    private void drawObsidianFoundryArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.currentTimeMillis() / 1000.0 : 0.0;
        g.setFill(Color.web("#08070B"));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);
        g.setFill(Color.web("#231015"));
        for (int bay = 0; bay < 7; bay++) {
            double x = bay * 980.0 - 350.0;
            g.fillRect(x, 180.0, 700.0, GROUND_Y + 120.0);
            g.setStroke(Color.web("#6D3430"));
            g.setLineWidth(24.0);
            g.strokeRoundRect(x + 70.0, 310.0, 560.0, GROUND_Y - 430.0, 90.0, 90.0);
            g.setFill(Color.web("#FF5722", 0.16));
            g.fillRoundRect(x + 120.0, 390.0, 460.0, 540.0, 55.0, 55.0);
        }
        double glow = 0.36 + (ambientFx ? 0.14 * Math.sin(time * 1.8) : 0.0);
        g.setFill(Color.web("#FF3D00", glow));
        g.fillRect(0, GROUND_Y + 120.0, WORLD_WIDTH, 330.0);
        g.setFill(Color.web("#FFAB40", 0.26));
        for (int channel = 0; channel < 12; channel++) {
            double x = channel * 560.0 - Math.floorMod((long) (time * 90.0), 560L);
            g.fillPolygon(new double[]{x, x + 220.0, x + 390.0, x + 130.0},
                    new double[]{GROUND_Y + 150.0, GROUND_Y + 150.0,
                            GROUND_Y + 390.0, GROUND_Y + 390.0}, 4);
        }
        drawObsidianFoundryMachinery(g, time, ambientFx);

        // Ceiling crane, chains, and functional presses replace decorative flashing lines.
        g.setFill(Color.web("#19171D"));
        g.fillRect(0, 70.0, WORLD_WIDTH, 150.0);
        g.setStroke(Color.web("#675B5B"));
        g.setLineWidth(16.0);
        for (double x = 220.0; x < WORLD_WIDTH; x += 420.0) {
            g.strokeLine(x, 210.0, x, 470.0 + (x % 3) * 70.0);
            g.strokeOval(x - 30.0, 440.0 + (x % 3) * 70.0, 60.0, 92.0);
        }
        for (int press = 0; press < OBSIDIAN_PRESS_X.length; press++) {
            drawObsidianPressLane(g, press);
            drawObsidianPress(g, press);
        }
        drawObsidianFoundryPlatforms(g);
    }

    private void drawGlasswindSkyRelief(GraphicsContext g, double time, boolean ambientFx) {
        double moonPulse = ambientFx ? 0.025 * Math.sin(time * 0.55) : 0.0;
        g.setFill(Color.web("#DDF8FF", 0.09 + moonPulse));
        g.fillOval(2_560.0, -390.0, 880.0, 880.0);
        g.setFill(Color.web("#E8FAFF", 0.76));
        g.fillOval(2_780.0, -150.0, 390.0, 390.0);
        g.setFill(Color.web("#071322", 0.97));
        g.fillOval(2_850.0, -190.0, 390.0, 390.0);

        for (int star = 0; star < 74; star++) {
            double x = Math.floorMod(star * 487, (int) WORLD_WIDTH);
            double y = 55.0 + Math.floorMod(star * 283, 690);
            double twinkle = ambientFx ? 0.12 * Math.sin(time * 1.4 + star * 0.73) : 0.0;
            double radius = 2.0 + Math.floorMod(star * 17, 5);
            g.setFill(Color.web("#D9F7FF", Math.clamp(0.28 + twinkle, 0.12, 0.48)));
            g.fillOval(x, y, radius, radius);
        }

        // A much farther bridge sells the scale without competing with the playable deck.
        g.setStroke(Color.web("#527B8C", 0.22));
        g.setLineWidth(12.0);
        g.strokeLine(0.0, 1_265.0, WORLD_WIDTH, 1_265.0);
        for (double towerX = 420.0; towerX < WORLD_WIDTH; towerX += 1_020.0) {
            g.setLineWidth(18.0);
            g.strokeLine(towerX, 810.0, towerX, 1_270.0);
            g.setLineWidth(4.0);
            strokeBezier(g, towerX - 510.0, 960.0, towerX - 280.0, 1_210.0,
                    towerX - 180.0, 1_210.0, towerX, 850.0);
            strokeBezier(g, towerX, 850.0, towerX + 180.0, 1_210.0,
                    towerX + 280.0, 1_210.0, towerX + 510.0, 960.0);
        }
    }

    private void drawWorldseamChasm(GraphicsContext g, double pulse,
                                    boolean seamreaverBoss, boolean wardenGauntlet) {
        Color core = seamreaverBoss ? Color.web("#FF1744")
                : wardenGauntlet ? Color.web("#B388FF") : Color.web("#FFF59D");
        g.setFill(Color.web("#000007", 0.90));
        g.fillPolygon(new double[]{2_790.0, 3_210.0, 3_390.0, 3_150.0, 2_850.0, 2_610.0},
                new double[]{0.0, 0.0, 920.0, GROUND_Y + 450.0, GROUND_Y + 450.0, 920.0}, 6);
        for (int ring = 0; ring < 5; ring++) {
            double size = 250.0 + ring * 155.0;
            g.setStroke(core.deriveColor(0, 1, 1, 0.38 - ring * 0.05 + pulse * 0.08));
            g.setLineWidth(Math.max(5.0, 18.0 - ring * 2.0));
            g.setLineDashes(45.0 + ring * 12.0, 26.0 + ring * 9.0);
            g.strokeOval(3_000.0 - size * 0.5, 1_145.0 - size * 0.40, size, size * 0.80);
        }
        g.setLineDashes();
        g.setFill(core.deriveColor(0, 1, 1, 0.72));
        g.fillPolygon(new double[]{2_972.0, 3_030.0, 3_055.0, 2_944.0},
                new double[]{500.0, 500.0, GROUND_Y + 360.0, GROUND_Y + 360.0}, 4);

        if (wardenGauntlet) {
            for (double x : new double[]{2_420.0, 3_000.0, 3_580.0}) {
                g.setFill(Color.web("#B388FF", 0.18 + pulse * 0.10));
                g.fillPolygon(new double[]{x - 90.0, x + 90.0, x + 34.0, x - 34.0},
                        new double[]{GROUND_Y + 90.0, GROUND_Y + 90.0, 620.0, 620.0}, 4);
                g.setStroke(Color.web("#D1C4E9", 0.45));
                g.setLineWidth(7.0);
                g.strokeLine(x, 650.0, x, GROUND_Y + 60.0);
            }
        }
    }

    private void drawGlasswindPrismWeather(GraphicsContext g, double time, boolean ambientFx) {
        for (int shard = 0; shard < 11; shard++) {
            double drift = ambientFx ? Math.sin(time * 0.45 + shard * 0.91) * 45.0 : 0.0;
            double x = 420.0 + shard * 525.0 + drift;
            double y = 430.0 + Math.floorMod(shard * 367, 1_160);
            Color color = switch (shard % 3) {
                case 0 -> Color.web("#80DEEA", 0.20);
                case 1 -> Color.web("#CE93D8", 0.18);
                default -> Color.web("#FFF59D", 0.16);
            };
            g.setFill(color);
            g.fillPolygon(new double[]{x - 34.0, x + 42.0, x + 12.0, x - 18.0},
                    new double[]{y + 62.0, y + 24.0, y - 82.0, y - 34.0}, 4);
            g.setStroke(color.deriveColor(0, 1, 1, 0.70));
            g.setLineWidth(5.0);
            g.strokeLine(x - 18.0, y + 42.0, x + 15.0, y - 51.0);
        }
    }

    private void drawGlasswindCausewayStructure(GraphicsContext g, GlasswindCausewayGeometry.Layout layout) {
        double deckBottom = battlefieldIslandY + 52.0;
        g.setFill(Color.web("#071824", 0.97));
        g.fillPolygon(new double[]{560.0, 5_440.0, 5_310.0, 690.0},
                new double[]{deckBottom, deckBottom, battlefieldIslandY + 292.0,
                        battlefieldIslandY + 292.0}, 4);

        g.setStroke(Color.web("#0A151D", 0.92));
        g.setLineWidth(18.0);
        for (StageArtGeometry.Segment member : layout.lowerTruss()) strokeGlasswindSegment(g, member);
        g.setStroke(Color.web("#4F7B8D", 0.88));
        g.setLineWidth(7.0);
        for (StageArtGeometry.Segment member : layout.lowerTruss()) strokeGlasswindSegment(g, member);

        g.setFill(Color.web("#183847"));
        g.fillRect(560.0, deckBottom + 18.0, 4_880.0, 34.0);
        g.setFill(Color.web("#9ADBE8", 0.62));
        g.fillRect(560.0, deckBottom + 18.0, 4_880.0, 9.0);
    }

    private void drawGlasswindDeckDetails(GraphicsContext g, boolean warning, boolean active, int direction) {
        g.setStroke(Color.web(active ? "#E4FBFF" : warning ? "#FFE082" : "#79AFC0", 0.68));
        g.setLineWidth(8.0);
        g.setLineDashes(72.0, 52.0);
        g.strokeLine(720.0, battlefieldIslandY + 12.0, 5_280.0, battlefieldIslandY + 12.0);
        g.setLineDashes();

        for (double x : new double[]{820.0, 1_900.0, 4_100.0, 5_180.0}) {
            g.setFill(Color.web(active ? "#E4FBFF" : warning ? "#FFD54F" : "#4DD0E1", 0.88));
            g.fillOval(x - 14.0, battlefieldIslandY - 24.0, 28.0, 28.0);
            g.setStroke(Color.web("#DDF8FF", 0.62));
            g.setLineWidth(5.0);
            g.strokeLine(x, battlefieldIslandY - 22.0, x, battlefieldIslandY - 88.0);
        }
        if (warning || active) {
            g.setFill(Color.web(active ? "#E4FBFF" : "#FFE082", 0.82));
            for (double x = 1_250.0; x <= 4_750.0; x += 700.0) {
                double tip = x + direction * 78.0;
                g.fillPolygon(new double[]{tip, x - direction * 25.0, x - direction * 25.0},
                        new double[]{battlefieldIslandY - 72.0, battlefieldIslandY - 112.0,
                                battlefieldIslandY - 32.0}, 3);
            }
        }
    }

    private void drawGlasswindTurbine(GraphicsContext g, double cx, double cy,
                                      double radius, double time) {
        g.save();
        g.translate(cx, cy);
        g.setFill(Color.web("#071923"));
        g.fillOval(-104.0, -104.0, 208.0, 208.0);
        g.setStroke(Color.web("#7FB6C6", 0.78));
        g.setLineWidth(12.0);
        g.strokeOval(-104.0, -104.0, 208.0, 208.0);
        g.rotate(time * 48.0);
        g.setFill(Color.web("#9ADBE8", 0.76));
        for (int blade = 0; blade < 6; blade++) {
            g.rotate(60.0);
            g.fillPolygon(new double[]{24.0, radius, radius * 0.72, 48.0},
                    new double[]{-16.0, -34.0, 38.0, 26.0}, 4);
        }
        g.setFill(Color.web("#E4FBFF"));
        g.fillOval(-36.0, -36.0, 72.0, 72.0);
        g.setFill(Color.web("#31586A"));
        g.fillOval(-14.0, -14.0, 28.0, 28.0);
        g.restore();
    }

    private void strokeBezier(GraphicsContext g, double x1, double y1,
                              double controlX1, double controlY1,
                              double controlX2, double controlY2,
                              double x2, double y2) {
        g.beginPath();
        g.moveTo(x1, y1);
        g.bezierCurveTo(controlX1, controlY1, controlX2, controlY2, x2, y2);
        g.stroke();
    }

    private void drawGlasswindPlatforms(GraphicsContext g) {
        for (Platform p : platforms) {
            if (p.y < battlefieldIslandY - 70.0) {
                // Closed triangular gantries cannot terminate in open air when a platform moves.
                double braceTopY = p.y + p.h;
                double braceBottomY = Math.min(battlefieldIslandY - 42.0,
                        braceTopY + Math.clamp((battlefieldIslandY - braceTopY) * 0.34, 105.0, 250.0));
                double left = p.x + 34.0;
                double right = p.x + p.w - 34.0;
                double center = p.x + p.w * 0.5;
                g.setStroke(Color.web("#07141D", 0.92));
                g.setLineWidth(19.0);
                g.strokeLine(left, braceTopY, center, braceBottomY);
                g.strokeLine(right, braceTopY, center, braceBottomY);
                g.strokeLine(left, braceTopY, right, braceTopY);
                g.setStroke(Color.web("#5A8798", 0.86));
                g.setLineWidth(7.0);
                g.strokeLine(left, braceTopY, center, braceBottomY);
                g.strokeLine(right, braceTopY, center, braceBottomY);
                g.strokeLine(left, braceTopY, right, braceTopY);
            }
            g.setFill(Color.web("#0B202C"));
            g.fillRoundRect(p.x, p.y, p.w, p.h, 16.0, 16.0);
            g.setStroke(Color.web("#A4E3ED"));
            g.setLineWidth(8.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 16.0, 16.0);
            g.setFill(Color.web("#B2EBF2", 0.34));
            for (double panel = p.x + 22.0; panel < p.x + p.w - 30.0; panel += 150.0) {
                g.fillRect(panel, p.y + 8.0, Math.min(118.0, p.x + p.w - panel - 12.0), 12.0);
            }
        }
    }

    private void drawWorldseamPlatforms(GraphicsContext g) {
        for (Platform p : platforms) {
            double center = p.x + p.w * 0.5;
            boolean left = center < 2_700.0;
            boolean right = center > 3_300.0;
            boolean mainLandmass = Math.abs(p.y - battlefieldIslandY) < 2.0 && p.w > 1_500.0;
            boolean innerRecovery = p.y > battlefieldIslandY + 80.0
                    && center > 2_500.0 && center < 3_500.0;
            Color edge = left ? Color.web("#00E5FF") : right ? Color.web("#EA80FC") : Color.web("#FFF59D");
            Color fill = left ? Color.web("#0A2632") : right ? Color.web("#29122D") : Color.web("#282437");
            if (mainLandmass) {
                double innerX = left ? p.x + p.w : p.x;
                g.setFill(fill.deriveColor(0, 0.84, 0.62, 0.98));
                if (left) {
                    g.fillPolygon(new double[]{p.x, p.x + p.w, innerX - 85.0, innerX - 270.0, p.x + 170.0},
                            new double[]{p.y, p.y, GROUND_Y + 270.0, WORLD_HEIGHT,
                                    WORLD_HEIGHT}, 5);
                } else {
                    g.fillPolygon(new double[]{p.x, p.x + p.w, p.x + p.w - 170.0,
                                    innerX + 270.0, innerX + 85.0},
                            new double[]{p.y, p.y, WORLD_HEIGHT, WORLD_HEIGHT,
                                    GROUND_Y + 270.0}, 5);
                }
                g.setStroke(edge.deriveColor(0, 1, 1, 0.28));
                g.setLineWidth(10.0);
                for (double crack = p.x + 260.0; crack < p.x + p.w - 100.0; crack += 420.0) {
                    g.strokeLine(crack, p.y + 65.0, crack + (left ? 80.0 : -80.0), p.y + 280.0);
                }
            }
            if (p.y < battlefieldIslandY - 70.0) {
                g.setFill(fill.deriveColor(0, 0.8, 0.65, 0.74));
                g.fillPolygon(new double[]{p.x + p.w * 0.18, p.x + p.w * 0.82,
                                p.x + p.w * 0.60, p.x + p.w * 0.40},
                        new double[]{p.y + p.h, p.y + p.h,
                                Math.min(GROUND_Y + 150.0, p.y + 560.0),
                                Math.min(GROUND_Y + 150.0, p.y + 560.0)}, 4);
            }
            g.setFill(fill);
            g.fillRoundRect(p.x, p.y, p.w, p.h, 18.0, 18.0);
            g.setStroke(edge);
            g.setLineWidth(8.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 18.0, 18.0);
            g.setFill(edge.deriveColor(0, 1, 1, 0.30));
            g.fillRoundRect(p.x + 16.0, p.y + 8.0, Math.max(0.0, p.w - 32.0), 11.0, 8.0, 8.0);
            if (innerRecovery) {
                g.setFill(Color.web("#FFF59D", 0.75));
                g.fillPolygon(new double[]{center - 28.0, center + 28.0, center},
                        new double[]{p.y + p.h + 14.0, p.y + p.h + 14.0, p.y + p.h + 56.0}, 3);
            }
        }
    }

    private void drawObsidianFoundryMachinery(GraphicsContext g, double time, boolean ambientFx) {
        for (int furnace = 0; furnace < 6; furnace++) {
            double x = 230.0 + furnace * 1_110.0;
            double breathe = ambientFx ? 0.06 * Math.sin(time * 1.25 + furnace) : 0.0;
            g.setFill(Color.web("#09080B", 0.96));
            g.fillRoundRect(x, 760.0, 620.0, 670.0, 85.0, 85.0);
            g.setStroke(Color.web("#5B3430", 0.94));
            g.setLineWidth(24.0);
            g.strokeRoundRect(x, 760.0, 620.0, 670.0, 85.0, 85.0);
            g.setFill(Color.web("#FF6D00", Math.clamp(0.25 + breathe, 0.16, 0.34)));
            g.fillRoundRect(x + 92.0, 940.0, 436.0, 365.0, 180.0, 180.0);
            g.setFill(Color.web("#FFCA28", 0.24));
            for (int flame = 0; flame < 4; flame++) {
                double flameX = x + 145.0 + flame * 95.0;
                g.fillPolygon(new double[]{flameX - 48.0, flameX, flameX + 48.0},
                        new double[]{1_285.0, 1_030.0 - (flame % 2) * 70.0, 1_285.0}, 3);
            }
        }

        // Layered pipes and flywheels make the press bays feel like one working plant.
        g.setStroke(Color.web("#604B4B", 0.84));
        g.setLineWidth(34.0);
        g.strokeLine(0.0, 580.0, WORLD_WIDTH, 580.0);
        g.setLineWidth(18.0);
        for (double x = 450.0; x < WORLD_WIDTH; x += 760.0) {
            g.strokeLine(x, 570.0, x, 1_010.0);
            g.setStroke(Color.web("#A65D45", 0.78));
            g.strokeOval(x - 95.0, 900.0, 190.0, 190.0);
            g.setLineWidth(12.0);
            for (int spoke = 0; spoke < 6; spoke++) {
                double angle = Math.toRadians(spoke * 60.0);
                g.strokeLine(x, 995.0, x + Math.cos(angle) * 82.0, 995.0 + Math.sin(angle) * 82.0);
            }
            g.setStroke(Color.web("#604B4B", 0.84));
            g.setLineWidth(18.0);
        }
    }

    private void drawObsidianPressLane(GraphicsContext g, int pressIndex) {
        double x = OBSIDIAN_PRESS_X[pressIndex];
        int phase = obsidianPressPhase(pressIndex);
        boolean warning = phase >= OBSIDIAN_PRESS_WARNING_FRAME && phase < OBSIDIAN_PRESS_ACTIVE_FRAME;
        boolean active = phase >= OBSIDIAN_PRESS_ACTIVE_FRAME && phase < OBSIDIAN_PRESS_END_FRAME;
        Color state = active ? Color.web("#FF3D00") : warning ? Color.web("#FFEA00") : Color.web("#546E7A");
        g.setFill(state.deriveColor(0, 1, 1, active ? 0.22 : warning ? 0.14 : 0.07));
        g.fillRect(x - 205.0, 500.0, 410.0, battlefieldIslandY - 500.0);

        g.setFill(Color.web("#171318", 0.96));
        g.fillRect(x - 215.0, battlefieldIslandY - 18.0, 430.0, 70.0);
        for (double stripe = x - 205.0; stripe < x + 205.0; stripe += 82.0) {
            g.setFill(state.deriveColor(0, 1, 1, active ? 0.92 : warning ? 0.78 : 0.42));
            g.fillPolygon(new double[]{stripe, stripe + 34.0, stripe + 76.0, stripe + 42.0},
                    new double[]{battlefieldIslandY + 48.0, battlefieldIslandY + 48.0,
                            battlefieldIslandY - 14.0, battlefieldIslandY - 14.0}, 4);
        }
        g.setFill(state);
        g.fillOval(x - 22.0, 260.0, 44.0, 44.0);
        g.setStroke(state.deriveColor(0, 1, 1, 0.45));
        g.setLineWidth(8.0);
        g.strokeOval(x - 37.0, 245.0, 74.0, 74.0);
    }

    private void drawObsidianPress(GraphicsContext g, int pressIndex) {
        double x = OBSIDIAN_PRESS_X[pressIndex];
        int phase = obsidianPressPhase(pressIndex);
        boolean warning = phase >= OBSIDIAN_PRESS_WARNING_FRAME && phase < OBSIDIAN_PRESS_ACTIVE_FRAME;
        boolean active = phase >= OBSIDIAN_PRESS_ACTIVE_FRAME && phase < OBSIDIAN_PRESS_END_FRAME;
        double headY = active ? battlefieldIslandY - 255.0 : 520.0;
        if (warning) {
            double warningAlpha = 0.24 + 0.28 * Math.sin((phase - OBSIDIAN_PRESS_WARNING_FRAME) * 0.36);
            g.setFill(Color.web("#FFEA00", Math.max(0.12, warningAlpha)));
            g.fillRect(x - 205.0, 520.0, 410.0, battlefieldIslandY - 520.0);
            g.setFill(Color.web("#FFF59D"));
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 25));
            g.setTextAlign(TextAlignment.CENTER);
            g.fillText("PRESS " + (pressIndex + 1) + " ARMED", x, 480.0);
            g.setTextAlign(TextAlignment.LEFT);
        }
        g.setFill(Color.web("#2A2529"));
        g.fillRect(x - 92.0, 190.0, 184.0, Math.max(0.0, headY - 190.0));
        g.setStroke(active ? Color.web("#FF3D00") : Color.web("#9E7770"));
        g.setLineWidth(16.0);
        g.strokeRect(x - 205.0, headY, 410.0, 220.0);
        g.setFill(active ? Color.web("#5D211D") : Color.web("#2E292E"));
        g.fillRect(x - 197.0, headY + 8.0, 394.0, 204.0);
        g.setFill(Color.web("#FFAB40", active ? 0.86 : 0.24));
        for (double tooth = x - 168.0; tooth < x + 180.0; tooth += 72.0) {
            g.fillPolygon(new double[]{tooth, tooth + 50.0, tooth + 25.0},
                    new double[]{headY + 212.0, headY + 212.0, headY + 252.0}, 3);
        }
    }

    private void drawObsidianFoundryPlatforms(GraphicsContext g) {
        for (Platform p : platforms) {
            boolean mainFloor = Math.abs(p.y - battlefieldIslandY) < 2.0 && p.w > 3_000.0;
            boolean pressCatwalk = p.y < battlefieldIslandY - 300.0
                    && p.w >= 500.0 && p.w <= 900.0;
            if (mainFloor) {
                g.setFill(Color.web("#151216", 0.98));
                g.fillRect(p.x, p.y + p.h, p.w, 255.0);
                g.setStroke(Color.web("#5F3B35", 0.82));
                g.setLineWidth(14.0);
                for (double brace = p.x + 120.0; brace < p.x + p.w - 120.0; brace += 310.0) {
                    g.strokeLine(brace, p.y + p.h + 25.0, brace + 210.0, p.y + p.h + 230.0);
                    g.strokeLine(brace + 210.0, p.y + p.h + 25.0, brace, p.y + p.h + 230.0);
                }
            }
            if (p.y < battlefieldIslandY - 70.0) {
                g.setFill(Color.web("#211B20", 0.92));
                double support = Math.min(GROUND_Y + 110.0, p.y + 520.0);
                g.fillPolygon(new double[]{p.x + 35.0, p.x + p.w - 35.0,
                                p.x + p.w * 0.66, p.x + p.w * 0.34},
                        new double[]{p.y + p.h, p.y + p.h, support, support}, 4);
            }
            if (pressCatwalk) {
                g.setStroke(Color.web("#8D6E63", 0.72));
                g.setLineWidth(8.0);
                double ladderX = p.x + p.w * 0.5;
                g.strokeLine(ladderX - 30.0, p.y + p.h, ladderX - 30.0, battlefieldIslandY);
                g.strokeLine(ladderX + 30.0, p.y + p.h, ladderX + 30.0, battlefieldIslandY);
                for (double rung = p.y + p.h + 34.0; rung < battlefieldIslandY; rung += 66.0) {
                    g.strokeLine(ladderX - 30.0, rung, ladderX + 30.0, rung);
                }
            }
            g.setFill(Color.web("#211B20"));
            g.fillRoundRect(p.x, p.y, p.w, p.h, 14.0, 14.0);
            g.setStroke(Color.web("#D46A43"));
            g.setLineWidth(8.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 14.0, 14.0);
            g.setFill(Color.web("#FFAB40", 0.34));
            g.fillRect(p.x + 18.0, p.y + 9.0, Math.max(0.0, p.w - 36.0), 11.0);
            for (double rivet = p.x + 36.0; rivet < p.x + p.w - 20.0; rivet += 130.0) {
                g.setFill(Color.web("#FFE0B2", 0.62));
                g.fillOval(rivet, p.y + p.h - 18.0, 10.0, 10.0);
            }
        }
    }

