    private void drawCityArena(GraphicsContext g, boolean ambientFx) {
        boolean parliamentTowers = activeArenaGeometryVariant == MapVariant.PARLIAMENT_ROOFTOPS;
        boolean rooftopRelay = activeArenaGeometryVariant == MapVariant.ROOFTOP_RELAY;
        double time = ambientFx ? System.currentTimeMillis() / 1000.0 : 0.0;
        if (rooftopRelay) {
            // Keep the sunrise concentrated at the distant horizon. The old
            // two-colour gradient stayed orange all the way below the arena,
            // so every open gap between skyscrapers looked like a vertical
            // yellow wall. Cool cloud-depth colours make those gaps read as
            // open air while retaining the dawn silhouette above the roofs.
            g.setFill(new LinearGradient(0, 0, 0, WORLD_HEIGHT, false,
                    CycleMethod.NO_CYCLE,
                    new Stop(0.00, Color.web("#203A66")),
                    new Stop(0.34, Color.web("#59647E")),
                    new Stop(0.56, Color.web("#B47D78")),
                    new Stop(0.72, Color.web("#747785")),
                    new Stop(1.00, Color.web("#48576B"))));
            g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);
        } else {
            Color skyTop = Color.web(parliamentTowers ? "#020516" : "#07102A");
            Color skyBottom = Color.web(parliamentTowers ? "#24335B" : "#351B50");
            for (int i = 0; i < 640; i++) {
                double ratio = i / 640.0;
                g.setFill(skyTop.interpolate(skyBottom, ratio));
                g.fillRect(0, i * (WORLD_HEIGHT / 640.0), WORLD_WIDTH, WORLD_HEIGHT / 640.0 + 3);
            }
        }

        if (!rooftopRelay) {
            drawCityStars(g, ambientFx, time, parliamentTowers);
        }
        if (parliamentTowers) {
            drawParliamentMoon(g, ambientFx, time);
            drawParliamentDistantCity(g, ambientFx, time);
            drawParliamentTowerBodies(g, ambientFx, time);
            drawParliamentCloudDeck(g, ambientFx, time);
        } else if (rooftopRelay) {
            drawRooftopRelayDawn(g, ambientFx, time);
            drawCityPlayableBuildingBodies(g, ambientFx, time);
            drawRooftopRelayCloudDeck(g, ambientFx, time);
        } else {
            drawGroundedCitySkyline(g, ambientFx, time);
            drawCityPlayableBuildingBodies(g, ambientFx, time);
            drawCityStreet(g, ambientFx, time);
        }

        drawCityPlatforms(g, parliamentTowers);
        drawCityRooftopFixtures(g, parliamentTowers);
        if (rooftopRelay) {
            drawRooftopRelayLandmarks(g);
        }
        // Billboards are deliberately last: rooftop equipment can never paint
        // over a sign again, even when a narrow platform carries both.
        drawCityNeonSigns(g, ambientFx, time, parliamentTowers);
    }

    private void drawRooftopRelayLandmarks(GraphicsContext g) {
        double nestX = 430.0;
        double nestY = GROUND_Y - 250.0;
        g.setStroke(Color.web("#7A4E32"));
        g.setLineWidth(9.0);
        for (int i = 0; i < 9; i++) {
            double offset = (i - 4) * 16.0;
            g.strokeArc(nestX - 92 + offset * 0.12, nestY - 46 + Math.abs(offset) * 0.10,
                    184 - Math.abs(offset) * 0.32, 70, 190, 160, ArcType.OPEN);
        }
        g.setFill(Color.web("#D9E2E7"));
        g.fillOval(nestX - 26, nestY - 54, 34, 44);
        g.setFill(Color.web("#ECEFF1"));
        g.fillOval(nestX + 10, nestY - 48, 30, 38);

        double towerX = 4_580.0;
        double towerY = GROUND_Y - 1_310.0;
        g.setStroke(Color.web("#263746"));
        g.setLineWidth(12.0);
        g.strokeLine(towerX - 95, towerY + 150, towerX - 62, towerY + 36);
        g.strokeLine(towerX + 95, towerY + 150, towerX + 62, towerY + 36);
        g.setFill(Color.web("#455A64"));
        g.fillRoundRect(towerX - 115, towerY - 34, 230, 100, 42, 42);
        g.setStroke(Color.web("#80DEEA", 0.52));
        g.setLineWidth(4.0);
        g.strokeRoundRect(towerX - 115, towerY - 34, 230, 100, 42, 42);
    }

    private void drawRooftopRelayDawn(GraphicsContext g, boolean ambientFx, double time) {
        double sunX = parallaxAdjustedWorldX(5300.0, 0.018);
        double sunY = 410.0;
        g.setFill(Color.web("#FFD180", 0.13));
        g.fillOval(sunX - 310, sunY - 310, 620, 620);
        g.setFill(Color.web("#FFF3C4", 0.86));
        g.fillOval(sunX - 105, sunY - 105, 210, 210);

        drawGroundedCityLayer(g, 340, 1050, 0.08,
                Color.web("#30384A", 0.72), Color.web("#A7C5D8", 0.13));
        drawGroundedCityLayer(g, 610, 1260, 0.20,
                Color.web("#171C2C", 0.92), Color.web("#B98AAE", 0.16));

        double beaconX = parallaxAdjustedWorldX(5570.0, 0.11);
        double beaconPulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 1.4) : 0.56;
        // The old cone crossed nearly the entire scene and looked like a gold
        // boundary wall at the right edge. Keep the landmark high in the sky
        // with compact radio rings and short rays instead.
        g.setFill(Color.web("#E9F8FF", 0.035 + beaconPulse * 0.025));
        g.fillOval(beaconX - 250, 250, 500, 500);
        g.setStroke(Color.web("#80DEEA", 0.24 + beaconPulse * 0.18));
        g.setLineWidth(8);
        g.strokeOval(beaconX - 130, 370, 260, 260);
        g.strokeOval(beaconX - 205, 295, 410, 410);
        g.setLineWidth(6);
        g.strokeLine(beaconX, 500, beaconX - 105, 280);
        g.strokeLine(beaconX, 500, beaconX + 105, 280);
        g.setFill(Color.web("#DFFBFF", 0.74 + beaconPulse * 0.16));
        g.fillOval(beaconX - 34, 468, 68, 68);
    }

    private void drawRooftopRelayCloudDeck(GraphicsContext g, boolean ambientFx, double time) {
        double drift = ambientFx ? (time * 9.0) % 900.0 : 160.0;
        // Keep the cloud bank visibly beneath the arena. A full-width rectangle
        // at GROUND_Y looked like a solid floor and hid an old implicit collision
        // plane, even though this route is meant to have open gaps between roofs.
        g.setFill(new LinearGradient(0, GROUND_Y + 80, 0, WORLD_HEIGHT, false,
                CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.TRANSPARENT),
                new Stop(0.42, Color.web("#EAF4FA", 0.07)),
                new Stop(1.0, Color.web("#F6E8E2", 0.16))));
        g.fillRect(0, GROUND_Y + 80, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 80);
        for (int i = -2; i < 10; i++) {
            double x = i * 760.0 + drift;
            g.setFill(Color.web(i % 2 == 0 ? "#FFF4E5" : "#E6F3FA", 0.14));
            g.fillOval(x, GROUND_Y + 105 + Math.floorMod(i, 3) * 38.0, 720, 190);
            g.fillOval(x + 170, GROUND_Y + 28 + Math.floorMod(i, 2) * 34.0, 390, 180);
        }
    }

    private double ashfallHazardStrengthMultiplier() {
        return classicModeActive
                && !bossRushModeActive
                && !ashfallTrialModeActive
                && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.PHOENIX_REBIRTH
                && classicPhoenixRebirthPhaseActive
                ? 1.25
                : 1.0;
    }

    private void drawCityStars(GraphicsContext g, boolean ambientFx, double time, boolean highAltitude) {
        int index = 0;
        for (double[] star : cityStars) {
            double twinkle = ambientFx ? 0.54 + 0.34 * Math.sin(time * 1.15 + index * 0.73) : 0.58;
            double alpha = (highAltitude ? 0.52 : 0.30) * Math.clamp(twinkle, 0.18, 1.0);
            double size = index % 17 == 0 ? 3.6 : index % 7 == 0 ? 2.4 : 1.4;
            g.setFill(Color.web(index % 13 == 0 ? "#B3E5FC" : "#FFFFFF", alpha));
            g.fillOval(star[0] - size * 0.5, star[1] - size * 0.5, size, size);
            index++;
        }
    }

    private void drawParliamentMoon(GraphicsContext g, boolean ambientFx, double time) {
        double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 0.42) : 0.5;
        double moonX = 4860;
        double moonY = 310;
        g.setFill(Color.web("#90CAF9", 0.045 + pulse * 0.025));
        g.fillOval(moonX - 270, moonY - 270, 540, 540);
        g.setFill(Color.web("#DDEBFF", 0.10));
        g.fillOval(moonX - 178, moonY - 178, 356, 356);
        g.setFill(Color.web("#F5F8FF", 0.88));
        g.fillOval(moonX - 116, moonY - 116, 232, 232);
        g.setFill(Color.web("#B0BEC5", 0.20));
        g.fillOval(moonX - 54, moonY - 70, 52, 34);
        g.fillOval(moonX + 34, moonY + 20, 38, 28);
        g.fillOval(moonX - 66, moonY + 48, 26, 20);
    }

    private void drawParliamentDistantCity(GraphicsContext g, boolean ambientFx, double time) {
        drawParliamentSkylineLayer(g, 0, 330, 2080, GROUND_Y + 470.0,
                0.08, Color.web("#10162B", 0.52), Color.web("#78A7C7", 0.14));
        drawParliamentSkylineLayer(g, 1, 510, 1840, GROUND_Y + 520.0,
                0.18, Color.web("#11192E", 0.70), Color.web("#CE7FC9", 0.16));
        drawParliamentSkylineLayer(g, 2, 740, 1760, GROUND_Y + 580.0,
                0.30, Color.web("#0B1122", 0.88), Color.web("#64D8E8", 0.19));

        if (ambientFx) {
            for (int i = 0; i < 7; i++) {
                double span = WORLD_WIDTH + 900.0;
                double aircraftX = (time * (24 + i * 5) + i * 940.0) % span - 450.0;
                double aircraftY = 1040 + (i % 4) * 175.0;
                Color light = i % 2 == 0 ? Color.web("#FF5252", 0.76) : Color.web("#80DEEA", 0.72);
                g.setFill(light);
                g.fillOval(aircraftX, aircraftY, 9, 5);
                g.setStroke(light.deriveColor(0, 1, 1, 0.24));
                g.setLineWidth(2);
                g.strokeLine(aircraftX - 82, aircraftY + 2, aircraftX, aircraftY + 2);
            }
        }
    }

    private void drawParliamentSkylineLayer(GraphicsContext g, int layer, double spacing,
                                             double topBase, double baseY, double movementFactor,
                                             Color buildingColor, Color windowColor) {
        int count = (int) Math.ceil((WORLD_WIDTH + 1800.0) / spacing);
        for (int i = -3; i < count; i++) {
            int shape = Math.floorMod(i * 5 + layer * 3, 9);
            double worldX = i * spacing + layer * 117.0;
            double x = parallaxAdjustedWorldX(worldX, movementFactor);
            double width = spacing * (0.52 + Math.floorMod(i * 7 + layer, 4) * 0.07);
            double topY = topBase + Math.floorMod(i * 173 + layer * 91, 430);
            if (shape == 0 || shape == 5) {
                topY -= 300 + layer * 55.0;
            }

            g.setFill(buildingColor);
            g.fillRect(x, topY, width, baseY - topY);
            if (shape % 3 == 0) {
                g.fillPolygon(
                        new double[]{x, x + width * 0.5, x + width},
                        new double[]{topY, topY - 110 - layer * 24.0, topY},
                        3
                );
                g.setStroke(buildingColor.brighter().deriveColor(0, 1, 1, 0.42));
                g.setLineWidth(3 + layer);
                g.strokeLine(x + width * 0.5, topY - 106 - layer * 24.0,
                        x + width * 0.5, topY - 205 - layer * 32.0);
            } else if (shape % 3 == 1) {
                g.fillRect(x + width * 0.18, topY - 58, width * 0.64, 58);
            }

            g.setFill(windowColor);
            double windowW = Math.max(7, width * 0.08);
            double columnGap = Math.max(28, width * 0.22);
            for (double wx = x + width * 0.15; wx < x + width * 0.86; wx += columnGap) {
                for (double wy = topY + 100 + layer * 22.0; wy < Math.min(baseY - 60, GROUND_Y + 260.0); wy += 104) {
                    if (((int) ((wx + wy) / 31.0) + layer) % 4 != 0) {
                        g.fillRoundRect(wx, wy, windowW, 23 + layer * 2.0, 4, 4);
                    }
                }
            }
        }
    }

    private void drawParliamentTowerBodies(GraphicsContext g, boolean ambientFx, double time) {
        double hazeBottom = GROUND_Y + 520.0;
        for (Platform p : platforms) {
            if (p.signText == null || p.w < 1000.0) {
                continue;
            }
            double inset = Math.min(130.0, p.w * 0.09);
            double bodyLeft = p.x + inset;
            double bodyRight = p.x + p.w - inset;
            double bodyTop = p.y + p.h - 2.0;
            double lowerInset = inset * 1.65;

            g.setFill(new LinearGradient(0, bodyTop, 0, hazeBottom, false, CycleMethod.NO_CYCLE,
                    new Stop(0.0, Color.web("#111829", 0.98)),
                    new Stop(0.55, Color.web("#121A2C", 0.80)),
                    new Stop(1.0, Color.web("#172540", 0.16))));
            g.fillPolygon(
                    new double[]{bodyLeft, bodyRight, p.x + p.w - lowerInset, p.x + lowerInset},
                    new double[]{bodyTop, bodyTop, hazeBottom, hazeBottom},
                    4
            );

            g.setStroke(Color.web("#4DD0E1", 0.20));
            g.setLineWidth(4);
            g.strokeLine(bodyLeft + 18, bodyTop + 28, p.x + lowerInset + 18, hazeBottom);
            g.setStroke(Color.web("#EC72D5", 0.16));
            g.strokeLine(bodyRight - 18, bodyTop + 28, p.x + p.w - lowerInset - 18, hazeBottom);

            int columns = Math.max(4, (int) Math.round((bodyRight - bodyLeft) / 190.0));
            double gap = (bodyRight - bodyLeft) / (columns + 1.0);
            for (int col = 1; col <= columns; col++) {
                double wx = bodyLeft + col * gap - 20;
                for (double wy = bodyTop + 105; wy < Math.min(hazeBottom - 100, GROUND_Y + 250.0); wy += 125) {
                    double lit = ambientFx ? 0.15 + 0.10 * (0.5 + 0.5 * Math.sin(time * 0.34 + col + wy * 0.01)) : 0.17;
                    g.setFill(Color.web(col % 3 == 0 ? "#FF80D5" : "#80DEEA", lit));
                    g.fillRoundRect(wx, wy, 40, 50, 6, 6);
                }
            }
        }
    }

    private void drawParliamentCloudDeck(GraphicsContext g, boolean ambientFx, double time) {
        double drift = ambientFx ? (time * 13.0) % 820.0 : 180.0;
        g.setFill(Color.web("#A9C7D8", 0.10));
        g.fillRect(0, GROUND_Y - 110.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y + 110.0);
        for (int layer = 0; layer < 3; layer++) {
            double y = GROUND_Y - 170.0 + layer * 105.0;
            double alpha = 0.13 + layer * 0.055;
            g.setFill(Color.web(layer == 0 ? "#B5CFDD" : "#D7E4EA", alpha));
            for (int i = -3; i < 11; i++) {
                double x = i * 760.0 + drift * (0.35 + layer * 0.24) - layer * 210.0;
                double w = 720 + ((i + layer) & 1) * 180.0;
                g.fillOval(x, y + (i % 3) * 24.0, w, 150 + layer * 36.0);
                g.fillOval(x + w * 0.22, y - 38 + (i % 2) * 20.0, w * 0.54, 150 + layer * 24.0);
            }
        }
        g.setFill(Color.web("#DCE9EF", 0.12));
        g.fillRect(0, GROUND_Y + 170.0, WORLD_WIDTH, 230.0);
    }

    private void drawGroundedCitySkyline(GraphicsContext g, boolean ambientFx, double time) {
        // Extremely low parallax and a subdued value keep the moon behind the
        // skyline instead of making it read like a foreground stage prop.
        double moonX = parallaxAdjustedWorldX(4720.0, 0.025);
        double moonY = 300.0;
        g.setFill(Color.web("#9FA8DA", 0.035));
        g.fillOval(moonX - 175, moonY - 175, 350, 350);
        g.setFill(Color.web("#E8ECFF", 0.56));
        g.fillOval(moonX - 82, moonY - 82, 164, 164);
        g.setFill(Color.web("#09112A", 0.97));
        g.fillOval(moonX - 34, moonY - 94, 158, 158);

        drawGroundedCityLayer(g, 430, 1280, 0.12,
                Color.web("#15142A", 0.68), Color.web("#5C6BC0", 0.18));
        drawGroundedCityLayer(g, 780, 900, 0.30,
                Color.web("#0D1020", 0.92), Color.web("#FF67CC", ambientFx ? 0.34 : 0.22));

        if (ambientFx) {
            g.setFill(Color.web("#80DEEA", 0.16));
            for (int i = 0; i < 8; i++) {
                double x = (time * (16 + i * 3) + i * 820.0) % (WORLD_WIDTH + 500.0) - 250.0;
                double y = 720 + (i % 4) * 210.0;
                g.fillOval(x, y, 7, 4);
            }
        }
    }

    private void drawCityPlayableBuildingBodies(GraphicsContext g, boolean ambientFx, double time) {
        CityBuildingGeometry.Layout layout = activeArenaGeometryVariant == MapVariant.ROOFTOP_RELAY
                ? CityBuildingGeometry.createRooftopRelay(platforms, GROUND_Y)
                : CityBuildingGeometry.create(platforms, GROUND_Y);
        for (CityBuildingGeometry.Facade facade : layout.facades()) {
            drawCityRectangularFacade(g, facade, ambientFx, time);
        }
        for (CityBuildingGeometry.BalconyBraces braces : layout.balconyBraces()) {
            drawCityBalconyBraces(g, braces);
        }
    }

    private void drawCityRectangularFacade(GraphicsContext g, CityBuildingGeometry.Facade facade,
                                             boolean ambientFx, double time) {
        Platform roof = facade.roof();
        CityBuildingGeometry.Bounds bounds = facade.bounds();
        double roofBottom = bounds.y();
        double baseY = bounds.bottom();
        double bodyX = bounds.x();
        double bodyW = bounds.width();
        double bodyH = bounds.height();
        Color bodyTop = roof.w >= 500.0 ? Color.web("#111426") : Color.web("#17172A");
        Color bodyBottom = roof.w >= 500.0 ? Color.web("#1B1C32") : Color.web("#232039");
        g.setFill(new LinearGradient(0, roofBottom, 0, baseY, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, bodyTop), new Stop(1.0, bodyBottom)));
        g.fillRect(bodyX, roofBottom, bodyW, bodyH);

        g.setStroke(Color.web("#303852", 0.66));
        g.setLineWidth(2.0);
        g.strokeRect(bodyX, roofBottom, bodyW, bodyH);

        int columns = Math.clamp((int) Math.round(bodyW / 120.0), 1, 6);
        double columnGap = bodyW / (columns + 1.0);
        for (int col = 1; col <= columns; col++) {
            double wx = bodyX + col * columnGap - 14.0;
            for (double wy = roofBottom + 64.0; wy < baseY - 34.0; wy += 104.0) {
                double shimmer = ambientFx
                        ? 0.18 + 0.08 * (0.5 + 0.5 * Math.sin(time * 0.42 + col + wy * 0.012))
                        : 0.21;
                g.setFill(Color.web((col + (int) (wy / 94.0)) % 3 == 0
                        ? "#C75AAB" : "#4F7898", shimmer));
                g.fillRect(wx, wy, 28, 38);
            }
        }
    }

    private void drawCityBalconyBraces(GraphicsContext g, CityBuildingGeometry.BalconyBraces braces) {
        Platform balcony = braces.balcony();
        double undersideY = balcony.y + balcony.h;
        if (braces.integratedIntoFacade()) {
            g.setFill(Color.web("#171B2D", 0.92));
            g.fillRect(balcony.x + 18.0, undersideY, Math.max(40.0, balcony.w - 36.0), 18.0);
        }
        g.setStroke(Color.web("#39435F", 0.88));
        g.setLineWidth(8.0);
        for (StageArtGeometry.Segment segment : braces.segments()) {
            g.strokeLine(segment.start().x(), segment.start().y(), segment.end().x(), segment.end().y());
        }
        g.setStroke(Color.web("#2DE2E6", 0.16));
        g.setLineWidth(2.0);
        for (StageArtGeometry.Segment segment : braces.segments()) {
            g.strokeLine(segment.start().x(), segment.start().y() + 2.0,
                    segment.end().x(), segment.end().y() - 2.0);
        }
        g.setFill(Color.web("#60708E", 0.94));
        for (StageArtGeometry.Segment segment : braces.segments()) {
            g.fillOval(segment.end().x() - 8.0, segment.end().y() - 8.0, 16.0, 16.0);
        }
    }

    private void drawGroundedCityLayer(GraphicsContext g, double spacing, double topBase,
                                        double movementFactor,
                                        Color buildingColor, Color windowColor) {
        int count = (int) Math.ceil((WORLD_WIDTH + 1400.0) / spacing);
        for (int i = -2; i < count; i++) {
            double x = parallaxAdjustedWorldX(i * spacing, movementFactor);
            double width = spacing * (0.62 + Math.floorMod(i, 3) * 0.08);
            double topY = topBase + Math.floorMod(i * 197, 560);
            if (Math.floorMod(i, 5) == 0) {
                topY -= 270;
            }
            g.setFill(buildingColor);
            g.fillRect(x, topY, width, GROUND_Y - topY);
            if (Math.floorMod(i, 3) == 0) {
                g.fillPolygon(new double[]{x, x + width * 0.5, x + width},
                        new double[]{topY, topY - 120, topY}, 3);
            } else {
                g.fillRect(x + width * 0.18, topY - 54, width * 0.64, 54);
            }

            g.setFill(windowColor);
            for (double wx = x + 54; wx < x + width - 30; wx += 96) {
                for (double wy = topY + 92; wy < GROUND_Y - 50; wy += 132) {
                    if (((int) ((wx + wy) / 47.0)) % 5 != 0) {
                        g.fillRoundRect(wx, wy, 30, 48, 5, 5);
                    }
                }
            }
        }
    }

    private void drawCityStreet(GraphicsContext g, boolean ambientFx, double time) {
        g.setFill(Color.web("#101321"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(Color.web("#202338"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, 54);
        g.setStroke(Color.web("#FF3DC8", 0.20));
        g.setLineWidth(5);
        double shift = ambientFx ? (time * 18.0) % 360.0 : 0.0;
        for (double x = -420 + shift; x < WORLD_WIDTH + 420; x += 360) {
            g.strokeLine(x, GROUND_Y + 240, x + 180, GROUND_Y + 60);
        }
    }

    private void drawCityPlatforms(GraphicsContext g, boolean parliamentTowers) {
        for (Platform p : platforms) {
            if (p.y >= GROUND_Y - 2.0 || p.x < -50.0 || p.x >= WORLD_WIDTH) {
                continue;
            }
            boolean towerRoof = parliamentTowers && p.signText != null && p.w >= 1000.0;
            double round = towerRoof ? 20.0 : 12.0;
            g.setFill(Color.web(towerRoof ? "#161D2D" : "#292C40"));
            g.fillRoundRect(p.x, p.y + p.h * 0.26, p.w, p.h * 0.94, round, round);
            g.setFill(Color.web(towerRoof ? "#303A50" : "#45485C"));
            g.fillRoundRect(p.x, p.y, p.w, p.h, round, round);
            g.setFill(Color.web("#8793A8", 0.22));
            g.fillRoundRect(p.x + 9, p.y + 7, Math.max(18, p.w - 18), Math.max(9, p.h * 0.27), round, round);

            Color edge = towerRoof ? Color.web("#72F1FF") : Color.web("#2DE2E6");
            g.setStroke(edge.deriveColor(0, 1, 1, 0.84));
            g.setLineWidth(towerRoof ? 5.0 : 3.5);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, round, round);
            if (p.y < GROUND_Y - 400.0) {
                g.setStroke(Color.web("#FF3DC8", towerRoof ? 0.48 : 0.72));
                g.setLineWidth(2.2);
                g.strokeRoundRect(p.x - 8, p.y - 8, p.w + 16, p.h + 16, round + 4, round + 4);
            }

            if (towerRoof) {
                g.setStroke(Color.web("#FFCA28", 0.36));
                g.setLineWidth(4);
                for (double markX = p.x + 70; markX < p.x + p.w - 50; markX += 180) {
                    g.strokeLine(markX, p.y + p.h - 16, markX + 50, p.y + p.h - 16);
                }
            }
        }
    }

    private void drawCityRooftopFixtures(GraphicsContext g, boolean parliamentTowers) {
        for (Platform p : platforms) {
            if (p.w <= 300.0 || p.y >= GROUND_Y - 200.0 || p.y >= GROUND_Y - 2.0) {
                continue;
            }
            int fixtureCount = p.w >= 760.0 ? 2 : 1;
            double boxW = Math.clamp(p.w * 0.13, 78.0, 118.0);
            double boxH = parliamentTowers ? 48.0 : 43.0;
            for (int i = 0; i < fixtureCount; i++) {
                double boxX = fixtureCount == 1
                        ? p.x + 34.0
                        : (i == 0 ? p.x + 58.0 : p.x + p.w - boxW - 58.0);
                double boxY = p.y - boxH;
                g.setFill(Color.web("#1B2230"));
                g.fillRoundRect(boxX, boxY, boxW, boxH, 8, 8);
                g.setStroke(Color.web("#718096", 0.72));
                g.setLineWidth(2.4);
                g.strokeRoundRect(boxX, boxY, boxW, boxH, 8, 8);
                g.setFill(Color.web("#0A101A"));
                g.fillOval(boxX + boxW * 0.31, boxY + 10, boxW * 0.38, boxH * 0.50);
                g.setStroke(Color.web("#90A4AE", 0.52));
                g.setLineWidth(2);
                g.strokeOval(boxX + boxW * 0.31, boxY + 10, boxW * 0.38, boxH * 0.50);
                g.strokeLine(boxX + boxW * 0.50, boxY + 13, boxX + boxW * 0.50, boxY + boxH * 0.55);
            }
        }
    }

    private void drawCityNeonSigns(GraphicsContext g, boolean ambientFx, double time,
                                   boolean parliamentTowers) {
        for (Platform p : platforms) {
            if (p.signText == null || p.signText.isBlank()) {
                continue;
            }
            String text = p.signText.toUpperCase(Locale.ROOT);
            int paletteIndex = Math.floorMod(text.hashCode(), 4);
            Color neon = switch (paletteIndex) {
                case 0 -> Color.web("#2DE2E6");
                case 1 -> Color.web("#FF3DC8");
                case 2 -> Color.web("#B388FF");
                default -> Color.web("#FFD740");
            };
            double fontSize = Math.clamp((p.w + 100.0) / Math.max(6.0, text.length() * 0.78),
                    parliamentTowers ? 24.0 : 19.0, parliamentTowers ? 36.0 : 31.0);
            double estimatedTextW = text.length() * fontSize * 0.66;
            double panelW = Math.max(145.0, estimatedTextW + 72.0);
            panelW = Math.min(panelW, Math.max(170.0, p.w + (p.w < 320.0 ? 90.0 : -42.0)));
            double panelH = fontSize + 34.0;
            double panelX = p.x + p.w * 0.5 - panelW * 0.5;
            double panelBottom = p.y - 62.0;
            double panelY = panelBottom - panelH;
            double neonPulse = ambientFx ? 0.78 + 0.22 * Math.sin(time * 5.0 + p.x * 0.013) : 0.82;

            g.save();
            g.setStroke(Color.web("#101522", 0.94));
            g.setLineWidth(9);
            g.strokeLine(panelX + 24, panelBottom, panelX + 24, p.y - 8);
            g.strokeLine(panelX + panelW - 24, panelBottom, panelX + panelW - 24, p.y - 8);

            g.setFill(Color.web("#050914", 0.92));
            g.fillRoundRect(panelX, panelY, panelW, panelH, 14, 14);
            g.setStroke(neon.deriveColor(0, 1, 1, 0.20 + neonPulse * 0.25));
            g.setLineWidth(12);
            g.strokeRoundRect(panelX + 3, panelY + 3, panelW - 6, panelH - 6, 14, 14);
            if (ambientFx) {
                g.setEffect(new Glow(0.82));
            }
            g.setStroke(neon.deriveColor(0, 1, 1, neonPulse));
            g.setLineWidth(3.2);
            g.strokeRoundRect(panelX + 4, panelY + 4, panelW - 8, panelH - 8, 12, 12);
            g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.72 * neonPulse));
            g.setLineWidth(1.2);
            g.strokeRoundRect(panelX + 8, panelY + 8, panelW - 16, panelH - 16, 9, 9);

            g.setFont(Font.font("Arial Black", FontWeight.BOLD, fontSize));
            g.setTextAlign(TextAlignment.CENTER);
            double textY = panelY + panelH * 0.68;
            g.setStroke(neon.deriveColor(0, 1, 1, 0.52 * neonPulse));
            g.setLineWidth(5.4);
            g.strokeText(text, panelX + panelW * 0.5, textY);
            g.setFill(Color.WHITE.interpolate(neon, 0.34).deriveColor(0, 1, 1, neonPulse));
            g.fillText(text, panelX + panelW * 0.5, textY);
            g.restore();
        }
    }

    private void drawCrownDuelArenaDetails(GraphicsContext g, boolean ambientFx) {
        double pulse = ambientFx
                ? 0.5 + 0.5 * Math.sin(System.nanoTime() / 180_000_000.0)
                : 0.5;
        double bridgeCenterX = CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W * 0.5;
        double bridgeBottomY = CROWN_DUEL_BRIDGE_Y + CROWN_DUEL_BRIDGE_H;

        g.save();
        g.setFill(Color.web("#020713", 0.30));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        // Pigeon's sealed transport hangs below the duel as the immediate stake.
        double transportY = CROWN_DUEL_BRIDGE_Y + 520.0;
        g.setStroke(Color.web("#90CAF9", 0.34));
        g.setLineWidth(10.0);
        g.strokeLine(CROWN_DUEL_BRIDGE_X + 250.0, bridgeBottomY,
                CROWN_DUEL_BRIDGE_X + 620.0, transportY);
        g.strokeLine(CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W - 250.0, bridgeBottomY,
                CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W - 620.0, transportY);
        g.setFill(Color.web("#071726", 0.92));
        g.fillRoundRect(bridgeCenterX - 620.0, transportY, 1240.0, 250.0, 90.0, 90.0);
        g.setStroke(Color.web("#4FC3F7", 0.48 + pulse * 0.28));
        g.setLineWidth(12.0);
        g.strokeRoundRect(bridgeCenterX - 620.0, transportY, 1240.0, 250.0, 90.0, 90.0);
        g.setFill(Color.web("#B3E5FC", 0.58));
        for (int i = 0; i < 6; i++) {
            g.fillRoundRect(bridgeCenterX - 480.0 + i * 170.0, transportY + 72.0,
                    92.0, 54.0, 18.0, 18.0);
        }

        // Crown command pylons frame the bridge and visibly lock the duel in.
        double leftPylonX = CROWN_DUEL_BRIDGE_X - 120.0;
        double rightPylonX = CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W + 120.0;
        g.setStroke(Color.web("#80DEEA", 0.42 + pulse * 0.38));
        g.setLineWidth(18.0);
        g.strokeLine(leftPylonX, CROWN_DUEL_BRIDGE_Y - 980.0, leftPylonX, bridgeBottomY + 180.0);
        g.strokeLine(rightPylonX, CROWN_DUEL_BRIDGE_Y - 980.0, rightPylonX, bridgeBottomY + 180.0);
        g.setStroke(Color.web("#FFF59D", 0.32 + pulse * 0.28));
        g.setLineWidth(8.0);
        g.strokeLine(leftPylonX, CROWN_DUEL_BRIDGE_Y - 790.0,
                bridgeCenterX, CROWN_DUEL_BRIDGE_Y - 610.0);
        g.strokeLine(rightPylonX, CROWN_DUEL_BRIDGE_Y - 790.0,
                bridgeCenterX, CROWN_DUEL_BRIDGE_Y - 610.0);

        // Redraw the authored duel geometry as Crown steel rather than grassy cliffs.
        for (Platform platform : platforms) {
            g.setFill(Color.web("#101C2A", 0.98));
            g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 24.0, 24.0);
            g.setStroke(Color.web("#78909C", 0.92));
            g.setLineWidth(platform == platforms.getFirst() ? 12.0 : 8.0);
            g.strokeRoundRect(platform.x, platform.y, platform.w, platform.h, 24.0, 24.0);
            g.setStroke(Color.web("#80DEEA", 0.34 + pulse * 0.24));
            g.setLineWidth(5.0);
            g.strokeLine(platform.x + 34.0, platform.y + 12.0,
                    platform.x + platform.w - 34.0, platform.y + 12.0);
        }

        g.setStroke(Color.web("#FFEE58", 0.48 + pulse * 0.38));
        g.setLineWidth(14.0);
        g.strokeOval(bridgeCenterX - 125.0, CROWN_DUEL_BRIDGE_Y - 128.0, 250.0, 250.0);
        g.strokeLine(bridgeCenterX, CROWN_DUEL_BRIDGE_Y - 172.0,
                bridgeCenterX, CROWN_DUEL_BRIDGE_Y + 110.0);
        g.strokeLine(bridgeCenterX - 142.0, CROWN_DUEL_BRIDGE_Y - 4.0,
                bridgeCenterX + 142.0, CROWN_DUEL_BRIDGE_Y - 4.0);
        g.restore();
    }

    private void drawCampaignObjectiveMarkers(GraphicsContext g) {
        if (!campaignModeActive || campaignMissionController == null || currentCampaignMission == null) {
            return;
        }
        StoryCampaign.MissionPhase phase = campaignMissionController.currentPhase();
        double pulse = 0.72 + 0.18 * Math.sin(System.nanoTime() / 240_000_000.0);
        g.save();
        switch (phase.objective()) {
            case CAPTURE, HOLD_ZONE -> {
                int total = Math.max(1, phase.targetCount());
                int cleared = campaignMissionController.capturedTargets();
                double floorY = campaignMissionController.objectiveFloorY();
                for (int i = 0; i < total; i++) {
                    double x = campaignMissionController.captureZoneCenterX(i, total);
                    boolean complete = i < cleared;
                    boolean active = i == cleared;
                    Color accent = complete ? Color.web("#69F0AE")
                            : active ? Color.web("#80DEEA") : Color.web("#78909C");
                    double alpha = active ? pulse : 0.42;
                    g.setFill(accent.deriveColor(0, 1, 1, alpha * 0.22));
                    g.fillOval(x - 150, floorY - 30, 300, 60);
                    g.setStroke(accent.deriveColor(0, 1, 1, alpha));
                    g.setLineWidth(active ? 12 : 7);
                    g.strokeOval(x - 150, floorY - 30, 300, 60);
                    g.setFill(accent.deriveColor(0, 1, 1, 0.18 + alpha * 0.18));
                    g.fillRoundRect(x - 24, floorY - 250, 48, 220, 18, 18);
                    g.setFont(Font.font("Arial Black", FontWeight.BOLD, 42));
                    g.setTextAlign(TextAlignment.CENTER);
                    g.setFill(accent);
                    g.fillText(complete ? "✓" : Integer.toString(i + 1), x, floorY - 274);
                }
            }
            case REACH_EXIT -> {
                double x = campaignMissionController.reachExitMarkerX();
                double floorY = campaignMissionController.objectiveFloorY();
                g.setFill(Color.web("#FFE082", 0.12 + pulse * 0.20));
                g.fillRoundRect(x - 100, floorY - 520, 200, 520, 42, 42);
                g.setStroke(Color.web("#FFE082", pulse));
                g.setLineWidth(12);
                g.strokeRoundRect(x - 100, floorY - 520, 200, 520, 42, 42);
                g.setFill(Color.web("#FFF8E1"));
                g.fillPolygon(
                        new double[]{x - 64, x + 16, x + 16, x + 82, x + 16, x + 16},
                        new double[]{floorY - 320, floorY - 320, floorY - 382,
                                floorY - 270, floorY - 158, floorY - 220},
                        6
                );
            }
            case PROTECT -> {
                Bird protectedBird = null;
                for (int i = 1; i < activePlayers; i++) {
                    if (players[i] != null && players[i].health > 0 && getEffectiveTeam(i) == 1) {
                        protectedBird = players[i];
                        break;
                    }
                }
                if (protectedBird != null) {
                    double radius = 120 + pulse * 18;
                    double cx = protectedBird.x + 40;
                    double cy = protectedBird.y + 40;
                    g.setFill(Color.web("#69F0AE", 0.10));
                    g.fillOval(cx - radius, cy - radius, radius * 2, radius * 2);
                    g.setStroke(Color.web("#69F0AE", pulse));
                    g.setLineWidth(10);
                    g.strokeOval(cx - radius, cy - radius, radius * 2, radius * 2);
                    g.setFont(Font.font("Arial Black", FontWeight.BOLD, 30));
                    g.setTextAlign(TextAlignment.CENTER);
                    g.setFill(Color.web("#E8FFF1"));
                    g.fillText("PROTECT", cx, cy - radius - 18);
                }
            }
            case BOSS_PHASES -> {
                Bird boss = null;
                for (int i = 1; i < activePlayers; i++) {
                    if (players[i] != null && players[i].health > 0 && getEffectiveTeam(i) == 2
                            && (boss == null || campaignStartingHealth[i] > campaignStartingHealth[boss.playerIndex])) {
                        boss = players[i];
                    }
                }
                if (boss != null) {
                    double cx = boss.x + 40;
                    double cy = boss.y + 40;
                    g.setStroke(Color.web("#FF5252", pulse * 0.82));
                    g.setLineWidth(9);
                    g.strokeOval(cx - 112, cy - 112, 224, 224);
                }
            }
            case SURVIVE, ELIMINATION, GAUNTLET -> {
            }
        }
        g.restore();
    }

    private void drawUltimateReadyScreenDarken(GraphicsContext g) {
        if (!hasUltimateReadyBird()) return;
        double safeZoom = Math.max(0.01, zoom);
        double viewWidth = WIDTH / safeZoom;
        double viewHeight = HEIGHT / safeZoom;
        double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 360.0);
        double alpha = 0.22 + pulse * 0.06;
        double pad = 220.0 / safeZoom + Math.max(80.0, shakeIntensity * 3.0);

        g.setFill(Color.rgb(0, 0, 0, alpha));
        g.fillRect(camX - pad, camY - pad, viewWidth + pad * 2.0, viewHeight + pad * 2.0);
    }

    private boolean hasUltimateReadyBird() {
        for (int i = 0; i < activePlayers; i++) {
            Bird bird = players[i];
            if (bird != null && bird.isUltimateVisualReady()) {
                return true;
            }
        }
        return false;
    }

    private boolean hasShoebillFinalStillnessActive() {
        return activeShoebillFinalStillnessBird() != null;
    }

    private Bird activeShoebillFinalStillnessBird() {
        for (int i = 0; i < activePlayers; i++) {
            Bird bird = players[i];
            if (bird != null
                    && bird.health > 0
                    && bird.type == BirdType.SHOEBILL
                    && bird.shoebillFinalStillnessTimer > 0) {
                return bird;
            }
        }
        return null;
    }

    private void drawShoebillFinalStillnessScreenDrain(GraphicsContext g) {
        Bird bird = activeShoebillFinalStillnessBird();
        if (bird == null) return;
        double safeZoom = Math.max(0.01, zoom);
        double viewWidth = WIDTH / safeZoom;
        double viewHeight = HEIGHT / safeZoom;
        int elapsed = ShoebillSpecials.finalStillnessElapsed(bird);
        double fadeIn = Math.clamp(elapsed / 18.0, 0.0, 1.0);
        double fadeOut = Math.clamp(bird.shoebillFinalStillnessTimer / 24.0, 0.0, 1.0);
        double alpha = Math.min(fadeIn, fadeOut);
        if (alpha <= 0.0) return;

        double pad = 240.0 / safeZoom + Math.max(80.0, shakeIntensity * 3.0);
        double left = camX - pad;
        double top = camY - pad;
        double width = viewWidth + pad * 2.0;
        double height = viewHeight + pad * 2.0;
        double pulse = 0.5 + 0.5 * Math.sin((elapsed + bird.playerIndex * 13.0) * 0.34);

        g.save();
        g.setFill(Color.gray(0.36, (0.28 + pulse * 0.04) * alpha));
        g.fillRect(left, top, width, height);
        g.setFill(Color.rgb(0, 0, 0, 0.18 * alpha));
        g.fillRect(left, top, width, height);
        g.setStroke(Color.web("#FF1744", (0.16 + pulse * 0.12) * alpha));
        g.setLineWidth(2.0 / safeZoom);
        double centerX = camX + viewWidth * 0.5;
        double centerY = camY + viewHeight * 0.5;
        for (int i = 0; i < 5; i++) {
            double inset = (34.0 + i * 30.0) / safeZoom;
            g.strokeRoundRect(centerX - viewWidth * 0.5 + inset, centerY - viewHeight * 0.5 + inset,
                    viewWidth - inset * 2.0, viewHeight - inset * 2.0, 20.0 / safeZoom, 20.0 / safeZoom);
        }
        if (ShoebillSpecials.finalStillnessBeamActive(bird)) {
            g.setFill(Color.web("#FF1744", 0.10 * alpha));
            g.fillRect(left, top, width, height);
        }
        g.restore();
    }

    private void drawSwingingVines(GraphicsContext g, boolean ambientFx) {
        boolean junglePalette = selectedMap == MapType.VIBRANT_JUNGLE;
        for (SwingingVine vine : swingingVines) {
            drawSwingingVine(g, vine, ambientFx, junglePalette);
        }
    }

    private void drawSwingingVine(GraphicsContext g, SwingingVine vine, boolean ambientFx, boolean junglePalette) {
        double tipX = vine.gripX();
        double tipY = vine.gripY();
        double controlX = (vine.baseX + tipX) * 0.5 - Math.cos(vine.angle) * (junglePalette ? 34 : 22);
        double controlY = vine.baseY + vine.length * 0.42 + Math.abs(Math.sin(vine.angle)) * 28;
        int segments = 16;

        Color vineCore = junglePalette ? Color.web("#2E7D32") : Color.web("#33691E");
        Color vineHighlight = junglePalette ? Color.web("#66BB6A") : Color.web("#7CB342");
        Color leaf = junglePalette ? Color.web("#8BC34A") : Color.web("#9CCC65");
        if (vine.temporary) {
            vineCore = Color.web("#43A047");
            vineHighlight = Color.web("#A5D6A7");
            leaf = Color.web("#C5E1A5");
        }
        if (vine.detaching) {
            vineCore = vineCore.deriveColor(0, 1, 1, 0.88);
            vineHighlight = vineHighlight.deriveColor(0, 1, 1, 0.7);
            leaf = leaf.deriveColor(0, 1, 1, 0.86);
        }

        double prevX = vine.baseX;
        double prevY = vine.baseY;
        for (int i = 1; i <= segments; i++) {
            double t = i / (double) segments;
            double pointX = quadraticPoint(vine.baseX, controlX, tipX, t);
            double pointY = quadraticPoint(vine.baseY, controlY, tipY, t);
            g.setStroke(vineCore);
            g.setLineWidth(10 - t * 4);
            g.strokeLine(prevX, prevY, pointX, pointY);
            g.setStroke(vineHighlight.deriveColor(0, 1, 1, 0.62));
            g.setLineWidth(4 - t * 1.4);
            g.strokeLine(prevX + 1.5, prevY, pointX + 1.5, pointY);

            if (junglePalette && (i == 4 || i == 8 || i == 12)) {
                drawSwingingVineLeafCluster(g, pointX, pointY, leaf, ambientFx);
            }
            prevX = pointX;
            prevY = pointY;
        }

        if (!vine.detaching) {
            g.setFill(Color.web("#4E342E"));
            g.fillOval(vine.baseX - 14, vine.baseY - 12, 28, 24);
        } else {
            g.setStroke(Color.web("#6D4C41", 0.8));
            g.setLineWidth(3.0);
            g.strokeLine(vine.baseX - 6, vine.baseY - 5, vine.baseX + 3, vine.baseY + 8);
            g.strokeLine(vine.baseX + 1, vine.baseY - 6, vine.baseX + 8, vine.baseY + 6);
        }

        g.setFill(leaf);
        g.fillOval(tipX - 22, tipY - 14, 44, 28);
        g.fillOval(tipX - 12, tipY - 22, 30, 22);
        g.fillOval(tipX - 24, tipY - 8, 26, 18);

        if (ambientFx && junglePalette) {
            g.setEffect(new Glow(vine.temporary ? 0.35 : 0.18));
            g.setFill(Color.web("#F06292", vine.temporary ? 0.44 : 0.28));
            g.fillOval(tipX - 10, tipY - 10, 20, 20);
            g.setEffect(null);
        }
    }

    private void drawSwingingVineLeafCluster(GraphicsContext g, double x, double y, Color leaf, boolean ambientFx) {
        g.setFill(leaf);
        g.fillOval(x - 12, y - 10, 24, 16);
        g.fillOval(x - 4, y - 16, 20, 14);
        g.fillOval(x - 16, y - 4, 18, 14);
        if (ambientFx) {
            g.setFill(Color.web("#F8BBD0", 0.55));
            g.fillOval(x - 5, y - 5, 10, 10);
        }
    }

    private double quadraticPoint(double start, double control, double end, double t) {
        double inv = 1.0 - t;
        return inv * inv * start + 2 * inv * t * control + t * t * end;
    }

    private void drawVibrantJungleArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#082C36")),
                new Stop(0.42, Color.web("#2F7469")),
                new Stop(0.74, Color.web("#8CB68A")),
                new Stop(1.0, Color.web("#D4C47A"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        g.setFill(Color.web("#FFF1A8", 0.13));
        g.fillOval(4_360.0, 140.0, 820.0, 820.0);
        g.setFill(Color.web("#FFF6BD", 0.82));
        g.fillOval(4_650.0, 425.0, 240.0, 240.0);

        drawJungleDistantRidges(g);
        drawJungleMistBands(g, time, ambientFx);
        drawJungleDistantCanopy(g);
        for (int i = 0; i < JUNGLE_TREE_X.length; i++) {
            drawJungleLivingTree(g, JUNGLE_TREE_X[i], i);
        }
        drawJungleRootFloor(g);

        for (Platform platform : platforms) {
            if (isJungleAerialPlatform(platform)) drawJungleBranchSupport(g, platform, false);
        }
        for (Platform platform : platforms) {
            if (isJungleAerialPlatform(platform)) drawJungleLivingLedge(g, platform, false);
        }
        for (WindVent vent : windVents) drawJungleUpdraft(g, vent, time, ambientFx, false);
        for (NectarNode node : nectarNodes) drawJungleNectar(g, node, time, ambientFx, false);
        drawJungleOrchidsAndFireflies(g, time, ambientFx);
    }

    private void drawJungleDistantRidges(GraphicsContext g) {
        double[] peaks = mountainPeaks;
        g.setFill(Color.web("#174B45", 0.58));
        for (int m = 0; m < MOUNTAIN_X.length - 1; m++) {
            double baseY = GROUND_Y + 340.0;
            double peakY = peaks != null && m < peaks.length
                    ? peaks[m] + 310.0 : GROUND_Y - 650.0 - (m % 3) * 230.0;
            double midX = (MOUNTAIN_X[m] + MOUNTAIN_X[m + 1]) * 0.5;
            g.fillPolygon(new double[]{MOUNTAIN_X[m], midX, MOUNTAIN_X[m + 1]},
                    new double[]{baseY, peakY, baseY}, 3);
        }
        g.setFill(Color.web("#123A38", 0.72));
        for (int m = 0; m < MOUNTAIN_X.length - 1; m++) {
            double baseY = GROUND_Y + 390.0;
            double peakY = GROUND_Y - 470.0 - (m % 2) * 260.0;
            double midX = (MOUNTAIN_X[m] + MOUNTAIN_X[m + 1]) * 0.5 + (m % 2 == 0 ? 110.0 : -90.0);
            g.fillPolygon(new double[]{MOUNTAIN_X[m], midX, MOUNTAIN_X[m + 1]},
                    new double[]{baseY, peakY, baseY}, 3);
        }
    }

    private void drawJungleMistBands(GraphicsContext g, double time, boolean ambientFx) {
        for (int band = 0; band < 4; band++) {
            double drift = ambientFx ? Math.sin(time * 0.08 + band * 1.4) * 65.0 : 0.0;
            double y = 1_280.0 + band * 360.0;
            g.setFill(Color.web(band % 2 == 0 ? "#D7F2DF" : "#BCE5D9", 0.12 + band * 0.025));
            for (int cloud = 0; cloud < 7; cloud++) {
                double x = -520.0 + cloud * 1_070.0 + (band % 2 == 0 ? drift : -drift);
                g.fillOval(x, y + (cloud % 2) * 42.0, 1_180.0, 250.0);
            }
        }
    }

    private void drawJungleDistantCanopy(GraphicsContext g) {
        for (int i = 0; i < 18; i++) {
            double x = 90.0 + i * 355.0;
            double top = 610.0 + (i % 4) * 115.0;
            double width = 92.0 + (i % 3) * 22.0;
            g.setFill(Color.web("#17483F", 0.66));
            g.fillRoundRect(x - width * 0.5, top, width, GROUND_Y - top + 50.0, 60.0, 60.0);
            g.setFill(Color.web(i % 2 == 0 ? "#24634F" : "#1F5A49", 0.82));
            g.fillOval(x - 180.0, top - 85.0, 360.0, 190.0);
            g.fillOval(x - 115.0, top - 155.0, 280.0, 180.0);
        }
    }

    private void drawJungleLivingTree(GraphicsContext g, double centerX, int index) {
        double crownY = GROUND_Y - 2_180.0 + (index % 2) * 80.0;
        double trunkTop = crownY + 105.0;
        double baseHalf = 155.0 + (index % 3) * 18.0;
        double topHalf = 82.0 + (index % 2) * 14.0;
        g.setFill(Color.web(index % 2 == 0 ? "#4B2E22" : "#543426"));
        g.fillPolygon(new double[]{centerX - baseHalf, centerX - topHalf,
                        centerX + topHalf, centerX + baseHalf},
                new double[]{GROUND_Y + 75.0, trunkTop, trunkTop, GROUND_Y + 75.0}, 4);
        g.setFill(Color.web("#744A2E", 0.78));
        g.fillPolygon(new double[]{centerX - baseHalf * 0.46, centerX - topHalf * 0.42,
                        centerX + topHalf * 0.06, centerX + baseHalf * 0.12},
                new double[]{GROUND_Y + 55.0, trunkTop + 15.0, trunkTop, GROUND_Y + 55.0}, 4);
        g.setStroke(Color.web("#2B241C", 0.70));
        g.setLineWidth(14.0);
        for (int groove = -1; groove <= 1; groove++) {
            double x = centerX + groove * 50.0;
            g.strokeLine(x, trunkTop + 90.0 + Math.abs(groove) * 60.0,
                    x + groove * 24.0, GROUND_Y - 90.0);
        }

        g.setFill(Color.web(index % 2 == 0 ? "#0E4A32" : "#13563A"));
        g.fillOval(centerX - 350.0, crownY - 110.0, 700.0, 285.0);
        g.setFill(Color.web("#1C6C45"));
        g.fillOval(centerX - 250.0, crownY - 210.0, 500.0, 260.0);
        g.fillOval(centerX - 410.0, crownY - 30.0, 400.0, 215.0);
        g.fillOval(centerX + 25.0, crownY - 45.0, 390.0, 220.0);
        g.setFill(Color.web("#4E9960", 0.58));
        g.fillOval(centerX - 205.0, crownY - 170.0, 275.0, 105.0);

        g.setFill(Color.web("#4B2E22"));
        g.fillPolygon(new double[]{centerX - baseHalf, centerX - baseHalf - 255.0,
                        centerX - 38.0, centerX + 38.0,
                        centerX + baseHalf + 255.0, centerX + baseHalf},
                new double[]{GROUND_Y - 25.0, GROUND_Y + 80.0, GROUND_Y + 36.0,
                        GROUND_Y + 36.0, GROUND_Y + 80.0, GROUND_Y - 25.0}, 6);
    }

    private void drawJungleRootFloor(GraphicsContext g) {
        g.setFill(Color.web("#1C2C20"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(Color.web("#37462B"));
        g.fillRect(0, GROUND_Y + 80.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 80.0);
        g.setFill(Color.web("#668A43"));
        g.fillRect(0, GROUND_Y - 22.0, WORLD_WIDTH, 30.0);
        g.setFill(Color.web("#9CCB64", 0.88));
        renderRandom.setSeed(0x71B8_A11EL);
        for (int tuft = 0; tuft < 150; tuft++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double width = 22.0 + renderRandom.nextDouble() * 62.0;
            g.fillOval(x - width * 0.5, GROUND_Y - 34.0 - renderRandom.nextDouble() * 9.0,
                    width, 19.0 + renderRandom.nextDouble() * 11.0);
        }
    }

    private boolean isJungleAerialPlatform(Platform platform) {
        return platform != null && platform.y < GROUND_Y - 55.0
                && platform.w > 105.0 && platform.h < 135.0;
    }

    private void drawJungleBranchSupport(GraphicsContext g, Platform platform, boolean deadwood) {
        double[] anchors = deadwood ? new double[]{1_050.0, 3_000.0, 4_950.0} : JUNGLE_TREE_X;
        double ledgeCenter = platform.x + platform.w * 0.5;
        double anchorX = anchors[0];
        for (double candidate : anchors) {
            if (Math.abs(candidate - ledgeCenter) < Math.abs(anchorX - ledgeCenter)) anchorX = candidate;
        }
        double innerEdge = ledgeCenter < anchorX ? platform.x + platform.w : platform.x;
        double underside = platform.y + platform.h;
        double anchorY = Math.min(GROUND_Y - 90.0,
                underside + 150.0 + Math.abs(innerEdge - anchorX) * 0.10);
        double thickness = Math.clamp(platform.w * 0.10, 28.0, 82.0);
        strokeJungleBranch(g, anchorX, anchorY, innerEdge, underside,
                Color.web(deadwood ? "#211B1C" : "#251D17"), thickness + 20.0);
        strokeJungleBranch(g, anchorX, anchorY, innerEdge, underside,
                Color.web(deadwood ? "#5B4439" : "#5A3825"), thickness);
        strokeJungleBranch(g, anchorX, anchorY - thickness * 0.10,
                innerEdge, underside - thickness * 0.10,
                Color.web(deadwood ? "#9C7960" : "#976342", 0.52),
                Math.max(6.0, thickness * 0.15));

        if (platform.y > GROUND_Y - 380.0) {
            double center = platform.x + platform.w * 0.5;
            double half = Math.clamp(platform.w * 0.27, 48.0, 150.0);
            g.setFill(Color.web(deadwood ? "#3B2B28" : "#443022"));
            g.fillPolygon(new double[]{center - 22.0, center + 22.0,
                            center + half, center - half},
                    new double[]{underside, underside, GROUND_Y + 10.0, GROUND_Y + 10.0}, 4);
        }
    }

    private void strokeJungleBranch(GraphicsContext g, double anchorX, double anchorY,
                                    double edgeX, double edgeY, Color color, double width) {
        double direction = Math.signum(edgeX - anchorX);
        g.setStroke(color);
        g.setLineWidth(width);
        g.beginPath();
        g.moveTo(anchorX, anchorY);
        g.bezierCurveTo(anchorX + direction * Math.abs(edgeX - anchorX) * 0.28, anchorY - 60.0,
                edgeX - direction * Math.abs(edgeX - anchorX) * 0.25, edgeY + 38.0,
                edgeX, edgeY);
        g.stroke();
    }

    private void drawJungleLivingLedge(GraphicsContext g, Platform platform, boolean deadwood) {
        renderRandom.setSeed(Double.doubleToLongBits(
                platform.x * 31.0 + platform.y * 17.0 + platform.w * 13.0));
        double underside = platform.y + platform.h + 12.0;
        double toothA = platform.x + platform.w * (0.24 + renderRandom.nextDouble() * 0.08);
        double toothB = platform.x + platform.w * (0.70 + renderRandom.nextDouble() * 0.08);
        g.setFill(Color.web(deadwood ? "#231B1B" : "#241C17"));
        g.fillPolygon(new double[]{platform.x - 9.0, platform.x + platform.w + 9.0,
                        platform.x + platform.w - 18.0, toothB, toothA, platform.x + 16.0},
                new double[]{platform.y - 4.0, platform.y - 4.0, underside,
                        underside + 38.0, underside + 28.0, underside}, 6);
        g.setFill(Color.web(deadwood ? "#60483B" : "#5E3D27"));
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 24.0, 24.0);
        g.setFill(Color.web(deadwood ? "#91705A" : "#8A5B38", 0.72));
        g.fillRoundRect(platform.x + 11.0, platform.y + 8.0,
                Math.max(20.0, platform.w - 22.0), Math.max(7.0, platform.h * 0.25), 14.0, 14.0);
        g.setFill(Color.web(deadwood ? "#4B3832" : "#3E4F2B"));
        g.fillRoundRect(platform.x - 7.0, platform.y - 13.0,
                platform.w + 14.0, 24.0, 20.0, 20.0);
        g.setStroke(Color.web(deadwood ? "#C6A56E" : "#A9D86D", 0.94));
        g.setLineWidth(6.0);
        g.strokeLine(platform.x + 10.0, platform.y - 10.0,
                platform.x + platform.w - 10.0, platform.y - 10.0);

        int leaves = Math.clamp((int) Math.round(platform.w / 180.0), 1, 5);
        for (int i = 0; i < leaves; i++) {
            double x = platform.x + (i + 1.0) * platform.w / (leaves + 1.0);
            g.setFill(Color.web(deadwood ? "#8A7245" : (i % 2 == 0 ? "#4D8F45" : "#66A953"), 0.86));
            g.fillOval(x - 20.0, platform.y - 34.0 - (i % 2) * 7.0, 40.0, 26.0);
        }
    }

    private void drawJungleUpdraft(GraphicsContext g, WindVent vent,
                                   double time, boolean ambientFx, boolean carrion) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.78 + 0.22 * Math.sin(time * 1.7 + vent.x * 0.014) : 0.86;
        double width = Math.clamp(vent.w * 0.52, 120.0, 240.0);
        double top = vent.y - 280.0;
        double bottom = vent.y + 180.0;
        g.setFill(new LinearGradient(0, 1, 0, 0, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web(carrion ? "#D4C77B" : "#C5F3DB", 0.20 * pulse)),
                new Stop(0.58, Color.web(carrion ? "#8F9F63" : "#8CDECC", 0.10 * pulse)),
                new Stop(1.0, Color.TRANSPARENT)));
        g.fillPolygon(new double[]{centerX - width * 0.30, centerX + width * 0.30,
                        centerX + width * 0.72, centerX - width * 0.72},
                new double[]{top, top, bottom, bottom}, 4);
        g.setStroke(Color.web(carrion ? "#E8D58D" : "#D9FFF0", 0.54 * pulse));
        g.setLineWidth(7.0);
        for (int ribbon = -1; ribbon <= 1; ribbon++) {
            double x = centerX + ribbon * width * 0.22;
            g.strokeArc(x - width * 0.25, top + 60.0 + ribbon * 32.0,
                    width * 0.50, 150.0, ribbon < 0 ? 205.0 : 25.0, 130.0, ArcType.OPEN);
        }
        g.setFill(Color.web(carrion ? "#574634" : "#315B3B"));
        g.fillOval(centerX - width * 0.34, vent.y + 115.0, width * 0.68, 54.0);
        g.setStroke(Color.web(carrion ? "#C6A56E" : "#8ED08A", 0.78));
        g.setLineWidth(8.0);
        g.strokeArc(centerX - width * 0.34, vent.y + 115.0,
                width * 0.68, 54.0, 185.0, 170.0, ArcType.OPEN);
    }

    private void drawJungleNectar(GraphicsContext g, NectarNode node,
                                  double time, boolean ambientFx, boolean carrion) {
        if (!node.active) return;
        double pulse = ambientFx ? 1.0 + Math.sin(time * 2.2 + node.x * 0.02) * 0.10 : 1.0;
        Color outer = carrion ? Color.web("#D6B85C")
                : (node.isSpeed ? Color.web("#FFE477") : Color.web("#8EF1D1"));
        g.setFill(outer.deriveColor(0, 1, 1, 0.20));
        g.fillOval(node.x - 45.0 * pulse, node.y - 45.0 * pulse,
                90.0 * pulse, 90.0 * pulse);
        g.setFill(outer);
        g.fillOval(node.x - 22.0, node.y - 26.0, 44.0, 52.0);
        g.setFill(Color.web("#FFFDE7", 0.82));
        g.fillOval(node.x - 9.0, node.y - 14.0, 16.0, 18.0);
        g.setStroke(Color.web(carrion ? "#6E5731" : "#417D4B"));
        g.setLineWidth(6.0);
        g.strokeLine(node.x, node.y - 25.0, node.x + 12.0, node.y - 47.0);
    }

    private void drawJungleOrchidsAndFireflies(GraphicsContext g, double time, boolean ambientFx) {
        renderRandom.setSeed(0x0AC1_DF11L);
        for (int i = 0; i < 42; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double y = 680.0 + renderRandom.nextDouble() * (GROUND_Y - 780.0);
            double drift = ambientFx ? Math.sin(time * 0.8 + i * 1.7) * 18.0 : 0.0;
            g.setFill(Color.web(i % 3 == 0 ? "#FFF59D" : "#B7FFD4", 0.38 + (i % 4) * 0.08));
            g.fillOval(x + drift, y, 10.0 + (i % 3) * 3.0, 10.0 + (i % 3) * 3.0);
        }
    }

    private void drawCarrionThroneArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#17151F")),
                new Stop(0.48, Color.web("#3B3032")),
                new Stop(0.78, Color.web("#665044")),
                new Stop(1.0, Color.web("#8A6B4A"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);
        g.setFill(Color.web("#E7D7A0", 0.12));
        g.fillOval(4_540.0, 150.0, 760.0, 760.0);
        g.setFill(Color.web("#E9DEB0", 0.78));
        g.fillOval(4_815.0, 425.0, 210.0, 210.0);

        g.setFill(Color.web("#23262A", 0.72));
        for (int i = 0; i < 13; i++) {
            double x = -180.0 + i * 510.0;
            double top = 850.0 + (i % 4) * 125.0;
            g.fillPolygon(new double[]{x, x + 160.0, x + 260.0, x + 410.0},
                    new double[]{GROUND_Y + 120.0, top, top + 250.0, GROUND_Y + 120.0}, 4);
        }
        drawCarrionDeadTree(g, 1_050.0, 0.72, false);
        drawCarrionDeadTree(g, 3_000.0, 1.18, true);
        drawCarrionDeadTree(g, 4_950.0, 0.72, false);
        drawCarrionRootFloor(g);

        for (Platform platform : platforms) {
            if (isJungleAerialPlatform(platform)) drawJungleBranchSupport(g, platform, true);
        }
        drawCarrionBoneThrone(g);
        for (Platform platform : platforms) {
            if (isJungleAerialPlatform(platform)) drawJungleLivingLedge(g, platform, true);
        }
        for (WindVent vent : windVents) drawJungleUpdraft(g, vent, time, ambientFx, true);
        for (NectarNode node : nectarNodes) drawJungleNectar(g, node, time, ambientFx, true);
        drawCarrionSilhouettes(g, time, ambientFx);
    }

    private void drawCarrionDeadTree(GraphicsContext g, double centerX,
                                     double scale, boolean throneTree) {
        double baseY = GROUND_Y + 70.0;
        double topY = throneTree ? 420.0 : 870.0;
        double baseHalf = 235.0 * scale;
        double topHalf = 86.0 * scale;
        g.setFill(Color.web(throneTree ? "#352624" : "#3D2D29"));
        g.fillPolygon(new double[]{centerX - baseHalf, centerX - topHalf,
                        centerX + topHalf, centerX + baseHalf},
                new double[]{baseY, topY, topY, baseY}, 4);
        g.setFill(Color.web("#62483A", 0.66));
        g.fillPolygon(new double[]{centerX - baseHalf * 0.45, centerX - topHalf * 0.46,
                        centerX + topHalf * 0.04, centerX + baseHalf * 0.12},
                new double[]{baseY, topY + 20.0, topY, baseY}, 4);
        g.setStroke(Color.web("#21191A"));
        g.setLineWidth(44.0 * scale);
        double branchY = topY + 190.0;
        g.strokeLine(centerX - topHalf * 0.35, branchY,
                centerX - 340.0 * scale, branchY - 250.0 * scale);
        g.strokeLine(centerX + topHalf * 0.35, branchY + 40.0,
                centerX + 350.0 * scale, branchY - 180.0 * scale);
        g.setStroke(Color.web("#735342"));
        g.setLineWidth(25.0 * scale);
        g.strokeLine(centerX - topHalf * 0.35, branchY,
                centerX - 340.0 * scale, branchY - 250.0 * scale);
        g.strokeLine(centerX + topHalf * 0.35, branchY + 40.0,
                centerX + 350.0 * scale, branchY - 180.0 * scale);
    }

    private void drawCarrionRootFloor(GraphicsContext g) {
        g.setFill(Color.web("#201A1C"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(Color.web("#352B2A"));
        g.fillRect(0, GROUND_Y + 88.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 88.0);
        g.setFill(Color.web("#735A42"));
        g.fillRect(0, GROUND_Y - 20.0, WORLD_WIDTH, 30.0);
        for (double rootX : new double[]{1_050.0, 3_000.0, 4_950.0}) {
            g.setFill(Color.web("#3D2B28"));
            g.fillPolygon(new double[]{rootX - 170.0, rootX - 520.0, rootX - 35.0,
                            rootX + 35.0, rootX + 520.0, rootX + 170.0},
                    new double[]{GROUND_Y - 18.0, GROUND_Y + 105.0, GROUND_Y + 42.0,
                            GROUND_Y + 42.0, GROUND_Y + 105.0, GROUND_Y - 18.0}, 6);
        }
    }

    private void drawCarrionBoneThrone(GraphicsContext g) {
        double centerX = 3_000.0;
        double seatY = GROUND_Y - 1_520.0;
        g.setStroke(Color.web("#D5C59B", 0.82));
        g.setLineWidth(28.0);
        for (int rib = -3; rib <= 3; rib++) {
            double x = centerX + rib * 112.0;
            double height = 430.0 - Math.abs(rib) * 45.0;
            g.strokeArc(x - 105.0, seatY - height, 210.0, height * 1.25,
                    rib <= 0 ? 275.0 : 175.0, 92.0, ArcType.OPEN);
        }
        g.setFill(Color.web("#C8B88B"));
        g.fillPolygon(new double[]{centerX - 190.0, centerX, centerX + 190.0,
                        centerX + 115.0, centerX - 115.0},
                new double[]{seatY - 410.0, seatY - 565.0, seatY - 410.0,
                        seatY - 335.0, seatY - 335.0}, 5);
        g.setFill(Color.web("#2A2020"));
        g.fillOval(centerX - 48.0, seatY - 475.0, 38.0, 52.0);
        g.fillOval(centerX + 10.0, seatY - 475.0, 38.0, 52.0);
    }

    private void drawCarrionSilhouettes(GraphicsContext g, double time, boolean ambientFx) {
        g.setStroke(Color.web("#171820", 0.78));
        g.setLineWidth(11.0);
        for (int i = 0; i < 8; i++) {
            double drift = ambientFx ? (time * (18.0 + i * 1.8)) % (WORLD_WIDTH + 600.0) : 0.0;
            double x = (420.0 + i * 790.0 + drift) % (WORLD_WIDTH + 500.0) - 250.0;
            double y = 430.0 + (i % 4) * 145.0;
            g.strokeArc(x - 42.0, y, 84.0, 36.0, 15.0, 150.0, ArcType.OPEN);
            g.strokeArc(x + 34.0, y, 84.0, 36.0, 15.0, 150.0, ArcType.OPEN);
        }
    }

    private void drawCommandBridgeArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        drawSkyVariantBackdrop(g, "#050B18", "#183653", "#946A58", true, time, ambientFx);

        double bridgeLeft = CROWN_DUEL_BRIDGE_X;
        double bridgeRight = bridgeLeft + CROWN_DUEL_BRIDGE_W;
        double bridgeY = CROWN_DUEL_BRIDGE_Y;
        double centerX = (bridgeLeft + bridgeRight) * 0.5;

        // The command bridge is suspended between two inhabited stone pylons.
        // Both towers continue below the cloud line, so the arena reads as a
        // real piece of Crown infrastructure rather than four floating bars.
        drawCommandBridgePylon(g, bridgeLeft - 150.0, bridgeY - 1_040.0, bridgeY + 1_060.0, false);
        drawCommandBridgePylon(g, bridgeRight + 150.0, bridgeY - 1_040.0, bridgeY + 1_060.0, true);

        g.setStroke(Color.web("#111B26"));
        g.setLineWidth(34.0);
        g.strokeLine(bridgeLeft - 105.0, bridgeY - 780.0, centerX, bridgeY - 560.0);
        g.strokeLine(bridgeRight + 105.0, bridgeY - 780.0, centerX, bridgeY - 560.0);
        g.setStroke(Color.web("#6D8290", 0.82));
        g.setLineWidth(12.0);
        g.strokeLine(bridgeLeft - 105.0, bridgeY - 780.0, centerX, bridgeY - 560.0);
        g.strokeLine(bridgeRight + 105.0, bridgeY - 780.0, centerX, bridgeY - 560.0);

        for (Platform p : platforms) {
            drawCommandBridgePlatformSupport(g, p, bridgeLeft, bridgeRight, bridgeY);
        }
        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#85E8FF"), Color.web("#152C3B"));
        }
        for (Platform p : platforms) {
            drawCommandBridgePlatform(g, p, p == platforms.getFirst(), time, ambientFx);
        }

        // A sealed transport carriage below the bridge makes its purpose and
        // scale clear without becoming misleading collision geometry.
        double carriageY = bridgeY + 470.0;
        g.setStroke(Color.web("#26394A"));
        g.setLineWidth(18.0);
        g.strokeLine(bridgeLeft + 350.0, bridgeY + 55.0, centerX - 510.0, carriageY);
        g.strokeLine(bridgeRight - 350.0, bridgeY + 55.0, centerX + 510.0, carriageY);
        g.setFill(Color.web("#0D1825"));
        g.fillRoundRect(centerX - 570.0, carriageY, 1_140.0, 230.0, 92.0, 92.0);
        g.setStroke(Color.web("#7597AA", 0.74));
        g.setLineWidth(11.0);
        g.strokeRoundRect(centerX - 570.0, carriageY, 1_140.0, 230.0, 92.0, 92.0);
        g.setFill(Color.web("#B9E7F5", 0.58));
        for (int i = 0; i < 6; i++) {
            g.fillRoundRect(centerX - 455.0 + i * 158.0, carriageY + 70.0,
                    86.0, 54.0, 18.0, 18.0);
        }

        double pulse = ambientFx ? 0.72 + 0.20 * Math.sin(time * 2.1) : 0.82;
        g.setStroke(Color.web("#FFE36B", pulse));
        g.setLineWidth(13.0);
        g.strokeOval(centerX - 116.0, bridgeY - 152.0, 232.0, 232.0);
        g.strokeLine(centerX, bridgeY - 205.0, centerX, bridgeY + 115.0);
        g.strokeLine(centerX - 145.0, bridgeY - 35.0, centerX + 145.0, bridgeY - 35.0);
    }

    private void drawCommandBridgePylon(GraphicsContext g, double centerX,
                                         double topY, double bottomY, boolean mirror) {
        double direction = mirror ? -1.0 : 1.0;
        g.setFill(Color.web("#101A25"));
        g.fillPolygon(new double[]{centerX - 150.0, centerX - 105.0, centerX + 105.0, centerX + 150.0},
                new double[]{bottomY, topY + 120.0, topY + 120.0, bottomY}, 4);
        g.setFill(Color.web("#263746"));
        g.fillPolygon(new double[]{centerX - 84.0, centerX - 55.0, centerX + 10.0, centerX + 36.0},
                new double[]{bottomY, topY + 165.0, topY + 165.0, bottomY}, 4);
        g.setFill(Color.web("#0A121D"));
        g.fillPolygon(new double[]{centerX - 170.0, centerX, centerX + 170.0},
                new double[]{topY + 150.0, topY, topY + 150.0}, 3);
        g.setStroke(Color.web("#7494A7", 0.72));
        g.setLineWidth(10.0);
        for (double y = topY + 260.0; y < bottomY - 100.0; y += 230.0) {
            g.strokeLine(centerX - 92.0, y, centerX + 92.0, y);
        }
        g.setStroke(Color.web("#253A4A", 0.92));
        g.setLineWidth(24.0);
        g.strokeLine(centerX + direction * 90.0, topY + 330.0,
                centerX + direction * 360.0, topY + 560.0);
    }

    private void drawCommandBridgePlatformSupport(GraphicsContext g, Platform p,
                                                   double bridgeLeft, double bridgeRight,
                                                   double bridgeY) {
        double centerX = p.x + p.w * 0.5;
        double underside = p.y + p.h;
        if (p.y >= bridgeY - 20.0 && p.w > 1_000.0) {
            g.setFill(Color.web("#101A25"));
            g.fillPolygon(new double[]{p.x + 80.0, p.x + p.w - 80.0,
                            p.x + p.w - 420.0, p.x + 420.0},
                    new double[]{underside, underside, underside + 250.0, underside + 250.0}, 4);
            g.setStroke(Color.web("#526B7B", 0.72));
            g.setLineWidth(14.0);
            for (double x = p.x + 210.0; x < p.x + p.w - 160.0; x += 280.0) {
                g.strokeLine(x, underside + 10.0, x + 120.0, underside + 205.0);
                g.strokeLine(x + 120.0, underside + 205.0, x + 240.0, underside + 10.0);
            }
            return;
        }
        double anchorX = centerX < (bridgeLeft + bridgeRight) * 0.5 ? bridgeLeft - 70.0 : bridgeRight + 70.0;
        double anchorY = Math.max(p.y + 170.0, bridgeY - 70.0);
        g.setStroke(Color.web("#101A25"));
        g.setLineWidth(34.0);
        g.strokeLine(anchorX, anchorY, centerX, underside);
        g.setStroke(Color.web("#506878"));
        g.setLineWidth(15.0);
        g.strokeLine(anchorX, anchorY, centerX, underside);
    }

    private void drawCommandBridgePlatform(GraphicsContext g, Platform p, boolean main,
                                           double time, boolean ambientFx) {
        double pulse = ambientFx ? 0.68 + 0.18 * Math.sin(time * 2.4 + p.x * 0.01) : 0.78;
        g.setFill(Color.web(main ? "#142536" : "#172B3C"));
        g.fillRoundRect(p.x, p.y, p.w, p.h, 18.0, 18.0);
        g.setFill(Color.web("#405868", 0.82));
        g.fillRoundRect(p.x + 12.0, p.y + 9.0, p.w - 24.0,
                Math.max(8.0, p.h * 0.27), 12.0, 12.0);
        g.setStroke(Color.web("#8199A7", 0.92));
        g.setLineWidth(main ? 10.0 : 7.0);
        g.strokeRoundRect(p.x, p.y, p.w, p.h, 18.0, 18.0);
        g.setStroke(Color.web("#69D9F0", pulse));
        g.setLineWidth(5.0);
        g.strokeLine(p.x + 24.0, p.y + 6.0, p.x + p.w - 24.0, p.y + 6.0);
    }

    private void drawSkybreakSpiresArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        drawSkyVariantBackdrop(g, "#07101E", "#294B68", "#8BA4A9", false, time, ambientFx);
        drawSkybreakDistantNeedles(g);

        for (Platform p : platforms) {
            if (isSkyVariantPlayablePlatform(p)) {
                double anchor = nearestAnchor(p.x + p.w * 0.5, 720.0, 3_000.0, 5_060.0);
                drawSkyVariantRockSupport(g, p, anchor,
                        Color.web("#17242D"), Color.web("#344B58"), true);
            }
        }
        drawSkyVariantGround(g, Color.web("#111D25"), Color.web("#263944"), Color.web("#9EB6B2"));
        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#9EEBFF"), Color.web("#102A38"));
        }
        for (Platform p : platforms) {
            if (isSkyVariantPlayablePlatform(p)) {
                drawSkyVariantRockPlatform(g, p, Color.web("#334B58"),
                        Color.web("#6F8790"), Color.web("#C5D9D4"));
            }
        }
    }

    private void drawSkybreakDistantNeedles(GraphicsContext g) {
        g.setFill(Color.web("#132D40", 0.72));
        for (double x : new double[]{180.0, 1_420.0, 2_090.0, 3_900.0, 4_520.0, 5_720.0}) {
            double peak = 350.0 + (x % 700.0) * 0.35;
            g.fillPolygon(new double[]{x - 320.0, x, x + 320.0},
                    new double[]{GROUND_Y + 40.0, peak, GROUND_Y + 40.0}, 3);
            g.setStroke(Color.web("#9ECBD7", 0.30));
            g.setLineWidth(10.0);
            g.strokeLine(x, peak + 80.0, x - 105.0, peak + 300.0);
        }
    }

    private void drawPeregrineRunArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        drawSkyVariantBackdrop(g, "#17253B", "#B56558", "#F2C27F", false, time, ambientFx);

        g.setFill(Color.web("#8A4E45", 0.48));
        g.fillPolygon(new double[]{0.0, 0.0, 950.0, 1_720.0, 2_420.0, 3_040.0,
                        3_760.0, 4_520.0, 5_250.0, WORLD_WIDTH, WORLD_WIDTH},
                new double[]{GROUND_Y + 260.0, 1_980.0, 1_230.0, 1_940.0, 1_050.0,
                        1_860.0, 980.0, 1_900.0, 1_180.0, 1_900.0, GROUND_Y + 260.0}, 11);

        for (Platform p : platforms) {
            double anchor = nearestAnchor(p.x + p.w * 0.5, 930.0, 3_000.0, 4_990.0);
            drawSkyVariantRockSupport(g, p, anchor,
                    Color.web("#3A2730"), Color.web("#765044"), false);
        }
        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#FFE3A7"), Color.web("#4D3030"));
        }
        for (Platform p : platforms) {
            drawSkyVariantRockPlatform(g, p, Color.web("#765044"),
                    Color.web("#B37B5D"), Color.web("#F4D19A"));
        }
        drawPeregrineRouteMarkers(g, time, ambientFx);
    }

    private void drawPeregrineRouteMarkers(GraphicsContext g, double time, boolean ambientFx) {
        double drift = ambientFx ? Math.sin(time * 1.3) * 12.0 : 0.0;
        g.setStroke(Color.web("#FFE8B0", 0.46));
        g.setLineWidth(12.0);
        double[][] route = {{520, 1_340}, {1_580, 1_010}, {2_160, 690},
                {3_010, 1_020}, {3_820, 650}, {4_650, 1_050}, {5_480, 1_420}};
        for (int i = 0; i < route.length - 1; i++) {
            g.strokeLine(route[i][0], route[i][1] + drift,
                    route[i + 1][0], route[i + 1][1] - drift);
        }
        g.setFill(Color.web("#FFF1C8", 0.82));
        for (double[] point : route) {
            g.fillPolygon(new double[]{point[0] - 26.0, point[0] + 30.0, point[0] - 26.0},
                    new double[]{point[1] - 18.0, point[1], point[1] + 18.0}, 3);
        }
    }

    private void drawTempestSummitArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        drawSkyVariantBackdrop(g, "#030711", "#17283C", "#565C69", true, time, ambientFx);

        // A single colossal storm crown supports the central summit while two
        // lower peaks form the recovery islands on either side.
        drawTempestMountain(g, 970.0, 700.0, GROUND_Y + 920.0, 850.0);
        drawTempestMountain(g, 3_000.0, 360.0, GROUND_Y + 1_150.0, 1_350.0);
        drawTempestMountain(g, 5_050.0, 690.0, GROUND_Y + 920.0, 850.0);

        for (Platform p : platforms) {
            double anchor = nearestAnchor(p.x + p.w * 0.5, 970.0, 3_000.0, 5_050.0);
            drawSkyVariantRockSupport(g, p, anchor,
                    Color.web("#121A25"), Color.web("#303B49"), false);
        }
        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#C5E9FF"), Color.web("#121E2B"));
        }
        for (Platform p : platforms) {
            drawSkyVariantRockPlatform(g, p, Color.web("#303B49"),
                    Color.web("#586777"), Color.web("#E1B85B"));
        }
        drawTempestLightningRods(g, time, ambientFx);
    }

    private void drawTempestMountain(GraphicsContext g, double centerX, double peakY,
                                     double baseY, double halfWidth) {
        g.setFill(Color.web("#111923"));
        g.fillPolygon(new double[]{centerX - halfWidth, centerX - halfWidth * 0.44,
                        centerX, centerX + halfWidth * 0.48, centerX + halfWidth},
                new double[]{baseY, peakY + 610.0, peakY, peakY + 570.0, baseY}, 5);
        g.setFill(Color.web("#334150", 0.72));
        g.fillPolygon(new double[]{centerX - halfWidth * 0.48, centerX,
                        centerX + halfWidth * 0.08, centerX - halfWidth * 0.18},
                new double[]{baseY, peakY, baseY, baseY}, 4);
        g.setStroke(Color.web("#82919B", 0.32));
        g.setLineWidth(13.0);
        g.strokeLine(centerX, peakY + 70.0, centerX - halfWidth * 0.22, peakY + 520.0);
    }

    private void drawTempestLightningRods(GraphicsContext g, double time, boolean ambientFx) {
        double pulse = ambientFx ? 0.58 + 0.28 * Math.sin(time * 3.2) : 0.72;
        for (double x : new double[]{970.0, 3_000.0, 5_050.0}) {
            double baseY = x == 3_000.0 ? 1_030.0 : 1_320.0;
            g.setStroke(Color.web("#111821"));
            g.setLineWidth(24.0);
            g.strokeLine(x, baseY, x, baseY - 300.0);
            g.setStroke(Color.web("#DDB557", 0.88));
            g.setLineWidth(8.0);
            g.strokeLine(x, baseY, x, baseY - 300.0);
            g.setFill(Color.web("#FFE37B", pulse * 0.34));
            g.fillOval(x - 55.0, baseY - 355.0, 110.0, 110.0);
            g.setFill(Color.web("#FFF2AE", pulse));
            g.fillOval(x - 14.0, baseY - 314.0, 28.0, 28.0);
        }
    }

    private void drawSkyVariantBackdrop(GraphicsContext g, String topColor,
                                        String middleColor, String horizonColor,
                                        boolean storm, double time, boolean ambientFx) {
        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web(topColor)),
                new Stop(0.58, Color.web(middleColor)),
                new Stop(1.0, Color.web(horizonColor))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        if (!storm) {
            g.setFill(Color.web("#FFF1B8", 0.18));
            g.fillOval(2_520.0, 180.0, 960.0, 960.0);
            g.setFill(Color.web("#FFF4CB", 0.76));
            g.fillOval(2_850.0, 510.0, 300.0, 300.0);
        }

        renderRandom.setSeed(storm ? 0x57A1_0FFEL : 0x5CA1_EA5EL);
        for (int i = 0; i < 17; i++) {
            double drift = ambientFx ? Math.sin(time * 0.12 + i * 0.91) * 38.0 : 0.0;
            double x = -480.0 + i * 410.0 + drift;
            double y = 1_620.0 + (i % 4) * 120.0;
            double width = 620.0 + renderRandom.nextDouble() * 280.0;
            g.setFill(storm ? Color.web("#AAB7C1", 0.24) : Color.web("#F4F3E8", 0.38));
            g.fillOval(x, y, width, 280.0);
            g.fillOval(x + width * 0.22, y - 75.0, width * 0.62, 250.0);
        }
        if (storm) {
            g.setFill(Color.web("#111827", 0.42));
            for (int i = 0; i < 8; i++) {
                double x = -240.0 + i * 840.0;
                double y = 260.0 + (i % 3) * 170.0;
                g.fillOval(x, y, 1_050.0, 310.0);
            }
        }
    }

    private boolean isSkyVariantPlayablePlatform(Platform p) {
        return p != null && p.w > 120.0 && p.h < 180.0
                && p.x >= -20.0 && p.x + p.w <= WORLD_WIDTH + 20.0;
    }

    private double nearestAnchor(double value, double... anchors) {
        double nearest = anchors[0];
        for (double anchor : anchors) {
            if (Math.abs(anchor - value) < Math.abs(nearest - value)) nearest = anchor;
        }
        return nearest;
    }

    private void drawSkyVariantRockSupport(GraphicsContext g, Platform p, double anchorX,
                                           Color shadow, Color light, boolean toGround) {
        double centerX = p.x + p.w * 0.5;
        double underside = p.y + p.h;
        double baseY = toGround ? GROUND_Y + 130.0 : Math.max(GROUND_Y + 780.0, underside + 760.0);
        double topHalf = Math.max(44.0, Math.min(p.w * 0.38, 260.0));
        double baseHalf = Math.max(topHalf + 90.0, Math.min(p.w * 0.72, 560.0));
        double baseCenter = centerX + (anchorX - centerX) * 0.32;
        g.setFill(shadow);
        g.fillPolygon(new double[]{centerX - topHalf, centerX + topHalf,
                        baseCenter + baseHalf, baseCenter - baseHalf},
                new double[]{underside - 2.0, underside - 2.0, baseY, baseY}, 4);
        g.setFill(light.deriveColor(0, 1, 1, 0.68));
        g.fillPolygon(new double[]{centerX - topHalf * 0.82, centerX - topHalf * 0.08,
                        baseCenter + baseHalf * 0.04, baseCenter - baseHalf * 0.58},
                new double[]{underside + 8.0, underside + 8.0, baseY, baseY}, 4);
        g.setStroke(light.deriveColor(0, 0.72, 1.28, 0.28));
        g.setLineWidth(9.0);
        for (double y = underside + 150.0; y < baseY - 70.0; y += 260.0) {
            double ratio = (y - underside) / Math.max(1.0, baseY - underside);
            double x = centerX + (baseCenter - centerX) * ratio;
            double half = topHalf + (baseHalf - topHalf) * ratio;
            g.strokeLine(x - half * 0.64, y, x + half * 0.38, y + 20.0);
        }
    }

    private void drawSkyVariantRockPlatform(GraphicsContext g, Platform p,
                                            Color body, Color highlight, Color edge) {
        g.setFill(body);
        g.fillRoundRect(p.x, p.y, p.w, p.h, 18.0, 18.0);
        g.setFill(highlight.deriveColor(0, 1, 1, 0.70));
        g.fillRoundRect(p.x + 12.0, p.y + 8.0, Math.max(12.0, p.w - 24.0),
                Math.max(7.0, p.h * 0.28), 12.0, 12.0);
        g.setStroke(body.darker());
        g.setLineWidth(9.0);
        g.strokeRoundRect(p.x, p.y, p.w, p.h, 18.0, 18.0);
        g.setStroke(edge.deriveColor(0, 1, 1, 0.92));
        g.setLineWidth(6.0);
        g.strokeLine(p.x + 12.0, p.y - 3.0, p.x + p.w - 12.0, p.y - 3.0);

        if (p.signText != null && !p.signText.isBlank() && p.w > 700.0) {
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, Math.min(34.0, p.w / 30.0)));
            g.setTextAlign(TextAlignment.CENTER);
            g.setFill(edge.deriveColor(0, 0.55, 1.05, 0.82));
            g.fillText(p.signText, p.x + p.w * 0.5, p.y + p.h * 0.72);
            g.setTextAlign(TextAlignment.LEFT);
        }
    }

    private void drawSkyVariantGround(GraphicsContext g, Color shadow, Color body, Color edge) {
        g.setFill(shadow);
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(body);
        g.fillRect(0, GROUND_Y + 88.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 88.0);
        g.setStroke(body.brighter().deriveColor(0, 0.72, 1.10, 0.42));
        g.setLineWidth(14.0);
        for (double x = -120.0; x < WORLD_WIDTH; x += 390.0) {
            g.strokeLine(x, GROUND_Y + 90.0, x + 220.0, GROUND_Y + 275.0);
        }
        g.setFill(body.brighter());
        g.fillRect(0, GROUND_Y - 18.0, WORLD_WIDTH, 70.0);
        g.setFill(edge);
        g.fillRect(0, GROUND_Y - 18.0, WORLD_WIDTH, 14.0);
    }

    private void drawSkyVariantWindChannel(GraphicsContext g, WindVent vent,
                                           double time, boolean ambientFx,
                                           Color accent, Color base) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.68 + 0.24 * Math.sin(time * 1.8 + vent.x * 0.01) : 0.78;
        double width = Math.clamp(vent.w * 0.46, 100.0, 240.0);
        double top = vent.y - 280.0;
        double bottom = vent.y + 205.0;
        g.setFill(new LinearGradient(0, 1, 0, 0, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, accent.deriveColor(0, 1, 1, 0.20 * pulse)),
                new Stop(0.55, accent.deriveColor(0, 1, 1, 0.08 * pulse)),
                new Stop(1.0, Color.TRANSPARENT)));
        g.fillPolygon(new double[]{centerX - width * 0.32, centerX + width * 0.32,
                        centerX + width * 0.72, centerX - width * 0.72},
                new double[]{top, top, bottom, bottom}, 4);
        g.setStroke(accent.deriveColor(0, 0.75, 1.18, 0.60 * pulse));
        g.setLineWidth(7.0);
        for (int ribbon = -1; ribbon <= 1; ribbon++) {
            double x = centerX + ribbon * width * 0.24;
            g.strokeArc(x - width * 0.30, top + 75.0 + ribbon * 24.0,
                    width * 0.60, 150.0, ribbon < 0 ? 205.0 : 25.0, 130.0, ArcType.OPEN);
            g.strokeArc(x - width * 0.30, top + 270.0 - ribbon * 18.0,
                    width * 0.60, 150.0, ribbon < 0 ? 25.0 : 205.0, 130.0, ArcType.OPEN);
        }
        g.setFill(base);
        g.fillOval(centerX - width * 0.58, bottom - 47.0, width * 1.16, 72.0);
        g.setStroke(accent.deriveColor(0, 1, 1, 0.72 * pulse));
        g.setLineWidth(8.0);
        g.strokeArc(centerX - width * 0.49, bottom - 40.0,
                width * 0.98, 56.0, 5.0, 170.0, ArcType.OPEN);
    }

    private void drawSkyCliffsArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;

        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#0C3153")),
                new Stop(0.48, Color.web("#5C9FC1")),
                new Stop(0.78, Color.web("#C5D8D2")),
                new Stop(1.0, Color.web("#E8C98E"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        drawSkyCliffsSun(g);
        drawSkyCliffsDistantRanges(g);
        drawSkyCliffsCloudSea(g, time, ambientFx);
        drawSkyCliffsSpires(g);
        drawSkyCliffsPlateau(g);

        for (Platform platform : platforms) {
            if (isSkyCliffsAerialPlatform(platform)) drawSkyCliffsLedgeSupport(g, platform);
        }
        for (WindVent vent : windVents) drawSkyCliffsWindChannel(g, vent, time, ambientFx);
        for (Platform platform : platforms) {
            if (isSkyCliffsAerialPlatform(platform)) drawSkyCliffsRockLedge(g, platform);
        }
        if (ambientFx) drawSkyCliffsDistantBirds(g, time);
    }

    private void drawSkyCliffsSun(GraphicsContext g) {
        double x = 3_040.0;
        double y = 500.0;
        g.setFill(Color.web("#FFF2B2", 0.12));
        g.fillOval(x - 430.0, y - 430.0, 860.0, 860.0);
        g.setFill(Color.web("#FFF5C7", 0.86));
        g.fillOval(x - 126.0, y - 126.0, 252.0, 252.0);
    }

    private void drawSkyCliffsDistantRanges(GraphicsContext g) {
        double[] farX = {-300.0, 380.0, 980.0, 1_620.0, 2_260.0, 2_920.0,
                3_540.0, 4_160.0, 4_820.0, 5_480.0, 6_240.0};
        double[] farPeak = {1_940.0, 1_020.0, 1_580.0, 880.0, 1_480.0, 760.0,
                1_420.0, 930.0, 1_550.0, 840.0, 1_930.0};
        double[] farY = new double[farX.length];
        for (int i = 0; i < farY.length; i++) farY[i] = farPeak[i];
        g.setFill(Color.web("#345F73", 0.58));
        g.fillPolygon(farX, farY, farX.length);
        g.fillRect(-300.0, 1_930.0, WORLD_WIDTH + 600.0, 720.0);

        double[] midX = {-300.0, 260.0, 790.0, 1_310.0, 1_860.0, 2_420.0,
                2_980.0, 3_520.0, 4_080.0, 4_650.0, 5_210.0, 5_760.0, 6_300.0};
        double[] midY = {2_120.0, 1_400.0, 2_030.0, 1_210.0, 1_940.0, 1_280.0,
                2_060.0, 1_170.0, 1_950.0, 1_340.0, 2_010.0, 1_260.0, 2_130.0};
        g.setFill(Color.web("#284958", 0.72));
        g.fillPolygon(midX, midY, midX.length);
        g.fillRect(-300.0, 2_080.0, WORLD_WIDTH + 600.0, 560.0);

        g.setStroke(Color.web("#E6F4F2", 0.40));
        g.setLineWidth(18.0);
        for (int i = 1; i < midX.length - 1; i += 2) {
            double peakX = midX[i];
            double peakY = midY[i];
            g.strokePolyline(new double[]{peakX - 125.0, peakX, peakX + 140.0},
                    new double[]{peakY + 170.0, peakY, peakY + 190.0}, 3);
        }
    }

    private void drawSkyCliffsCloudSea(GraphicsContext g, double time, boolean ambientFx) {
        g.setFill(Color.web("#EAF5F4", 0.64));
        for (int i = 0; i < 15; i++) {
            double drift = ambientFx ? Math.sin(time * 0.08 + i * 1.1) * 34.0 : 0.0;
            double x = -420.0 + i * 470.0 + drift;
            double y = 1_850.0 + (i % 3) * 105.0;
            double width = 660.0 + (i % 4) * 90.0;
            g.fillOval(x, y, width, 290.0);
            g.fillOval(x + width * 0.28, y - 85.0, width * 0.56, 260.0);
        }
        g.setFill(Color.web("#F5FBF8", 0.42));
        g.fillRect(0, 2_060.0, WORLD_WIDTH, 390.0);
    }

    private void drawSkyCliffsSpires(GraphicsContext g) {
        double[] centers = {600.0, 1_600.0, 2_600.0, 3_600.0, 4_600.0, 5_400.0};
        for (int i = 0; i < centers.length; i++) drawSkyCliffsSpire(g, centers[i], i);
    }

    private void drawSkyCliffsSpire(GraphicsContext g, double centerX, int index) {
        double summitY = 770.0 + (index % 2) * 90.0 + (index == 5 ? 80.0 : 0.0);
        double shoulderY = 1_310.0 + (index % 3) * 95.0;
        double baseY = GROUND_Y + 130.0;
        double baseHalf = 390.0 + (index % 2) * 70.0;
        double midHalf = 245.0 + (index % 3) * 28.0;
        double summitHalf = 118.0 + (index % 2) * 22.0;

        g.setFill(Color.web(index % 2 == 0 ? "#293843" : "#303C45"));
        g.fillPolygon(new double[]{centerX - baseHalf, centerX - midHalf,
                        centerX - summitHalf, centerX + summitHalf,
                        centerX + midHalf, centerX + baseHalf},
                new double[]{baseY, shoulderY, summitY, summitY,
                        shoulderY, baseY}, 6);
        // An uneven crown keeps the six authored climbing towers natural even
        // though their gameplay shelves repeat at deliberate intervals.
        g.fillPolygon(new double[]{centerX - summitHalf, centerX - summitHalf * 0.64,
                        centerX - summitHalf * 0.22, centerX + summitHalf * 0.08,
                        centerX + summitHalf * 0.46, centerX + summitHalf},
                new double[]{summitY + 38.0, summitY - 34.0 - (index % 2) * 22.0,
                        summitY - 138.0 + (index % 3) * 16.0,
                        summitY - 82.0 - (index % 2) * 24.0,
                        summitY - 16.0, summitY + 44.0}, 6);
        g.setFill(Color.web("#52616A", 0.72));
        g.fillPolygon(new double[]{centerX - baseHalf * 0.56, centerX - midHalf * 0.58,
                        centerX - summitHalf * 0.50, centerX + summitHalf * 0.04,
                        centerX + midHalf * 0.10, centerX + baseHalf * 0.12},
                new double[]{baseY, shoulderY + 80.0, summitY + 28.0, summitY,
                        shoulderY + 30.0, baseY}, 6);
        g.fillPolygon(new double[]{centerX - summitHalf * 0.46, centerX - summitHalf * 0.22,
                        centerX + summitHalf * 0.02, centerX + summitHalf * 0.18},
                new double[]{summitY + 24.0, summitY - 118.0 + (index % 3) * 16.0,
                        summitY - 74.0, summitY + 18.0}, 4);
        g.setFill(Color.web("#182832", 0.66));
        g.fillPolygon(new double[]{centerX + summitHalf * 0.12, centerX + summitHalf,
                        centerX + midHalf, centerX + baseHalf, centerX + baseHalf * 0.22,
                        centerX + midHalf * 0.24},
                new double[]{summitY + 8.0, summitY, shoulderY, baseY, baseY,
                        shoulderY + 70.0}, 6);

        g.setStroke(Color.web("#9DA9A8", 0.38));
        g.setLineWidth(10.0);
        for (int band = 0; band < 5; band++) {
            double y = summitY + 250.0 + band * 285.0;
            double half = summitHalf + (y - summitY) / (baseY - summitY) * (baseHalf - summitHalf);
            g.strokeLine(centerX - half * 0.72, y, centerX + half * 0.58, y + 18.0);
        }
    }

    private void drawSkyCliffsPlateau(GraphicsContext g) {
        g.setFill(Color.web("#222F37"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(Color.web("#34444C"));
        g.fillRect(0, GROUND_Y + 105.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 105.0);
        g.setStroke(Color.web("#69767A", 0.52));
        g.setLineWidth(13.0);
        for (double x = -120.0; x < WORLD_WIDTH; x += 350.0) {
            g.strokeLine(x, GROUND_Y + 90.0, x + 160.0, GROUND_Y + 270.0);
        }
        g.setFill(Color.web("#4B5C61"));
        g.fillRect(0, GROUND_Y - 20.0, WORLD_WIDTH, 78.0);
        g.setFill(Color.web("#C1C79B"));
        g.fillRect(0, GROUND_Y - 20.0, WORLD_WIDTH, 15.0);
        g.setFill(Color.web("#D9D6A0", 0.68));
        renderRandom.setSeed(0x5A7C_11FFL);
        for (int i = 0; i < 120; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double width = 30.0 + renderRandom.nextDouble() * 50.0;
            g.fillOval(x - width * 0.5, GROUND_Y - 30.0 - renderRandom.nextDouble() * 10.0,
                    width, 18.0 + renderRandom.nextDouble() * 12.0);
        }
    }

    private boolean isSkyCliffsAerialPlatform(Platform platform) {
        return platform != null
                && platform.y < GROUND_Y - 55.0
                && platform.w > 120.0
                && platform.h < 130.0;
    }

    private void drawSkyCliffsLedgeSupport(GraphicsContext g, Platform platform) {
        double[] centers = {600.0, 1_600.0, 2_600.0, 3_600.0, 4_600.0, 5_400.0};
        double ledgeCenter = platform.x + platform.w * 0.5;
        double anchorX = centers[0];
        for (double candidate : centers) {
            if (Math.abs(candidate - ledgeCenter) < Math.abs(anchorX - ledgeCenter)) anchorX = candidate;
        }
        double innerEdge = ledgeCenter < anchorX ? platform.x + platform.w : platform.x;
        double spireEdge = anchorX + Math.copySign(128.0, ledgeCenter - anchorX);
        double underside = platform.y + platform.h;
        double braceY = Math.min(GROUND_Y - 70.0,
                platform.y + 160.0 + Math.abs(innerEdge - spireEdge) * 0.13);
        double thickness = Math.clamp(platform.w * 0.12, 34.0, 86.0);

        g.setStroke(Color.web("#17242B", 0.92));
        g.setLineWidth(thickness + 22.0);
        g.strokeLine(spireEdge, braceY, innerEdge, underside);
        g.setStroke(Color.web("#3A4A51"));
        g.setLineWidth(thickness);
        g.strokeLine(spireEdge, braceY, innerEdge, underside);
        g.setStroke(Color.web("#829094", 0.42));
        g.setLineWidth(Math.max(7.0, thickness * 0.18));
        g.strokeLine(spireEdge, braceY - thickness * 0.13, innerEdge, underside - thickness * 0.13);

        if (platform.y > GROUND_Y - 330.0) {
            double center = platform.x + platform.w * 0.5;
            double half = Math.clamp(platform.w * 0.28, 56.0, 150.0);
            g.setFill(Color.web("#2A3940"));
            g.fillPolygon(new double[]{center - 24.0, center + 24.0, center + half, center - half},
                    new double[]{underside, underside, GROUND_Y + 12.0, GROUND_Y + 12.0}, 4);
        }
    }

    private void drawSkyCliffsRockLedge(GraphicsContext g, Platform platform) {
        renderRandom.setSeed(Double.doubleToLongBits(platform.x * 23.0 + platform.y * 19.0 + platform.w * 7.0));
        double underside = platform.y + platform.h + 13.0;
        double toothA = platform.x + platform.w * (0.24 + renderRandom.nextDouble() * 0.08);
        double toothB = platform.x + platform.w * (0.68 + renderRandom.nextDouble() * 0.10);

        g.setFill(Color.web("#17242B"));
        g.fillPolygon(new double[]{platform.x - 10.0, platform.x + platform.w + 10.0,
                        platform.x + platform.w - 18.0, toothB, toothA, platform.x + 14.0},
                new double[]{platform.y - 5.0, platform.y - 5.0, underside,
                        underside + 40.0, underside + 29.0, underside}, 6);
        g.setFill(Color.web("#44545B"));
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 18.0, 18.0);
        g.setFill(Color.web("#6B797D", 0.78));
        g.fillRoundRect(platform.x + 12.0, platform.y + 8.0,
                Math.max(18.0, platform.w - 24.0), Math.max(7.0, platform.h * 0.28), 13.0, 13.0);

        g.setFill(Color.web("#35464B"));
        g.fillRoundRect(platform.x - 6.0, platform.y - 12.0, platform.w + 12.0, 21.0, 18.0, 18.0);
        Color edge = platform.y < GROUND_Y - 1_200.0 ? Color.web("#E8D58D") : Color.web("#D8E1DC");
        g.setStroke(edge.deriveColor(0, 1, 1, 0.92));
        g.setLineWidth(5.0);
        g.strokeLine(platform.x + 10.0, platform.y - 9.0,
                platform.x + platform.w - 10.0, platform.y - 9.0);

        int grassCount = Math.clamp((int) Math.round(platform.w / 190.0), 1, 4);
        g.setStroke(Color.web("#C9C48D", 0.72));
        g.setLineWidth(4.0);
        for (int i = 0; i < grassCount; i++) {
            double x = platform.x + (i + 1.0) * platform.w / (grassCount + 1.0);
            double lean = i % 2 == 0 ? -8.0 : 9.0;
            g.strokeLine(x, platform.y - 8.0, x + lean, platform.y - 35.0);
        }

        g.setStroke(Color.web("#202E34", 0.86));
        g.setLineWidth(4.0);
        for (int seam = 0; seam < Math.clamp((int) (platform.w / 230.0), 1, 4); seam++) {
            double x = platform.x + (seam + 1.0) * platform.w
                    / (Math.clamp((int) (platform.w / 230.0), 1, 4) + 1.0);
            g.strokeLine(x - 15.0, platform.y + platform.h * 0.45,
                    x + 10.0, platform.y + platform.h + 10.0);
        }
    }

    private void drawSkyCliffsWindChannel(GraphicsContext g, WindVent vent,
                                          double time, boolean ambientFx) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.74 + 0.26 * Math.sin(time * 1.9 + vent.x * 0.011) : 0.84;
        double width = Math.clamp(vent.w * 0.42, 92.0, 210.0);
        double top = vent.y - 260.0;
        double bottom = vent.y + 230.0;
        g.setFill(new LinearGradient(0, 1, 0, 0, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#DDF8FF", 0.17 * pulse)),
                new Stop(0.55, Color.web("#A8E3F0", 0.08 * pulse)),
                new Stop(1.0, Color.TRANSPARENT)));
        g.fillPolygon(new double[]{centerX - width * 0.32, centerX + width * 0.32,
                        centerX + width * 0.70, centerX - width * 0.70},
                new double[]{top, top, bottom, bottom}, 4);

        g.setStroke(Color.web("#EAFBFF", 0.52 * pulse));
        g.setLineWidth(7.0);
        for (int ribbon = -1; ribbon <= 1; ribbon++) {
            double x = centerX + ribbon * width * 0.23;
            g.strokeArc(x - width * 0.28, top + 60.0 + ribbon * 25.0,
                    width * 0.56, 150.0, ribbon < 0 ? 205.0 : 25.0, 130.0, ArcType.OPEN);
            g.strokeArc(x - width * 0.30, top + 245.0 - ribbon * 18.0,
                    width * 0.60, 150.0, ribbon < 0 ? 25.0 : 205.0, 130.0, ArcType.OPEN);
        }
        g.setFill(Color.web("#24343B", 0.94));
        g.fillOval(centerX - width * 0.58, bottom - 50.0, width * 1.16, 74.0);
        g.setStroke(Color.web("#BDEDF4", 0.68 * pulse));
        g.setLineWidth(8.0);
        g.strokeArc(centerX - width * 0.50, bottom - 43.0,
                width, 58.0, 5.0, 170.0, ArcType.OPEN);
    }

    private void drawSkyCliffsDistantBirds(GraphicsContext g, double time) {
        renderRandom.setSeed(0x51C1_1FF5L);
        g.setStroke(Color.web("#102938", 0.48));
        g.setLineWidth(6.0);
        for (int i = 0; i < 18; i++) {
            double x = 150.0 + renderRandom.nextDouble() * (WORLD_WIDTH - 300.0)
                    + Math.sin(time * 0.16 + i) * 35.0;
            double y = 250.0 + renderRandom.nextDouble() * 900.0
                    + Math.cos(time * 0.21 + i * 0.8) * 18.0;
            double wing = 16.0 + renderRandom.nextDouble() * 18.0;
            g.strokeArc(x - wing, y, wing, 14.0, 10.0, 150.0, ArcType.OPEN);
            g.strokeArc(x, y, wing, 14.0, 20.0, 150.0, ArcType.OPEN);
        }
    }

    private void drawForestArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;

        // Big Forest is an ancient woodland, not a collection of green test
        // ledges. A cool dawn behind the canopy gives fighters high contrast,
        // while every collision platform is presented as a real living branch.
        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#173B4A")),
                new Stop(0.46, Color.web("#7FB08A")),
                new Stop(1.0, Color.web("#D4C58A"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        g.setFill(Color.web("#FFF3B0", 0.16));
        g.fillOval(2_510, 180, 980, 980);
        g.setFill(Color.web("#FFF5C7", 0.82));
        g.fillOval(2_850, 520, 300, 300);

        drawForestHillLayer(g, Color.web("#547C65", 0.66), GROUND_Y + 230, 260, 120, 0.10, 8_101L);
        drawForestHillLayer(g, Color.web("#315B48", 0.78), GROUND_Y + 330, 390, 170, 0.18, 8_102L);
        drawForestHillLayer(g, Color.web("#173D34", 0.94), GROUND_Y + 450, 470, 190, 0.27, 8_103L);

        drawForestTreeLayer(g, 0.16, GROUND_Y + 70, 620, 320, 330,
                Color.web("#263E32", 0.46), Color.web("#2F6247", 0.52), 8_120L);
        drawForestTreeLayer(g, 0.26, GROUND_Y + 100, 760, 430, 360,
                Color.web("#233427", 0.70), Color.web("#17462F", 0.76), 8_121L);
        drawForestDistantCanopy(g);

        if (ambientFx) {
            drawForestSunbeams(g);
            drawForestAmbientMotes(g);
        }

        drawForestAncientTrunks(g, time, ambientFx);
        drawForestGround(g);

        // Supports are deliberately drawn before the collision surfaces. This
        // makes even the procedurally placed ledges terminate in a trunk or root
        // instead of hovering independently in the scene.
        for (Platform platform : platforms) {
            if (isForestAerialPlatform(platform)) {
                drawForestBranchSupport(g, platform);
            }
        }
        for (Platform platform : platforms) {
            if (isForestAerialPlatform(platform)) {
                drawForestBranchPlatform(g, platform);
            }
        }
    }

    private void drawForestDistantCanopy(GraphicsContext g) {
        renderRandom.setSeed(8_124L);
        for (int i = 0; i < 34; i++) {
            double x = -180.0 + i * 190.0 + renderRandom.nextDouble() * 80.0;
            double y = 250.0 + renderRandom.nextDouble() * 420.0;
            double width = 300.0 + renderRandom.nextDouble() * 260.0;
            double height = 170.0 + renderRandom.nextDouble() * 130.0;
            Color shadow = i % 3 == 0 ? Color.web("#123B2D", 0.76) : Color.web("#1C4D36", 0.66);
            g.setFill(shadow);
            g.fillOval(x - width * 0.50, y, width, height);
            g.fillOval(x - width * 0.72, y + 54.0, width * 0.72, height * 0.72);
            g.fillOval(x + width * 0.02, y + 38.0, width * 0.70, height * 0.76);
        }
        g.setFill(Color.web("#0D2F28", 0.80));
        g.fillPolygon(new double[]{0, 0, 620, 1_050, 1_530, 2_030, 2_500, 3_020,
                        3_530, 4_020, 4_520, 5_030, 5_520, WORLD_WIDTH, WORLD_WIDTH},
                new double[]{0, 310, 410, 260, 360, 220, 340, 210,
                        350, 230, 390, 250, 370, 290, 0}, 15);
    }

    private void drawForestAncientTrunks(GraphicsContext g, double time, boolean ambientFx) {
        double[] treeX = {760.0, 2_080.0, 3_400.0, 4_780.0, 5_610.0};
        for (int i = 0; i < treeX.length; i++) {
            double sway = ambientFx ? Math.sin(time * 0.24 + i * 1.7) * 5.0 : 0.0;
            drawForestAncientTrunk(g, treeX[i] + sway, i);
        }
    }

    private void drawForestAncientTrunk(GraphicsContext g, double centerX, int index) {
        double baseWidth = 330.0 + (index % 3) * 54.0;
        double crownWidth = baseWidth * 0.54;
        double topY = index % 2 == 0 ? 260.0 : 390.0;
        double baseY = GROUND_Y + 235.0;

        g.setFill(Color.web("#17271F", 0.34));
        g.fillOval(centerX - baseWidth * 1.15, GROUND_Y - 80.0, baseWidth * 2.30, 250.0);

        g.setFill(Color.web(index % 2 == 0 ? "#3B2C20" : "#432E20"));
        g.fillPolygon(
                new double[]{centerX - baseWidth * 0.50, centerX - crownWidth * 0.52,
                        centerX + crownWidth * 0.46, centerX + baseWidth * 0.50},
                new double[]{baseY, topY, topY - 30.0, baseY}, 4);
        g.setFill(Color.web("#65452D", 0.72));
        g.fillPolygon(
                new double[]{centerX - baseWidth * 0.22, centerX - crownWidth * 0.16,
                        centerX + crownWidth * 0.04, centerX + baseWidth * 0.12},
                new double[]{baseY, topY + 30.0, topY, baseY}, 4);
        g.setStroke(Color.web("#9B7145", 0.34));
        g.setLineWidth(16.0);
        g.strokeLine(centerX - baseWidth * 0.18, baseY - 40.0, centerX - crownWidth * 0.16, topY + 90.0);
        g.strokeLine(centerX + baseWidth * 0.16, baseY - 90.0, centerX + crownWidth * 0.18, topY + 55.0);

        // Flared roots make the foreground trees visibly continue into the
        // soil instead of ending as thin columns on top of the floor.
        g.setFill(Color.web("#38271E"));
        g.fillPolygon(new double[]{centerX - baseWidth * 0.40, centerX - baseWidth * 1.18,
                        centerX - baseWidth * 0.10, centerX},
                new double[]{GROUND_Y - 90.0, GROUND_Y + 82.0, GROUND_Y + 110.0, GROUND_Y - 20.0}, 4);
        g.fillPolygon(new double[]{centerX + baseWidth * 0.36, centerX + baseWidth * 1.22,
                        centerX + baseWidth * 0.12, centerX},
                new double[]{GROUND_Y - 82.0, GROUND_Y + 88.0, GROUND_Y + 112.0, GROUND_Y - 18.0}, 4);

        double canopyY = topY - 120.0;
        g.setFill(Color.web("#0C3024"));
        g.fillOval(centerX - 430.0, canopyY - 160.0, 860.0, 360.0);
        g.fillOval(centerX - 650.0, canopyY - 60.0, 520.0, 300.0);
        g.fillOval(centerX + 120.0, canopyY - 80.0, 560.0, 320.0);
        g.setFill(Color.web("#1F5A37", 0.88));
        g.fillOval(centerX - 320.0, canopyY - 205.0, 520.0, 250.0);
        g.fillOval(centerX - 520.0, canopyY - 80.0, 380.0, 220.0);
        g.setFill(Color.web("#6F9851", 0.42));
        g.fillOval(centerX - 210.0, canopyY - 170.0, 260.0, 100.0);
    }

    private void drawForestGround(GraphicsContext g) {
        g.setFill(Color.web("#241D18"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(Color.web("#3B2A20"));
        g.fillRect(0, GROUND_Y + 95.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 95.0);

        g.setStroke(Color.web("#6A4930", 0.72));
        g.setLineWidth(24.0);
        for (double x = -120.0; x < WORLD_WIDTH; x += 310.0) {
            g.strokeLine(x, GROUND_Y + 120.0, x + 210.0, GROUND_Y + 260.0);
        }

        g.setFill(Color.web("#173E29"));
        g.fillRect(0, GROUND_Y - 18.0, WORLD_WIDTH, 95.0);
        g.setFill(Color.web("#2F6C36"));
        g.fillRect(0, GROUND_Y - 22.0, WORLD_WIDTH, 34.0);
        g.setFill(Color.web("#7CAD57"));
        renderRandom.setSeed(8_130L);
        for (int i = 0; i < 150; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double width = 42.0 + renderRandom.nextDouble() * 64.0;
            g.fillOval(x - width * 0.5, GROUND_Y - 32.0 - renderRandom.nextDouble() * 13.0,
                    width, 28.0 + renderRandom.nextDouble() * 16.0);
        }
        g.setStroke(Color.web("#B5D57B", 0.62));
        g.setLineWidth(5.0);
        for (double x = 25.0; x < WORLD_WIDTH; x += 68.0) {
            double lean = ((int) x / 68) % 2 == 0 ? -10.0 : 12.0;
            g.strokeLine(x, GROUND_Y - 18.0, x + lean, GROUND_Y - 55.0);
        }
    }

    private boolean isForestAerialPlatform(Platform platform) {
        return platform != null
                && platform.y < GROUND_Y - 40.0
                && platform.w > 120.0
                && platform.h < 180.0;
    }

    private void drawForestBranchSupport(GraphicsContext g, Platform platform) {
        double[] treeX = {760.0, 2_080.0, 3_400.0, 4_780.0, 5_610.0};
        double platformCenter = platform.x + platform.w * 0.5;
        double anchorX = treeX[0];
        for (double candidate : treeX) {
            if (Math.abs(candidate - platformCenter) < Math.abs(anchorX - platformCenter)) {
                anchorX = candidate;
            }
        }

        double innerEdge = platformCenter < anchorX ? platform.x + platform.w : platform.x;
        double trunkEdge = anchorX + Math.copySign(120.0, platformCenter - anchorX);
        double attachY = platform.y + platform.h * 0.58;
        double rootY = Math.min(GROUND_Y - 55.0, platform.y + 150.0 + Math.abs(innerEdge - trunkEdge) * 0.12);
        double thickness = Math.clamp(platform.w * 0.10, 24.0, 54.0);

        g.setStroke(Color.web("#201A15", 0.82));
        g.setLineWidth(thickness + 16.0);
        g.strokeLine(trunkEdge, rootY, innerEdge, attachY);
        g.setStroke(Color.web("#513724"));
        g.setLineWidth(thickness);
        g.strokeLine(trunkEdge, rootY, innerEdge, attachY);
        g.setStroke(Color.web("#8A6040", 0.46));
        g.setLineWidth(Math.max(7.0, thickness * 0.22));
        g.strokeLine(trunkEdge, rootY - thickness * 0.12, innerEdge, attachY - thickness * 0.12);

        // Very low ledges also receive a root into the forest floor, ensuring
        // their silhouette still makes structural sense when the trunk is far.
        if (platform.y > GROUND_Y - 420.0) {
            double rootX = platform.x + platform.w * 0.5;
            g.setStroke(Color.web("#38281E"));
            g.setLineWidth(Math.clamp(platform.w * 0.08, 22.0, 48.0));
            g.strokeLine(rootX, platform.y + platform.h, rootX + (anchorX - rootX) * 0.28, GROUND_Y + 18.0);
        }
    }

    private void drawForestBranchPlatform(GraphicsContext g, Platform platform) {
        double barkRadius = Math.min(34.0, platform.h * 0.72);
        g.setFill(Color.web("#241A15"));
        g.fillRoundRect(platform.x - 9.0, platform.y - 4.0,
                platform.w + 18.0, platform.h + 20.0, barkRadius + 10.0, barkRadius + 10.0);
        g.setFill(Color.web("#60402A"));
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h,
                barkRadius, barkRadius);
        g.setFill(Color.web("#7B5434", 0.72));
        g.fillRoundRect(platform.x + 14.0, platform.y + 8.0,
                Math.max(20.0, platform.w - 28.0), Math.max(8.0, platform.h * 0.28), 18.0, 18.0);

        renderRandom.setSeed(Double.doubleToLongBits(platform.x * 31.0 + platform.y * 17.0 + platform.w * 13.0));
        int knotCount = Math.clamp((int) Math.round(platform.w / 230.0), 1, 3);
        for (int i = 0; i < knotCount; i++) {
            double knotX = platform.x + 46.0 + renderRandom.nextDouble() * Math.max(12.0, platform.w - 92.0);
            double knotY = platform.y + platform.h * (0.48 + renderRandom.nextDouble() * 0.24);
            g.setFill(Color.web("#2A1D17", 0.82));
            g.fillOval(knotX - 13.0, knotY - 8.0, 26.0, 16.0);
            g.setStroke(Color.web("#A4774D", 0.42));
            g.setLineWidth(3.0);
            g.strokeOval(knotX - 19.0, knotY - 12.0, 38.0, 24.0);
        }

        // The bright, perfectly level moss line marks the real collision top.
        g.setFill(Color.web("#173E29"));
        g.fillRoundRect(platform.x - 7.0, platform.y - 13.0,
                platform.w + 14.0, 24.0, 22.0, 22.0);
        g.setFill(Color.web("#4F8B45"));
        g.fillRoundRect(platform.x - 3.0, platform.y - 16.0,
                platform.w + 6.0, 15.0, 16.0, 16.0);
        g.setStroke(Color.web("#A8D06D", 0.82));
        g.setLineWidth(4.0);
        g.strokeLine(platform.x + 12.0, platform.y - 13.0,
                platform.x + platform.w - 12.0, platform.y - 13.0);

        int hangingRoots = Math.clamp((int) Math.round(platform.w / 180.0), 1, 4);
        g.setStroke(Color.web("#315533", 0.78));
        g.setLineWidth(5.0);
        for (int i = 0; i < hangingRoots; i++) {
            double rootX = platform.x + (i + 1.0) * platform.w / (hangingRoots + 1.0);
            double length = 34.0 + renderRandom.nextDouble() * 54.0;
            double drift = (renderRandom.nextDouble() - 0.5) * 24.0;
            g.strokeLine(rootX, platform.y + platform.h, rootX + drift, platform.y + platform.h + length);
        }
    }

    private void drawForestHillLayer(GraphicsContext g, Color color, double baseY, double amplitude, double variance,
                                     double movementFactor, long seed) {
        final int points = 22;
        double[] xPoints = new double[points + 2];
        double[] yPoints = new double[points + 2];
        renderRandom.setSeed(seed);
        for (int i = 0; i < points; i++) {
            double worldX = -420 + i * ((WORLD_WIDTH + 840) / (double) (points - 1));
            double wave = Math.sin((worldX + seed * 0.11) / 360.0) * amplitude * 0.18;
            double ridge = Math.cos((worldX + seed * 0.07) / 640.0) * amplitude * 0.1;
            double lift = amplitude * 0.34 + renderRandom.nextDouble() * variance;
            xPoints[i] = parallaxAdjustedWorldX(worldX, movementFactor);
            yPoints[i] = baseY - lift - wave - ridge;
        }
        xPoints[points] = parallaxAdjustedWorldX(WORLD_WIDTH + 480, movementFactor);
        yPoints[points] = WORLD_HEIGHT + 120;
        xPoints[points + 1] = parallaxAdjustedWorldX(-480, movementFactor);
        yPoints[points + 1] = WORLD_HEIGHT + 120;
        g.setFill(color);
        g.fillPolygon(xPoints, yPoints, xPoints.length);
    }

    private void drawForestTreeLayer(GraphicsContext g, double movementFactor, double baseY, double minHeight,
                                     double heightVariance, double spacing, Color trunkColor, Color canopyColor, long seed) {
        renderRandom.setSeed(seed);
        Random treeRandom = renderRandom;
        for (int i = 0; i < 24; i++) {
            double worldX = -240 + i * spacing + treeRandom.nextDouble() * 70;
            double drawX = parallaxAdjustedWorldX(worldX, movementFactor);
            double trunkHeight = minHeight + treeRandom.nextDouble() * heightVariance;
            double trunkWidth = 26 + treeRandom.nextDouble() * 28;
            double canopyWidth = 170 + treeRandom.nextDouble() * 120;
            double canopyHeight = 110 + treeRandom.nextDouble() * 90;
            double trunkTopY = baseY - trunkHeight;

            g.setFill(trunkColor);
            g.fillRoundRect(drawX - trunkWidth * 0.5, trunkTopY, trunkWidth, trunkHeight + 70,
                    trunkWidth, Math.min(trunkWidth, trunkHeight + 70));

            g.setFill(canopyColor);
            g.fillOval(drawX - canopyWidth * 0.52, trunkTopY - canopyHeight * 0.26, canopyWidth, canopyHeight);
            g.fillOval(drawX - canopyWidth * 0.82, trunkTopY + canopyHeight * 0.05, canopyWidth * 0.72, canopyHeight * 0.72);
            g.fillOval(drawX - canopyWidth * 0.06, trunkTopY + canopyHeight * 0.02, canopyWidth * 0.72, canopyHeight * 0.76);
            if (treeRandom.nextDouble() < 0.55) {
                g.fillOval(drawX - canopyWidth * 0.28, trunkTopY - canopyHeight * 0.42,
                        canopyWidth * 0.62, canopyHeight * 0.62);
            }
        }
    }

    private void drawForestSunbeams(GraphicsContext g) {
        double time = System.currentTimeMillis() / 1800.0;
        g.setFill(Color.web("#FFF9C4", 0.08));
        for (int i = 0; i < 6; i++) {
            double beamCenterX = parallaxAdjustedWorldX(180 + i * 980 + Math.sin(time + i * 0.8) * 80, 0.10);
            double beamWidth = 170 + (i % 3) * 34;
            g.fillPolygon(
                    new double[]{beamCenterX - beamWidth, beamCenterX + beamWidth, beamCenterX + beamWidth * 0.42, beamCenterX - beamWidth * 0.42},
                    new double[]{0, 0, GROUND_Y + 140, GROUND_Y + 140},
                    4
            );
        }
    }

    private void drawForestAmbientMotes(GraphicsContext g) {
        double time = System.currentTimeMillis() / 950.0;
        renderRandom.setSeed(8_140L);
        Random moteRandom = renderRandom;
        for (int i = 0; i < 48; i++) {
            double baseX = moteRandom.nextDouble() * WORLD_WIDTH;
            double baseY = 160 + moteRandom.nextDouble() * (GROUND_Y - 260);
            double driftX = Math.sin(time * 0.8 + i * 1.37) * (14 + moteRandom.nextDouble() * 20);
            double driftY = Math.cos(time * 0.65 + i * 0.93) * (8 + moteRandom.nextDouble() * 14);
            double x = baseX + driftX;
            double y = baseY + driftY;
            boolean glowing = i % 6 == 0;
            g.setFill(glowing ? Color.web("#FFF59D", 0.54) : Color.web("#C5E1A5", 0.3));
            double size = glowing ? 6.2 : 3.8;
            g.fillOval(x - size * 0.5, y - size * 0.5, size, size * 0.78);
        }
    }

    private void drawEchoCavernArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;

        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#060914")),
                new Stop(0.54, Color.web("#16142B")),
                new Stop(1.0, Color.web("#282039"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        drawEchoCavernBackChambers(g);
        drawEchoCavernGeode(g, time, ambientFx);
        drawEchoCavernPillars(g);
        if (ambientFx) drawEchoCavernBats(g, time);
        drawEchoCavernShell(g);

        // Dark limestone braces sit behind the playable shelves. They make
        // every collision surface part of the chamber's geology without
        // changing the actual platform rectangles or implying a new hitbox.
        for (Platform platform : platforms) {
            if (isCaveAerialPlatform(platform)) drawCaveShelfSupport(g, platform);
        }
        for (WindVent vent : windVents) drawEchoDraftShaft(g, vent, time, ambientFx);
        for (Platform platform : platforms) {
            if (isCaveAerialPlatform(platform)) drawCaveRockShelf(g, platform);
        }

        drawEchoCavernCrystalLandmarks(g, time, ambientFx);
        if (ambientFx) {
            g.setFill(Color.web("#8C7DB4", 0.10));
            g.fillRect(0, GROUND_Y - 150.0, WORLD_WIDTH, 230.0);
        }
    }

    private void drawEchoCavernBackChambers(GraphicsContext g) {
        // Three receding limestone chambers give the map a real cavern scale
        // and preserve a quiet center behind combat silhouettes.
        g.setFill(Color.web("#0B0C1A"));
        g.fillPolygon(new double[]{0, 0, 560, 980, 1_360, 1_760, 2_180, 2_620,
                        3_020, 3_440, 3_880, 4_300, 4_720, 5_160, 5_580, WORLD_WIDTH, WORLD_WIDTH},
                new double[]{0, 390, 520, 370, 510, 320, 470, 290,
                        430, 300, 500, 340, 520, 360, 490, 350, 0}, 17);

        Color farStone = Color.web("#17182A");
        Color farEdge = Color.web("#34324A", 0.68);
        double[] chamberX = {620.0, 1_820.0, 3_000.0, 4_180.0, 5_380.0};
        for (int i = 0; i < chamberX.length; i++) {
            double center = chamberX[i];
            double width = i == 2 ? 960.0 : 760.0;
            double top = 390.0 + (i % 2) * 120.0;
            g.setFill(farStone);
            g.fillOval(center - width * 0.5, top, width, 1_760.0);
            g.setFill(Color.web("#090B17"));
            g.fillOval(center - width * 0.36, top + 150.0, width * 0.72, 1_530.0);
            g.setStroke(farEdge);
            g.setLineWidth(22.0);
            g.strokeArc(center - width * 0.39, top + 85.0, width * 0.78, 1_610.0,
                    8.0, 164.0, ArcType.OPEN);
        }

        g.setStroke(Color.web("#3C3852", 0.30));
        g.setLineWidth(9.0);
        for (double y = 650.0; y < GROUND_Y - 150.0; y += 280.0) {
            g.strokeLine(160.0, y, WORLD_WIDTH - 160.0, y + 32.0 * Math.sin(y * 0.01));
        }
    }

    private void drawEchoCavernGeode(GraphicsContext g, double time, boolean ambientFx) {
        double pulse = ambientFx ? 0.88 + 0.12 * Math.sin(time * 1.15) : 0.94;
        double centerX = WORLD_WIDTH * 0.5;
        double centerY = 1_050.0;
        g.setFill(Color.web("#42D9E8", 0.045 * pulse));
        g.fillOval(centerX - 720.0, centerY - 620.0, 1_440.0, 1_240.0);
        g.setStroke(Color.web("#5BE0EC", 0.18 * pulse));
        g.setLineWidth(28.0);
        g.strokeOval(centerX - 500.0, centerY - 430.0, 1_000.0, 860.0);
        g.setStroke(Color.web("#A77BE8", 0.24 * pulse));
        g.setLineWidth(18.0);
        g.strokeOval(centerX - 390.0, centerY - 330.0, 780.0, 660.0);

        g.setFill(Color.web("#5CE8EA", 0.52 * pulse));
        for (int i = 0; i < 11; i++) {
            double angle = Math.PI * 2.0 * i / 11.0;
            double innerX = centerX + Math.cos(angle) * 245.0;
            double innerY = centerY + Math.sin(angle) * 200.0;
            double outerX = centerX + Math.cos(angle) * (340.0 + (i % 3) * 28.0);
            double outerY = centerY + Math.sin(angle) * (285.0 + (i % 2) * 25.0);
            double sideX = innerX + Math.cos(angle + Math.PI * 0.5) * 32.0;
            double sideY = innerY + Math.sin(angle + Math.PI * 0.5) * 32.0;
            g.fillPolygon(new double[]{innerX, sideX, outerX}, new double[]{innerY, sideY, outerY}, 3);
        }
    }

    private void drawEchoCavernPillars(GraphicsContext g) {
        double[] pillarX = {520.0, 1_650.0, 2_760.0, 3_880.0, 5_060.0, 5_760.0};
        for (int i = 0; i < pillarX.length; i++) {
            double x = pillarX[i];
            double width = 220.0 + (i % 3) * 42.0;
            g.setFill(Color.web(i % 2 == 0 ? "#202031" : "#242136", 0.84));
            g.fillPolygon(new double[]{x - width * 0.42, x - width * 0.58, x - width * 0.48,
                            x + width * 0.48, x + width * 0.58, x + width * 0.42},
                    new double[]{190.0, 760.0, GROUND_Y + 120.0,
                            GROUND_Y + 120.0, 760.0, 190.0}, 6);
            g.setStroke(Color.web("#514B62", 0.48));
            g.setLineWidth(14.0);
            g.strokeLine(x - width * 0.18, 270.0, x - width * 0.26, GROUND_Y + 40.0);
            g.setStroke(Color.web("#0B0B15", 0.55));
            g.setLineWidth(20.0);
            g.strokeLine(x + width * 0.23, 240.0, x + width * 0.30, GROUND_Y + 50.0);
        }
    }

    private void drawEchoCavernShell(GraphicsContext g) {
        // The visible roof and side walls match the real collision shell.
        g.setFill(Color.web("#151421"));
        g.fillRect(0, 0, WORLD_WIDTH, 86.0);
        g.setFill(Color.web("#292636"));
        g.fillRect(0, 0, WORLD_WIDTH, 44.0);
        g.setStroke(Color.web("#494357", 0.72));
        g.setLineWidth(9.0);
        g.strokeLine(0, 76.0, WORLD_WIDTH, 76.0);

        renderRandom.setSeed(0xEC40_CE11L);
        for (int i = 0; i < 30; i++) {
            double x = 30.0 + i * 205.0 + renderRandom.nextDouble() * 54.0;
            double length = 90.0 + renderRandom.nextDouble() * 210.0;
            double half = 36.0 + renderRandom.nextDouble() * 34.0;
            g.setFill(Color.web(i % 3 == 0 ? "#242235" : "#1C1B2A"));
            g.fillPolygon(new double[]{x - half, x + half, x + (renderRandom.nextDouble() - 0.5) * 18.0},
                    new double[]{72.0, 72.0, 72.0 + length}, 3);
            if (i % 5 == 0) {
                g.setStroke(Color.web("#8D78B5", 0.28));
                g.setLineWidth(6.0);
                g.strokeLine(x - half * 0.35, 80.0, x, 72.0 + length * 0.78);
            }
        }

        g.setFill(Color.web("#1C1927"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y);
        g.setFill(Color.web("#302A3B"));
        g.fillRect(0, GROUND_Y + 100.0, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y - 100.0);
        g.setStroke(Color.web("#575064", 0.54));
        g.setLineWidth(13.0);
        for (double x = -80.0; x < WORLD_WIDTH; x += 330.0) {
            g.strokeLine(x, GROUND_Y + 128.0, x + 220.0, GROUND_Y + 265.0);
        }
        g.setFill(Color.web("#454050"));
        g.fillRect(0, GROUND_Y - 18.0, WORLD_WIDTH, 72.0);
        g.setFill(Color.web("#756C82"));
        g.fillRect(0, GROUND_Y - 18.0, WORLD_WIDTH, 16.0);

        g.setFill(Color.web("#1A1825"));
        g.fillPolygon(new double[]{0, 180.0, 230.0, 170.0, 0},
                new double[]{0, 0, 620.0, GROUND_Y + 80.0, GROUND_Y + 80.0}, 5);
        g.fillPolygon(new double[]{WORLD_WIDTH, WORLD_WIDTH - 180.0, WORLD_WIDTH - 230.0,
                        WORLD_WIDTH - 170.0, WORLD_WIDTH},
                new double[]{0, 0, 620.0, GROUND_Y + 80.0, GROUND_Y + 80.0}, 5);
    }

    private boolean isCaveAerialPlatform(Platform platform) {
        return platform != null
                && platform.y > 90.0
                && platform.y < GROUND_Y - 55.0
                && platform.w > 120.0
                && platform.h < 140.0;
    }

    private void drawCaveShelfSupport(GraphicsContext g, Platform platform) {
        double centerX = platform.x + platform.w * 0.5;
        double underside = platform.y + platform.h;
        if (platform.y < 820.0) {
            double neckWidth = Math.clamp(platform.w * 0.20, 40.0, 92.0);
            g.setFill(Color.web("#1D1C2A"));
            g.fillPolygon(new double[]{centerX - neckWidth * 0.34, centerX + neckWidth * 0.34,
                            centerX + neckWidth, centerX - neckWidth},
                    new double[]{70.0, 70.0, underside + 8.0, underside + 8.0}, 4);
            g.setStroke(Color.web("#4A4558", 0.50));
            g.setLineWidth(8.0);
            g.strokeLine(centerX - neckWidth * 0.16, 80.0, centerX - neckWidth * 0.48, underside);
            return;
        }

        double[] pillarX = {520.0, 1_650.0, 2_760.0, 3_880.0, 5_060.0, 5_760.0};
        double anchorX = pillarX[0];
        for (double candidate : pillarX) {
            if (Math.abs(candidate - centerX) < Math.abs(anchorX - centerX)) anchorX = candidate;
        }
        double innerEdge = centerX < anchorX ? platform.x + platform.w : platform.x;
        double pillarEdge = anchorX + Math.copySign(110.0, centerX - anchorX);
        double anchorY = Math.min(GROUND_Y - 90.0,
                platform.y + 160.0 + Math.abs(innerEdge - pillarEdge) * 0.10);
        double thickness = Math.clamp(platform.w * 0.11, 30.0, 74.0);
        g.setStroke(Color.web("#11111B", 0.86));
        g.setLineWidth(thickness + 20.0);
        g.strokeLine(pillarEdge, anchorY, innerEdge, underside * 0.96 + platform.y * 0.04);
        g.setStroke(Color.web("#34303F"));
        g.setLineWidth(thickness);
        g.strokeLine(pillarEdge, anchorY, innerEdge, underside);
        g.setStroke(Color.web("#665F73", 0.42));
        g.setLineWidth(Math.max(7.0, thickness * 0.18));
        g.strokeLine(pillarEdge, anchorY - thickness * 0.12, innerEdge, underside - thickness * 0.12);

        if (platform.y > GROUND_Y - 520.0) {
            double baseHalf = Math.clamp(platform.w * 0.28, 60.0, 150.0);
            g.setFill(Color.web("#292633"));
            g.fillPolygon(new double[]{centerX - 25.0, centerX + 25.0,
                            centerX + baseHalf, centerX - baseHalf},
                    new double[]{underside, underside, GROUND_Y + 18.0, GROUND_Y + 18.0}, 4);
        }
    }

    private void drawCaveRockShelf(GraphicsContext g, Platform platform) {
        renderRandom.setSeed(Double.doubleToLongBits(platform.x * 29.0 + platform.y * 13.0 + platform.w * 17.0));
        double bottom = platform.y + platform.h + 12.0;
        double pointA = platform.x + platform.w * (0.22 + renderRandom.nextDouble() * 0.10);
        double pointB = platform.x + platform.w * (0.70 + renderRandom.nextDouble() * 0.10);

        g.setFill(Color.web("#181722"));
        g.fillPolygon(new double[]{platform.x - 10.0, platform.x + platform.w + 10.0,
                        platform.x + platform.w - 16.0, pointB, pointA, platform.x + 14.0},
                new double[]{platform.y - 5.0, platform.y - 5.0, bottom,
                        bottom + 36.0, bottom + 24.0, bottom}, 6);
        g.setFill(Color.web("#494454"));
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 18.0, 18.0);
        g.setFill(Color.web("#625B6D", 0.80));
        g.fillRoundRect(platform.x + 12.0, platform.y + 7.0,
                Math.max(18.0, platform.w - 24.0), Math.max(7.0, platform.h * 0.28), 12.0, 12.0);

        // A pale, level mineral seam marks the actual collision surface.
        g.setFill(Color.web("#393748"));
        g.fillRoundRect(platform.x - 6.0, platform.y - 11.0, platform.w + 12.0, 20.0, 18.0, 18.0);
        g.setStroke(Color.web("#A79AB9", 0.92));
        g.setLineWidth(5.0);
        g.strokeLine(platform.x + 10.0, platform.y - 8.0,
                platform.x + platform.w - 10.0, platform.y - 8.0);

        int seamCount = Math.clamp((int) Math.round(platform.w / 210.0), 1, 4);
        g.setStroke(Color.web("#24212E", 0.84));
        g.setLineWidth(4.0);
        for (int i = 0; i < seamCount; i++) {
            double x = platform.x + (i + 1.0) * platform.w / (seamCount + 1.0);
            g.strokeLine(x - 18.0, platform.y + platform.h * 0.42,
                    x + 11.0, platform.y + platform.h + 10.0);
        }

        if (((long) Math.floor(platform.x + platform.y)) % 3L == 0L) {
            drawCaveCrystalCluster(g, platform.x + platform.w * 0.52,
                    platform.y - 12.0, 0.42, false);
        }
    }

    private void drawEchoDraftShaft(GraphicsContext g, WindVent vent, double time, boolean ambientFx) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.72 + 0.28 * Math.sin(time * 2.0 + vent.x * 0.013) : 0.82;
        double width = Math.clamp(vent.w * 0.46, 96.0, 180.0);
        double top = vent.y - 250.0;
        double height = 500.0;
        g.setFill(new LinearGradient(0, 1, 0, 0, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#55DDE8", 0.20 * pulse)),
                new Stop(0.48, Color.web("#55DDE8", 0.09 * pulse)),
                new Stop(1.0, Color.TRANSPARENT)));
        g.fillPolygon(new double[]{centerX - width * 0.36, centerX + width * 0.36,
                        centerX + width * 0.72, centerX - width * 0.72},
                new double[]{top, top, top + height, top + height}, 4);
        g.setStroke(Color.web("#75E6EC", 0.30 * pulse));
        g.setLineWidth(7.0);
        for (int stream = -1; stream <= 1; stream++) {
            double x = centerX + stream * width * 0.24;
            g.strokeLine(x, top + 45.0 + Math.abs(stream) * 30.0,
                    x + stream * 11.0, top + height - 38.0);
        }
        g.setFill(Color.web("#11141F", 0.92));
        g.fillOval(centerX - width * 0.62, top + height - 48.0, width * 1.24, 74.0);
        g.setStroke(Color.web("#55DDE8", 0.62 * pulse));
        g.setLineWidth(8.0);
        g.strokeArc(centerX - width * 0.52, top + height - 42.0,
                width * 1.04, 56.0, 5.0, 170.0, ArcType.OPEN);
    }

    private void drawEchoCavernCrystalLandmarks(GraphicsContext g, double time, boolean ambientFx) {
        double pulse = ambientFx ? 0.90 + 0.10 * Math.sin(time * 1.7) : 0.94;
        double[] x = {430.0, 1_470.0, 2_650.0, 3_520.0, 4_720.0, 5_650.0};
        double[] scale = {1.0, 0.72, 1.18, 0.82, 1.10, 0.78};
        for (int i = 0; i < x.length; i++) {
            drawCaveCrystalCluster(g, x[i], GROUND_Y - 18.0,
                    scale[i] * pulse, i % 2 != 0);
        }
    }

    private void drawCaveCrystalCluster(GraphicsContext g, double x, double baseY,
                                        double scale, boolean violet) {
        Color glow = Color.web(violet ? "#A884F4" : "#64E7EC");
        g.setFill(glow.deriveColor(0, 1, 1, 0.10));
        g.fillOval(x - 105.0 * scale, baseY - 150.0 * scale,
                210.0 * scale, 180.0 * scale);
        double[] offsets = {-52.0, -16.0, 24.0, 58.0};
        double[] heights = {88.0, 146.0, 112.0, 70.0};
        for (int i = 0; i < offsets.length; i++) {
            double cx = x + offsets[i] * scale;
            double height = heights[i] * scale;
            double half = (14.0 + (i % 2) * 5.0) * scale;
            g.setFill(glow.deriveColor(0, 1, 0.82 + i * 0.05, 0.82));
            g.fillPolygon(new double[]{cx - half, cx + half, cx + half * 0.60, cx,
                            cx - half * 0.60},
                    new double[]{baseY, baseY, baseY - height * 0.72, baseY - height,
                            baseY - height * 0.72}, 5);
            g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.42));
            g.setLineWidth(Math.max(2.0, 4.0 * scale));
            g.strokeLine(cx - half * 0.20, baseY - height * 0.12,
                    cx - half * 0.10, baseY - height * 0.72);
        }
    }

    private void drawEchoCavernBats(GraphicsContext g, double time) {
        renderRandom.setSeed(9_042L);
        for (int i = 0; i < 24; i++) {
            double baseX = 180.0 + renderRandom.nextDouble() * (WORLD_WIDTH - 360.0);
            double baseY = 320.0 + renderRandom.nextDouble() * (GROUND_Y - 780.0);
            double phase = renderRandom.nextDouble() * Math.PI * 2.0;
            double speed = 0.42 + renderRandom.nextDouble() * 0.85;
            double x = baseX + Math.sin(time * speed + phase) * (30.0 + renderRandom.nextDouble() * 70.0);
            double y = baseY + Math.cos(time * speed * 1.3 + phase) * (12.0 + renderRandom.nextDouble() * 26.0);
            double flap = 0.58 + 0.42 * Math.sin(time * speed * 6.0 + phase);
            g.setFill(Color.web("#02040A", 0.64));
            g.fillOval(x - 10.0, y - 5.0, 20.0, 13.0);
            g.fillPolygon(new double[]{x - 6.0, x - 22.0 - 18.0 * flap, x - 12.0},
                    new double[]{y, y - 9.0 * flap, y + 6.0}, 3);
            g.fillPolygon(new double[]{x + 6.0, x + 22.0 + 18.0 * flap, x + 12.0},
                    new double[]{y, y - 9.0 * flap, y + 6.0}, 3);
        }
    }

    private void drawFrozenCalderaArena(GraphicsContext g, boolean ambientFx) {
        double thaw = longWinterThawProgress();
        Color skyTop = Color.web("#030B1D").interpolate(Color.web("#24122D"), thaw);
        Color skyBottom = Color.web("#315E7D").interpolate(Color.web("#D35D47"), thaw);
        for (int i = 0; i < 640; i++) {
            double ratio = i / 640.0;
            g.setFill(skyTop.interpolate(skyBottom, ratio));
            g.fillRect(0, i * (WORLD_HEIGHT / 640.0), WORLD_WIDTH, WORLD_HEIGHT / 640.0 + 3);
        }

        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;

        // A deep aurora crowns the caldera without competing with the pale
        // playable ice. Render-time motion is deliberately presentation-only.
        drawFrozenCalderaAurora(g, time, thaw, ambientFx);
        renderRandom.setSeed(0xCA1D_E4A1L);
        for (int i = 0; i < 150; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double y = 60.0 + renderRandom.nextDouble() * (GROUND_Y - 1_100.0);
            double radius = 2.0 + renderRandom.nextDouble() * 5.0;
            double twinkle = ambientFx ? 0.72 + 0.28 * Math.sin(time * 1.4 + i * 0.91) : 0.84;
            g.setFill(Color.web(i % 9 == 0 ? "#FFF0C2" : "#D6F7FF",
                    (0.20 + renderRandom.nextDouble() * 0.44) * twinkle * (1.0 - thaw * 0.34)));
            g.fillOval(x, y, radius, radius);
        }

        double sunX = 3_000.0;
        double sunY = 420.0 - thaw * 80.0;
        g.setFill(Color.web("#FFD89A", 0.05 + thaw * 0.16));
        g.fillOval(sunX - 400, sunY - 400, 800, 800);
        g.setFill(Color.web("#FFF5D2", 0.38 + thaw * 0.56));
        g.fillOval(sunX - 104, sunY - 104, 208, 208);

        // Three nested crater rings give the stage a real place and scale:
        // distant polar peaks, the black volcanic wall, then translucent ice.
        Color farIce = Color.web("#102D49").interpolate(Color.web("#523244"), thaw);
        drawFrozenCalderaMountainLayer(g, GROUND_Y + 110, 780, 720, farIce, 0.72);
        drawFrozenCalderaMountainLayer(g, GROUND_Y + 130, 560, 910,
                farIce.interpolate(Color.web("#1A3850"), 0.45), 0.88);

        Color craterRock = Color.web("#07131F").interpolate(Color.web("#351922"), thaw);
        g.setFill(craterRock);
        g.fillPolygon(
                new double[]{0, 0, 520, 1_060, 1_540, 2_000, 2_420, 3_000,
                        3_580, 4_000, 4_460, 4_940, 5_480, WORLD_WIDTH, WORLD_WIDTH},
                new double[]{GROUND_Y + 150, GROUND_Y - 190, GROUND_Y - 540, GROUND_Y - 330,
                        GROUND_Y - 660, GROUND_Y - 440, GROUND_Y - 770, GROUND_Y - 920,
                        GROUND_Y - 770, GROUND_Y - 440, GROUND_Y - 660, GROUND_Y - 330,
                        GROUND_Y - 540, GROUND_Y - 190, GROUND_Y + 150},
                15);
        g.setStroke(Color.web("#65BFD3", 0.18 + (1.0 - thaw) * 0.16));
        g.setLineWidth(16.0);
        g.strokePolyline(
                new double[]{0, 520, 1_060, 1_540, 2_000, 2_420, 3_000, 3_580,
                        4_000, 4_460, 4_940, 5_480, WORLD_WIDTH},
                new double[]{GROUND_Y - 190, GROUND_Y - 540, GROUND_Y - 330, GROUND_Y - 660,
                        GROUND_Y - 440, GROUND_Y - 770, GROUND_Y - 920, GROUND_Y - 770,
                        GROUND_Y - 440, GROUND_Y - 660, GROUND_Y - 330, GROUND_Y - 540,
                        GROUND_Y - 190},
                13);

        // The last thermal glows through the caldera's frozen throat.
        double corePulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 1.55) : 0.62;
        g.setFill(Color.web("#FF6D24", 0.08 + thaw * 0.17 + corePulse * 0.025));
        g.fillOval(2_190, GROUND_Y - 640, 1_620, 1_050);
        g.setFill(Color.web("#FFB347", 0.07 + thaw * 0.12));
        g.fillOval(2_500, GROUND_Y - 370, 1_000, 520);

        Color abyss = Color.web("#020912").interpolate(Color.web("#260C11"), thaw);
        Color molten = Color.web("#123A52").interpolate(Color.web("#FF5A1F"), thaw);
        g.setFill(abyss);
        g.fillRect(0, GROUND_Y + 85, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y + 320);
        g.setFill(molten.deriveColor(0, 1, 1, 0.30 + thaw * 0.18));
        for (int i = -1; i < 11; i++) {
            double drift = ambientFx ? Math.sin(time * 0.75 + i) * 24.0 : 0.0;
            g.fillOval(i * 620.0 + drift, GROUND_Y + 74 + (i % 2) * 24.0, 760, 105);
        }

        // The playable islands are the crown of one glacier rather than loose
        // slabs. Broad foundations visibly descend into the volcanic chasm.
        Color deepGlacier = Color.web("#0B324A").interpolate(Color.web("#403038"), thaw);
        Color glacierFace = Color.web("#286A82").interpolate(Color.web("#9B5943"), thaw);
        drawFrozenCalderaFoundation(g, 420, GROUND_Y - 190, 1_080, GROUND_Y + 330,
                deepGlacier, glacierFace);
        drawFrozenCalderaFoundation(g, 1_750, GROUND_Y - 350, 2_500, GROUND_Y + 410,
                deepGlacier, glacierFace);
        drawFrozenCalderaFoundation(g, 4_500, GROUND_Y - 190, 1_080, GROUND_Y + 330,
                deepGlacier, glacierFace);
        drawFrozenCalderaFoundation(g, 720, GROUND_Y + 55, 420, GROUND_Y + 360,
                deepGlacier, glacierFace);
        drawFrozenCalderaFoundation(g, 4_860, GROUND_Y + 55, 420, GROUND_Y + 360,
                deepGlacier, glacierFace);

        drawFrozenCalderaThermalVeins(g, thaw, corePulse);

        drawFrozenCalderaButtress(g, 1_170, GROUND_Y - 720, 430,
                760, GROUND_Y - 190, 1_470, GROUND_Y - 190, deepGlacier, thaw);
        drawFrozenCalderaButtress(g, 4_400, GROUND_Y - 720, 430,
                4_530, GROUND_Y - 190, 5_240, GROUND_Y - 190, deepGlacier, thaw);
        drawFrozenCalderaButtress(g, 2_520, GROUND_Y - 932, 960,
                2_080, GROUND_Y - 350, 3_920, GROUND_Y - 350, deepGlacier, thaw);

        if (ambientFx) {
            renderRandom.setSeed(0xF20A_E4A1L);
            for (int i = 0; i < 95; i++) {
                double baseX = renderRandom.nextDouble() * (WORLD_WIDTH + 400.0) - 200.0;
                double baseY = 80.0 + renderRandom.nextDouble() * (GROUND_Y - 100.0);
                double fall = (time * (24.0 + renderRandom.nextDouble() * 34.0) + i * 41.0)
                        % Math.max(1.0, GROUND_Y - 80.0);
                double x = baseX + Math.sin(time * 0.7 + i * 0.83) * 42.0;
                double y = 60.0 + (baseY + fall) % Math.max(1.0, GROUND_Y - 80.0);
                double size = 2.0 + renderRandom.nextDouble() * 5.0;
                g.setFill(Color.web("#EAFBFF", (0.42 - thaw * 0.24) * (0.65 + renderRandom.nextDouble() * 0.35)));
                g.fillOval(x, y, size, size);
            }
        }

        for (Platform platform : platforms) {
            drawFrozenCalderaPlatform(g, platform, thaw);

            if (platform.signText != null) {
                g.setTextAlign(TextAlignment.CENTER);
                g.setFont(Font.font("Arial Black", FontWeight.BOLD, 27));
                g.setFill(Color.web("#E9FCFF", 0.88));
                g.fillText(platform.signText, platform.x + platform.w * 0.5,
                        platform.y + Math.min(platform.h * 0.70, 58.0));
            }
        }

        for (WindVent vent : windVents) {
            double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 2.0 + vent.x * 0.01) : 0.55;
            double centerX = vent.x + vent.w * 0.5;
            Color ventWarmth = Color.web("#6FE7FF").interpolate(Color.web("#FFB24D"), thaw);
            g.setFill(ventWarmth.deriveColor(0, 1, 1, 0.06 + pulse * 0.07));
            g.fillPolygon(
                    new double[]{centerX - 82, centerX - 32, centerX, centerX + 32, centerX + 82},
                    new double[]{vent.y + 30, vent.y - 145, vent.y - 215, vent.y - 145, vent.y + 30},
                    5);
            g.setStroke(ventWarmth.deriveColor(0, 1, 1, 0.48 + pulse * 0.24));
            g.setLineWidth(5.0);
            g.strokeLine(centerX - 88, vent.y + 9, centerX - 28, vent.y - 10);
            g.strokeLine(centerX - 28, vent.y - 10, centerX + 8, vent.y + 14);
            g.strokeLine(centerX + 8, vent.y + 14, centerX + 74, vent.y - 5);
            g.setLineWidth(3.0);
            g.strokeArc(centerX - 75, vent.y - 122, 150, 150, 18, 144, ArcType.OPEN);
        }
    }

    private void drawFrozenCalderaAurora(GraphicsContext g, double time, double thaw, boolean ambientFx) {
        double sway = ambientFx ? Math.sin(time * 0.22) * 70.0 : 0.0;
        Color blueAurora = Color.web("#48E3F2", Math.max(0.05, 0.17 - thaw * 0.08));
        Color greenAurora = Color.web("#72F2B8", Math.max(0.04, 0.13 - thaw * 0.06));
        g.setFill(blueAurora);
        g.beginPath();
        g.moveTo(-220, 480);
        g.bezierCurveTo(980 + sway, 90, 1_540 + sway, 760, 2_770, 300);
        g.bezierCurveTo(3_920 - sway, -20, 4_960 - sway, 690, WORLD_WIDTH + 220, 190);
        g.lineTo(WORLD_WIDTH + 220, 390);
        g.bezierCurveTo(4_950 - sway, 840, 3_850 - sway, 170, 2_790, 490);
        g.bezierCurveTo(1_550 + sway, 900, 940 + sway, 270, -220, 690);
        g.closePath();
        g.fill();
        g.setFill(greenAurora);
        g.beginPath();
        g.moveTo(-140, 720);
        g.bezierCurveTo(1_060 - sway, 310, 1_960 - sway, 970, 3_060, 520);
        g.bezierCurveTo(4_230 + sway, 100, 5_100 + sway, 790, WORLD_WIDTH + 160, 370);
        g.lineTo(WORLD_WIDTH + 160, 510);
        g.bezierCurveTo(5_110 + sway, 920, 4_230 + sway, 280, 3_060, 690);
        g.bezierCurveTo(1_960 - sway, 1_120, 1_030 - sway, 500, -140, 870);
        g.closePath();
        g.fill();
    }

    private void drawFrozenCalderaMountainLayer(GraphicsContext g, double baseY, double spacing,
                                                  double maxHeight, Color color, double opacity) {
        g.setFill(color.deriveColor(0, 1, 1, opacity));
        int count = (int) Math.ceil(WORLD_WIDTH / spacing) + 2;
        for (int i = -1; i < count; i++) {
            double centerX = i * spacing + (i % 2 == 0 ? 110.0 : -40.0);
            double height = maxHeight * (0.60 + Math.floorMod(i, 4) * 0.105);
            double halfWidth = spacing * 0.62;
            g.fillPolygon(
                    new double[]{centerX - halfWidth, centerX - halfWidth * 0.20,
                            centerX, centerX + halfWidth * 0.18, centerX + halfWidth},
                    new double[]{baseY, baseY - height * 0.44,
                            baseY - height, baseY - height * 0.48, baseY},
                    5);
        }
    }

