    private void drawAshfallFlyingButtress(GraphicsContext g, double topX, double topY,
                                            double footX, double footY, double width) {
        double dx = footX - topX;
        double dy = footY - topY;
        double length = Math.hypot(dx, dy);
        double nx = -dy / length * width * 0.5;
        double ny = dx / length * width * 0.5;
        g.setFill(Color.web("#211018"));
        g.fillPolygon(new double[]{topX + nx, footX + nx, footX - nx, topX - nx},
                new double[]{topY + ny, footY + ny, footY - ny, topY - ny}, 4);
        g.setStroke(Color.web("#80402F", 0.52));
        g.setLineWidth(8.0);
        g.strokeLine(topX, topY, footX, footY);
    }

    private void drawAshfallPlatform(GraphicsContext g, Platform p) {
        boolean altar = Math.abs(p.x - ASHFALL_ALTAR_X) < 1.0 && Math.abs(p.y - ASHFALL_ALTAR_Y) < 1.0;
        boolean main = Math.abs(p.x - ASHFALL_MAIN_X) < 1.0 && Math.abs(p.w - ASHFALL_MAIN_W) < 1.0;
        double bodyHeight = p.h + (main ? 24.0 : 16.0);
        Color top = altar ? Color.web("#70201D") : Color.web("#37151A");
        Color side = altar ? Color.web("#2B0C11") : Color.web("#170B10");
        Color rim = altar ? Color.web("#F3A33C", 0.96) : Color.web("#A4553A", 0.90);

        g.setFill(side);
        g.fillPolygon(new double[]{p.x, p.x + p.w, p.x + p.w - 16,
                        p.x + p.w * 0.74, p.x + p.w * 0.48, p.x + 14},
                new double[]{p.y, p.y, p.y + bodyHeight, p.y + bodyHeight + (main ? 18 : 10),
                        p.y + bodyHeight, p.y + bodyHeight - 3}, 6);
        g.setFill(top);
        g.fillRect(p.x, p.y, p.w, Math.max(18.0, p.h * 0.58));
        g.setStroke(rim);
        g.setLineWidth(main ? 6.0 : 4.0);
        g.strokeLine(p.x, p.y, p.x + p.w, p.y);
        g.setStroke(Color.web("#613026", 0.72));
        g.setLineWidth(3.0);
        for (double brickX = p.x + 55.0; brickX < p.x + p.w - 25.0; brickX += 120.0) {
            g.strokeLine(brickX, p.y + p.h * 0.58, brickX + 18.0, p.y + bodyHeight - 3.0);
        }

        renderRandom.setSeed((long) (p.x * 17 + p.y * 31));
        g.setStroke(Color.web("#FF6D00", 0.42));
        g.setLineWidth(2.2);
        int cracks = Math.max(2, (int) Math.min(10, p.w / 360.0));
        for (int i = 0; i < cracks; i++) {
            double x = p.x + 40 + renderRandom.nextDouble() * Math.max(1.0, p.w - 80.0);
            double y = p.y + 10 + renderRandom.nextDouble() * Math.max(1.0, p.h * 0.42);
            g.strokeLine(x, y, x + (renderRandom.nextDouble() - 0.5) * 130.0,
                    y + 8 + renderRandom.nextDouble() * 20.0);
        }
    }

    private void drawAshfallVent(GraphicsContext g, WindVent vent, double time, boolean ambientFx) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.60 + 0.40 * Math.sin(time * 2.8 + vent.x * 0.014) : 0.74;
        g.setStroke(Color.web("#FFB23E", 0.56 + pulse * 0.30));
        g.setLineWidth(7.0);
        g.strokePolyline(new double[]{vent.x + 24, centerX - 52, centerX, centerX + 58, vent.x + vent.w - 22},
                new double[]{vent.y + 8, vent.y - 8, vent.y + 13, vent.y - 7, vent.y + 8}, 5);
        g.setFill(Color.web("#FF641E", 0.10 + pulse * 0.08));
        g.fillPolygon(new double[]{centerX - vent.w * 0.24, centerX + vent.w * 0.24,
                        centerX + vent.w * 0.11, centerX - vent.w * 0.10},
                new double[]{vent.y - 2, vent.y - 2, vent.y - 180, vent.y - 155}, 4);
        g.setStroke(Color.web("#FFD06A", 0.28 + pulse * 0.22));
        g.setLineWidth(3.0);
        g.setLineDashes(18.0, 14.0);
        for (int stream = -2; stream <= 2; stream++) {
            double x = centerX + stream * vent.w * 0.09;
            double sway = ambientFx ? Math.sin(time * 1.7 + stream) * 18.0 : stream * 2.0;
            g.strokeLine(x, vent.y - 8, x + sway, vent.y - 138.0 - Math.abs(stream) * 14.0);
        }
        g.setLineDashes((double[]) null);
    }

    private void drawAshfallEmbers(GraphicsContext g, double time) {
        renderRandom.setSeed(0xE8BE_2511L);
        double verticalSpan = GROUND_Y - 140.0;
        for (int i = 0; i < 120; i++) {
            double x = (renderRandom.nextDouble() * WORLD_WIDTH + time * (26.0 + i % 8))
                    % (WORLD_WIDTH + 180.0) - 90.0;
            double rawY = renderRandom.nextDouble() * verticalSpan - time * (22.0 + i % 6);
            double y = 100.0 + ((rawY % verticalSpan) + verticalSpan) % verticalSpan;
            double drift = Math.sin(time * 0.9 + i) * 20.0;
            double size = 2.0 + renderRandom.nextDouble() * 5.0;
            g.setFill(Color.web(i % 9 == 0 ? "#8BE4E1" : "#FFB044", 0.42 + renderRandom.nextDouble() * 0.34));
            g.fillOval(x + drift, y, size, size * 1.5);
        }
    }

    private void drawAshfallEruptionColumns(GraphicsContext g, boolean ambientFx, double time) {
        for (int i = 0; i < ASHFALL_GEYSER_CENTER_X.length; i++) {
            int phase = ashfallEruptionPhase(i);
            double centerX = ASHFALL_GEYSER_CENTER_X[i];
            double baseY = ASHFALL_GEYSER_BASE_Y[i];
            double halfW = ASHFALL_GEYSER_HALF_W[i];
            double height = ASHFALL_GEYSER_HEIGHT[i];
            if (ashfallEruptionWarning(phase)) {
                double charge = phase / (double) ASHFALL_ERUPTION_WARNING_FRAMES;
                double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 8.0 + i * 1.7) : 0.55;
                double ringW = halfW * (1.25 + charge * 1.1 + pulse * 0.08);
                double ringH = 34.0 + charge * 28.0;
                g.setFill(Color.web("#FF3D00", 0.08 + charge * 0.13));
                g.fillRoundRect(centerX - halfW * 0.75, baseY - height * (0.32 + charge * 0.52),
                        halfW * 1.5, height * (0.32 + charge * 0.52), halfW, halfW);
                g.setStroke(Color.web(charge > 0.72 ? "#FFF176" : "#FF7043", 0.32 + charge * 0.52));
                g.setLineWidth(4.0 + charge * 5.0);
                g.strokeOval(centerX - ringW, baseY - ringH * 0.5, ringW * 2.0, ringH);
                g.setStroke(Color.web("#4DD0E1", 0.18 + charge * 0.22));
                g.setLineWidth(2.0);
                g.strokeOval(centerX - ringW * 0.62, baseY - ringH * 0.36, ringW * 1.24, ringH * 0.72);
            } else if (ashfallEruptionActive(phase)) {
                double active = (phase - ASHFALL_ERUPTION_WARNING_FRAMES) / (double) ASHFALL_ERUPTION_ACTIVE_FRAMES;
                double bloom = Math.sin(Math.PI * Math.clamp(active, 0.0, 1.0));
                double width = halfW * (1.45 + bloom * 0.35);
                double drawHeight = height * (0.82 + bloom * 0.18);
                g.setFill(Color.web("#FF3D00", 0.34));
                g.fillRoundRect(centerX - width, baseY - drawHeight, width * 2.0, drawHeight + 20.0, width, width);
                g.setFill(Color.web("#FFB300", 0.34));
                g.fillRoundRect(centerX - width * 0.55, baseY - drawHeight * 0.92,
                        width * 1.1, drawHeight * 0.92, width, width);
                g.setFill(Color.web("#FFF59D", 0.3 + bloom * 0.16));
                g.fillRoundRect(centerX - width * 0.25, baseY - drawHeight * 0.78,
                        width * 0.5, drawHeight * 0.72, width, width);
                g.setStroke(Color.web("#4DD0E1", 0.26));
                g.setLineWidth(5.0);
                g.strokeLine(centerX - width * 0.52, baseY - drawHeight * 0.86, centerX - width * 0.1, baseY - drawHeight * 0.18);
                g.strokeLine(centerX + width * 0.52, baseY - drawHeight * 0.86, centerX + width * 0.1, baseY - drawHeight * 0.18);
            }
        }
    }

    private void drawFrostbiteFjordArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        double waterY = FROSTBITE_MAIN_Y + 138.0;
        g.save();

        g.setFill(new LinearGradient(0, 0, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#02081B")),
                new Stop(0.34, Color.web("#0A2443")),
                new Stop(0.66, Color.web("#18516A")),
                new Stop(1.0, Color.web("#477D88"))));
        g.fillRect(-400, -300, WORLD_WIDTH + 800, WORLD_HEIGHT + 600);

        drawFrostbiteFjordAurora(g, time, ambientFx);
        drawFrostbiteFjordMoonAndStars(g, time, ambientFx);
        drawFrostbiteFjordWalls(g, waterY);

        g.setFill(new LinearGradient(0, waterY, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#0B3A52")),
                new Stop(0.24, Color.web("#05243B")),
                new Stop(1.0, Color.web("#010813"))));
        g.fillRect(0, waterY, WORLD_WIDTH, WORLD_HEIGHT - waterY);
        drawFrostbiteFjordWater(g, waterY, time, ambientFx);
        drawFrostbiteFjordShelfFoundations(g, waterY);
        drawFrostbiteFjordSupports(g);

        for (Platform platform : platforms) drawFrostbiteFjordPlatform(g, platform);
        drawFrostbiteSnowbanks(g);
        for (WindVent vent : windVents) drawFrostbiteFjordVent(g, vent, time, ambientFx);

        drawFrostbiteFjordForeground(g, waterY, time, ambientFx);
        if (ambientFx) drawFrostbiteFjordSnow(g, time);
        g.restore();
    }

    private void drawFrostbiteFjordAurora(GraphicsContext g, double time, boolean ambientFx) {
        Color[] colors = {
                Color.web("#63FFD5", 0.18), Color.web("#69CFFF", 0.14), Color.web("#B990FF", 0.12)
        };
        for (int band = 0; band < colors.length; band++) {
            int segments = 18;
            double[] xs = new double[(segments + 1) * 2];
            double[] ys = new double[(segments + 1) * 2];
            for (int i = 0; i <= segments; i++) {
                double t = i / (double) segments;
                double x = -260.0 + t * (WORLD_WIDTH + 520.0);
                double wave = Math.sin(t * 8.2 + band * 1.7 + time * (0.20 + band * 0.04)) * 74.0;
                double top = 170.0 + band * 96.0 + wave;
                double curtain = 390.0 + 115.0 * Math.sin(t * 5.3 + band * 0.9 + time * 0.13);
                xs[i] = x;
                ys[i] = top;
                xs[xs.length - 1 - i] = x + 38.0;
                ys[ys.length - 1 - i] = top + curtain;
            }
            g.setFill(colors[band]);
            g.fillPolygon(xs, ys, xs.length);
        }
    }

    private void drawFrostbiteFjordMoonAndStars(GraphicsContext g, double time, boolean ambientFx) {
        renderRandom.setSeed(0xF205_7B17L);
        for (int i = 0; i < 150; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double y = 55.0 + renderRandom.nextDouble() * 960.0;
            double size = 1.3 + renderRandom.nextDouble() * 3.4;
            double pulse = ambientFx ? 0.72 + Math.sin(time * 1.2 + i * 0.83) * 0.28 : 0.82;
            g.setFill(Color.web(i % 12 == 0 ? "#CCFFF1" : "#D9F5FF",
                    (0.20 + renderRandom.nextDouble() * 0.46) * pulse));
            g.fillOval(x, y, size, size);
        }

        double moonX = 4725.0;
        double moonY = 270.0;
        g.setFill(Color.web("#A9E8F4", 0.08));
        g.fillOval(moonX - 145, moonY - 145, 500, 500);
        g.setFill(Color.web("#DFFAFF", 0.18));
        g.fillOval(moonX - 82, moonY - 82, 374, 374);
        g.setFill(Color.web("#F4FCFF", 0.94));
        g.fillOval(moonX, moonY, 236, 236);
        g.setFill(Color.web("#B8D7E3", 0.28));
        g.fillOval(moonX + 48, moonY + 38, 64, 42);
        g.fillOval(moonX + 132, moonY + 112, 42, 30);
    }

    private void drawFrostbiteFjordWalls(GraphicsContext g, double waterY) {
        g.setFill(Color.web("#17364B", 0.86));
        g.fillPolygon(new double[]{0, 0, 720, 1190, 1570, 1930, 2210, 0},
                new double[]{560, waterY, waterY, 2050, 1680, 1910, waterY, waterY}, 8);
        g.fillPolygon(new double[]{WORLD_WIDTH, WORLD_WIDTH, 5280, 4810, 4430, 4070, 3790, WORLD_WIDTH},
                new double[]{560, waterY, waterY, 2050, 1680, 1910, waterY, waterY}, 8);

        g.setFill(Color.web("#214F63", 0.94));
        g.fillPolygon(new double[]{0, 0, 410, 790, 1060, 1300, 1510, 920, 0},
                new double[]{930, waterY + 90, waterY + 90, 2140, 1810, 2050, waterY + 90, waterY + 90, waterY + 90}, 9);
        g.fillPolygon(new double[]{WORLD_WIDTH, WORLD_WIDTH, 5590, 5210, 4940, 4700, 4490, 5080, WORLD_WIDTH},
                new double[]{930, waterY + 90, waterY + 90, 2140, 1810, 2050, waterY + 90, waterY + 90, waterY + 90}, 9);

        g.setFill(Color.web("#94D7E3", 0.26));
        g.fillPolygon(new double[]{350, 690, 1020, 800, 520},
                new double[]{waterY + 45, 1930, waterY - 80, waterY + 70, waterY + 100}, 5);
        g.fillPolygon(new double[]{5650, 5310, 4980, 5200, 5480},
                new double[]{waterY + 45, 1930, waterY - 80, waterY + 70, waterY + 100}, 5);

        g.setStroke(Color.web("#C6F4FF", 0.24));
        g.setLineWidth(10.0);
        g.strokePolyline(new double[]{250, 690, 1030, 1310, 1510},
                new double[]{waterY + 20, 1945, 1810, 2050, waterY + 20}, 5);
        g.strokePolyline(new double[]{5750, 5310, 4970, 4690, 4490},
                new double[]{waterY + 20, 1945, 1810, 2050, waterY + 20}, 5);
    }

    private void drawFrostbiteFjordWater(GraphicsContext g, double waterY, double time, boolean ambientFx) {
        g.setStroke(Color.web("#78D9EE", 0.28));
        g.setLineWidth(3.0);
        renderRandom.setSeed(0xF10A_7E25L);
        for (int row = 0; row < 15; row++) {
            double y = waterY + 22.0 + row * 43.0;
            for (int segment = 0; segment < 10; segment++) {
                double x = 80.0 + segment * 620.0 + renderRandom.nextDouble() * 170.0;
                double width = 110.0 + renderRandom.nextDouble() * 270.0;
                double shift = ambientFx ? Math.sin(time * 0.7 + row * 0.61 + segment) * 18.0 : 0.0;
                g.strokeLine(x + shift, y, Math.min(WORLD_WIDTH - 45.0, x + width + shift), y + (segment % 3 - 1) * 4.0);
            }
        }

        g.setFill(Color.web("#CFF8FF", 0.12));
        for (int row = 0; row < 7; row++) {
            double y = waterY + 48.0 + row * 72.0;
            double width = 360.0 - row * 28.0;
            double x = 4835.0 + row * 18.0;
            g.fillRoundRect(x, y, width, 9.0, 9.0, 9.0);
        }
    }

    private void drawFrostbiteFjordShelfFoundations(GraphicsContext g, double waterY) {
        g.setFill(new LinearGradient(0, FROSTBITE_MAIN_Y, 0, waterY + 330, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#79D4E8")),
                new Stop(0.40, Color.web("#28718D")),
                new Stop(1.0, Color.web("#092C49"))));
        g.fillPolygon(new double[]{FROSTBITE_MAIN_X + 25, FROSTBITE_MAIN_X + FROSTBITE_MAIN_W - 25,
                        FROSTBITE_MAIN_X + FROSTBITE_MAIN_W - 210, FROSTBITE_MAIN_X + 2860,
                        FROSTBITE_MAIN_X + 2360, FROSTBITE_MAIN_X + 1740, FROSTBITE_MAIN_X + 970,
                        FROSTBITE_MAIN_X + 220},
                new double[]{FROSTBITE_MAIN_Y + 36, FROSTBITE_MAIN_Y + 36, waterY + 170,
                        waterY + 250, waterY + 190, waterY + 310, waterY + 210, waterY + 145}, 8);

        drawFrostbiteFjordFloe(g, FROSTBITE_MAIN_X - 500, FROSTBITE_MAIN_Y + 154, 610, waterY + 285);
        drawFrostbiteFjordFloe(g, FROSTBITE_MAIN_X + FROSTBITE_MAIN_W - 90,
                FROSTBITE_MAIN_Y + 140, 680, waterY + 270);

        g.setStroke(Color.web("#BCEFFF", 0.34));
        g.setLineWidth(4.0);
        for (int i = 0; i < 12; i++) {
            double x = FROSTBITE_MAIN_X + 220 + i * 275.0;
            g.strokeLine(x, FROSTBITE_MAIN_Y + 75, x + (i % 2 == 0 ? 85 : -70), waterY + 130 + i % 3 * 38);
        }
    }

    private void drawFrostbiteFjordFloe(GraphicsContext g, double x, double topY, double width, double bottomY) {
        g.setFill(Color.web("#2B7893"));
        g.fillPolygon(new double[]{x, x + width, x + width * 0.82, x + width * 0.58, x + width * 0.22},
                new double[]{topY, topY, bottomY - 18, bottomY, bottomY - 52}, 5);
        g.setFill(Color.web("#9BE4F1", 0.42));
        g.fillPolygon(new double[]{x + 24, x + width * 0.48, x + width * 0.22},
                new double[]{topY + 14, topY + 14, bottomY - 52}, 3);
    }

    private void drawFrostbiteFjordSupports(GraphicsContext g) {
        drawFrostbiteFjordIcefall(g, 1520, FROSTBITE_MAIN_Y - 260, 500, FROSTBITE_MAIN_Y + 20);
        drawFrostbiteFjordIcefall(g, 3980, FROSTBITE_MAIN_Y - 260, 500, FROSTBITE_MAIN_Y + 20);
        drawFrostbiteFjordIcefall(g, 2630, FROSTBITE_MAIN_Y - 440, 740, FROSTBITE_MAIN_Y + 30);
        drawFrostbiteFjordIcefall(g, 1840, FROSTBITE_MAIN_Y - 680, 260, FROSTBITE_MAIN_Y - 245);
        drawFrostbiteFjordIcefall(g, 3900, FROSTBITE_MAIN_Y - 680, 260, FROSTBITE_MAIN_Y - 245);
        drawFrostbiteFjordIcefall(g, 2820, FROSTBITE_MAIN_Y - 830, 360, FROSTBITE_MAIN_Y - 420);
    }

    private void drawFrostbiteFjordIcefall(GraphicsContext g, double x, double y, double width, double bottomY) {
        g.setFill(Color.web("#17506D", 0.86));
        g.fillPolygon(new double[]{x, x + width, x + width * 0.86, x + width * 0.58,
                        x + width * 0.30, x + width * 0.10},
                new double[]{y, y, bottomY - 45, bottomY, bottomY - 20, bottomY - 82}, 6);
        g.setFill(Color.web("#8CD9E9", 0.30));
        g.fillPolygon(new double[]{x + width * 0.08, x + width * 0.38, x + width * 0.29},
                new double[]{y + 10, y + 10, bottomY - 30}, 3);
        g.setStroke(Color.web("#D9F8FF", 0.26));
        g.setLineWidth(4.0);
        g.strokeLine(x + width * 0.72, y + 12, x + width * 0.58, bottomY - 18);
    }

    private void drawFrostbiteFjordPlatform(GraphicsContext g, Platform platform) {
        boolean main = Math.abs(platform.x - FROSTBITE_MAIN_X) < 2.0
                && Math.abs(platform.w - FROSTBITE_MAIN_W) < 2.0;
        double bodyHeight = platform.h + (main ? 22.0 : 15.0);
        g.setFill(new LinearGradient(0, platform.y, 0, platform.y + bodyHeight, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#C8F4FA")),
                new Stop(0.26, Color.web("#70C9DF")),
                new Stop(1.0, Color.web("#1A5876"))));
        g.fillPolygon(new double[]{platform.x, platform.x + platform.w, platform.x + platform.w - 18,
                        platform.x + platform.w * 0.72, platform.x + platform.w * 0.46, platform.x + 16},
                new double[]{platform.y, platform.y, platform.y + bodyHeight,
                        platform.y + bodyHeight + (main ? 20 : 10), platform.y + bodyHeight,
                        platform.y + bodyHeight - 4}, 6);
        g.setFill(Color.web("#F4FDFF"));
        g.fillPolygon(new double[]{platform.x - 8, platform.x + platform.w + 7,
                        platform.x + platform.w - 10, platform.x + platform.w * 0.66,
                        platform.x + platform.w * 0.40, platform.x + 12},
                new double[]{platform.y - 11, platform.y - 11, platform.y + 7,
                        platform.y + 3, platform.y + 9, platform.y + 5}, 6);
        g.setStroke(Color.web("#D7FAFF", 0.92));
        g.setLineWidth(main ? 5.0 : 3.5);
        g.strokeLine(platform.x, platform.y, platform.x + platform.w, platform.y);

        renderRandom.setSeed(Double.doubleToLongBits(platform.x * 11.0 + platform.y * 5.0 + platform.w));
        g.setStroke(Color.web("#144C68", 0.48));
        g.setLineWidth(2.2);
        int cracks = Math.clamp((int) Math.round(platform.w / 240.0), 1, main ? 15 : 5);
        for (int i = 0; i < cracks; i++) {
            double x = platform.x + 30.0 + renderRandom.nextDouble() * Math.max(20.0, platform.w - 60.0);
            double y = platform.y + 12.0 + renderRandom.nextDouble() * Math.max(10.0, platform.h * 0.45);
            double direction = renderRandom.nextBoolean() ? 1.0 : -1.0;
            g.strokeLine(x, y, x + direction * (24.0 + renderRandom.nextDouble() * 48.0), y + 18.0);
        }

        if (!main) {
            g.setFill(Color.web("#C7F2FA", 0.78));
            int icicles = Math.clamp((int) Math.round(platform.w / 150.0), 2, 7);
            for (int i = 0; i < icicles; i++) {
                double x = platform.x + 24.0 + i * (platform.w - 48.0) / Math.max(1, icicles - 1);
                double height = 18.0 + (i * 23 % 34);
                g.fillPolygon(new double[]{x - 8, x + 8, x},
                        new double[]{platform.y + bodyHeight - 2, platform.y + bodyHeight - 2,
                                platform.y + bodyHeight + height}, 3);
            }
        }
    }

    private void drawFrostbiteFjordVent(GraphicsContext g, WindVent vent, double time, boolean ambientFx) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.58 + 0.42 * Math.sin(time * 3.0 + vent.x * 0.013) : 0.72;
        g.setStroke(Color.web("#092E49", 0.86));
        g.setLineWidth(7.0);
        g.strokePolyline(new double[]{vent.x + 32, centerX - 52, centerX, centerX + 62, vent.x + vent.w - 28},
                new double[]{vent.y + 10, vent.y - 6, vent.y + 14, vent.y - 8, vent.y + 8}, 5);
        g.setStroke(Color.web("#E6FCFF", 0.34 + pulse * 0.32));
        g.setLineWidth(3.0);
        g.setLineDashes(20.0, 16.0);
        for (int stream = -2; stream <= 2; stream++) {
            double startX = centerX + stream * vent.w * 0.095;
            double sway = ambientFx ? Math.sin(time * 1.8 + stream) * 22.0 : stream * 3.0;
            g.strokeLine(startX, vent.y - 12, startX + sway, vent.y - 150.0 - Math.abs(stream) * 18.0);
        }
        g.setLineDashes((double[]) null);
        g.setFill(Color.web("#D8F8FF", 0.10 + pulse * 0.08));
        g.fillPolygon(new double[]{centerX - vent.w * 0.22, centerX + vent.w * 0.22,
                        centerX + vent.w * 0.10, centerX - vent.w * 0.08},
                new double[]{vent.y - 5, vent.y - 5, vent.y - 190, vent.y - 170}, 4);
    }

    private void drawFrostbiteFjordForeground(GraphicsContext g, double waterY, double time, boolean ambientFx) {
        renderRandom.setSeed(0xF10E_5EEDL);
        for (int i = 0; i < 13; i++) {
            double x = 90.0 + renderRandom.nextDouble() * (WORLD_WIDTH - 180.0);
            double y = waterY + 120.0 + renderRandom.nextDouble() * 520.0;
            double width = 80.0 + renderRandom.nextDouble() * 220.0;
            double drift = ambientFx ? Math.sin(time * 0.24 + i * 0.91) * 18.0 : 0.0;
            g.setFill(Color.web("#6DB9CD", 0.20 + renderRandom.nextDouble() * 0.12));
            g.fillPolygon(new double[]{x + drift, x + width + drift, x + width * 0.78 + drift, x + width * 0.18 + drift},
                    new double[]{y, y + 5, y + 32, y + 25}, 4);
            g.setStroke(Color.web("#C5F4FC", 0.25));
            g.setLineWidth(2.0);
            g.strokeLine(x + drift, y, x + width + drift, y + 5);
        }
    }

    private void drawFrostbiteFjordSnow(GraphicsContext g, double time) {
        renderRandom.setSeed(0x5A0F_7F11L);
        g.setFill(Color.web("#FFFFFF", 0.58));
        for (int i = 0; i < 120; i++) {
            double x = (renderRandom.nextDouble() * WORLD_WIDTH + time * (20.0 + i % 6)) % (WORLD_WIDTH + 180.0) - 90.0;
            double y = 90.0 + (renderRandom.nextDouble() * (WORLD_HEIGHT - 90.0) + time * (24.0 + i % 5))
                    % (WORLD_HEIGHT - 90.0);
            double drift = Math.sin(time * 0.65 + i) * 18.0;
            double size = 2.0 + renderRandom.nextDouble() * 4.8;
            g.fillOval(x + drift, y, size, size);
        }
    }

    private void drawLastIceShelfArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        g.save();
        g.setFill(new LinearGradient(0, 0, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#02061A")),
                new Stop(0.38, Color.web("#10284B")),
                new Stop(0.70, Color.web("#2C6A82")),
                new Stop(1.0, Color.web("#5D91A0"))));
        g.fillRect(-500, -300, WORLD_WIDTH + 1_000, WORLD_HEIGHT + 600);

        drawLastIceShelfAurora(g, time, ambientFx);
        drawLastIceShelfMoon(g, time, ambientFx);

        renderRandom.setSeed(0x1CE5_11E1L);
        for (int i = 0; i < 140; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double y = 60.0 + renderRandom.nextDouble() * (LAST_ICE_MAIN_Y - 640.0);
            double size = 1.5 + renderRandom.nextDouble() * 4.2;
            double pulse = ambientFx ? 0.70 + Math.sin(time * 1.1 + i * 0.79) * 0.30 : 0.84;
            g.setFill(Color.web(i % 13 == 0 ? "#E6FFF2" : "#D8F5FF",
                    (0.18 + renderRandom.nextDouble() * 0.38) * pulse));
            g.fillOval(x, y, size, size);
        }

        drawLastIceShelfDistantCliffs(g);
        double waterY = LAST_ICE_MAIN_Y + 260;
        g.setFill(new LinearGradient(0, waterY, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#082B46", 0.98)),
                new Stop(0.28, Color.web("#03182B", 0.99)),
                new Stop(1.0, Color.web("#010713"))));
        g.fillRect(0, waterY, WORLD_WIDTH, WORLD_HEIGHT - waterY);
        drawLastIceShelfWater(g, waterY, time, ambientFx);
        drawLastIceShelfGlacierBase(g, waterY);
        drawLastIceShelfFortressSupports(g, waterY);

        for (Platform p : platforms) drawLastIceShelfPlatform(g, p, time, ambientFx);
        for (WindVent vent : windVents) drawLastIceShelfVent(g, vent, time, ambientFx);

        drawLastIceShelfForeground(g, waterY, time, ambientFx);
        if (ambientFx) drawLastIceShelfSnow(g, time);
        g.restore();
    }

    private void drawLastIceShelfAurora(GraphicsContext g, double time, boolean ambientFx) {
        double sway = ambientFx ? Math.sin(time * 0.20) * 85.0 : 0.0;
        Color[] colors = {
                Color.web("#58F1D1", 0.16),
                Color.web("#7BB8FF", 0.14),
                Color.web("#B68CFF", 0.11)
        };
        for (int band = 0; band < colors.length; band++) {
            double offset = band * 155.0;
            g.setFill(colors[band]);
            g.beginPath();
            g.moveTo(-240, 340 + offset);
            g.bezierCurveTo(980 + sway, 30 + offset, 1_720 - sway, 610 + offset,
                    2_930, 245 + offset);
            g.bezierCurveTo(4_070 + sway, -30 + offset, 5_070 - sway, 610 + offset,
                    WORLD_WIDTH + 260, 170 + offset);
            g.lineTo(WORLD_WIDTH + 260, 350 + offset);
            g.bezierCurveTo(5_060 - sway, 770 + offset, 4_080 + sway, 170 + offset,
                    2_930, 470 + offset);
            g.bezierCurveTo(1_720 - sway, 810 + offset, 980 + sway, 260 + offset,
                    -240, 570 + offset);
            g.closePath();
            g.fill();
        }

        g.setStroke(Color.web("#C9FFF2", 0.11));
        g.setLineWidth(7.0);
        g.beginPath();
        g.moveTo(-180, 470);
        g.bezierCurveTo(1_080 + sway, 120, 1_960 - sway, 710, 3_050, 335);
        g.bezierCurveTo(4_240 + sway, 30, 5_120 - sway, 680, WORLD_WIDTH + 180, 275);
        g.stroke();
    }

    private void drawLastIceShelfMoon(GraphicsContext g, double time, boolean ambientFx) {
        double moonX = 4_830.0;
        double moonY = 300.0;
        double pulse = ambientFx ? 0.92 + Math.sin(time * 0.31) * 0.08 : 0.96;
        g.setFill(new RadialGradient(0, 0, moonX, moonY, 490.0, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#D9FAFF", 0.20 * pulse)),
                new Stop(0.48, Color.web("#74E2E1", 0.08 * pulse)),
                new Stop(1.0, Color.TRANSPARENT)));
        g.fillOval(moonX - 490, moonY - 490, 980, 980);
        g.setFill(Color.web("#E5FAFF", 0.90));
        g.fillOval(moonX - 150, moonY - 150, 300, 300);
        g.setFill(Color.web("#A8D7E2", 0.20));
        g.fillOval(moonX - 82, moonY - 55, 62, 42);
        g.fillOval(moonX + 28, moonY + 38, 76, 48);
    }

    private void drawLastIceShelfDistantCliffs(GraphicsContext g) {
        double baseY = LAST_ICE_MAIN_Y + 300.0;
        Color far = Color.web("#102D4A", 0.72);
        Color near = Color.web("#1B4A64", 0.68);
        for (int layer = 0; layer < 2; layer++) {
            Color color = layer == 0 ? far : near;
            double spacing = layer == 0 ? 760.0 : 980.0;
            double shift = layer == 0 ? -220.0 : 180.0;
            g.setFill(color);
            int count = (int) Math.ceil(WORLD_WIDTH / spacing) + 2;
            for (int i = -1; i < count; i++) {
                double x = shift + i * spacing;
                double height = (layer == 0 ? 610.0 : 450.0) + Math.floorMod(i, 3) * 110.0;
                double width = spacing * 0.88;
                g.fillPolygon(
                        new double[]{x, x + width * 0.18, x + width * 0.42,
                                x + width * 0.60, x + width, x + width * 0.82},
                        new double[]{baseY, baseY - height * 0.54, baseY - height,
                                baseY - height * 0.62, baseY, baseY + 20}, 6);
                g.setFill(Color.web("#70C7D7", layer == 0 ? 0.08 : 0.11));
                g.fillPolygon(
                        new double[]{x + width * 0.18, x + width * 0.42, x + width * 0.34},
                        new double[]{baseY - height * 0.54, baseY - height, baseY - 20}, 3);
                g.setFill(color);
            }
        }
        g.setFill(Color.web("#06192C", 0.76));
        g.fillPolygon(
                new double[]{0, 620, 1_130, 1_730, 2_320, 3_020,
                        3_650, 4_290, 4_920, 5_470, WORLD_WIDTH},
                new double[]{baseY, baseY - 270, baseY - 80, baseY - 350,
                        baseY - 120, baseY - 420, baseY - 150, baseY - 330,
                        baseY - 100, baseY - 280, baseY}, 11);
    }

    private void drawLastIceShelfWater(GraphicsContext g, double waterY,
                                       double time, boolean ambientFx) {
        g.setStroke(Color.web("#70CFE3", 0.20));
        g.setLineWidth(3.0);
        for (int row = 0; row < 20; row++) {
            double y = waterY + 28 + row * 58.0;
            double shift = ambientFx ? Math.sin(time * 0.72 + row * 0.67) * 38.0 : 0.0;
            for (int segment = 0; segment < 7; segment++) {
                double x = 55.0 + segment * 905.0 + (row % 2) * 110.0 + shift;
                double width = 330.0 + ((row + segment) % 3) * 90.0;
                g.strokeLine(x, y, Math.min(WORLD_WIDTH - 45.0, x + width), y + 4.0);
            }
        }

        double moonX = 4_830.0;
        g.setFill(Color.web("#BCEBF1", 0.045));
        g.fillPolygon(new double[]{moonX - 120, moonX + 120, moonX + 420, moonX - 390},
                new double[]{waterY, waterY, WORLD_HEIGHT, WORLD_HEIGHT}, 4);
        g.setStroke(Color.web("#D4FAFF", 0.15));
        g.setLineWidth(5.0);
        for (int i = 0; i < 15; i++) {
            double width = 70.0 + i * 25.0;
            double y = waterY + 45.0 + i * 72.0;
            double drift = ambientFx ? Math.sin(time * 0.64 + i) * 20.0 : 0.0;
            g.strokeLine(moonX - width + drift, y, moonX + width + drift, y);
        }
    }

    private void drawLastIceShelfGlacierBase(GraphicsContext g, double waterY) {
        // One continuous above-water cliff joins both recovery shelves to the
        // main fighting span. The larger translucent body below the waterline
        // communicates real iceberg mass without suggesting a hidden floor.
        g.setFill(new LinearGradient(0, LAST_ICE_MAIN_Y, 0, waterY + 160.0, false,
                CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#8DE1EE")),
                new Stop(0.38, Color.web("#397E9A")),
                new Stop(1.0, Color.web("#123A5B"))));
        g.fillPolygon(
                new double[]{520, 1_000, 5_000, 5_840, 5_680, 5_170,
                        4_670, 3_760, 3_000, 2_230, 1_350, 760},
                new double[]{LAST_ICE_MAIN_Y + 155, LAST_ICE_MAIN_Y + 52,
                        LAST_ICE_MAIN_Y + 52, LAST_ICE_MAIN_Y + 155,
                        waterY + 185, waterY + 215, waterY + 255,
                        waterY + 335, waterY + 440, waterY + 340,
                        waterY + 245, waterY + 200}, 12);
        g.setFill(Color.web("#0E385A", 0.58));
        g.fillPolygon(
                new double[]{760, 1_350, 2_230, 3_000, 3_760, 4_670, 5_170, 5_680,
                        5_310, 4_410, 3_640, 3_000, 2_270, 1_430, 690},
                new double[]{waterY + 180, waterY + 230, waterY + 330, waterY + 430,
                        waterY + 325, waterY + 240, waterY + 205, waterY + 180,
                        waterY + 620, waterY + 820, waterY + 1_020, waterY + 1_180,
                        waterY + 1_000, waterY + 790, waterY + 590}, 15);

        g.setFill(Color.web("#65BDD2", 0.28));
        g.fillPolygon(
                new double[]{1_000, 2_230, 3_000, 2_270, 1_430, 760},
                new double[]{LAST_ICE_MAIN_Y + 65, waterY + 330, waterY + 430,
                        waterY + 1_000, waterY + 790, waterY + 180}, 6);
        g.setStroke(Color.web("#9AE7F1", 0.22));
        g.setLineWidth(7.0);
        g.strokeLine(1_140, LAST_ICE_MAIN_Y + 100, 2_270, waterY + 960);
        g.strokeLine(4_860, LAST_ICE_MAIN_Y + 100, 3_640, waterY + 990);
        g.strokeLine(3_000, LAST_ICE_MAIN_Y + 120, 3_000, waterY + 1_120);

        g.setStroke(Color.web("#D8FAFF", 0.34));
        g.setLineWidth(10.0);
        g.strokeLine(500, waterY, 5_860, waterY);
    }

    private void drawLastIceShelfFortressSupports(GraphicsContext g, double waterY) {
        for (Platform p : platforms) {
            if (p.y >= LAST_ICE_MAIN_Y - 40.0) continue;
            boolean melting = classicLastIceMeltPlatforms.contains(p);
            if (p.y <= LAST_ICE_MAIN_Y - 850.0) {
                drawLastIceShelfArchSupport(g, p, melting);
            } else {
                drawLastIceShelfCliffSupport(g, p, waterY, melting);
            }
        }
    }

    private void drawLastIceShelfCliffSupport(GraphicsContext g, Platform p,
                                              double waterY, boolean melting) {
        double centerX = p.x + p.w * 0.5;
        double bottomY = LAST_ICE_MAIN_Y + 84.0;
        double inset = Math.min(190.0, p.w * 0.22);
        Color top = melting ? Color.web("#76CADD", 0.90) : Color.web("#72D6E5", 0.92);
        Color bottom = melting ? Color.web("#244C71", 0.84) : Color.web("#1A5775", 0.88);
        g.setFill(new LinearGradient(0, p.y, 0, bottomY, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, top), new Stop(1.0, bottom)));
        g.fillPolygon(
                new double[]{p.x + 22, p.x + p.w - 22, centerX + inset,
                        centerX + inset * 0.30, centerX - inset * 0.38, centerX - inset},
                new double[]{p.y + p.h * 0.40, p.y + p.h * 0.40, bottomY - 45,
                        bottomY, bottomY - 20, bottomY - 52}, 6);
        g.setStroke(Color.web("#B6F3F7", melting ? 0.20 : 0.30));
        g.setLineWidth(5.0);
        g.strokeLine(p.x + p.w * 0.30, p.y + p.h, centerX - inset * 0.26, bottomY - 28);
        g.strokeLine(p.x + p.w * 0.70, p.y + p.h, centerX + inset * 0.22, bottomY - 18);

        if (Math.abs(centerX - WORLD_WIDTH * 0.5) < 100.0) {
            g.setFill(Color.web("#061A2D", 0.62));
            g.fillOval(centerX - 190, p.y + 175, 380, Math.max(220.0, bottomY - p.y - 245));
            g.setStroke(Color.web("#75D7E5", 0.22));
            g.setLineWidth(9.0);
            g.strokeArc(centerX - 190, p.y + 175, 380,
                    Math.max(220.0, bottomY - p.y - 245), 0, 180, ArcType.OPEN);
        }
    }

    private void drawLastIceShelfArchSupport(GraphicsContext g, Platform p, boolean melting) {
        double centerX = p.x + p.w * 0.5;
        boolean west = centerX < WORLD_WIDTH * 0.5;
        double outerAnchorX = west ? 1_600.0 : 4_400.0;
        double innerAnchorX = west ? 2_670.0 : 3_330.0;
        double anchorY = LAST_ICE_MAIN_Y - 300.0;
        Color ice = melting ? Color.web("#4E94B7", 0.80) : Color.web("#5AB7CE", 0.88);
        g.setFill(ice);
        g.fillPolygon(
                new double[]{p.x + 30, p.x + p.w * 0.36, outerAnchorX - 70, outerAnchorX + 105},
                new double[]{p.y + p.h * 0.45, p.y + p.h * 0.45, anchorY, anchorY}, 4);
        g.fillPolygon(
                new double[]{p.x + p.w * 0.64, p.x + p.w - 30,
                        innerAnchorX - 105, innerAnchorX + 70},
                new double[]{p.y + p.h * 0.45, p.y + p.h * 0.45, anchorY - 145, anchorY - 145}, 4);
        g.setStroke(Color.web("#C6F8FA", melting ? 0.22 : 0.34));
        g.setLineWidth(6.0);
        g.strokeLine(p.x + p.w * 0.22, p.y + p.h,
                outerAnchorX + (west ? 30 : -30), anchorY);
        g.strokeLine(p.x + p.w * 0.78, p.y + p.h,
                innerAnchorX + (west ? -30 : 30), anchorY - 145);
    }

    private void drawLastIceShelfPlatform(GraphicsContext g, Platform p,
                                          double time, boolean ambientFx) {
        boolean main = Math.abs(p.x - LAST_ICE_MAIN_X) < 1.0
                && Math.abs(p.w - LAST_ICE_MAIN_W) < 1.0;
        boolean melting = classicLastIceMeltPlatforms.contains(p);
        Color side = melting ? Color.web("#245071") : Color.web("#165774");
        Color faceTop = melting ? Color.web("#70C6D8") : Color.web("#7CE0EC");
        Color faceBottom = melting ? Color.web("#397D9B") : Color.web("#3C91A9");
        Color rim = melting ? Color.web("#D9F4FF") : Color.web("#EEFEFF");

        g.setFill(side);
        g.fillPolygon(
                new double[]{p.x + 8, p.x + p.w - 8, p.x + p.w - 34,
                        p.x + p.w * 0.56, p.x + p.w * 0.44, p.x + 34},
                new double[]{p.y + 18, p.y + 18, p.y + p.h + (main ? 58 : 34),
                        p.y + p.h + (main ? 76 : 46), p.y + p.h + (main ? 68 : 42),
                        p.y + p.h + (main ? 54 : 32)}, 6);
        g.setFill(new LinearGradient(0, p.y, 0, p.y + p.h, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, faceTop), new Stop(1.0, faceBottom)));
        g.fillRoundRect(p.x, p.y, p.w, p.h, 18, 18);
        g.setFill(Color.web("#F5FEFF", melting ? 0.82 : 0.94));
        g.fillRoundRect(p.x + 9, p.y - 12, p.w - 18,
                Math.max(20.0, p.h * 0.34), 14, 14);
        g.setFill(Color.web("#B9EEF5", 0.52));
        g.fillRoundRect(p.x + 22, p.y + p.h * 0.33,
                Math.max(20.0, p.w - 44), Math.max(10.0, p.h * 0.22), 10, 10);
        g.setStroke(rim.deriveColor(0, 1, 1, 0.88));
        g.setLineWidth(main ? 5.5 : 4.2);
        g.strokeRoundRect(p.x + 2.5, p.y + 2.5, p.w - 5, p.h - 5, 16, 16);

        renderRandom.setSeed(Double.doubleToLongBits(p.x * 13.0 + p.y * 23.0 + p.w * 5.0));
        g.setStroke(Color.web(melting ? "#4D5E9A" : "#17617B", melting ? 0.62 : 0.46));
        g.setLineWidth(melting ? 3.6 : 2.6);
        int cracks = Math.max(2, Math.min(14, (int) (p.w / 230.0)));
        for (int i = 0; i < cracks; i++) {
            double x = p.x + 30 + renderRandom.nextDouble() * Math.max(1.0, p.w - 60);
            double y = p.y + 11 + renderRandom.nextDouble() * Math.max(8.0, p.h * 0.42);
            double direction = renderRandom.nextBoolean() ? 1.0 : -1.0;
            g.strokeLine(x, y, x + direction * 28, y + 20);
            g.strokeLine(x + direction * 28, y + 20,
                    x + direction * 12, y + Math.min(p.h - 4, 42));
        }

        if (melting) {
            double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 1.3 + p.x * 0.01) : 0.58;
            g.setFill(Color.web("#C8F7FF", 0.55 + pulse * 0.22));
            int drips = Math.max(3, Math.min(8, (int) (p.w / 120.0)));
            for (int i = 0; i < drips; i++) {
                double x = p.x + (i + 0.55) * p.w / drips;
                double length = 30.0 + (i % 3) * 24.0 + pulse * 12.0;
                g.fillPolygon(new double[]{x - 8, x + 8, x},
                        new double[]{p.y + p.h + 18, p.y + p.h + 18,
                                p.y + p.h + 18 + length}, 3);
            }
        }

        if (p.signText != null) {
            g.setTextAlign(TextAlignment.CENTER);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 25));
            g.setFill(Color.web("#E8FDFF", 0.82));
            g.fillText(p.signText, p.x + p.w * 0.5,
                    p.y + Math.min(67.0, p.h * 0.70));
        }
    }

    private void drawLastIceShelfVent(GraphicsContext g, WindVent vent,
                                      double time, boolean ambientFx) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 2.1 + vent.x * 0.011) : 0.58;
        g.setFill(Color.web("#A5F4FF", 0.06 + pulse * 0.07));
        g.fillPolygon(
                new double[]{centerX - 95, centerX - 34, centerX, centerX + 34, centerX + 95},
                new double[]{vent.y + 30, vent.y - 145, vent.y - 245, vent.y - 145, vent.y + 30}, 5);
        g.setStroke(Color.web("#D9FFFF", 0.28 + pulse * 0.24));
        g.setLineWidth(5.0);
        g.strokeLine(centerX - 88, vent.y + 8, centerX - 28, vent.y - 12);
        g.strokeLine(centerX - 28, vent.y - 12, centerX + 10, vent.y + 13);
        g.strokeLine(centerX + 10, vent.y + 13, centerX + 78, vent.y - 7);
        for (int ring = 0; ring < 3; ring++) {
            double width = 100.0 + ring * 66.0 + pulse * 10.0;
            g.strokeArc(centerX - width * 0.5, vent.y - 68 - ring * 74.0,
                    width, 50.0 + ring * 13.0, 18, 144, ArcType.OPEN);
        }
    }

    private void drawLastIceShelfForeground(GraphicsContext g, double waterY,
                                             double time, boolean ambientFx) {
        g.setFill(Color.web("#0B2841", 0.88));
        for (int i = -1; i < 12; i++) {
            double x = i * 620.0 + (i % 2) * 80.0;
            double drift = ambientFx ? Math.sin(time * 0.37 + i) * 18.0 : 0.0;
            double y = waterY + 620.0 + (i % 3) * 95.0;
            g.fillPolygon(
                    new double[]{x + drift, x + 120 + drift, x + 250 + drift,
                            x + 430 + drift, x + 570 + drift},
                    new double[]{y + 45, y - 26, y + 8, y - 42, y + 54}, 5);
        }
        g.setStroke(Color.web("#80DDE8", 0.12));
        g.setLineWidth(4.0);
        for (int i = 0; i < 9; i++) {
            double y = waterY + 540.0 + i * 86.0;
            g.strokeLine(60 + (i % 2) * 140, y, WORLD_WIDTH - 60 - (i % 3) * 120, y + 4);
        }
    }

    private void drawLastIceShelfSnow(GraphicsContext g, double time) {
        renderRandom.setSeed(0x5A0F_1CE5L);
        for (int i = 0; i < 105; i++) {
            double baseX = renderRandom.nextDouble() * (WORLD_WIDTH + 360.0) - 180.0;
            double speed = 28.0 + renderRandom.nextDouble() * 42.0;
            double x = baseX + Math.sin(time * 0.52 + i) * 34.0;
            double y = 35.0 + (renderRandom.nextDouble() * WORLD_HEIGHT + time * speed + i * 29.0)
                    % Math.max(1.0, WORLD_HEIGHT - 35.0);
            double size = 2.0 + renderRandom.nextDouble() * 4.6;
            g.setFill(Color.web("#F1FDFF", 0.30 + renderRandom.nextDouble() * 0.42));
            g.fillOval(x, y, size, size);
        }
    }

    private void drawStillwaterMarshArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        g.save();
        g.setFill(new LinearGradient(0, 0, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#020813")),
                new Stop(0.40, Color.web("#0B2830")),
                new Stop(0.72, Color.web("#17473F")),
                new Stop(1.0, Color.web("#102E2B"))));
        g.fillRect(-500, -300, WORLD_WIDTH + 1_000, WORLD_HEIGHT + 600);

        drawStillwaterMoon(g, time, ambientFx);

        renderRandom.setSeed(0x5711_0A7EL);
        for (int i = 0; i < 125; i++) {
            double x = renderRandom.nextDouble() * WORLD_WIDTH;
            double y = 55.0 + renderRandom.nextDouble() * (STILLWATER_MAIN_Y - 720.0);
            double size = 1.5 + renderRandom.nextDouble() * 4.0;
            double pulse = ambientFx ? 0.65 + 0.35 * Math.sin(time * 1.3 + i * 1.17) : 0.82;
            g.setFill(Color.web(i % 11 == 0 ? "#DDF6B6" : "#B9E7E0",
                    (0.18 + renderRandom.nextDouble() * 0.42) * pulse));
            g.fillOval(x, y, size, size);
        }

        // Layered cypress silhouettes frame the flooded shrine and make the
        // playable foreground feel like a clearing rather than a flat backdrop.
        double distantBase = STILLWATER_MAIN_Y + 260.0;
        for (int i = 0; i < 11; i++) {
            double x = -220 + i * 640.0;
            double height = 820.0 + (i % 4) * 125.0;
            drawStillwaterCypress(g, x, distantBase, height, 420.0,
                    Color.web("#06191E", 0.88), Color.web("#0B2525", 0.86), false);
        }
        for (int i = 0; i < 7; i++) {
            double x = -320 + i * 1_050.0;
            double height = 1_050.0 + (i % 3) * 145.0;
            drawStillwaterCypress(g, x, distantBase + 60.0, height, 610.0,
                    Color.web("#082027", 0.78), Color.web("#10332E", 0.76), true);
        }

        double waterY = STILLWATER_MAIN_Y + 230.0;
        drawStillwaterRuinedShrine(g, waterY);

        g.setFill(new LinearGradient(0, waterY, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#0B3E42", 0.97)),
                new Stop(0.34, Color.web("#06282F", 0.98)),
                new Stop(1.0, Color.web("#020D17"))));
        g.fillRect(0, waterY, WORLD_WIDTH, WORLD_HEIGHT - waterY);
        drawStillwaterMoonReflection(g, waterY, time, ambientFx);
        drawStillwaterRipples(g, waterY, time, ambientFx);
        drawStillwaterRootWeb(g, waterY);
        drawStillwaterForegroundTrees(g, waterY);

        for (Platform platform : platforms) drawStillwaterPlatform(g, platform);

        for (WindVent vent : windVents) drawStillwaterMarshGas(g, vent, time, ambientFx);

        drawStillwaterWaterPlants(g, waterY);
        drawStillwaterFog(g, waterY, time, ambientFx);
        drawStillwaterFireflies(g, time, ambientFx);
        g.restore();
    }

    private void drawStillwaterMoon(GraphicsContext g, double time, boolean ambientFx) {
        double moonX = 4_820.0;
        double moonY = 300.0;
        double pulse = ambientFx ? 0.92 + Math.sin(time * 0.38) * 0.08 : 0.96;
        g.setFill(new RadialGradient(0, 0, moonX, moonY, 500.0, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#EAF5D2", 0.22 * pulse)),
                new Stop(0.48, Color.web("#B6E5C6", 0.08 * pulse)),
                new Stop(1.0, Color.TRANSPARENT)));
        g.fillOval(moonX - 500, moonY - 500, 1_000, 1_000);
        g.setFill(Color.web("#EDF5D3", 0.92));
        g.fillOval(moonX - 168, moonY - 168, 336, 336);
        g.setFill(Color.web("#AFCDB8", 0.18));
        g.fillOval(moonX - 92, moonY - 74, 72, 48);
        g.fillOval(moonX + 32, moonY + 38, 82, 56);
        g.fillOval(moonX - 118, moonY + 52, 54, 34);

        // Thin cloud banks pass behind the fighter silhouettes while breaking
        // the perfect moon disc into a more natural marsh-night focal point.
        double cloudShift = ambientFx ? Math.sin(time * 0.12) * 85.0 : 0.0;
        g.setFill(Color.web("#17373B", 0.58));
        g.fillOval(4_280 + cloudShift, 250, 500, 105);
        g.fillOval(4_650 + cloudShift, 220, 580, 125);
        g.fillOval(5_040 + cloudShift, 280, 430, 90);
    }

    private void drawStillwaterCypress(GraphicsContext g, double x, double baseY,
                                        double height, double crownWidth,
                                        Color trunk, Color foliage, boolean moss) {
        double centerX = x + crownWidth * 0.5;
        double topY = baseY - height;
        double trunkWidth = Math.max(58.0, crownWidth * 0.16);
        g.setFill(trunk);
        g.fillPolygon(
                new double[]{centerX - trunkWidth * 0.45, centerX + trunkWidth * 0.42,
                        centerX + trunkWidth * 0.78, centerX + trunkWidth * 1.22,
                        centerX - trunkWidth * 1.12, centerX - trunkWidth * 0.68},
                new double[]{topY + height * 0.18, topY + height * 0.18,
                        baseY - 70, baseY, baseY, baseY - 70},
                6);
        g.setFill(foliage);
        g.fillOval(x, topY, crownWidth, height * 0.22);
        g.fillOval(x + crownWidth * 0.10, topY - height * 0.07,
                crownWidth * 0.72, height * 0.20);
        g.fillOval(x + crownWidth * 0.25, topY + height * 0.07,
                crownWidth * 0.70, height * 0.18);
        if (moss) {
            g.setStroke(Color.web("#4D7F65", 0.26));
            g.setLineWidth(8.0);
            for (int i = 0; i < 5; i++) {
                double mx = x + crownWidth * (0.18 + i * 0.15);
                double length = 95.0 + (i % 3) * 65.0;
                g.strokeLine(mx, topY + height * 0.13, mx + 14, topY + height * 0.13 + length);
            }
        }
    }

    private void drawStillwaterRuinedShrine(GraphicsContext g, double waterY) {
        Color stone = Color.web("#172F31", 0.86);
        Color stoneLight = Color.web("#35544B", 0.58);
        double centerX = WORLD_WIDTH * 0.5;
        double baseY = STILLWATER_MAIN_Y + 28.0;
        g.setFill(stone);
        g.fillRect(centerX - 540, baseY - 850, 150, 880);
        g.fillRect(centerX + 390, baseY - 850, 150, 880);
        g.fillRect(centerX - 620, baseY - 920, 340, 105);
        g.fillRect(centerX + 280, baseY - 920, 340, 105);
        g.setStroke(stone);
        g.setLineWidth(125.0);
        g.strokeArc(centerX - 470, baseY - 1_125, 940, 760, 0, 180, ArcType.OPEN);
        g.setStroke(stoneLight);
        g.setLineWidth(15.0);
        g.strokeArc(centerX - 430, baseY - 1_085, 860, 690, 0, 180, ArcType.OPEN);

        g.setFill(Color.web("#89C49A", 0.18));
        g.fillPolygon(
                new double[]{centerX - 575, centerX - 390, centerX - 270,
                        centerX + 110, centerX + 300, centerX + 565},
                new double[]{baseY - 915, baseY - 940, baseY - 895,
                        baseY - 930, baseY - 900, baseY - 930}, 6);

        // Broken steps sink below the waterline instead of becoming deceptive
        // extra platforms.
        g.setFill(Color.web("#122B2D", 0.74));
        for (int i = 0; i < 4; i++) {
            double width = 1_420.0 - i * 210.0;
            g.fillRect(centerX - width * 0.5, baseY + 80 + i * 58, width, 32);
        }
        g.setFill(Color.web("#79CBB0", 0.08));
        g.fillRect(centerX - 780, waterY - 12, 1_560, 24);
    }

    private void drawStillwaterMoonReflection(GraphicsContext g, double waterY,
                                               double time, boolean ambientFx) {
        double centerX = 4_820.0;
        g.setFill(Color.web("#DDF1C4", 0.08));
        g.fillPolygon(
                new double[]{centerX - 155, centerX + 155, centerX + 470, centerX - 430},
                new double[]{waterY, waterY, WORLD_HEIGHT, WORLD_HEIGHT}, 4);
        g.setStroke(Color.web("#DDF1C4", 0.20));
        g.setLineWidth(5.0);
        for (int i = 0; i < 18; i++) {
            double width = 75.0 + i * 24.0;
            double shift = ambientFx ? Math.sin(time * 0.7 + i * 0.63) * 22.0 : 0.0;
            double y = waterY + 35.0 + i * 68.0;
            g.strokeLine(centerX - width + shift, y, centerX + width + shift, y);
        }
    }

    private void drawStillwaterRipples(GraphicsContext g, double waterY,
                                       double time, boolean ambientFx) {
        g.setStroke(Color.web("#79D6C4", 0.17));
        g.setLineWidth(3.0);
        for (int row = 0; row < 22; row++) {
            double shift = ambientFx ? Math.sin(time * 0.62 + row * 0.61) * 42.0 : 0.0;
            double y = waterY + 28 + row * 52.0;
            for (int segment = 0; segment < 7; segment++) {
                double x = 80 + segment * 890.0 + (row % 2) * 90.0 + shift;
                double width = 300.0 + ((row + segment) % 3) * 95.0;
                g.strokeLine(x, y, Math.min(WORLD_WIDTH - 60, x + width), y + 3.0);
            }
        }
    }

    private void drawStillwaterRootWeb(GraphicsContext g, double waterY) {
        g.setLineCap(StrokeLineCap.ROUND);
        g.setStroke(Color.web("#171411"));
        g.setLineWidth(190.0);
        g.beginPath();
        g.moveTo(420, STILLWATER_MAIN_Y + 260);
        g.bezierCurveTo(1_280, STILLWATER_MAIN_Y + 110, 1_840, waterY + 270, 2_520, waterY + 400);
        g.bezierCurveTo(3_020, waterY + 510, 3_520, waterY + 510, 4_060, waterY + 385);
        g.bezierCurveTo(4_720, waterY + 225, 5_160, STILLWATER_MAIN_Y + 125, 5_580, STILLWATER_MAIN_Y + 255);
        g.stroke();
        g.setStroke(Color.web("#493324"));
        g.setLineWidth(52.0);
        g.strokeLine(900, STILLWATER_MAIN_Y + 104, 5_100, STILLWATER_MAIN_Y + 104);

        drawStillwaterRootBranch(g, 1_040, STILLWATER_MAIN_Y + 85, 510, waterY + 590, -430);
        drawStillwaterRootBranch(g, 1_620, STILLWATER_MAIN_Y + 85, 1_150, waterY + 780, -160);
        drawStillwaterRootBranch(g, 2_500, STILLWATER_MAIN_Y + 100, 2_200, waterY + 860, 80);
        drawStillwaterRootBranch(g, 3_500, STILLWATER_MAIN_Y + 100, 3_770, waterY + 860, -80);
        drawStillwaterRootBranch(g, 4_380, STILLWATER_MAIN_Y + 85, 4_860, waterY + 780, 160);
        drawStillwaterRootBranch(g, 4_970, STILLWATER_MAIN_Y + 85, 5_480, waterY + 590, 430);
    }

    private void drawStillwaterRootBranch(GraphicsContext g, double startX, double startY,
                                          double endX, double endY, double curve) {
        g.setStroke(Color.web("#201814"));
        g.setLineWidth(86.0);
        g.beginPath();
        g.moveTo(startX, startY);
        g.bezierCurveTo(startX + curve, startY + 180, endX - curve * 0.35, endY - 250, endX, endY);
        g.stroke();
        g.setStroke(Color.web("#5A3D29", 0.50));
        g.setLineWidth(15.0);
        g.beginPath();
        g.moveTo(startX, startY);
        g.bezierCurveTo(startX + curve, startY + 180, endX - curve * 0.35, endY - 250, endX, endY);
        g.stroke();
    }

    private void drawStillwaterForegroundTrees(GraphicsContext g, double waterY) {
        // These two cypresses are the actual visual supports for the upper root
        // shelves; their knees join the same submerged root web as the main span.
        drawStillwaterForegroundCypress(g, 2_160, waterY + 620, STILLWATER_MAIN_Y - 850, -1.0);
        drawStillwaterForegroundCypress(g, 3_840, waterY + 620, STILLWATER_MAIN_Y - 850, 1.0);
    }

    private void drawStillwaterForegroundCypress(GraphicsContext g, double centerX,
                                                  double baseY, double topY, double direction) {
        g.setFill(Color.web("#231A16"));
        g.fillPolygon(
                new double[]{centerX - 105, centerX + 95, centerX + 150, centerX + 280,
                        centerX - 260, centerX - 145},
                new double[]{topY + 24, topY + 24, baseY - 120, baseY,
                        baseY, baseY - 125}, 6);
        g.setStroke(Color.web("#6C4930", 0.62));
        g.setLineWidth(18.0);
        g.strokeLine(centerX - 20, topY + 70, centerX + direction * 32, baseY - 85);

        g.setStroke(Color.web("#241A15"));
        g.setLineWidth(110.0);
        g.beginPath();
        g.moveTo(centerX, topY + 250);
        g.bezierCurveTo(centerX - direction * 190, topY + 180,
                centerX - direction * 360, STILLWATER_MAIN_Y - 300,
                centerX - direction * 610, STILLWATER_MAIN_Y - 300);
        g.stroke();
        g.setStroke(Color.web("#51745A", 0.34));
        g.setLineWidth(20.0);
        g.strokeLine(centerX - 44, topY + 42, centerX - 44, topY + 350);
    }

    private void drawStillwaterPlatform(GraphicsContext g, Platform platform) {
        boolean mainRoot = Math.abs(platform.x - STILLWATER_MAIN_X) < 1.0
                && Math.abs(platform.w - STILLWATER_MAIN_W) < 1.0;
        boolean shrineStone = platform.y <= STILLWATER_MAIN_Y - 610.0;
        if (shrineStone) {
            drawStillwaterStonePlatform(g, platform);
        } else {
            drawStillwaterRootPlatform(g, platform, mainRoot);
        }

        if (platform.signText != null) {
            g.setTextAlign(TextAlignment.CENTER);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 25));
            g.setFill(Color.web("#D8F1D2", 0.76));
            g.fillText(platform.signText, platform.x + platform.w * 0.5,
                    platform.y + Math.min(65.0, platform.h * 0.70));
        }
    }

    private void drawStillwaterRootPlatform(GraphicsContext g, Platform platform, boolean mainRoot) {
        double taper = Math.min(80.0, platform.w * 0.10);
        g.setFill(Color.web("#171310"));
        g.fillPolygon(
                new double[]{platform.x + taper, platform.x + platform.w - taper,
                        platform.x + platform.w, platform.x + platform.w - taper * 0.25,
                        platform.x + taper * 0.25, platform.x},
                new double[]{platform.y - 8, platform.y - 8, platform.y + platform.h * 0.44,
                        platform.y + platform.h + (mainRoot ? 58 : 34),
                        platform.y + platform.h + (mainRoot ? 58 : 34),
                        platform.y + platform.h * 0.44}, 6);
        g.setFill(new LinearGradient(0, platform.y, 0, platform.y + platform.h, false,
                CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#684A30")),
                new Stop(0.42, Color.web("#3B2B20")),
                new Stop(1.0, Color.web("#211814"))));
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 32, 32);
        g.setStroke(Color.web("#8B6540", 0.68));
        g.setLineWidth(6.0);
        g.strokeRoundRect(platform.x + 3, platform.y + 3,
                platform.w - 6, platform.h - 6, 30, 30);
        g.setFill(Color.web("#47745A"));
        g.fillRoundRect(platform.x + 12, platform.y - 2,
                Math.max(0.0, platform.w - 24), 24, 18, 18);
        g.setFill(Color.web("#83A86C", 0.58));
        for (int i = 0; i < Math.max(2, (int) (platform.w / 330.0)); i++) {
            double x = platform.x + 45 + i * (platform.w - 90)
                    / Math.max(1, Math.max(2, (int) (platform.w / 330.0)) - 1);
            g.fillOval(x - 26, platform.y - 7, 52, 18);
        }
    }

    private void drawStillwaterStonePlatform(GraphicsContext g, Platform platform) {
        g.setFill(Color.web("#101E1E"));
        g.fillPolygon(
                new double[]{platform.x + 18, platform.x + platform.w - 18,
                        platform.x + platform.w - 50, platform.x + platform.w * 0.58,
                        platform.x + platform.w * 0.45, platform.x + 45},
                new double[]{platform.y + 18, platform.y + 18,
                        platform.y + platform.h + 45, platform.y + platform.h + 64,
                        platform.y + platform.h + 52, platform.y + platform.h + 42}, 6);
        g.setFill(new LinearGradient(0, platform.y, 0, platform.y + platform.h, false,
                CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#607069")),
                new Stop(0.42, Color.web("#3C4C48")),
                new Stop(1.0, Color.web("#1F302F"))));
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 18, 18);
        g.setStroke(Color.web("#91A79A", 0.66));
        g.setLineWidth(5.0);
        g.strokeRoundRect(platform.x + 3, platform.y + 3,
                platform.w - 6, platform.h - 6, 16, 16);
        g.setFill(Color.web("#588165", 0.86));
        g.fillRoundRect(platform.x + 10, platform.y - 3,
                platform.w - 20, 20, 14, 14);

        renderRandom.setSeed(Double.doubleToLongBits(platform.x * 19.0 + platform.y * 11.0));
        g.setStroke(Color.web("#172524", 0.68));
        g.setLineWidth(2.5);
        int cracks = Math.max(2, (int) (platform.w / 220.0));
        for (int i = 0; i < cracks; i++) {
            double x = platform.x + 30 + renderRandom.nextDouble() * Math.max(1, platform.w - 60);
            g.strokeLine(x, platform.y + 14, x - 14, platform.y + platform.h * 0.70);
            g.strokeLine(x - 14, platform.y + platform.h * 0.70,
                    x + 11, platform.y + platform.h - 5);
        }
    }

    private void drawStillwaterMarshGas(GraphicsContext g, WindVent vent,
                                         double time, boolean ambientFx) {
        double centerX = vent.x + vent.w * 0.5;
        double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 1.75 + vent.x * 0.013) : 0.58;
        g.setFill(Color.web("#72E2C4", 0.05 + pulse * 0.06));
        g.fillOval(centerX - 105, vent.y - 250, 210, 320);
        g.setStroke(Color.web("#A4F1D5", 0.25 + pulse * 0.18));
        g.setLineWidth(4.0);
        for (int ring = 0; ring < 3; ring++) {
            double width = 100.0 + ring * 64.0;
            g.strokeArc(centerX - width * 0.5, vent.y - 55 - ring * 76.0,
                    width, 52.0 + ring * 12.0, 18, 144, ArcType.OPEN);
        }
        g.setFill(Color.web("#B9F5D1", 0.34));
        for (int i = 0; i < 5; i++) {
            double drift = ambientFx ? Math.sin(time * 1.2 + i) * 16.0 : 0.0;
            g.fillOval(centerX - 34 + i * 17 + drift, vent.y - 42 - i * 38,
                    10 + i * 2.0, 10 + i * 2.0);
        }
    }

    private void drawStillwaterWaterPlants(GraphicsContext g, double waterY) {
        g.setFill(Color.web("#183E35", 0.94));
        for (int i = 0; i < 16; i++) {
            double x = 90 + i * 390.0;
            double y = waterY + 85 + (i % 4) * 170.0;
            g.fillOval(x, y, 120 + (i % 3) * 26.0, 30 + (i % 2) * 8.0);
            if (i % 3 == 0) {
                g.setFill(Color.web("#7FAD78", 0.40));
                g.fillOval(x + 54, y - 5, 24, 14);
                g.setFill(Color.web("#183E35", 0.94));
            }
        }
        g.setStroke(Color.web("#315B43", 0.72));
        g.setLineWidth(12.0);
        for (int i = 0; i < 18; i++) {
            double x = 45 + i * 360.0;
            double base = WORLD_HEIGHT + 30.0;
            double height = 130.0 + (i % 5) * 38.0;
            g.strokeLine(x, base, x - 24 + (i % 3) * 20, base - height);
        }
    }

    private void drawStillwaterFog(GraphicsContext g, double waterY,
                                    double time, boolean ambientFx) {
        g.setStroke(Color.web("#A3D8C4", ambientFx ? 0.13 : 0.10));
        g.setLineCap(StrokeLineCap.ROUND);
        for (int fog = 0; fog < 6; fog++) {
            double x = -650 + fog * 1_320.0
                    + (ambientFx ? Math.sin(time * 0.16 + fog) * 135.0 : 0.0);
            double y = waterY - 42 - fog * 16.0;
            g.setLineWidth(70.0 - fog * 5.0);
            g.strokeLine(x, y, x + 1_080, y - 22.0);
        }
    }

    private void drawStillwaterFireflies(GraphicsContext g, double time, boolean ambientFx) {
        renderRandom.setSeed(0xF1AE_F11EL);
        for (int i = 0; i < 78; i++) {
            double x = 260.0 + renderRandom.nextDouble() * (WORLD_WIDTH - 520.0);
            double y = 480.0 + renderRandom.nextDouble() * (STILLWATER_MAIN_Y - 420.0);
            double drift = ambientFx ? Math.sin(time * 0.72 + i * 1.31) * 24.0 : 0.0;
            double glow = ambientFx ? 0.58 + 0.42 * Math.sin(time * 1.85 + i * 0.77) : 0.78;
            g.setFill(Color.web("#E7F58A", 0.08 + glow * 0.10));
            g.fillOval(x - 18 + drift, y - 18, 36, 36);
            g.setFill(Color.web("#F3FFAA", 0.45 + glow * 0.42));
            g.fillOval(x - 3 + drift, y - 3, 6, 6);
        }
    }

    private void drawFrostbiteSnowbanks(GraphicsContext g) {
        for (FrostbiteSnowbank bank : frostbiteSnowbanks) {
            if (bank.health <= 0) {
                continue;
            }
            if (bank.damageFlash > 0) {
                bank.damageFlash--;
            }
            double ratio = Math.clamp(bank.health / (double) bank.maxHealth, 0.0, 1.0);
            double slump = (1.0 - ratio) * bank.h * 0.20;
            Color snow = bank.damageFlash > 0 ? Color.web("#FFF59D") : Color.web("#F8FDFF");
            g.setFill(Color.web("#082339", 0.22));
            g.fillOval(bank.x + 8, bank.y + bank.h - 12, bank.w - 16, 28);
            g.setFill(snow);
            g.fillOval(bank.x, bank.y + 12 + slump, bank.w * 0.58, bank.h * 0.86);
            g.fillOval(bank.x + bank.w * 0.30, bank.y + slump, bank.w * 0.55, bank.h * 0.96);
            g.fillOval(bank.x + bank.w * 0.62, bank.y + 18 + slump, bank.w * 0.38, bank.h * 0.72);
            g.setFill(Color.web("#B3E5FC", 0.58));
            g.fillOval(bank.x + bank.w * 0.08, bank.y + bank.h * 0.52 + slump, bank.w * 0.46, bank.h * 0.22);
            g.fillOval(bank.x + bank.w * 0.52, bank.y + bank.h * 0.48 + slump, bank.w * 0.32, bank.h * 0.18);
            g.setStroke(bank.damageFlash > 0 ? Color.web("#FFFDE7") : Color.web("#D7F7FF", 0.88));
            g.setLineWidth(2.6);
            g.strokeOval(bank.x + bank.w * 0.27, bank.y + slump, bank.w * 0.58, bank.h * 0.92);
        }
    }

    private double parallaxAdjustedWorldX(double worldX, double movementFactor) {
        return worldX + camX * (1.0 - movementFactor);
    }

    private void drawPremiumBattlefieldArena(GraphicsContext g, boolean ambientFx) {
        double islandCenterX = battlefieldIslandX + battlefieldIslandW * 0.5;
        double horizonY = battlefieldIslandY + 230.0;
        double time = System.currentTimeMillis() / 1000.0;

        g.save();

        // A cool, high-altitude sky keeps fighters readable while the warmer
        // horizon and sun establish a clear focal axis behind the main island.
        g.setFill(new LinearGradient(0, 0, 0, WORLD_HEIGHT, false, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#10283E")),
                new Stop(0.28, Color.web("#315B73")),
                new Stop(0.58, Color.web("#86AFAE")),
                new Stop(1.0, Color.web("#D5D7B6"))));
        g.fillRect(-1200, -500, WORLD_WIDTH + 2400, WORLD_HEIGHT + 1000);

        double sunX = islandCenterX + 250.0;
        double sunY = battlefieldIslandY - 570.0;
        g.setFill(Color.web("#F6D79B", 0.10));
        g.fillOval(sunX - 310, sunY - 310, 620, 620);
        g.setFill(Color.web("#FFE4A6", 0.22));
        g.fillOval(sunX - 205, sunY - 205, 410, 410);
        g.setFill(Color.web("#FFF2C7", 0.78));
        g.fillOval(sunX - 118, sunY - 118, 236, 236);
        g.setFill(Color.web("#FFF6D5", 0.08));
        g.fillPolygon(
                new double[]{sunX - 180, sunX - 560, sunX + 610, sunX + 190},
                new double[]{sunY + 80, horizonY, horizonY, sunY + 80}, 4);

        // Three parallax ridge layers create depth without competing with play.
        drawBattlefieldRidge(g, 0.18, horizonY + 80, 370, Color.web("#294856"), 760, 0.34);
        drawBattlefieldRidge(g, 0.34, horizonY + 145, 285, Color.web("#365D61"), 620, 1.12);
        drawBattlefieldRidge(g, 0.52, horizonY + 205, 205, Color.web("#426B64"), 470, 2.06);

        g.setFill(Color.web("#294D55", 0.72));
        g.fillPolygon(
                new double[]{islandCenterX - 1780, islandCenterX - 1240, islandCenterX - 760,
                        islandCenterX - 260, islandCenterX + 210, islandCenterX + 720,
                        islandCenterX + 1220, islandCenterX + 1780},
                new double[]{horizonY + 160, battlefieldIslandY - 250, battlefieldIslandY - 430,
                        battlefieldIslandY - 275, battlefieldIslandY - 520, battlefieldIslandY - 330,
                        battlefieldIslandY - 405, horizonY + 160}, 8);
        g.setFill(Color.web("#52766E", 0.62));
        g.fillPolygon(
                new double[]{islandCenterX - 1620, islandCenterX - 1060, islandCenterX - 520,
                        islandCenterX - 40, islandCenterX + 440, islandCenterX + 980,
                        islandCenterX + 1580},
                new double[]{horizonY + 210, battlefieldIslandY - 80, battlefieldIslandY - 240,
                        battlefieldIslandY - 135, battlefieldIslandY - 310, battlefieldIslandY - 125,
                        horizonY + 210}, 7);

        // A distant weathered aerie gives Battlefield a memorable identity.
        // Perch it high on the left ridge and keep it deliberately small so
        // it cannot read as architecture resting on a gameplay platform.
        double citadelX = islandCenterX - 420.0;
        double citadelBaseY = battlefieldIslandY + BATTLEFIELD_CITADEL_BASE_Y_OFFSET;
        double citadelScale = BATTLEFIELD_CITADEL_SCALE;

        // Give the aerie its own distant hill. The flat summit and the
        // citadel foundation share citadelBaseY, so the building can never
        // drift into the sky or appear to rest on a gameplay platform.
        g.setFill(Color.web("#294F55", 0.78));
        g.beginPath();
        g.moveTo(citadelX - 520.0, citadelBaseY + 300.0);
        g.bezierCurveTo(citadelX - 390.0, citadelBaseY + 215.0,
                citadelX - 205.0, citadelBaseY + 42.0,
                citadelX - BATTLEFIELD_CITADEL_HILL_PLATEAU_HALF_W, citadelBaseY);
        g.lineTo(citadelX + BATTLEFIELD_CITADEL_HILL_PLATEAU_HALF_W, citadelBaseY);
        g.bezierCurveTo(citadelX + 220.0, citadelBaseY + 52.0,
                citadelX + 405.0, citadelBaseY + 220.0,
                citadelX + 540.0, citadelBaseY + 300.0);
        g.closePath();
        g.fill();

        g.setFill(Color.web("#5D8176", 0.18));
        g.beginPath();
        g.moveTo(citadelX, citadelBaseY);
        g.lineTo(citadelX + BATTLEFIELD_CITADEL_HILL_PLATEAU_HALF_W, citadelBaseY);
        g.bezierCurveTo(citadelX + 220.0, citadelBaseY + 52.0,
                citadelX + 405.0, citadelBaseY + 220.0,
                citadelX + 540.0, citadelBaseY + 300.0);
        g.lineTo(citadelX + 55.0, citadelBaseY + 300.0);
        g.closePath();
        g.fill();

        g.save();
        g.translate(citadelX, citadelBaseY);
        g.scale(citadelScale, citadelScale);
        g.setFill(Color.web("#203B43", 0.72));
        g.fillRect(-270, -205, 540, 205);
        g.fillRect(-390, -130, 135, 130);
        g.fillRect(255, -130, 135, 130);
        g.fillRect(-92, -330, 184, 330);
        g.fillPolygon(new double[]{-132, 0, 132}, new double[]{-330, -470, -330}, 3);
        g.setFill(Color.web("#9BB89B", 0.34));
        for (int i = -2; i <= 2; i++) {
            double windowX = i * 86.0;
            g.fillRoundRect(windowX - 15, -152, 30, 68, 15, 15);
        }
        g.setStroke(Color.web("#D2B86E", 0.34));
        g.setLineWidth(5.0);
        g.strokeLine(0, -455, 0, -530);
        g.strokeLine(0, -520, 92, -490);
        g.restore();

        // Soft cloud shelves frame the stage and sell the altitude.
        double cloudDrift = ambientFx ? (time * 12.0) % 760.0 : 210.0;
        for (int layer = 0; layer < 3; layer++) {
            double layerY = battlefieldIslandY - 820.0 + layer * 205.0;
            double movement = 0.18 + layer * 0.12;
            Color cloud = Color.web(layer == 0 ? "#E8F0EA" : "#D8E6DE", 0.065 + layer * 0.022);
            g.setFill(cloud);
            for (int i = -2; i < 10; i++) {
                double baseX = i * 760.0 + cloudDrift * (layer + 1) * 0.45;
                double cx = parallaxAdjustedWorldX(baseX, movement);
                double w = 350.0 + (i & 1) * 90.0;
                g.fillOval(cx - w * 0.5, layerY + (i % 3) * 20.0, w, 64.0 + layer * 18.0);
                g.fillOval(cx - w * 0.24, layerY - 22.0 + (i % 2) * 14.0, w * 0.58, 78.0);
            }
        }

        g.setFill(Color.web("#D7E6DC", 0.22));
        g.fillRect(-1000, horizonY - 30, WORLD_WIDTH + 2000, 170);
        g.setFill(Color.web("#B7CDBD", 0.16));
        g.fillRect(-1000, horizonY + 100, WORLD_WIDTH + 2000, 300);

        if (ambientFx) {
            // Render-only motes use fixed formulas and wall time; they never touch SimRng.
            for (int i = 0; i < 34; i++) {
                double baseX = (i * 227.0 + time * (8.0 + i % 4) + 700.0) % (WORLD_WIDTH + 500.0) - 250.0;
                double moteX = parallaxAdjustedWorldX(baseX, 0.72);
                double moteY = battlefieldIslandY - 650.0 + (i % 11) * 82.0
                        + Math.sin(time * 0.55 + i * 1.37) * 24.0;
                double radius = 2.0 + (i % 3) * 0.9;
                g.setFill(Color.web(i % 4 == 0 ? "#FFE7A8" : "#EAF5E8", 0.22 + (i % 3) * 0.06));
                g.fillOval(moteX - radius, moteY - radius, radius * 2.0, radius * 2.0);
            }
        }

        drawBattlefieldCitadelSupports(g);

        for (Platform p : platforms) {
            drawPremiumBattlefieldPlatform(g, p);
        }

        g.restore();
    }

    private void drawBattlefieldRidge(GraphicsContext g, double movementFactor, double baseY,
                                      double peakHeight, Color color, double segmentWidth, double phase) {
        g.setFill(color);
        int segments = (int) Math.ceil((WORLD_WIDTH + 2200.0) / segmentWidth) + 2;
        double startX = parallaxAdjustedWorldX(-1100.0, movementFactor);
        double[] xs = new double[segments + 2];
        double[] ys = new double[segments + 2];
        xs[0] = startX;
        ys[0] = baseY + 360.0;
        for (int i = 0; i < segments; i++) {
            double x = startX + i * segmentWidth;
            double shape = 0.46 + 0.54 * Math.abs(Math.sin(i * 1.71 + phase));
            xs[i + 1] = x;
            ys[i + 1] = baseY - peakHeight * shape;
        }
        xs[segments + 1] = startX + segments * segmentWidth;
        ys[segments + 1] = baseY + 360.0;
        g.fillPolygon(xs, ys, xs.length);
    }

    /**
     * Grounds Battlefield's three upper perches in one readable ruin.  These
     * supports are deliberately painted behind the collision platforms: the
     * platform tops remain the only solid surfaces, while the architecture
     * makes their placement believable at both gameplay and thumbnail scale.
     */
    private void drawBattlefieldCitadelSupports(GraphicsContext g) {
        if (platforms.size() < 4 || battlefieldIslandW <= 0.0) return;

        Platform main = platforms.get(0);
        Platform left = platforms.get(1);
        Platform right = platforms.get(2);
        Platform crown = platforms.get(3);
        double centerX = main.x + main.w * 0.5;
        double foundationY = main.y + 22.0;

        // A broad, broken temple silhouette keeps the compact combat island
        // from disappearing against the six-thousand-unit world preview.
        g.setFill(Color.web("#1A3039", 0.92));
        g.fillPolygon(
                new double[]{main.x - 330.0, main.x - 120.0, main.x + main.w + 120.0,
                        main.x + main.w + 330.0, main.x + main.w + 190.0, main.x - 190.0},
                new double[]{foundationY + 250.0, foundationY - 10.0, foundationY - 10.0,
                        foundationY + 250.0, foundationY + 430.0, foundationY + 430.0}, 6);
        g.setStroke(Color.web("#D0B86F", 0.40));
        g.setLineWidth(8.0);
        g.strokeLine(main.x - 112.0, foundationY + 4.0,
                main.x + main.w + 112.0, foundationY + 4.0);

        drawBattlefieldPerchTower(g, left, foundationY, false);
        drawBattlefieldPerchTower(g, right, foundationY, true);

        // The summit perch is the lintel of a large open arch.  Keeping the
        // centre hollow preserves fighter readability and avoids implying an
        // invisible wall beneath the platform.
        double crownLeft = crown.x + 48.0;
        double crownRight = crown.x + crown.w - 48.0;
        g.setFill(Color.web("#203A42", 0.96));
        g.fillPolygon(
                new double[]{crownLeft, crownLeft + 70.0, crownLeft + 94.0, crownLeft + 28.0},
                new double[]{crown.y + crown.h, crown.y + crown.h, foundationY, foundationY}, 4);
        g.fillPolygon(
                new double[]{crownRight - 70.0, crownRight, crownRight - 28.0, crownRight - 94.0},
                new double[]{crown.y + crown.h, crown.y + crown.h, foundationY, foundationY}, 4);
        g.setStroke(Color.web("#78948D", 0.38));
        g.setLineWidth(5.0);
        g.strokeArc(centerX - 265.0, crown.y + 88.0, 530.0,
                Math.max(220.0, foundationY - crown.y - 70.0), 0.0, 180.0, ArcType.OPEN);

        // Three open doorways and a central standard turn the island into a
        // recognisable ancient arena without adding misleading collision art.
        g.setStroke(Color.web("#A9C1AC", 0.30));
        g.setLineWidth(10.0);
        for (double x : new double[]{main.x + 235.0, centerX, main.x + main.w - 235.0}) {
            g.strokeArc(x - 72.0, foundationY + 88.0, 144.0, 210.0,
                    0.0, 180.0, ArcType.OPEN);
            g.strokeLine(x - 72.0, foundationY + 193.0, x - 72.0, foundationY + 300.0);
            g.strokeLine(x + 72.0, foundationY + 193.0, x + 72.0, foundationY + 300.0);
        }
        g.setStroke(Color.web("#D7BE6E", 0.64));
        g.setLineWidth(7.0);
        g.strokeLine(centerX, crown.y - 105.0, centerX, crown.y + 8.0);
        g.setFill(Color.web("#D7BE6E", 0.54));
        g.fillPolygon(new double[]{centerX, centerX + 112.0, centerX},
                new double[]{crown.y - 96.0, crown.y - 58.0, crown.y - 20.0}, 3);
    }

    private void drawBattlefieldPerchTower(GraphicsContext g, Platform platform,
                                           double foundationY, boolean mirrored) {
        double centerX = platform.x + platform.w * 0.5;
        double towerTop = platform.y + platform.h;
        double shoulder = platform.w * 0.34;
        g.setFill(Color.web("#203A42", 0.94));
        g.fillPolygon(
                new double[]{centerX - shoulder, centerX + shoulder,
                        centerX + shoulder + 54.0, centerX - shoulder - 54.0},
                new double[]{towerTop, towerTop, foundationY, foundationY}, 4);
        g.setFill(Color.web("#35535A", 0.56));
        double slitX = centerX + (mirrored ? 34.0 : -46.0);
        for (double y = towerTop + 82.0; y < foundationY - 46.0; y += 118.0) {
            g.fillRoundRect(slitX, y, 18.0, 54.0, 9.0, 9.0);
        }
        g.setStroke(Color.web("#D0B86F", 0.30));
        g.setLineWidth(5.0);
        g.strokeLine(centerX - shoulder, towerTop + 22.0,
                centerX - shoulder - 44.0, foundationY - 18.0);
        g.strokeLine(centerX + shoulder, towerTop + 22.0,
                centerX + shoulder + 44.0, foundationY - 18.0);
    }

    private void drawPremiumBattlefieldPlatform(GraphicsContext g, Platform p) {
        boolean mainIsland = Math.abs(p.x - battlefieldIslandX) < 0.01
                && Math.abs(p.w - battlefieldIslandW) < 0.01;
        double keel = mainIsland ? 175.0 : 64.0;
        double centerX = p.x + p.w * 0.5;

        g.setFill(new LinearGradient(0, p.y + p.h * 0.35, 0, p.y + p.h + keel, false,
                CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#344955")),
                new Stop(0.46, Color.web("#243541")),
                new Stop(1.0, Color.web("#14232C"))));
        g.fillPolygon(
                new double[]{p.x + 20, p.x + p.w - 20, p.x + p.w * 0.68, centerX, p.x + p.w * 0.32},
                new double[]{p.y + p.h * 0.48, p.y + p.h * 0.48, p.y + p.h + keel * 0.58,
                        p.y + p.h + keel, p.y + p.h + keel * 0.58}, 5);

        g.setStroke(Color.web("#58717B", 0.24));
        g.setLineWidth(2.4);
        g.strokeLine(p.x + p.w * 0.16, p.y + p.h * 0.72, centerX, p.y + p.h + keel * 0.90);
        g.strokeLine(p.x + p.w * 0.84, p.y + p.h * 0.72, centerX, p.y + p.h + keel * 0.90);
        g.strokeLine(p.x + p.w * 0.38, p.y + p.h * 0.62,
                p.x + p.w * 0.45, p.y + p.h + keel * 0.76);

        g.setFill(Color.web("#2B3C47"));
        g.fillRoundRect(p.x, p.y, p.w, p.h, 28, 28);
        g.setFill(Color.web("#3E5660"));
        g.fillRoundRect(p.x + 5, p.y + 5, p.w - 10, Math.max(14.0, p.h * 0.46), 22, 22);
        g.setStroke(Color.web("#162630"));
        g.setLineWidth(mainIsland ? 4.0 : 3.0);
        g.strokeRoundRect(p.x, p.y, p.w, p.h, 28, 28);

        int seams = Math.max(2, (int) Math.round(p.w / 180.0));
        g.setStroke(Color.web("#172933", 0.56));
        g.setLineWidth(1.8);
        for (int i = 1; i < seams; i++) {
            double seamX = p.x + p.w * i / seams;
            g.strokeLine(seamX, p.y + 11, seamX - 5, p.y + p.h - 8);
        }

        g.setFill(Color.web("#527B67"));
        g.fillRoundRect(p.x + 7, p.y - 10, p.w - 14, 20, 18, 18);
        g.setFill(Color.web("#78A679", 0.72));
        g.fillRoundRect(p.x + 15, p.y - 7, p.w - 30, 8, 12, 12);
        g.setStroke(Color.web("#D4B86A", mainIsland ? 0.76 : 0.58));
        g.setLineWidth(mainIsland ? 3.2 : 2.2);
        g.strokeLine(p.x + 22, p.y + 15, p.x + p.w - 22, p.y + 15);

        // Symmetric floor inlays subtly clarify the standard spawn lanes.
        if (mainIsland) {
            g.setStroke(Color.web("#D9C27D", 0.36));
            g.setLineWidth(3.0);
            for (double ratio : new double[]{0.22, 0.50, 0.78}) {
                double markerX = p.x + p.w * ratio;
                g.strokeArc(markerX - 38, p.y - 4, 76, 30, 190, 160, ArcType.OPEN);
                g.strokeLine(markerX - 20, p.y + 12, markerX + 20, p.y + 12);
            }
        }
    }

    private void drawTrainingCombatOverlay(GraphicsContext g) {
        for (Bird b : players) {
            if (b == null || b.health <= 0) continue;

            g.setLineWidth(3.0 / Math.max(0.25, zoom));
            g.setStroke((isTrainingDummy(b) ? Color.web("#FFB74D") : Color.web("#80DEEA")).deriveColor(0, 1, 1, 0.88));
            g.strokeRect(
                    b.debugCombatLeft(),
                    b.debugCombatTop(),
                    b.debugCombatWidth(),
                    b.debugCombatHeight()
            );

            if (!b.debugAttackBoxActive()) continue;
            g.setStroke(Color.web("#FF5252").deriveColor(0, 1, 1, 0.94));
            g.strokeRect(
                    b.debugAttackBoxLeft(),
                    b.debugAttackBoxTop(),
                    b.debugAttackBoxWidth(),
                    b.debugAttackBoxHeight()
            );
            double sweetRatio = b.debugNormalAttackSweetSpotStartRatio();
            if (Double.isFinite(sweetRatio)) {
                double innerW = b.debugAttackBoxWidth() * sweetRatio;
                double innerH = b.debugAttackBoxHeight() * sweetRatio;
                double innerX = b.debugAttackBoxLeft() + (b.debugAttackBoxWidth() - innerW) * 0.5;
                double innerY = b.debugAttackBoxTop() + (b.debugAttackBoxHeight() - innerH) * 0.5;
                g.setStroke(Color.web("#FFD54F").deriveColor(0, 1, 1, 0.92));
                g.setLineDashes(9.0 / Math.max(0.25, zoom), 6.0 / Math.max(0.25, zoom));
                g.strokeRect(innerX, innerY, innerW, innerH);
                g.setLineDashes();
            }
        }
    }

    private void drawBeaconCrownBattlefield(GraphicsContext g, boolean ambientFx) {
        switch (activeArenaGeometryVariant) {
            case NULL_ROCK_DUEL -> drawFinalDuelAltar(g, ambientFx);
            case NULL_ROC_ASCENDING -> drawNullRocAscent(g, ambientFx);
            case VOID_CROWN -> drawVoidCrownArena(g, ambientFx);
            default -> drawBeaconCrownCitadel(g, ambientFx);
        }
    }

    private void drawBeaconCrownCitadel(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        double bossRatio = beaconCrownBossHealthRatio();
        drawCrownSky(g, "#02040A", "#10182D", Color.web("#FFE082"),
                time, ambientFx, 0.42 + (1.0 - bossRatio) * 0.18);

        if (isNullRockCampaign() && !isNullRockDuelPhase()) {
            drawNullRockBackgroundCommander(g, ambientFx);
        }

        double centerX = WORLD_WIDTH * 0.5;
        double mainY = battlefieldIslandY;
        drawBeaconDistantCitadel(g, mainY);

        // The Crown beacon is a single monumental tower. Its upper shelves are
        // observation balconies carried by ribs from the central spire.
        g.setFill(Color.web("#111425"));
        g.fillPolygon(new double[]{centerX - 610.0, centerX - 185.0,
                        centerX + 185.0, centerX + 610.0},
                new double[]{WORLD_HEIGHT + 160.0, 690.0, 690.0, WORLD_HEIGHT + 160.0}, 4);
        g.setFill(Color.web("#30304A", 0.76));
        g.fillPolygon(new double[]{centerX - 240.0, centerX - 65.0,
                        centerX + 25.0, centerX + 170.0},
                new double[]{WORLD_HEIGHT + 160.0, 720.0, 720.0, WORLD_HEIGHT + 160.0}, 4);
        g.setStroke(Color.web("#D8B75B", 0.54));
        g.setLineWidth(16.0);
        for (double y = 960.0; y < mainY; y += 310.0) {
            double half = 120.0 + (y - 690.0) * 0.15;
            g.strokeLine(centerX - half, y, centerX + half, y);
        }

        for (Platform platform : platforms) {
            drawBeaconCrownSupport(g, platform, centerX, mainY);
        }
        for (Platform platform : platforms) {
            drawCrownStonePlatform(g, platform,
                    Color.web("#292C43"), Color.web("#555874"), Color.web("#E3C66B"));
        }
        drawBeaconCrownSeal(g, centerX, mainY, time, ambientFx, bossRatio);
    }

    private double beaconCrownBossHealthRatio() {
        if (isUnitedFinaleClimaxContext()) {
            Bird boss = unitedFinaleBoss();
            return boss == null ? 1.0
                    : Math.clamp(boss.health / unitedFinaleBossMaxHealth(), 0.0, 1.0);
        }
        if (bossRushModeActive && classicModeActive) {
            return bossRushEnemyHealthRatio();
        }
        for (Bird bird : players) {
            if (bird != null && bird.health > 0.0 && bird.isNullRockForm()) {
                return Math.clamp(bird.health / Math.max(1.0, bird.getMaxHealth()), 0.0, 1.0);
            }
        }
        return 1.0;
    }

    private void drawCrownSky(GraphicsContext g, String top, String bottom, Color halo,
                              double time, boolean ambientFx, double haloAlpha) {
        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web(top)),
                new Stop(1.0, Color.web(bottom))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        double centerX = WORLD_WIDTH * 0.5;
        double eclipseY = 430.0;
        g.setFill(halo.deriveColor(0, 0.75, 1.0, haloAlpha * 0.18));
        g.fillOval(centerX - 470.0, eclipseY - 470.0, 940.0, 940.0);
        g.setFill(Color.web("#010207", 0.98));
        g.fillOval(centerX - 205.0, eclipseY - 205.0, 410.0, 410.0);
        g.setStroke(halo.deriveColor(0, 0.88, 1.08, haloAlpha));
        g.setLineWidth(24.0);
        g.strokeOval(centerX - 250.0, eclipseY - 250.0, 500.0, 500.0);
        g.setStroke(Color.web("#80DEEA", 0.18));
        g.setLineWidth(7.0);
        g.strokeOval(centerX - 285.0, eclipseY - 285.0, 570.0, 570.0);

        renderRandom.setSeed(0xC20A_4E5EL);
        for (int shard = 0; shard < 21; shard++) {
            double angle = shard * Math.PI * 2.0 / 21.0 + (ambientFx ? time * 0.014 : 0.0);
            double radius = 760.0 + (shard % 4) * 235.0;
            double x = centerX + Math.cos(angle) * radius;
            double y = eclipseY + Math.sin(angle) * radius * 0.34;
            double size = 34.0 + (shard % 5) * 9.0;
            g.setFill((shard & 1) == 0
                    ? halo.deriveColor(0, 0.8, 1.0, 0.24)
                    : Color.web("#75D8E8", 0.20));
            g.fillPolygon(new double[]{x - size, x, x + size},
                    new double[]{y + size * 0.55, y - size, y + size * 0.55}, 3);
        }
    }

    private void drawBeaconDistantCitadel(GraphicsContext g, double mainY) {
        g.setFill(Color.web("#090D1A", 0.94));
        for (int tower = 0; tower < 9; tower++) {
            double x = 100.0 + tower * 730.0;
            double height = 680.0 + (tower % 4) * 190.0;
            double width = 210.0 + (tower % 2) * 45.0;
            g.fillPolygon(new double[]{x - width, x - width * 0.72, x,
                            x + width * 0.72, x + width},
                    new double[]{mainY + 520.0, mainY - height + 180.0, mainY - height,
                            mainY - height + 180.0, mainY + 520.0}, 5);
            g.setStroke(Color.web("#B89D58", 0.25));
            g.setLineWidth(8.0);
            g.strokeLine(x, mainY - height + 120.0, x, mainY + 330.0);
        }
    }

    private void drawBeaconCrownSupport(GraphicsContext g, Platform platform,
                                        double centerX, double mainY) {
        double platformCenter = platform.x + platform.w * 0.5;
        double underside = platform.y + platform.h;
        boolean main = Math.abs(platform.x - battlefieldIslandX) < 2.0
                && Math.abs(platform.w - battlefieldIslandW) < 2.0;
        if (main) {
            g.setFill(Color.web("#111425"));
            g.fillPolygon(new double[]{platform.x + 80.0, platform.x + platform.w - 80.0,
                            centerX + 360.0, centerX - 360.0},
                    new double[]{underside, underside, WORLD_HEIGHT + 80.0, WORLD_HEIGHT + 80.0}, 4);
            return;
        }
        double anchorY = Math.min(mainY + 80.0, platform.y + 285.0);
        double anchorX = centerX + (platformCenter - centerX) * 0.30;
        g.setStroke(Color.web("#121626"));
        g.setLineWidth(Math.clamp(platform.w * 0.09, 34.0, 72.0));
        g.strokeLine(anchorX, anchorY, platformCenter, underside);
        g.setStroke(Color.web("#4A4D68", 0.84));
        g.setLineWidth(Math.clamp(platform.w * 0.035, 12.0, 28.0));
        g.strokeLine(anchorX, anchorY, platformCenter, underside);
        g.setStroke(Color.web("#C3A956", 0.42));
        g.setLineWidth(7.0);
        g.strokeLine(anchorX, anchorY - 10.0, platformCenter, underside - 10.0);
    }

    private void drawBeaconCrownSeal(GraphicsContext g, double centerX, double mainY,
                                     double time, boolean ambientFx, double bossRatio) {
        double pulse = ambientFx ? 0.66 + 0.24 * Math.sin(time * 1.8) : 0.78;
        g.setFill(Color.web("#F3CE63", 0.12 + (1.0 - bossRatio) * 0.12));
        g.fillPolygon(new double[]{centerX - 190.0, centerX - 65.0, centerX + 65.0, centerX + 190.0},
                new double[]{mainY + 8.0, 690.0, 690.0, mainY + 8.0}, 4);
        g.setStroke(Color.web("#FFE27C", pulse));
        g.setLineWidth(14.0);
        g.strokeOval(centerX - 112.0, mainY - 134.0, 224.0, 224.0);
        g.strokeLine(centerX, mainY - 190.0, centerX, mainY + 98.0);
        g.strokeLine(centerX - 138.0, mainY - 22.0, centerX + 138.0, mainY - 22.0);
    }

    private void drawFinalDuelAltar(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        drawCrownSky(g, "#020106", "#24111F", Color.web("#FF456C"), time, ambientFx, 0.62);
        double centerX = WORLD_WIDTH * 0.5;
        double mainY = battlefieldIslandY;

        g.setFill(Color.web("#100A13"));
        g.fillPolygon(new double[]{centerX - 1_050.0, centerX - 520.0, centerX - 150.0,
                        centerX + 150.0, centerX + 520.0, centerX + 1_050.0},
                new double[]{WORLD_HEIGHT + 140.0, mainY + 250.0, mainY - 250.0,
                        mainY - 250.0, mainY + 250.0, WORLD_HEIGHT + 140.0}, 6);
        g.setFill(Color.web("#382134", 0.74));
        g.fillPolygon(new double[]{centerX - 500.0, centerX - 120.0,
                        centerX + 30.0, centerX + 280.0},
                new double[]{WORLD_HEIGHT + 140.0, mainY - 230.0,
                        mainY - 230.0, WORLD_HEIGHT + 140.0}, 4);

        // Fractured crown ribs hold the three upper duel ledges to the altar.
        for (Platform platform : platforms) {
            drawFinalDuelRib(g, platform, centerX, mainY);
        }
        for (Platform platform : platforms) {
            drawCrownStonePlatform(g, platform,
                    Color.web("#2B1B2B"), Color.web("#5A344B"), Color.web("#E76A7C"));
        }
        g.setStroke(Color.web("#FF5575", ambientFx ? 0.68 + 0.20 * Math.sin(time * 2.7) : 0.76));
        g.setLineWidth(11.0);
        for (int crack = -3; crack <= 3; crack++) {
            g.strokeLine(centerX + crack * 135.0, mainY + 30.0,
                    centerX + crack * 210.0, mainY + 560.0 + Math.abs(crack) * 70.0);
        }
    }

    private void drawFinalDuelRib(GraphicsContext g, Platform platform,
                                  double centerX, double mainY) {
        boolean main = Math.abs(platform.x - battlefieldIslandX) < 2.0
                && Math.abs(platform.w - battlefieldIslandW) < 2.0;
        double center = platform.x + platform.w * 0.5;
        double underside = platform.y + platform.h;
        if (main) {
            g.setFill(Color.web("#140C17"));
            g.fillPolygon(new double[]{platform.x + 60.0, platform.x + platform.w - 60.0,
                            centerX + 620.0, centerX - 620.0},
                    new double[]{underside, underside, WORLD_HEIGHT + 100.0, WORLD_HEIGHT + 100.0}, 4);
            return;
        }
        g.setStroke(Color.web("#160D18"));
        g.setLineWidth(48.0);
        g.strokeLine(centerX + (center - centerX) * 0.20,
                Math.min(mainY + 30.0, platform.y + 300.0), center, underside);
        g.setStroke(Color.web("#6D3A52", 0.76));
        g.setLineWidth(17.0);
        g.strokeLine(centerX + (center - centerX) * 0.20,
                Math.min(mainY + 30.0, platform.y + 300.0), center, underside);
    }

    private void drawNullRocAscent(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        drawCrownSky(g, "#02050D", "#12233A", Color.web("#EAC85E"), time, ambientFx, 0.52);
        drawCrownAscentTrail(g);
        for (Platform platform : platforms) drawCrownAscentFragment(g, platform);
        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#84E4F4"), Color.web("#111B2A"));
        }
        for (Platform platform : platforms) {
            drawCrownStonePlatform(g, platform,
                    Color.web("#242A3E"), Color.web("#565E76"), Color.web("#E2C568"));
        }
    }

    private void drawCrownAscentTrail(GraphicsContext g) {
        Platform previous = null;
        g.setStroke(Color.web("#8E793F", 0.52));
        g.setLineWidth(36.0);
        for (Platform platform : platforms.stream()
                .sorted(Comparator.comparingDouble(p -> p.y))
                .toList()) {
            if (previous != null) {
                g.strokeLine(previous.x + previous.w * 0.5, previous.y + previous.h + 80.0,
                        platform.x + platform.w * 0.5, platform.y - 80.0);
            }
            previous = platform;
        }
    }

    private void drawCrownAscentFragment(GraphicsContext g, Platform platform) {
        double center = platform.x + platform.w * 0.5;
        double underside = platform.y + platform.h;
        double drop = platform.w > 1_000.0 ? 680.0 : 330.0 + platform.w * 0.32;
        g.setFill(Color.web("#111827"));
        g.fillPolygon(new double[]{platform.x - 16.0, platform.x + platform.w + 16.0,
                        center + platform.w * 0.20, center - platform.w * 0.15},
                new double[]{underside, underside, underside + drop, underside + drop * 0.82}, 4);
        g.setFill(Color.web("#4A5064", 0.70));
        g.fillPolygon(new double[]{platform.x + 40.0, center,
                        center - platform.w * 0.06, platform.x + platform.w * 0.18},
                new double[]{underside + 10.0, underside + 10.0,
                        underside + drop * 0.74, underside + drop * 0.62}, 4);
    }

    private void drawVoidCrownArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        g.setFill(new RadialGradient(0, 0, 0.5, 0.42, 0.76, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#24113C")),
                new Stop(0.45, Color.web("#090718")),
                new Stop(1.0, Color.web("#010105"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);
        drawVoidCrownRing(g, time, ambientFx);

        for (Platform platform : platforms) drawVoidCrownFragment(g, platform);
        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#A785FF"), Color.web("#120E24"));
        }
        for (Platform platform : platforms) {
            drawCrownStonePlatform(g, platform,
                    Color.web("#241C38"), Color.web("#5B4E79"), Color.web("#D6B9FF"));
        }
    }

    private void drawVoidCrownRing(GraphicsContext g, double time, boolean ambientFx) {
        double centerX = WORLD_WIDTH * 0.5;
        double centerY = 1_300.0;
        double pulse = ambientFx ? 0.70 + 0.20 * Math.sin(time * 1.55) : 0.78;
        g.setFill(Color.web("#000002"));
        g.fillOval(centerX - 640.0, centerY - 640.0, 1_280.0, 1_280.0);
        g.setStroke(Color.web("#A47CFF", pulse * 0.62));
        g.setLineWidth(34.0);
        g.strokeOval(centerX - 730.0, centerY - 730.0, 1_460.0, 1_460.0);
        g.setStroke(Color.web("#F0D066", pulse * 0.50));
        g.setLineWidth(15.0);
        g.strokeOval(centerX - 820.0, centerY - 820.0, 1_640.0, 1_640.0);
        for (int shard = 0; shard < 18; shard++) {
            double angle = shard * Math.PI * 2.0 / 18.0 + (ambientFx ? time * 0.06 : 0.0);
            double x = centerX + Math.cos(angle) * 980.0;
            double y = centerY + Math.sin(angle) * 520.0;
            g.setFill(shard % 3 == 0 ? Color.web("#D4B75B", 0.52) : Color.web("#67518B", 0.62));
            g.fillPolygon(new double[]{x - 50.0, x, x + 58.0, x + 12.0},
                    new double[]{y + 18.0, y - 96.0, y + 10.0, y + 56.0}, 4);
        }
    }

    private void drawVoidCrownFragment(GraphicsContext g, Platform platform) {
        double center = platform.x + platform.w * 0.5;
        double underside = platform.y + platform.h;
        double direction = center < WORLD_WIDTH * 0.5 ? -1.0 : 1.0;
        if (Math.abs(center - WORLD_WIDTH * 0.5) < 200.0) direction = 0.0;
        g.setFill(Color.web("#130D20"));
        g.fillPolygon(new double[]{platform.x - 18.0, platform.x + platform.w + 18.0,
                        center + direction * platform.w * 0.22 + 70.0,
                        center + direction * platform.w * 0.35 - 40.0},
                new double[]{underside, underside, underside + 330.0,
                        underside + 470.0}, 4);
        g.setFill(Color.web("#4D3B68", 0.70));
        g.fillPolygon(new double[]{platform.x + 35.0, center,
                        center + direction * platform.w * 0.18,
                        center + direction * platform.w * 0.26},
                new double[]{underside + 9.0, underside + 9.0,
                        underside + 280.0, underside + 350.0}, 4);
    }

    private void drawCrownStonePlatform(GraphicsContext g, Platform platform,
                                        Color body, Color highlight, Color edge) {
        g.setFill(body);
        g.fillRoundRect(platform.x, platform.y, platform.w, platform.h, 22.0, 22.0);
        g.setFill(highlight.deriveColor(0, 1, 1, 0.74));
        g.fillRoundRect(platform.x + 10.0, platform.y + 8.0,
                Math.max(18.0, platform.w - 20.0), Math.max(8.0, platform.h * 0.28), 13.0, 13.0);
        g.setStroke(body.darker());
        g.setLineWidth(8.0);
        g.strokeRoundRect(platform.x, platform.y, platform.w, platform.h, 22.0, 22.0);
        g.setStroke(edge.deriveColor(0, 1, 1, 0.88));
        g.setLineWidth(6.0);
        g.strokeLine(platform.x + 14.0, platform.y - 3.0,
                platform.x + platform.w - 14.0, platform.y - 3.0);
        g.setStroke(edge.deriveColor(0, 0.7, 0.78, 0.30));
        g.setLineWidth(4.0);
        for (double x = platform.x + 110.0; x < platform.x + platform.w; x += 150.0) {
            g.strokeLine(x, platform.y + 12.0, x - 16.0, platform.y + platform.h - 8.0);
        }
    }

    @SuppressWarnings("unused")
    private void drawLegacyBeaconCrownBattlefield(GraphicsContext g, boolean ambientFx) {
        Bird boss;
        double bossRatio = 1.0;
        if (isUnitedFinaleClimaxContext()) {
            boss = unitedFinaleBoss();
            bossRatio = boss == null ? 1.0 : Math.clamp(boss.health / unitedFinaleBossMaxHealth(), 0.0, 1.0);
        } else if (bossRushModeActive && classicModeActive) {
            bossRushLeadBoss();
            bossRatio = bossRushEnemyHealthRatio();
        } else {
            for (Bird b : players) {
                if (b != null && b.health > 0 && b.isNullRockForm()) {
                    bossRatio = Math.clamp(b.health / Math.max(1.0, b.getMaxHealth()), 0.0, 1.0);
                    break;
                }
            }
        }
        for (int i = 0; i < 640; i++) {
            double ratio = i / 640.0;
            Color top = Color.web("#04060C");
            Color bottom = Color.web("#1A2036");
            Color c = top.interpolate(bottom, ratio);
            g.setFill(c);
            g.fillRect(0, i * (WORLD_HEIGHT / 640.0), WORLD_WIDTH, WORLD_HEIGHT / 640.0 + 3);
        }

        if (isNullRockCampaign() && !isNullRockDuelPhase()) {
            drawNullRockBackgroundCommander(g, ambientFx);
        }

        double time = System.currentTimeMillis() / 280.0;
        double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time) : 0.45;
        double centerX = WORLD_WIDTH / 2.0;
        double eclipseY = 420;

        g.setFill(Color.rgb(10, 10, 18, 0.94));
        g.fillOval(centerX - 210, eclipseY - 210, 420, 420);
        g.setStroke(Color.web("#FFE082", 0.38 + (1.0 - bossRatio) * 0.24 + pulse * 0.1));
        g.setLineWidth(22);
        g.strokeOval(centerX - 250, eclipseY - 250, 500, 500);
        g.setStroke(Color.web("#80DEEA", 0.14 + pulse * 0.08));
        g.setLineWidth(8);
        g.strokeOval(centerX - 280, eclipseY - 280, 560, 560);

        double beamBaseY = battlefieldIslandY + 30;
        g.setFill(Color.web("#FFE082", 0.16 + (1.0 - bossRatio) * 0.12 + pulse * 0.06));
        g.fillPolygon(
                new double[]{centerX - 150, centerX - 58, centerX + 58, centerX + 150},
                new double[]{beamBaseY, 620, 620, beamBaseY},
                4
        );
        g.setFill(Color.web("#80DEEA", 0.16 + pulse * 0.08));
        g.fillPolygon(
                new double[]{centerX - 60, centerX - 22, centerX + 22, centerX + 60},
                new double[]{beamBaseY, 590, 590, beamBaseY},
                4
        );

        for (int i = 0; i < 7; i++) {
            double shardX = 650 + i * 760 + Math.sin(time * 0.4 + i) * 28;
            double shardY = 260 + (i % 3) * 120 + Math.cos(time * 0.55 + i) * 20;
            double shardH = 90 + (i % 2) * 35;
            g.setFill(Color.web(i % 2 == 0 ? "#FFE082" : "#80DEEA", 0.24));
            g.fillPolygon(
                    new double[]{shardX - 28, shardX, shardX + 28},
                    new double[]{shardY + shardH * 0.45, shardY - shardH * 0.55, shardY + shardH * 0.45},
                    3
            );
        }

        g.setFill(Color.rgb(18, 12, 26, 0.55));
        g.fillRect(0, GROUND_Y - 240, WORLD_WIDTH, 320);

        for (Platform p : platforms) {
            boolean high = p.y < battlefieldIslandY - 320;
            g.setFill(high ? Color.web("#4E342E") : Color.web("#3B2F3B"));
            g.fillRoundRect(p.x, p.y, p.w, p.h, 34, 34);
            g.setFill(high ? Color.web("#FFE082", 0.26) : Color.web("#80DEEA", 0.22));
            g.fillRoundRect(p.x + 10, p.y - 12, p.w - 20, p.h + 18, 34, 34);
            g.setStroke(high ? Color.web("#FFF59D") : Color.web("#B2EBF2"));
            g.setLineWidth(high ? 4.2 : 3.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 34, 34);
        }
    }

    private void drawNullRockBackgroundCommander(GraphicsContext g, boolean ambientFx) {
        int phase = campaignMissionController == null ? 0 : campaignMissionController.phaseIndex();
        double time = System.nanoTime() / 1_000_000_000.0;
        double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 1.35) : 0.5;
        double cx = WORLD_WIDTH * 0.5;
        double cy = 920.0;
        double wingLift = 34.0 * Math.sin(time * 0.72);

        g.save();
        g.setFill(Color.web("#000005", 0.82));
        g.fillOval(cx - 2380, cy - 650 + wingLift, 2180, 940);
        g.fillOval(cx + 200, cy - 650 - wingLift, 2180, 940);
        g.setFill(Color.web("#090510", 0.96));
        g.fillOval(cx - 780, cy - 820, 1560, 1500);
        g.setFill(Color.web("#13061D", 0.94));
        g.fillOval(cx - 430, cy - 710, 860, 900);

        // A blunt meteor-beak and three fractured crown prongs make the true
        // form readable at arena scale without borrowing Vulture's fighter rig.
        g.setFill(Color.web("#211329"));
        g.fillPolygon(new double[]{cx - 120, cx + 1040, cx + 170, cx - 250},
                new double[]{cy - 310, cy - 70, cy + 95, cy + 10}, 4);
        g.setFill(Color.web("#A10B3B", 0.72 + pulse * 0.18));
        g.fillPolygon(new double[]{cx + 80, cx + 780, cx + 155},
                new double[]{cy - 255, cy - 82, cy - 35}, 3);
        g.setFill(Color.web("#050107"));
        for (int i = -1; i <= 1; i++) {
            double spikeX = cx + i * 230.0;
            g.fillPolygon(new double[]{spikeX - 115, spikeX, spikeX + 115},
                    new double[]{cy - 610, cy - 1060 - (i == 0 ? 120 : 0), cy - 610}, 3);
        }

        g.setEffect(new Glow(0.90));
        g.setFill(Color.web("#FF1744", 0.86 + pulse * 0.14));
        g.fillOval(cx - 265, cy - 400, 210, 150);
        g.fillOval(cx + 55, cy - 400, 210, 150);
        g.setFill(Color.web("#FFF3E0", 0.90));
        g.fillOval(cx - 175, cy - 355, 50, 40);
        g.fillOval(cx + 125, cy - 355, 50, 40);
        g.setEffect(null);

        g.setStroke(Color.web(phase >= 2 ? "#FF5252" : "#7C4DFF", 0.46 + pulse * 0.20));
        g.setLineWidth(14.0 + phase * 3.0);
        for (int i = 0; i < 5 + phase * 2; i++) {
            double offset = (i - 3.0) * 145.0;
            g.strokeLine(cx + offset, cy - 500 + i * 22.0,
                    cx + offset * 1.55, cy + 160 + (i % 2) * 80.0);
        }

        // Hundreds of commanded silhouettes stay presentation-only; combat
        // crows are spawned separately from fixed simulation ticks.
        g.setFill(Color.web("#020105", 0.70));
        for (int i = 0; i < 34; i++) {
            double angle = i * 2.399963229728653 + time * (0.10 + (i % 4) * 0.018);
            double radius = 760.0 + (i % 9) * 115.0;
            double bx = cx + Math.cos(angle) * radius;
            double by = 760.0 + Math.sin(angle * 1.4) * 430.0;
            double s = 18.0 + (i % 5) * 5.0;
            g.fillPolygon(new double[]{bx - s * 1.8, bx, bx + s * 1.8, bx},
                    new double[]{by, by - s * 0.55, by, by + s * 0.35}, 4);
        }
        g.restore();
    }

    private void drawDesertArena(GraphicsContext g, boolean ambientFx) {
        for (int i = 0; i < 620; i++) {
            double ratio = i / 620.0;
            Color c = ratio < 0.52
                    ? Color.web("#6B4055").interpolate(Color.web("#E78A59"), ratio / 0.52)
                    : Color.web("#E78A59").interpolate(Color.web("#F8D99A"), (ratio - 0.52) / 0.48);
            g.setFill(c);
            g.fillRect(0, i * (WORLD_HEIGHT / 620.0), WORLD_WIDTH, WORLD_HEIGHT / 620.0 + 3);
        }

        double time = System.currentTimeMillis() / 760.0;
        double horizonY = GROUND_Y - 250;
        double waterline = dockWaterSurfaceY();

        g.setFill(Color.web("#FFD180", 0.20));
        g.fillOval(250, 35, 770, 770);
        g.setFill(Color.web("#FFF0B4", 0.80));
        g.fillOval(470, 255, 330, 330);

        g.setFill(Color.web("#D8A45B", 0.46));
        for (int i = 0; i < 6; i++) {
            double duneX = i * 880 - 240;
            double duneW = 980 + (i % 2) * 120;
            double duneH = 92 + (i % 3) * 18;
            g.fillOval(duneX, horizonY + 26 + (i % 2) * 10, duneW, duneH);
        }

        g.setFill(Color.web("#B9733A", 0.52));
        g.fillPolygon(
                new double[]{DESERT_CLIFF_BASE_X - 120, DESERT_CLIFF_MID_X - 90, DESERT_CLIFF_TOP_X + 70,
                        DESERT_CLIFF_HIGH_X + 80, WORLD_WIDTH - 140, WORLD_WIDTH - 380, DESERT_CLIFF_BASE_X - 240},
                new double[]{horizonY + 120, horizonY - 70, horizonY - 190, horizonY - 156, horizonY - 20, horizonY + 126, horizonY + 188},
                7
        );
        g.setFill(Color.web("#D8A45B", 0.38));
        g.fillPolygon(
                new double[]{DESERT_CLIFF_BASE_X + 24, DESERT_CLIFF_MID_X - 24, DESERT_CLIFF_TOP_X + 92,
                        DESERT_CLIFF_HIGH_X + 70, WORLD_WIDTH - 210, WORLD_WIDTH - 420, DESERT_CLIFF_BASE_X - 96},
                new double[]{horizonY + 82, horizonY - 38, horizonY - 116, horizonY - 100, horizonY + 18, horizonY + 114, horizonY + 144},
                7
        );

        drawDesertDistantCaravanCity(g, horizonY);

        if (ambientFx) {
            g.setStroke(Color.web("#FFF8E1", 0.16));
            g.setLineWidth(2.2);
            for (int i = 0; i < 12; i++) {
                double lineY = 240 + i * 80;
                double x1 = 180 + Math.sin(time * 0.5 + i * 0.8) * 60;
                double x2 = WORLD_WIDTH - 220 + Math.cos(time * 0.45 + i * 0.65) * 70;
                g.strokeLine(x1, lineY, x2, lineY - 46);
            }
        }

        double tumbleSpan = WORLD_WIDTH + 900;
        for (int i = 0; i < 5; i++) {
            double tumbleX = (time * (42 + i * 7) + i * 1180) % tumbleSpan - 260;
            if (tumbleX < -120 || tumbleX > WORLD_WIDTH + 120) {
                continue;
            }
            double tumbleY = horizonY + 180 + Math.sin(time * (0.7 + i * 0.05) + i) * 12;
            double radius = 20 + i * 4;
            double alpha = ambientFx ? 0.28 : 0.18;
            drawDesertTumbleweed(g, tumbleX, tumbleY, radius, time * (70 + i * 11) + i * 21, alpha);
            if (ambientFx) {
                g.setFill(Color.web("#E3B26B", 0.16));
                g.fillOval(tumbleX - radius * 1.6, tumbleY + radius * 0.6, radius * 2.0, radius * 0.58);
                g.fillOval(tumbleX - radius * 0.2, tumbleY + radius * 0.8, radius * 1.4, radius * 0.42);
            }
        }

        g.setFill(Color.web("#C7904F"));
        g.fillRect(0, GROUND_Y, WORLD_WIDTH, WORLD_HEIGHT - GROUND_Y + 120);
        g.setFill(Color.web("#E6B96F"));
        for (int i = 0; i < 7; i++) {
            double duneX = -180 + i * 920;
            g.fillOval(duneX, GROUND_Y - 18 + (i % 2) * 8, 560, 54);
        }
        if (isDockWaterActive()) {
            double pondBowlX = dockWaterX - 28;
            double pondBowlW = dockWaterW + 56;
            double pondDepth = 320;
            double pondBowlY = waterline - pondDepth;
            double pondRimX = pondBowlX - 44;
            double pondRimW = pondBowlW + 88;
            double pondRimDepth = pondDepth + 54;
            double pondRimY = waterline - pondRimDepth;

            g.setFill(Color.web("#C68E4F", 0.92));
            g.fillArc(pondRimX, pondRimY, pondRimW, pondRimDepth * 2.0, 180, 180, ArcType.CHORD);
            g.setFill(Color.web("#E8C37A", 0.88));
            g.fillArc(pondRimX - 34, waterline - 108, pondRimW + 68, 204, 180, 180, ArcType.CHORD);

            g.setFill(Color.web("#2A8C9E", 0.92));
            g.fillArc(pondBowlX, pondBowlY, pondBowlW, pondDepth * 2.0, 180, 180, ArcType.CHORD);
            g.setFill(Color.web("#52C7C3", 0.30));
            g.fillArc(dockWaterX + 54, waterline - 6, dockWaterW - 108, 116, 180, 180, ArcType.CHORD);
            g.setFill(Color.web("#0F6270", 0.20));
            g.fillArc(dockWaterX + 112, waterline + 36, dockWaterW - 224, 168, 180, 180, ArcType.CHORD);
            g.setStroke(Color.web("#B2EBF2", 0.68));
            g.setLineWidth(4.0);
            g.strokeArc(pondBowlX, pondBowlY, pondBowlW, pondDepth * 2.0, 180, 180, ArcType.OPEN);
            g.strokeLine(dockWaterX + 22, waterline, dockWaterX + dockWaterW - 22, waterline);
            g.setStroke(Color.web("#E0F7FA", 0.24));
            g.setLineWidth(2.0);
            for (int i = 0; i < 7; i++) {
                double waveInset = 54 + i * 12;
                double waveY = waterline + 18 + i * 24;
                double shift = Math.sin(time * 1.5 + i * 0.75) * 7;
                g.strokeLine(dockWaterX + waveInset, waveY + shift, dockWaterX + dockWaterW - waveInset, waveY - shift * 0.45);
            }
            g.setFill(Color.web("#8BC34A", 0.58));
            g.fillOval(dockWaterX - 120, waterline - 44, 220, 86);
            g.fillOval(dockWaterX + dockWaterW - 120, waterline - 36, 210, 76);

            g.setFill(Color.web("#E6BC73"));
            g.fillPolygon(
                    new double[]{dockWaterX - 248, dockWaterX - 154, dockWaterX - 92, dockWaterX - 18, dockWaterX + 72, dockWaterX + 136, dockWaterX - 248},
                    new double[]{GROUND_Y + 12, GROUND_Y - 4, GROUND_Y - 22, waterline - 28, waterline - 4, GROUND_Y + 18, GROUND_Y + 18},
                    7
            );
            g.fillPolygon(
                    new double[]{dockWaterX + dockWaterW + 248, dockWaterX + dockWaterW + 154, dockWaterX + dockWaterW + 92,
                            dockWaterX + dockWaterW + 18, dockWaterX + dockWaterW - 72, dockWaterX + dockWaterW - 136,
                            dockWaterX + dockWaterW + 248},
                    new double[]{GROUND_Y + 12, GROUND_Y - 4, GROUND_Y - 22, waterline - 28, waterline - 4, GROUND_Y + 18, GROUND_Y + 18},
                    7
            );
        }

        g.setFill(Color.web("#E7C173"));
        g.fillRoundRect(0, GROUND_Y - 14, DESERT_OASIS_X - 18, 20, 18, 18);
        double desertMidGroundX = DESERT_OASIS_X + DESERT_OASIS_W + 18;
        g.fillRoundRect(desertMidGroundX, GROUND_Y - 14, DESERT_CLIFF_BASE_X - desertMidGroundX + 30, 20, 18, 18);
        g.setStroke(Color.web("#B07A43", 0.72));
        g.setLineWidth(2.6);
        g.strokeLine(0, GROUND_Y + 2, DESERT_OASIS_X - 26, GROUND_Y + 2);
        g.strokeLine(desertMidGroundX, GROUND_Y + 2, DESERT_CLIFF_BASE_X - 28, GROUND_Y + 2);

        double[][] cactusData = {
                {360, GROUND_Y - 200, 44, 190},
                {1780, GROUND_Y - 180, 38, 168},
                {2640, GROUND_Y - 190, 42, 178},
                {3920, GROUND_Y - 185, 40, 176}
        };
        g.setFill(Color.web("#3E7D4C"));
        g.setStroke(Color.web("#1B5E20"));
        g.setLineWidth(3.2);
        for (double[] cactus : cactusData) {
            double cx = cactus[0];
            double cy = cactus[1];
            double cw = cactus[2];
            double ch = cactus[3];
            g.fillRoundRect(cx, cy, cw, ch, 20, 20);
            g.fillRoundRect(cx - 22, cy + 54, 18, 64, 14, 14);
            g.fillRoundRect(cx + cw + 4, cy + 38, 18, 72, 14, 14);
            g.strokeRoundRect(cx, cy, cw, ch, 20, 20);
        }

        double palmBaseX = dockWaterX - 110;
        g.setStroke(Color.web("#7B5A38"));
        g.setLineWidth(16);
        g.strokeLine(palmBaseX, GROUND_Y - 8, palmBaseX - 40, GROUND_Y - 210);
        g.strokeLine(palmBaseX + 80, GROUND_Y - 8, palmBaseX + 120, GROUND_Y - 196);
        g.setStroke(Color.web("#2E7D32"));
        g.setLineWidth(9);
        for (int i = 0; i < 5; i++) {
            double leafY = GROUND_Y - 220 + i * 6;
            g.strokeLine(palmBaseX - 40, GROUND_Y - 210, palmBaseX - 140 + i * 8, leafY - 24 - i * 4);
            g.strokeLine(palmBaseX - 40, GROUND_Y - 210, palmBaseX + 40 + i * 16, leafY - 42 + i * 2);
            g.strokeLine(palmBaseX + 120, GROUND_Y - 196, palmBaseX + 20 - i * 12, leafY - 18 + i * 5);
            g.strokeLine(palmBaseX + 120, GROUND_Y - 196, palmBaseX + 210 - i * 4, leafY - 34 - i * 3);
        }

        double[][] cliffLayers = {
                {DESERT_CLIFF_BASE_X, DESERT_CLIFF_LOW_X, DESERT_CLIFF_LOW_Y},
                {DESERT_CLIFF_LOW_X - 72, DESERT_CLIFF_MID_X, DESERT_CLIFF_MID_Y},
                {DESERT_CLIFF_MID_X - 74, DESERT_CLIFF_TOP_X, DESERT_CLIFF_TOP_Y},
                {DESERT_CLIFF_TOP_X - 72, DESERT_CLIFF_HIGH_X, DESERT_CLIFF_HIGH_Y},
                {DESERT_CLIFF_HIGH_X - 56, DESERT_CLIFF_SUMMIT_X, DESERT_CLIFF_SUMMIT_Y}
        };
        Color[] cliffFill = {
                Color.web("#B17943"),
                Color.web("#A96E3C"),
                Color.web("#9B6334"),
                Color.web("#8D572D"),
                Color.web("#7E4D29")
        };
        Color[] cliffHighlight = {
                Color.web("#D29A57", 0.26),
                Color.web("#CB8E4E", 0.24),
                Color.web("#C07D43", 0.22),
                Color.web("#AF6E39", 0.18),
                Color.web("#9C6031", 0.16)
        };
        for (int i = 0; i < cliffLayers.length; i++) {
            double baseX = cliffLayers[i][0];
            double topX = cliffLayers[i][1];
            double topY = cliffLayers[i][2];
            g.setFill(cliffFill[i]);
            g.fillPolygon(
                    new double[]{baseX, topX, WORLD_WIDTH, WORLD_WIDTH, baseX},
                    new double[]{GROUND_Y, topY, topY, GROUND_Y, GROUND_Y},
                    5
            );
            g.setFill(cliffHighlight[i]);
            g.fillPolygon(
                    new double[]{baseX + 48, topX + 56, WORLD_WIDTH - 26, WORLD_WIDTH - 84, baseX + 110},
                    new double[]{GROUND_Y - 10, topY + 34, topY + 28, GROUND_Y - 126, GROUND_Y - 60},
                    5
            );
            g.setStroke(Color.web("#6C4427", 0.78));
            g.setLineWidth(3.0);
            g.strokeLine(baseX, GROUND_Y, topX, topY);
            g.strokeLine(topX, topY, WORLD_WIDTH, topY);
        }

        // Every freestanding gameplay ledge is the roof of a grounded adobe
        // watchtower.  Drawing this before the collision cap lets the cap and
        // tower read as one object while leaving the open arch non-solid.
        for (Platform p : platforms) {
            if (p.y >= GROUND_Y - 40.0 || isDesertCliffPlatform(p)
                    || p.x < 0.0 || p.x + p.w > WORLD_WIDTH) continue;
            drawDesertWaystation(g, p);
        }

        for (Platform p : platforms) {
            if (p.y >= GROUND_Y - 6 || p.x < -50 || p.x > WORLD_WIDTH - 50) {
                continue;
            }
            boolean plateau = p.y < GROUND_Y - 80;
            boolean cliffPlatform = isDesertCliffPlatform(p);
            Color rock = cliffPlatform ? Color.web("#8A542C") : plateau ? Color.web("#936033") : Color.web("#A16B35");
            Color cap = cliffPlatform ? Color.web("#D4A05A") : plateau ? Color.web("#C99556") : Color.web("#D7A35E");
            g.setFill(rock);
            g.fillRoundRect(p.x, p.y, p.w, p.h, 24, 24);
            g.setFill(cap);
            g.fillRoundRect(p.x + 10, p.y - 12, Math.max(24, p.w - 20), Math.max(20, p.h * 0.36), 24, 24);
            g.setStroke(Color.web("#5D4037"));
            g.setLineWidth(3.2);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 24, 24);
        }
    }

    private void drawDesertDistantCaravanCity(GraphicsContext g, double horizonY) {
        // A half-buried caravan city fills the old empty centre without
        // pretending to be collision geometry.  Its bases all disappear into
        // the same dune shelf, so no tower can read as floating.
        double cityFloor = horizonY + 205.0;
        g.setFill(Color.web("#75483D", 0.30));
        double[][] towers = {
                {1_420, 390, 250}, {1_850, 510, 330}, {2_360, 355, 220},
                {2_780, 650, 410}, {3_400, 445, 285}, {3_900, 570, 355}
        };
        for (double[] tower : towers) {
            double x = tower[0];
            double w = tower[1];
            double h = tower[2];
            double top = cityFloor - h;
            g.fillPolygon(new double[]{x, x + w * 0.5, x + w, x + w, x},
                    new double[]{top + 72.0, top, top + 72.0, cityFloor, cityFloor}, 5);
            g.setFill(Color.web("#F1B86F", 0.16));
            for (double windowX = x + 62.0; windowX < x + w - 35.0; windowX += 90.0) {
                g.fillRoundRect(windowX, top + 110.0, 24.0, 54.0, 12.0, 12.0);
            }
            g.setFill(Color.web("#75483D", 0.30));
        }

        g.setStroke(Color.web("#6A4038", 0.36));
        g.setLineWidth(34.0);
        g.strokeArc(2_070.0, cityFloor - 520.0, 1_760.0, 840.0,
                12.0, 156.0, ArcType.OPEN);
        g.setStroke(Color.web("#E8B36B", 0.15));
        g.setLineWidth(8.0);
        g.strokeArc(2_115.0, cityFloor - 475.0, 1_670.0, 750.0,
                12.0, 156.0, ArcType.OPEN);
    }

    private void drawDesertWaystation(GraphicsContext g, Platform platform) {
        double top = platform.y + platform.h - 3.0;
        double bottom = GROUND_Y + 12.0;
        double inset = Math.min(30.0, platform.w * 0.16);
        double left = platform.x + inset;
        double right = platform.x + platform.w - inset;
        double centre = (left + right) * 0.5;

        g.setFill(Color.web("#865637"));
        g.fillPolygon(new double[]{left, right, right + 18.0, left - 18.0},
                new double[]{top, top, bottom, bottom}, 4);
        g.setFill(Color.web("#B97B48", 0.72));
        g.fillRect(left + 10.0, top + 22.0, Math.max(18.0, right - left - 20.0),
                Math.max(12.0, bottom - top - 22.0));

        double openingW = Math.max(34.0, (right - left) * 0.48);
        double openingH = Math.min(150.0, Math.max(72.0, bottom - top - 42.0));
        g.setFill(Color.web("#3E2B31", 0.74));
        g.fillArc(centre - openingW * 0.5, bottom - openingH,
                openingW, openingH * 0.72, 0.0, 180.0, ArcType.CHORD);
        g.fillRect(centre - openingW * 0.5, bottom - openingH * 0.64,
                openingW, openingH * 0.64);

        g.setStroke(Color.web("#E6B568", 0.66));
        g.setLineWidth(5.0);
        g.strokeLine(left - 12.0, top + 20.0, right + 12.0, top + 20.0);
        g.strokeLine(left - 18.0, bottom, right + 18.0, bottom);
    }

    private boolean isDesertCliffPlatform(Platform p) {
        return p != null && p.x >= DESERT_CLIFF_LOW_X - 60 && p.y < GROUND_Y - 40;
    }

    private void drawDesertTumbleweed(GraphicsContext g, double x, double y, double radius, double rotationDeg, double alpha) {
        g.save();
        g.translate(x, y);
        g.rotate(rotationDeg);
        g.setStroke(Color.web("#8A6138", alpha));
        g.setLineWidth(Math.max(1.6, radius * 0.08));
        for (int i = 0; i < 3; i++) {
            double ring = radius * (1.0 - i * 0.18);
            g.strokeOval(-ring, -ring * 0.82, ring * 2.0, ring * 1.64);
        }
        for (int i = 0; i < 8; i++) {
            double angle = i * Math.PI / 4.0;
            double inner = radius * 0.24;
            double outer = radius * 0.98;
            g.strokeLine(Math.cos(angle) * inner, Math.sin(angle) * inner,
                    Math.cos(angle) * outer, Math.sin(angle) * outer);
        }
        g.restore();
    }

    private void drawDockArena(GraphicsContext g, boolean ambientFx) {
        if (activeArenaGeometryVariant == MapVariant.TITAN_DOCK) {
            drawTitanDockArena(g, ambientFx);
            return;
        }
        for (int i = 0; i < 620; i++) {
            double ratio = i / 620.0;
            Color c = Color.web("#0B2030").interpolate(Color.web("#2C6E87"), ratio);
            g.setFill(c);
            g.fillRect(0, i * (WORLD_HEIGHT / 620.0), WORLD_WIDTH, WORLD_HEIGHT / 620.0 + 3);
        }

        double time = System.currentTimeMillis() / 820.0;
        double horizonY = GROUND_Y - 250;
        g.setFill(Color.web("#FFD180", 0.26));
        g.fillOval(420, 140, 520, 520);
        g.setFill(Color.web("#FFFFFF", 0.08));
        g.fillOval(520, 220, 320, 320);

        g.setFill(Color.web("#10293A", 0.85));
        for (int i = 0; i < 9; i++) {
            double baseX = i * 720 - 120;
            double height = 220 + (i % 3) * 60;
            g.fillRect(baseX, horizonY - height, 280, height);
            g.fillRect(baseX + 220, horizonY - height * 0.72, 180, height * 0.72);
            g.fillPolygon(
                    new double[]{baseX + 420, baseX + 540, baseX + 660},
                    new double[]{horizonY, horizonY - 120 - (i % 2) * 40, horizonY},
                    3
            );
        }

        g.setFill(Color.web("#0C1D28", 0.65));
        g.fillRect(0, horizonY, WORLD_WIDTH, WORLD_HEIGHT - horizonY);
        g.setStroke(Color.web("#7FDBFF", 0.14));
        g.setLineWidth(3);
        for (int i = 0; i < 18; i++) {
            double waveY = horizonY + 55 + i * 28;
            double y1 = waveY + Math.sin(time + i * 0.8) * 5;
            g.strokeLine(0, y1, WORLD_WIDTH, y1);
        }

        g.setFill(Color.web("#0E2430", 0.82));
        g.fillPolygon(
                new double[]{820, 980, 1180, 1360, 1240, 900},
                new double[]{horizonY + 70, horizonY - 20, horizonY + 10, horizonY + 100, horizonY + 130, horizonY + 120},
                6
        );
        g.fillPolygon(
                new double[]{4180, 4370, 4600, 4780, 4660, 4300},
                new double[]{horizonY + 40, horizonY - 40, horizonY - 10, horizonY + 96, horizonY + 126, horizonY + 116},
                6
        );
        g.setFill(Color.web("#D7CCC8", 0.16));
        g.fillPolygon(new double[]{1000, 1170, 1000}, new double[]{horizonY - 10, horizonY + 86, horizonY + 146}, 3);
        g.fillPolygon(new double[]{4390, 4580, 4390}, new double[]{horizonY - 30, horizonY + 78, horizonY + 146}, 3);

        if (ambientFx) {
            g.setFill(Color.web("#FFF8E1", 0.12));
            for (int i = 0; i < 8; i++) {
                double gullX = 500 + i * 650 + Math.sin(time * 0.55 + i * 0.7) * 70;
                double gullY = 180 + (i % 3) * 80 + Math.cos(time * 0.75 + i) * 18;
                g.fillArc(gullX - 20, gullY, 26, 14, 15, 145, ArcType.OPEN);
                g.fillArc(gullX - 2, gullY, 26, 14, 20, 145, ArcType.OPEN);
            }
        }

        double waterline = dockWaterSurfaceY();
        g.setFill(Color.web("#8D6E63"));
        g.fillRect(0, GROUND_Y - 6, dockWaterX - 24, WORLD_HEIGHT - GROUND_Y + 180);
        g.setFill(Color.web("#C8A268"));
        g.fillRect(0, GROUND_Y - 20, dockWaterX - 46, WORLD_HEIGHT - GROUND_Y + 180);
        g.setFill(Color.web("#E6C68A", 0.72));
        g.fillPolygon(
                new double[]{dockWaterX - 300, dockWaterX - 120, dockWaterX + 34, dockWaterX + 10, dockWaterX - 260},
                new double[]{GROUND_Y + 22, GROUND_Y - 58, GROUND_Y - 26, GROUND_Y + 42, GROUND_Y + 76},
                5
        );
        g.setFill(Color.web("#F4D79E", 0.34));
        for (int i = 0; i < 6; i++) {
            double duneX = 220 + i * 320;
            g.fillOval(duneX, GROUND_Y - 34 + (i % 2) * 8, 240, 54);
        }

        g.setFill(Color.web("#0A2533", 0.84));
        g.fillRect(dockWaterX, waterline, dockWaterW, WORLD_HEIGHT - waterline + 220);
        g.setFill(Color.web("#173C4D", 0.48));
        g.fillRect(dockWaterX + 30, waterline + 16, dockWaterW - 60, 34);
        g.setStroke(Color.web("#80DEEA", 0.24));
        g.setLineWidth(3.2);
        for (int i = 0; i < 14; i++) {
            double waveY = waterline + 18 + i * 26;
            double waveShift = Math.sin(time * 1.2 + i * 0.9) * 8;
            g.strokeLine(dockWaterX, waveY + waveShift, dockWaterX + dockWaterW, waveY - waveShift * 0.35);
        }
        g.setStroke(Color.web("#B3E5FC", 0.55));
        g.setLineWidth(4);
        g.strokeLine(dockWaterX, waterline, dockWaterX + dockWaterW, waterline);

        double shipX = dockShipVisualX();
        double shipY = dockShipVisualY();
        double shipScale = DOCK_SHIP_SCALE;
        boolean shipActive = dockShipBomb != null && !dockShipBomb.exploded;
        double cannonGlow = shipActive
                ? (dockShipBomb.fired
                ? 0.22 + Math.max(0.0, dockShipBomb.cannonFlashFrames / (double) DOCK_BOMB_CANNON_FLASH_FRAMES) * 0.55
                : 0.16 + (1.0 - Math.max(0, dockShipBomb.launchDelayFrames) / (double) DOCK_BOMB_LOCKON_FRAMES) * 0.28)
                : 0.08;
        g.save();
        g.translate(shipX, shipY);
        g.scale(shipScale, shipScale);
        g.setFill(Color.web("#132734", 0.92));
        g.fillPolygon(
                new double[]{30, 220, 670, 860, 930, 180},
                new double[]{154, 106, 114, 148, 198, 214},
                6
        );
        g.setFill(Color.web("#1E3948", 0.76));
        g.fillPolygon(
                new double[]{88, 232, 646, 780, 196},
                new double[]{150, 118, 126, 152, 186},
                5
        );
        g.setStroke(Color.web("#4E342E", 0.74));
        g.setLineWidth(10);
        g.strokeLine(308, -242, 308, 116);
        g.strokeLine(520, -188, 520, 132);
        g.strokeLine(714, -120, 714, 144);
        g.setStroke(Color.web("#BCAAA4", 0.24));
        g.setLineWidth(2.4);
        g.strokeLine(308, -210, 122, 20);
        g.strokeLine(308, -110, 620, 70);
        g.strokeLine(520, -150, 312, 20);
        g.strokeLine(520, -38, 756, 88);
        g.strokeLine(714, -92, 566, 48);
        g.setFill(Color.web("#263238", 0.84));
        g.fillPolygon(
                new double[]{308, 118, 308},
                new double[]{-214, -24, 28},
                3
        );
        g.fillPolygon(
                new double[]{520, 332, 520},
                new double[]{-150, 14, 54},
                3
        );
        g.fillPolygon(
                new double[]{714, 572, 714},
                new double[]{-82, 34, 72},
                3
        );
        g.setFill(Color.web("#FFECB3", 0.14));
        for (int i = 0; i < 5; i++) {
            g.fillOval(210 + i * 112, 136 + (i % 2) * 6, 38, 16);
        }
        g.setStroke(Color.web("#3E2723", 0.9));
        g.setLineWidth(16);
        g.strokeLine(78, 146, -18, 134);
        g.setStroke(Color.web("#4A2E1F", 0.92));
        g.setLineWidth(10);
        g.strokeLine(82, 148, -36, 132);
        g.setFill(Color.web("#FFCC80", cannonGlow));
        g.fillOval(4, 106, 132, 58);
        g.setFill(Color.web("#FFE082", cannonGlow * 0.92));
        g.fillOval(-12, 114, 92, 42);
        g.restore();

        g.setFill(Color.web("#4E342E", 0.95));
        g.fillRoundRect(720, GROUND_Y - 250, 420, 140, 18, 18);
        g.fillRoundRect(980, GROUND_Y - 420, 300, 170, 18, 18);
        g.setFill(Color.web("#6D4C41", 0.94));
        g.fillPolygon(
                new double[]{920, 1090, 1280, 1200, 980},
                new double[]{GROUND_Y - 420, GROUND_Y - 580, GROUND_Y - 420, GROUND_Y - 350, GROUND_Y - 350},
                5
        );
        g.setStroke(Color.web("#D7CCC8", 0.22));
        g.setLineWidth(3);
        for (int i = 0; i < 3; i++) {
            g.strokeRect(800 + i * 90, GROUND_Y - 200, 54, 40);
            g.strokeRect(1020 + i * 68, GROUND_Y - 360, 42, 34);
        }

        g.setStroke(Color.web("#5D4037", 0.85));
        g.setLineWidth(14);
        g.strokeLine(3180, GROUND_Y - 192, 4880, GROUND_Y - 192);
        g.setLineWidth(10);
        for (double supportX = 3240; supportX <= 4820; supportX += 220) {
            g.strokeLine(supportX, GROUND_Y - 164, supportX, waterline + 110);
        }
        g.setStroke(Color.web("#BCAAA4", 0.28));
        g.setLineWidth(2.2);
        g.strokeLine(3300, GROUND_Y - 540, 3460, GROUND_Y - 220);
        g.strokeLine(4300, GROUND_Y - 780, 4520, GROUND_Y - 220);

        for (Platform p : platforms) {
            boolean skiff = isDockSkiffPlatform(p);
            boolean bridge = p.x >= 3000;
            boolean highRigging = p.y < GROUND_Y - 520;
            Color wood = highRigging ? Color.web("#5D4037") : Color.web("#6D4C41");
            Color trim = highRigging ? Color.web("#A1887F") : Color.web("#8D6E63");
            g.setFill(wood);
            g.fillRoundRect(p.x, p.y, p.w, p.h, 24, 24);
            g.setStroke(Color.web("#3E2723"));
            g.setLineWidth(3.4);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 24, 24);
            g.setStroke(trim);
            g.setLineWidth(2.0);
            for (int i = 1; i < Math.max(2, (int) (p.w / 110)); i++) {
                double plankX = p.x + i * (p.w / Math.max(2, (int) (p.w / 110) + 1));
                g.strokeLine(plankX, p.y + 6, plankX, p.y + p.h - 6);
            }
            g.setFill(Color.web("#D7CCC8", 0.16));
            g.fillRoundRect(p.x + 10, p.y + 6, Math.max(20, p.w - 20), Math.max(10, p.h * 0.24), 18, 18);

            if (skiff) {
                g.setStroke(Color.web("#4E342E", 0.85));
                g.setLineWidth(5);
                g.strokeArc(p.x - 18, p.y + 4, p.w + 36, p.h + 30, 0, 180, ArcType.OPEN);
            } else if (bridge && p.y >= GROUND_Y - 260) {
                g.setStroke(Color.web("#4E342E", 0.72));
                g.setLineWidth(7);
                for (double postX = p.x + 40; postX < p.x + p.w - 10; postX += 120) {
                    g.strokeLine(postX, p.y + p.h, postX, waterline + 95);
                }
            } else if (p.y >= battlefieldIslandY - 180) {
                g.setStroke(Color.web("#4E342E", 0.72));
                g.setLineWidth(8);
                double supportBottom = p.x + p.w < dockWaterX - 20 ? GROUND_Y + 10 : waterline + 30;
                for (double postX = p.x + 50; postX < p.x + p.w - 20; postX += 140) {
                    g.strokeLine(postX, p.y + p.h, postX, supportBottom);
                }
            } else {
                double mastBaseX = p.x + p.w / 2;
                g.setStroke(Color.web("#5D4037", 0.72));
                g.setLineWidth(5);
                g.strokeLine(mastBaseX, battlefieldIslandY + 8, mastBaseX, p.y + p.h);
                g.setStroke(Color.web("#D7CCC8", 0.22));
                g.setLineWidth(2);
                g.strokeLine(mastBaseX, p.y + p.h, mastBaseX - 160, battlefieldIslandY + 20);
                g.strokeLine(mastBaseX, p.y + p.h, mastBaseX + 160, battlefieldIslandY + 20);
            }
        }

        double leverBaseY = dockLeverY + 26;
        boolean leverReady = dockLeverCooldown <= 0;
        g.setFill(leverReady ? Color.web("#7B5A3B") : Color.web("#546E7A"));
        g.fillRoundRect(dockLeverX - 34, leverBaseY - 10, 68, 18, 10, 10);
        g.setStroke(Color.web("#2E1F16"));
        g.setLineWidth(3);
        g.strokeRoundRect(dockLeverX - 34, leverBaseY - 10, 68, 18, 10, 10);
        double handleTipX = dockLeverX + (leverReady ? 18 : -18);
        double handleTipY = dockLeverY + (leverReady ? -20 : -34);
        g.setStroke(leverReady ? Color.web("#FFCA28") : Color.web("#90A4AE"));
        g.setLineWidth(5);
        g.strokeLine(dockLeverX, leverBaseY - 4, handleTipX, handleTipY);
        g.setFill(leverReady ? Color.web("#FFE082") : Color.web("#CFD8DC"));
        g.fillOval(handleTipX - 8, handleTipY - 8, 16, 16);
        g.setFill(Color.web("#FFF8E1", leverReady ? 0.72 : 0.46));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 20));
        String leverText = leverReady ? "LEVER READY" : "RELOAD " + (int) Math.ceil(dockLeverCooldown / 60.0) + "s";
        g.fillText(leverText, dockLeverX - 60, dockLeverY - 24);

        for (WindVent v : windVents) {
            g.setFill(Color.web("#B3E5FC", ambientFx ? 0.22 : 0.14));
            g.fillOval(v.x + v.w / 2 - 120, v.y - 180, 240, 300);
            g.setStroke(Color.web("#E1F5FE", 0.18));
            g.setLineWidth(2);
            g.strokeOval(v.x + v.w / 2 - 94, v.y - 140, 188, 224);
        }
    }

    private void drawTitanDockArena(GraphicsContext g, boolean ambientFx) {
        double time = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        double waterline = dockWaterSurfaceY();
        double pulse = ambientFx ? 0.66 + 0.22 * Math.sin(time * 1.9) : 0.76;

        g.setFill(new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#030812")),
                new Stop(0.52, Color.web("#183248")),
                new Stop(1.0, Color.web("#57656A"))));
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);

        drawTitanDockStormBank(g, time, ambientFx);
        drawTitanDockDistantHarbor(g, waterline);
        drawTitanDockWater(g, waterline, time, ambientFx);
        drawTitanDockDrydockFrame(g, waterline);

        // Every authored surface is supported before its collision deck is
        // painted. The central decks are part of the dreadnought, the two low
        // shelves are armored service barges, and high catwalks terminate on a
        // mast or gantry instead of hanging from invisible lines.
        for (Platform p : platforms) drawTitanDockSupport(g, p, waterline);
        drawTitanDockHull(g, waterline);
        drawTitanDockCommandTower(g);

        for (WindVent vent : windVents) {
            drawSkyVariantWindChannel(g, vent, time, ambientFx,
                    Color.web("#78DDF2"), Color.web("#102833"));
        }
        for (Platform p : platforms) drawTitanDockDeck(g, p);

        drawTitanDockCannon(g, pulse);
        drawTitanDockLever(g);
        drawTitanDockWarningLamps(g, pulse);
    }

    private void drawTitanDockStormBank(GraphicsContext g, double time, boolean ambientFx) {
        g.setFill(Color.web("#AAB9C2", 0.16));
        for (int i = 0; i < 9; i++) {
            double drift = ambientFx ? Math.sin(time * 0.13 + i * 0.8) * 64.0 : 0.0;
            double x = -520.0 + i * 760.0 + drift;
            double y = 170.0 + (i % 3) * 135.0;
            g.fillOval(x, y, 1_020.0, 250.0);
            g.fillOval(x + 180.0, y - 75.0, 620.0, 230.0);
        }
        g.setStroke(Color.web("#B9D8E5", 0.20));
        g.setLineWidth(7.0);
        for (double x = 410.0; x < WORLD_WIDTH; x += 930.0) {
            g.strokeLine(x, 120.0, x - 125.0, 410.0);
        }
    }

    private void drawTitanDockDistantHarbor(GraphicsContext g, double waterline) {
        g.setFill(Color.web("#091824", 0.88));
        for (int i = 0; i < 13; i++) {
            double x = -180.0 + i * 520.0;
            double height = 250.0 + (i % 4) * 95.0;
            g.fillRect(x, waterline - height, 260.0, height);
            g.fillPolygon(new double[]{x + 210.0, x + 330.0, x + 450.0},
                    new double[]{waterline, waterline - 170.0 - (i % 2) * 70.0, waterline}, 3);
        }
        g.setFill(Color.web("#D8B462", 0.38));
        for (double x = 150.0; x < WORLD_WIDTH; x += 360.0) {
            g.fillRect(x, waterline - 75.0 - (x % 3.0) * 18.0, 20.0, 10.0);
        }
    }

    private void drawTitanDockWater(GraphicsContext g, double waterline,
                                    double time, boolean ambientFx) {
        g.setFill(Color.web("#04131E"));
        g.fillRect(0, waterline, WORLD_WIDTH, WORLD_HEIGHT - waterline + 260.0);
        g.setFill(Color.web("#0D3548", 0.76));
        g.fillRect(0, waterline + 18.0, WORLD_WIDTH, 56.0);
        g.setStroke(Color.web("#69D6EE", 0.26));
        g.setLineWidth(4.0);
        for (int wave = 0; wave < 19; wave++) {
            double y = waterline + 20.0 + wave * 27.0;
            double shift = ambientFx ? Math.sin(time * 1.1 + wave * 0.63) * 20.0 : 0.0;
            g.strokeLine(0, y + shift, WORLD_WIDTH, y - shift * 0.32);
        }
        g.setStroke(Color.web("#B7ECF6", 0.58));
        g.setLineWidth(6.0);
        g.strokeLine(0, waterline, WORLD_WIDTH, waterline);
    }

    private void drawTitanDockDrydockFrame(GraphicsContext g, double waterline) {
        double[] gantryX = {350.0, 1_180.0, 4_820.0, 5_650.0};
        g.setFill(Color.web("#0A141E"));
        for (double x : gantryX) {
            g.fillRect(x - 72.0, 430.0, 144.0, waterline - 430.0);
            g.setStroke(Color.web("#506777", 0.58));
            g.setLineWidth(10.0);
            for (double y = 520.0; y < waterline - 80.0; y += 190.0) {
                g.strokeLine(x - 56.0, y, x + 56.0, y + 92.0);
                g.strokeLine(x + 56.0, y, x - 56.0, y + 92.0);
            }
        }
        g.setStroke(Color.web("#101C27"));
        g.setLineWidth(44.0);
        g.strokeLine(350.0, 490.0, 1_500.0, 490.0);
        g.strokeLine(4_500.0, 490.0, 5_650.0, 490.0);
        g.setStroke(Color.web("#6C8390"));
        g.setLineWidth(15.0);
        g.strokeLine(350.0, 490.0, 1_500.0, 490.0);
        g.strokeLine(4_500.0, 490.0, 5_650.0, 490.0);
        g.setStroke(Color.web("#D9A734", 0.68));
        g.setLineWidth(7.0);
        g.strokeLine(390.0, 505.0, 1_460.0, 505.0);
        g.strokeLine(4_540.0, 505.0, 5_610.0, 505.0);
    }

    private void drawTitanDockSupport(GraphicsContext g, Platform p, double waterline) {
        boolean mainDeck = Math.abs(p.x - battlefieldIslandX) < 1.0
                && Math.abs(p.w - battlefieldIslandW) < 1.0;
        boolean serviceBarge = p.w >= 800.0 && !mainDeck;
        double centerX = p.x + p.w * 0.5;
        double underside = p.y + p.h;
        if (mainDeck) return;

        if (serviceBarge) {
            g.setFill(Color.web("#111E28"));
            g.fillPolygon(new double[]{p.x - 25.0, p.x + p.w + 25.0,
                            p.x + p.w - 105.0, p.x + 110.0},
                    new double[]{underside, underside, waterline + 100.0, waterline + 100.0}, 4);
            g.setFill(Color.web("#314551", 0.70));
            g.fillPolygon(new double[]{p.x + 45.0, p.x + p.w - 45.0,
                            p.x + p.w - 135.0, p.x + 130.0},
                    new double[]{underside + 18.0, underside + 18.0,
                            waterline + 45.0, waterline + 45.0}, 4);
            return;
        }

        double anchorY = mainDeckTopAt(centerX);
        if (!Double.isFinite(anchorY)) anchorY = waterline + 28.0;
        g.setStroke(Color.web("#0D1821"));
        g.setLineWidth(p.w >= 500.0 ? 48.0 : 32.0);
        g.strokeLine(centerX, underside, centerX, anchorY);
        g.setStroke(Color.web("#4D6471", 0.82));
        g.setLineWidth(p.w >= 500.0 ? 19.0 : 13.0);
        g.strokeLine(centerX, underside, centerX, anchorY);

        double brace = Math.min(170.0, p.w * 0.32);
        g.setStroke(Color.web("#374C58", 0.72));
        g.setLineWidth(12.0);
        g.strokeLine(centerX, underside + 75.0, centerX - brace, underside);
        g.strokeLine(centerX, underside + 75.0, centerX + brace, underside);

        // Outer crane decks visibly hang from their matching gantry beams.
        if (p.y < GROUND_Y - 950.0 && (centerX < 1_600.0 || centerX > 4_400.0)) {
            double beamY = 510.0;
            g.setStroke(Color.web("#728995", 0.72));
            g.setLineWidth(9.0);
            g.strokeLine(centerX, beamY, centerX, p.y);
        }
    }

    private double mainDeckTopAt(double x) {
        if (x >= battlefieldIslandX && x <= battlefieldIslandX + battlefieldIslandW) {
            return battlefieldIslandY + 180.0;
        }
        return Double.NaN;
    }

    private void drawTitanDockHull(GraphicsContext g, double waterline) {
        double left = battlefieldIslandX - 165.0;
        double right = battlefieldIslandX + battlefieldIslandW + 165.0;
        double deckBottom = battlefieldIslandY + 105.0;
        g.setFill(Color.web("#0A141D"));
        g.fillPolygon(new double[]{left, right, right - 250.0, 3_620.0, 3_000.0,
                        2_380.0, left + 250.0},
                new double[]{deckBottom, deckBottom, waterline + 40.0, waterline + 250.0,
                        waterline + 360.0, waterline + 250.0, waterline + 40.0}, 7);
        g.setFill(Color.web("#263945"));
        g.fillPolygon(new double[]{left + 120.0, right - 120.0, right - 330.0,
                        3_000.0, left + 330.0},
                new double[]{deckBottom + 45.0, deckBottom + 45.0, waterline + 18.0,
                        waterline + 235.0, waterline + 18.0}, 5);
        g.setStroke(Color.web("#6A8190", 0.68));
        g.setLineWidth(12.0);
        g.strokeLine(left + 180.0, deckBottom + 86.0, right - 180.0, deckBottom + 86.0);
        g.setStroke(Color.web("#E0AC39", 0.72));
        g.setLineWidth(7.0);
        g.strokeLine(left + 260.0, deckBottom + 120.0, right - 260.0, deckBottom + 120.0);
        g.setFill(Color.web("#A6CEDB", 0.34));
        for (double x = left + 360.0; x < right - 300.0; x += 260.0) {
            g.fillRoundRect(x, deckBottom + 165.0, 94.0, 28.0, 12.0, 12.0);
        }
    }

    private void drawTitanDockCommandTower(GraphicsContext g) {
        double x = 3_000.0;
        double baseY = battlefieldIslandY;
        g.setFill(Color.web("#121F29"));
        g.fillPolygon(new double[]{x - 330.0, x - 240.0, x + 240.0, x + 330.0},
                new double[]{baseY, baseY - 680.0, baseY - 680.0, baseY}, 4);
        g.setFill(Color.web("#314754"));
        g.fillRoundRect(x - 205.0, baseY - 720.0, 410.0, 130.0, 30.0, 30.0);
        g.setFill(Color.web("#8FD4E5", 0.54));
        for (int window = -2; window <= 2; window++) {
            g.fillRoundRect(x + window * 72.0 - 23.0, baseY - 682.0, 46.0, 34.0, 9.0, 9.0);
        }
        g.setStroke(Color.web("#506B7A"));
        g.setLineWidth(18.0);
        g.strokeLine(x, baseY - 720.0, x, baseY - 1_220.0);
        g.setStroke(Color.web("#D9A52E", 0.78));
        g.setLineWidth(7.0);
        g.strokeLine(x - 170.0, baseY - 850.0, x + 170.0, baseY - 850.0);
    }

    private void drawTitanDockDeck(GraphicsContext g, Platform p) {
        boolean mainDeck = Math.abs(p.x - battlefieldIslandX) < 1.0
                && Math.abs(p.w - battlefieldIslandW) < 1.0;
        g.setFill(Color.web(mainDeck ? "#253944" : "#2D424D"));
        g.fillRoundRect(p.x, p.y, p.w, p.h, mainDeck ? 18.0 : 13.0, mainDeck ? 18.0 : 13.0);
        g.setFill(Color.web(mainDeck ? "#5B7480" : "#526A75", 0.78));
        g.fillRoundRect(p.x + 10.0, p.y + 8.0, Math.max(18.0, p.w - 20.0),
                Math.max(8.0, p.h * 0.27), 11.0, 11.0);
        g.setStroke(Color.web(mainDeck ? "#D9A735" : "#92A9B1", mainDeck ? 0.88 : 0.74));
        g.setLineWidth(mainDeck ? 7.0 : 5.0);
        g.strokeRoundRect(p.x, p.y, p.w, p.h, mainDeck ? 18.0 : 13.0, mainDeck ? 18.0 : 13.0);
        g.setStroke(Color.web("#14232C", 0.76));
        g.setLineWidth(4.0);
        for (double seamX = p.x + 120.0; seamX < p.x + p.w; seamX += 150.0) {
            g.strokeLine(seamX, p.y + 8.0, seamX - 10.0, p.y + p.h - 7.0);
        }
    }

    private void drawTitanDockCannon(GraphicsContext g, double pulse) {
        double muzzleX = dockShipCannonMuzzleX();
        double muzzleY = dockShipCannonMuzzleY();
        g.setFill(Color.web("#15242D"));
        g.fillOval(muzzleX - 95.0, muzzleY - 78.0, 190.0, 150.0);
        g.setStroke(Color.web("#536B77"));
        g.setLineWidth(34.0);
        g.strokeLine(muzzleX + 28.0, muzzleY - 12.0, muzzleX - 145.0, muzzleY - 42.0);
        g.setStroke(Color.web("#91A8B1"));
        g.setLineWidth(10.0);
        g.strokeLine(muzzleX + 18.0, muzzleY - 18.0, muzzleX - 144.0, muzzleY - 46.0);
        if (dockShipBomb != null && !dockShipBomb.exploded) {
            g.setFill(Color.web("#FFCA4A", 0.20 + pulse * 0.32));
            g.fillOval(muzzleX - 194.0, muzzleY - 82.0, 105.0, 74.0);
        }
    }

    private void drawTitanDockLever(GraphicsContext g) {
        boolean ready = dockLeverCooldown <= 0;
        double baseY = dockLeverY + 26.0;
        g.setFill(ready ? Color.web("#DCA72E") : Color.web("#526773"));
        g.fillRoundRect(dockLeverX - 38.0, baseY - 12.0, 76.0, 24.0, 11.0, 11.0);
        g.setStroke(Color.web("#101922"));
        g.setLineWidth(5.0);
        double tipX = dockLeverX + (ready ? 20.0 : -20.0);
        double tipY = dockLeverY - (ready ? 24.0 : 38.0);
        g.strokeLine(dockLeverX, baseY - 3.0, tipX, tipY);
        g.setFill(ready ? Color.web("#FFE082") : Color.web("#B0BEC5"));
        g.fillOval(tipX - 9.0, tipY - 9.0, 18.0, 18.0);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 20.0));
        g.setFill(Color.web("#FFF8E1", ready ? 0.86 : 0.52));
        g.fillText(ready ? "TITAN CANNON" : "CANNON RELOADING", dockLeverX - 94.0, dockLeverY - 28.0);
    }

    private void drawTitanDockWarningLamps(GraphicsContext g, double pulse) {
        g.setFill(Color.web("#FFCA4A", pulse));
        for (double x : new double[]{650.0, 1_650.0, 2_520.0, 3_480.0, 4_350.0, 5_350.0}) {
            g.fillOval(x - 12.0, battlefieldIslandY + 28.0, 24.0, 24.0);
            g.setFill(Color.web("#FFCA4A", pulse * 0.20));
            g.fillOval(x - 42.0, battlefieldIslandY - 2.0, 84.0, 84.0);
            g.setFill(Color.web("#FFCA4A", pulse));
        }
    }

    @SuppressWarnings("unused")
    private void drawLegacyTitanDockArena(GraphicsContext g, boolean ambientFx) {
        for (int i = 0; i < 620; i++) {
            double ratio = i / 620.0;
            Color c = Color.web("#050A12").interpolate(Color.web("#263C4B"), ratio);
            g.setFill(c);
            g.fillRect(0, i * (WORLD_HEIGHT / 620.0), WORLD_WIDTH, WORLD_HEIGHT / 620.0 + 3);
        }

        double time = System.currentTimeMillis() / 1000.0;
        double waterline = dockWaterSurfaceY();
        double pulse = ambientFx ? 0.5 + 0.5 * Math.sin(time * 1.8) : 0.45;

        g.setFill(Color.web("#9ECAE1", 0.12));
        for (int i = 0; i < 7; i++) {
            double cloudX = -420 + i * 1040 + (ambientFx ? Math.sin(time * 0.18 + i) * 90 : 0);
            g.fillOval(cloudX, 180 + (i % 3) * 130, 1180, 240);
        }

        // Two colossal drydock cranes frame the dreadnought without creating
        // false collision surfaces.
        g.setFill(Color.web("#101820", 0.92));
        g.fillRect(300, 560, 150, waterline - 560);
        g.fillRect(WORLD_WIDTH - 450, 520, 150, waterline - 520);
        g.setStroke(Color.web("#546E7A", 0.72));
        g.setLineWidth(34);
        g.strokeLine(375, 650, 1510, 650);
        g.strokeLine(WORLD_WIDTH - 375, 610, WORLD_WIDTH - 1510, 610);
        g.setStroke(Color.web("#FFB300", 0.38));
        g.setLineWidth(8);
        g.strokeLine(330, 780, 1420, 780);
        g.strokeLine(WORLD_WIDTH - 330, 740, WORLD_WIDTH - 1420, 740);
        g.setStroke(Color.web("#263238", 0.84));
        g.setLineWidth(10);
        g.strokeLine(1330, 650, 1330, GROUND_Y - 390);
        g.strokeLine(WORLD_WIDTH - 1330, 610, WORLD_WIDTH - 1330, GROUND_Y - 390);

        g.setFill(Color.web("#061722", 0.96));
        g.fillRect(0, waterline, WORLD_WIDTH, WORLD_HEIGHT - waterline + 200);
        g.setFill(Color.web("#164052", 0.52));
        g.fillRect(0, waterline + 16, WORLD_WIDTH, 42);
        g.setStroke(Color.web("#80DEEA", 0.28 + pulse * 0.12));
        g.setLineWidth(3.2);
        for (int i = 0; i < 14; i++) {
            double waveY = waterline + 18 + i * 30;
            double shift = ambientFx ? Math.sin(time * 1.25 + i * 0.73) * 18 : 0;
            g.strokeLine(0, waveY + shift, WORLD_WIDTH, waveY - shift * 0.35);
        }

        // The armored hull hangs beneath the main collision deck.
        double hullLeft = battlefieldIslandX - 140;
        double hullRight = battlefieldIslandX + battlefieldIslandW + 140;
        g.setFill(Color.web("#111A21"));
        g.fillPolygon(
                new double[]{hullLeft, hullRight, hullRight - 380, WORLD_WIDTH / 2.0 + 520,
                        WORLD_WIDTH / 2.0, WORLD_WIDTH / 2.0 - 520, hullLeft + 380},
                new double[]{battlefieldIslandY + 30, battlefieldIslandY + 30, battlefieldIslandY + 260,
                        battlefieldIslandY + 420, battlefieldIslandY + 540,
                        battlefieldIslandY + 420, battlefieldIslandY + 260},
                7
        );
        g.setFill(Color.web("#26343D", 0.84));
        g.fillPolygon(
                new double[]{hullLeft + 110, hullRight - 110, hullRight - 430, hullLeft + 430},
                new double[]{battlefieldIslandY + 70, battlefieldIslandY + 70,
                        battlefieldIslandY + 250, battlefieldIslandY + 250},
                4
        );
        g.setStroke(Color.web("#FFB300", 0.34));
        g.setLineWidth(5);
        g.strokeLine(hullLeft + 220, battlefieldIslandY + 130, hullRight - 220, battlefieldIslandY + 130);

        // The bombardment cannon sits below the deck at the actual projectile
        // muzzle so its shots never appear from empty space.
        double muzzleX = dockShipCannonMuzzleX();
        double muzzleY = dockShipCannonMuzzleY();
        g.setFill(Color.web("#18242C"));
        g.fillOval(muzzleX - 100, muzzleY - 70, 170, 120);
        g.setStroke(Color.web("#37474F"));
        g.setLineWidth(28);
        g.strokeLine(muzzleX + 20, muzzleY - 10, muzzleX - 115, muzzleY - 30);
        if (dockShipBomb != null && !dockShipBomb.exploded) {
            g.setFill(Color.web("#FFCA28", 0.20 + pulse * 0.24));
            g.fillOval(muzzleX - 145, muzzleY - 58, 86, 58);
        }

        for (Platform p : platforms) {
            boolean mainDeck = Math.abs(p.x - battlefieldIslandX) < 1.0
                    && Math.abs(p.w - battlefieldIslandW) < 1.0;
            g.setFill(mainDeck ? Color.web("#202D34") : Color.web("#2B3940"));
            g.fillRoundRect(p.x, p.y, p.w, p.h, mainDeck ? 18 : 12, mainDeck ? 18 : 12);
            g.setFill(Color.web(mainDeck ? "#52666E" : "#455A64", 0.78));
            g.fillRoundRect(p.x + 8, p.y + 6, Math.max(18, p.w - 16), Math.max(10, p.h * 0.32), 12, 12);
            g.setStroke(Color.web(mainDeck ? "#FFB300" : "#90A4AE", mainDeck ? 0.72 : 0.58));
            g.setLineWidth(mainDeck ? 4.2 : 3.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, mainDeck ? 18 : 12, mainDeck ? 18 : 12);
            g.setStroke(Color.web("#10181D", 0.64));
            g.setLineWidth(2);
            for (double seamX = p.x + 100; seamX < p.x + p.w; seamX += 130) {
                g.strokeLine(seamX, p.y + 8, seamX - 8, p.y + p.h - 6);
            }
        }

        double leverBaseY = dockLeverY + 26;
        boolean leverReady = dockLeverCooldown <= 0;
        g.setFill(leverReady ? Color.web("#FFB300") : Color.web("#546E7A"));
        g.fillRoundRect(dockLeverX - 34, leverBaseY - 10, 68, 18, 10, 10);
        g.setStroke(Color.web("#111820"));
        g.setLineWidth(4);
        g.strokeLine(dockLeverX, leverBaseY - 4,
                dockLeverX + (leverReady ? 18 : -18), dockLeverY - (leverReady ? 20 : 34));
        g.setFill(Color.web("#FFF8E1", leverReady ? 0.82 : 0.48));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 20));
        g.fillText(leverReady ? "TITAN CANNON" : "CANNON RELOADING", dockLeverX - 94, dockLeverY - 24);

        for (WindVent v : windVents) {
            g.setFill(Color.web("#80DEEA", 0.12 + pulse * 0.10));
            g.fillOval(v.x + v.w / 2.0 - v.w * 0.45, v.y - 220, v.w * 0.9, 360);
            g.setStroke(Color.web("#E1F5FE", 0.20 + pulse * 0.10));
            g.setLineWidth(2.4);
            g.strokeOval(v.x + v.w * 0.18, v.y - 145, v.w * 0.64, 230);
        }
    }

    private void drawPrisonArena(GraphicsContext g, boolean ambientFx) {
        double presentationSeconds = ambientFx ? System.nanoTime() / 1_000_000_000.0 : 0.0;
        long presentationMillis = (long) (presentationSeconds * 1000.0);

        // The shattered roof opens Crownlock directly to the city night. The outside
        // is deliberately brighter than the cell hall so the upper blast exit reads
        // as open sky rather than an invisible ceiling.
        LinearGradient sky = new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#020710")),
                new Stop(0.58, Color.web("#0A2540")),
                new Stop(1.0, Color.web("#31506A")));
        g.setFill(sky);
        g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);
        g.setFill(Color.web("#D8F2FF", 0.68));
        for (int star = 0; star < 38; star++) {
            double sx = 90 + Math.floorMod(star * 947, (int) WORLD_WIDTH - 180);
            double sy = 38 + Math.floorMod(star * 313, 500);
            double sr = star % 7 == 0 ? 8.0 : 4.0;
            g.fillOval(sx, sy, sr, sr);
        }
        g.setFill(Color.web("#D8ECF7", 0.22));
        g.fillOval(4870, 90, 330, 330);
        g.setFill(Color.web("#08131F", 0.94));
        for (int building = 0; building < 18; building++) {
            double bx = building * 350.0 - 80.0;
            double bh = 150.0 + Math.floorMod(building * 137, 330);
            g.fillRect(bx, 650 - bh, 280, bh);
            g.setFill(Color.web("#FFD54F", 0.28));
            for (int window = 0; window < 3; window++) {
                g.fillRect(bx + 38 + window * 78, 610 - bh, 26, 16);
            }
            g.setFill(Color.web("#08131F", 0.94));
        }

        // Lower detention wall and large, readable blockwork.
        LinearGradient wall = new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#17252F")),
                new Stop(0.56, Color.web("#202F39")),
                new Stop(1.0, Color.web("#111A20")));
        g.setFill(wall);
        g.fillRect(0, 510, WORLD_WIDTH, PRISON_MAIN_Y - 510);
        g.setStroke(Color.web("#41535F", 0.6));
        g.setLineWidth(5);
        for (double y = 560; y < PRISON_MAIN_Y; y += 190) {
            g.strokeLine(0, y, WORLD_WIDTH, y);
            double offset = ((int) (y / 190) & 1) == 0 ? 0 : 150;
            for (double x = offset; x < WORLD_WIDTH; x += 300) {
                g.strokeLine(x, y, x, Math.min(PRISON_MAIN_Y, y + 190));
            }
        }

        drawPrisonStructuralFrame(g);
        drawPrisonBrokenRoof(g);
        drawPrisonCellBank(g, 180, 700, false);
        drawPrisonCellBank(g, WORLD_WIDTH - 180, 700, true);
        drawPrisonControlGate(g);

        // Three independent searchlights sweep at different rates. They are purely
        // presentational and never consume SimRng or alter the simulation.
        double leftTarget = 520 + (0.5 + 0.5 * Math.sin(presentationSeconds * 0.48)) * 2100;
        double centerTarget = 1300 + (0.5 + 0.5 * Math.sin(presentationSeconds * 0.36 + 2.1)) * 3400;
        double rightTarget = 3380 + (0.5 + 0.5 * Math.sin(presentationSeconds * 0.53 + 4.2)) * 2100;
        drawPrisonSearchlight(g, 840, 285, leftTarget, Color.web("#B3E5FC"));
        drawPrisonSearchlight(g, 3000, 170, centerTarget, Color.web("#E1F5FE"));
        drawPrisonSearchlight(g, 5160, 285, rightTarget, Color.web("#B3E5FC"));

        // Emergency lamps and conduit give the wall depth behind the catwalks.
        g.setStroke(Color.web("#0B1115"));
        g.setLineWidth(18);
        g.strokeLine(0, 650, WORLD_WIDTH, 650);
        g.setLineWidth(10);
        g.strokeLine(0, 1960, 2160, 1960);
        g.strokeLine(3840, 1960, WORLD_WIDTH, 1960);
        for (int lamp = 0; lamp < 7; lamp++) {
            double lx = 420 + lamp * 860.0;
            boolean flashOn = !ambientFx || ((presentationMillis / 420 + lamp) & 1L) == 0L;
            g.setFill(Color.web("#3A1014"));
            g.fillRoundRect(lx - 40, 590, 80, 42, 12, 12);
            g.setFill(Color.web("#FF1744", flashOn ? 0.9 : 0.24));
            g.fillOval(lx - 22, 594, 44, 32);
        }

        drawPrisonPlatforms(g);
        drawPrisonFloor(g);
        for (int lever = 0; lever < PRISON_LEVER_X.length; lever++) {
            drawPrisonLever(g, lever);
        }

        if (ambientFx && !prisonerRushes.isEmpty()) {
            double alarm = 0.045 + 0.025 * (0.5 + 0.5 * Math.sin(presentationSeconds * 7.0));
            g.setFill(Color.web("#FF1744", alarm));
            g.fillRect(0, 0, WORLD_WIDTH, PRISON_MAIN_Y + PRISON_MAIN_H);
        }
    }

    private void drawPrisonStructuralFrame(GraphicsContext g) {
        double[] columns = {760.0, 1920.0, 4080.0, 5240.0};
        g.setStroke(Color.web("#0A1116", 0.98));
        g.setLineWidth(78.0);
        for (double x : columns) g.strokeLine(x, 500, x, PRISON_MAIN_Y + 12);
        g.setStroke(Color.web("#526774", 0.55));
        g.setLineWidth(8.0);
        for (double x : columns) {
            g.strokeLine(x - 25, 510, x - 25, PRISON_MAIN_Y);
            g.strokeLine(x + 25, 510, x + 25, PRISON_MAIN_Y);
        }

        g.setStroke(Color.web("#0C151B"));
        g.setLineWidth(48.0);
        g.strokeLine(0, 1110, 2110, 1110);
        g.strokeLine(3890, 1110, WORLD_WIDTH, 1110);
        g.strokeLine(0, 1710, 2110, 1710);
        g.strokeLine(3890, 1710, WORLD_WIDTH, 1710);
        g.setStroke(Color.web("#465B67", 0.50));
        g.setLineWidth(6.0);
        g.strokeLine(0, 1092, 2110, 1092);
        g.strokeLine(3890, 1092, WORLD_WIDTH, 1092);
        g.strokeLine(0, 1692, 2110, 1692);
        g.strokeLine(3890, 1692, WORLD_WIDTH, 1692);

        drawPrisonRearBrace(g, 760, 1110, 1920, 1710);
        drawPrisonRearBrace(g, 1920, 1110, 760, 1710);
        drawPrisonRearBrace(g, 4080, 1110, 5240, 1710);
        drawPrisonRearBrace(g, 5240, 1110, 4080, 1710);
    }

    private void drawPrisonRearBrace(GraphicsContext g, double x1, double y1, double x2, double y2) {
        g.setStroke(Color.web("#263943", 0.58));
        g.setLineWidth(22.0);
        g.strokeLine(x1, y1, x2, y2);
        g.setStroke(Color.web("#607D8B", 0.24));
        g.setLineWidth(5.0);
        g.strokeLine(x1, y1, x2, y2);
    }

    private void drawPrisonBrokenRoof(GraphicsContext g) {
        g.setFill(Color.web("#070C10"));
        g.fillPolygon(
                new double[]{0, 0, 2080, 2080, 1940, 1860, 1720, 1590, 1430, 1290, 0},
                new double[]{0, 390, 390, 160, 255, 180, 335, 230, 410, 315, 510}, 11);
        g.fillPolygon(
                new double[]{WORLD_WIDTH, WORLD_WIDTH, 3920, 3920, 4060, 4140, 4280, 4410, 4570, 4710, WORLD_WIDTH},
                new double[]{0, 390, 390, 160, 255, 180, 335, 230, 410, 315, 510}, 11);

        g.setStroke(Color.web("#546E7A"));
        g.setLineWidth(22);
        g.strokeLine(0, 430, 1310, 430);
        g.strokeLine(4690, 430, WORLD_WIDTH, 430);
        g.strokeLine(1550, 255, 2160, 610);
        g.strokeLine(4450, 255, 3840, 610);
        g.setStroke(Color.web("#90A4AE", 0.72));
        g.setLineWidth(8);
        double[] rebarX = {1420, 1690, 1960, 4040, 4310, 4580};
        for (int i = 0; i < rebarX.length; i++) {
            double x = rebarX[i];
            double direction = x < WORLD_WIDTH / 2.0 ? 1.0 : -1.0;
            g.strokeLine(x, 300 + (i % 3) * 45, x + direction * 70, 540 + (i % 2) * 80);
        }

        g.setFill(Color.web("#111B21"));
        g.fillPolygon(new double[]{2140, 2360, 2500, 2250}, new double[]{390, 390, 560, 520}, 4);
        g.fillPolygon(new double[]{3860, 3640, 3500, 3750}, new double[]{390, 390, 560, 520}, 4);
        g.setStroke(Color.web("#607D8B", 0.72));
        g.setLineWidth(12.0);
        g.strokeLine(2080, 390, 2520, 590);
        g.strokeLine(3920, 390, 3480, 590);

        // Suspended fragments frame the launch route without acting as platforms.
        g.setFill(Color.web("#101920"));
        g.fillPolygon(new double[]{2360, 2510, 2460, 2300}, new double[]{90, 165, 310, 220}, 4);
        g.fillPolygon(new double[]{3540, 3690, 3700, 3500}, new double[]{120, 70, 245, 315}, 4);
        g.setStroke(Color.web("#78909C", 0.58));
        g.setLineWidth(6);
        g.strokeLine(2430, 0, 2405, 135);
        g.strokeLine(3605, 0, 3620, 118);
    }

    private void drawPrisonControlGate(GraphicsContext g) {
        double gateX = 2260;
        double gateY = 800;
        double gateW = 1480;
        double gateH = PRISON_MAIN_Y - gateY;
        g.setFill(Color.web("#0A1116"));
        g.fillPolygon(new double[]{gateX - 150, gateX + 100, gateX + 100, gateX - 55},
                new double[]{gateY + 170, gateY, PRISON_MAIN_Y, PRISON_MAIN_Y}, 4);
        g.fillPolygon(new double[]{gateX + gateW + 150, gateX + gateW - 100,
                        gateX + gateW - 100, gateX + gateW + 55},
                new double[]{gateY + 170, gateY, PRISON_MAIN_Y, PRISON_MAIN_Y}, 4);
        g.setStroke(Color.web("#607D8B", 0.62));
        g.setLineWidth(10.0);
        g.strokeLine(gateX - 110, gateY + 190, gateX + 45, PRISON_MAIN_Y);
        g.strokeLine(gateX + gateW + 110, gateY + 190, gateX + gateW - 45, PRISON_MAIN_Y);

        g.setFill(Color.web("#0B141A"));
        g.fillRoundRect(gateX, gateY, gateW, gateH, 34, 34);
        g.setStroke(Color.web("#50636F"));
        g.setLineWidth(12);
        g.strokeRoundRect(gateX, gateY, gateW, gateH, 34, 34);

        g.setFill(Color.web("#05090C"));
        g.fillRoundRect(gateX + 190, gateY + 330, gateW - 380, gateH - 360, 24, 24);
        g.setStroke(Color.web("#263A45"));
        g.setLineWidth(8);
        for (int seam = 1; seam < 4; seam++) {
            double sx = gateX + 190 + seam * (gateW - 380) / 4.0;
            g.strokeLine(sx, gateY + 340, sx, gateY + gateH - 40);
        }
        g.setStroke(Color.web("#3B4E58", 0.70));
        g.setLineWidth(5.0);
        for (int row = 0; row < 5; row++) {
            double sy = gateY + 410 + row * 220.0;
            g.strokeLine(gateX + 205, sy, gateX + gateW - 205, sy);
        }
        g.setFill(Color.web("#101E25"));
        for (int side = 0; side < 2; side++) {
            double panelX = side == 0 ? gateX + 38 : gateX + gateW - 158;
            for (int row = 0; row < 4; row++) {
                double panelY = gateY + 330 + row * 260.0;
                g.fillRoundRect(panelX, panelY, 120, 180, 12, 12);
                g.setStroke(Color.web("#455A64", 0.64));
                g.setLineWidth(5.0);
                g.strokeRoundRect(panelX, panelY, 120, 180, 12, 12);
            }
        }
        g.setFill(Color.web("#081018"));
        g.fillRoundRect(gateX + 350, gateY + 80, gateW - 700, 190, 22, 22);
        g.setStroke(Color.web("#00BCD4", 0.75));
        g.setLineWidth(5);
        g.strokeRoundRect(gateX + 350, gateY + 80, gateW - 700, 190, 22, 22);
        g.setFill(Color.web("#00BCD4", 0.72));
        g.fillOval(WORLD_WIDTH / 2.0 - 68, gateY + 108, 136, 136);
        g.setFill(Color.web("#041016"));
        g.fillOval(WORLD_WIDTH / 2.0 - 34, gateY + 142, 68, 68);
        g.setStroke(Color.web("#8FE6F0", 0.82));
        g.setLineWidth(7.0);
        g.strokeArc(WORLD_WIDTH / 2.0 - 31, gateY + 147, 62, 56, 22, 136, ArcType.OPEN);
        g.strokeLine(WORLD_WIDTH / 2.0 - 20, gateY + 175,
                WORLD_WIDTH / 2.0 - 20, gateY + 208);
        g.strokeLine(WORLD_WIDTH / 2.0 + 20, gateY + 175,
                WORLD_WIDTH / 2.0 + 20, gateY + 208);
        g.setFont(Font.font("Arial Black", FontWeight.BOLD, 38));
        g.setFill(Color.web("#CFD8DC", 0.82));
        g.setTextAlign(TextAlignment.CENTER);
        g.fillText("CROWNLOCK // TRANSFER", WORLD_WIDTH / 2.0, gateY + 335);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 23));
        g.setFill(Color.web("#FF5252", 0.78));
        g.fillText("LOCKDOWN FAILED  •  SURFACE BREACH", WORLD_WIDTH / 2.0, gateY + 380);
        g.setTextAlign(TextAlignment.LEFT);
    }

    private void drawPrisonSearchlight(GraphicsContext g, double originX, double originY,
                                       double targetX, Color beamColor) {
        double targetHalfWidth = 280.0;
        g.setFill(beamColor.deriveColor(0, 1, 1, 0.075));
        g.fillPolygon(
                new double[]{originX - 18, originX + 18, targetX + targetHalfWidth, targetX - targetHalfWidth},
                new double[]{originY, originY, PRISON_MAIN_Y, PRISON_MAIN_Y}, 4);
        g.setFill(beamColor.deriveColor(0, 1, 1, 0.055));
        g.fillPolygon(
                new double[]{originX - 7, originX + 7, targetX + 125, targetX - 125},
                new double[]{originY, originY, PRISON_MAIN_Y, PRISON_MAIN_Y}, 4);
        g.setStroke(beamColor.deriveColor(0, 1, 1, 0.2));
        g.setLineWidth(4);
        g.strokeLine(originX, originY, targetX, PRISON_MAIN_Y);
        g.setFill(beamColor.deriveColor(0, 1, 1, 0.13));
        g.fillOval(targetX - 250, PRISON_MAIN_Y - 38, 500, 76);

        g.setFill(Color.web("#101A21"));
        g.fillRoundRect(originX - 62, originY - 34, 124, 68, 30, 30);
        g.setStroke(Color.web("#90A4AE"));
        g.setLineWidth(7);
        g.strokeRoundRect(originX - 62, originY - 34, 124, 68, 30, 30);
        g.setFill(beamColor.deriveColor(0, 1, 1, 0.88));
        g.fillOval(originX - 22, originY - 13, 44, 26);
        g.setFill(Color.web("#263943"));
        g.fillRect(originX - 18, originY - 58, 36, 26);
    }

    private void drawPrisonFloor(GraphicsContext g) {
        LinearGradient foundation = new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                new Stop(0.0, Color.web("#263842")),
                new Stop(0.42, Color.web("#121D23")),
                new Stop(1.0, Color.web("#05090C")));
        g.setFill(foundation);
        g.fillRect(0, PRISON_MAIN_Y, WORLD_WIDTH, WORLD_HEIGHT - PRISON_MAIN_Y);
        g.setFill(Color.web("#334953"));
        g.fillRect(0, PRISON_MAIN_Y, WORLD_WIDTH, PRISON_MAIN_H);
        g.setFill(Color.web("#10191E"));
        g.fillRect(0, PRISON_MAIN_Y + 30, WORLD_WIDTH, 16);
        g.setStroke(Color.web("#90A4AE"));
        g.setLineWidth(7);
        g.strokeLine(0, PRISON_MAIN_Y, WORLD_WIDTH, PRISON_MAIN_Y);
        g.setStroke(Color.web("#FFB300", 0.82));
        g.setLineWidth(12);
        for (double x = -40; x < WORLD_WIDTH; x += 240) {
            g.strokeLine(x, PRISON_MAIN_Y + 68, x + 86, PRISON_MAIN_Y + 68);
        }
        g.setFill(Color.web("#05090C"));
        for (double grateX = 500; grateX < WORLD_WIDTH - 400; grateX += 1000) {
            g.fillRoundRect(grateX, PRISON_MAIN_Y + 108, 500, 90, 12, 12);
            g.setStroke(Color.web("#455A64"));
            g.setLineWidth(5);
            for (int bar = 0; bar < 8; bar++) {
                double gx = grateX + 32 + bar * 60;
                g.strokeLine(gx, PRISON_MAIN_Y + 120, gx, PRISON_MAIN_Y + 184);
            }
        }
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 27));
        g.setFill(Color.web("#78909C", 0.72));
        g.fillText("CELL BLOCK A", 170, PRISON_MAIN_Y + 245);
        g.setTextAlign(TextAlignment.CENTER);
        g.fillText("TRANSFER FLOOR 07", WORLD_WIDTH / 2.0, PRISON_MAIN_Y + 245);
        g.setTextAlign(TextAlignment.RIGHT);
        g.fillText("CELL BLOCK B", WORLD_WIDTH - 170, PRISON_MAIN_Y + 245);
        g.setTextAlign(TextAlignment.LEFT);
    }

    private void drawPrisonPlatforms(GraphicsContext g) {
        for (Platform platform : platforms) {
            if (platform.y >= PRISON_MAIN_Y - 5.0) {
                continue;
            }

            drawPrisonCatwalkSupports(g, platform);

            LinearGradient steel = new LinearGradient(0, 0, 0, 1, true, CycleMethod.NO_CYCLE,
                    new Stop(0.0, Color.web("#6F8791")),
                    new Stop(0.20, Color.web("#344A55")),
                    new Stop(1.0, Color.web("#0B151B")));
            g.setFill(steel);
            g.fillRect(platform.x, platform.y, platform.w, platform.h);
            g.setStroke(Color.web("#90A4AE"));
            g.setLineWidth(7);
            g.strokeLine(platform.x, platform.y, platform.x + platform.w, platform.y);
            g.strokeLine(platform.x, platform.y + platform.h,
                    platform.x + platform.w, platform.y + platform.h);
            g.setStroke(Color.web("#C5D5DC", 0.52));
            g.setLineWidth(4);
            g.strokeLine(platform.x + 20, platform.y + 12,
                    platform.x + platform.w - 20, platform.y + 12);

            g.setFill(Color.web("#AFC0C8", 0.72));
            int rivets = Math.max(2, (int) (platform.w / 170.0));
            for (int rivet = 1; rivet <= rivets; rivet++) {
                double rx = platform.x + rivet * platform.w / (rivets + 1.0);
                g.fillOval(rx - 5, platform.y + platform.h / 2.0 - 5, 10, 10);
            }

            g.setStroke(Color.web("#526A76", 0.70));
            g.setLineWidth(5.0);
            int trussBays = Math.max(2, (int) Math.round(platform.w / 240.0));
            double bayWidth = platform.w / trussBays;
            for (int bay = 0; bay < trussBays; bay++) {
                double x = platform.x + bay * bayWidth;
                if ((bay & 1) == 0) {
                    g.strokeLine(x, platform.y + platform.h, x + bayWidth, platform.y);
                } else {
                    g.strokeLine(x, platform.y, x + bayWidth, platform.y + platform.h);
                }
            }
        }
    }

    private void drawPrisonCatwalkSupports(GraphicsContext g, Platform platform) {
        double centerX = platform.x + platform.w * 0.5;
        double relativeY = platform.y - PRISON_MAIN_Y;
        g.setStroke(Color.web("#17262E", 0.96));

        if (relativeY > -430.0) {
            double left = platform.x + Math.min(140.0, platform.w * 0.20);
            double right = platform.x + platform.w - Math.min(140.0, platform.w * 0.20);
            g.setLineWidth(34.0);
            g.strokeLine(left, platform.y + platform.h, left + 18.0, PRISON_MAIN_Y);
            g.strokeLine(right, platform.y + platform.h, right - 18.0, PRISON_MAIN_Y);
            g.setStroke(Color.web("#708793", 0.52));
            g.setLineWidth(7.0);
            g.strokeLine(left, platform.y + platform.h, left + 18.0, PRISON_MAIN_Y);
            g.strokeLine(right, platform.y + platform.h, right - 18.0, PRISON_MAIN_Y);
            g.strokeLine(left, platform.y + platform.h, right - 18.0, PRISON_MAIN_Y);
            g.strokeLine(right, platform.y + platform.h, left + 18.0, PRISON_MAIN_Y);
        } else if (platform.w > 1000.0) {
            g.setLineWidth(42.0);
            g.strokeLine(platform.x + 120, platform.y + platform.h, 2310, PRISON_MAIN_Y - 55.0);
            g.strokeLine(platform.x + platform.w - 120, platform.y + platform.h,
                    3690, PRISON_MAIN_Y - 55.0);
            g.setStroke(Color.web("#718996", 0.54));
            g.setLineWidth(8.0);
            g.strokeLine(platform.x + 120, platform.y + platform.h, 2310, PRISON_MAIN_Y - 55.0);
            g.strokeLine(platform.x + platform.w - 120, platform.y + platform.h,
                    3690, PRISON_MAIN_Y - 55.0);
        } else if (Math.abs(centerX - WORLD_WIDTH * 0.5) < 420.0) {
            g.setLineWidth(24.0);
            g.strokeLine(platform.x + 95, platform.y, platform.x + 95, 780.0);
            g.strokeLine(platform.x + platform.w - 95, platform.y,
                    platform.x + platform.w - 95, 780.0);
            g.setStroke(Color.web("#78909C", 0.60));
            g.setLineWidth(6.0);
            g.strokeLine(platform.x + 95, platform.y, platform.x + 95, 780.0);
            g.strokeLine(platform.x + platform.w - 95, platform.y,
                    platform.x + platform.w - 95, 780.0);
        } else {
            boolean leftWing = centerX < WORLD_WIDTH * 0.5;
            double wallX = leftWing ? 1930.0 : 4070.0;
            double nearX = leftWing ? platform.x + platform.w - 36.0 : platform.x + 36.0;
            g.setLineWidth(40.0);
            g.strokeLine(nearX, platform.y + platform.h, wallX, platform.y + 360.0);
            g.setStroke(Color.web("#78909C", 0.54));
            g.setLineWidth(8.0);
            g.strokeLine(nearX, platform.y + platform.h, wallX, platform.y + 360.0);
        }
    }

    private void drawPrisonCellBank(GraphicsContext g, double edgeX, double topY, boolean faceLeft) {
        double direction = faceLeft ? -1.0 : 1.0;
        double backingX = faceLeft ? edgeX - 1380.0 : edgeX;
        g.setFill(Color.web("#0B141A", 0.92));
        g.fillRect(backingX - 28, topY - 48, 1436, 1368);
        g.setStroke(Color.web("#3C505B", 0.72));
        g.setLineWidth(13.0);
        g.strokeRect(backingX - 28, topY - 48, 1436, 1368);
        for (int tier = 0; tier < 2; tier++) {
            double y = topY + tier * 520.0;
            for (int cell = 0; cell < 4; cell++) {
                double x = edgeX + direction * cell * 360.0;
                if (faceLeft) x -= 300.0;
                g.setFill(Color.web("#050A0D"));
                g.fillRoundRect(x, y, 300, 310, 16, 16);
                g.setStroke(Color.web("#607D8B"));
                g.setLineWidth(10);
                for (int bar = 0; bar < 6; bar++) {
                    double bx = x + 22 + bar * 51;
                    g.strokeLine(bx, y + 8, bx, y + 302);
                }
                g.setStroke(Color.web("#37474F"));
                g.setLineWidth(8);
                g.strokeRoundRect(x, y, 300, 310, 16, 16);
                g.setFill(Color.web("#FFB300", 0.48));
                g.fillRect(x + 30, y + 260, 62, 12);
            }
        }
        g.setFill(Color.web("#263943"));
        g.fillRect(backingX - 20, topY + 360, 1420, 58);
        g.fillRect(backingX - 20, topY + 880, 1420, 58);
        g.setStroke(Color.web("#90A4AE", 0.58));
        g.setLineWidth(7.0);
        g.strokeLine(backingX - 20, topY + 360, backingX + 1400, topY + 360);
        g.strokeLine(backingX - 20, topY + 880, backingX + 1400, topY + 880);
        for (int post = 0; post <= 7; post++) {
            double x = backingX + post * 200.0;
            g.strokeLine(x, topY + 360, x, topY + 418);
            g.strokeLine(x, topY + 880, x, topY + 938);
        }
    }

    private void drawPrisonLever(GraphicsContext g, int lever) {
        double x = PRISON_LEVER_X[lever];
        double y = PRISON_LEVER_Y;
        boolean ready = prisonLeverCooldowns[lever] <= 0;
        g.setFill(Color.web("#111A20"));
        g.fillRoundRect(x - 58, y - 7, 116, 72, 14, 14);
        g.setStroke(ready ? Color.web("#FFD54F") : Color.web("#546E7A"));
        g.setLineWidth(7);
        g.strokeRoundRect(x - 58, y - 7, 116, 72, 14, 14);
        double handleX = x + (ready ? (lever == 0 ? 23 : -23) : 0);
        double handleY = y - (ready ? 45 : 22);
        g.strokeLine(x, y + 14, handleX, handleY);
        g.setFill(ready ? Color.web("#FFCA28") : Color.web("#78909C"));
        g.fillOval(handleX - 15, handleY - 15, 30, 30);
        g.setTextAlign(TextAlignment.CENTER);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 19));
        g.setFill(ready ? Color.web("#FFF8E1") : Color.web("#90A4AE"));
        String label = ready ? "RELEASE" : "LOCKED " + (int) Math.ceil(prisonLeverCooldowns[lever] / 60.0) + "s";
        g.fillText(label, x, y - 70);
        g.setTextAlign(TextAlignment.LEFT);

        double gateX = PRISON_CELL_X[lever];
        double openProgress = prisonLeverCooldowns[lever] > PRISON_LEVER_COOLDOWN_FRAMES - 96
                ? (PRISON_LEVER_COOLDOWN_FRAMES - prisonLeverCooldowns[lever]) / 96.0
                : 1.0;
        double visibleGateH = 190.0 * Math.clamp(openProgress, 0.0, 1.0);
        g.setFill(Color.web("#050A0D"));
        g.fillRoundRect(gateX - 88, PRISON_MAIN_Y - 230, 176, 230, 14, 14);
        g.setStroke(Color.web("#90A4AE"));
        g.setLineWidth(8);
        for (int bar = 0; bar < 5; bar++) {
            double bx = gateX - 72 + bar * 36;
            g.strokeLine(bx, PRISON_MAIN_Y - 230, bx, PRISON_MAIN_Y - 230 + visibleGateH);
        }
    }

    private void drawPrisonerRush(GraphicsContext g, PrisonerRush rush) {
        Color[] feathers = {
                Color.web("#795548"), Color.web("#607D8B"),
                Color.web("#455A64"), Color.web("#8D6E63")
        };
        Color feather = feathers[Math.floorMod(rush.variant, feathers.length)];
        double stride = Math.sin((PRISON_RUSH_LIFETIME_FRAMES - rush.lifeFrames) * 0.72);
        g.save();
        g.translate(rush.x, rush.y + Math.abs(stride) * 3.0);
        g.scale(rush.direction, 1.0);

        g.setFill(Color.web("#000000", 0.28));
        g.fillOval(-48, 37, 96, 20);
        g.setStroke(Color.web("#CFD8DC", 0.72));
        g.setLineWidth(4);
        for (int line = 0; line < 3; line++) {
            double trail = -70 - line * 34;
            g.strokeLine(trail, -10 + line * 14, trail - 38, -5 + line * 14);
        }

        g.setFill(feather);
        g.fillOval(-42, -34, 82, 76);
        g.setFill(feather.brighter());
        g.fillOval(18, -27, 48, 48);
        g.setFill(Color.web("#F57C00"));
        g.fillPolygon(new double[]{58, 94, 58}, new double[]{-15, -2, 9}, 3);
        g.setFill(Color.WHITE);
        g.fillOval(35, -25, 25, 25);
        g.setFill(Color.BLACK);
        g.fillOval(44, -18, 12, 12);

        // Prison uniform, number plate, and a loose shackle sell the hazard at gameplay scale.
        g.setFill(Color.web("#EF6C00"));
        g.fillRoundRect(-30, -4, 62, 32, 18, 18);
        g.setFill(Color.web("#1B1B1B"));
        g.fillRect(-28, 5, 58, 7);
        g.setFill(Color.web("#ECEFF1"));
        g.fillRoundRect(-9, -1, 28, 19, 5, 5);
        g.setFill(Color.web("#263238"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 11));
        g.fillText("C" + (rush.variant + 3), -4, 13);

        g.setStroke(Color.web("#B0BEC5"));
        g.setLineWidth(5);
        g.strokeLine(-18, 32, -26 + stride * 13, 47);
        g.strokeLine(13, 31, 20 - stride * 13, 47);
        g.strokeOval(-36, 38, 20, 12);
        g.strokeLine(-16, 44, -2, 44);
        g.restore();
    }

    private boolean updateAnchoredCrowMinion(CrowMinion c) {
        if (c.anchorGuardFrames > 0) {
            c.anchorGuardFrames--;
        }
        if (c.anchorGuardFrames <= 0) {
            return true;
        }

        Bird closest = c.target;
        if (!isValidAnchoredCrowTarget(c, closest)) {
            closest = null;
        }
        if (closest == null || c.retargetCooldown <= 0) {
            double bestSq = Double.MAX_VALUE;
            for (Bird b : players) {
                if (!isValidAnchoredCrowTarget(c, b)) continue;
                double dx = b.x + 40 - c.x;
                double dy = b.y + 40 - c.y;
                double distSq = dx * dx + dy * dy;
                if (distSq < bestSq) {
                    bestSq = distSq;
                    closest = b;
                }
            }
            c.target = closest;
            c.retargetCooldown = isLargeFightLoad() ? 12 : 6;
        }

        double targetX;
        double targetY;
        if (closest != null) {
            targetX = closest.x + 40;
            targetY = closest.y + 40;
        } else {
            double orbit = c.anchorOrbitOffset + c.age * 0.055;
            targetX = c.anchorX + Math.cos(orbit) * c.anchorRadius * 0.54;
            targetY = c.anchorY + Math.sin(orbit) * c.anchorRadius * 0.34;
        }

        double dx = targetX - c.x;
        double dy = targetY - c.y;
        double dist = Math.hypot(dx, dy);
        if (dist > 0.001) {
            double accel = closest == null ? 0.13 : 0.20;
            c.vx += dx / dist * accel;
            c.vy += dy / dist * accel;
        }

        double anchorDx = c.x - c.anchorX;
        double anchorDy = c.y - c.anchorY;
        double anchorDist = Math.hypot(anchorDx, anchorDy);
        if (anchorDist > c.anchorRadius * 0.72) {
            c.vx -= anchorDx / Math.max(1.0, anchorDist) * 0.24;
            c.vy -= anchorDy / Math.max(1.0, anchorDist) * 0.24;
        }

        double maxSpeed = closest == null ? 2.25 : 3.05;
        double speedSq = c.vx * c.vx + c.vy * c.vy;
        if (speedSq > maxSpeed * maxSpeed) {
            double speedNow = Math.sqrt(speedSq);
            c.vx = c.vx / speedNow * maxSpeed;
            c.vy = c.vy / speedNow * maxSpeed;
        }

        c.x += c.vx;
        c.y += c.vy;

        anchorDx = c.x - c.anchorX;
        anchorDy = c.y - c.anchorY;
        anchorDist = Math.hypot(anchorDx, anchorDy);
        if (anchorDist > c.anchorRadius) {
            c.x = c.anchorX + anchorDx / anchorDist * c.anchorRadius;
            c.y = c.anchorY + anchorDy / anchorDist * c.anchorRadius;
            c.vx *= 0.42;
            c.vy *= 0.42;
        }

        if (isValidAnchoredCrowTarget(c, closest)) {
            double hitDx = (closest.x + 40) - c.x;
            double hitDy = (closest.y + 40) - c.y;
            if (Math.hypot(hitDx, hitDy) < 48.0) {
                double oldHealth = closest.health;
                double dealtDamage = closest.receiveOwnedMinionDamage(c.contactDamage(), c.owner);
                if (dealtDamage <= 0) {
                    return true;
                }
                int shownDamage = (int) Math.round(dealtDamage);
                addToKillFeed(c.displayName() + " guards the bone from " + shortName(closest.name) + "! -" + shownDamage + " HP");
                double hitDirection = Math.signum(hitDx == 0.0 ? c.vx : hitDx);
                if (hitDirection == 0.0) {
                    hitDirection = closest.facingRight ? -1.0 : 1.0;
                }
                recordTrainingVultureCrowHit(c.owner, closest);
                double launchMultiplier = c.contactLaunchMultiplier();
                closest.vx += (hitDirection * 5.4 + c.vx * 0.25) * launchMultiplier;
                closest.vy -= 3.6 * launchMultiplier;
                recordOwnedCrowImpact(c, closest, oldHealth, dealtDamage);
                int particleCount = scaledParticleBurstCount(16);
                for (int i = 0; i < particleCount; i++) {
                    double angle = nextParticleRandom() * Math.PI * 2;
                    double spd = 4 + nextParticleRandom() * 12;
                    particles.add(new Particle(c.x, c.y, Math.cos(angle) * spd, Math.sin(angle) * spd - 5,
                            Color.DARKRED.deriveColor(0, 1, 1, 0.86)));
                }
                return true;
            }
        }

        return c.x < -1500 || c.x > WORLD_WIDTH + 1500 || c.y < -1500 || c.y > WORLD_HEIGHT + 1500;
    }

    private void recordOwnedCrowImpact(CrowMinion crow, Bird target, double oldHealth, double dealtDamage) {
        Bird owner = crow == null ? null : crow.owner;
        if (owner == null || target == null || dealtDamage <= 0.0) {
            return;
        }
        int ownerIndex = owner.playerIndex;
        if (ownerIndex < 0 || ownerIndex >= damageDealt.length) {
            return;
        }

        int shownDamage = Math.max(1, (int) Math.round(dealtDamage));
        damageDealt[ownerIndex] += shownDamage;
        specialHits[ownerIndex]++;
        specialDamageDealt[ownerIndex] += shownDamage;
        owner.confirmSpecialHit(shownDamage, Color.web("#B71C1C"));

        String moveName = crow.displayName();
        recordTelemetryMoveImpact(owner, moveName, shownDamage, true);
        boolean isKill = !usesSmashCombatRules() && oldHealth > 0.0 && target.health <= 0.0;
        emitCombatImpact(owner, target, target.bodyCenterX(), target.bodyCenterY(),
                target.vx, target.vy, dealtDamage, isKill, moveName);
        if (isKill) {
            eliminations[ownerIndex]++;
            recordMoveKo(owner, target, moveName);
        }
    }

    private boolean isValidAnchoredCrowTarget(CrowMinion c, Bird b) {
        if (b == null || b.health <= 0) return false;
        if (c.owner != null && !canDamage(c.owner, b)) return false;
        double dx = b.x + 40 - c.anchorX;
        double dy = b.y + 40 - c.anchorY;
        double allowed = c.anchorRadius + 40.0 * Math.max(0.75, b.sizeMultiplier);
        return dx * dx + dy * dy <= allowed * allowed;
    }

    private void drawCrowMinion(GraphicsContext g, CrowMinion crow) {
        int variant = crow.effectiveVariant();
        if (variant == CrowMinion.VARIANT_VULTURE_HENCHMAN) {
            drawVultureHenchman(g, crow);
            return;
        }
        double pulseVal = 1.0 + 0.3 * Math.sin(crow.age * 0.4);
        double scale = pulseVal * crow.drawScale();
        double hitFlash = Math.clamp(crow.hitFlashTimer / 10.0, 0.0, 1.0);
        double drawX = crow.x + (hitFlash > 0 ? (crow.hitFlashTimer % 2 == 0 ? 2.4 : -2.4) * scale : 0.0);
        double drawY = crow.y - hitFlash * 2.0 * scale;
        double dir = crow.vx >= 0.0 ? 1.0 : -1.0;
        double flap = Math.sin(crow.age * 0.46);
        double wingLift = -4.0 - flap * (variant == CrowMinion.VARIANT_GIANT_CROW ? 5.6 : 4.2);

        Color body = switch (variant) {
            case CrowMinion.VARIANT_GIANT_CROW -> Color.web("#140407");
            case CrowMinion.VARIANT_RAVEN -> Color.web("#111822");
            case CrowMinion.VARIANT_VOID_RAVEN -> Color.web("#08070D");
            case CrowMinion.VARIANT_MURDER_CROW -> Color.rgb(20, 0, 0);
            default -> Color.BLACK;
        };
        Color wings = switch (variant) {
            case CrowMinion.VARIANT_GIANT_CROW -> Color.web("#2B070C");
            case CrowMinion.VARIANT_RAVEN -> Color.web("#283445");
            case CrowMinion.VARIANT_VOID_RAVEN -> Color.web("#25102B");
            case CrowMinion.VARIANT_MURDER_CROW -> Color.rgb(40, 0, 0);
            default -> Color.rgb(30, 30, 40);
        };
        Color trim = switch (variant) {
            case CrowMinion.VARIANT_GIANT_CROW -> Color.web("#7B1B22");
            case CrowMinion.VARIANT_RAVEN -> Color.web("#607D8B");
            case CrowMinion.VARIANT_VOID_RAVEN -> Color.web("#B71C5C");
            case CrowMinion.VARIANT_MURDER_CROW -> Color.web("#8E0000");
            default -> Color.web("#455A64");
        };
        Color highlight = switch (variant) {
            case CrowMinion.VARIANT_RAVEN -> Color.web("#546E7A");
            case CrowMinion.VARIANT_VOID_RAVEN -> Color.web("#6A1B9A");
            case CrowMinion.VARIANT_GIANT_CROW -> Color.web("#4A0D13");
            case CrowMinion.VARIANT_MURDER_CROW -> Color.web("#5A0000");
            default -> Color.web("#37474F");
        };
        Color eyes = switch (variant) {
            case CrowMinion.VARIANT_RAVEN -> Color.web("#90CAF9");
            case CrowMinion.VARIANT_VOID_RAVEN -> Color.web("#FF80AB");
            default -> Color.RED.brighter();
        };
        if (hitFlash > 0) {
            body = body.interpolate(Color.web("#FFEBEE"), 0.18 + hitFlash * 0.28);
            wings = wings.interpolate(Color.web("#FFF59D"), 0.10 + hitFlash * 0.22);
        }

        g.save();
        g.setFill(Color.rgb(0, 0, 0, 0.30));
        g.fillOval(drawX - 26 * scale, drawY + 12 * scale, 52 * scale, 12 * scale);
        if (variant == CrowMinion.VARIANT_VOID_RAVEN) {
            g.setFill(Color.web("#B71C5C", 0.12 + 0.05 * Math.sin(crow.age * 0.18)));
            g.fillOval(drawX - 32 * scale, drawY - 26 * scale, 64 * scale, 58 * scale);
        }
        if (crow.anchorGuard) {
            g.setStroke(trim.deriveColor(0, 1, 1, 0.36));
            g.setLineWidth(1.4 * scale);
            g.strokeOval(drawX - 24 * scale, drawY - 22 * scale, 48 * scale, 42 * scale);
        }
        g.translate(drawX, drawY);
        g.scale(dir * scale, scale);

        g.setFill(wings.darker());
        g.fillPolygon(
                new double[]{-7, -22, -44, -28, -4},
                new double[]{-4, wingLift - 18, wingLift - 2, 13, 10},
                5
        );
        g.setStroke(Color.web("#050507", 0.74));
        g.setLineWidth(2.0);
        g.strokePolygon(
                new double[]{-7, -22, -44, -28, -4},
                new double[]{-4, wingLift - 18, wingLift - 2, 13, 10},
                5
        );

        g.setFill(body.darker());
        g.fillPolygon(
                new double[]{-16, -30, -21, -35, -13},
                new double[]{1, -8, 6, 13, 12},
                5
        );

        g.setFill(body);
        g.fillOval(-15, -11, 33, 23);
        g.setStroke(Color.web("#050507", 0.82));
        g.setLineWidth(2.0);
        g.strokeOval(-15, -11, 33, 23);

        g.setFill(highlight.deriveColor(0, 0.88, 1.10, 0.62));
        g.fillOval(-6, -8, 17, 10);
        g.setStroke(trim.deriveColor(0, 1, 1, 0.82));
        g.setLineWidth(1.5);
        g.strokeLine(-10, 2, 9, 7);
        g.strokeLine(-9, 6, 6, 10);

        g.setFill(wings);
        g.fillPolygon(
                new double[]{-2, -26, -50, -27, 8},
                new double[]{-2, wingLift - 23, wingLift + 1, 18, 10},
                5
        );
        g.setStroke(Color.web("#050507", 0.80));
        g.setLineWidth(2.1);
        g.strokePolygon(
                new double[]{-2, -26, -50, -27, 8},
                new double[]{-2, wingLift - 23, wingLift + 1, 18, 10},
                5
        );
        g.setStroke(highlight.deriveColor(0, 1, 1, 0.75));
        g.setLineWidth(1.35);
        g.strokeLine(-12, wingLift - 9, -34, wingLift + 2);
        g.strokeLine(-7, wingLift - 2, -25, wingLift + 12);

        g.setFill(body.brighter());
        g.fillOval(6, -17, 23, 20);
        g.setStroke(Color.web("#050507", 0.82));
        g.setLineWidth(1.8);
        g.strokeOval(6, -17, 23, 20);
        g.setFill(trim.deriveColor(0, 0.9, 1.08, 0.64));
        g.fillArc(10, -14, 14, 10, 12, 136, ArcType.CHORD);

        g.setFill(variant == CrowMinion.VARIANT_ALLIED_CROW ? Color.web("#B0BEC5") : Color.web("#263238"));
        g.fillPolygon(
                new double[]{26, 18, 18},
                new double[]{-7, -2, -12},
                3
        );
        g.setStroke(Color.web("#050507", 0.78));
        g.setLineWidth(1.2);
        g.strokePolygon(
                new double[]{26, 18, 18},
                new double[]{-7, -2, -12},
                3
        );

        g.setEffect(new Glow(0.42));
        g.setFill(eyes);
        g.fillOval(17, -11, 6.2, 6.2);
        g.setFill(Color.web("#FFFDE7", 0.84));
        g.fillOval(19, -10, 1.8, 1.8);
        g.setEffect(null);

        g.setStroke(trim.deriveColor(0, 0.9, 1.2, 0.72));
        g.setLineWidth(1.25);
        g.strokeLine(-4, 10, -9, 16);
        g.strokeLine(5, 10, 3, 17);
        g.setStroke(Color.web("#FFF8E1", 0.58));
        g.strokeLine(-9, 16, -14, 17);
        g.strokeLine(3, 17, 9, 18);

        if (variant == CrowMinion.VARIANT_VOID_RAVEN) {
            g.setStroke(Color.web("#FF80AB").deriveColor(0, 1, 1, 0.75));
            g.setLineWidth(1.6);
            g.strokeOval(-20, -22, 45, 34);
            g.setStroke(Color.web("#CE93D8", 0.58));
            g.strokeArc(-31, -31, 58, 50, 206, 118, ArcType.OPEN);
        }
        if (crow.hasCrown) {
            double crownW = 20;
            double crownH = 11;
            double cx = 17.5;
            double cy = -28;
            double[] xs = new double[]{
                    cx - crownW / 2, cx - crownW / 4, cx, cx + crownW / 4, cx + crownW / 2,
                    cx + crownW / 2, cx - crownW / 2
            };
            double[] ys = new double[]{
                    cy + crownH, cy, cy + crownH * 0.3, cy, cy + crownH, cy + crownH * 1.3, cy + crownH * 1.3
            };
            g.setFill(variant == CrowMinion.VARIANT_VOID_RAVEN ? Color.web("#B71C5C") : Color.GOLD);
            g.fillPolygon(xs, ys, xs.length);
            g.setStroke(variant == CrowMinion.VARIANT_VOID_RAVEN ? Color.web("#FFCDD2") : Color.web("#FFF59D"));
            g.setLineWidth(1.2);
            g.strokePolygon(xs, ys, xs.length);
        }
        g.restore();
    }

    private void drawVultureHenchman(GraphicsContext g, CrowMinion henchman) {
        double scale = henchman.drawScale() * (1.0 + 0.08 * Math.sin(henchman.age * 0.34));
        double hitFlash = Math.clamp(henchman.hitFlashTimer / 10.0, 0.0, 1.0);
        double drawX = henchman.x + (hitFlash > 0.0 ? (henchman.hitFlashTimer % 2 == 0 ? 2.2 : -2.2) * scale : 0.0);
        double drawY = henchman.y - hitFlash * 2.0 * scale;
        double dir = henchman.vx >= 0.0 ? 1.0 : -1.0;
        double flap = Math.sin(henchman.age * 0.42);
        Color body = Color.web("#17131A").interpolate(Color.web("#FFEBEE"), hitFlash * 0.34);
        Color wing = Color.web("#29222E").interpolate(Color.web("#FFF59D"), hitFlash * 0.22);
        Color flesh = Color.web("#79343B");
        Color beak = Color.web("#8D7844");

        g.save();
        g.setFill(Color.rgb(0, 0, 0, 0.32));
        g.fillOval(drawX - 30.0 * scale, drawY + 16.0 * scale, 60.0 * scale, 13.0 * scale);
        g.translate(drawX, drawY);
        g.scale(dir * scale, scale);

        double wingLift = -8.0 - flap * 8.0;
        g.setFill(wing.darker());
        g.fillPolygon(
                new double[]{-7, -28, -51, -38, -13, 3},
                new double[]{0, wingLift - 20, wingLift - 5, wingLift + 17, 18, 10},
                6
        );
        g.setStroke(Color.web("#08060A", 0.88));
        g.setLineWidth(2.0);
        g.strokePolygon(
                new double[]{-7, -28, -51, -38, -13, 3},
                new double[]{0, wingLift - 20, wingLift - 5, wingLift + 17, 18, 10},
                6
        );

        g.setFill(body);
        g.fillOval(-20, -10, 43, 31);
        g.setStroke(Color.web("#070609", 0.88));
        g.setLineWidth(2.0);
        g.strokeOval(-20, -10, 43, 31);
        g.setFill(Color.web("#3B303F", 0.78));
        g.fillArc(-15, -7, 31, 23, 205, 150, ArcType.ROUND);

        g.setFill(wing);
        g.fillPolygon(
                new double[]{-1, -25, -48, -34, -7, 10},
                new double[]{-2, wingLift - 24, wingLift + 1, wingLift + 21, 18, 8},
                6
        );
        g.setStroke(Color.web("#08060A", 0.90));
        g.strokePolygon(
                new double[]{-1, -25, -48, -34, -7, 10},
                new double[]{-2, wingLift - 24, wingLift + 1, wingLift + 21, 18, 8},
                6
        );
        g.setStroke(Color.web("#6D5B70", 0.56));
        g.setLineWidth(1.2);
        g.strokeLine(-13, wingLift - 9, -35, wingLift + 4);
        g.strokeLine(-7, wingLift - 2, -27, wingLift + 14);

        g.setStroke(flesh.darker());
        g.setLineCap(StrokeLineCap.ROUND);
        g.setLineWidth(11.0);
        g.strokeLine(13, 1, 19, -17);
        g.setStroke(flesh);
        g.setLineWidth(7.0);
        g.strokeLine(13, 1, 19, -17);
        g.setFill(flesh);
        g.fillOval(11, -28, 25, 21);
        g.setStroke(Color.web("#351419", 0.72));
        g.setLineWidth(1.3);
        g.strokeArc(14, -23, 17, 9, 190, 115, ArcType.OPEN);

        g.setFill(beak.darker());
        g.fillPolygon(new double[]{30, 48, 32}, new double[]{-23, -17, -12}, 3);
        g.setFill(beak);
        g.fillPolygon(new double[]{28, 49, 31}, new double[]{-25, -20, -17}, 3);
        g.setFill(Color.web("#FF1744"));
        g.fillOval(25, -22, 5.5, 5.5);
        g.setFill(Color.web("#FFF8E1"));
        g.fillOval(27, -21, 1.5, 1.5);

        g.setStroke(Color.web("#6D5A3A"));
        g.setLineWidth(2.0);
        g.strokeLine(-5, 18, -8, 27);
        g.strokeLine(8, 17, 10, 27);
        g.strokeLine(-8, 27, -15, 29);
        g.strokeLine(10, 27, 18, 28);

        if (henchman.hasCrown) {
            g.setFill(Color.web("#FFD54F"));
            g.fillPolygon(
                    new double[]{12, 16, 21, 26, 31, 32, 12},
                    new double[]{-30, -41, -33, -43, -31, -27, -27},
                    7
            );
            g.setStroke(Color.web("#FFF59D", 0.82));
            g.setLineWidth(1.2);
            g.strokePolyline(
                    new double[]{12, 16, 21, 26, 31, 32},
                    new double[]{-30, -41, -33, -43, -31, -27},
                    6
            );
        }
        g.restore();
    }

    private void drawPiranhaHazard(GraphicsContext g, PiranhaHazard piranha) {
        double dir = piranha.vx >= 0 ? 1.0 : -1.0;
        double bodyW = 56;
        double bodyH = 31;
        double x = piranha.x;
        double y = piranha.y;
        double bitePulse = piranha.biteCooldown > 0 ? 1.0 : 0.0;
        double breach = Math.clamp(piranha.breachCooldown / 48.0, 0.0, 1.0);
        double swim = Math.sin(piranha.age * 0.34);
        double mouthOpen = 0.20 + bitePulse * 0.58 + Math.max(0.0, swim) * 0.10;

        g.save();
        g.setFill(Color.web("#0A1A20", 0.26));
        g.fillOval(x - bodyW * 0.58, y + bodyH * 0.36, bodyW * 1.18, bodyH * 0.32);
        if (breach > 0.0) {
            g.setStroke(Color.web("#B3E5FC", 0.20 + breach * 0.18));
            g.setLineWidth(2.0);
            g.strokeArc(x - bodyW * 0.72, y + bodyH * 0.18, bodyW * 1.44, bodyH * 0.72,
                    200, 140, ArcType.OPEN);
            g.setFill(Color.web("#E1F5FE", 0.12 + breach * 0.16));
            g.fillOval(x - bodyW * 0.46, y + bodyH * 0.28, bodyW * 0.92, bodyH * 0.20);
        }
        for (int i = 1; i <= 3; i++) {
            double trailX = x - dir * (bodyW * (0.42 + i * 0.16));
            g.setStroke(Color.web("#80DEEA", 0.10 - i * 0.018));
            g.setLineWidth(1.4);
            g.strokeArc(trailX - bodyW * 0.32, y + bodyH * (0.14 + i * 0.02),
                    bodyW * 0.62, bodyH * 0.40, 210, 112, ArcType.OPEN);
        }

        g.translate(x, y + swim * 1.2);
        g.scale(dir, 1.0);

        g.setFill(Color.web("#8E0000"));
        g.fillPolygon(
                new double[]{-bodyW * 0.42, -bodyW * 0.78, -bodyW * 0.48},
                new double[]{0, -bodyH * 0.48, bodyH * 0.44},
                3
        );
        g.setStroke(Color.web("#260507", 0.85));
        g.setLineWidth(2.0);
        g.strokePolygon(
                new double[]{-bodyW * 0.42, -bodyW * 0.78, -bodyW * 0.48},
                new double[]{0, -bodyH * 0.48, bodyH * 0.44},
                3
        );

        g.setFill(Color.web("#EF5350"));
        g.fillPolygon(
                new double[]{-bodyW * 0.02, bodyW * 0.14, bodyW * 0.32},
                new double[]{-bodyH * 0.32, -bodyH * 0.66, -bodyH * 0.22},
                3
        );
        g.setFill(Color.web("#C62828"));
        g.fillOval(-bodyW * 0.52, -bodyH * 0.50, bodyW * 0.95, bodyH);
        g.setStroke(Color.web("#260507", 0.88));
        g.setLineWidth(2.3);
        g.strokeOval(-bodyW * 0.52, -bodyH * 0.50, bodyW * 0.95, bodyH);

        g.setFill(Color.web("#FF8A80", 0.72));
        g.fillOval(-bodyW * 0.20, -bodyH * 0.42, bodyW * 0.40, bodyH * 0.42);
        g.setStroke(Color.web("#FFCDD2", 0.50));
        g.setLineWidth(1.5);
        g.strokeArc(-bodyW * 0.30, -bodyH * 0.35, bodyW * 0.52, bodyH * 0.52, 20, 110, ArcType.OPEN);

        g.setFill(Color.web("#8E0000"));
        g.fillPolygon(
                new double[]{-bodyW * 0.10, -bodyW * 0.22, -bodyW * 0.02},
                new double[]{bodyH * 0.48, bodyH * 0.78, bodyH * 0.56},
                3
        );
        g.setFill(Color.web("#6D0000"));
        g.fillPolygon(
                new double[]{-bodyW * 0.36, -bodyW * 0.52, -bodyW * 0.30},
                new double[]{bodyH * 0.16, bodyH * 0.36, bodyH * 0.32},
                3
        );

        double jawX = bodyW * 0.19;
        double topLipY = -bodyH * (0.13 + mouthOpen * 0.28);
        double bottomLipY = bodyH * (0.10 + mouthOpen * 0.25);
        g.setFill(Color.web("#B71C1C"));
        g.fillPolygon(
                new double[]{jawX - bodyW * 0.08, bodyW * 0.58, bodyW * 0.34, jawX - bodyW * 0.04},
                new double[]{-bodyH * 0.30, topLipY, -bodyH * 0.02, bodyH * 0.04},
                4
        );
        g.fillPolygon(
                new double[]{jawX - bodyW * 0.08, bodyW * 0.60, bodyW * 0.34, jawX - bodyW * 0.04},
                new double[]{bodyH * 0.26, bottomLipY, bodyH * 0.02, -bodyH * 0.02},
                4
        );
        g.setStroke(Color.web("#260507", 0.88));
        g.setLineWidth(2.0);
        g.strokeLine(jawX - bodyW * 0.05, topLipY, bodyW * 0.55, -bodyH * 0.02);
        g.strokeLine(jawX - bodyW * 0.05, bottomLipY, bodyW * 0.55, bodyH * 0.02);

        g.setFill(Color.web("#FFFDE7"));
        for (int i = 0; i < 4; i++) {
            double tx = bodyW * (0.24 + i * 0.075);
            double tooth = i % 2 == 0 ? 6.0 : 5.0;
            g.fillPolygon(
                    new double[]{tx, tx + 3.6, tx + 7.2},
                    new double[]{topLipY + 1.0, topLipY + tooth, topLipY + 1.0},
                    3
            );
            g.fillPolygon(
                    new double[]{tx + 2.0, tx + 5.6, tx + 9.2},
                    new double[]{bottomLipY - 1.0, bottomLipY - tooth, bottomLipY - 1.0},
                    3
            );
        }

        g.setFill(Color.web("#FFFDE7"));
        g.fillOval(bodyW * 0.02, -bodyH * 0.32, 8.0, 8.0);
        g.setFill(Color.web("#111111"));
        g.fillOval(bodyW * 0.04, -bodyH * 0.30, 4.2, 4.2);
        g.setFill(Color.web("#FFFFFF", 0.88));
        g.fillOval(bodyW * 0.055, -bodyH * 0.29, 1.4, 1.4);

        g.setStroke(Color.web("#FFCDD2", 0.45));
        g.setLineWidth(1.3);
        g.strokeLine(-bodyW * 0.28, -bodyH * 0.20, -bodyW * 0.20, bodyH * 0.22);
        g.strokeLine(-bodyW * 0.17, -bodyH * 0.23, -bodyW * 0.09, bodyH * 0.21);
        if (bitePulse > 0) {
            g.setStroke(Color.web("#FFEB3B", 0.6));
            g.setLineWidth(2.2);
            g.strokeOval(-bodyW * 0.58, -bodyH * 0.74, bodyW * 1.18, bodyH * 1.50);
        }
        g.restore();
    }

    private void drawDockShipBomb(GraphicsContext g, DockShipBomb bomb) {
        if (bomb == null) return;
        double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 95.0);
        if (!bomb.exploded) {
            double warningRadius = DOCK_BOMB_WARNING_RADIUS + pulse * 10.0;
            double telegraphAlpha = bomb.fired ? 0.2 : 0.28 + (1.0 - Math.max(0, bomb.launchDelayFrames) / (double) DOCK_BOMB_LOCKON_FRAMES) * 0.22;
            g.setFill(Color.web("#D50000", telegraphAlpha * 0.38));
            g.fillOval(bomb.targetX - warningRadius, bomb.targetY - warningRadius, warningRadius * 2, warningRadius * 2);
            g.setStroke(Color.web("#FF5252", Math.min(0.92, telegraphAlpha + 0.24)));
            g.setLineWidth(4.5);
            g.strokeOval(bomb.targetX - warningRadius, bomb.targetY - warningRadius, warningRadius * 2, warningRadius * 2);
            g.setStroke(Color.web("#FF8A80", Math.min(0.96, telegraphAlpha + 0.3)));
            g.setLineWidth(2.6);
            g.strokeLine(bomb.targetX - warningRadius * 0.72, bomb.targetY, bomb.targetX + warningRadius * 0.72, bomb.targetY);
            g.strokeLine(bomb.targetX, bomb.targetY - warningRadius * 0.72, bomb.targetX, bomb.targetY + warningRadius * 0.72);
        }

        double muzzleX = dockShipCannonMuzzleX();
        double muzzleY = dockShipCannonMuzzleY();
        if (!bomb.fired) {
            g.setStroke(Color.web("#FF8A80", 0.26 + pulse * 0.12));
            g.setLineWidth(3.2);
            g.setLineDashes(18, 12);
            g.strokeLine(muzzleX, muzzleY, bomb.targetX, bomb.targetY);
            g.setLineDashes();
            double charge = 1.0 - Math.max(0, bomb.launchDelayFrames) / (double) DOCK_BOMB_LOCKON_FRAMES;
            double chargeRadius = 28 + charge * 40;
            g.setFill(Color.web("#FFB74D", 0.22 + charge * 0.24));
            g.fillOval(muzzleX - chargeRadius, muzzleY - chargeRadius * 0.72, chargeRadius * 2, chargeRadius * 1.44);
            g.setStroke(Color.web("#FFF59D", 0.34 + charge * 0.36));
            g.setLineWidth(3.0);
            g.strokeOval(muzzleX - chargeRadius * 0.78, muzzleY - chargeRadius * 0.52, chargeRadius * 1.56, chargeRadius * 1.04);
            return;
        }

        if (bomb.cannonFlashFrames > 0) {
            double flash = bomb.cannonFlashFrames / (double) DOCK_BOMB_CANNON_FLASH_FRAMES;
            g.setFill(Color.web("#FFD54F", 0.22 + flash * 0.48));
            g.fillOval(muzzleX - 62, muzzleY - 34, 124, 68);
            g.setFill(Color.web("#FFF8E1", 0.24 + flash * 0.54));
            g.fillPolygon(
                    new double[]{muzzleX - 8, muzzleX - 88, muzzleX - 30, muzzleX - 108, muzzleX - 24},
                    new double[]{muzzleY - 14, muzzleY - 32, muzzleY, muzzleY + 20, muzzleY + 14},
                    5
            );
        }

        if (bomb.exploded) {
            double radius = 90 + bomb.explosionFrames * 8;
            g.setFill(Color.web("#FFCA28", 0.28));
            g.fillOval(bomb.x - radius, bomb.y - radius, radius * 2, radius * 2);
            g.setStroke(Color.web("#FFF59D", 0.75));
            g.setLineWidth(4);
            g.strokeOval(bomb.x - radius * 0.78, bomb.y - radius * 0.78, radius * 1.56, radius * 1.56);
            return;
        }

        for (int i = 5; i >= 1; i--) {
            double trailX = bomb.x - bomb.vx * i * 2.1;
            double trailY = bomb.y - bomb.vy * i * 2.1 + DOCK_BOMB_GRAVITY * i * i * 0.45;
            double size = 16 + i * 5;
            g.setFill(Color.web("#6D4C41", 0.08 + i * 0.06));
            g.fillOval(trailX - size * 0.5, trailY - size * 0.42, size, size * 0.84);
        }
        g.setStroke(Color.web("#6D4C41", 0.56));
        g.setLineWidth(2.6);
        g.strokeLine(bomb.x + 8, bomb.y - 10, bomb.x + 18, bomb.y - 24);
        g.setFill(Color.web("#2B2B2B"));
        g.fillOval(bomb.x - 22, bomb.y - 22, 44, 44);
        g.setStroke(Color.web("#B0BEC5"));
        g.setLineWidth(2.8);
        g.strokeOval(bomb.x - 22, bomb.y - 22, 44, 44);
        g.setFill(Color.web("#FF7043", 0.92));
        g.fillOval(bomb.x + 14, bomb.y - 28, 12, 12);
        g.setFill(Color.web("#FFD180", 0.32));
        g.fillOval(bomb.x - 34, bomb.y - 16, 24, 14);
    }

    private void drawChickMinion(GraphicsContext g, ChickMinion chick) {
        double pulse = 1.0 + 0.05 * Math.sin(chick.age * 0.35);
        double w = chick.width * pulse;
        double h = chick.height * pulse;
        double x = chick.x + (chick.width - w) * 0.5;
        double y = chick.y + (chick.height - h) * 0.5;
        boolean facingRight = chick.vx >= 0;
        boolean sunforgeBrood = chick.owner != null
                && chick.owner.type == BirdType.ROOSTER
                && chick.owner.isSunforgeSkin;
        if (chick.owner != null && chick.owner.type == BirdType.ROOSTER && chick.followingOwner) {
            double ownerCx = chick.owner.x + 40.0 * chick.owner.sizeMultiplier;
            double ownerCy = chick.owner.y + 54.0 * chick.owner.sizeMultiplier;
            Color tether = sunforgeBrood ? Color.web("#FFD54F") : Color.web("#FFF176");
            g.setStroke(tether.deriveColor(0, 1, 1, 0.22 + 0.10 * Math.sin(chick.age * 0.22)));
            g.setLineWidth(Math.max(1.0, 1.4 * chick.owner.sizeMultiplier));
            g.setLineDashes(5.0, 8.0);
            g.strokeLine(ownerCx, ownerCy, x + w * 0.55, y + h * 0.54);
            g.setLineDashes();
        }

        Color body;
        Color accent;
        Color trim = null;
        if (sunforgeBrood) {
            switch (chick.variant) {
                case 1 -> {
                    body = Color.web("#455A64");
                    accent = Color.web("#4DD0E1");
                    trim = Color.web("#FFD54F");
                }
                case 2 -> {
                    body = Color.web("#8D6E63");
                    accent = Color.web("#FF7043");
                    trim = Color.web("#FFD54F");
                }
                default -> {
                    body = Color.web("#6D4C41");
                    accent = Color.web("#FFB300");
                    trim = Color.web("#FFF176");
                }
            }
        } else {
            switch (chick.variant) {
                case 1 -> {
                    body = Color.web("#FFF8E1");
                    accent = Color.web("#4FC3F7");
                    trim = Color.web("#90CAF9");
                }
                case 2 -> {
                    body = Color.web("#FFB74D");
                    accent = Color.web("#6D4C41");
                }
                default -> {
                    body = Color.web("#FFD54F");
                    accent = Color.web("#F57C00");
                    trim = Color.web("#FF7043");
                }
            }
        }

        g.setFill(Color.rgb(0, 0, 0, 0.22));
        g.fillOval(x + w * 0.02, y + h * 0.78, w * 1.06, h * 0.24);

        if (chick.roosterSwarm && chick.swarmVisualCopies > 0) {
            double lifeFade = Math.clamp(1.0 - chick.age / (double) Math.max(1, chick.maxAge), 0.15, 1.0);
            double backDir = chick.vx >= 0.0 ? -1.0 : 1.0;
            int copies = Math.min(7, chick.swarmVisualCopies);
            for (int i = copies; i >= 1; i--) {
                double phase = chick.age * 0.26 + chick.variant * 1.7 + i * 0.9;
                double side = i % 2 == 0 ? -1.0 : 1.0;
                double scale = 0.74 - i * 0.035;
                double copyW = w * scale;
                double copyH = h * scale;
                double copyX = x + backDir * (20.0 + i * 14.0) + side * Math.sin(phase) * (8.0 + i * 2.0);
                double copyY = y + Math.cos(phase * 0.8) * (6.0 + i * 1.5) + i * 1.4;
                double alpha = Math.clamp((0.24 - i * 0.018) * lifeFade, 0.05, 0.24);
                Color copyBody = body.deriveColor(0, 1.0, 1.10, alpha);
                Color copyAccent = accent.deriveColor(0, 1.0, 1.08, alpha + 0.08);
                g.setFill(copyBody);
                g.fillOval(copyX, copyY + copyH * 0.22, copyW * 1.08, copyH * 0.78);
                double copyHeadW = copyW * 0.44;
                double copyHeadH = copyH * 0.44;
                double copyHeadX = facingRight ? copyX + copyW * 0.68 : copyX - copyHeadW * 0.08;
                double copyHeadY = copyY + copyH * 0.04;
                g.fillOval(copyHeadX, copyHeadY, copyHeadW, copyHeadH);
                g.setFill(copyAccent);
                if (facingRight) {
                    g.fillPolygon(
                            new double[]{copyHeadX + copyHeadW * 0.9, copyHeadX + copyHeadW * 1.18, copyHeadX + copyHeadW * 0.9},
                            new double[]{copyHeadY + copyHeadH * 0.45, copyHeadY + copyHeadH * 0.56, copyHeadY + copyHeadH * 0.67},
                            3
                    );
                } else {
                    g.fillPolygon(
                            new double[]{copyHeadX + copyHeadW * 0.1, copyHeadX - copyHeadW * 0.18, copyHeadX + copyHeadW * 0.1},
                            new double[]{copyHeadY + copyHeadH * 0.45, copyHeadY + copyHeadH * 0.56, copyHeadY + copyHeadH * 0.67},
                            3
                    );
                }
                g.setStroke(Color.web("#FFF59D").deriveColor(0, 1, 1, alpha * 1.3));
                g.setLineWidth(1.4);
                g.strokeLine(copyX + copyW * 0.45, copyY + copyH * 0.56,
                        copyX + copyW * 0.45 + backDir * (24.0 + i * 7.0), copyY + copyH * 0.56 + side * 5.0);
            }
        }

        if (chick.ultimate) {
            Color aura = sunforgeBrood ? Color.web("#FFB300") : Color.GOLD;
            g.setFill(aura.deriveColor(0, 1, 1, 0.25));
            g.fillOval(x - w * 0.6, y - h * 0.7, w * 2.2, h * 2.0);
            body = body.brighter();
        }
        if (chick.thrownFrames > 0) {
            double fade = Math.clamp(chick.thrownFrames / 30.0, 0.0, 1.0);
            double dir = chick.vx >= 0 ? -1.0 : 1.0;
            g.setStroke(Color.web("#FF7043").deriveColor(0, 1, 1, 0.22 + 0.30 * fade));
            g.setLineWidth(Math.max(2.0, h * 0.16));
            for (int i = 0; i < 3; i++) {
                double trailY = y + h * (0.32 + i * 0.18);
                g.strokeLine(x + w * 0.5, trailY, x + w * 0.5 + dir * (30.0 + i * 12.0) * fade, trailY + (i - 1) * 4.0);
            }
        }
        if (chick.boostSparkFrames > 0) {
            double fade = Math.clamp(chick.boostSparkFrames / 36.0, 0.0, 1.0);
            g.setStroke((sunforgeBrood ? Color.web("#FFF59D") : Color.web("#B3E5FC")).deriveColor(0, 1, 1, 0.30 + 0.34 * fade));
            g.setLineWidth(2.0);
            g.strokeOval(x - w * 0.26, y + h * 0.55, w * 1.58, h * 0.74);
            g.setFill(Color.web("#FFFFFF").deriveColor(0, 1, 1, 0.12 * fade));
            g.fillOval(x - w * 0.12, y + h * 0.76, w * 1.32, h * 0.42);
        }
        if (chick.commandFlashFrames > 0) {
            double fade = Math.clamp(chick.commandFlashFrames / 36.0, 0.0, 1.0);
            Color ring = sunforgeBrood ? Color.web("#FFD54F") : Color.web("#FFF176");
            g.setStroke(ring.deriveColor(0, 1, 1, 0.28 + 0.42 * fade));
            g.setLineWidth(1.8 + 1.6 * fade);
            g.strokeOval(x - w * (0.22 + 0.18 * fade), y - h * (0.18 + 0.16 * fade),
                    w * (1.54 + 0.36 * fade), h * (1.44 + 0.32 * fade));
        }

        g.setFill(body);
        g.fillOval(x, y + h * 0.2, w * 1.1, h * 0.8);
        g.setStroke(Color.web("#2A1A0A", sunforgeBrood ? 0.78 : 0.58));
        g.setLineWidth(Math.max(1.4, w * 0.055));
        g.strokeOval(x, y + h * 0.2, w * 1.1, h * 0.8);

        if (sunforgeBrood) {
            g.setStroke(Color.web("#FFD54F").deriveColor(0, 1, 1, chick.ultimate ? 0.95 : 0.7));
            g.setLineWidth(Math.max(1.6, w * 0.06));
            g.strokeOval(x - w * 0.02, y + h * 0.18, w * 1.14, h * 0.84);
        }

        g.setFill(body.darker());
        g.fillOval(x + w * 0.25, y + h * 0.35, w * 0.45, h * 0.4);
        g.setFill(body.brighter().deriveColor(0, 0.86, 1.12, 0.42));
        g.fillArc(x + w * 0.10, y + h * 0.24, w * 0.82, h * 0.48, 18, 108, ArcType.CHORD);
        g.setStroke(accent.deriveColor(0, 0.86, 1.10, 0.52));
        g.setLineWidth(Math.max(1.0, w * 0.035));
        g.strokeArc(x + w * 0.22, y + h * 0.38, w * 0.44, h * 0.32, 192, 132, ArcType.OPEN);

        double headW = w * 0.45;
        double headH = h * 0.45;
        double headX = facingRight ? x + w * 0.7 : x - headW * 0.1;
        double headY = y + h * 0.05;
        g.setFill(body.brighter());
        g.fillOval(headX, headY, headW, headH);
        g.setStroke(Color.web("#2A1A0A", sunforgeBrood ? 0.78 : 0.56));
        g.setLineWidth(Math.max(1.1, w * 0.04));
        g.strokeOval(headX, headY, headW, headH);

        if (chick.variant == 1) {
            g.setFill(accent);
            double crestX = headX + headW * 0.1;
            double crestY = headY - headH * 0.25;
            g.fillPolygon(
                    new double[]{crestX, crestX + headW * 0.35, crestX + headW * 0.7},
                    new double[]{crestY + headH * 0.8, crestY, crestY + headH * 0.8},
                    3
            );
        } else if (chick.variant == 0 && trim != null) {
            g.setStroke(trim);
            g.setLineWidth(2.0);
            g.strokeLine(x + w * 0.35, y + h * 0.5, x + w * 0.7, y + h * 0.58);
        } else if (chick.variant == 2) {
            g.setFill(accent);
            g.fillOval(x + w * 0.18, y + h * 0.52, w * 0.18, h * 0.18);
            g.fillOval(x + w * 0.38, y + h * 0.55, w * 0.18, h * 0.18);
        }

        if (sunforgeBrood) {
            g.setStroke(trim != null ? trim : Color.web("#FFE082"));
            g.setLineWidth(Math.max(1.2, w * 0.045));
            g.strokeLine(x + w * 0.24, y + h * 0.34, x + w * 0.82, y + h * 0.46);
        }

        g.setFill(accent);
        if (facingRight) {
            double[] beakX = new double[]{headX + headW * 0.9, headX + headW * 1.15, headX + headW * 0.9};
            double[] beakY = new double[]{headY + headH * 0.45, headY + headH * 0.55, headY + headH * 0.65};
            g.fillPolygon(beakX, beakY, 3);
            g.setStroke(Color.web("#3E2723", 0.58));
            g.setLineWidth(Math.max(0.8, w * 0.025));
            g.strokePolygon(beakX, beakY, 3);
        } else {
            double[] beakX = new double[]{headX + headW * 0.1, headX - headW * 0.15, headX + headW * 0.1};
            double[] beakY = new double[]{headY + headH * 0.45, headY + headH * 0.55, headY + headH * 0.65};
            g.fillPolygon(beakX, beakY, 3);
            g.setStroke(Color.web("#3E2723", 0.58));
            g.setLineWidth(Math.max(0.8, w * 0.025));
            g.strokePolygon(beakX, beakY, 3);
        }

        g.setFill(sunforgeBrood ? Color.web("#FFF8E1") : Color.BLACK);
        double eyeX = facingRight ? headX + headW * 0.6 : headX + headW * 0.25;
        double eyeY = headY + headH * 0.35;
        g.fillOval(eyeX, eyeY, headW * 0.15, headW * 0.15);
        g.setFill(Color.web("#FFFFFF", sunforgeBrood ? 0.92 : 0.74));
        g.fillOval(eyeX + headW * 0.052, eyeY + headW * 0.030, headW * 0.045, headW * 0.045);

        double footY = y + h * 0.92;
        double footDir = facingRight ? 1.0 : -1.0;
        g.setStroke(sunforgeBrood ? Color.web("#FFE082") : Color.web("#E65100"));
        g.setLineWidth(Math.max(1.2, w * 0.04));
        for (int i = 0; i < 2; i++) {
            double legX = x + w * (0.34 + i * 0.23);
            g.strokeLine(legX, y + h * 0.83, legX + footDir * w * 0.04, footY);
            g.strokeLine(legX + footDir * w * 0.04, footY, legX + footDir * w * 0.18, footY + h * 0.02);
            g.strokeLine(legX + footDir * w * 0.04, footY, legX - footDir * w * 0.08, footY + h * 0.03);
        }

        if (chick.ultimate) {
            double crownW = headW * 0.9;
            double crownH = headH * 0.55;
            double cx = headX + headW * 0.5;
            double cy = headY - crownH * 0.4;
            double[] xs = new double[]{
                    cx - crownW / 2, cx - crownW * 0.2, cx, cx + crownW * 0.2, cx + crownW / 2,
                    cx + crownW / 2, cx - crownW / 2
            };
            double[] ys = new double[]{
                    cy + crownH, cy, cy + crownH * 0.35, cy, cy + crownH,
                    cy + crownH * 1.25, cy + crownH * 1.25
            };
            g.setFill(Color.GOLD);
            g.fillPolygon(xs, ys, xs.length);
            g.setStroke(Color.web("#FFF59D"));
            g.setLineWidth(1.0);
            g.strokePolygon(xs, ys, xs.length);
        }
    }

    private void drawMockingbirdShadowMinion(GraphicsContext g, MockingbirdShadowMinion shadow) {
        if (shadow == null || shadow.copiedType == null) return;
        double w = shadow.bodyWidth();
        double h = shadow.bodyHeight();
        double cx = shadow.bodyCenterX();
        double cy = shadow.bodyCenterY();
        double size = shadow.sizeMultiplier();
        double lifeRatio = Math.clamp(shadow.health / Math.max(1.0, shadow.maxHealth), 0.0, 1.0);
        double spawn = Math.clamp(shadow.spawnFlashFrames / 34.0, 0.0, 1.0);
        double hit = Math.clamp(shadow.hitFlashTimer / 10.0, 0.0, 1.0);
        double pulse = 0.5 + 0.5 * Math.sin((shadow.age + shadow.slot * 17.0) * 0.24);
        Color accent = shadow.slot == 2 ? Color.web("#EC407A") : shadow.copiedType.color;

        g.save();
        g.setFill(Color.rgb(0, 0, 0, 0.30 + spawn * 0.16));
        g.fillOval(cx - w * 0.60, shadow.y + h * 0.78, w * 1.20, h * 0.24);

        g.setStroke(accent.deriveColor(0, 0.92, 0.9, 0.26 + spawn * 0.34 + pulse * 0.08));
        g.setLineWidth(2.0 + spawn * 3.5);
        g.strokeOval(cx - w * (0.60 + spawn * 0.44), cy - h * (0.47 + spawn * 0.32),
                w * (1.20 + spawn * 0.88), h * (0.94 + spawn * 0.64));
        g.setStroke(Color.web("#111019", 0.56 + spawn * 0.16));
        g.setLineWidth(2.4);
        g.strokeArc(cx - w * 0.70, cy - h * 0.54, w * 1.40, h * 1.08,
                shadow.facingRight ? 208 : -28, 150, ArcType.OPEN);

        ColorAdjust shadowTone = new ColorAdjust();
        shadowTone.setSaturation(-1.0);
        shadowTone.setBrightness(-0.78 + hit * 0.16);
        shadowTone.setContrast(0.72);
        g.setEffect(shadowTone);
        g.setGlobalAlpha(0.74 + hit * 0.20);
        Bird preview = new Bird(0.0, shadow.copiedType,
                shadow.owner != null ? Math.clamp(shadow.owner.playerIndex, 0, Math.max(0, players.length - 1)) : 0,
                this);
        preview.suppressSelectEffects = true;
        preview.setBaseMultipliers(size, 1.0, 1.0);
        preview.health = Bird.STARTING_HEALTH;
        preview.x = shadow.x;
        preview.y = shadow.y;
        preview.prevX = shadow.x;
        preview.prevY = shadow.y;
        preview.vx = shadow.vx;
        preview.vy = shadow.vy;
        preview.facingRight = shadow.facingRight;
        preview.attackAnimationTimer = shadow.attackCooldown > 31 ? 9 : 0;
        preview.draw(g);
        g.setEffect(null);
        g.setGlobalAlpha(1.0);

        g.setFill(Color.web("#050108", 0.42 + hit * 0.18));
        g.fillOval(shadow.x + w * 0.08, shadow.y + h * 0.14, w * 0.86, h * 0.78);

        double eyeY = shadow.y + h * 0.34;
        double eyeLeadX = shadow.x + (shadow.facingRight ? w * 0.68 : w * 0.26);
        double eyeBackX = eyeLeadX + (shadow.facingRight ? -w * 0.15 : w * 0.15);
        g.setEffect(new Glow(0.88));
        g.setFill(Color.web("#FF1744", 0.92));
        g.fillOval(eyeLeadX - 4.5 * size, eyeY - 3.5 * size, 9.0 * size, 7.0 * size);
        g.fillOval(eyeBackX - 3.2 * size, eyeY - 2.8 * size, 6.4 * size, 5.6 * size);
        g.setFill(Color.web("#FFCDD2", 0.82));
        g.fillOval(eyeLeadX - 1.6 * size, eyeY - 1.2 * size, 3.2 * size, 2.4 * size);
        g.setEffect(null);

        double barW = Math.max(32.0, w * 0.72);
        double barH = 5.0;
        double barX = cx - barW * 0.5;
        double barY = shadow.y - 12.0 * size;
        g.setFill(Color.rgb(0, 0, 0, 0.58));
        g.fillRoundRect(barX - 2.0, barY - 2.0, barW + 4.0, barH + 4.0, 5.0, 5.0);
        g.setFill(Color.web("#4A001A", 0.88));
        g.fillRoundRect(barX, barY, barW, barH, 4.0, 4.0);
        g.setFill(Color.web(lifeRatio > 0.45 ? "#EC407A" : "#FF1744", 0.94));
        g.fillRoundRect(barX, barY, barW * lifeRatio, barH, 4.0, 4.0);

        if (hit > 0.0) {
            g.setStroke(Color.web("#F8BBD0", 0.42 + hit * 0.42));
            g.setLineWidth(2.0 + hit * 2.0);
            g.strokeOval(cx - w * (0.48 + hit * 0.16), cy - h * (0.44 + hit * 0.14),
                    w * (0.96 + hit * 0.32), h * (0.88 + hit * 0.28));
        }
        g.restore();
    }

    private void drawBirdCompanionPreview(Canvas canvas, BirdCompanionEntry entry) {
        GraphicsContext g = canvas.getGraphicsContext2D();
        double w = canvas.getWidth();
        double h = canvas.getHeight();
        g.clearRect(0, 0, w, h);

        g.setFill(entry.accent.deriveColor(0, 1, 1, 0.18));
        g.fillRoundRect(4, 4, w - 8, h - 8, 16, 16);
        g.setStroke(entry.accent.deriveColor(0, 1, 1, 0.85));
        g.setLineWidth(2);
        g.strokeRoundRect(4, 4, w - 8, h - 8, 16, 16);

        if (entry.kind == BirdCompanionKind.CHICK) {
            g.setFill(Color.rgb(0, 0, 0, 0.2));
            g.fillOval(w * 0.22, h * 0.72, w * 0.48, h * 0.16);
            double scale = Math.min(w / 84.0, h / 62.0);
            g.save();
            g.translate(w * 0.14, h * 0.08);
            g.scale(scale, scale);
            ChickMinion chick = new ChickMinion(18, 18, entry.variant, entry.empowered, null);
            chick.x = 16;
            chick.y = 12;
            chick.vx = 2.0;
            chick.age = 18;
            drawChickMinion(g, chick);
            g.restore();
            return;
        }

        g.setFill(Color.rgb(0, 0, 0, 0.25));
        g.fillOval(w * 0.16, h * 0.7, w * 0.56, h * 0.16);
        CrowMinion crow = new CrowMinion(28, 22, null);
        crow.age = 18;
        int variant = entry.variant >= 0 ? entry.variant
                : (entry.empowered ? CrowMinion.VARIANT_MURDER_CROW : CrowMinion.VARIANT_ALLIED_CROW);
        crow.withVariant(variant);
        double scale = Math.min(w / 78.0, h / 58.0) / Math.max(1.0, crow.drawScale() * 2.0);
        g.save();
        g.translate(w * 0.5 - crow.x * scale, h * 0.5 - crow.y * scale);
        g.scale(scale, scale);
        drawCrowMinion(g, crow);
        g.restore();
    }






    private void drawPlayerTag(GraphicsContext g, Bird b) {
        String tag = "P" + (b.playerIndex + 1);
        Font font = Font.font("Arial Black", 20);
        Text text = new Text(tag);
        text.setFont(font);
        double textW = text.getLayoutBounds().getWidth();
        double textH = text.getLayoutBounds().getHeight();

        double drawSize = 80 * b.sizeMultiplier;
        double centerX = b.x + drawSize / 2.0;
        double boxW = textW + 14;
        double boxH = textH + 6;
        double boxX = centerX - boxW / 2.0;
        double boxY = b.y - boxH - 12;

        g.setFill(Color.BLACK.deriveColor(0, 1, 1, 0.6));
        g.fillRoundRect(boxX, boxY, boxW, boxH, 10, 10);
        g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.85));
        g.setLineWidth(1.4);
        g.strokeRoundRect(boxX, boxY, boxW, boxH, 10, 10);
        g.setFill(Color.WHITE);
        g.setFont(font);
        g.fillText(tag, centerX - textW / 2.0, boxY + boxH - 4);
    }

    private void drawPowerUpSprite(GraphicsContext g, PowerUp p, double offset) {
        drawPowerUpSprite(g, p, offset, 1.0);
    }

    private void drawPowerUpSprite(GraphicsContext g, PowerUp p, double offset, double visualScale) {
        double cx = p.x;
        double cy = p.y + offset;

        g.save();
        g.translate(cx, cy);
        g.scale(visualScale, visualScale);
        cx = 0.0;
        cy = 0.0;

        g.setFill(p.type.color.deriveColor(0, 1, 1, 0.22));
        g.fillOval(cx - 44, cy - 44, 88, 88);
        g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.8));
        g.setLineWidth(2.2);
        g.strokeOval(cx - 31, cy - 31, 62, 62);

        switch (p.type) {
            case HEALTH -> {
                g.setFill(Color.rgb(210, 20, 20));
                g.fillOval(cx - 22, cy - 22, 44, 44);
                g.setFill(Color.WHITE);
                g.fillRoundRect(cx - 6, cy - 16, 12, 32, 6, 6);
                g.fillRoundRect(cx - 16, cy - 6, 32, 12, 6, 6);
            }
            case SPEED -> {
                g.setFill(Color.CYAN.brighter());
                g.fillPolygon(new double[]{cx - 20, cx - 2, cx - 20}, new double[]{cy - 14, cy, cy + 14}, 3);
                g.fillPolygon(new double[]{cx - 2, cx + 16, cx - 2}, new double[]{cy - 14, cy, cy + 14}, 3);
                g.setStroke(Color.WHITE);
                g.setLineWidth(2);
                g.strokeLine(cx - 26, cy - 18, cx - 10, cy - 18);
                g.strokeLine(cx - 26, cy + 18, cx - 10, cy + 18);
            }
            case RAGE -> {
                g.setFill(Color.ORANGERED);
                g.fillPolygon(
                        new double[]{cx - 18, cx - 6, cx - 2, cx + 4, cx + 16, cx + 6, cx - 2},
                        new double[]{cy + 18, cy + 2, cy + 12, cy - 14, cy + 4, cy, cy + 18},
                        7
                );
                g.setStroke(Color.YELLOW);
                g.setLineWidth(2);
                g.strokeLine(cx - 14, cy + 18, cx + 12, cy - 8);
            }
            case SHRINK -> {
                g.setStroke(Color.MEDIUMPURPLE.brighter());
                g.setLineWidth(3);
                g.strokeOval(cx - 18, cy - 18, 36, 36);
                g.setFill(Color.MEDIUMPURPLE.brighter());
                g.fillPolygon(new double[]{cx - 24, cx - 12, cx - 12}, new double[]{cy, cy - 6, cy + 6}, 3);
                g.fillPolygon(new double[]{cx + 24, cx + 12, cx + 12}, new double[]{cy, cy - 6, cy + 6}, 3);
                g.fillPolygon(new double[]{cx, cx - 6, cx + 6}, new double[]{cy - 24, cy - 12, cy - 12}, 3);
                g.fillPolygon(new double[]{cx, cx - 6, cx + 6}, new double[]{cy + 24, cy + 12, cy + 12}, 3);
            }
            case NEON -> {
                g.setStroke(Color.MAGENTA.brighter());
                g.setLineWidth(3);
                for (int i = 0; i < 6; i++) {
                    double a = i * Math.PI / 3;
                    g.strokeLine(cx, cy, cx + Math.cos(a) * 22, cy + Math.sin(a) * 22);
                }
                g.setFill(Color.CYAN.brighter());
                g.fillOval(cx - 8, cy - 8, 16, 16);
            }
            case THERMAL -> {
                g.setFill(Color.GOLD);
                g.fillPolygon(new double[]{cx - 14, cx, cx + 14}, new double[]{cy + 6, cy - 16, cy + 6}, 3);
                g.fillPolygon(new double[]{cx - 10, cx, cx + 10}, new double[]{cy + 18, cy, cy + 18}, 3);
                g.setStroke(Color.WHITE);
                g.setLineWidth(2);
                g.strokeLine(cx, cy + 20, cx, cy - 22);
            }
            case VINE_GRAPPLE -> {
                g.setStroke(Color.LIMEGREEN.brighter());
                g.setLineWidth(4);
                g.strokeOval(cx - 15, cy - 15, 30, 30);
                g.strokeLine(cx + 10, cy + 10, cx + 22, cy + 22);
                g.setFill(Color.FORESTGREEN);
                g.fillOval(cx + 18, cy + 20, 10, 10);
            }
            case OVERCHARGE -> {
                g.setFill(Color.DEEPSKYBLUE.brighter());
                g.fillPolygon(
                        new double[]{cx - 10, cx + 2, cx - 2, cx + 12, cx, cx + 4},
                        new double[]{cy - 18, cy - 3, cy - 3, cy + 18, cy + 4, cy + 4},
                        6
                );
                g.setStroke(Color.WHITE);
                g.setLineWidth(2);
                g.strokeLine(cx - 20, cy - 14, cx - 10, cy - 14);
                g.strokeLine(cx + 12, cy + 14, cx + 22, cy + 14);
            }
            case TITAN -> {
                g.setFill(Color.DARKGOLDENROD);
                g.fillRoundRect(cx - 16, cy - 20, 32, 40, 10, 10);
                g.setStroke(Color.GOLD.brighter());
                g.setLineWidth(2.6);
                g.strokeRoundRect(cx - 16, cy - 20, 32, 40, 10, 10);
                g.setFill(Color.WHITE);
                g.fillPolygon(new double[]{cx - 3, cx + 3, cx + 3, cx + 8, cx, cx - 8, cx - 3},
                        new double[]{cy - 14, cy - 14, cy - 2, cy - 2, cy + 12, cy -2, cy -2}, 7);
            }
            case BROADSIDE -> {
                g.setFill(Color.web("#5D4037"));
                g.fillRoundRect(cx - 18, cy - 10, 26, 20, 8, 8);
                g.setStroke(Color.web("#D7CCC8"));
                g.setLineWidth(2.4);
                g.strokeRoundRect(cx - 18, cy - 10, 26, 20, 8, 8);
                g.setStroke(Color.web("#FFCC80"));
                g.setLineWidth(3);
                g.strokeLine(cx + 8, cy, cx + 22, cy);
                g.strokeLine(cx + 12, cy - 10, cx + 22, cy - 16);
                g.strokeLine(cx + 12, cy + 10, cx + 22, cy + 16);
                g.setFill(Color.web("#8D6E63"));
                g.fillOval(cx - 22, cy - 5, 12, 10);
            }
        }
        g.restore();
    }

    private void appendStartLog(String msg) {
        try {
            File out = new File(System.getProperty("user.home"), "Desktop\\birdgame3-start-log.txt");
            try (PrintStream ps = new PrintStream(new FileOutputStream(out, true))) {
                ps.println(LocalDateTime.now() + " - " + msg);
            }
        } catch (Exception ignore) {
        }
    }

    private static boolean officialTrailerMode() {
        return Boolean.getBoolean("birdfight3.officialTrailer")
                || "1".equals(System.getenv("BIRDFIGHT3_OFFICIAL_TRAILER"));
    }

    private static String officialTrailerExportPath() {
        String property = System.getProperty("birdfight3.officialTrailerExport", "").trim();
        if (!property.isBlank()) {
            return property;
        }
        String environment = System.getenv("BIRDFIGHT3_OFFICIAL_TRAILER_EXPORT");
        return environment == null ? "" : environment.trim();
    }

    private static boolean officialTrailerExportMode() {
        return !officialTrailerExportPath().isBlank();
    }

    private double officialTrailerExportDuration(double fullDuration) {
        String configured = System.getenv("BIRDFIGHT3_TRAILER_EXPORT_SECONDS");
        if (configured == null || configured.isBlank()) {
            return fullDuration;
        }
        try {
            return Math.clamp(Double.parseDouble(configured.trim()), 0.5, fullDuration);
        } catch (NumberFormatException ignored) {
            return fullDuration;
        }
    }

    public void start(Stage stage) {
        try {
            boolean officialTrailerExport = officialTrailerExportMode();
            boolean officialTrailer = officialTrailerMode() || officialTrailerExport;
            appendStartLog("enter start");
            String statsSummary = BirdStats.reloadFromDisk();
            if (statsSummary != null) {
                LOGGER.info(statsSummary);
            }
            String spriteSummary = BirdSpriteLibrary.reload();
            if (spriteSummary != null) {
                LOGGER.info(spriteSummary);
            }
            appendStartLog("loaded bird stats");
            currentStage = stage;
            appendStartLog("set currentStage");
            if (officialTrailerExport) {
                stage.setTitle("Bird Fight 3 - Background Trailer Export");
                showOfficialTrailer(stage);
                return;
            }
            // Ensure the JVM exits immediately when the window is closed from OS window controls
            stage.setOnCloseRequest(evt -> {
                appendStartLog("stage close requested");
                shutdownAndExit();
            });
            appendStartLog("set onCloseRequest");
            stage.setTitle(officialTrailer
                    ? "Bird Fight 3 - Official Trailer"
                    : "Bird Fight 3 - Power-Up Chaos!");
            appendStartLog("set title");
            stage.setResizable(true);
            stage.centerOnScreen();
            stage.setFullScreenExitKeyCombination(KeyCombination.NO_MATCH);
            stage.setFullScreenExitHint("");
            appendStartLog("before scheduling input init");
            // Initialize native input managers on a background thread to avoid blocking/crashing the JavaFX thread.
            Thread inputInitThread = getThread();
            inputInitThread.start();
            appendStartLog("scheduled input init");
            saveRepository.createBackup("Automatic backup before startup");
            loadAchievements();
            appendStartLog("loadAchievements done");
            fullscreenEnabled = true;
            syncWiimoteModesToManager();
            appendStartLog("synced wiimote modes");
            loadSounds();
            appendStartLog("loadSounds done");
            startWiimoteMenuTimer();
            appendStartLog("before showMenu");
            showMenu(stage);
            appendStartLog("after showMenu");
            prepareStageForInitialShow(stage);
            appendStartLog("prepared initial stage size");
            appendStartLog("before stage.show");
            stage.show();
            appendStartLog("after stage.show");
            javafx.application.Platform.runLater(() -> {
                applyDisplaySettings(stage);
                if (officialTrailer) {
                    showOfficialTrailer(stage);
                } else {
                    maybeShowLatestUpdateSplash(stage);
                }
            });
            appendStartLog("scheduled applyDisplaySettings");
            tryShowQueuedAchievementToast();
            if (!officialTrailer) {
                DesktopShortcutSupport.ensureDesktopShortcutAsync();
                GameUpdater.checkForUpdatesAsync();
            }
            appendStartLog("end start");
        } catch (Throwable t) {
            ThrowableLogSupport.log(LOGGER, Level.SEVERE, "Application startup failed", t);
            ThrowableLogSupport.writeReport(
                    java.nio.file.Path.of(System.getProperty("user.home"), "birdgame3-start-error.txt"),
                    false,
                    "Application startup failure",
                    t
            );
            // Re-throw so JavaFX still reports the error as before.
            throw t;
        }
    }

    private Thread getThread() {
        Thread inputInitThread = new Thread(() -> {
            appendStartLog("input init thread start");
            try {
                WiimoteInputManager w = null;
                try {
                    w = new WiimoteInputManager();
                    appendStartLog("wiimote init OK");
                } catch (Throwable t) {
                    appendStartLog("wiimote init failed: " + t);
                    ThrowableLogSupport.log(LOGGER, Level.WARNING, "WiimoteInputManager failed", t);
                    ThrowableLogSupport.writeReport(
                            java.nio.file.Path.of(System.getProperty("user.home"), "Desktop", "birdgame3-uncaught.txt"),
                            true,
                            "WiimoteInputManager init failure",
                            t
                    );
                }
                synchronized (inputManagerLock) {
                    if (!shuttingDown) {
                        wiimoteInputManager = w;
                        w = null;
                    }
                }
                try { if (w != null) w.close(); } catch (Throwable ignore) {}

                XboxInputManager x = null;
                try {
                    x = new XboxInputManager();
                    appendStartLog("xbox init OK");
                } catch (Throwable t) {
                    appendStartLog("xbox init failed: " + t);
                    ThrowableLogSupport.log(LOGGER, Level.WARNING, "XboxInputManager failed", t);
                    ThrowableLogSupport.writeReport(
                            java.nio.file.Path.of(System.getProperty("user.home"), "Desktop", "birdgame3-uncaught.txt"),
                            true,
                            "XboxInputManager init failure",
                            t
                    );
                }
                synchronized (inputManagerLock) {
                    if (!shuttingDown) {
                        xboxInputManager = x;
                        x = null;
                    }
                }
                try { if (x != null) x.close(); } catch (Throwable ignore) {}
            } catch (Throwable t) {
                appendStartLog("input init thread top-level failure: " + t);
                ThrowableLogSupport.log(LOGGER, Level.SEVERE, "Input init thread failed", t);
            } finally {
                appendStartLog("input init thread end");
            }
        }, "InputInit");
        inputInitThread.setDaemon(true);
        return inputInitThread;
    }

    private void showMenu(Stage stage) {
        campaignModeActive = false;
        currentCampaignMission = null;
        campaignMissionController = null;
        campaignTeamMode = false;
        Arrays.fill(campaignTeams, 1);
        storyModeActive = false;
        storyReplayMode = false;
        adventureModeActive = false;
        adventureReplayMode = false;
        currentAdventureBattle = null;
        adventureTeamMode = false;
        Arrays.fill(adventureTeams, 1);
        classicModeActive = false;
        classicEncounter = null;
        classicRun.clear();
        classicRoundIndex = 0;
        classicTeamMode = false;
        Arrays.fill(classicTeams, 1);
        clearBossRushState();
        clearAshfallTrialState();
        clearActiveDailyChallengeRun();
        resetTournamentRun();
        competitionSeriesActive = false;
        Arrays.fill(competitionRoundWins, 0);
        Arrays.fill(competitionTeamWins, 0);
        competitionRoundNumber = 1;
        trainingModeActive = false;
        stageSelectHandler = null;
        disposeGameplayMusicPlayer();
        victoryMusicPlayer = stopMediaPlayer(victoryMusicPlayer, false);
        defeatMusicPlayer = stopMediaPlayer(defeatMusicPlayer, false);
        playMenuMusic();
        showHub(stage);
    }

    private void drawRosterSprite(Canvas canvas, BirdType type, String skinKey, boolean randomPick) {
        drawRosterSprite(canvas, type, skinKey, randomPick, false);
    }

    Bird createCampaignCutsceneBird(BirdType type, String skinKey) {
        Bird preview = new Bird(0, type, 0, this);
        // Keep the exact gameplay body/skin renderer, but do not let combat-only
        // state (airborne rotations, cooldown HUD, auras) leak into cinematics.
        preview.suppressSelectEffects = true;
        applyPreviewSkinChoiceToBird(preview, type, skinKey);
        return preview;
    }

    double campaignCutsceneActorSkinScale(Bird actor) {
        if (actor == null || actor.type == null) return 1.0;
        String skinKey = skinKeyForBird(actor);
        double baseExtent = rosterSpriteExtentFactor(actor.type, null);
        double skinExtent = rosterSpriteExtentFactor(actor.type, skinKey);
        return Math.clamp(baseExtent / Math.max(0.01, skinExtent), 0.42, 1.18);
    }

    Bird createCampaignEscapeBird(String skinKey) {
        Bird playable = new Bird(0, BirdType.PIGEON, 0, this);
        applyPreviewSkinChoiceToBird(playable, BirdType.PIGEON, skinKey);
        playable.suppressSelectEffects = false;
        playable.name = "Pigeon";
        return playable;
    }

    void beginCampaignCaveEscapePhysics(Bird playable, DoubleUnaryOperator floorProvider,
                                        double worldLength, double bottomY) {
        if (!campaignCaveEscapePhysicsActive) {
            campaignEscapeSavedPlayers = players.clone();
            campaignEscapeSavedAi = isAI.clone();
            campaignEscapeSavedActivePlayers = activePlayers;
            campaignEscapeSavedMap = selectedMap;
            campaignEscapeSavedPlatforms = platforms;
            campaignEscapeSavedPowerUps = powerUps;
            campaignEscapeSavedNectarNodes = nectarNodes;
            campaignEscapeSavedVines = swingingVines;
        }
        campaignCaveEscapePhysicsActive = true;
        campaignEscapeFloorProvider = Objects.requireNonNull(floorProvider, "floorProvider");
        campaignEscapeWorldLength = Math.max(WIDTH, worldLength);
        campaignEscapeBottomY = Math.max(HEIGHT, bottomY);
        selectedMap = MapType.CAVE;
        activePlayers = 1;
        Arrays.fill(players, null);
        Arrays.fill(isAI, false);
        players[0] = Objects.requireNonNull(playable, "playable");
        platforms = new ArrayList<>();
        powerUps = new ArrayList<>();
        nectarNodes = new ArrayList<>();
        swingingVines = new ArrayList<>();
        particles.clear();
        clearCampaignSequenceActions();
    }

    void endCampaignCaveEscapePhysics() {
        if (!campaignCaveEscapePhysicsActive) return;
        clearCampaignSequenceActions();
        particles.clear();
        if (campaignEscapeSavedPlayers != null) {
            System.arraycopy(campaignEscapeSavedPlayers, 0, players, 0,
                    Math.min(players.length, campaignEscapeSavedPlayers.length));
        }
        if (campaignEscapeSavedAi != null) {
            System.arraycopy(campaignEscapeSavedAi, 0, isAI, 0,
                    Math.min(isAI.length, campaignEscapeSavedAi.length));
        }
        activePlayers = campaignEscapeSavedActivePlayers;
        if (campaignEscapeSavedMap != null) selectedMap = campaignEscapeSavedMap;
        if (campaignEscapeSavedPlatforms != null) platforms = campaignEscapeSavedPlatforms;
        if (campaignEscapeSavedPowerUps != null) powerUps = campaignEscapeSavedPowerUps;
        if (campaignEscapeSavedNectarNodes != null) nectarNodes = campaignEscapeSavedNectarNodes;
        if (campaignEscapeSavedVines != null) swingingVines = campaignEscapeSavedVines;
        campaignCaveEscapePhysicsActive = false;
        campaignEscapeFloorProvider = null;
        campaignEscapeSavedPlayers = null;
        campaignEscapeSavedAi = null;
        campaignEscapeSavedMap = null;
        campaignEscapeSavedPlatforms = null;
        campaignEscapeSavedPowerUps = null;
        campaignEscapeSavedNectarNodes = null;
        campaignEscapeSavedVines = null;
    }

    boolean isCampaignCaveEscapePhysicsActiveFor(Bird bird) {
        return campaignCaveEscapePhysicsActive && bird != null && players[0] == bird;
    }

    double campaignCaveEscapeFloorAt(double worldX) {
        if (!campaignCaveEscapePhysicsActive || campaignEscapeFloorProvider == null) {
            return Double.NaN;
        }
        return campaignEscapeFloorProvider.applyAsDouble(worldX);
    }

    double campaignCaveEscapeWorldLength() {
        return campaignEscapeWorldLength;
    }

    double campaignCaveEscapeBottomY() {
        return campaignEscapeBottomY;
    }

    void setCampaignSequenceActions(boolean left, boolean right, boolean jump,
                                    boolean attack, boolean special, boolean grab, boolean block,
                                    boolean attackUp, boolean attackDown) {
        if (!campaignCaveEscapePhysicsActive) return;
        campaignSequenceActionPressed[ControlAction.LEFT.ordinal()] = left;
        campaignSequenceActionPressed[ControlAction.RIGHT.ordinal()] = right;
        campaignSequenceActionPressed[ControlAction.JUMP.ordinal()] = jump;
        campaignSequenceActionPressed[ControlAction.ATTACK.ordinal()] = attack;
        campaignSequenceActionPressed[ControlAction.SPECIAL.ordinal()] = special;
        campaignSequenceActionPressed[ControlAction.GRAB.ordinal()] = grab;
        campaignSequenceActionPressed[ControlAction.BLOCK.ordinal()] = block;
        campaignSequenceAttackUpHeld = attackUp;
        campaignSequenceAttackDownHeld = attackDown;
    }

    private void clearCampaignSequenceActions() {
        Arrays.fill(campaignSequenceActionPressed, false);
        campaignSequenceAttackUpHeld = false;
        campaignSequenceAttackDownHeld = false;
    }

    void updateCampaignSequenceParticles() {
        if (!particleEffectsEnabled) {
            particles.clear();
            return;
        }
        for (Iterator<Particle> iterator = particles.iterator(); iterator.hasNext(); ) {
            Particle particle = iterator.next();
            if (particle == null || particle.color == null) {
                iterator.remove();
                continue;
            }
            particle.x += particle.vx;
            particle.y += particle.vy;
            particle.vy += 0.4;
            particle.life--;
            if (particle.life <= 0
                    || particle.y > campaignEscapeBottomY + 300.0
                    || particle.y < -500.0
                    || particle.x < -500.0
                    || particle.x > campaignEscapeWorldLength + 500.0) {
                iterator.remove();
            }
        }
    }

    void drawCampaignSequenceParticles(GraphicsContext graphics, double cameraX) {
        if (!particleEffectsEnabled || graphics == null) return;
        for (Particle particle : particles) {
            if (particle == null || particle.color == null || particle.life <= 0) continue;
            double screenX = particle.x - cameraX;
            if (screenX < -40.0 || screenX > WIDTH + 40.0) continue;
            graphics.setFill(particle.color.deriveColor(0, 1, 1,
                    Math.clamp(particle.life / 60.0, 0.0, 1.0)));
            graphics.fillOval(screenX - 4.0, particle.y - 4.0, 8.0, 8.0);
        }
    }

    void prepareCampaignCutsceneScene(Scene scene, Region frame, Region content) {
        setupKeyboardNavigation(scene);
        applyConsoleHighlight(scene);
        Runnable applyScale = () -> {
            double frameWidth = frame.getWidth() > 1.0
                    ? frame.getWidth()
                    : initialLayoutSceneWidth(scene);
            double frameHeight = frame.getHeight() > 1.0
                    ? frame.getHeight()
                    : initialLayoutSceneHeight(scene);
            double scale = Math.min(frameWidth / WIDTH, frameHeight / HEIGHT);
            content.setScaleX(Math.max(0.01, scale));
            content.setScaleY(Math.max(0.01, scale));
        };
        frame.widthProperty().addListener((obs, oldValue, newValue) -> applyScale.run());
        frame.heightProperty().addListener((obs, oldValue, newValue) -> applyScale.run());
        applyScale.run();
        javafx.application.Platform.runLater(applyScale);
    }

    void prepareCampaignPlayableSequenceScene(Scene scene, Region frame, Region content) {
        if (scene != null) {
            scene.getProperties().put(SCENE_PROP_CAMPAIGN_PLAYABLE_SEQUENCE, true);
        }
        prepareCampaignCutsceneScene(scene, frame, content);
    }

    private boolean isCampaignPlayableSequence(Scene scene) {
        Scene active = activeSceneFor(scene);
        return active != null
                && Boolean.TRUE.equals(active.getProperties().get(SCENE_PROP_CAMPAIGN_PLAYABLE_SEQUENCE));
    }

    <T extends Event> void addCampaignSceneEventFilter(
            Scene scene, EventType<T> eventType, EventHandler<? super T> handler) {
        addSceneEventFilter(scene, eventType, handler);
    }

