        double gridY = 18;
        double gridW = paneW - gridX - 18;
        double gridH = paneH - gridY * 2;
        double cellW = gridW / columns;
        double cellH = gridH / Math.max(1, rows);

        Region gridFrame = new Region();
        gridFrame.setLayoutX(gridX - 12);
        gridFrame.setLayoutY(gridY - 12);
