            removePlayerBtn.setStyle("-fx-background-color: #455A64; -fx-text-fill: white; "
                    + "-fx-font-family: 'Arial Black'; -fx-font-size: 14px; -fx-font-weight: bold; "
                    + "-fx-background-radius: 14; -fx-border-color: black; -fx-border-width: 2.5; "
                    + "-fx-border-radius: 14;");
