    private void resetTournamentRun() {
        tournamentModeActive = false;
        tournamentRounds.clear();
        tournamentSeedOrder.clear();
        currentTournamentMatch = null;
        tournamentSlotA = null;
        tournamentSlotB = null;
        tournamentMatchResolved = false;
        for (TournamentEntry entry : tournamentEntries) {
            if (entry != null) {
                entry.resolvedType = null;
            }
        }
    }

    private void ensureTournamentEntries() {
        tournamentEntrantCount = Math.clamp(tournamentEntrantCount, 2, 32);
        tournamentHumanCount = Math.clamp(tournamentHumanCount, 0, tournamentEntrantCount);
        int current = tournamentEntries.size();
        if (current < tournamentEntrantCount) {
            for (int i = current; i < tournamentEntrantCount; i++) {
                tournamentEntries.add(new TournamentEntry(i + 1));
            }
        } else if (current > tournamentEntrantCount) {
            while (tournamentEntries.size() > tournamentEntrantCount) {
                tournamentEntries.removeLast();
            }
        }
    }

    List<TournamentEntry> tournamentEntries() {
        return tournamentEntries;
    }

    int tournamentEntrantCount() {
        return tournamentEntrantCount;
    }

    void setTournamentEntrantCount(int entrantCount) {
        tournamentEntrantCount = Math.clamp(entrantCount, 2, 32);
        tournamentHumanCount = Math.clamp(tournamentHumanCount, 0, tournamentEntrantCount);
    }

    int tournamentHumanCount() {
        return tournamentHumanCount;
    }

    void setTournamentHumanCount(int humanCount) {
        tournamentHumanCount = Math.clamp(humanCount, 0, tournamentEntrantCount);
    }

    boolean isTournamentMapRandom() {
        return tournamentMapRandom;
    }

    void setTournamentMapRandom(boolean tournamentMapRandom) {
        this.tournamentMapRandom = tournamentMapRandom;
    }

    MapType tournamentFixedMap() {
        List<MapType> maps = tournamentMapPool();
        if (!maps.contains(tournamentFixedMap)) {
            tournamentFixedMap = maps.getFirst();
        }
        return tournamentFixedMap;
    }

    void setTournamentFixedMap(MapType map) {
        if (map == null) {
            return;
        }
        List<MapType> maps = tournamentMapPool();
        tournamentFixedMap = maps.contains(map) ? map : maps.getFirst();
    }

    List<List<TournamentMatch>> tournamentRounds() {
        return tournamentRounds;
    }

    void syncTournamentEntries() {
        ensureTournamentEntries();
        for (int i = 0; i < tournamentEntries.size(); i++) {
            TournamentEntry entry = tournamentEntries.get(i);
            entry.human = i < tournamentHumanCount;
            if (entry.selectedType != null && !isBirdUnlocked(entry.selectedType)) {
                entry.selectedType = null;
                entry.resolvedType = null;
            }
            if (entry.resolvedType != null && !isBirdUnlocked(entry.resolvedType)) {
                entry.resolvedType = null;
            }
            BirdType skinType = entry.selectedType != null ? entry.selectedType : entry.resolvedType;
            entry.selectedSkinKey = normalizeAdventureSkinChoice(skinType, entry.selectedSkinKey);
            entry.customName = normalizeTournamentEntryName(entry.customName);
            entry.cpuLevel = Math.clamp(entry.cpuLevel, 1, 9);
        }
        ensureTournamentSeedOrder();
    }

    private void ensureTournamentSeedOrder() {
        tournamentSeedOrder.removeIf(entry -> !tournamentEntries.contains(entry));
        for (TournamentEntry entry : tournamentEntries) {
            if (!tournamentSeedOrder.contains(entry)) {
                tournamentSeedOrder.add(entry);
            }
        }
    }

    void shuffleTournamentSeedOrder() {
        ensureTournamentSeedOrder();
        Collections.shuffle(tournamentSeedOrder, random);
    }

    int tournamentEntrySeedNumber(TournamentEntry entry) {
        if (entry == null) {
            return 0;
        }
        int seededIndex = tournamentSeedOrder.indexOf(entry);
        if (seededIndex >= 0) {
            return seededIndex + 1;
        }
        int fallbackIndex = tournamentEntries.indexOf(entry);
        return fallbackIndex >= 0 ? fallbackIndex + 1 : entry.id;
    }

    private String normalizeTournamentEntryName(String requestedName) {
        if (requestedName == null) {
            return "";
        }
        String trimmed = requestedName.trim();
        if (trimmed.isEmpty()) {
            return "";
        }
        String shortened = trimmed.length() > 32 ? trimmed.substring(0, 32).trim() : trimmed;
        return shortened.isEmpty() ? "" : shortened;
    }

    String tournamentEntryLabel(TournamentEntry entry) {
        if (entry == null) return "PLAYER";
        if (entry.customName != null && !entry.customName.isBlank()) {
            return entry.customName;
        }
        return "PLAYER " + entry.id;
    }

    Color tournamentEntryAccent(int index, boolean human) {
        Color[] palette = human
                ? new Color[]{
                Color.web("#F44336"),
                Color.web("#42A5F5"),
                Color.web("#FDD835"),
                Color.web("#66BB6A"),
                Color.web("#FF8A65"),
                Color.web("#AB47BC")
        }
                : new Color[]{
                Color.web("#8D6E63"),
                Color.web("#78909C"),
                Color.web("#9575CD"),
                Color.web("#4DB6AC"),
                Color.web("#A1887F"),
                Color.web("#90A4AE")
        };
        return palette[Math.floorMod(index, palette.length)];
    }

    private String tournamentEntrySeedLabel(TournamentEntry entry) {
        if (entry == null) {
            return "";
        }
        return "SEED " + tournamentEntrySeedNumber(entry);
    }

    void setTournamentEntrySelection(TournamentEntry entry, BirdType type) {
        if (entry == null) {
            return;
        }
        entry.selectedType = type;
        entry.resolvedType = null;
        entry.selectedSkinKey = normalizeAdventureSkinChoice(type, entry.selectedSkinKey);
    }

    String tournamentEntrySkinKey(TournamentEntry entry, BirdType type) {
        if (entry == null || type == null) {
            return null;
        }
        String normalized = normalizeAdventureSkinChoice(type, entry.selectedSkinKey);
        entry.selectedSkinKey = normalized;
        return normalized;
    }

    String tournamentEntrySkinLabel(TournamentEntry entry, BirdType type) {
        return adventureSkinLabel(type, tournamentEntrySkinKey(entry, type));
    }

    boolean tournamentEntryCanCycleSkin(TournamentEntry entry) {
        if (entry == null || entry.selectedType == null) {
            return false;
        }
        return adventureSkinOptions(entry.selectedType).size() > 1;
    }

    void cycleTournamentEntrySkin(TournamentEntry entry) {
        if (entry == null || entry.selectedType == null) {
            return;
        }
        List<String> options = adventureSkinOptions(entry.selectedType);
        if (options.size() <= 1) {
            entry.selectedSkinKey = null;
            return;
        }
        String current = normalizeAdventureSkinChoice(entry.selectedType, entry.selectedSkinKey);
        int index = options.indexOf(current);
        if (index < 0) {
            index = 0;
        }
        entry.selectedSkinKey = options.get((index + 1) % options.size());
    }

    int tournamentEntryCpuLevel(TournamentEntry entry) {
        if (entry == null) {
            return 5;
        }
        entry.cpuLevel = Math.clamp(entry.cpuLevel, 1, 9);
        return entry.cpuLevel;
    }

    void cycleTournamentEntryCpuLevel(TournamentEntry entry) {
        if (entry == null) {
            return;
        }
        entry.cpuLevel = tournamentEntryCpuLevel(entry) % 9 + 1;
    }

    BirdType tournamentAssignedBird(TournamentEntry entry) {
        if (entry == null) {
            return null;
        }
        BirdType direct = entry.selectedType;
        if (direct != null && isBirdUnlocked(direct)) {
            return direct;
        }
        if (entry.resolvedType != null && isBirdUnlocked(entry.resolvedType)) {
            return entry.resolvedType;
        }
        return null;
    }

    private BirdType resolveTournamentEntryBird(TournamentEntry entry) {
        if (entry == null) {
            return null;
        }
        BirdType direct = entry.selectedType;
        if (direct != null && isBirdUnlocked(direct)) {
            entry.resolvedType = direct;
            return direct;
        }
        if (entry.resolvedType != null && isBirdUnlocked(entry.resolvedType)) {
            return entry.resolvedType;
        }
        List<BirdType> pool = unlockedBirdPool();
        BirdType resolved = pool.isEmpty() ? firstUnlockedBird() : pool.get(random.nextInt(pool.size()));
        entry.resolvedType = resolved;
        return resolved;
    }

    private void resolveTournamentEntryBirds() {
        for (TournamentEntry entry : tournamentEntries) {
            resolveTournamentEntryBird(entry);
        }
    }

    String tournamentBirdLabel(TournamentEntry entry, boolean revealResolvedRandom) {
        if (entry == null) {
            return "TBD";
        }
        if (entry.selectedType != null) {
            return entry.selectedType.name.toUpperCase(Locale.ROOT);
        }
        if (revealResolvedRandom && entry.resolvedType != null) {
            return "RANDOM -> " + entry.resolvedType.name.toUpperCase(Locale.ROOT);
        }
        return "RANDOM";
    }

    private String tournamentBracketBirdLabel(BirdType birdType, String skinKey) {
        if (birdType == null) {
            return "TBD";
        }
        if (skinKey == null) {
            return birdType.name.toUpperCase(Locale.ROOT);
        }
        String label = adventureSkinLabel(birdType, skinKey);
        if (label.startsWith("SKIN: ")) {
            label = label.substring("SKIN: ".length());
        }
        return label.toUpperCase(Locale.ROOT);
    }

    private void renameTournamentEntryPrompt(Stage stage, TournamentEntry entry, Runnable onComplete) {
        if (entry == null) {
            if (onComplete != null) {
                onComplete.run();
            }
            return;
        }
        String defaultName = entry.customName == null || entry.customName.isBlank()
                ? "PLAYER " + entry.id
                : entry.customName;
        TextInputDialog dialog = new TextInputDialog(defaultName);
        dialog.setTitle("Rename Tournament Entrant");
        dialog.setHeaderText("Rename this tournament entrant.");
        dialog.setContentText("Entrant name:");
        dialog.initOwner(stage);
        dialog.showAndWait().ifPresent(name -> {
            entry.customName = normalizeTournamentEntryName(name);
            if (onComplete != null) {
                onComplete.run();
            }
        });
    }

