    private String findLanAddress() {
        try {
            Enumeration<NetworkInterface> interfaces = NetworkInterface.getNetworkInterfaces();
            InetAddress bestSiteLocal = null;
            int bestSiteLocalScore = Integer.MIN_VALUE;
            InetAddress bestFallback = null;
            int bestFallbackScore = Integer.MIN_VALUE;

            while (interfaces.hasMoreElements()) {
                NetworkInterface iface = interfaces.nextElement();
                if (!iface.isUp() || iface.isLoopback()) continue;
                int score = networkInterfacePriority(iface);
                Enumeration<InetAddress> addrs = iface.getInetAddresses();
                while (addrs.hasMoreElements()) {
                    InetAddress addr = addrs.nextElement();
                    if (!(addr instanceof Inet4Address) || addr.isLoopbackAddress()) continue;
                    if (addr.isSiteLocalAddress() && score > bestSiteLocalScore) {
                        bestSiteLocal = addr;
                        bestSiteLocalScore = score;
                    }
                    if (score > bestFallbackScore) {
                        bestFallback = addr;
                        bestFallbackScore = score;
                    }
                }
            }

            if (bestSiteLocal != null) {
                return bestSiteLocal.getHostAddress();
            }
            if (bestFallback != null) {
                return bestFallback.getHostAddress();
            }
        } catch (SocketException ignored) {
        }
        return "127.0.0.1";
    }

    private int networkInterfacePriority(NetworkInterface iface) {
        if (iface == null) return Integer.MIN_VALUE;
        int score = 0;
        try {
            if (iface.isVirtual()) {
                score -= 1000;
            }
            if (iface.supportsMulticast()) {
                score += 50;
            }
            if (iface.isPointToPoint()) {
                score -= 300;
            }
        } catch (SocketException ignored) {
        }

        String name = (iface.getName() == null ? "" : iface.getName()).toLowerCase(Locale.ROOT);
        String displayName = (iface.getDisplayName() == null ? "" : iface.getDisplayName()).toLowerCase(Locale.ROOT);
        String combined = name + " " + displayName;

        if (combined.contains("ethernet") || combined.startsWith("eth")) {
            score += 300;
        }
        if (combined.contains("wi-fi") || combined.contains("wifi") || combined.contains("wireless") || combined.contains("wlan")) {
            score += 280;
        }
        if (combined.contains("realtek") || combined.contains("intel")) {
            score += 80;
        }
        if (combined.contains("virtualbox")
                || combined.contains("vmware")
                || combined.contains("hyper-v")
                || combined.contains("vethernet")
                || combined.contains("wsl")
                || combined.contains("docker")
                || combined.contains("podman")
                || combined.contains("bridge")
                || combined.contains("host-only")
                || combined.contains("tunnel")
                || combined.contains("tap")
                || combined.contains("tun")
                || combined.contains("loopback")) {
            score -= 900;
        }
        if (combined.contains("hamachi") || combined.contains("zerotier") || combined.contains("tailscale")) {
            score -= 250;
        }
        return score;
    }

    private void broadcastLanLobby() {
        if (!lanIsHost) return;
        updateLanMapSelectionFromVotes();
        if (lanHost != null) {
            MapType mapToSend = lanSelectedMap != null ? lanSelectedMap : MapType.FOREST;
            boolean mapRandom = lanSelectedMap == null || lanSelectedMapRandom;
            lanHost.broadcastLobby(mapToSend, lanSelectedMapVariant, mapRandom,
                    lanSlotConnected, lanSelectedBirds, lanRandomBirds, lanSelectedSkinKeys, lanReady);
        }
        publishLanCompanionSnapshot();
    }

    void onLanClientConnected(int slot) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            if (slot < 0 || slot >= LAN_MAX_PLAYERS) return;
            lanSlotConnected[slot] = true;
            lanRandomBirds[slot] = false;
            lanSelectedSkinKeys[slot] = null;
            lanReady[slot] = false;
            lanMapVotes[slot] = null;
            lanMapVariantVotes[slot] = MapVariant.STANDARD;
            lanMapVoteRandomPools[slot] = StageRandomPool.NONE;
            if (lanSelectedBirds[slot] == null) {
                lanSelectedBirds[slot] = firstUnlockedBird();
            }
            synchronized (lanInputLock) {
                lanInputMasks[slot] = 0;
                lanLastInputMasks[slot] = 0;
            }
            updateLanMapSelectionFromVotes();
            refreshLanLobbyUI();
            broadcastLanLobby();
        });
    }

    void onLanClientDisconnected(int slot) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            if (slot < 0 || slot >= LAN_MAX_PLAYERS) return;
            LockstepSession session = lockstepSession;
            if (session != null && lanHost != null) {
                // Complete any bundles that were only waiting on this client so
                // the remaining machines don't stall forever.
                for (long tick : session.slotDisconnected(slot)) {
                    int[] bundle = session.bundleFor(tick);
                    if (bundle != null) {
                        lanHost.broadcastLockstepBundle(tick, bundle);
                    }
                }
            }
            lanSlotConnected[slot] = false;
            lanSelectedBirds[slot] = null;
            lanRandomBirds[slot] = false;
            lanSelectedSkinKeys[slot] = null;
            lanReady[slot] = false;
            lanMapVotes[slot] = null;
            lanMapVariantVotes[slot] = MapVariant.STANDARD;
            lanMapVoteRandomPools[slot] = StageRandomPool.NONE;
            synchronized (lanInputLock) {
                lanInputMasks[slot] = 0;
                lanLastInputMasks[slot] = 0;
            }
            updateLanMapSelectionFromVotes();
            refreshLanLobbyUI();
            broadcastLanLobby();
        });
    }

    void onLanClientSelected(int slot, BirdType type, boolean random, String skinKey) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            if (slot < 0 || slot >= LAN_MAX_PLAYERS) return;
            lanRandomBirds[slot] = random;
            lanSelectedBirds[slot] = random ? null : type;
            lanSelectedSkinKeys[slot] = random ? null : skinKey;
            refreshLanLobbyUI();
            broadcastLanLobby();
        });
    }

    void onLanClientMapVote(int slot, MapType map, MapVariant variant, StageRandomPool randomPool) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            if (slot < 0 || slot >= LAN_MAX_PLAYERS) return;
            StageRandomPool resolvedPool = randomPool == null ? StageRandomPool.NONE : randomPool;
            lanMapVoteRandomPools[slot] = resolvedPool;
            lanMapVotes[slot] = resolvedPool == StageRandomPool.NONE ? map : null;
            lanMapVariantVotes[slot] = resolvedPool == StageRandomPool.NONE && variant != null
                    ? variant
                    : MapVariant.STANDARD;
            updateLanMapSelectionFromVotes();
            refreshLanLobbyUI();
            broadcastLanLobby();
        });
    }

    void onLanClientReady(int slot, boolean ready) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            if (slot < 0 || slot >= LAN_MAX_PLAYERS) return;
            lanReady[slot] = ready;
            refreshLanLobbyUI();
            broadcastLanLobby();
        });
    }

    void onLanClientInput(int slot, int mask) {
        if (!lanModeActive || !lanIsHost) return;
        if (slot < 0 || slot >= LAN_MAX_PLAYERS) return;
        synchronized (lanInputLock) {
            lanInputMasks[slot] = mask;
        }
    }

    void onLanCompanionViewerChanged() {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            refreshLanCompanionFeedUI();
        });
    }

    void onLanServerError(IOException e) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsHost) return;
            NetworkSessionMode mode = networkSessionMode;
            Alert alert = new Alert(Alert.AlertType.ERROR, "Network hosting error: "
                    + (e.getMessage() == null ? "" : e.getMessage()), ButtonType.OK);
            alert.setTitle("Network Error");
            alert.setHeaderText("Hosting interrupted.");
            alert.showAndWait();
            stopLanSession();
            if (currentStage != null) {
                showNetworkModeMenu(currentStage, mode);
            }
        });
    }

    void onLanWelcome(int idx) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsClient) return;
            lanPlayerIndex = idx;
            if (lanPlayerIndex >= 0 && lanPlayerIndex < LAN_MAX_PLAYERS) {
                if (!lanRandomBirds[lanPlayerIndex] && lanSelectedBirds[lanPlayerIndex] == null) {
                    lanSelectedBirds[lanPlayerIndex] = firstUnlockedBird();
                }
                if (lanClient != null) {
                    lanSelectedSkinKeys[lanPlayerIndex] = normalizeAdventureSkinChoice(
                            lanSelectedBirds[lanPlayerIndex], lanSelectedSkinKeys[lanPlayerIndex]);
                    lanClient.sendSelect(lanSelectedBirds[lanPlayerIndex], lanRandomBirds[lanPlayerIndex], lanSelectedSkinKeys[lanPlayerIndex]);
                    lanClient.sendReady(lanReady[lanPlayerIndex]);
                }
            }
            refreshLanLobbyUI();
        });
    }

    void onLanLobbyUpdate(MapType map, MapVariant variant, boolean mapRandom, boolean[] connected, BirdType[] birds, boolean[] randomBirds, String[] skinKeys, boolean[] ready) {
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsClient) return;
            StageChoice selected = new StageChoice(map, variant);
            lanSelectedMap = selected.map();
            lanSelectedMapVariant = selected.variant();
            lanSelectedMapRandom = mapRandom;
            if (connected != null) {
                System.arraycopy(connected, 0, lanSlotConnected, 0, Math.min(connected.length, LAN_MAX_PLAYERS));
            }
            if (birds != null) {
                System.arraycopy(birds, 0, lanSelectedBirds, 0, Math.min(birds.length, LAN_MAX_PLAYERS));
            }
            if (randomBirds != null) {
                System.arraycopy(randomBirds, 0, lanRandomBirds, 0, Math.min(randomBirds.length, LAN_MAX_PLAYERS));
            }
            if (skinKeys != null) {
                System.arraycopy(skinKeys, 0, lanSelectedSkinKeys, 0, Math.min(skinKeys.length, LAN_MAX_PLAYERS));
            }
            if (ready != null) {
                System.arraycopy(ready, 0, lanReady, 0, Math.min(ready.length, LAN_MAX_PLAYERS));
            }
            refreshLanLobbyUI();
        });
    }

    void onLanStartMatch(MapType map, MapVariant variant, long seed, int inputDelayTicks, NetworkSimulationConfig simulationConfig,
                         boolean[] connected, BirdType[] birds, String[] skinKeys) {
        javafx.application.Platform.runLater(() -> {
            networkInputDelayTicks = LockstepSession.sanitizeInputDelay(inputDelayTicks);
            if (simulationConfig != null) {
                simulationConfig.apply();
                networkSimulationConfigApplied = true;
            }
            startLanMatchClient(currentStage, map, variant, seed, connected, birds, skinKeys);
        });
    }

    void onLanState(LanState state) {
        if (!lanModeActive || !lanIsClient) return;
        javafx.application.Platform.runLater(() -> {
            if (!lanMatchActive) {
                pendingLanState = state;
                return;
            }
            applyLanState(state);
        });
    }

    void onLanCountdown(int seconds) {
        if (!lanModeActive || !lanIsClient) return;
        javafx.application.Platform.runLater(() -> {
            lanCountdownValue = seconds;
            updateLanCountdownLabel();
        });
    }

    void onLanMatchEnd(int winnerIndex) {
        if (!lanModeActive || !lanIsClient) return;
        if (matchEnded) {
            // Lockstep clients conclude the match locally; the host's END
            // message is just a failsafe for desynced clients.
            return;
        }
        matchEnded = true;
        lanMatchActive = false;
        javafx.application.Platform.runLater(() -> {
            if (timer != null) timer.stop();
            showLanResults(currentStage, winnerIndex);
        });
    }

    void showLanResults(Stage stage, int winnerIndex) {
        if (stage == null) return;
        lanMatchActive = false;
        lanLastWinnerIndex = winnerIndex;
        publishLanCompanionSnapshot();
        lanResultsActionPending = false;
        lanResultsStatusLabel = null;

        Bird winner = null;
        if (winnerIndex >= 0 && winnerIndex < players.length) {
            winner = players[winnerIndex];
        }
        recordBalanceOutcome(winner);
        showMatchSummary(stage, winner);
    }

    private void requestLanResultsAction(int action, Stage stage, Button backLobby, Button exit) {
        if (lanResultsActionPending) return;
        lanResultsActionPending = true;
        if (backLobby != null) backLobby.setDisable(true);
        if (exit != null) exit.setDisable(true);
        int delayMs = LAN_RESULTS_CLOSE_DELAY_MS;
        if (lanIsHost && lanHost != null) {
            lanHost.broadcastResultsAction(action, delayMs);
        }
        if (lanResultsStatusLabel != null) {
            lanResultsStatusLabel.setText(action == LAN_RESULTS_ACTION_LOBBY
                    ? "Host is returning to lobby..."
                    : "Host is exiting to hub...");
        }
        PauseTransition closeDelay = new PauseTransition(Duration.millis(delayMs));
        closeDelay.setOnFinished(e -> performLanResultsAction(action, stage));
        closeDelay.play();
    }

    private void performLanResultsAction(int action, Stage stage) {
        lanResultsActionPending = false;
        lanResultsStatusLabel = null;
        if (stage == null) return;
        if (action == LAN_RESULTS_ACTION_LOBBY) {
            returnToLanLobby(stage);
        } else if (action == LAN_RESULTS_ACTION_EXIT) {
            stopLanSession();
            showMenu(stage);
        }
    }

    void onLanResultsAction(int action, int delayMs) {
        if (!lanModeActive || !lanIsClient) return;
        javafx.application.Platform.runLater(() -> {
            lanResultsActionPending = true;
            if (lanResultsStatusLabel != null) {
                lanResultsStatusLabel.setText(action == LAN_RESULTS_ACTION_LOBBY
                        ? "Host is returning to lobby..."
                        : "Host is exiting to hub...");
            }
            int delay = Math.max(0, delayMs);
            PauseTransition pause = new PauseTransition(Duration.millis(delay));
            pause.setOnFinished(e -> performLanResultsAction(action, currentStage));
            pause.play();
        });
    }

    void onLanDisconnected(String reason) {
        if (!lanModeActive || !lanIsClient) return;
        javafx.application.Platform.runLater(() -> {
            if (!lanModeActive || !lanIsClient) return;
            NetworkSessionMode mode = networkSessionMode;
            String detail = reason == null || reason.isBlank() ? "Connection lost." : reason;
            Alert alert = new Alert(Alert.AlertType.INFORMATION, detail, ButtonType.OK);
            alert.setTitle("Network Disconnected");
            alert.setHeaderText("Connection closed.");
            alert.showAndWait();
            stopLanSession();
            if (currentStage != null) {
                showNetworkModeMenu(currentStage, mode);
            }
        });
    }

    private void startLanMatchHost(Stage stage) {
        if (!lanIsHost) return;
        if (countLanConnected() < 2) return;
        stopLanCountdown();
        resetMatchStats();
        storyModeActive = false;
        storyReplayMode = false;
        adventureModeActive = false;
        adventureReplayMode = false;
        currentAdventureBattle = null;
        trainingModeActive = false;
        classicModeActive = false;
        clearAshfallTrialState();
        classicEncounter = null;
        competitionModeEnabled = false;
        mutatorModeEnabled = false;
        teamModeEnabled = false;
        lanMatchSeed = System.nanoTime();
        StageChoice stageToPlay = pickLanStageForMatch(lanMatchSeed);
        MapType mapToPlay = stageToPlay.map();
        lanSelectedMap = mapToPlay;
        lanSelectedMapVariant = stageToPlay.variant();
        lanSelectedMapRandom = false;
        selectedMap = mapToPlay;
        selectedMapVariant = stageToPlay.variant();
        activePlayers = LAN_MAX_PLAYERS;
        lanMatchActive = true;
        lastLanSnapshotNs = 0L;
        lastLanCompanionSnapshotNs = 0L;
        lanLastWinnerIndex = -1;
        List<BirdType> pool = unlockedBirdPool();
        for (int i = 0; i < LAN_MAX_PLAYERS; i++) {
            if (!lanSlotConnected[i]) continue;
            if ((lanRandomBirds[i] || lanSelectedBirds[i] == null) && !pool.isEmpty()) {
                lanSelectedBirds[i] = pool.get(random.nextInt(pool.size()));
                lanRandomBirds[i] = false;
                lanSelectedSkinKeys[i] = null;
            }
        }
        NetworkSimulationConfig simulationConfig = NetworkSimulationConfig.capture();
        if (lanHost != null) {
            lanHost.broadcastStart(mapToPlay, selectedMapVariant, lanMatchSeed, networkInputDelayTicks, simulationConfig,
                    lanSlotConnected, lanSelectedBirds, lanSelectedSkinKeys);
        }
        startMatch(stage);
        publishLanCompanionSnapshot();
    }

    private void startLanMatchClient(Stage stage, MapType map, MapVariant variant, long seed,
                                     boolean[] connected, BirdType[] birds, String[] skinKeys) {
        if (!lanModeActive || !lanIsClient) return;
        if (stage == null) return;
        lanCountdownValue = 0;
        updateLanCountdownLabel();
        resetMatchStats();
        storyModeActive = false;
        storyReplayMode = false;
        adventureModeActive = false;
        adventureReplayMode = false;
        currentAdventureBattle = null;
        trainingModeActive = false;
        classicModeActive = false;
        clearAshfallTrialState();
        classicEncounter = null;
        competitionModeEnabled = false;
        mutatorModeEnabled = false;
        teamModeEnabled = false;
        lanMatchSeed = seed;
        StageChoice selectedStage = new StageChoice(map, variant);
        lanSelectedMap = selectedStage.map();
        lanSelectedMapVariant = selectedStage.variant();
        selectedMap = selectedStage.map();
        selectedMapVariant = selectedStage.variant();
        if (connected != null) {
            System.arraycopy(connected, 0, lanSlotConnected, 0, Math.min(connected.length, LAN_MAX_PLAYERS));
        }
        if (birds != null) {
            System.arraycopy(birds, 0, lanSelectedBirds, 0, Math.min(birds.length, LAN_MAX_PLAYERS));
        }
        if (skinKeys != null) {
            System.arraycopy(skinKeys, 0, lanSelectedSkinKeys, 0, Math.min(skinKeys.length, LAN_MAX_PLAYERS));
        }
        for (int i = 0; i < LAN_MAX_PLAYERS; i++) {
            if (lanSlotConnected[i] && lanSelectedBirds[i] == null) {
                lanSelectedBirds[i] = firstUnlockedBird();
            }
            if (lanSlotConnected[i]) {
                lanRandomBirds[i] = false;
            }
        }
        activePlayers = LAN_MAX_PLAYERS;
        lanMatchActive = true;
        lanLocalInputMask = 0;
        lanKeyboardInputMask = 0;
        lanControllerInputMask = 0;
        if (lanClient != null) {
            lanClient.sendInputMask(0);
        }
        LanState pending = pendingLanState;
        pendingLanState = null;
        startMatch(stage);
        if (pending != null) {
            applyLanState(pending);
        }
    }

    private void returnToLanLobby(Stage stage) {
        if (stage == null) return;
        clearGameplayInputs();
        lanMatchActive = false;
        pendingLanState = null;
        lanResultsActionPending = false;
        lanResultsStatusLabel = null;
        lastLanCompanionSnapshotNs = 0L;
        lanLastWinnerIndex = -1;
        stopLanCountdown();
        synchronized (lanInputLock) {
            Arrays.fill(lanInputMasks, 0);
            Arrays.fill(lanLastInputMasks, 0);
        }
        lanLocalInputMask = 0;
        lanKeyboardInputMask = 0;
        lanControllerInputMask = 0;
        if (lanIsHost) {
            Arrays.fill(lanReady, false);
        } else if (lanPlayerIndex >= 0) {
            lanReady[lanPlayerIndex] = false;
            if (lanClient != null) {
                lanClient.sendReady(false);
            }
        }
        resetMatchStats();
        showLanLobby(stage);
        if (lanIsHost) {
            broadcastLanLobby();
        }
    }

    private void stopLanSession() {
        lanModeActive = false;
        lanIsHost = false;
        lanIsClient = false;
        networkSessionMode = NetworkSessionMode.NONE;
        networkSessionPort = LanProtocol.DEFAULT_PORT;
        networkInputDelayTicks = LockstepSession.INPUT_DELAY_TICKS;
        networkRemoteEndpoint = "";
        lanMatchActive = false;
        lanPlayerIndex = -1;
        lanResultsActionPending = false;
        lanResultsStatusLabel = null;
        lanLobbyInfoLabel = null;
        stopLanCountdown();
        if (lanHost != null) {
            lanHost.stop();
            lanHost = null;
        }
        if (lanClient != null) {
            lanClient.disconnect();
            lanClient = null;
        }
        Arrays.fill(lanSlotConnected, false);
        Arrays.fill(lanSelectedBirds, null);
        Arrays.fill(lanSelectedSkinKeys, null);
        Arrays.fill(lanRandomBirds, false);
        Arrays.fill(lanReady, false);
        Arrays.fill(lanMapVotes, null);
        Arrays.fill(lanMapVariantVotes, MapVariant.STANDARD);
        Arrays.fill(lanMapVoteRandomPools, StageRandomPool.NONE);
        synchronized (lanInputLock) {
            Arrays.fill(lanInputMasks, 0);
            Arrays.fill(lanLastInputMasks, 0);
        }
        lanLocalInputMask = 0;
        lanKeyboardInputMask = 0;
        lanControllerInputMask = 0;
        lockstepSession = null;
        lastLanSnapshotNs = 0L;
        lastLanCompanionSnapshotNs = 0L;
        lanLastWinnerIndex = -1;
        lanSelectedMapVariant = MapVariant.STANDARD;
        lanSelectedMapRandom = false;
        lanVoteSignature = 0;
        if (networkSimulationConfigApplied) {
            BirdStats.reloadFromDisk();
            networkSimulationConfigApplied = false;
        }
    }

    private void confirmLeaveLanMatch(Stage stage) {
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION,
                "Leave the match?",
                ButtonType.YES,
                ButtonType.NO);
        alert.setTitle("Leave Match");
        alert.setHeaderText("This will disconnect you from the network session.");
        alert.initOwner(stage);
        alert.showAndWait().ifPresent(choice -> {
            if (choice == ButtonType.YES) {
                stopLanSession();
                showLanMenu(stage);
            }
        });
    }

    private void confirmLeaveLanSession(Stage stage, Runnable onConfirm) {
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION,
                "Leave network session?",
                ButtonType.YES,
                ButtonType.NO);
        alert.setTitle("Leave Network Match");
        alert.setHeaderText("This will disconnect you from the network session.");
        alert.initOwner(stage);
        alert.showAndWait().ifPresent(choice -> {
            if (choice == ButtonType.YES && onConfirm != null) {
                onConfirm.run();
            }
        });
    }

    void publishLanCompanionMatchEnd(int winnerIndex) {
        lanLastWinnerIndex = winnerIndex;
        publishLanCompanionSnapshot();
    }

    private void publishLanCompanionSnapshot() {
        if (!lanModeActive || !lanIsHost || lanHost == null || !lanHost.isCompanionFeedEnabled()) return;
        lanHost.broadcastCompanionSnapshot(buildLanCompanionSnapshot());
    }

    private NetworkSessionHost.CompanionSnapshot buildLanCompanionSnapshot() {
        NetworkSessionHost.CompanionSnapshot snapshot = new NetworkSessionHost.CompanionSnapshot();
        snapshot.phase = lanCompanionPhase();
        snapshot.status = lanCompanionStatus(snapshot.phase);
        MapType map = (lanMatchActive || matchEnded) ? selectedMap : lanSelectedMap;
        if (map == null || (!lanMatchActive && !matchEnded && lanSelectedMapRandom)) {
            snapshot.mapName = "Random Map";
        } else {
            MapVariant variant = (lanMatchActive || matchEnded) ? selectedMapVariant : lanSelectedMapVariant;
            snapshot.mapName = stageDisplayName(map, variant);
        }
        snapshot.matchTimerFrames = Math.max(0, matchTimer);
        snapshot.matchEnded = matchEnded;
        snapshot.suddenDeathActive = suddenDeath.isActive();
        snapshot.suddenDeathSmashStyle = suddenDeath.isSmashStyle();
        snapshot.smashRules = usesSmashCombatRules();
        snapshot.countdownSeconds = Math.max(0, lanCountdownValue);
        snapshot.winnerIndex = lanLastWinnerIndex;
        snapshot.generatedAtMillis = System.currentTimeMillis();
        snapshot.killFeed = new ArrayList<>(killFeed.subList(0, Math.min(killFeed.size(), 6)));

        for (int i = 0; i < LAN_MAX_PLAYERS; i++) {
            populateLanCompanionPlayer(snapshot.players[i], i);
        }
        return snapshot;
    }

    private int lanCompanionPhase() {
        if (matchEnded) {
            return NetworkSessionHost.COMPANION_PHASE_RESULTS;
        }
        if (lanMatchActive) {
            return NetworkSessionHost.COMPANION_PHASE_MATCH;
        }
        if (lanCountdownValue > 0) {
            return NetworkSessionHost.COMPANION_PHASE_COUNTDOWN;
        }
        return NetworkSessionHost.COMPANION_PHASE_LOBBY;
    }

    private String lanCompanionStatus(int phase) {
        if (phase == NetworkSessionHost.COMPANION_PHASE_RESULTS) {
            if (lanLastWinnerIndex >= 0 && lanLastWinnerIndex < LAN_MAX_PLAYERS) {
                return "P" + (lanLastWinnerIndex + 1) + " wins";
            }
            return "Match complete";
        }
        if (phase == NetworkSessionHost.COMPANION_PHASE_MATCH) {
            return suddenDeath.isActive() ? "Sudden Death" : "Match live";
        }
        if (phase == NetworkSessionHost.COMPANION_PHASE_COUNTDOWN) {
            return "Match starts in " + lanCountdownValue;
        }
        return "LAN lobby";
    }

    private void populateLanCompanionPlayer(NetworkSessionHost.CompanionSnapshot.Player player, int index) {
        if (player == null || index < 0 || index >= LAN_MAX_PLAYERS) return;
        Bird bird = players[index];
        boolean hasBird = bird != null && (lanMatchActive || matchEnded);
        BirdType type = hasBird ? bird.type : lanSelectedBirds[index];
        boolean randomPick = !hasBird && lanRandomBirds[index];

        player.connected = lanSlotConnected[index] || hasBird;
        player.ready = lanReady[index];
        player.birdName = randomPick ? "Random" : (type != null ? type.name : "");
        player.colorHex = type != null ? toHex(type.color) : "#90A4AE";
        player.score = index < scores.length ? scores[index] : 0;
        player.health = hasBird ? Math.max(0.0, bird.health) : 0.0;
        player.damage = hasBird ? Math.max(0.0, bird.smashDamagePercent()) : 0.0;
        player.alive = hasBird && (usesSmashCombatRules() ? playerHasStocksRemaining(index) : bird.health > 0);
    }

    private LanState buildLanState() {
        LanState state = new LanState();
        state.matchTimer = matchTimer;
        state.matchEnded = matchEnded;
        state.suddenDeathActive = suddenDeath.isActive();
        state.suddenDeathSmashStyle = suddenDeath.isSmashStyle();
        state.activePlayers = activePlayers;
        state.camX = camX;
        state.camY = camY;
        state.zoom = zoom;
        state.shakeIntensity = shakeIntensity;
        state.hitstopFrames = hitstopFrames;
        state.dockLeverCooldown = dockLeverCooldown;
        state.scores = Arrays.copyOf(scores, scores.length);
        state.killFeed = new ArrayList<>(killFeed);
        for (int i = 0; i < LAN_MAX_PLAYERS; i++) {
            Bird b = players[i];
            if (b != null) {
                state.birds[i] = b.toLanState();
            }
        }
        for (PowerUp p : powerUps) {
            LanState.PowerUpState ps = new LanState.PowerUpState();
            ps.x = p.x;
            ps.y = p.y;
            ps.typeOrdinal = p.type.ordinal();
            state.powerUps.add(ps);
        }
        for (NectarNode n : nectarNodes) {
            LanState.NectarNodeState ns = new LanState.NectarNodeState();
            ns.x = n.x;
            ns.y = n.y;
            ns.isSpeed = n.isSpeed;
            ns.active = n.active;
            state.nectarNodes.add(ns);
        }
        for (SwingingVine v : swingingVines) {
            LanState.SwingingVineState vs = new LanState.SwingingVineState();
            vs.baseX = v.baseX;
            vs.baseY = v.baseY;
            vs.length = v.length;
            vs.angle = v.angle;
            vs.angularVelocity = v.angularVelocity;
            vs.temporary = v.temporary;
            vs.detaching = v.detaching;
            vs.detachedVX = v.detachedVX;
            vs.detachedVY = v.detachedVY;
            state.swingingVines.add(vs);
        }
        for (WindVent v : windVents) {
            LanState.WindVentState ws = new LanState.WindVentState();
            ws.x = v.x;
            ws.y = v.y;
            ws.w = v.w;
            ws.cooldown = v.cooldown;
            state.windVents.add(ws);
        }
        for (CrowMinion c : crowMinions) {
            LanState.CrowMinionState cs = new LanState.CrowMinionState();
            cs.x = c.x;
            cs.y = c.y;
            cs.age = c.age;
            cs.ownerIndex = c.owner != null ? c.owner.playerIndex : -1;
            cs.hasCrown = c.hasCrown;
            cs.variant = c.variant;
            state.crowMinions.add(cs);
        }
        for (PiranhaHazard piranha : piranhaHazards) {
            LanState.PiranhaState ps = new LanState.PiranhaState();
            ps.x = piranha.x;
            ps.y = piranha.y;
            ps.vx = piranha.vx;
            ps.vy = piranha.vy;
            ps.age = piranha.age;
            ps.biteCooldown = piranha.biteCooldown;
            ps.breachCooldown = piranha.breachCooldown;
            state.piranhas.add(ps);
        }
        if (dockShipBomb != null) {
            LanState.DockBombState bs = new LanState.DockBombState();
            bs.x = dockShipBomb.x;
            bs.y = dockShipBomb.y;
            bs.vx = dockShipBomb.vx;
            bs.vy = dockShipBomb.vy;
            bs.targetX = dockShipBomb.targetX;
            bs.targetY = dockShipBomb.targetY;
            bs.ownerPlayerIndex = dockShipBomb.ownerPlayerIndex;
            bs.targetPlayerIndex = dockShipBomb.targetPlayerIndex;
            bs.fuse = dockShipBomb.fuse;
            bs.launchDelayFrames = dockShipBomb.launchDelayFrames;
            bs.cannonFlashFrames = dockShipBomb.cannonFlashFrames;
            bs.explosionFrames = dockShipBomb.explosionFrames;
            bs.fired = dockShipBomb.fired;
            bs.exploded = dockShipBomb.exploded;
            state.dockBomb = bs;
        }
        for (ChickMinion chick : chickMinions) {
            LanState.ChickMinionState cs = new LanState.ChickMinionState();
            cs.x = chick.x;
            cs.y = chick.y;
            cs.vx = chick.vx;
            cs.age = chick.age;
            cs.ownerIndex = chick.owner != null ? chick.owner.playerIndex : -1;
            cs.variant = chick.variant;
            cs.life = chick.life;
            cs.ultimate = chick.ultimate;
            cs.followingOwner = chick.followingOwner;
            cs.commandFlashFrames = chick.commandFlashFrames;
            cs.thrownFrames = chick.thrownFrames;
            cs.boostSparkFrames = chick.boostSparkFrames;
            cs.roosterSwarm = chick.roosterSwarm;
            cs.swarmHitsRemaining = chick.swarmHitsRemaining;
            cs.swarmVisualCopies = chick.swarmVisualCopies;
            state.chickMinions.add(cs);
        }
        for (MockingbirdShadowMinion shadow : mockingbirdShadowMinions) {
            LanState.MockingbirdShadowState ss = new LanState.MockingbirdShadowState();
            ss.x = shadow.x;
            ss.y = shadow.y;
            ss.vx = shadow.vx;
            ss.vy = shadow.vy;
            ss.age = shadow.age;
            ss.ownerIndex = shadow.owner != null ? shadow.owner.playerIndex : -1;
            ss.copiedTypeOrdinal = shadow.copiedType != null ? shadow.copiedType.ordinal() : BirdType.PIGEON.ordinal();
            ss.health = shadow.health;
            ss.maxHealth = shadow.maxHealth;
            ss.attackCooldown = shadow.attackCooldown;
            ss.jumpCooldown = shadow.jumpCooldown;
            ss.retargetCooldown = shadow.retargetCooldown;
            ss.hitFlashTimer = shadow.hitFlashTimer;
            ss.spawnFlashFrames = shadow.spawnFlashFrames;
            ss.onGround = shadow.onGround;
            ss.facingRight = shadow.facingRight;
            ss.slot = shadow.slot;
            state.mockingbirdShadows.add(ss);
        }
        return state;
    }

    private void applyLanState(LanState state) {
        if (state == null) return;
        matchTimer = state.matchTimer;
        matchEnded = state.matchEnded;
        suddenDeath.syncFromRemote(state.suddenDeathActive, state.suddenDeathSmashStyle);
        smashCombatRulesActive = true;
        activePlayers = Math.clamp(state.activePlayers > 0 ? state.activePlayers : LAN_MAX_PLAYERS, 1, LAN_MAX_PLAYERS);
        camX = state.camX;
        camY = state.camY;
        zoom = state.zoom;
        syncTrackedCameraToCurrentView();
        shakeIntensity = state.shakeIntensity;
        hitstopFrames = state.hitstopFrames;
        dockLeverCooldown = state.dockLeverCooldown;
        if (state.scores != null) {
            int len = Math.min(scores.length, state.scores.length);
            System.arraycopy(state.scores, 0, scores, 0, len);
        }
        killFeed.clear();
        if (state.killFeed != null) {
            killFeed.addAll(state.killFeed);
        }
        for (int i = 0; i < LAN_MAX_PLAYERS; i++) {
            LanBirdState bs = state.birds[i];
            if (bs == null) {
                players[i] = null;
                isAI[i] = false;
                continue;
            }
            BirdType type = BirdType.values()[Math.clamp(bs.typeOrdinal, 0, BirdType.values().length - 1)];
            Bird b = players[i];
            if (b == null || b.type != type) {
                b = new Bird(0, type, i, this);
                players[i] = b;
            }
            isAI[i] = false;
            b.applyLanState(bs);
        }
        for (int i = 0; i < LAN_MAX_PLAYERS; i++) {
            if (players[i] != null && state.birds[i] != null) {
                players[i].resolveLanGrabLinks(state.birds[i], players);
            }
        }

        syncLanPowerUps(state.powerUps);
        syncLanNectarNodes(state.nectarNodes);
        syncLanSwingingVines(state.swingingVines);
        syncLanWindVents(state.windVents);
        syncLanCrowMinions(state.crowMinions);
        syncLanPiranhas(state.piranhas);
        syncLanDockBomb(state.dockBomb);
        syncLanChickMinions(state.chickMinions);
        syncLanMockingbirdShadows(state.mockingbirdShadows);
    }

    private void syncLanPowerUps(List<LanState.PowerUpState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (powerUps.size() > targetSize) {
            powerUps.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.PowerUpState ps = states.get(i);
            PowerUpType type = PowerUpType.values()[Math.clamp(ps.typeOrdinal, 0, PowerUpType.values().length - 1)];
            PowerUp powerUp;
            if (i < powerUps.size()) {
                powerUp = powerUps.get(i);
            } else {
                powerUp = new PowerUp(ps.x, ps.y, type);
                powerUps.add(powerUp);
            }
            powerUp.x = ps.x;
            powerUp.y = ps.y;
            powerUp.type = type;
        }
    }

    private void syncLanNectarNodes(List<LanState.NectarNodeState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (nectarNodes.size() > targetSize) {
            nectarNodes.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.NectarNodeState ns = states.get(i);
            NectarNode node;
            if (i < nectarNodes.size()) {
                node = nectarNodes.get(i);
            } else {
                node = new NectarNode(ns.x, ns.y, ns.isSpeed);
                nectarNodes.add(node);
            }
            node.x = ns.x;
            node.y = ns.y;
            node.isSpeed = ns.isSpeed;
            node.active = ns.active;
        }
    }

    private void syncLanSwingingVines(List<LanState.SwingingVineState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (swingingVines.size() > targetSize) {
            swingingVines.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.SwingingVineState vs = states.get(i);
            SwingingVine vine;
            if (i < swingingVines.size()) {
                vine = swingingVines.get(i);
            } else {
                vine = new SwingingVine(vs.baseX, vs.baseY, vs.length);
                swingingVines.add(vine);
            }
            vine.baseX = vs.baseX;
            vine.baseY = vs.baseY;
            vine.length = vs.length;
            vine.angle = vs.angle;
            vine.angularVelocity = vs.angularVelocity;
            vine.temporary = vs.temporary;
            vine.detaching = vs.detaching;
            vine.detachedVX = vs.detachedVX;
            vine.detachedVY = vs.detachedVY;
            vine.updatePlatformPosition();
        }
    }

    private void syncLanWindVents(List<LanState.WindVentState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (windVents.size() > targetSize) {
            windVents.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.WindVentState ws = states.get(i);
            WindVent vent;
            if (i < windVents.size()) {
                vent = windVents.get(i);
            } else {
                vent = new WindVent(ws.x, ws.y, ws.w);
                windVents.add(vent);
            }
            vent.x = ws.x;
            vent.y = ws.y;
            vent.w = ws.w;
            vent.cooldown = ws.cooldown;
        }
    }

    private void syncLanCrowMinions(List<LanState.CrowMinionState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (crowMinions.size() > targetSize) {
            crowMinions.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.CrowMinionState cs = states.get(i);
            CrowMinion crow;
            if (i < crowMinions.size()) {
                crow = crowMinions.get(i);
            } else {
                crow = new CrowMinion(cs.x, cs.y, null);
                crow.vx = 0;
                crow.vy = 0;
                crowMinions.add(crow);
            }
            crow.x = cs.x;
            crow.y = cs.y;
            crow.age = cs.age;
            crow.hasCrown = cs.hasCrown;
            crow.variant = cs.variant;
            crow.owner = cs.ownerIndex >= 0 && cs.ownerIndex < players.length ? players[cs.ownerIndex] : null;
            crow.target = null;
        }
    }

    private void syncLanPiranhas(List<LanState.PiranhaState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (piranhaHazards.size() > targetSize) {
            piranhaHazards.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.PiranhaState ps = states.get(i);
            PiranhaHazard piranha;
            if (i < piranhaHazards.size()) {
                piranha = piranhaHazards.get(i);
            } else {
                piranha = new PiranhaHazard(ps.x, ps.y, ps.vx);
                piranhaHazards.add(piranha);
            }
            piranha.x = ps.x;
            piranha.y = ps.y;
            piranha.vx = ps.vx;
            piranha.vy = ps.vy;
            piranha.age = ps.age;
            piranha.biteCooldown = ps.biteCooldown;
            piranha.breachCooldown = ps.breachCooldown;
            piranha.target = null;
            piranha.retargetCooldown = 0;
        }
    }

    private void syncLanDockBomb(LanState.DockBombState state) {
        if (state == null) {
            dockShipBomb = null;
            return;
        }
        if (dockShipBomb == null) {
            dockShipBomb = new DockShipBomb(
                    state.x,
                    state.y,
                    state.vx,
                    state.vy,
                    state.targetX,
                    state.targetY,
                    state.ownerPlayerIndex,
                    state.targetPlayerIndex,
                    state.fuse
            );
        }
        dockShipBomb.x = state.x;
        dockShipBomb.y = state.y;
        dockShipBomb.vx = state.vx;
        dockShipBomb.vy = state.vy;
        dockShipBomb.targetX = state.targetX;
        dockShipBomb.targetY = state.targetY;
        dockShipBomb.ownerPlayerIndex = state.ownerPlayerIndex;
        dockShipBomb.targetPlayerIndex = state.targetPlayerIndex;
        dockShipBomb.fuse = state.fuse;
        dockShipBomb.launchDelayFrames = state.launchDelayFrames;
        dockShipBomb.cannonFlashFrames = state.cannonFlashFrames;
        dockShipBomb.explosionFrames = state.explosionFrames;
        dockShipBomb.fired = state.fired;
        dockShipBomb.exploded = state.exploded;
    }

    private void syncLanChickMinions(List<LanState.ChickMinionState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (chickMinions.size() > targetSize) {
            chickMinions.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.ChickMinionState cs = states.get(i);
            ChickMinion chick;
            boolean needsReplacement = i >= chickMinions.size();
            if (!needsReplacement) {
                chick = chickMinions.get(i);
                needsReplacement = chick.variant != cs.variant
                        || chick.ultimate != cs.ultimate
                        || chick.roosterSwarm != cs.roosterSwarm;
            } else {
                chick = null;
            }
            if (needsReplacement) {
                chick = new ChickMinion(cs.x, cs.y, cs.variant, cs.ultimate, null);
                chick.vx = 0;
                chick.vy = 0;
                if (i < chickMinions.size()) {
                    chickMinions.set(i, chick);
                } else {
                    chickMinions.add(chick);
                }
            }
            chick.x = cs.x;
            chick.y = cs.y;
            chick.vx = cs.vx;
            chick.age = cs.age;
            chick.life = Math.clamp(cs.life, 0, chick.maxLife);
            chick.owner = cs.ownerIndex >= 0 && cs.ownerIndex < players.length ? players[cs.ownerIndex] : null;
            chick.followingOwner = cs.followingOwner;
            chick.commandFlashFrames = cs.commandFlashFrames;
            chick.thrownFrames = cs.thrownFrames;
            chick.boostSparkFrames = cs.boostSparkFrames;
            chick.roosterSwarm = cs.roosterSwarm;
            chick.swarmHitsRemaining = Math.max(0, cs.swarmHitsRemaining);
            chick.swarmVisualCopies = Math.clamp(cs.swarmVisualCopies, 0, 8);
            chick.target = null;
        }
    }

    private void syncLanMockingbirdShadows(List<LanState.MockingbirdShadowState> states) {
        int targetSize = states != null ? states.size() : 0;
        while (mockingbirdShadowMinions.size() > targetSize) {
            mockingbirdShadowMinions.removeLast();
        }
        for (int i = 0; i < targetSize; i++) {
            LanState.MockingbirdShadowState ss = states.get(i);
            Bird owner = ss.ownerIndex >= 0 && ss.ownerIndex < players.length ? players[ss.ownerIndex] : null;
            BirdType copiedType = BirdType.values()[Math.clamp(ss.copiedTypeOrdinal, 0, BirdType.values().length - 1)];
            if (copiedType == BirdType.MOCKINGBIRD) {
                copiedType = BirdType.PIGEON;
            }

            MockingbirdShadowMinion shadow;
            boolean needsReplacement = i >= mockingbirdShadowMinions.size();
            if (!needsReplacement) {
                shadow = mockingbirdShadowMinions.get(i);
                needsReplacement = shadow.copiedType != copiedType || shadow.slot != Math.max(0, ss.slot);
            } else {
                shadow = null;
            }
            if (needsReplacement) {
                shadow = new MockingbirdShadowMinion(
                        ss.x + 40.0,
                        ss.y + 40.0,
                        copiedType,
                        owner,
                        Math.max(0, ss.slot)
                );
                if (i < mockingbirdShadowMinions.size()) {
                    mockingbirdShadowMinions.set(i, shadow);
                } else {
                    mockingbirdShadowMinions.add(shadow);
                }
            }
            shadow.x = ss.x;
            shadow.y = ss.y;
            shadow.prevX = ss.x;
            shadow.prevY = ss.y;
            shadow.vx = ss.vx;
            shadow.vy = ss.vy;
            shadow.age = Math.max(0, ss.age);
            shadow.owner = owner;
            shadow.target = null;
            shadow.copiedType = copiedType;
            shadow.maxHealth = Math.max(1.0, ss.maxHealth);
            shadow.health = Math.clamp(ss.health, 0.0, shadow.maxHealth);
            shadow.attackCooldown = Math.max(0, ss.attackCooldown);
            shadow.jumpCooldown = Math.max(0, ss.jumpCooldown);
            shadow.retargetCooldown = Math.max(0, ss.retargetCooldown);
            shadow.hitFlashTimer = Math.max(0, ss.hitFlashTimer);
            shadow.spawnFlashFrames = Math.max(0, ss.spawnFlashFrames);
            shadow.onGround = ss.onGround;
            shadow.facingRight = ss.facingRight;
        }
    }

    private void applyLanInputMasks() {
        synchronized (lanInputLock) {
            for (int i = 1; i < LAN_MAX_PLAYERS; i++) {
                int mask = lanSlotConnected[i] ? lanInputMasks[i] : 0;
                updatePressedKeysForPlayer(i, mask);
                int last = lanLastInputMasks[i];
                if ((mask & LanProtocol.INPUT_LEFT) != 0 && (last & LanProtocol.INPUT_LEFT) == 0) {
                    if (players[i] != null) players[i].registerDashTap(-1);
                }
                if ((mask & LanProtocol.INPUT_RIGHT) != 0 && (last & LanProtocol.INPUT_RIGHT) == 0) {
                    if (players[i] != null) players[i].registerDashTap(1);
                }
                lanLastInputMasks[i] = mask;
            }
        }
    }

    private void updatePressedKeysForPlayer(int idx, int mask) {
        setLanActionState(idx, ControlAction.LEFT, (mask & LanProtocol.INPUT_LEFT) != 0);
        setLanActionState(idx, ControlAction.RIGHT, (mask & LanProtocol.INPUT_RIGHT) != 0);
        setLanActionState(idx, ControlAction.JUMP, (mask & LanProtocol.INPUT_JUMP) != 0);
        setLanActionState(idx, ControlAction.ATTACK, (mask & LanProtocol.INPUT_ATTACK) != 0);
        setLanActionState(idx, ControlAction.SPECIAL, (mask & LanProtocol.INPUT_SPECIAL) != 0);
        setLanActionState(idx, ControlAction.GRAB, (mask & LanProtocol.INPUT_GRAB) != 0);
        setLanActionState(idx, ControlAction.BLOCK, (mask & LanProtocol.INPUT_BLOCK) != 0);
        setLanActionState(idx, ControlAction.TAUNT_CYCLE, (mask & LanProtocol.INPUT_TAUNT_CYCLE) != 0);
        setLanActionState(idx, ControlAction.TAUNT_EXECUTE, (mask & LanProtocol.INPUT_TAUNT_EXEC) != 0);
        lanAttackUpHeld[idx] = (mask & LanProtocol.INPUT_ATTACK_UP) != 0;
        lanAttackDownHeld[idx] = (mask & LanProtocol.INPUT_ATTACK_DOWN) != 0;
    }

    private void handleLanKeyPress(Stage stage, KeyEvent e) {
        KeyCode code = e.getCode();
        if (code == KeyCode.F11) {
            fullscreenEnabled = !fullscreenEnabled;
            applyDisplaySettings(stage);
            saveAchievements();
            return;
        }
        if (code == KeyCode.F3) {
            debugHudEnabled = !debugHudEnabled;
            addToKillFeed(debugHudEnabled ? "DEBUG HUD: ON" : "DEBUG HUD: OFF");
            return;
        }
        if (code == KeyCode.ESCAPE) {
            confirmLeaveLanMatch(stage);
            return;
        }
        if (lanPlayerIndex < 0) return;
        int bit = inputBitForKey(code, lanPlayerIndex);
        if (bit == 0) {
            bit = inputBitForKey(code, 0);
        }
        if (bit == 0) return;
        lanKeyboardInputMask |= bit;
        refreshLanLocalInputMask();
    }

    /** Recombines keyboard + controller bits; sends the legacy mask on change. */
    private void refreshLanLocalInputMask() {
        int combined = lanKeyboardInputMask | lanControllerInputMask;
        if (combined != lanLocalInputMask) {
            lanLocalInputMask = combined;
            if (lanClient != null) {
                lanClient.sendInputMask(combined);
            }
        }
    }

    private void handleLanKeyRelease(KeyEvent e) {
        if (lanPlayerIndex < 0) return;
        KeyCode code = e.getCode();
        int bit = inputBitForKey(code, lanPlayerIndex);
        if (bit == 0) {
            bit = inputBitForKey(code, 0);
        }
        if (bit == 0) return;
        lanKeyboardInputMask &= ~bit;
        refreshLanLocalInputMask();
    }

