        g.setFill(Color.web("#B9C7D8"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 22));
        g.fillText(BirdType.values().length + " FIGHTERS  /  ONE SKY", WIDTH / 2.0, 920);
        g.setTextAlign(TextAlignment.LEFT);
