    private void drawOfficialTrailerCopy(GraphicsContext g, int sceneIndex, double phase) {
        if (isOfficialTrailerCutsceneScene(sceneIndex)
                || isOfficialTrailerGraphicScene(sceneIndex)) {
            return;
        }
        if (isOfficialTrailerGameplayScene(sceneIndex)) {
            String kicker = switch (sceneIndex) {
                case 2 -> "REAL GAMEPLAY";
                case 4 -> "SIGNATURE SPECIALS AND ULTIMATES";
                case 5 -> "EVERY ARENA CHANGES THE FIGHT";
                case 9 -> "LOCAL, LAN, AND INTERNET MULTIPLAYER";
                case 10 -> "BOSS RUSH";
                case 11 -> "THE FINAL BATTLE";
                default -> "GAMEPLAY";
            };
            String title = switch (sceneIndex) {
                case 2 -> "READ. STRIKE. LAUNCH.";
                case 4 -> "MASTER YOUR MOVESET";
                case 5 -> MapType.values().length + " ARENAS  /  "
                        + (MapVariant.values().length - 1) + " VARIANTS";
                case 9 -> "UP TO FOUR PLAYERS";
                case 10 -> "BOSSES DON'T FIGHT FAIR";
                case 11 -> "FACE THE NULL ROCK";
                default -> "TAKE THE SKY";
            };
            drawOfficialTrailerGameplayCaption(g, kicker, title, phase);
            return;
        }
        if (sceneIndex == 3 || sceneIndex == 7 || sceneIndex == 8 || sceneIndex == 13) {
            return;
        }

        String kicker;
        String title;
        String subtitle;
        boolean centered = false;
        switch (sceneIndex) {
            case 0 -> {
                kicker = "THE STILL SKY";
                title = "THE CROWN HAS AWAKENED";
                subtitle = "An ancient ruler has returned to take the sky.";
                centered = true;
            }
            case 1 -> {
                kicker = "A FULL STORY CAMPAIGN";
                title = "UNITE THE FLOCK";
                subtitle = "Break the prisons. Defy the Crown. Reach the Beacon.";
            }
            case 2 -> {
                kicker = "PLATFORM FIGHTING, REBUILT FOR BIRDS";
                title = "EVERY HIT CHANGES THE FIGHT";
                subtitle = "Build damage. Read the recovery. Send them beyond the arena.";
            }
            case 4 -> {
                kicker = "DEEP, DISTINCT MOVESETS";
                title = "FOUR SPECIALS. ONE ULTIMATE.";
                subtitle = "Master movement, charge attacks, shields, parries, and signature powers.";
            }
            case 5 -> {
                kicker = "THE BATTLE NEVER STAYS STILL";
                title = MapType.values().length + " ARENAS. " + (MapVariant.values().length - 1) + " VARIANTS.";
                subtitle = "Cities. Cathedrals. Prisons. Dreadnoughts. Frozen seas. The edge of the void.";
                centered = true;
            }
            case 6 -> {
                kicker = "THE STILL SKY CAMPAIGN";
                title = "YOUR CHOICES CARRY FORWARD";
                subtitle = "Fight through chapters, allies, rivalries, escapes, and a war for the sky.";
            }
            case 7 -> {
                kicker = "PLAY YOUR WAY";
                title = "MORE THAN VERSUS";
                subtitle = "Story. Classic. Boss Rush. Tournaments. Training.";
                centered = true;
            }
            case 9 -> {
                kicker = "UP TO FOUR PLAYERS";
                title = "LOCAL. LAN. INTERNET.";
                subtitle = "Share one screen or direct-connect for deterministic multiplayer battles.";
            }
            case 10 -> {
                kicker = "BOSS RUSH";
                title = "BOSSES DON'T FIGHT FAIR";
                subtitle = "Survive colossal rivals, hostile arenas, and escalating difficulty.";
            }
            case 11 -> {
                kicker = "THE FINAL BATTLE";
                title = "FACE THE NULL ROCK";
                subtitle = "When the sky goes dark, the whole flock answers.";
                centered = true;
            }
            case 12 -> {
                kicker = "CHOOSE YOUR BIRD";
                title = "BECOME THE LAST ONE FLYING";
                subtitle = "The sky belongs to whoever can hold it.";
                centered = true;
            }
            default -> {
                return;
            }
        }
        drawOfficialTrailerTypography(g, kicker, title, subtitle, phase, centered);
    }

    private void drawOfficialTrailerGameplayCaption(GraphicsContext g,
                                                     String kicker,
                                                     String title,
                                                     double phase) {
        double alpha = officialTrailerCopyAlpha(phase);
        if (alpha <= 0.01) {
            return;
        }
        g.save();
        g.setGlobalAlpha(alpha);
        double width = Math.clamp(580.0 + title.length() * 13.0, 720.0, 1100.0);
        double x = WIDTH / 2.0 - width / 2.0;
        g.setFill(Color.web("#02050A", 0.78));
        g.fillRoundRect(x, 5, width, 57, 16, 16);
        g.setStroke(Color.web("#FFB74D", 0.58));
        g.setLineWidth(2);
        g.strokeRoundRect(x, 5, width, 57, 16, 16);
        g.setTextAlign(TextAlignment.CENTER);
        g.setFill(Color.web("#FFB74D"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 13));
        g.fillText(kicker, WIDTH / 2.0, 18);
        g.setFill(Color.web("#FFF8E8"));
        g.setFont(Font.font("Arial Black", FontWeight.BOLD, 27));
        g.fillText(title, WIDTH / 2.0, 49);
        g.restore();
        g.setTextAlign(TextAlignment.LEFT);
    }

    private void drawOfficialTrailerTypography(GraphicsContext g,
                                                String kicker,
                                                String title,
                                                String subtitle,
                                                double phase,
                                                boolean centered) {
        double alpha = officialTrailerCopyAlpha(phase);
        if (alpha <= 0.01) return;
        g.save();
        g.setGlobalAlpha(alpha);
        double anchorX = centered ? WIDTH / 2.0 : 150.0;
        double baselineY = centered ? HEIGHT * 0.72 : HEIGHT - 205.0;
        g.setTextAlign(centered ? TextAlignment.CENTER : TextAlignment.LEFT);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 25));
        g.setFill(Color.web("#FFB74D"));
        g.fillText(kicker, anchorX, baselineY - 104);
        double titleSize = title.length() > 32 ? 58.0 : title.length() > 24 ? 66.0 : 76.0;
        g.setFont(Font.font("Arial Black", FontWeight.BOLD, titleSize));
        g.setStroke(Color.web("#03070B", 0.96));
        g.setLineWidth(10);
        g.strokeText(title, anchorX, baselineY - 28);
        g.setFill(Color.web("#FFF8E8"));
        g.fillText(title, anchorX, baselineY - 28);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 24));
        g.setStroke(Color.web("#03070B", 0.88));
        g.setLineWidth(6);
        g.strokeText(subtitle, anchorX, baselineY + 24);
        g.setFill(Color.web("#DCE8EF"));
        g.fillText(subtitle, anchorX, baselineY + 24);
        if (!centered) {
            g.setStroke(Color.web("#FFB74D", 0.88));
            g.setLineWidth(5);
            g.strokeLine(anchorX, baselineY + 58, anchorX + 430, baselineY + 58);
        }
        g.restore();
        g.setTextAlign(TextAlignment.LEFT);
    }

    private double officialTrailerCopyAlpha(double phase) {
        double fadeIn = smoothStep01(phase / 0.12);
        double fadeOut = 1.0 - smoothStep01((phase - 0.86) / 0.14);
        return Math.clamp(fadeIn * fadeOut, 0.0, 1.0);
    }

    private void drawOfficialTrailerBackdrop(GraphicsContext g, Color top, Color bottom) {
        for (int i = 0; i < 360; i++) {
            double ratio = i / 359.0;
            g.setFill(top.interpolate(bottom, ratio));
            g.fillRect(0, i * (HEIGHT / 360.0), WIDTH, HEIGHT / 360.0 + 2);
        }
        g.setStroke(Color.web("#90CAF9", 0.035));
        g.setLineWidth(2);
        for (int i = 0; i < 18; i++) {
            double y = 90 + i * 58;
            g.strokeLine(0, y, WIDTH, y - 34);
        }
    }

    private void drawOfficialTrailerVignette(GraphicsContext g) {
        for (int i = 0; i < 12; i++) {
            double alpha = 0.014 + i * 0.006;
            double inset = i * 18.0;
            g.setStroke(Color.web("#000000", alpha));
            g.setLineWidth(38);
            g.strokeRect(inset, inset, WIDTH - inset * 2, HEIGHT - inset * 2);
        }
    }

    private void drawOfficialTrailerLetterbox(GraphicsContext g) {
        g.setFill(Color.web("#010204"));
        g.fillRect(0, 0, WIDTH, 62);
        g.fillRect(0, HEIGHT - 62, WIDTH, 62);
    }

    private void drawOfficialTrailerTransition(GraphicsContext g, int sceneIndex, double phase) {
        double cutFade = sceneIndex == 0
                ? 1.0 - smoothStep01(phase / 0.20)
                : 1.0 - smoothStep01(phase / 0.045);
        double finalFade = sceneIndex == 13 ? smoothStep01((phase - 0.91) / 0.09) : 0.0;
        double alpha = Math.clamp(Math.max(cutFade, finalFade), 0.0, 1.0);
        if (alpha > 0.001) {
            g.setFill(Color.web("#000000", alpha));
            g.fillRect(0, 0, WIDTH, HEIGHT);
        }
        if (sceneIndex == 2 && phase < 0.055) {
            double flash = 1.0 - Math.abs(phase - 0.0275) / 0.0275;
            g.setFill(Color.WHITE.deriveColor(0, 1, 1,
                    Math.clamp(flash * 0.78, 0.0, 0.78)));
            g.fillRect(0, 0, WIDTH, HEIGHT);
        }
        if ((sceneIndex == 4 || sceneIndex == 10 || sceneIndex == 11)
                && phase > 0.48 && phase < 0.515) {
            double flash = 1.0 - Math.abs(phase - 0.4975) / 0.0175;
            g.setFill(Color.WHITE.deriveColor(0, 1, 1, Math.clamp(flash * 0.42, 0.0, 0.42)));
            g.fillRect(0, 0, WIDTH, HEIGHT);
        }
    }

    private Bird createTrailerBird(BirdType type, int playerIndex, String name, String skinKey) {
        Bird bird = new Bird(0, type, playerIndex, this);
        bird.name = name;
        if (skinKey != null) {
            applyPreviewSkinChoiceToBird(bird, type, skinKey);
        }
        return bird;
    }

    private void poseTrailerBird(Bird bird, double x, double y, boolean facingRight, boolean flying, int attackFrames, double vx) {
        if (bird == null) {
            return;
        }
        bird.x = x;
        bird.y = y;
        bird.facingRight = facingRight;
        bird.isFlying = flying;
        bird.attackAnimationTimer = attackFrames;
        // Trailer motion comes from explicit position choreography. Feeding a
        // synthetic velocity into the normal renderer selects hitstun/flight
        // rotations and can turn a posed bird upside down.
        bird.vx = 0.0;
        bird.vy = 0.0;
        bird.diveTimer = 0;
        bird.eagleDiveActive = false;
        bird.eagleAscentActive = false;
    }

    private void drawTrailerTitleCard(GraphicsContext g,
                                      String kicker,
                                      String title,
                                      String subtitle,
                                      Color accent,
                                      double alpha,
                                      double centerY) {
        if (g == null || title == null || title.isBlank() || alpha <= 0.0) {
            return;
        }

        Font kickerFont = Font.font("Consolas", FontWeight.BOLD, 24);
        Font titleFont = Font.font("Arial Black", FontWeight.BOLD, 74);
        Font subtitleFont = Font.font("Consolas", FontWeight.BOLD, 23);

        double titleWidth = measureTextWidth(title, titleFont);
        double subtitleWidth = subtitle == null || subtitle.isBlank() ? 0.0 : measureTextWidth(subtitle, subtitleFont);
        double kickerWidth = kicker == null || kicker.isBlank() ? 0.0 : measureTextWidth(kicker, kickerFont);
        double cardWidth = Math.clamp(Math.max(titleWidth, Math.max(subtitleWidth, kickerWidth)) + 180.0, 720.0, 1320.0);
        double cardHeight = subtitle == null || subtitle.isBlank() ? 168.0 : 212.0;
        double cardX = WIDTH / 2.0 - cardWidth / 2.0;
        double cardY = centerY - cardHeight / 2.0;

        g.save();
        g.setGlobalAlpha(alpha);
        g.setFill(Color.web("#03070B", 0.76));
        g.fillRoundRect(cardX, cardY, cardWidth, cardHeight, 38, 38);
        g.setFill(accent.deriveColor(0, 1, 1, 0.22));
        g.fillRoundRect(cardX, cardY, cardWidth, 20, 38, 38);
        g.setStroke(accent.deriveColor(0, 1, 1, 0.96));
        g.setLineWidth(2.8);
        g.strokeRoundRect(cardX, cardY, cardWidth, cardHeight, 38, 38);

        g.setTextAlign(TextAlignment.CENTER);
        if (kicker != null && !kicker.isBlank()) {
            g.setFill(accent.brighter());
            g.setFont(kickerFont);
            g.fillText(kicker, WIDTH / 2.0, cardY + 40);
        }

        double titleBaseline = cardY + (subtitle == null || subtitle.isBlank() ? 112.0 : 102.0);
        g.setFont(titleFont);
        g.setLineWidth(7.0);
        g.setStroke(Color.web("#351A00", 0.88));
        g.strokeText(title, WIDTH / 2.0, titleBaseline);
        g.setFill(Color.web("#FFF6E8"));
        g.fillText(title, WIDTH / 2.0, titleBaseline);

        if (subtitle != null && !subtitle.isBlank()) {
            g.setFill(Color.web("#D7E3EA"));
            g.setFont(subtitleFont);
            g.fillText(subtitle, WIDTH / 2.0, cardY + 154);
        }
        g.setTextAlign(TextAlignment.LEFT);
        g.restore();
    }

    private void drawTrailerSpeedLines(GraphicsContext g, Bird bird, Color accent, double intensity) {
        if (g == null || bird == null || intensity <= 0.0) {
            return;
        }
        double dir = bird.facingRight ? -1.0 : 1.0;
        double centerY = bird.y + 40.0 * bird.sizeMultiplier;
        double baseX = bird.facingRight ? bird.x - 220.0 : bird.x + 150.0;
        Color lineColor = (accent == null ? Color.web("#FFD180") : accent).deriveColor(0, 1, 1, 0.16 + intensity * 0.22);

        g.save();
        g.setStroke(lineColor);
        g.setLineWidth(5.0);
        double t = System.currentTimeMillis() / 140.0;
        for (int i = 0; i < 7; i++) {
            double offsetY = (i - 3) * 22.0 + Math.sin(t + i * 0.8) * 6.0;
            double startX = baseX + dir * i * 18.0;
            double endX = startX - dir * (110.0 + i * 34.0 + intensity * 40.0);
            g.strokeLine(startX, centerY + offsetY, endX, centerY + offsetY + Math.sin(t * 1.2 + i) * 5.0);
        }
        g.restore();
    }

    private double normalizedProgress(double value, double start, double end) {
        if (end <= start) {
            return value >= end ? 1.0 : 0.0;
        }
        return Math.clamp((value - start) / (end - start), 0.0, 1.0);
    }

    private double smoothStep01(double value) {
        double t = Math.clamp(value, 0.0, 1.0);
        return t * t * (3.0 - 2.0 * t);
    }

    private double trailerOverlayAlpha(double progress) {
        double clamped = Math.clamp(progress, 0.0, 1.0);
        // Slower fade in/out so text boxes stay visible longer on the extended trailer
        double fadeIn = smoothStep01(clamped / 0.25);
        double fadeOut = 1.0 - smoothStep01((clamped - 0.85) / 0.30);
        return Math.clamp(fadeIn * Math.max(0.0, fadeOut), 0.0, 1.0);
    }

    private double lerp(double start, double end, double progress) {
        return start + (end - start) * Math.clamp(progress, 0.0, 1.0);
    }

    private double trailerGroundCameraY(double zoomLevel, double groundInset) {
        return Math.clamp(
                GROUND_Y - HEIGHT / Math.max(zoomLevel, 0.001) + groundInset,
                0.0,
                cameraMaxYForZoom(zoomLevel)
        );
    }

    private void prepareTrailerArena(MapType map) {
        selectedMap = map == null ? MapType.DESERT : map;
        platforms.clear();
        windVents.clear();
        nectarNodes.clear();
        swingingVines.clear();
        particles.clear();
        blastZoneKoEffects.clear();
        combatImpactEffects.clear();
        crowMinions.clear();
        piranhaHazards.clear();
        chickMinions.clear();
        mockingbirdShadowMinions.clear();
        frostbiteSnowbanks.clear();
        powerUps.clear();
        dockWaterX = 0;
        dockWaterY = 0;
        dockWaterW = 0;
        dockWaterH = 0;
        dockDrownY = 0;
        dockLeverX = 0;
        dockLeverY = 0;
        dockLeverCooldown = 0;
        dockShipBomb = null;
        battlefieldIslandX = 0;
        battlefieldIslandW = 0;
        battlefieldIslandY = 0;
        Arrays.fill(dockLeverHeld, false);
        Arrays.fill(prisonLeverCooldowns, 0);
        Arrays.fill(prisonLeverHeld, false);
        Arrays.fill(resonancePlateHoldFrames, 0);
        Arrays.fill(resonancePlateReuseFrames, 0);
        Arrays.fill(resonancePlateIndex, -1);
        prisonerRushes.clear();
        mountainPeaks = null;
        switch (Objects.requireNonNull(selectedMap)) {
            case DOCK -> setupDockArena();
            case DESERT -> setupDesertArena();
            case ASHFALL_CATHEDRAL -> setupAshfallCathedralArena();
            case BATTLEFIELD -> {
                double islandW = 1200;
                double islandH = 70;
                double islandX = (WORLD_WIDTH - islandW) / 2.0;
                double islandY = GROUND_Y - 80;
                platforms.add(new Platform(islandX, islandY, islandW, islandH));
                platforms.add(new Platform(islandX + 120, islandY - 260, 360, 45));
                platforms.add(new Platform(islandX + islandW - 480, islandY - 260, 360, 45));
                platforms.add(new Platform(islandX + (islandW - 420) / 2.0, islandY - 420, 420, 45));
                battlefieldIslandX = islandX;
                battlefieldIslandW = islandW;
                battlefieldIslandY = islandY;
            }
            case BEACON_CROWN -> setupBeaconCrownBattlefield();
            case FROSTBITE_FJORD -> setupFrostbiteFjordArena(new Random(74_021L));
            case PRISON -> setupPrisonArena();
            default -> {
                platforms.add(new Platform(0, GROUND_Y, WORLD_WIDTH, 600));
                platforms.add(new Platform(-100, 0, 100, WORLD_HEIGHT));
                platforms.add(new Platform(WORLD_WIDTH, 0, 100, WORLD_HEIGHT));
            }
        }
    }

    private void drawTrailerArena(GraphicsContext g) {
        switch (selectedMap) {
            case DOCK -> drawDockArena(g, true);
            case DESERT -> drawDesertArena(g, true);
            case ASHFALL_CATHEDRAL -> drawAshfallCathedralArena(g, true);
            case BATTLEFIELD -> drawTrailerBattlefieldArena(g);
            case BEACON_CROWN -> drawBeaconCrownBattlefield(g, true);
            case FROSTBITE_FJORD ->  drawFrostbiteFjordArena(g, true);
            case PRISON -> drawPrisonArena(g, true);
            default -> drawForestArena(g, true);
        }
    }

    private void drawTrailerBattlefieldArena(GraphicsContext g) {
        for (int i = 0; i < 520; i++) {
            double ratio = i / 520.0;
            Color c = Color.web("#7EC8FF").interpolate(Color.web("#DFF6F0"), ratio);
            g.setFill(c);
            g.fillRect(0, i * (WORLD_HEIGHT / 520.0), WORLD_WIDTH, WORLD_HEIGHT / 520.0 + 3);
        }

        g.setStroke(Color.web("#3E2723"));
        g.setLineWidth(4);
        for (Platform p : platforms) {
            g.setFill(Color.web("#5D4037"));
            g.fillRoundRect(p.x, p.y, p.w, p.h, 34, 34);
            g.setFill(Color.web("#2E7D32"));
            g.fillRoundRect(p.x + 8, p.y - 12, p.w - 16, p.h + 16, 34, 34);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 34, 34);
        }
    }

    private void drawTrailerParticles(GraphicsContext g) {
        if (!particleEffectsEnabled || g == null) {
            return;
        }
        for (Particle particle : particles) {
            if (particle == null || particle.life <= 0) {
                continue;
            }
            double alpha = Math.clamp(particle.life / 60.0, 0.14, 1.0);
            g.setFill(particle.color.deriveColor(0, 1, 1, alpha));
            g.fillOval(particle.x - 4, particle.y - 4, 8, 8);
        }
    }

    private void triggerTrailerCue(Set<String> firedCues, String key, boolean shouldFire, Runnable action) {
        if (firedCues == null || key == null || key.isBlank() || !shouldFire || action == null) {
            return;
        }
        if (!firedCues.add(key)) {
            return;
        }
        action.run();
    }

    private void triggerTrailerBirdSpecial(Bird bird, boolean fillUltimate) {
        if (bird == null) {
            return;
        }
        if (fillUltimate) {
            bird.gainUltimateFromMinionDamage(999);
        }
        bird.specialCooldown = 0;
        try {
            Method special = Bird.class.getDeclaredMethod("special");
            special.setAccessible(true);
            special.invoke(bird);
        } catch (ReflectiveOperationException ex) {
            throw new IllegalStateException("Unable to trigger trailer special for " + bird.name, ex);
        }
    }

    private BorderPane buildBirdBookContent(BirdBookCategory category) {
        BorderPane content = new BorderPane();
        FlowPane grid = new FlowPane(16, 16);
        grid.setAlignment(Pos.TOP_LEFT);
        grid.setPrefWrapLength(1040);
        grid.setPadding(new Insets(6, 6, 6, 6));

        ScrollPane scroll = new ScrollPane(grid);
        scroll.setFitToWidth(true);
        scroll.setStyle("-fx-background-color: transparent; -fx-background: transparent; -fx-control-inner-background: transparent;");
        scroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
        scroll.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);
        scroll.setPannable(true);
        StackPane gridShell = new StackPane(scroll);
        gridShell.setPadding(new Insets(16));
        gridShell.setMinWidth(0);
        gridShell.setStyle(MenuTheme.panelStyle("#546E7A", 28));

        VBox sidebar = new VBox(16);
        sidebar.setAlignment(Pos.TOP_LEFT);
        sidebar.setFillWidth(true);
        sidebar.setPadding(new Insets(20));
        sidebar.setPrefWidth(500);
        sidebar.setMinHeight(Region.USE_PREF_SIZE);
        sidebar.setStyle(MenuTheme.panelStyle("#607D8B", 22));
        ScrollPane sidebarScroll = getScrollPane(sidebar);

        buildBirdBookGrid(category, grid, sidebar);

        content.setCenter(gridShell);
        content.setRight(sidebarScroll);
        BorderPane.setMargin(sidebarScroll, new Insets(0, 0, 0, 18));
        return content;
    }

    private static ScrollPane getScrollPane(VBox sidebar) {
        ScrollPane sidebarScroll = new ScrollPane(sidebar);
        sidebarScroll.setFitToWidth(true);
        sidebarScroll.setFitToHeight(false);
        sidebarScroll.setPrefWidth(528);
        sidebarScroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
        sidebarScroll.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);
        sidebarScroll.setPannable(true);
        sidebarScroll.setStyle("-fx-background-color: transparent; -fx-background: transparent; -fx-control-inner-background: transparent;");
        return sidebarScroll;
    }

    private void buildBirdBookGrid(BirdBookCategory category, FlowPane grid, VBox sidebar) {
        grid.getChildren().clear();
        sidebar.getChildren().clear();
        switch (category) {
            case ITEMS -> buildBirdBookItemsGrid(grid, sidebar);
            case POWERUPS -> buildBirdBookPowerUpsGrid(grid, sidebar);
            case BIRDS -> buildBirdBookBirdsGrid(grid, sidebar);
            case SKINS -> buildBirdBookSkinsGrid(grid, sidebar);
            case MAPS -> buildBirdBookMapsGrid(grid, sidebar);
        }
    }

    private void buildBirdBookItemsGrid(FlowPane grid, VBox sidebar) {
        Runnable[] initial = new Runnable[1];
        Runnable[] fallback = new Runnable[1];

        for (ItemEntry entry : birdBookItems()) {
            Color accent = entry.powerUp != null ? entry.powerUp.color : Color.web("#FFD54F");
            String label = entry.name + "\nOWNED: " + itemOwnedText(entry);
            Node icon = entry.unlocked
                    ? (entry.isContinue ? buildContinueTileIcon() : (entry.isCoin ? buildCoinTileIcon() : buildPowerUpTileIcon(entry.powerUp)))
                    : buildLockedTileIcon(accent);
            Button tile = createBirdBookTile(grid, label, icon, entry.unlocked, accent,
                    () -> showItemSidebar(sidebar, entry));
            grid.getChildren().add(tile);

            Runnable select = () -> {
                selectBirdBookTile(grid, tile);
                showItemSidebar(sidebar, entry);
            };
            if (fallback[0] == null) fallback[0] = select;
            if (initial[0] == null && entry.unlocked) initial[0] = select;
        }

        if (initial[0] != null) {
            initial[0].run();
        } else if (fallback[0] != null) {
            fallback[0].run();
        }
    }

    private void buildBirdBookBirdsGrid(FlowPane grid, VBox sidebar) {
        Runnable[] initial = new Runnable[1];
        Runnable[] fallback = new Runnable[1];

        for (BirdBookBirdEntry entry : birdBookBirdEntries()) {
            boolean unlocked = entry.unlocked;
            Color accent = mapAccentColor(entry.origin);
            Node icon = unlocked
                    ? buildBirdTileIcon(entry.type, entry.skinKey, entry.origin)
                    : buildLockedTileIcon(accent);
            String label = unlocked
                    ? (entry.displayName.toUpperCase()
                    + (entry.skinKey != null ? "\nBOSS FORM" : ""))
                    : entry.displayName.toUpperCase();
            Button tile = createBirdBookTile(grid, label, icon, unlocked, accent,
                    () -> showBirdSidebar(sidebar, entry));
            grid.getChildren().add(tile);

            Runnable select = () -> {
                selectBirdBookTile(grid, tile);
                showBirdSidebar(sidebar, entry);
            };
            if (fallback[0] == null) fallback[0] = select;
            if (initial[0] == null && unlocked) initial[0] = select;
        }

        if (initial[0] != null) {
            initial[0].run();
        } else if (fallback[0] != null) {
            fallback[0].run();
        }
    }

