    private void showItemSidebar(VBox sidebar, ItemEntry entry) {
        sidebar.getChildren().clear();
        Color accent = entry.powerUp != null ? entry.powerUp.color : Color.web("#FFD54F");
        Label name = bookTitle(entry.name, 30);
        FlowPane meta = featherpediaMetaRow(
                bookStatus(entry.unlocked),
                featherpediaChip(entry.isContinue ? "CONTINUE" : (entry.isCoin ? "COIN" : "PICKUP"), accent)
        );
        sidebar.getChildren().addAll(name, meta);
        if (entry.isCoin || entry.isContinue) {
            sidebar.getChildren().add(featherpediaSection("Inventory", accent,
                    featherpediaBody("Owned: " + itemOwnedText(entry), 18)));
        }
        if (!entry.unlocked) {
            sidebar.getChildren().add(featherpediaSection("Unlock Route", accent,
                    featherpediaBody(entry.howToGet, 18)));
            return;
        }
        Canvas icon = new Canvas(200, 200);
        if (entry.isContinue) {
            drawContinueIcon(icon);
        } else if (entry.isCoin) {
            drawCoinIcon(icon);
        } else if (entry.powerUp != null) {
            drawPowerUpIcon(icon, entry.powerUp);
        }
        sidebar.getChildren().addAll(
                featherpediaSection("Preview", accent, icon),
                featherpediaSection("Overview", accent, featherpediaBody(entry.description, 18)),
                featherpediaSection("Unlock Route", accent, featherpediaBody(entry.howToGet, 16))
        );
    }

    private void showBirdSidebar(VBox sidebar, BirdType type) {
        showBirdSidebar(sidebar, birdBookEntry(type, true));
    }

    private void showBirdSidebar(VBox sidebar, BirdBookBirdEntry entry) {
        sidebar.getChildren().clear();
        boolean unlocked = entry.unlocked;
        Color accent = mapAccentColor(entry.origin);
        Label name = bookTitle(entry.displayName.toUpperCase(), 32);
        BirdType baseBird = featherpediaBaseBird(entry);
        FlowPane meta = featherpediaMetaRow(
                bookStatus(unlocked),
                featherpediaChip(entry.origin.name().replace('_', ' '), accent),
                entry.skinKey != null ? featherpediaChip("BOSS FORM", Color.web("#FFB300")) : null,
                baseBird != null ? featherpediaChip("BASE: " + baseBird.name, Color.web("#90CAF9")) : null,
                entry.skinKey == null && hasTrainingAcademyDrillBadge(entry.type)
                        ? featherpediaChip("ACADEMY BADGE", Color.web("#80DEEA"))
                        : null
        );
        sidebar.getChildren().addAll(name, meta);
        if (!unlocked) {
            sidebar.getChildren().add(featherpediaSection("Unlock Route", accent,
                    featherpediaBody(entry.howToGet, 18)));
            return;
        }
        StackPane art = buildBirdBookArt(entry.type, entry.skinKey, entry.origin);
        VBox loadout = featherpediaSection("Loadout", accent,
                featherpediaBody(entry.statsLine, 18),
                featherpediaBody("Special: " + featherpediaSpecialLine(entry), 18),
                baseBird != null ? featherpediaBody("Base Bird: " + baseBird.name, 16) : null
        );
        GuidedTutorialLesson drillLesson = entry.skinKey == null ? trainingAcademyDrillLessonFor(entry.type) : null;
        Node academySection = drillLesson == null ? null : featherpediaSection("Training Academy", accent,
                featherpediaBody(hasTrainingAcademyDrillBadge(entry.type)
                        ? "Academy Drill Badge: earned."
                        : "Academy Drill Badge: clear " + drillLesson.title + " in Training Mode.",
                        16));
        sidebar.getChildren().addAll(
                featherpediaSection("Preview", accent, art),
                loadout,
                featherpediaSection("Profile", accent, featherpediaBody(entry.description, 17)),
                featherpediaSection("Unlock Route", accent, featherpediaBody(entry.howToGet, 16))
        );
        if (academySection != null) {
            sidebar.getChildren().add(2, academySection);
        }

        List<BirdCompanionEntry> companions = entry.companions;
        if (!companions.isEmpty()) {
            sidebar.getChildren().add(featherpediaSection("Field Notes", accent,
                    featherpediaBody("Select a companion entry for more detail.", 14),
                    buildBirdCompanionTiles(sidebar, entry, companions)));
        }
    }

    private BirdBookBirdEntry birdBookEntry(BirdType type, boolean forceUnlocked) {
        return new BirdBookBirdEntry(
                type,
                type.name,
                null,
                birdFunDescription(type),
                birdHowToGet(type),
                forceUnlocked || isBirdUnlocked(type),
                birdStatsLine(type),
                type.ability,
                originMapForBird(type),
                birdCompanionEntries(type)
        );
    }

    private BirdType featherpediaBaseBird(BirdBookBirdEntry entry) {
        if (entry == null) return null;
        if (NULL_ROCK_VULTURE_SKIN.equals(entry.skinKey)) {
            return BirdType.VULTURE;
        }
        return switch (entry.type) {
            case FALCON -> BirdType.EAGLE;
            case HEISENBIRD -> BirdType.OPIUMBIRD;
            default -> null;
        };
    }

    private String featherpediaSpecialLine(BirdBookBirdEntry entry) {
        if (entry == null) return "";
        return switch (entry.type) {
            case FALCON -> "Precision dive + sweetspot damage";
            case HEISENBIRD -> "Crystal Cloud + Blue Rush + Crystal Column + Glass Cook";
            default -> entry.specialLine;
        };
    }

    private BirdBookBirdEntry nullRockBirdBookEntry() {
        return new BirdBookBirdEntry(
                BirdType.VULTURE,
                "The Null Rock",
                NULL_ROCK_VULTURE_SKIN,
                nullRockBirdBookDescription(),
                "Complete Adventure Chapter 9: Sky of All Wings",
                nullRockVultureUnlocked,
                nullRockBirdBookStatsLine(),
                "Dark Flock + Eye Lasers + Vulture Henchmen + Blood Spear Rain + Void Shell phase armor",
                MapType.BEACON_CROWN,
                nullRockCompanionEntries()
        );
    }

    private List<BirdBookBirdEntry> birdBookBirdEntries() {
        List<BirdBookBirdEntry> entries = new ArrayList<>();
        for (BirdType type : characterSelectBirdOrder()) {
            entries.add(birdBookEntry(type, false));
            if (type == BirdType.VULTURE) {
                entries.add(nullRockBirdBookEntry());
            }
        }
        return entries;
    }

    private static List<BirdType> characterSelectBirdOrder() {
        List<BirdType> ordered = new ArrayList<>(Arrays.asList(BirdType.values()));
        if (ordered.remove(BirdType.HEISENBIRD)) {
            int opiumIndex = ordered.indexOf(BirdType.OPIUMBIRD);
            if (opiumIndex >= 0) {
                ordered.add(opiumIndex + 1, BirdType.HEISENBIRD);
            } else {
                ordered.add(BirdType.HEISENBIRD);
            }
        }
        return ordered;
    }

