    private String skinDescription(String key, BirdType type) {
        if (PREMIUM_PIGEON_SKIN.equals(key)) return "The detailed painted Pigeon atlas, preserved as an optional skin while the original in-engine Pigeon remains the canonical base look.";
        if (OLD_SPARROW_SKIN.equals(key)) return "Old Sparrow as a complete in-engine Titmouse skin: weathered brown feathers, silver crown plumage, a sharp amber eye, and the posture of a bird who has survived every bad route.";
        if ("CITY_PIGEON".equals(key)) return "Gold-plated city swagger for the rooftop boss. Every flap looks expensive and every landing sounds like a coin drop.";
        if ("NOIR_PIGEON".equals(key)) return "Trench-coat noir vibe with a hardboiled stare. Smells like rain, neon, and unfinished business.";
        if (BEACON_PIGEON_SKIN.equals(key)) return "Beacon-lit feathers with a steady glow. The signal chose a keeper and the skyline can feel it.";
        if (STORM_PIGEON_SKIN.equals(key)) return "Slate feathers, lightning scars, and skyline-static eyes. It looks like a rooftop storm decided to become a bird.";
        if (FREEMAN_PIGEON_SKIN.equals(key)) return "A bleary-eyed pigeon with a worn beanie and a constant cigarette. Very addicted to smoking.";
        if (STOCK_PHOTO_EAGLE_SKIN.equals(key)) return "A brutally literal eagle skin. No stylization, no compromise, just a real bird photo entering the bracket like the renderer lost a bet.";
        if (STOCK_PHOTO_TURKEY_SKIN.equals(key)) return "A brutally literal turkey skin with real bird cutouts and a bowl of stuffing for the feast trap. The sprite sheet has fully committed to the bit.";
        if ("SKY_KING_EAGLE".equals(key)) return "Crowned and gilded, a ruler of the highest drafts. The sky feels smaller when this one arrives.";
        if (DUNE_FALCON_SKIN.equals(key)) return "Sandstorm tones and desert grit. A heat-haze blur that hits before you hear it.";
        if (MINT_PENGUIN_SKIN.equals(key)) return "Fresh icy sheen with a minty chill. Slides look cleaner and landings feel colder.";
        if (CIRCUIT_TITMOUSE_SKIN.equals(key)) return "Neon circuits pulse across the feathers. A tiny turbo engine disguised as a bird.";
        if (PRISM_RAZORBILL_SKIN.equals(key)) return "Prismatic edge that refracts every strike. The blade line is beautiful and dangerous.";
        if (SUNFLARE_HUMMINGBIRD_SKIN.equals(key)) return "Sun-hot wings with a citrus glow. The air smells like ozone and nectar when it passes.";
        if (LORE_ACCURATE_HUMMINGBIRD_SKIN.equals(key)) return "A literal hummingbird: tiny emerald body, white belly, ruby throat, needle beak, blurred wings, and directional attacks that point from the beak.";
        if (GLACIER_SHOEBILL_SKIN.equals(key)) return "Ice-blue armor plates and frozen eyes. Every stomp sounds like cracking lake glass.";
        if (NULL_ROCK_VULTURE_SKIN.equals(key)) return "The Crown's ancient true body: a colossal, scarred vulture with ruined wings, a broken divine halo, and a living seal burning through his chest.";
        if (TIDE_VULTURE_SKIN.equals(key)) return "Deep-sea hues with salt-stained edges. It circles like a stormfront rolling in.";
        if (ECLIPSE_MOCKINGBIRD_SKIN.equals(key)) return "Shadow velvet with a violet halo. The lounge feels like a night club after midnight.";
        if (NOVA_PHOENIX_SKIN.equals(key)) return "Star-forged glow with cosmic embers. A living supernova with too much style to burn out.";
        if (ASHEN_SOVEREIGN_PHOENIX_SKIN.equals(key)) return "Black-glass feathers, white-hot crownfire, and cathedral embers orbiting the wings. Only the Ashfall Trial can mark Phoenix like this.";
        if (AURORA_PELICAN_SKIN.equals(key)) return "Polar lights woven into heavy wings. Looks calm, hits like a stormfront.";
        if (IRONCLAD_PELICAN_SKIN.equals(key)) return "Storm-bronze plating, riveted wingguards, and a siege-bird silhouette built to crash through the line.";
        if (UMBRA_BAT_SKIN.equals(key)) return "Void-black membrane with starlit edges. A silent dive that leaves only afterimages.";
        if (RESONANCE_BAT_SKIN.equals(key)) return "Ultrasonic veins glow through the wings, and every flap looks like it should leave a sonar shockwave behind.";
        if (SUNFORGE_ROOSTER_SKIN.equals(key)) return "A first-light warlord with molten crestwork and a sun-stamped brood. Every summoned chick hatches in matching forged colors.";
        if (MIRAGE_ROADRUNNER_SKIN.equals(key)) return "Pale desert feathers, cyan speed marks, and glassy heat-haze trails. Every dash looks like three Roadrunners arrived at once.";
        if (VOID_HERALD_RAVEN_SKIN.equals(key)) return "A black-and-bone herald with a cracked white mask, violet eyes, and feathers that fall like torn pieces of the arena shadow.";
        if (key != null && key.startsWith("CLASSIC_SKIN_")) {
            return "Classic reward skin for " + type.name + ". Earned by clearing a full Classic run and wearing the badge with pride.";
        }
        return "Signature skin.";
    }

    private String skinRarityLabel(String key) {
        if (key == null) return "UNKNOWN";
        switch (key) {
            case DUNE_FALCON_SKIN, SUNFLARE_HUMMINGBIRD_SKIN -> {
                return "COMMON";
            }
            case MINT_PENGUIN_SKIN, GLACIER_SHOEBILL_SKIN -> {
                return "UNCOMMON";
            }
            case "CITY_PIGEON", CIRCUIT_TITMOUSE_SKIN, FREEMAN_PIGEON_SKIN, TIDE_VULTURE_SKIN -> {
                return "RARE";
            }
            case "NOIR_PIGEON", "SKY_KING_EAGLE", PRISM_RAZORBILL_SKIN, ECLIPSE_MOCKINGBIRD_SKIN,
                    STORM_PIGEON_SKIN, RESONANCE_BAT_SKIN, MIRAGE_ROADRUNNER_SKIN -> {
                return "EPIC";
            }
            case BEACON_PIGEON_SKIN, NOVA_PHOENIX_SKIN, AURORA_PELICAN_SKIN, UMBRA_BAT_SKIN, SUNFORGE_ROOSTER_SKIN,
                    NULL_ROCK_VULTURE_SKIN, IRONCLAD_PELICAN_SKIN, VOID_HERALD_RAVEN_SKIN -> {
                return "LEGENDARY";
            }
            case ASHEN_SOVEREIGN_PHOENIX_SKIN, LORE_ACCURATE_HUMMINGBIRD_SKIN,
                    STOCK_PHOTO_EAGLE_SKIN, STOCK_PHOTO_TURKEY_SKIN,
                    PREMIUM_PIGEON_SKIN, OLD_SPARROW_SKIN -> {
                return "UNIQUE";
            }
        }
        if (key.startsWith("CLASSIC_SKIN_")) return "CLASSIC";
        return "SPECIAL";
    }

    private int skinRarityRank(String key) {
        return switch (skinRarityLabel(key)) {
            case "CLASSIC" -> 0;
            case "COMMON" -> 1;
            case "UNCOMMON" -> 2;
            case "RARE" -> 3;
            case "EPIC" -> 4;
            case "LEGENDARY" -> 5;
            case "UNIQUE" -> 6;
            default -> 7;
        };
    }

    private int itemOwnedCount(ItemEntry entry) {
        if (entry == null) return 0;
        if (entry.isCoin) return Math.max(0, birdCoinLedger.balance());
        if (entry.isContinue) return Math.max(0, classicContinues);
        return 0;
    }

    private String itemOwnedText(ItemEntry entry) {
        if (entry != null && entry.isCoin && developerInfiniteBirdCoins) {
            return "INFINITE";
        }
        return Integer.toString(itemOwnedCount(entry));
    }

