        platforms.clear();
        windVents.clear();
        activeArenaGeometryVariant = MapVariant.CROWN_DUEL;

        platforms.add(new Platform(
                CROWN_DUEL_BRIDGE_X,
                CROWN_DUEL_BRIDGE_Y,
                CROWN_DUEL_BRIDGE_W,
                CROWN_DUEL_BRIDGE_H));
