            int optionIndex = i;
            Canvas preview = buildClassicStagePreview(option, 330, 175);
            Label name = new Label(option.name.toUpperCase(Locale.ROOT));
            name.setFont(Font.font("Arial Black", 23));
            name.setTextFill(Color.WHITE);
