        g.setLineWidth(8.0);
        g.strokePolyline(new double[]{-170, -72, -28, -10, -88},
                new double[]{20, -82, -55, 72, 104}, 5);
        g.strokePolyline(new double[]{170, 72, 28, 10, 88},
                new double[]{20, -82, -55, 72, 104}, 5);
