    void applyRazorbillArenaRuntimeEffects() {
        if (matchEnded) return;
        if (selectedMap == MapType.GLASSWIND_CAUSEWAY) {
            applyGlasswindCrosswind();
            return;
        }
        if (activeArenaGeometryVariant == MapVariant.OBSIDIAN_FOUNDRY) {
            applyObsidianFoundryPresses();
            return;
        }
        if (selectedMap != MapType.WORLDSEAM) return;
        for (int slot = 0; slot < activePlayers; slot++) {
            if (worldseamGateCooldowns[slot] > 0) worldseamGateCooldowns[slot]--;
            Bird bird = players[slot];
            if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget
                    || worldseamGateCooldowns[slot] > 0) continue;
            double cx = bird.bodyCenterX();
            double cy = bird.bodyCenterY();
            boolean left = Math.pow((cx - WORLDSEAM_LEFT_GATE_X) / WORLDSEAM_GATE_RADIUS_X, 2.0)
                    + Math.pow((cy - WORLDSEAM_GATE_Y) / WORLDSEAM_GATE_RADIUS_Y, 2.0) <= 1.0;
            boolean right = Math.pow((cx - WORLDSEAM_RIGHT_GATE_X) / WORLDSEAM_GATE_RADIUS_X, 2.0)
                    + Math.pow((cy - WORLDSEAM_GATE_Y) / WORLDSEAM_GATE_RADIUS_Y, 2.0) <= 1.0;
            if (!left && !right) continue;
            double destination = left ? WORLDSEAM_RIGHT_GATE_X : WORLDSEAM_LEFT_GATE_X;
            double exitOffsetY = Math.clamp(cy - WORLDSEAM_GATE_Y,
                    -WORLDSEAM_GATE_RADIUS_Y * 0.70, WORLDSEAM_GATE_RADIUS_Y * 0.70);
            bird.x = destination - bird.bodyWidth() * 0.5 + (left ? 165.0 : -165.0);
            bird.y = WORLDSEAM_GATE_Y + exitOffsetY - bird.bodyHeight() * 0.5;
            bird.prevX = bird.x;
            bird.prevY = bird.y;
            worldseamGateCooldowns[slot] = WORLDSEAM_GATE_COOLDOWN_FRAMES;
            playManagedSfxVaried(steamAchievementClip, 0.24, left ? 1.28 : 1.06, 0.0);
        }
    }

    int glasswindGustPhase() {
        return Math.floorMod((int) (simTick % GLASSWIND_GUST_CYCLE_FRAMES),
                GLASSWIND_GUST_CYCLE_FRAMES);
    }

    boolean isGlasswindGustWarning() {
        int phase = glasswindGustPhase();
        return phase >= GLASSWIND_GUST_WARNING_FRAME && phase < GLASSWIND_GUST_ACTIVE_FRAME;
    }

    boolean isGlasswindGustActive() {
        int phase = glasswindGustPhase();
        return phase >= GLASSWIND_GUST_ACTIVE_FRAME && phase < GLASSWIND_GUST_END_FRAME;
    }

    int glasswindGustDirection() {
        return ((simTick / GLASSWIND_GUST_CYCLE_FRAMES) & 1L) == 0L ? 1 : -1;
    }

    private void applyGlasswindCrosswind() {
        if (!isGlasswindGustActive()) return;
        int direction = glasswindGustDirection();
        for (int slot = 0; slot < activePlayers; slot++) {
            Bird bird = players[slot];
            if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget
                    || bird.bodyCenterY() > battlefieldIslandY + 70.0) continue;
            double altitude = Math.clamp((battlefieldIslandY - bird.bodyCenterY()) / 900.0, 0.0, 1.0);
            double exposure = bird.isOnGround()
                    ? GLASSWIND_GROUNDED_GUST_MULTIPLIER
                    : 0.84 + altitude * 0.30;
            bird.vx = Math.clamp(bird.vx + direction * 0.14 * exposure, -15.5, 15.5);
        }
    }

    int obsidianPressPhase(int pressIndex) {
        if (pressIndex < 0 || pressIndex >= OBSIDIAN_PRESS_X.length) return 0;
        long offset = pressIndex * (OBSIDIAN_PRESS_CYCLE_FRAMES / OBSIDIAN_PRESS_X.length);
        return Math.floorMod((int) ((simTick + offset) % OBSIDIAN_PRESS_CYCLE_FRAMES),
                OBSIDIAN_PRESS_CYCLE_FRAMES);
    }

    boolean isObsidianPressWarning(int pressIndex) {
        int phase = obsidianPressPhase(pressIndex);
        return phase >= OBSIDIAN_PRESS_WARNING_FRAME && phase < OBSIDIAN_PRESS_ACTIVE_FRAME;
    }

    boolean isObsidianPressActive(int pressIndex) {
        int phase = obsidianPressPhase(pressIndex);
        return phase >= OBSIDIAN_PRESS_ACTIVE_FRAME && phase < OBSIDIAN_PRESS_END_FRAME;
    }

    private void applyObsidianFoundryPresses() {
        for (int slot = 0; slot < activePlayers; slot++) {
            if (obsidianPressHitCooldowns[slot] > 0) obsidianPressHitCooldowns[slot]--;
        }
        for (int press = 0; press < OBSIDIAN_PRESS_X.length; press++) {
            if (!isObsidianPressActive(press)) continue;
            double pressX = OBSIDIAN_PRESS_X[press];
            for (int slot = 0; slot < activePlayers; slot++) {
                Bird bird = players[slot];
                if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget
                        || obsidianPressHitCooldowns[slot] > 0
                        || Math.abs(bird.bodyCenterX() - pressX) > 205.0
                        || bird.bodyCenterY() < battlefieldIslandY - 300.0
                        || bird.bodyCenterY() > battlefieldIslandY + 90.0) continue;
                double dealt = bird.receiveExternalDamage(8.0);
                double side = Math.signum(bird.bodyCenterX() - pressX);
                if (side == 0.0) side = (slot & 1) == 0 ? -1.0 : 1.0;
                bird.applyExternalDamageScaledLaunch(side * 8.5, -6.5, dealt);
                obsidianPressHitCooldowns[slot] = 50;
                shakeIntensity = Math.max(shakeIntensity, 13.0);
                playManagedSfxVaried(hugewaveClip, 0.30, 0.72 + press * 0.06, 0.0);
            }
        }
    }

    void applyRazorbillClassicRuntimeEffects() {
        if (!classicModeActive || classicEncounter == null || classicSelectedBird != BirdType.RAZORBILL
                || bossRushModeActive || ashfallTrialModeActive || matchEnded) return;
        Bird player = players[0];
        if (player == null || !playerHasStocksRemaining(0)) return;
        if (classicRazorbillAttackHitCooldown > 0) classicRazorbillAttackHitCooldown--;
        if (classicSeamreaverHitCooldown > 0) classicSeamreaverHitCooldown--;

        boolean attackHeld = isAttackPressed(0);
        boolean newStrike = attackHeld && !classicRazorbillAttackWasHeld
                && classicRazorbillAttackHitCooldown == 0;
        classicRazorbillAttackWasHeld = attackHeld;
        if (newStrike) {
            closeNearbyRazorbillAnchor(player);
            if (classicEncounter.style == ClassicEncounterStyle.BETWEEN_LINES
                    && classicRazorbillBonusReady
                    && Math.hypot(player.bodyCenterX() - 3_000.0,
                    player.bodyCenterY() - (battlefieldIslandY - 170.0)) <= 290.0) {
                completeRazorbillBetweenLines();
            }
        }

        switch (classicEncounter.style) {
            case RAZORBILL_REFLECTION -> updateRazorbillReflection(player);
            case BETWEEN_LINES -> updateRazorbillBetweenLines(player);
            case SEAM_WARDEN_GAUNTLET -> updateRazorbillSeamWarden(player);
            case SEAMREAVER_BOSS -> updateRazorbillSeamreaver(player);
            default -> updateClassicSeamShards(player);
        }
    }

    private void closeNearbyRazorbillAnchor(Bird player) {
        for (ClassicRiftAnchor anchor : classicRiftAnchors) {
            if (anchor.closed || Math.hypot(player.bodyCenterX() - anchor.x,
                    player.bodyCenterY() - anchor.y) > 260.0) continue;
            anchor.closed = true;
            anchor.pulseFrames = 32;
            classicRazorbillSeals[anchor.sealIndex] = true;
            classicRazorbillAttackHitCooldown = 12;
            classicBonusCoins += 15;
            classicRunScore += 1_500;
            playClassicNectarRingSfx(anchor.sealIndex + 1, 3);
            addToKillFeed("RIFT ANCHOR SEALED! Bird Coins +15.");
        }
    }

    private void updateRazorbillReflection(Bird player) {
        if (--classicRazorbillReflectionTimer == 80) {
            classicRazorbillReflectionTargetX = player.bodyCenterX();
            classicRazorbillReflectionTargetY = player.bodyCenterY();
            addToKillFeed("PRISM ECHO: move away from your recorded line.");
        }
        if (classicRazorbillReflectionTimer == 32) {
            boolean horizontal = Math.abs(player.bodyCenterY() - classicRazorbillReflectionTargetY) < 135.0;
            boolean vertical = Math.abs(player.bodyCenterX() - classicRazorbillReflectionTargetX) < 150.0;
            if (horizontal || vertical) {
                double dealt = player.receiveExternalDamage(7.0);
                player.applyExternalDamageScaledLaunch(
                        Math.signum(player.bodyCenterX() - 3_000.0) * 8.0, -6.0, dealt);
                shakeIntensity = Math.max(shakeIntensity, 10.0);
            }
        }
        if (classicRazorbillReflectionTimer <= 0) classicRazorbillReflectionTimer = 170;
        updateClassicSeamShards(player);
    }

    private void updateRazorbillBetweenLines(Bird player) {
        if (classicRazorbillBonusReady) return;
        if (classicRazorbillBonusPatternTimer > 0) classicRazorbillBonusPatternTimer--;
        if (classicRazorbillBonusPatternTimer == 42) {
            int safeLane = RAZORBILL_BONUS_SAFE_LANES[classicRazorbillBonusPatternIndex];
            int playerLane = Math.clamp((int) ((player.bodyCenterX() - 900.0) / 1_050.0), 0, 3);
            if (playerLane != safeLane) {
                double dealt = player.receiveExternalDamage(10.0);
                player.applyExternalDamageScaledLaunch(playerLane < safeLane ? -8.0 : 8.0, -7.0, dealt);
                shakeIntensity = Math.max(shakeIntensity, 15.0);
                playManagedSfxVaried(hugewaveClip, 0.36, 1.22, 0.0);
            } else {
                classicRunScore += 500;
                playClassicNectarRingSfx(classicRazorbillBonusPatternIndex + 1, 4);
            }
        }
        if (classicRazorbillBonusPatternTimer <= 0) {
            classicRazorbillBonusPatternIndex++;
            classicRazorbillBonusPatternTimer = 150;
            if (classicRazorbillBonusPatternIndex >= RAZORBILL_BONUS_SAFE_LANES.length) {
                classicRazorbillBonusReady = true;
                addToKillFeed("THE ANCHOR IS EXPOSED — strike the center seal!");
            }
        }
    }

    boolean registerRazorbillBonusAnchorStrike() {
        if (!isClassicBetweenLinesActive() || !classicRazorbillBonusReady) return false;
        completeRazorbillBetweenLines();
        return true;
    }

    private void completeRazorbillBetweenLines() {
        if (!isClassicBetweenLinesActive()) return;
        classicBonusCoins += 75;
        classicRunScore += 5_000;
        addToKillFeed("BETWEEN THE LINES COMPLETE! Bird Coins +75.");
        playClassicNectarRingSfx(4, 4);
        matchController.triggerMatchEnd(players[0]);
    }

    boolean isClassicBetweenLinesActive() {
        return classicModeActive && !bossRushModeActive && !ashfallTrialModeActive
                && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.BETWEEN_LINES
                && !matchEnded;
    }

    void finishClassicBetweenLinesFromTimeout() {
        if (!isClassicBetweenLinesActive()) return;
        addToKillFeed("TIME! The Worldseam closes before the last line is crossed.");
        matchController.triggerMatchEnd(null);
    }

    boolean isClassicSeamWardenActive() {
        return classicModeActive && !bossRushModeActive && !ashfallTrialModeActive
                && classicSelectedBird == BirdType.RAZORBILL
                && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.SEAM_WARDEN_GAUNTLET
                && !matchEnded;
    }

    void finishClassicSeamWardenFromTimeout() {
        if (!isClassicSeamWardenActive()) return;
        addToKillFeed("TIME! The remaining Seam Warden seals the Worldseam.");
        matchController.triggerMatchEnd(firstClassicEnemyWithStocks());
    }

    private void updateRazorbillSeamWarden(Bird player) {
        Bird warden = firstClassicEnemyWithStocks();
        if (warden == null) return;
        // The construct's ordinary attacks remain the main threat. Telegraph
        // shards punctuate each wave instead of forming a near-continuous
        // screen lock that the navigation AI (and new players) cannot route.
        int cadence = Math.max(104, 154 - classicRazorbillWaveIndex * 14);
        if ((simTick + 30L) % cadence == 0L) {
            spawnRazorbillPattern(warden, player, classicRazorbillWaveIndex, 0.58);
        }
        updateClassicSeamShards(player);
    }

    private void updateRazorbillSeamreaver(Bird player) {
        Bird boss = firstClassicEnemyWithStocks();
        if (boss == null) return;
        if (boss.health <= 0.0) {
            onClassicStaminaBossDefeated(boss, null);
            return;
        }
        int nextPhase = hollowMaestroPhaseForHealth(boss.health, boss.getMaxHealth());
        if (nextPhase > classicSeamreaverPhase) {
            int crossed = nextPhase - classicSeamreaverPhase;
            classicSeamreaverPhase = nextPhase;
            player.heal(12.0 * crossed);
            classicSeamreaverAttackTimer = 108;
            addToKillFeed(classicSeamreaverPhase == 1
                    ? "SECOND DIVISION: diagonal seams awaken. 12% repaired."
                    : "ZERO DIVIDE: every axis is armed. 12% repaired.");
        }
        steerRazorbillConstruct(boss, classicSeamreaverPhase + 1);
        if (classicSeamreaverBurstWindow > 0 && --classicSeamreaverBurstWindow == 0) {
            classicSeamreaverBurstDamage = 0.0;
        }
        if (classicSeamreaverGuardCooldown > 0) classicSeamreaverGuardCooldown--;
        if (classicSeamreaverGuardTimer > 0) {
            classicSeamreaverGuardTimer--;
            if (classicSeamreaverGuardTimer == SEAMREAVER_GUARD_IMPACT_FRAME) {
                double distance = Math.hypot(player.bodyCenterX() - boss.bodyCenterX(),
                        player.bodyCenterY() - boss.bodyCenterY());
                if (distance < 520.0) {
                    double dealt = player.receiveExternalDamage(7.0 + classicSeamreaverPhase * 2.0);
                    player.applyExternalDamageScaledLaunch(
                            Math.signum(player.bodyCenterX() - boss.bodyCenterX()) * 13.0,
                            -8.0, dealt);
                }
            }
        } else if (--classicSeamreaverAttackTimer <= 0) {
            classicSeamreaverAttackKind = (classicSeamreaverAttackKind + 1) % 3;
            classicSeamreaverFlightWaypoint = (classicSeamreaverFlightWaypoint + 1)
                    % SEAMREAVER_FLIGHT_X.length;
            classicSeamreaverTargetX = player.bodyCenterX();
            classicSeamreaverTargetY = player.bodyCenterY();
            spawnRazorbillPattern(boss, player, classicSeamreaverAttackKind,
                    1.0 + classicSeamreaverPhase * 0.16);
            classicSeamreaverAttackTimer = Math.max(68, 112 - classicSeamreaverPhase * 15);
        }
        updateClassicSeamShards(player);
    }

    private void steerRazorbillConstruct(Bird construct, int phase) {
        int waypoint = Math.floorMod(classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS
                ? classicSeamreaverFlightWaypoint : classicRazorbillWaveIndex,
                SEAMREAVER_FLIGHT_X.length);
        double targetX = SEAMREAVER_FLIGHT_X[waypoint];
        double targetY = SEAMREAVER_FLIGHT_Y[waypoint];
        double maxSpeed = 5.0 + phase * 0.65;
        steerRazorbillConstructToward(construct, targetX, targetY, maxSpeed);
    }

    private void steerRazorbillConstructToward(Bird construct, double targetX, double targetY,
                                                double maxSpeed) {
        construct.vx += (Math.clamp((targetX - construct.bodyCenterX()) * 0.018,
                -maxSpeed, maxSpeed) - construct.vx) * 0.20;
        construct.vy += (Math.clamp((targetY - construct.bodyCenterY()) * 0.024,
                -maxSpeed, maxSpeed) - construct.vy) * 0.24 - GRAVITY * 0.78;
        construct.vx = Math.clamp(construct.vx, -maxSpeed, maxSpeed);
        construct.vy = Math.clamp(construct.vy, -maxSpeed, maxSpeed);
    }

    private void spawnRazorbillPattern(Bird source, Bird player, int kind, double power) {
        double sx = source.bodyCenterX();
        double sy = source.bodyCenterY();
        int count = kind == 2 ? 7 : 5;
        for (int i = 0; i < count; i++) {
            double vx;
            double vy;
            if (kind == 0) {
                vx = Math.signum(player.bodyCenterX() - sx) * (9.5 + i * 0.45) * power;
                vy = (i - (count - 1) / 2.0) * 1.3;
            } else if (kind == 1) {
                vx = (i - (count - 1) / 2.0) * 1.35;
                vy = Math.signum(player.bodyCenterY() - sy) * (8.5 + i * 0.35) * power;
            } else {
                double angle = -0.85 + i * 1.70 / Math.max(1, count - 1);
                double direction = Math.signum(player.bodyCenterX() - sx);
                vx = Math.cos(angle) * direction * 10.5 * power;
                vy = Math.sin(angle) * 10.5 * power;
            }
            classicSeamShards.add(new ClassicSeamShard(sx, sy, vx, vy, 210,
                    classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS
                            ? classicSeamreaverPhase : classicRazorbillWaveIndex));
        }
        playManagedSfxVaried(hugewaveClip, 0.34, 1.04 + kind * 0.10, 0.0);
    }

    private void updateClassicSeamShards(Bird player) {
        for (int i = classicSeamShards.size() - 1; i >= 0; i--) {
            ClassicSeamShard shard = classicSeamShards.get(i);
            shard.x += shard.vx;
            shard.y += shard.vy;
            shard.life--;
            if (Math.hypot(player.bodyCenterX() - shard.x, player.bodyCenterY() - shard.y)
                    <= player.combatRadius() + 28.0 && classicSeamreaverHitCooldown == 0) {
                boolean bossShard = classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS;
                double dealt = player.receiveExternalDamage(bossShard
                        ? 4.5 + shard.phase * 1.1 : 2.0 + shard.phase * 0.40);
                player.applyExternalDamageScaledLaunch(
                        Math.signum(shard.vx) * (bossShard ? 6.0 + shard.phase : 3.3 + shard.phase * 0.4),
                        bossShard ? -4.5 - shard.phase * 0.5 : -2.8 - shard.phase * 0.20, dealt);
                classicSeamreaverHitCooldown = 12;
                classicSeamShards.remove(i);
            } else if (shard.life <= 0 || shard.x < -250.0 || shard.x > WORLD_WIDTH + 250.0
                    || shard.y < -250.0 || shard.y > WORLD_HEIGHT + 250.0) {
                classicSeamShards.remove(i);
            }
        }
    }

    private void setupHummingbirdNectarRoute(ClassicEncounter encounter) {
        classicNectarRings.clear();
        classicNectarRingIndex = 0;
        classicHummingbirdDashCompleted = false;
        classicBlightPollen.clear();
        classicHeartbloomPollenHitCooldown = 0;
        if (!classicModeActive || bossRushModeActive || ashfallTrialModeActive
                || classicSelectedBird != BirdType.HUMMINGBIRD || encounter == null) {
            return;
        }
        if (encounter.style == ClassicEncounterStyle.NECTAR_DASH) {
            double[][] gates = {
                    {800, GROUND_Y - 720}, {1_180, GROUND_Y - 1_080}, {1_620, GROUND_Y - 720},
                    {2_020, GROUND_Y - 1_300}, {2_430, GROUND_Y - 850}, {2_820, GROUND_Y - 1_520},
                    {3_200, GROUND_Y - 960}, {3_610, GROUND_Y - 1_300}, {4_020, GROUND_Y - 720},
                    {4_410, GROUND_Y - 1_150}, {4_830, GROUND_Y - 820}, {5_230, GROUND_Y - 1_180}
            };
            for (double[] gate : gates) classicNectarRings.add(new ClassicNectarRing(gate[0], gate[1], 82));
            addToKillFeed("HUNDRED-FLOWER DASH: follow all 12 gates in order. Falling resets your position.");
            return;
        }
        if (encounter.style == ClassicEncounterStyle.BLIGHTWING_BOSS) {
            addToKillFeed("HEARTBLOOM: " + classicHummingbirdBlossomCount()
                    + " banked blossoms have awakened recovery flowers.");
            return;
        }
        if (classicRoundIndex < 0 || classicRoundIndex >= 6
                || classicHummingbirdBlossoms[classicRoundIndex]) {
            return;
        }
        double[][][] routes = {
                {{1_250, GROUND_Y - 620}, {2_850, GROUND_Y - 1_020}, {4_600, GROUND_Y - 680}},
                {{1_100, GROUND_Y - 850}, {3_000, GROUND_Y - 1_360}, {4_820, GROUND_Y - 820}},
                {{1_160, GROUND_Y - 780}, {3_040, GROUND_Y - 1_220}, {4_750, GROUND_Y - 720}},
                {{1_200, GROUND_Y - 680}, {3_000, GROUND_Y - 1_180}, {4_740, GROUND_Y - 680}},
                {{1_100, GROUND_Y - 820}, {3_000, GROUND_Y - 1_650}, {4_850, GROUND_Y - 820}},
                {{1_280, GROUND_Y - 650}, {3_000, GROUND_Y - 1_100}, {4_680, GROUND_Y - 650}}
        };
        for (double[] gate : routes[classicRoundIndex]) {
            classicNectarRings.add(new ClassicNectarRing(gate[0], gate[1], 74));
        }
        addToKillFeed("NECTAR CHAIN: fly through all three flower rings in order to bank this round's blossom.");
    }

    private void applyHummingbirdClassicRuntimeEffects() {
        if (!classicModeActive || classicEncounter == null || classicSelectedBird != BirdType.HUMMINGBIRD
                || matchEnded) return;
        Bird player = players[0];
        if (player == null || player.health <= 0.0) return;

        if (classicNectarRingIndex < classicNectarRings.size()) {
            ClassicNectarRing ring = classicNectarRings.get(classicNectarRingIndex);
            double dx = player.bodyCenterX() - ring.x;
            double dy = player.bodyCenterY() - ring.y;
            if (dx * dx + dy * dy <= ring.radius * ring.radius) {
                ring.collected = true;
                classicNectarRingIndex++;
                playClassicNectarRingSfx(classicNectarRingIndex, classicNectarRings.size());
                classicRunScore += 350;
                addToKillFeed("FLOWER GATE " + classicNectarRingIndex + "/" + classicNectarRings.size());
                if (classicNectarRingIndex >= classicNectarRings.size()) {
                    completeHummingbirdNectarChain();
                }
            }
        }

        if ("Poison in the Pollen".equals(classicEncounter.name) && simTick > 0 && simTick % 240 == 0
                && classicNectarRingIndex < classicNectarRings.size()) {
            ClassicNectarRing ring = classicNectarRings.get(classicNectarRingIndex);
            classicBlightPollen.add(new ClassicBlightPollen(ring.x, ring.y, 0.0, 0.0, 135));
        }
        if (classicEncounter.style == ClassicEncounterStyle.BLIGHTWING_BOSS) {
            applyBlightwingRuntimeEffects(player);
        }
        updateClassicBlightPollen(player);
    }

    private void completeHummingbirdNectarChain() {
        if (classicEncounter.style == ClassicEncounterStyle.NECTAR_DASH) {
            classicHummingbirdDashCompleted = true;
            if (!classicHummingbirdBlossoms[6]) {
                classicHummingbirdBlossoms[6] = true;
                classicBonusCoins += 75;
                classicRunScore += 5_000;
            }
            addToKillFeed("HUNDRED-FLOWER DASH COMPLETE! Final blossom banked. Bird Coins +75.");
            matchController.triggerMatchEnd(players[0]);
            return;
        }
        if (classicRoundIndex >= 0 && classicRoundIndex < 6 && !classicHummingbirdBlossoms[classicRoundIndex]) {
            classicHummingbirdBlossoms[classicRoundIndex] = true;
            classicBonusCoins += 15;
            classicRunScore += 1_500;
            addToKillFeed("BLOSSOM BANKED! The final sanctuary grows stronger. Bird Coins +15.");
        }
    }

    private void applyBlightwingRuntimeEffects(Bird player) {
        Bird blightwing = null;
        for (Bird bird : players) {
            if (bird != null && getEffectiveTeam(bird.playerIndex) == 2 && bird.type == BirdType.RAVEN) {
                blightwing = bird;
                break;
            }
        }
        if (blightwing == null) return;

        if (simTick > 0 && simTick % 165 == 0) {
            double dx = player.bodyCenterX() - blightwing.bodyCenterX();
            double dy = player.bodyCenterY() - blightwing.bodyCenterY();
            double length = Math.max(1.0, Math.hypot(dx, dy));
            for (int fan = -1; fan <= 1; fan++) {
                double vx = dx / length * 7.2 - dy / length * fan * 0.9;
                double vy = dy / length * 7.2 + dx / length * fan * 0.9;
                classicBlightPollen.add(new ClassicBlightPollen(
                        blightwing.bodyCenterX(), blightwing.bodyCenterY(), vx, vy, 180));
            }
        }

        int divePhase = (int) (simTick % 330);
        if (divePhase >= 115 && divePhase <= 138 && !blightwing.isOnGround()) {
            blightwing.vx = Math.clamp((player.bodyCenterX() - blightwing.bodyCenterX()) * 0.035, -14.0, 14.0);
            blightwing.vy = Math.max(blightwing.vy, 10.5);
        }

        int closurePhase = (int) (simTick % 420);
        if (closurePhase == 0 && classicClosedHeartbloomPetal == null && !classicHeartbloomPetals.isEmpty()) {
            classicHeartbloomClosureIndex = (int) ((simTick / 420) % classicHeartbloomPetals.size());
            Platform petal = classicHeartbloomPetals.get(classicHeartbloomClosureIndex);
            if (platforms.remove(petal)) {
                classicClosedHeartbloomPetal = petal;
                addToKillFeed("BLIGHTWING: a Heartbloom petal has wilted shut.");
            }
        } else if (closurePhase == 150 && classicClosedHeartbloomPetal != null) {
            if (!platforms.contains(classicClosedHeartbloomPetal)) platforms.add(classicClosedHeartbloomPetal);
            classicClosedHeartbloomPetal = null;
        }
    }

    private void updateClassicBlightPollen(Bird player) {
        if (classicHeartbloomPollenHitCooldown > 0) classicHeartbloomPollenHitCooldown--;
        Iterator<ClassicBlightPollen> iterator = classicBlightPollen.iterator();
        while (iterator.hasNext()) {
            ClassicBlightPollen pollen = iterator.next();
            pollen.x += pollen.vx;
            pollen.y += pollen.vy;
            pollen.life--;
            if (pollen.life <= 0) {
                iterator.remove();
                continue;
            }
            double dx = player.bodyCenterX() - pollen.x;
            double dy = player.bodyCenterY() - pollen.y;
            double hitRadius = pollen.vx == 0.0 && pollen.vy == 0.0 ? 115.0 : 44.0;
            if (classicHeartbloomPollenHitCooldown <= 0 && dx * dx + dy * dy <= hitRadius * hitRadius) {
                player.receiveExternalDamage(pollen.vx == 0.0 ? 3.0 : 7.0);
                player.vx = Math.clamp(player.vx + Math.copySign(4.2, dx == 0.0 ? 1.0 : dx), -18.0, 18.0);
                player.vy = Math.min(player.vy, -4.5);
                player.applyStun(10.0);
                classicHeartbloomPollenHitCooldown = 28;
                iterator.remove();
            }
        }
    }

    private void drawClassicHummingbirdRouteFeatures(GraphicsContext g) {
        if (!classicModeActive || classicSelectedBird != BirdType.HUMMINGBIRD || classicEncounter == null) return;
        drawClassicNectarGuideMarker(g);
        for (int i = 0; i < classicNectarRings.size(); i++) {
            ClassicNectarRing ring = classicNectarRings.get(i);
            if (ring.collected) continue;
            boolean next = i == classicNectarRingIndex;
            g.setStroke(Color.web(next ? "#FFF176" : "#7CE8C6", next ? 0.96 : 0.34));
            g.setLineWidth(next ? 13.0 : 7.0);
            g.strokeOval(ring.x - ring.radius, ring.y - ring.radius, ring.radius * 2.0, ring.radius * 2.0);
            g.setFill(Color.web(next ? "#FF70C5" : "#75DDBB", next ? 0.72 : 0.26));
            for (int petal = 0; petal < 8; petal++) {
                double angle = petal * Math.PI / 4.0;
                double px = ring.x + Math.cos(angle) * ring.radius;
                double py = ring.y + Math.sin(angle) * ring.radius;
                g.fillOval(px - 19, py - 13, 38, 26);
            }
        }
        for (ClassicBlightPollen pollen : classicBlightPollen) {
            double radius = pollen.vx == 0.0 && pollen.vy == 0.0 ? 110.0 : 34.0;
            g.setFill(Color.web("#120816", 0.64));
            g.fillOval(pollen.x - radius, pollen.y - radius, radius * 2.0, radius * 2.0);
            g.setStroke(Color.web("#9C4D8C", 0.65));
            g.setLineWidth(4.0);
            g.strokeOval(pollen.x - radius, pollen.y - radius, radius * 2.0, radius * 2.0);
        }
        if (classicClosedHeartbloomPetal != null) {
            Platform p = classicClosedHeartbloomPetal;
            g.setFill(Color.web("#25142A", 0.88));
            g.fillRoundRect(p.x, p.y, p.w, p.h, 70, 70);
            g.setStroke(Color.web("#75446D"));
            g.setLineWidth(7.0);
            g.strokeRoundRect(p.x, p.y, p.w, p.h, 70, 70);
        }
    }

    private void drawClassicNectarGuideMarker(GraphicsContext g) {
        if (classicNectarRingIndex < 0 || classicNectarRingIndex >= classicNectarRings.size()) return;
        Bird player = players[0];
        if (player == null || player.health <= 0.0) return;

        ClassicNectarRing next = classicNectarRings.get(classicNectarRingIndex);
        double playerX = player.bodyCenterX();
        double playerY = player.bodyCenterY();
        double dx = next.x - playerX;
        double dy = next.y - playerY;
        double distance = Math.hypot(dx, dy);
        if (distance < 1.0) return;

        double ux = dx / distance;
        double uy = dy / distance;
        double markerDistance = Math.clamp(distance * 0.22, 92.0, 142.0);
        double markerX = playerX + ux * markerDistance;
        double markerY = playerY + uy * markerDistance;
        double angle = Math.atan2(dy, dx);

        g.save();
        g.translate(markerX, markerY);
        g.rotate(Math.toDegrees(angle));
        g.setFill(Color.web("#09120F", 0.72));
        g.fillOval(-34, -34, 68, 68);
        g.setStroke(Color.web("#FFF176", 0.96));
        g.setLineWidth(4.0);
        g.strokeOval(-31, -31, 62, 62);

        g.setFill(Color.web("#FF70C5", 0.92));
        for (int petal = 0; petal < 6; petal++) {
            double petalAngle = petal * Math.PI / 3.0;
            double px = Math.cos(petalAngle) * 15.0;
            double py = Math.sin(petalAngle) * 15.0;
            g.fillOval(px - 7.5, py - 5.5, 15.0, 11.0);
        }
        g.setFill(Color.web("#FFF59D"));
        g.fillOval(-6.5, -6.5, 13.0, 13.0);
        g.fillPolygon(new double[]{26, 49, 26}, new double[]{-13, 0, 13}, 3);
        g.restore();
    }

    private void setupTurkeyClassicRoute(ClassicEncounter encounter) {
        classicTurkeyWaveIndex = 0;
        classicTurkeyFeastDecisionActive = false;
        classicTurkeyFeastDecisionFrames = 0;
        classicTurkeyBlockWasDown = false;
        classicTurkeyStuffedFrames = 0;
        classicTurkeyFamineFrames = 0;
        classicHarvestPlate = null;
        classicTurkeyDefenseWaveIndex = 0;
        classicTurkeyDefenseHealth = 100;
        classicTurkeyDefenseCompleted = false;
        classicDevourerMeals = 0;
        classicDevourerTrapCooldown = 0;
        classicDevourerSuctionPhaseActive = false;
        classicDevourerFinalPhaseActive = false;
        if (!classicModeActive || bossRushModeActive || ashfallTrialModeActive
                || classicSelectedBird != BirdType.TURKEY || encounter == null) {
            return;
        }
        switch (encounter.style) {
            case FEAST_GAUNTLET -> addToKillFeed(
                    "FEAST OR FAMINE: touch the plate to heal, or press BLOCK to reject it and gain a battle rush.");
            case HARVEST_DEFENSE -> addToKillFeed(
                    "HARVEST WATCH: defend the central feast through all four raider waves.");
            case DEVOURER_BOSS -> addToKillFeed(
                    "THE GREAT HUNGER: deny the offerings and lure The Devourer into Turkey's feast traps.");
            default -> {
            }
        }
    }

    void applyTurkeyClassicRuntimeEffects() {
        if (!classicModeActive || classicEncounter == null || classicSelectedBird != BirdType.TURKEY
                || bossRushModeActive || ashfallTrialModeActive || matchEnded) {
            return;
        }
        Bird player = players[0];
        if (player == null || player.health <= 0.0 || !playerHasStocksRemaining(0)) return;

        if (classicTurkeyStuffedFrames > 0) {
            classicTurkeyStuffedFrames--;
            player.turkeyStuffedTimer = Math.max(player.turkeyStuffedTimer, 2);
            if (player.shrinkTimer <= 0 && player.titanTimer <= 0) {
                player.sizeMultiplier = Math.max(player.sizeMultiplier, player.baseSizeMultiplier * 1.12);
            }
            if (classicTurkeyStuffedFrames == 0 && player.shrinkTimer <= 0 && player.titanTimer <= 0) {
                player.sizeMultiplier = player.baseSizeMultiplier;
            }
        }
        if (classicTurkeyFamineFrames > 0) {
            classicTurkeyFamineFrames--;
            player.powerMultiplier = Math.max(player.powerMultiplier, player.basePowerMultiplier * 1.10);
            player.speedMultiplier = Math.max(player.speedMultiplier, player.baseSpeedMultiplier * 1.16);
        }

        switch (classicEncounter.style) {
            case FEAST_GAUNTLET -> updateTurkeyFeastDecision(player);
            case HARVEST_DEFENSE -> updateTurkeyHarvestDefense(player);
            case DEVOURER_BOSS -> updateTurkeyDevourerBoss(player);
            default -> {
            }
        }
    }

    private void updateTurkeyFeastDecision(Bird player) {
        boolean blockDown = isBlockPressed(0);
        if (!classicTurkeyFeastDecisionActive || classicHarvestPlate == null) {
            classicTurkeyBlockWasDown = blockDown;
            return;
        }
        classicTurkeyFeastDecisionFrames--;
        classicHarvestPlate.lifeFrames--;
        double dx = player.bodyCenterX() - classicHarvestPlate.x;
        double dy = player.bodyCenterY() - classicHarvestPlate.y;
        if (dx * dx + dy * dy <= 82.0 * 82.0) {
            completeTurkeyFeastChoice(true);
        } else if (blockDown && !classicTurkeyBlockWasDown) {
            completeTurkeyFeastChoice(false);
        } else if (classicTurkeyFeastDecisionFrames <= 0 || classicHarvestPlate.lifeFrames <= 0) {
            completeTurkeyFeastChoice(false);
        }
        classicTurkeyBlockWasDown = blockDown;
    }

    private void beginTurkeyFeastChoice() {
        Bird player = players[0];
        if (player == null || classicTurkeyFeastDecisionActive) return;
        double left = battlefieldIslandW > 0.0 ? battlefieldIslandX + 130.0 : 180.0;
        double right = battlefieldIslandW > 0.0 ? battlefieldIslandX + battlefieldIslandW - 130.0 : WORLD_WIDTH - 180.0;
        double plateX = Math.clamp(player.bodyCenterX() + (player.facingRight ? 150.0 : -150.0), left, right);
        double plateY = player.bodyCenterY();
        classicHarvestPlate = new ClassicHarvestPlate(plateX, plateY, true, 210);
        classicTurkeyFeastDecisionActive = true;
        classicTurkeyFeastDecisionFrames = 210;
        classicTurkeyBlockWasDown = isBlockPressed(0);
        addToKillFeed("COURSE CLEARED: touch the plate to FEAST, or press BLOCK for FAMINE RUSH.");
    }

    private void completeTurkeyFeastChoice(boolean feast) {
        Bird player = players[0];
        if (player == null || classicEncounter == null || classicEncounter.waves == null) return;
        if (feast) {
            player.heal(24.0);
            classicTurkeyStuffedFrames = 300;
            player.turkeyStuffedTimer = Math.max(player.turkeyStuffedTimer, 300);
            classicRunScore += 650;
            playManagedSfxVaried(steamAchievementClip, 0.43, 1.08, 0.015);
            addToKillFeed("FEAST: 24% recovered. Turkey is heavier and slower for the next course.");
        } else {
            classicTurkeyFamineFrames = 360;
            classicRunScore += 900;
            playManagedSfxVaried(swingClip, 0.36, 1.36, 0.016);
            addToKillFeed("FAMINE RUSH: no recovery, but Turkey gains speed and power.");
        }
        classicHarvestPlate = null;
        classicTurkeyFeastDecisionActive = false;
        classicTurkeyWaveIndex++;
        if (classicTurkeyWaveIndex < classicEncounter.waves.length) {
            spawnTurkeyClassicWave(classicEncounter.waves[classicTurkeyWaveIndex], false);
        }
    }

    boolean holdClassicTurkeyEncounterOpen() {
        if (!classicModeActive || classicEncounter == null || classicSelectedBird != BirdType.TURKEY
                || bossRushModeActive || ashfallTrialModeActive || matchEnded
                || !playerHasStocksRemaining(0)) {
            return false;
        }
        if (classicEncounter.style == ClassicEncounterStyle.HARVEST_DEFENSE) {
            return classicTurkeyDefenseHealth > 0 && !classicTurkeyDefenseCompleted;
        }
        if (classicEncounter.style != ClassicEncounterStyle.FEAST_GAUNTLET
                || classicEncounter.waves == null || classicEncounter.waves.length == 0) {
            return false;
        }
        if (classicTurkeyFeastDecisionActive) return true;
        if (classicEnemyTeamHasStocks()) return false;
        if (classicTurkeyWaveIndex + 1 < classicEncounter.waves.length) {
            beginTurkeyFeastChoice();
            return true;
        }
        return false;
    }

    private boolean classicEnemyTeamHasStocks() {
        for (int slot = 1; slot < activePlayers; slot++) {
            Bird bird = players[slot];
            if (bird != null && getEffectiveTeam(slot) == 2 && playerHasStocksRemaining(slot)) return true;
        }
        return false;
    }

    private Bird firstClassicEnemyWithStocks() {
        for (int slot = 1; slot < activePlayers; slot++) {
            Bird bird = players[slot];
            if (bird != null && getEffectiveTeam(slot) == 2 && playerHasStocksRemaining(slot)) return bird;
        }
        return null;
    }

    private void spawnTurkeyClassicWave(ClassicFighter[] wave, boolean defenseWave) {
        if (wave == null || wave.length == 0 || classicEncounter == null) return;
        for (int slot = 1; slot < MAX_COMBATANTS; slot++) {
            players[slot] = null;
            isAI[slot] = false;
            scores[slot] = 0;
            classicTeams[slot] = 2;
            classicCpuLevels[slot] = 0;
        }

        int count = Math.min(MAX_COMBATANTS - 1, wave.length);
        double difficultyDelta = classicDifficulty - CLASSIC_STARTING_DIFFICULTY;
        double enemyHealthScale = 1.0 + difficultyDelta * 0.045;
        double enemyPowerScale = 1.0 + difficultyDelta * 0.015;
        double center = battlefieldSpawnCenterX();
        for (int i = 0; i < count; i++) {
            ClassicFighter fighter = wave[i];
            int slot = i + 1;
            Bird enemy = createStoryBird(0.0, fighter.type, slot, fighter.title,
                    fighter.health * enemyHealthScale,
                    fighter.powerMult * enemyPowerScale, fighter.speedMult, true);
            if (fighter.skinKey != null) applyPreviewSkinChoiceToBird(enemy, fighter.type, fighter.skinKey);
            if (defenseWave) {
                scaleBossRushBird(enemy, 0.62, 0.92, 1.08);
                enemy.setUltimateEnabled(false);
            }
            applyClassicOpponentBalancePass(classicEncounter, enemy);
            classicTeams[slot] = 2;
            classicCpuLevels[slot] = resolvedClassicFighterCpuLevel(fighter, classicEncounter);
            int authoredRound = authoredClassicRoundIndex(classicEncounter);
            boolean secondStockCourse = !defenseWave
                    && ((authoredRound == 0 && classicTurkeyWaveIndex >= 1)
                    || (authoredRound == 1 && classicTurkeyWaveIndex == 1));
            scores[slot] = secondStockCourse ? 2 : 1;

            double spawnCenter;
            if (defenseWave) {
                spawnCenter = count == 1 ? center + 1_750.0
                        : (i == 0 ? battlefieldIslandX + 260.0 : battlefieldIslandX + battlefieldIslandW - 260.0);
            } else {
                spawnCenter = center + 620.0 + (i - (count - 1) * 0.5) * 420.0;
            }
            if (battlefieldIslandW > 0.0) {
                spawnCenter = Math.clamp(spawnCenter, battlefieldIslandX + 150.0,
                        battlefieldIslandX + battlefieldIslandW - 150.0);
            }
            enemy.x = spawnCenter - enemy.bodyWidth() * 0.5;
            enemy.y = battlefieldSpawnY(enemy.sizeMultiplier);
            enemy.prevX = enemy.x;
            enemy.prevY = enemy.y;
            enemy.vx = 0.0;
            enemy.vy = 0.0;
            enemy.facingRight = enemy.bodyCenterX() < center;
        }
        activePlayers = Math.max(2, count + 1);
        addToKillFeed((defenseWave ? "HARVEST RAIDER WAVE " + (classicTurkeyDefenseWaveIndex + 1)
                : "COURSE " + (classicTurkeyWaveIndex + 1)) + " ENTERS.");
    }

    private void updateTurkeyHarvestDefense(Bird player) {
        double objectiveX = battlefieldSpawnCenterX();
        double objectiveY = battlefieldIslandY - 72.0;
        for (int slot = 1; slot < activePlayers; slot++) {
            Bird raider = players[slot];
            if (raider == null || !playerHasStocksRemaining(slot) || raider.health <= 0.0) continue;
            double dx = raider.bodyCenterX() - objectiveX;
            double dy = raider.bodyCenterY() - objectiveY;
            if (Math.abs(dx) > 120.0) {
                raider.vx = Math.clamp(raider.vx - Math.signum(dx) * 0.22, -8.5, 8.5);
                raider.facingRight = dx < 0.0;
            }
            if (dx * dx + dy * dy <= 145.0 * 145.0) {
                classicTurkeyDefenseHealth = Math.max(0, classicTurkeyDefenseHealth - 15);
                scores[slot] = 0;
                raider.retireFromStockMatch();
                shakeIntensity = Math.max(shakeIntensity, 6.0);
                addToKillFeed("A raider reached the feast! Harvest integrity " + classicTurkeyDefenseHealth + "%.");
            }
        }

        if (classicTurkeyDefenseHealth <= 0) {
            addToKillFeed("THE HARVEST FELL. The bonus ends, but the Classic route continues.");
            matchController.triggerMatchEnd(firstClassicEnemyWithStocks());
            return;
        }

        boolean waveCleared = !classicEnemyTeamHasStocks();
        int waveCount = classicEncounter.waves == null ? 0 : classicEncounter.waves.length;
        if (waveCleared && classicTurkeyDefenseWaveIndex + 1 < waveCount
                && simTick >= (classicTurkeyDefenseWaveIndex + 1L) * 720L) {
            classicTurkeyDefenseWaveIndex++;
            spawnTurkeyClassicWave(classicEncounter.waves[classicTurkeyDefenseWaveIndex], true);
        } else if (waveCleared && waveCount > 0 && classicTurkeyDefenseWaveIndex >= waveCount - 1) {
            completeTurkeyHarvestDefense(player);
        } else if (matchTimer <= 1) {
            completeTurkeyHarvestDefense(player);
        }
    }

    private void completeTurkeyHarvestDefense(Bird player) {
        if (classicTurkeyDefenseCompleted || matchEnded) return;
        classicTurkeyDefenseCompleted = true;
        classicBonusCoins += 75;
        classicRunScore += 5_000 + classicTurkeyDefenseHealth * 25;
        playManagedSfxVaried(steamAchievementClip, 0.55, 1.18, 0.015);
        addToKillFeed("HARVEST SECURED! Bird Coins +75.");
        matchController.triggerMatchEnd(player);
    }

    private void updateTurkeyDevourerBoss(Bird player) {
        Bird devourer = null;
        for (int slot = 1; slot < activePlayers; slot++) {
            Bird candidate = players[slot];
            if (candidate != null && candidate.type == BirdType.PELICAN && getEffectiveTeam(slot) == 2
                    && playerHasStocksRemaining(slot)) {
                devourer = candidate;
                break;
            }
        }
        if (devourer == null) return;
        int stocks = matchScoreForPlayer(devourer.playerIndex);
        if (classicDevourerTrapCooldown > 0) classicDevourerTrapCooldown--;

        if (stocks <= 2 && !classicDevourerSuctionPhaseActive) {
            classicDevourerSuctionPhaseActive = true;
            addToKillFeed("THE DEVOURER PHASE II: the feast hall bends toward its hunger.");
        }
        if (stocks <= 1 && !classicDevourerFinalPhaseActive) {
            classicDevourerFinalPhaseActive = true;
            classicHarvestPlate = null;
            if (classicHarvestWestTable != null) platforms.remove(classicHarvestWestTable);
            if (classicHarvestEastTable != null) platforms.remove(classicHarvestEastTable);
            updateDevourerScale(devourer);
            addToKillFeed("FAMINE PHASE: the outer table collapses. The Devourer is faster, but lighter.");
            shakeIntensity = Math.max(shakeIntensity, 20.0);
            playManagedSfxVaried(hugewaveClip, 0.72, 0.70, 0.014);
        }

        if (!classicDevourerFinalPhaseActive && classicHarvestPlate == null
                && simTick > 0 && simTick % 330 == 45) {
            double[] offeringX = {1_420.0, 3_000.0, 4_580.0};
            int index = (int) ((simTick / 330) % offeringX.length);
            classicHarvestPlate = new ClassicHarvestPlate(offeringX[index], battlefieldIslandY - 88.0,
                    false, 300);
            addToKillFeed("AN OFFERING APPEARS: reach it before The Devourer feeds.");
        }
        if (classicHarvestPlate != null && !classicHarvestPlate.waveChoice) {
            classicHarvestPlate.lifeFrames--;
            double pdx = player.bodyCenterX() - classicHarvestPlate.x;
            double pdy = player.bodyCenterY() - classicHarvestPlate.y;
            double bdx = devourer.bodyCenterX() - classicHarvestPlate.x;
            double bdy = devourer.bodyCenterY() - classicHarvestPlate.y;
            devourer.vx = Math.clamp(devourer.vx + Math.signum(-bdx) * 0.16, -10.5, 10.5);
            if (pdx * pdx + pdy * pdy <= 78.0 * 78.0) {
                player.heal(10.0);
                classicRunScore += 450;
                classicHarvestPlate = null;
                addToKillFeed("OFFERING DENIED: Turkey recovers 10%.");
            } else if (bdx * bdx + bdy * bdy <= 104.0 * 104.0) {
                classicDevourerMeals = Math.min(4, classicDevourerMeals + 1);
                devourer.heal(14.0);
                updateDevourerScale(devourer);
                classicHarvestPlate = null;
                addToKillFeed("THE DEVOURER FEEDS: size and launch resistance increased.");
            } else if (classicHarvestPlate.lifeFrames <= 0) {
                classicHarvestPlate = null;
            }
        }

        if (classicDevourerSuctionPhaseActive) {
            int suctionFrame = (int) (simTick % 270);
            if (suctionFrame >= 82 && suctionFrame <= 128) {
                double dx = devourer.bodyCenterX() - player.bodyCenterX();
                double dy = devourer.bodyCenterY() - player.bodyCenterY();
                double strength = classicDevourerFinalPhaseActive ? 0.34 : 0.24;
                player.vx = Math.clamp(player.vx + Math.signum(dx) * strength, -17.0, 17.0);
                player.vy = Math.clamp(player.vy + Math.signum(dy) * strength * 0.35, -16.0, 16.0);
            }
        }

        if (classicDevourerTrapCooldown <= 0 && !player.turkeyFeastTraps.isEmpty()) {
            Bird.TurkeyFeastTrap triggered = null;
            for (Bird.TurkeyFeastTrap trap : player.turkeyFeastTraps) {
                double dx = devourer.bodyCenterX() - trap.x;
                double dy = devourer.bodyBottomY() - trap.y;
                if (dx * dx + dy * dy <= 132.0 * 132.0) {
                    triggered = trap;
                    break;
                }
            }
            if (triggered != null) {
                player.turkeyFeastTraps.remove(triggered);
                classicDevourerTrapCooldown = 150;
                classicDevourerMeals = Math.max(0, classicDevourerMeals - 1);
                devourer.applyStun(48.0);
                devourer.vx *= 0.28;
                devourer.vy = Math.min(devourer.vy, -3.5);
                updateDevourerScale(devourer);
                classicRunScore += 1_100;
                addToKillFeed("FEAST TRAP: The Devourer is stuffed, stunned, and stripped of one meal.");
            }
        }

        if (classicDevourerFinalPhaseActive) {
            devourer.powerMultiplier = Math.max(devourer.powerMultiplier, devourer.basePowerMultiplier * 1.08);
            devourer.speedMultiplier = Math.max(devourer.speedMultiplier, devourer.baseSpeedMultiplier * 1.08);
            if (devourer.attackCooldown > 0) devourer.attackCooldown = Math.min(devourer.attackCooldown, 9);
            if (devourer.specialCooldown > 0) devourer.specialCooldown = Math.min(devourer.specialCooldown, 105);
        }
    }

    private void updateDevourerScale(Bird devourer) {
        if (devourer == null) return;
        double difficultyPower = 1.0 + (classicDifficulty - CLASSIC_STARTING_DIFFICULTY) * 0.015;
        double size = classicDevourerFinalPhaseActive ? 1.34 : 1.38 + classicDevourerMeals * 0.07;
        double power = (classicDevourerFinalPhaseActive ? 1.06 : 0.98 + classicDevourerMeals * 0.025)
                * difficultyPower;
        double speed = classicDevourerFinalPhaseActive ? 1.12 : 1.02;
        double health = devourer.health;
        devourer.setBaseMultipliers(size, power, speed);
        devourer.health = health;
    }

    private void drawClassicTurkeyRouteFeatures(GraphicsContext g) {
        if (!classicModeActive || classicSelectedBird != BirdType.TURKEY || classicEncounter == null) return;
        g.save();
        if (classicHarvestPlate != null) {
            double pulse = 0.86 + 0.08 * Math.sin(simTick * 0.12);
            double radius = 64.0 * pulse;
            g.setFill(Color.web("#160F0B", 0.82));
            g.fillOval(classicHarvestPlate.x - radius, classicHarvestPlate.y - radius,
                    radius * 2.0, radius * 2.0);
            g.setStroke(Color.web(classicHarvestPlate.waveChoice ? "#FFE082" : "#FFB74D", 0.96));
            g.setLineWidth(8.0);
            g.strokeOval(classicHarvestPlate.x - radius, classicHarvestPlate.y - radius,
                    radius * 2.0, radius * 2.0);
            g.setFill(Color.web("#D39A45"));
            g.fillOval(classicHarvestPlate.x - 42, classicHarvestPlate.y - 17, 84, 34);
            g.setFill(Color.web("#F7E0A3"));
            g.fillOval(classicHarvestPlate.x - 24, classicHarvestPlate.y - 25, 48, 34);
            g.setTextAlign(TextAlignment.CENTER);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 24));
            g.setFill(Color.WHITE);
            g.fillText(classicHarvestPlate.waveChoice ? "FEAST" : "OFFERING",
                    classicHarvestPlate.x, classicHarvestPlate.y - 86);
            if (classicHarvestPlate.waveChoice) {
                g.setFont(Font.font("Consolas", FontWeight.BOLD, 18));
                g.setFill(Color.web("#FFD166"));
                g.fillText("TOUCH TO EAT  |  BLOCK FOR FAMINE",
                        classicHarvestPlate.x, classicHarvestPlate.y + 102);
            }
        }

        if (classicEncounter.style == ClassicEncounterStyle.HARVEST_DEFENSE) {
            double x = battlefieldSpawnCenterX();
            double y = battlefieldIslandY - 72.0;
            g.setFill(Color.web("#2A1510", 0.90));
            g.fillRoundRect(x - 150, y - 90, 300, 96, 30, 30);
            g.setStroke(Color.web("#FFD166"));
            g.setLineWidth(8.0);
            g.strokeRoundRect(x - 150, y - 90, 300, 96, 30, 30);
            g.setFill(Color.web("#F4D06F"));
            g.fillOval(x - 72, y - 75, 144, 54);
            g.setFill(Color.web("#17120F"));
            g.fillRoundRect(x - 168, y + 18, 336, 34, 14, 14);
            g.setFill(Color.web(classicTurkeyDefenseHealth > 45 ? "#66BB6A" : "#EF5350"));
            g.fillRoundRect(x - 162, y + 24, 324 * classicTurkeyDefenseHealth / 100.0, 22, 10, 10);
            g.setTextAlign(TextAlignment.CENTER);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 22));
            g.setFill(Color.WHITE);
            g.fillText("HARVEST " + classicTurkeyDefenseHealth + "%", x, y + 82);
        }

        if (classicEncounter.style == ClassicEncounterStyle.DEVOURER_BOSS) {
            Bird devourer = firstClassicEnemyWithStocks();
            if (devourer != null) {
                double aura = 130.0 + classicDevourerMeals * 22.0;
                g.setStroke(Color.web("#FFB74D", 0.28));
                g.setLineWidth(10.0);
                g.strokeOval(devourer.bodyCenterX() - aura, devourer.bodyCenterY() - aura,
                        aura * 2.0, aura * 2.0);
                if (classicDevourerSuctionPhaseActive) {
                    int suctionFrame = (int) (simTick % 270);
                    if (suctionFrame >= 72 && suctionFrame <= 138) {
                        for (int ring = 0; ring < 3; ring++) {
                            double r = 190.0 + ring * 95.0 - (suctionFrame - 72) * 1.7;
                            if (r <= 35.0) continue;
                            g.setStroke(Color.web("#FFE0B2", 0.30));
                            g.setLineWidth(7.0);
                            g.strokeOval(devourer.bodyCenterX() - r, devourer.bodyCenterY() - r,
                                    r * 2.0, r * 2.0);
                        }
                    }
                }
            }
        }
        g.restore();
    }

    private void setupRoosterClassicRoute(ClassicEncounter encounter) {
        Arrays.fill(classicRoosterRecruitClaims, false);
        classicRoosterMoraleAwardedThisEncounter = false;
        classicRoosterCages.clear();
        classicDawnBells.clear();
        classicRoosterCagesRescued = 0;
        classicRoosterHunterCaptures = 0;
        classicRoosterMusterStep = 0;
        classicRoosterMusterCompleted = false;
        classicRoosterReviveUsed = false;
        classicBroodbreakerCapturePhaseActive = false;
        classicBroodbreakerCaptureCountdown = 0;
        classicBroodbreakerCaptureResolved = false;
        classicBroodbreakerFinalPhaseActive = false;
        classicBroodbreakerEclipseBroken = false;
        if (!classicModeActive || bossRushModeActive || ashfallTrialModeActive
                || classicSelectedBird != BirdType.ROOSTER || encounter == null) {
            return;
        }

        Bird player = players[0];
        if (player == null) return;
        int startingChicks = switch (encounter.style) {
            case BROOD_RECRUITMENT, DAWN_MUSTER -> 1;
            case BROOD_RESCUE -> 2;
            default -> Bird.ROOSTER_STARTING_CHICKS;
        };
        seedRoosterRouteFollowers(player, startingChicks);
        if (encounter.style == ClassicEncounterStyle.BROOD_RESCUE) {
            classicRoosterCages.add(new ClassicBroodCage(1_260, GROUND_Y - 250, 3, false, 0));
            classicRoosterCages.add(new ClassicBroodCage(3_000, GROUND_Y - 520, 3, false, 1));
            classicRoosterCages.add(new ClassicBroodCage(4_740, GROUND_Y - 250, 3, false, 2));
            addToKillFeed("BROOD RESCUE: normal attacks or thrown chicks break the three Crown cages.");
        } else if (encounter.style == ClassicEncounterStyle.DAWN_MUSTER) {
            addToKillFeed("GREAT MUSTER: follow the gold marker and complete CALL, TOSS, LIFT, then RECALL.");
        } else if (encounter.style == ClassicEncounterStyle.BROOD_HUNT) {
            addToKillFeed("CARRION HUNT: Vulture grows stronger each time a veteran chick falls.");
        } else if (encounter.style == ClassicEncounterStyle.NIGHT_COMMAND) {
            addToKillFeed("PARLIAMENT BLACKOUT: the brood's gold command glow marks the safe lanes.");
        } else if (encounter.style == ClassicEncounterStyle.BROODBREAKER_BOSS) {
            addToKillFeed("FALSE DAWN: recall before the capture, break every cage, then toss chicks into the bells.");
        }
    }

    private void seedRoosterRouteFollowers(Bird player, int count) {
        if (player == null) return;
        chickMinions.removeIf(chick -> chick.owner == player);
        player.roosterInitialChicksSpawned = true;
        for (int i = 0; i < Math.clamp(count, 0, Bird.ROOSTER_MAX_CHICKS); i++) {
            RoosterSpecials.spawnFollower(player, i % Bird.ROOSTER_STARTING_CHICKS, false, i);
        }
    }

    void applyRoosterClassicRuntimeEffects() {
        if (!classicModeActive || classicEncounter == null || classicSelectedBird != BirdType.ROOSTER
                || bossRushModeActive || ashfallTrialModeActive || matchEnded) {
            return;
        }
        Bird player = players[0];
        if (player == null || player.health <= 0.0 || !playerHasStocksRemaining(0)) return;

        applyRoosterMoraleToFollowers(player);
        updateClassicRoosterCages(player);
        switch (classicEncounter.style) {
            case BROOD_RECRUITMENT -> updateRoosterRecruitment(player);
            case BROOD_HUNT -> updateRoosterHunter(player);
            case DAWN_MUSTER -> updateRoosterGreatMuster(player);
            case BROODBREAKER_BOSS -> updateRoosterBroodbreaker(player);
            default -> {
            }
        }
    }

    private void applyRoosterMoraleToFollowers(Bird player) {
        for (ChickMinion chick : chickMinions) {
            if (chick.owner != player || chick.roosterSwarm || chick.life <= 0) continue;
            // Classic route followers are the objective, not disposable summons.
            // Keep them for the full encounter unless an opponent defeats them.
            chick.maxAge = Math.max(chick.maxAge, classicEncounter.timerFrames + 600);
            while (chick.classicMoraleApplied < classicRoosterMorale) {
                chick.classicMoraleApplied++;
                if (chick.classicMoraleApplied == 1) {
                    chick.speed *= 1.14;
                    chick.accel *= 1.10;
                } else if (chick.classicMoraleApplied == 2) {
                    chick.maxLife += 2;
                    chick.life += 2;
                    chick.knockbackTakenMultiplier = 0.72;
                }
            }
        }
    }

    private int ownedClassicRoosterChicks(Bird player) {
        int count = 0;
        for (ChickMinion chick : chickMinions) {
            if (chick.owner == player && !chick.roosterSwarm && chick.life > 0) count++;
        }
        return count;
    }

    private void updateRoosterRecruitment(Bird player) {
        for (int slot = 1; slot < activePlayers; slot++) {
            if (classicRoosterRecruitClaims[slot] || players[slot] == null || playerHasStocksRemaining(slot)) continue;
            classicRoosterRecruitClaims[slot] = true;
            if (ownedClassicRoosterChicks(player) < Bird.ROOSTER_MAX_CHICKS) {
                RoosterSpecials.spawnFollower(player, RoosterSpecials.nextVariant(player), false,
                        ownedClassicRoosterChicks(player));
                addToKillFeed("THE FIRST CALL: a veteran chick has answered the hatch signal.");
                playManagedSfxVaried(steamAchievementClip, 0.34, 1.28, 0.015);
            }
            classicRunScore += 500;
        }
    }

    private void updateClassicRoosterCages(Bird player) {
        if (classicRoosterCages.isEmpty()) return;
        Iterator<ClassicBroodCage> iterator = classicRoosterCages.iterator();
        while (iterator.hasNext()) {
            ClassicBroodCage cage = iterator.next();
            if (cage.hitCooldown > 0) cage.hitCooldown--;
            boolean hit = false;
            double pdx = player.bodyCenterX() - cage.x;
            double pdy = player.bodyCenterY() - cage.y;
            if (cage.hitCooldown <= 0 && pdx * pdx + pdy * pdy <= 145.0 * 145.0
                    && player.attackAnimationTimer > 0) {
                cage.health--;
                cage.hitCooldown = 16;
                hit = true;
            }
            for (ChickMinion chick : chickMinions) {
                if (chick.owner != player || chick.thrownFrames <= 0 || chick.life <= 0) continue;
                double dx = chick.x + chick.width * 0.5 - cage.x;
                double dy = chick.y + chick.height * 0.5 - cage.y;
                if (dx * dx + dy * dy <= 125.0 * 125.0) {
                    cage.health = 0;
                    chick.followingOwner = true;
                    chick.target = null;
                    hit = true;
                    break;
                }
            }
            if (hit) {
                shakeIntensity = Math.max(shakeIntensity, 4.0);
                playManagedSfxVaried(swingClip, 0.30, cage.shadow ? 0.78 : 1.02, 0.012);
            }
            if (cage.health > 0) continue;

            iterator.remove();
            classicRoosterCagesRescued++;
            if (ownedClassicRoosterChicks(player) < Bird.ROOSTER_MAX_CHICKS) {
                int variant = cage.capturedVariant >= 0 ? cage.capturedVariant : RoosterSpecials.nextVariant(player);
                RoosterSpecials.spawnFollower(player, variant, false, ownedClassicRoosterChicks(player));
            }
            classicRunScore += cage.shadow ? 1_100 : 750;
            addToKillFeed(cage.shadow ? "SHADOW CAGE BROKEN: a veteran returns to formation."
                    : "BROOD CAGE OPEN: one more chick joins the command line.");
            if (classicEncounter.style == ClassicEncounterStyle.BROOD_RESCUE
                    && classicRoosterCagesRescued >= 3) {
                awardRoosterMoraleCrest("ALL THREE BROOD CAGES OPEN");
            }
        }
    }

    private void awardRoosterMoraleCrest(String reason) {
        if (classicRoosterMorale >= 3 || classicRoosterMoraleAwardedThisEncounter) return;
        classicRoosterMorale++;
        classicRoosterMoraleAwardedThisEncounter = true;
        classicBonusCoins += 20;
        classicRunScore += 1_750;
        playManagedSfxVaried(steamAchievementClip, 0.52, 1.12 + classicRoosterMorale * 0.10, 0.014);
        addToKillFeed("BROOD MORALE " + classicRoosterMorale + "/3: " + reason + ". Bird Coins +20.");
    }

    private void updateRoosterHunter(Bird player) {
        Bird hunter = firstClassicEnemyWithStocks();
        if (hunter == null) return;
        ChickMinion closest = null;
        double best = Double.MAX_VALUE;
        for (ChickMinion chick : chickMinions) {
            if (chick.owner != player || chick.roosterSwarm || chick.life <= 0) continue;
            double dx = chick.x + chick.width * 0.5 - hunter.bodyCenterX();
            double dy = chick.y + chick.height * 0.5 - hunter.bodyCenterY();
            double distance = dx * dx + dy * dy;
            if (distance < best) {
                best = distance;
                closest = chick;
            }
        }
        if (closest != null && simTick % 180 >= 40 && simTick % 180 <= 120) {
            double dx = closest.x + closest.width * 0.5 - hunter.bodyCenterX();
            hunter.vx = Math.clamp(hunter.vx + Math.signum(dx) * 0.18, -9.5, 9.5);
            hunter.facingRight = dx > 0.0;
        }
        double health = hunter.health;
        double difficultyPower = 1.0 + (classicDifficulty - CLASSIC_STARTING_DIFFICULTY) * 0.015;
        hunter.setBaseMultipliers(1.02 + classicRoosterHunterCaptures * 0.05,
                (0.46 + classicRoosterHunterCaptures * 0.03) * difficultyPower,
                0.94 + classicRoosterHunterCaptures * 0.025);
        hunter.health = health;
    }

    boolean rescueClassicRoosterChick(ChickMinion chick) {
        if (!classicModeActive || classicSelectedBird != BirdType.ROOSTER || classicEncounter == null
                || chick == null || chick.owner != players[0] || chick.roosterSwarm) {
            return false;
        }
        if (classicRoosterMorale >= 3 && !classicRoosterReviveUsed) {
            classicRoosterReviveUsed = true;
            chick.life = Math.max(1, chick.maxLife);
            chick.followingOwner = true;
            chick.target = null;
            chick.thrownFrames = 0;
            chick.x = players[0].bodyCenterX() - chick.width * 0.5;
            chick.y = players[0].bodyBottomY() - chick.height - 12.0;
            chick.vx = 0.0;
            chick.vy = -5.0;
            chick.commandFlashFrames = 52;
            addToKillFeed("DAWN GUARD: one defeated veteran immediately returned to formation.");
            return true;
        }
        if (classicEncounter.style == ClassicEncounterStyle.BROOD_HUNT) {
            classicRoosterHunterCaptures = Math.min(5, classicRoosterHunterCaptures + 1);
            addToKillFeed("THE HUNTER CLAIMS A CHICK: carrion power rises to "
                    + classicRoosterHunterCaptures + ".");
        }
        return false;
    }

    private void updateRoosterGreatMuster(Bird player) {
        double[][] markers = roosterMusterMarkers();
        int step = Math.clamp(classicRoosterMusterStep, 0, markers.length - 1);
        double x = markers[step][0];
        double y = markers[step][1];
        boolean complete = false;
        if (step == 0) {
            double dx = player.bodyCenterX() - x;
            double dy = player.bodyCenterY() - y;
            complete = dx * dx + dy * dy <= 240.0 * 240.0
                    && player.roosterNeutralReuseTimer > 0 && ownedClassicRoosterChicks(player) >= 2;
        } else if (step == 1) {
            for (ChickMinion chick : chickMinions) {
                if (chick.owner != player || chick.thrownFrames <= 0) continue;
                double dx = chick.x + chick.width * 0.5 - x;
                double dy = chick.y + chick.height * 0.5 - y;
                if (dx * dx + dy * dy <= 170.0 * 170.0) {
                    complete = true;
                    break;
                }
            }
        } else if (step == 2) {
            double dx = player.bodyCenterX() - x;
            complete = player.roosterCommandFxKind == 3 && player.roosterCommandFxTimer > 0
                    && Math.abs(dx) <= 300.0 && player.bodyCenterY() <= y + 180.0;
        } else {
            double dx = player.bodyCenterX() - x;
            double dy = player.bodyCenterY() - y;
            boolean formation = ownedClassicRoosterChicks(player) >= 2;
            for (ChickMinion chick : chickMinions) {
                if (chick.owner == player && !chick.roosterSwarm && chick.life > 0 && !chick.followingOwner) {
                    formation = false;
                }
            }
            complete = dx * dx + dy * dy <= 260.0 * 260.0
                    && player.roosterDownReuseTimer > 0 && formation;
        }
        if (!complete) return;

        classicRoosterMusterStep++;
        classicRunScore += 1_000;
        playClassicNectarRingSfx(classicRoosterMusterStep, 4);
        addToKillFeed("COMMAND " + classicRoosterMusterStep + "/4 COMPLETE: "
                + switch (step) { case 0 -> "CALL"; case 1 -> "TOSS"; case 2 -> "LIFT"; default -> "RECALL"; });
        if (classicRoosterMusterStep == 3) {
            for (int i = 0; i < chickMinions.size(); i++) {
                ChickMinion chick = chickMinions.get(i);
                if (chick.owner != player || chick.roosterSwarm) continue;
                chick.followingOwner = false;
                chick.target = null;
                chick.x = 4_150.0 + i * 520.0;
                chick.y = GROUND_Y - 720.0 - (i % 2) * 180.0;
                chick.vx = i % 2 == 0 ? -2.5 : 2.5;
                chick.vy = -3.0;
            }
        }
        if (classicRoosterMusterStep >= 4) {
            classicRoosterMusterCompleted = true;
            awardRoosterMoraleCrest("THE GREAT MUSTER COMPLETE");
            classicBonusCoins += 75;
            classicRunScore += 5_000;
            addToKillFeed("GREAT MUSTER COMPLETE! Bird Coins +75.");
            matchController.triggerMatchEnd(player);
        }
    }

    private double[][] roosterMusterMarkers() {
        return new double[][]{
                {1_060.0, GROUND_Y - 540.0},
                {2_120.0, GROUND_Y - 700.0},
                {3_000.0, GROUND_Y - 1_300.0},
                {4_860.0, GROUND_Y - 540.0}
        };
    }

    boolean holdClassicRoosterEncounterOpen() {
        return classicModeActive && classicEncounter != null && classicSelectedBird == BirdType.ROOSTER
                && !bossRushModeActive && !ashfallTrialModeActive && !matchEnded
                && playerHasStocksRemaining(0) && classicEncounter.style == ClassicEncounterStyle.DAWN_MUSTER
                && !classicRoosterMusterCompleted && matchTimer > 1;
    }

    private void updateRoosterBroodbreaker(Bird player) {
        Bird boss = firstClassicEnemyWithStocks();
        if (boss == null || boss.type != BirdType.RAVEN) return;
        int stocks = matchScoreForPlayer(boss.playerIndex);

        int shockFrame = (int) (simTick % 300);
        if (shockFrame == 84) {
            double center = boss.bodyCenterX();
            for (ChickMinion chick : chickMinions) {
                if (chick.owner != player || chick.roosterSwarm) continue;
                double direction = Math.signum(chick.x + chick.width * 0.5 - center);
                if (direction == 0.0) direction = 1.0;
                chick.vx += direction * 8.5;
                chick.vy = Math.min(chick.vy, -6.0);
                chick.followingOwner = false;
                chick.target = null;
            }
            addToKillFeed("BROODBREAKER SHOCKWAVE: the formation scatters.");
            shakeIntensity = Math.max(shakeIntensity, 9.0);
        }

        if (stocks <= 2 && !classicBroodbreakerCapturePhaseActive) {
            classicBroodbreakerCapturePhaseActive = true;
            classicBroodbreakerCaptureCountdown = 90;
            boss.setTrailerSmashDamagePercent(55.0);
            addToKillFeed("SHADOW CAPTURE: use BROOD RECALL before the command ring closes!");
        }
        if (classicBroodbreakerCapturePhaseActive && !classicBroodbreakerCaptureResolved) {
            if (player.roosterDownReuseTimer > 0) {
                classicBroodbreakerCaptureResolved = true;
                classicRunScore += 1_500;
                addToKillFeed("PERFECT RECALL: the brood escaped the shadow cages.");
            } else if (--classicBroodbreakerCaptureCountdown <= 0) {
                captureRoosterChicksForBroodbreaker(player);
                classicBroodbreakerCaptureResolved = true;
            }
        }

        if (stocks <= 1 && !classicBroodbreakerFinalPhaseActive) {
            classicBroodbreakerFinalPhaseActive = true;
            boss.setTrailerSmashDamagePercent(58.0);
            classicDawnBells.clear();
            classicDawnBells.add(new ClassicDawnBell(1_520, GROUND_Y - 760));
            classicDawnBells.add(new ClassicDawnBell(3_000, GROUND_Y - 1_140));
            classicDawnBells.add(new ClassicDawnBell(4_480, GROUND_Y - 760));
            addToKillFeed("FINAL ECLIPSE: toss chicks through all three dawn bells.");
        }
        if (classicBroodbreakerFinalPhaseActive && !classicBroodbreakerEclipseBroken) {
            for (ClassicDawnBell bell : classicDawnBells) {
                if (bell.lit) continue;
                for (ChickMinion chick : chickMinions) {
                    if (chick.owner != player || chick.thrownFrames <= 0 || chick.life <= 0) continue;
                    double dx = chick.x + chick.width * 0.5 - bell.x;
                    double dy = chick.y + chick.height * 0.5 - bell.y;
                    if (dx * dx + dy * dy <= 165.0 * 165.0) {
                        bell.lit = true;
                        chick.followingOwner = true;
                        chick.target = null;
                        classicRunScore += 1_250;
                        playManagedSfxVaried(steamAchievementClip, 0.56, 0.92 + litDawnBellCount() * 0.18, 0.012);
                        addToKillFeed("DAWN BELL " + litDawnBellCount() + "/3 RUNG.");
                        break;
                    }
                }
            }
            if (litDawnBellCount() >= 3) {
                classicBroodbreakerEclipseBroken = true;
                boss.applyStun(42.0);
                addToKillFeed("THE ECLIPSE BREAKS: the Broodbreaker has lost its armor.");
            }
        }
        updateBroodbreakerScale(boss);
    }

    private void captureRoosterChicksForBroodbreaker(Bird player) {
        int captured = 0;
        Iterator<ChickMinion> iterator = chickMinions.iterator();
        while (iterator.hasNext() && captured < 2) {
            ChickMinion chick = iterator.next();
            if (chick.owner != player || chick.roosterSwarm || chick.life <= 0) continue;
            int variant = chick.variant;
            iterator.remove();
            double x = captured == 0 ? 2_080.0 : 3_920.0;
            classicRoosterCages.add(new ClassicBroodCage(x, GROUND_Y - 430.0, 2, true, variant));
            captured++;
        }
        if (captured > 0) {
            addToKillFeed("SHADOW CAGES CLOSED: break " + captured + " cage" + (captured == 1 ? "" : "s") + ".");
        }
    }

    private int litDawnBellCount() {
        int count = 0;
        for (ClassicDawnBell bell : classicDawnBells) if (bell.lit) count++;
        return count;
    }

    private void updateBroodbreakerScale(Bird boss) {
        if (boss == null) return;
        int shadowCages = 0;
        for (ClassicBroodCage cage : classicRoosterCages) if (cage.shadow) shadowCages++;
        double difficultyPower = 1.0 + (classicDifficulty - CLASSIC_STARTING_DIFFICULTY) * 0.015;
        double size = classicBroodbreakerEclipseBroken ? 1.16
                : (classicBroodbreakerFinalPhaseActive ? 1.28 : 1.18 + shadowCages * 0.06);
        double power = (classicBroodbreakerFinalPhaseActive && !classicBroodbreakerEclipseBroken ? 0.66 : 0.56)
                * difficultyPower;
        double speed = classicBroodbreakerFinalPhaseActive ? 1.02 : 0.98;
        double health = boss.health;
        boss.setBaseMultipliers(size, power, speed);
        boss.health = health;
    }

    private void drawClassicRoosterRouteFeatures(GraphicsContext g) {
        if (!classicModeActive || classicSelectedBird != BirdType.ROOSTER || classicEncounter == null) return;
        g.save();

        if (classicEncounter.style == ClassicEncounterStyle.NIGHT_COMMAND) {
            int blackoutFrame = (int) (simTick % 360);
            if (blackoutFrame >= 110 && blackoutFrame <= 240) {
                g.setFill(Color.web("#02030A", 0.70));
                g.fillRect(0, 0, WORLD_WIDTH, WORLD_HEIGHT);
                for (ChickMinion chick : chickMinions) {
                    if (chick.owner != players[0] || chick.roosterSwarm || chick.life <= 0) continue;
                    double cx = chick.x + chick.width * 0.5;
                    double cy = chick.y + chick.height * 0.5;
                    g.setFill(Color.web("#FFE082", 0.20));
                    g.fillOval(cx - 145, cy - 145, 290, 290);
                    g.setStroke(Color.web("#FFF0A8", 0.72));
                    g.setLineWidth(5.0);
                    g.strokeOval(cx - 62, cy - 62, 124, 124);
                }
            }
        }

        for (ClassicBroodCage cage : classicRoosterCages) {
            Color bars = cage.shadow ? Color.web("#9B59B6") : Color.web("#B0BEC5");
            g.setFill(Color.web(cage.shadow ? "#120A1B" : "#20242C", 0.88));
            g.fillRoundRect(cage.x - 74, cage.y - 72, 148, 144, 18, 18);
            g.setStroke(bars);
            g.setLineWidth(8.0);
            g.strokeRoundRect(cage.x - 74, cage.y - 72, 148, 144, 18, 18);
            for (int bar = -2; bar <= 2; bar++) g.strokeLine(cage.x + bar * 25, cage.y - 66, cage.x + bar * 25, cage.y + 66);
            g.setTextAlign(TextAlignment.CENTER);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 19));
            g.setFill(Color.WHITE);
            g.fillText((cage.shadow ? "SHADOW " : "") + "CAGE " + cage.health, cage.x, cage.y - 94);
        }

        if (classicEncounter.style == ClassicEncounterStyle.DAWN_MUSTER && !classicRoosterMusterCompleted) {
            double[][] markers = roosterMusterMarkers();
            int step = Math.clamp(classicRoosterMusterStep, 0, 3);
            String[] labels = {"CALL", "TOSS", "LIFT", "RECALL"};
            double x = markers[step][0];
            double y = markers[step][1];
            double pulse = 74.0 + Math.sin(simTick * 0.12) * 10.0;
            g.setStroke(Color.web("#FFF176", 0.95));
            g.setLineWidth(10.0);
            g.strokeOval(x - pulse, y - pulse, pulse * 2.0, pulse * 2.0);
            g.setFill(Color.web("#3A2410", 0.82));
            g.fillRoundRect(x - 90, y - 128, 180, 42, 18, 18);
            g.setFill(Color.WHITE);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 24));
            g.setTextAlign(TextAlignment.CENTER);
            g.fillText(labels[step], x, y - 98);
        }

        for (ClassicDawnBell bell : classicDawnBells) {
            g.setStroke(Color.web(bell.lit ? "#FFF59D" : "#7B5A36", bell.lit ? 0.98 : 0.76));
            g.setLineWidth(bell.lit ? 13.0 : 8.0);
            g.strokeOval(bell.x - 88, bell.y - 110, 176, 220);
            g.setFill(Color.web(bell.lit ? "#FFD54F" : "#4A3741", 0.78));
            g.fillOval(bell.x - 60, bell.y - 82, 120, 164);
        }
        g.restore();
    }

    int classicHummingbirdBlossomCount() {
        int total = 0;
        for (boolean blossom : classicHummingbirdBlossoms) if (blossom) total++;
        return total;
    }

    boolean isClassicNectarDashActive() {
        return classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.NECTAR_DASH;
    }

    boolean isClassicNectarDashParticipant(Bird bird) {
        return isClassicNectarDashActive() && bird != null && bird.playerIndex == 0;
    }

    void finishClassicNectarDashFromTimeout() {
        if (!isClassicNectarDashActive() || matchEnded) return;
        addToKillFeed("TIME! The flower course closes, but the Classic route continues.");
        matchController.triggerMatchEnd(players[0]);
    }

    boolean isClassicRedlineRunActive() {
        return classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.REDLINE_RUN;
    }

    void finishClassicRedlineRunFromTimeout() {
        if (!isClassicRedlineRunActive() || matchEnded) return;
        classicRoadrunnerRunCompleted = true;
        classicRoadrunnerRunRank = "C";
        addToKillFeed("TIME! Redline Run closes at C rank. The Classic route continues.");
        matchController.triggerMatchEnd(players[0]);
    }

    private boolean isClassicBlightwingEncounter() {
        return classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.BLIGHTWING_BOSS;
    }

    void onClassicBonusTargetDestroyed(Bird target) {
        if (!classicModeActive || classicEncounter == null
                || (classicEncounter.style != ClassicEncounterStyle.BONUS_RELAY
                && classicEncounter.style != ClassicEncounterStyle.RIPPLE_HUNT) || target == null) {
            return;
        }
        classicBonusCoins += 25;
        classicRunScore += 2_500;
        String bonusName = switch (classicEncounter.name) {
            case "Bonus: Storm Beacon Ascent" -> "STORM BEACON ASCENT";
            case "Bonus: Peregrine Run" -> "PEREGRINE RUN";
            case "Bonus: Rebirth Relay" -> "REBIRTH RELAY";
            case "Bonus: Ripple Hunt" -> "RIPPLE HUNT";
            case "Bonus: Buried Markers" -> "BURIED MARKERS";
            default -> "ROOFTOP RELAY";
        };
        addToKillFeed(bonusName + ": target broken. Bird Coins +25.");
    }

    private void recordClassicEncounterScore(boolean playerWon) {
        if (!playerWon || classicEncounter == null) return;
        Bird player = players[0];
        int timeBonus = Math.max(0, matchTimer / 6);
        int healthBonus = player == null ? 0 : (int) Math.round(Math.max(0.0, player.health) * 8.0);
        int intensityBonus = (int) Math.round(classicDifficulty * 300.0);
        int lifeBonus = Math.max(0, 3 - classicDeaths) * 750;
        classicRunScore += 2_000 + timeBonus + healthBonus + intensityBonus + lifeBonus;
    }

    private void claimDestroyedClassicBonusTargets() {
        for (Bird bird : players) {
            if (bird == null || !bird.classicBonusTarget || bird.health > 0.0
                    || bird.classicBonusTargetRewardClaimed) {
                continue;
            }
            bird.classicBonusTargetRewardClaimed = true;
            onClassicBonusTargetDestroyed(bird);
        }
    }

    private void scaleBossRushBird(Bird bird, double sizeScale, double powerScale, double speedScale) {
        if (bird == null) return;
        double health = bird.health;
        bird.setBaseMultipliers(
                bird.baseSizeMultiplier * sizeScale,
                bird.basePowerMultiplier * powerScale,
                bird.baseSpeedMultiplier * speedScale
        );
        bird.health = health;
    }

    private void applyBossRushEncounterRosterModifiers(ClassicEncounter encounter) {
        if (encounter == null) return;
        for (Bird bird : players) {
            if (bird == null) continue;
            switch (bird.name) {
                case "Ally: Sky King" -> scaleBossRushBird(bird, 1.04, 1.04, 1.06);
                case "Boss: Canopy Vulture" -> scaleBossRushBird(bird, 1.18, 1.06, 1.02);
                case "Elite: Sunflare Courier" -> scaleBossRushBird(bird, 0.98, 1.03, 1.08);
                case "Boss: Ashen Phoenix" -> scaleBossRushBird(bird, 1.05, 1.03, 1.01);
                case "Ally: Umbra Bat" -> scaleBossRushBird(bird, 1.02, 1.04, 1.05);
                case "Boss: Titan Pelican" -> scaleBossRushBird(bird, 1.22, 1.04, 0.96);
                case "Ally: Night Raven" -> scaleBossRushBird(bird, 1.04, 1.05, 1.06);
                case "Boss: Old Sparrow" -> scaleBossRushBird(bird, 1.04, 1.03, 1.01);
                case "Boss: Void Raven" -> scaleBossRushBird(bird, 1.06, 1.04, 1.05);
                case "Boss: Carrion Regent" -> scaleBossRushBird(bird, 1.14, 1.05, 1.01);
                case "Boss: Opium Seer" -> scaleBossRushBird(bird, 1.04, 1.04, 1.04);
                case "Boss: Null Roc" -> scaleBossRushBird(bird, 1.55, 1.08, 1.00);
                case "EX Boss: Void Sovereign" -> scaleBossRushBird(bird, 1.34, 1.12, 1.08);
                default -> {
                }
            }
        }
    }

