    private boolean didPlayerWinClassic(Bird winner) {
        if (winner == null || players[0] == null) return false;
        return getEffectiveTeam(winner.playerIndex) == getEffectiveTeam(0);
    }

    private void resetClassicAdaptiveDifficulty() {
        classicDifficulty = CLASSIC_STARTING_DIFFICULTY;
    }

    private void adjustClassicDifficulty(boolean won) {
        double delta = won ? CLASSIC_DIFFICULTY_STEP : -CLASSIC_DIFFICULTY_STEP;
        classicDifficulty = Math.clamp(classicDifficulty + delta, 1.0, 9.0);
    }

    void applyClassicRestartPenalty() {
        classicDeaths++;
        adjustClassicDifficulty(false);
    }

    private void evaluateRoosterClassicEncounter(boolean playerWon) {
        if (!playerWon || classicSelectedBird != BirdType.ROOSTER || classicEncounter == null || players[0] == null) {
            return;
        }
        Bird player = players[0];
        if (classicEncounter.style == ClassicEncounterStyle.BROOD_LEADERSHIP) {
            boolean turkeyStanding = false;
            for (int slot = 1; slot < activePlayers; slot++) {
                Bird bird = players[slot];
                if (bird != null && getEffectiveTeam(slot) == 1 && bird.type == BirdType.TURKEY
                        && playerHasStocksRemaining(slot)) {
                    turkeyStanding = true;
                    break;
                }
            }
            if (turkeyStanding && ownedClassicRoosterChicks(player) >= 2) {
                awardRoosterMoraleCrest("BOTH LEADERS AND THE BROOD HELD THE LINE");
            }
        } else if (classicEncounter.style == ClassicEncounterStyle.BROOD_RECRUITMENT
                && ownedClassicRoosterChicks(player) >= Bird.ROOSTER_STARTING_CHICKS) {
            classicRunScore += 1_000;
            addToKillFeed("FULL FORMATION: all three veteran chicks answered the first call.");
        } else if (classicEncounter.style == ClassicEncounterStyle.BROOD_HUNT
                && classicRoosterHunterCaptures == 0) {
            classicRunScore += 1_500;
            classicBonusCoins += 15;
            addToKillFeed("NO ONE TAKEN: the entire brood escaped the Carrion Hunt. Bird Coins +15.");
        }
    }

    static int classicContinueCoinValue(int continueCount) {
        long value = (long) Math.max(0, continueCount) * CLASSIC_CONTINUE_BIRD_COIN_COST;
        return value >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) value;
    }

    private void handleClassicMatchEnd(Stage stage, Bird winner) {
        if (!classicModeActive || classicEncounter == null) {
            if (dailyChallengeModeActive) {
                showDailyChallengeSetup(stage);
            } else {
                showClassicBirdSelect(stage);
            }
            return;
        }
        if (dailyChallengeModeActive) {
            handleDailyChallengeMatchEnd(stage, winner);
            return;
        }
        if (ashfallTrialModeActive) {
            handleAshfallTrialMatchEnd(stage, winner);
            return;
        }
        if (bossRushModeActive) {
            handleBossRushMatchEnd(stage, winner);
            return;
        }

        claimDestroyedClassicBonusTargets();
        boolean playerWon = didPlayerWinClassic(winner);
        evaluateRoosterClassicEncounter(playerWon);
        if (isClassicObjectiveEncounterStyle(classicEncounter.style)) {
            recordClassicEncounterScore(playerWon);
            classicRoundIndex++;
            classicEncounter = classicRun.get(classicRoundIndex);
            saveAchievements();
            showClassicEncounterIntro(stage);
            return;
        }

        if (!playerWon) {
            classicDeaths++;
            adjustClassicDifficulty(false);
            showClassicContinuePrompt(stage);
            return;
        }

        adjustClassicDifficulty(true);
        recordClassicEncounterScore(true);

        if (classicRoundIndex >= classicRun.size() - 1) {
            classicDeaths = 0;
            int finalScore = Math.max(0, classicRunScore - classicContinuesUsed * 5_000);
            int routePayout = 100 + (int) Math.round(classicDifficulty * 20.0) + classicBonusCoins;
            grantBirdCoins(routePayout);
            if (classicSelectedBird == BirdType.PIGEON) {
                rooftopRelayUnlocked = true;
            } else if (classicSelectedBird == BirdType.EAGLE) {
                tempestSummitUnlocked = true;
            } else if (classicSelectedBird == BirdType.FALCON) {
                peregrineRunUnlocked = true;
            } else if (classicSelectedBird == BirdType.PHOENIX) {
                frozenCalderaUnlocked = true;
            } else if (classicSelectedBird == BirdType.HUMMINGBIRD) {
                heartbloomSanctuaryUnlocked = true;
            } else if (classicSelectedBird == BirdType.TURKEY) {
                harvestTribunalUnlocked = true;
            } else if (classicSelectedBird == BirdType.ROOSTER) {
                dawnwatchBastionUnlocked = true;
            } else if (classicSelectedBird == BirdType.ROADRUNNER) {
                redlineCanyonUnlocked = true;
            } else if (classicSelectedBird == BirdType.PENGUIN) {
                lastIceShelfUnlocked = true;
            } else if (classicSelectedBird == BirdType.SHOEBILL) {
                stillwaterMarshUnlocked = true;
            } else if (classicSelectedBird == BirdType.MOCKINGBIRD
                    && !isClassicCompleted(BirdType.MOCKINGBIRD)) {
                queueMapUnlockCard(MapType.RESONANCE_HALL);
                queueMapUnlockCard(MapType.SIGNAL_SPIRE);
                queueMapUnlockCard(MapType.SILENT_AMPHITHEATER);
            } else if (classicSelectedBird == BirdType.RAZORBILL
                    && !isClassicCompleted(BirdType.RAZORBILL)) {
                queueMapUnlockCard(MapType.GLASSWIND_CAUSEWAY);
                queueMapUnlockCard(MapType.WORLDSEAM);
            } else if (classicSelectedBird == BirdType.GRINCHHAWK
                    && !isClassicCompleted(BirdType.GRINCHHAWK)) {
                queueMapUnlockCard(MapType.MIDNIGHT_WORKSHOP);
            } else if (classicSelectedBird == BirdType.VULTURE
                    && !isClassicCompleted(BirdType.VULTURE)) {
                queueMapUnlockCard(MapType.CARRION_EXCHANGE);
            } else if (classicSelectedBird == BirdType.OPIUMBIRD
                    && !isClassicCompleted(BirdType.OPIUMBIRD)) {
                queueMapUnlockCard(MapType.ONEIRIC_OBSERVATORY);
            } else if (classicSelectedBird == BirdType.HEISENBIRD
                    && !isClassicCompleted(BirdType.HEISENBIRD)) {
                queueMapUnlockCard(MapType.STORMGLASS_REFINERY);
            }
            profileProgressController.onClassicRunCompleted(classicSelectedBird, achievementEvaluator::onClassicRunCompleted);
            ClassicEndingContent.Ending authoredEnding = Objects.requireNonNull(
                    ClassicEndingContent.endingFor(classicSelectedBird),
                    "Every playable bird must have an authored Classic ending: " + classicSelectedBird);
            ClassicEndingContent.Cinematic playback = ClassicEndingContent.withRouteRecord(
                    authoredEnding,
                    routePayout,
                    finalScore,
                    classicRouteMapRewardName(classicSelectedBird));
            playClassicEnding(stage, playback, classicSelectedSkinKey,
                    () -> runAfterUnlockCards(stage, () -> showClassicBirdSelect(stage)));
            return;
        }

        classicRoundIndex++;
        classicEncounter = classicRun.get(classicRoundIndex);
        saveAchievements();
        showClassicEncounterIntro(stage);
    }

    private void playClassicEnding(Stage stage, ClassicEndingContent.Cinematic cinematic,
                                   String skinKey, Runnable after) {
        if (cinematic == null) {
            if (after != null) after.run();
            return;
        }
        classicEndingPlayer.play(stage, cinematic, skinKey, () -> {
            saveAchievements();
            if (after != null) after.run();
        });
    }

    boolean isClassicEndingUnlocked(BirdType bird) {
        return ClassicEndingContent.hasEnding(bird) && isClassicCompleted(bird);
    }

    private String classicRouteMapRewardName(BirdType bird) {
        return switch (bird) {
            case PIGEON -> "Rooftop Relay";
            case EAGLE -> "Tempest Summit";
            case FALCON -> "Peregrine Run";
            case PHOENIX -> "Frozen Caldera";
            case HUMMINGBIRD -> "Heartbloom Sanctuary";
            case TURKEY -> "Harvest Tribunal";
            case ROOSTER -> "Dawnwatch Bastion";
            case ROADRUNNER -> "Redline Canyon";
            case PENGUIN -> "Last Ice Shelf";
            case SHOEBILL -> "Stillwater Marsh";
            case MOCKINGBIRD -> "Resonance Hall + Signal Spire + Silent Amphitheater";
            case RAZORBILL -> "Glasswind Causeway + The Worldseam";
            case GRINCHHAWK -> "Midnight Workshop";
            case VULTURE -> "Carrion Exchange";
            case OPIUMBIRD -> "Oneiric Observatory";
            case HEISENBIRD -> "Stormglass Refinery + Eye of the Supercell";
            default -> "";
        };
    }

    private void handleAshfallTrialMatchEnd(Stage stage, Bird winner) {
        if (!classicModeActive || classicEncounter == null) {
            showAshfallTrialBriefing(stage);
            return;
        }

        if (!didPlayerWinClassic(winner)) {
            classicDeaths++;
            if (classicDeaths < 3) {
                int livesLeft = Math.max(0, 3 - classicDeaths);
                showStoryDialogue(
                        stage,
                        "Trial Broken",
                        "Pyrecaster",
                        "You were eliminated in " + classicEncounter.name + ".\nTrial lives remaining: "
                                + livesLeft + "/3.\nReturn to the altar and retry this rite.",
                        () -> startClassicEncounter(stage)
                );
            } else {
                classicDeaths = 0;
                showStoryDialogue(
                        stage,
                        "Ashfall Trial Failed",
                        "Rebirth Oracle",
                        "The route collapsed in " + classicEncounter.name + ".\nThe cathedral stays lit, but the trial must be restarted.",
                        () -> showAshfallTrialBriefing(stage)
                );
            }
            return;
        }

        if (classicRoundIndex >= classicRun.size() - 1) {
            boolean firstClear = !ashfallTrialCompleted;
            boolean unlockedAshenSkin = !ashenSovereignPhoenixUnlocked;
            int payout = firstClear ? ASHFALL_TRIAL_FIRST_CLEAR_BONUS : ASHFALL_TRIAL_REPEAT_CLEAR_BONUS;
            ashfallTrialCompleted = true;
            classicDeaths = 0;
            grantBirdCoins(payout);
            if (unlockedAshenSkin) {
                unlockShopPreview(new ShopPreview(BirdType.PHOENIX, ASHEN_SOVEREIGN_PHOENIX_SKIN, null));
            }
            saveAchievements();
            showStoryDialogue(
                    stage,
                    "Ashfall Trial Cleared",
                    "Rebirth Oracle",
                    "The final flame answers Phoenix.\nBird Coins awarded: +" + payout + "."
                            + (unlockedAshenSkin ? "\nReward unlocked: Ashen Sovereign Phoenix."
                            : "\nAshen Sovereign Phoenix already unlocked.")
                            + "\nTrial status: CLEARED.",
                    () -> runAfterUnlockCards(stage, () -> showClassicMoreMenu(stage))
            );
            return;
        }

        classicRoundIndex++;
        classicEncounter = classicRun.get(classicRoundIndex);
        saveAchievements();
        showStoryDialogue(
                stage,
                "Rite Cleared",
                "Ashcaller",
                "Advance to Trial " + (classicRoundIndex + 1) + ": " + classicEncounter.name + ".",
                () -> showClassicEncounterIntro(stage)
        );
    }

    private void handleDailyChallengeMatchEnd(Stage stage, Bird winner) {
        if (!classicModeActive || classicEncounter == null) {
            showDailyChallengeSetup(stage);
            return;
        }

        if (!didPlayerWinClassic(winner)) {
            classicDeaths++;
            if (classicDeaths < 3) {
                showStoryDialogue(
                        stage,
                        "Run Stalled",
                        "Skycaster",
                        "You were eliminated in " + classicEncounter.name + ".\nDaily lives: "
                                + classicDeaths + "/3.\nRetry this encounter.",
                        () -> startClassicEncounter(stage)
                );
            } else {
                classicDeaths = 0;
                showStoryDialogue(
                        stage,
                        "Daily Run Failed",
                        "Skycaster",
                        "The daily challenge ended in " + classicEncounter.name + ".\n"
                                + dailyChallengeBestStatus(dailyChallengeRunKey),
                        () -> showDailyChallengeSetup(stage)
                );
            }
            return;
        }

        if (classicRoundIndex >= classicRun.size() - 1) {
            classicDeaths = 0;
            saveAchievements();
            showStoryDialogue(
                    stage,
                    "Daily Challenge Cleared",
                    "Skycaster Prime",
                    "Daily seed " + formatDailyChallengeSeed(dailyChallengeSeed) + " cleared with "
                            + classicSelectedBird.name + ".\n"
                            + dailyChallengeBonusStatus(dailyChallengeRunKey) + "\n"
                            + dailyChallengeBestStatus(dailyChallengeRunKey),
                    () -> showDailyChallengeSetup(stage)
            );
            return;
        }

        classicRoundIndex++;
        classicEncounter = classicRun.get(classicRoundIndex);
        saveAchievements();
        showStoryDialogue(
                stage,
                "Encounter Cleared",
                "Skycaster",
                "Advance to Daily Round " + (classicRoundIndex + 1) + ": " + classicEncounter.name + ".",
                () -> showClassicEncounterIntro(stage)
        );
    }

    private void handleBossRushMatchEnd(Stage stage, Bird winner) {
        if (!classicModeActive || classicEncounter == null) {
            showClassicBirdSelect(stage);
            return;
        }

        boolean playerWon = didPlayerWinClassic(winner);
        if (!playerWon) {
            bossRushPerfectRun = false;
            classicDeaths++;
            if (classicDeaths < 3) {
                int stocksLeft = Math.max(0, 3 - classicDeaths);
                showStoryDialogue(
                        stage,
                        "Boss Breach",
                        "Stormcaster Prime",
                        "You fell in " + classicEncounter.name + ".\nRepair stocks remaining: "
                                + stocksLeft + "/3.\nRearm and retry the boss.",
                        () -> startClassicEncounter(stage)
                );
            } else {
                long elapsedMillis = bossRushRunStartMillis > 0L
                        ? Math.max(0L, System.currentTimeMillis() - bossRushRunStartMillis)
                        : 0L;
                classicDeaths = 0;
                showStoryDialogue(
                        stage,
                        "Boss Rush Failed",
                        "Stormcaster Prime",
                        "The route collapsed in " + classicEncounter.name + ".\n"
                                + "Bosses cleared: " + classicRoundIndex + "/" + classicRun.size() + "\n"
                                + "Run time: " + formatElapsedMillis(elapsedMillis),
                        () -> showClassicBirdSelect(stage)
                );
            }
            return;
        }

        boolean finalRound = classicRoundIndex >= classicRun.size() - 1;
        boolean exEncounter = isBossRushExEncounter(classicEncounter);
        if (finalRound) {
            if (!exEncounter && bossRushPerfectRun && !bossRushExEncounterAdded) {
                classicRun.add(buildBossRushExEncounter());
                bossRushExEncounterAdded = true;
                classicRoundIndex++;
                classicEncounter = classicRun.get(classicRoundIndex);
                saveAchievements();
                showStoryDialogue(
                        stage,
                        "EX Route Open",
                        "Beaconcaster Prime",
                        "Perfect route confirmed.\nThe crown tears open again.\n"
                                + BOSS_RUSH_EX_NAME + " is now active.",
                        () -> showClassicEncounterIntro(stage)
                );
                return;
            }
            completeBossRushRun(stage, exEncounter);
            return;
        }

        classicRoundIndex++;
        classicEncounter = classicRun.get(classicRoundIndex);
        saveAchievements();
        showStoryDialogue(
                stage,
                "Boss Broken",
                "Stormcaster Prime",
                "Advance to Boss " + (classicRoundIndex + 1) + ": " + classicEncounter.name + ".",
                () -> showClassicEncounterIntro(stage)
        );
    }

