    /**
     * Renders the real playable arena without fighters or HUD for the bundled
     * stage-select captures. Call this only on a dedicated off-screen instance;
     * arena setup intentionally replaces that instance's current match state.
     */
    Canvas captureActualStagePreview(StageChoice choice, double outputWidth, double outputHeight) {
        StageChoice stage = choice == null ? StageChoice.main(MapType.FOREST) : choice;
        long seed = 0x57A6_ECA9_7E21L
                ^ ((long) stage.map().ordinal() << 24)
                ^ ((long) stage.variant().ordinal() << 8);
        resetHeadlessHarness(seed);
        selectedMap = stage.map();
        selectedMapVariant = stage.variant();
        Arrays.fill(players, null);
        Arrays.fill(isAI, false);
        activePlayers = 0;
        ambientEffectsEnabled = false;
        particleEffectsEnabled = false;
        stageCaptureBackdropEnabled = true;
        screenShakeEnabled = false;
        shakeIntensity = 0.0;
        setupMatchArenaGeometry();
        applySelectedMapVariantArena();

        // A real match camera at this zoom fills the full 16:9 frame while
        // preserving nearly the entire authored 6000x3000 arena.
        zoom = HEIGHT / WORLD_HEIGHT;
        camX = Math.max(0.0, (WORLD_WIDTH - WIDTH / zoom) * 0.5);
        camY = 0.0;

        Canvas capture = new Canvas(outputWidth, outputHeight);
        GraphicsContext graphics = capture.getGraphicsContext2D();
        graphics.save();
        graphics.scale(outputWidth / WIDTH, outputHeight / HEIGHT);
        drawGame(graphics);
        graphics.restore();
        return capture;
    }

    private HBox stageSelectLegendChip(String marker, String labelText, String accent) {
        Label badge = new Label(marker);
        badge.setFont(Font.font("Arial Black", FontWeight.BOLD, 11));
        badge.setTextFill(Color.web("#071018"));
        badge.setAlignment(Pos.CENTER);
        badge.setMinSize(22, 22);
        badge.setPrefSize(22, 22);
        badge.setMaxSize(22, 22);
        badge.setStyle("-fx-background-color:" + accent + "; -fx-background-radius:11;");

        Label text = new Label(labelText);
        text.setFont(Font.font("Consolas", FontWeight.BOLD, 13));
        text.setTextFill(Color.web("#B8C7D5"));
        applyNoEllipsis(text);

        HBox chip = new HBox(5, badge, text);
        chip.setAlignment(Pos.CENTER_LEFT);
        chip.setPadding(new Insets(3, 9, 3, 4));
        chip.setStyle("-fx-background-color:#0A0E16CC; -fx-background-radius:12;"
                + "-fx-border-color:#FFFFFF22; -fx-border-radius:12;");
        return chip;
    }

    private void styleStagePreviewFrame(StackPane frame, Color accent) {
        String color = toCssHex(accent);
        frame.setStyle("-fx-background-color:#03050A; -fx-background-radius:16;"
                + "-fx-border-color:" + color + "; -fx-border-width:3; -fx-border-radius:16;"
                + "-fx-effect:dropshadow(gaussian," + color + "55,18,0.24,0,0);");
    }

    private void animateStagePreview(Canvas preview) {
        String key = "stage-select-preview-fade";
        Object previous = preview.getProperties().remove(key);
        if (previous instanceof FadeTransition oldTransition) {
            oldTransition.stop();
        }
        FadeTransition transition = new FadeTransition(Duration.millis(125), preview);
        transition.setFromValue(0.58);
        transition.setToValue(1.0);
        preview.getProperties().put(key, transition);
        transition.setOnFinished(event -> preview.getProperties().remove(key, transition));
        transition.play();
    }

    private Button buildStageSelectTile(StageChoice choice, boolean random,
                                        Runnable action, Runnable previewAction) {
        Canvas image = new Canvas(StageSelectLayout.TILE_IMAGE_WIDTH, StageSelectLayout.TILE_IMAGE_HEIGHT);
        if (random) {
            StagePreviewRenderer.drawRandom(image);
        } else {
            StagePreviewRenderer.draw(image, choice);
        }
        String name = random ? "RANDOM" : stageDisplayName(choice.map(), choice.variant()).toUpperCase(Locale.ROOT);
        Label nameLabel = new Label(name);
        nameLabel.setFont(Font.font("Arial Black", FontWeight.BOLD, name.length() > 18 ? 11 : 13));
        nameLabel.setTextFill(Color.WHITE);
        nameLabel.setWrapText(true);
        nameLabel.setTextAlignment(TextAlignment.CENTER);
        nameLabel.setAlignment(Pos.CENTER);
        nameLabel.setMinSize(StageSelectLayout.TILE_IMAGE_WIDTH, 39);
        nameLabel.setPrefSize(StageSelectLayout.TILE_IMAGE_WIDTH, 39);
        nameLabel.setMaxSize(StageSelectLayout.TILE_IMAGE_WIDTH, 39);
        applyNoEllipsis(nameLabel);
        fitWrappedLabelText(nameLabel, name, StageSelectLayout.TILE_IMAGE_WIDTH - 4.0, 39.0, 8.0);

        String badgeText = random ? "?" : choice.variant() == MapVariant.STANDARD ? "M"
                : switch (choice.variant().category) {
                    case "Story Arenas" -> "S";
                    case "Boss Rush Arenas" -> "B";
                    case "Classic Routes" -> "C";
                    default -> "V";
                };
        Label badge = new Label(badgeText);
        badge.setFont(Font.font("Arial Black", FontWeight.BOLD, 12));
        badge.setTextFill(Color.web("#071018"));
        badge.setAlignment(Pos.CENTER);
        badge.setMinSize(24, 24);
        badge.setPrefSize(24, 24);
        badge.setMaxSize(24, 24);
        Color accent = random ? Color.web("#FFE082") : StagePreviewRenderer.accentFor(choice);
        badge.setStyle("-fx-background-color:" + toCssHex(accent) + "; -fx-background-radius:12;"
                + "-fx-border-color:#FFFFFFAA; -fx-border-radius:12;");
        StackPane.setAlignment(badge, Pos.TOP_LEFT);
        StackPane.setMargin(badge, new Insets(5, 0, 0, 5));

        Rectangle imageClip = new Rectangle(StageSelectLayout.TILE_IMAGE_WIDTH,
                StageSelectLayout.TILE_IMAGE_HEIGHT);
        imageClip.setArcWidth(14);
        imageClip.setArcHeight(14);
        image.setClip(imageClip);

        Label cursorTag = new Label("P1");
        cursorTag.setFont(Font.font("Arial Black", FontWeight.BOLD, 11));
        cursorTag.setTextFill(Color.WHITE);
        cursorTag.setAlignment(Pos.CENTER);
        cursorTag.setMinSize(30, 22);
        cursorTag.setPrefSize(30, 22);
        cursorTag.setMaxSize(30, 22);
        cursorTag.setVisible(false);
        cursorTag.setStyle("-fx-background-color:#C3172C; -fx-background-radius:7;"
                + "-fx-border-color:#FFE082; -fx-border-width:2; -fx-border-radius:7;"
                + "-fx-effect:dropshadow(gaussian,#000000AA,5,0.3,0,2);");
        StackPane.setAlignment(cursorTag, Pos.TOP_RIGHT);
        StackPane.setMargin(cursorTag, new Insets(5, 5, 0, 0));

        StackPane picture = new StackPane(image, badge, cursorTag);
        picture.setMinSize(StageSelectLayout.TILE_IMAGE_WIDTH, StageSelectLayout.TILE_IMAGE_HEIGHT);
        picture.setPrefSize(StageSelectLayout.TILE_IMAGE_WIDTH, StageSelectLayout.TILE_IMAGE_HEIGHT);
        picture.setMaxSize(StageSelectLayout.TILE_IMAGE_WIDTH, StageSelectLayout.TILE_IMAGE_HEIGHT);
        picture.setStyle("-fx-background-color:#05070D; -fx-background-radius:7;"
                + "-fx-border-color:#FFFFFF26; -fx-border-radius:7;");

        VBox graphic = new VBox(2, picture, nameLabel);
        graphic.setAlignment(Pos.TOP_CENTER);
        Button tile = new Button();
        tile.setGraphic(graphic);
        tile.setContentDisplay(ContentDisplay.GRAPHIC_ONLY);
        tile.setMinSize(StageSelectLayout.TILE_WIDTH, StageSelectLayout.TILE_HEIGHT);
        tile.setPrefSize(StageSelectLayout.TILE_WIDTH, StageSelectLayout.TILE_HEIGHT);
        tile.setMaxSize(StageSelectLayout.TILE_WIDTH, StageSelectLayout.TILE_HEIGHT);
        tile.setPadding(new Insets(4));
        tile.setFocusTraversable(true);
        tile.setCursor(Cursor.HAND);
        tile.setAccessibleText(name + " stage");
        tile.setOnAction(event -> {
            playButtonClick();
            action.run();
        });

        String baseStyle = "-fx-background-color:linear-gradient(to bottom,#1B2431,#0C1119);"
                + "-fx-background-radius:9; -fx-border-radius:9; -fx-border-width:2;"
                + "-fx-border-color:#546575; -fx-effect:dropshadow(gaussian,#00000099,8,0.25,0,3);";
        String activeStyle = "-fx-background-color:linear-gradient(to bottom,#2A3544,#111722);"
                + "-fx-background-radius:9; -fx-border-radius:9; -fx-border-width:4;"
                + "-fx-border-color:" + toCssHex(accent) + ";"
                + "-fx-effect:dropshadow(gaussian," + toCssHex(accent) + "99,14,0.35,0,0);";
        tile.setStyle(baseStyle);

        Runnable activatePreview = () -> {
            previewAction.run();
            tile.setStyle(activeStyle);
            cursorTag.setVisible(true);
        };
        Runnable deactivate = () -> {
            tile.setStyle(baseStyle);
            cursorTag.setVisible(false);
        };
        tile.setOnMouseEntered(event -> {
            tile.requestFocus();
            if (!tile.isFocused()) {
                activatePreview.run();
            }
            animateStageTileScale(tile, tile.isFocused() ? 1.045 : 1.035);
        });
        tile.setOnMouseExited(event -> {
            if (!tile.isFocused()) {
                deactivate.run();
            }
            animateStageTileScale(tile, tile.isFocused() ? 1.035 : 1.0);
        });
        tile.focusedProperty().addListener((obs, oldValue, focused) -> {
            if (focused) {
                activatePreview.run();
                animateStageTileScale(tile, 1.035);
            } else {
                deactivate.run();
                animateStageTileScale(tile, 1.0);
            }
        });
        return tile;
    }

    private void animateStageTileScale(Node node, double scale) {
        String key = "stage-select-scale-transition";
        Object previous = node.getProperties().remove(key);
        if (previous instanceof ScaleTransition oldTransition) {
            oldTransition.stop();
        }
        ScaleTransition transition = new ScaleTransition(Duration.millis(90), node);
        transition.setToX(scale);
        transition.setToY(scale);
        node.getProperties().put(key, transition);
        transition.setOnFinished(event -> node.getProperties().remove(key, transition));
        transition.play();
    }

    private String toCssHex(Color color) {
        int red = (int) Math.round(color.getRed() * 255.0);
        int green = (int) Math.round(color.getGreen() * 255.0);
        int blue = (int) Math.round(color.getBlue() * 255.0);
        return String.format("#%02X%02X%02X", red, green, blue);
    }

    private String stageSelectDescription(StageChoice choice) {
        if (choice.variant() != MapVariant.STANDARD) {
            return choice.variant().description;
        }
        return switch (choice.map()) {
            case FOREST -> "A broad woodland arena with layered tree platforms and dependable recovery routes.";
            case CITY -> "Fight across integrated neon skyscraper rooftops above a deep midnight city.";
            case SKYCLIFFS -> "Separated mountain shelves reward aerial control, committed jumps, and vent recovery.";
            case VIBRANT_JUNGLE -> "Living tree platforms, vines, nectar, and vertical lanes create a fast canopy brawl.";
            case DESERT -> "A wide desert floor framed by an oasis and elevated mesa routes.";
            case CAVE -> "Enclosed stone lanes and staggered ledges make every approach feel close and dangerous.";
            case BATTLEFIELD -> "A compact floating island with symmetrical perches and honest open blast zones.";
            case BEACON_CROWN -> "Long crown lanes and isolated upper perches surround a lethal central monument.";
            case DOCK -> "Storm piers, ship rigging, crane perches, rescue skiffs, and a working bombardment lever.";
            case FROSTBITE_FJORD -> "Aurora-lit glacier terraces combine slippery movement with carved recovery shelves.";
            case ASHFALL_CATHEDRAL -> "A burning sky-temple of lava routes, ember thermals, and volcanic platforms.";
            case PRISON -> "Steel catwalks, searchlights, and prisoner-release levers tower over a flat cell-block floor.";
            case RESONANCE_HALL -> "A grand performance hall of mirrored balconies and a commanding central stage.";
            case SIGNAL_SPIRE -> "Climb an exposed broadcast tower through asymmetric platforms and open air.";
            case SILENT_AMPHITHEATER -> "A solemn circular arena built from monumental tiers and open duel lanes.";
            case GLASSWIND_CAUSEWAY -> "A colossal suspended bridge where turbine warnings announce alternating crosswinds.";
            case WORLDSEAM -> "Two broken realities face each other across a rift, linked by momentum-preserving gates.";
            case MIDNIGHT_WORKSHOP -> "A moonlit clockwork factory with supported conveyor decks, readable presses, and a sealed gift vault.";
            case CARRION_EXCHANGE -> "A vast suspended salvage exchange whose crane-supported decks and warning-lit magnets reshape its connected fighting lanes.";
            case ONEIRIC_OBSERVATORY -> "A high celestial observatory of connected forecast-glass terraces, brass orbits, and open recovery lanes.";
            case STORMGLASS_REFINERY -> "An offshore crystal works of supported production decks, storm turbines, and warning-lit electrical conduits.";
        };
    }

    private void beginFreshMatchOnMap(Stage stage, MapType map) {
        beginFreshMatchOnStage(stage, StageChoice.main(map));
    }

    private void beginFreshMatchOnStage(Stage stage, StageChoice choice) {
        beginFreshMatch(stage, choice, StageRandomPool.NONE);
    }

    private void beginFreshMatchOnRandomMap(Stage stage, StageRandomPool randomPool) {
        beginFreshMatch(stage, StageChoice.main(MapType.FOREST), randomPool);
    }

    private void beginFreshMatch(Stage stage, StageChoice choice, StageRandomPool randomPool) {
        stageSelectReturn = null;
        stageSelectHandler = null;
        stageSelectRandomHandler = null;
        selectedMap = choice.map();
        selectedMapVariant = choice.variant();
        standardFightRandomMapPool = randomPool == null ? StageRandomPool.NONE : randomPool;
        trainingModeActive = false;
        classicModeActive = false;
        classicEncounter = null;
        classicRun.clear();
        classicRoundIndex = 0;
        classicTeamMode = false;
        Arrays.fill(classicTeams, 1);
        competitionSeriesActive = false;
        Arrays.fill(competitionRoundWins, 0);
        Arrays.fill(competitionTeamWins, 0);
        competitionRoundNumber = 1;
        startMatch(stage);
    }

    private void beginTrainingMatchOnMap(Stage stage, MapType map) {
        beginTrainingMatchOnMap(stage, StageChoice.main(map));
    }

    private void beginTrainingMatchOnMap(Stage stage, StageChoice choice) {
        stageSelectReturn = null;
        stageSelectHandler = null;
        stageSelectRandomHandler = null;
        resetMatchStats();
        selectedMap = choice.map();
        selectedMapVariant = choice.variant();
        standardFightRandomMapPool = StageRandomPool.NONE;
        trainingModeActive = true;
        storyModeActive = false;
        storyReplayMode = false;
        adventureModeActive = false;
        adventureReplayMode = false;
        currentAdventureBattle = null;
        adventureTeamMode = false;
        Arrays.fill(adventureTeams, 1);
        classicModeActive = false;
        classicEncounter = null;
        classicRun.clear();
        classicRoundIndex = 0;
        classicTeamMode = false;
        Arrays.fill(classicTeams, 1);
        competitionSeriesActive = false;
        Arrays.fill(competitionRoundWins, 0);
        Arrays.fill(competitionTeamWins, 0);
        competitionRoundNumber = 1;
        teamModeEnabled = false;
        competitionModeEnabled = false;
        mutatorModeEnabled = false;
        startMatch(stage);
    }

