    boolean cycleLocalTeamForPlayer(int playerIdx) {
        if (playerIdx < 0 || playerIdx >= playerTeams.length) return false;
        playerTeams[playerIdx] = localTeamForPlayer(playerIdx) == 2 ? 1 : 2;
        return true;
    }

    int localTeamForPlayer(int playerIdx) {
        if (playerIdx < 0 || playerIdx >= playerTeams.length) return 1;
        return playerTeams[playerIdx] == 2 ? 2 : 1;
    }

    private void refreshFightSetupTeamButton(Button teamBtn, int idx) {
        if (teamBtn == null) return;
        boolean visible = teamModeEnabled && idx >= 0 && idx < activePlayers;
        int team = localTeamForPlayer(idx);
        teamBtn.setText(teamLabel(team));
        teamBtn.setVisible(visible);
        teamBtn.setManaged(visible);
        teamBtn.setDisable(!visible);
        boolean compact = activePlayers >= 4;
        String bg = toHex(teamColor(team));
        String fg = team == 1 ? "#06131F" : "#FFFFFF";
        teamBtn.setStyle("-fx-background-color: " + bg + "; -fx-text-fill: " + fg + "; "
                + "-fx-font-family: 'Arial Black'; -fx-font-size: " + (compact ? 12 : 13) + "px; "
                + "-fx-font-weight: bold; -fx-background-radius: 14; "
                + "-fx-border-color: rgba(0,0,0,0.82); -fx-border-width: 2.5; "
                + "-fx-border-radius: 14;");
    }

    private void refreshCpuButton(int idx) {
        if (idx < 0 || idx >= cpuButtons.length) return;
        Button cpuBtn = cpuButtons[idx];
        if (cpuBtn == null) return;
        int level = cpuLevels[idx];
        boolean compact = activePlayers >= 4;
        cpuBtn.setText(compact ? "CPU LV " + level : "CPU LV: " + level);
        boolean aiActive = isAI[idx];
        cpuBtn.setDisable(!aiActive);
        cpuBtn.setOpacity(aiActive ? 1.0 : 0.65);
        cpuBtn.setVisible(aiActive);
        cpuBtn.setManaged(aiActive);
        cpuBtn.setStyle("-fx-background-color: " + (aiActive ? "#5D4037" : "#455A64") + "; "
                + "-fx-text-fill: white; -fx-font-family: 'Arial Black'; -fx-font-size: "
                + (compact ? "12px; " : "14px; ")
                + "-fx-font-weight: bold; -fx-background-radius: 16; "
                + "-fx-border-color: rgba(255,255,255,0.16); -fx-border-width: 2; "
                + "-fx-border-radius: 16;");
    }

    private Label createFightSetupSpecialGuideCard(int playerIdx) {
        Label card = new Label();
        card.setWrapText(true);
        card.setTextAlignment(TextAlignment.LEFT);
        card.setAlignment(Pos.CENTER_LEFT);
        card.setPadding(new Insets(8, 10, 8, 10));
        card.setFont(Font.font("Consolas", FontWeight.BOLD, 12.0));
        applyNoEllipsis(card);
        refreshFightSetupSpecialGuideCard(card, playerIdx, null, false, false, activePlayers);
        return card;
    }

    private void refreshFightSetupSpecialGuideCard(Label card, int playerIdx, BirdType type,
                                                   boolean randomPick, boolean active, int activeCount) {
        if (card == null) {
            return;
        }
        double width = activeCount >= 4 ? 286.0 : activeCount == 3 ? 360.0 : 500.0;
        double height = 72.0;
        Color accent = switch (playerIdx) {
            case 0 -> Color.web("#F44336");
            case 1 -> Color.web("#42A5F5");
            case 2 -> Color.web("#FDD835");
            default -> Color.web("#66BB6A");
        };
        String accentHex = toHex(accent);

        card.setVisible(active);
        card.setManaged(active);
        card.setMinSize(width, height);
        card.setPrefSize(width, height);
        card.setMaxSize(width, height);
        if (!active) {
            return;
        }

        boolean waitingForPick = type == null && !randomPick;
        String text = fightSetupSpecialGuideText(playerIdx, type, randomPick);
        card.setFont(Font.font("Consolas", FontWeight.BOLD, activeCount >= 4 ? 10.8 : 12.0));
        card.setTextFill(waitingForPick && playerIdx == 2 ? Color.web("#111111") : Color.WHITE);
        card.setStyle("-fx-background-color: " + (waitingForPick ? accentHex : "rgba(12, 17, 24, 0.94)") + "; "
                + "-fx-background-radius: 12; -fx-border-color: " + accentHex + "; "
                + "-fx-border-width: 2; -fx-border-radius: 12;");
        fitWrappedLabelText(card, text, width - 22.0, height - 16.0, activeCount >= 4 ? 8.8 : 10.0);
    }

    private String fightSetupSpecialGuideText(int playerIdx, BirdType type, boolean randomPick) {
        String prefix = "P" + (playerIdx + 1) + " ";
        if (randomPick) {
            return prefix + "RANDOM\nSPECIALS REVEALED AT START";
        }
        if (type == null) {
            return prefix + "SELECT BIRD\nN: -    S: -\nU: -    D: -";
        }
        String[] moves = specialMoveNames(type);
        return prefix + type.name.toUpperCase(Locale.ROOT)
                + "\nN: " + moves[0] + "    S: " + moves[1]
                + "\nU: " + moves[2] + "    D: " + moves[3];
    }

    private void applyFightSetupSlotLayout(
            StackPane slotCard,
            VBox slot,
            HBox slotHeader,
            HBox slotBody,
            VBox detailColumn,
            StackPane playerBadge,
            StackPane portraitFrame,
            Canvas portrait,
            Label nameLabel,
            Button aiToggle,
            Button teamButton,
            Button inputButton,
            Button skinButton,
            Button cpuButton,
            boolean compact,
            double slotWidth
    ) {
        if (slotCard == null || slot == null || slotHeader == null || slotBody == null
                || detailColumn == null || playerBadge == null || portraitFrame == null
                || portrait == null || nameLabel == null) {
            return;
        }

        double cardHeight = 248.0;
        double padding = compact ? 10.0 : 16.0;
        double slotGap = compact ? 8.0 : 14.0;
        double bodyGap = compact ? 10.0 : 18.0;
        double detailGap = compact ? 6.0 : 10.0;
        double portraitFrameSize = compact ? 108.0 : 170.0;
        double portraitCanvasSize = compact ? 102.0 : 156.0;
        double badgeWidth = compact ? 58.0 : 78.0;
        double badgeHeight = compact ? 34.0 : 44.0;
        double aiWidth = compact ? 96.0 : 132.0;
        double aiHeight = compact ? 34.0 : 40.0;
        double teamWidth = compact ? 78.0 : 112.0;
        double buttonHeight = compact ? 32.0 : 42.0;
        double buttonFontSize = compact ? 11.5 : 14.0;
        double nameFontSize = compact ? 20.0 : 30.0;
        double detailWidth = Math.max(110.0, slotWidth - padding * 2.0 - portraitFrameSize - bodyGap);
        double nameWidth = compact ? 150.0 : Math.min(260.0, detailWidth);

        slotCard.setMinHeight(cardHeight);
        slotCard.setPrefHeight(cardHeight);
        slotCard.setMaxHeight(cardHeight);
        slot.setPadding(new Insets(padding));
        slot.setSpacing(slotGap);
        slotHeader.setSpacing(compact ? 7.0 : 10.0);
        slotBody.setSpacing(bodyGap);
        detailColumn.setSpacing(detailGap);
        detailColumn.setMaxWidth(detailWidth);
        detailColumn.setPrefWidth(detailWidth);

        playerBadge.setMinSize(badgeWidth, badgeHeight);
        playerBadge.setPrefSize(badgeWidth, badgeHeight);
        playerBadge.setMaxSize(badgeWidth, badgeHeight);
        for (Node child : playerBadge.getChildren()) {
            if (child instanceof Label label) {
                label.setFont(Font.font("Arial Black", compact ? 18.0 : 24.0));
            }
        }

        portraitFrame.setMinSize(portraitFrameSize, portraitFrameSize);
        portraitFrame.setPrefSize(portraitFrameSize, portraitFrameSize);
        portraitFrame.setMaxSize(portraitFrameSize, portraitFrameSize);
        if (Math.abs(portrait.getWidth() - portraitCanvasSize) > 0.01
                || Math.abs(portrait.getHeight() - portraitCanvasSize) > 0.01) {
            portrait.setWidth(portraitCanvasSize);
            portrait.setHeight(portraitCanvasSize);
        }

        nameLabel.setFont(Font.font("Arial Black", nameFontSize));
        nameLabel.setMaxWidth(nameWidth);

        if (aiToggle != null) {
            aiToggle.setMinSize(aiWidth, aiHeight);
            aiToggle.setPrefSize(aiWidth, aiHeight);
            aiToggle.setMaxSize(aiWidth, aiHeight);
        }
        if (teamButton != null) {
            teamButton.setMinSize(teamWidth, aiHeight);
            teamButton.setPrefSize(teamWidth, aiHeight);
            teamButton.setMaxSize(teamWidth, aiHeight);
            teamButton.setFont(Font.font("Arial Black", compact ? 12.0 : 13.0));
        }
        applyFightSetupCompactButtonMetrics(inputButton, buttonHeight, buttonFontSize);
        applyFightSetupCompactButtonMetrics(skinButton, buttonHeight, buttonFontSize);
        applyFightSetupCompactButtonMetrics(cpuButton, buttonHeight, compact ? 12.0 : buttonFontSize);
    }

    private void applyFightSetupCompactButtonMetrics(Button button, double height, double fontSize) {
        if (button == null) return;
        button.setMinHeight(height);
        button.setPrefHeight(height);
        button.setMaxHeight(height);
        button.setMaxWidth(Double.MAX_VALUE);
        button.setFont(Font.font("Arial Black", fontSize));
    }

    private String toHex(Color c) {
        return String.format("#%02X%02X%02X", (int) (c.getRed() * 255), (int) (c.getGreen() * 255), (int) (c.getBlue() * 255));
    }

    private String toRgba(Color c, double opacity) {
        Color color = c == null ? Color.WHITE : c;
        double alpha = Math.clamp(opacity, 0.0, 1.0);
        return String.format(Locale.ROOT, "rgba(%d,%d,%d,%.3f)",
                (int) Math.round(color.getRed() * 255),
                (int) Math.round(color.getGreen() * 255),
                (int) Math.round(color.getBlue() * 255),
                alpha);
    }

    private void configureMatchModes() {
        matchController.configureMatchModes();
    }

    private String competitionScoreLine() {
        return matchController.competitionScoreLine();
    }

    boolean usesSmashCombatRules() {
        return smashCombatRulesActive;
    }

    boolean classicUsesSmashRules() {
        if (!classicModeActive || classicEncounter == null
                || bossRushModeActive || ashfallTrialModeActive) {
            return false;
        }
        return classicEncounter.style != ClassicEncounterStyle.BONUS_RELAY
                && classicEncounter.style != ClassicEncounterStyle.NECTAR_DASH
                && classicEncounter.style != ClassicEncounterStyle.REDLINE_RUN
                && classicEncounter.style != ClassicEncounterStyle.ICE_ARCHITECT
                && classicEncounter.style != ClassicEncounterStyle.RIPPLE_HUNT
                && classicEncounter.style != ClassicEncounterStyle.PERFECT_PITCH
                && classicEncounter.style != ClassicEncounterStyle.BETWEEN_LINES
                && classicEncounter.style != ClassicEncounterStyle.OPIUM_LUCID_DASH
                && classicEncounter.style != ClassicEncounterStyle.HEISEN_CALIBRATION
                && classicEncounter.style != ClassicEncounterStyle.TITMOUSE_MEMORY_CACHE
                && classicEncounter.style != ClassicEncounterStyle.NULL_ROCK_BOSS;
    }

    boolean usesDamageScaledKnockback() {
        return smashCombatRulesActive || campaignModeActive;
    }

    double damageScaledLaunchPercent(Bird bird) {
        if (bird == null) {
            return 0.0;
        }
        if (usesSmashCombatRules()) {
            return bird.smashDamagePercent();
        }
        if (!campaignModeActive) {
            return 0.0;
        }
        int index = bird.playerIndex;
        double startingHealth = index >= 0 && index < campaignStartingHealth.length
                ? campaignStartingHealth[index]
                : 0.0;
        if (startingHealth <= 0.0) {
            startingHealth = Math.max(1.0, bird.health);
        }
        return Math.clamp((startingHealth - Math.max(0.0, bird.health)) / startingHealth * 100.0, 0.0, 100.0);
    }

    int smashStartingStocks() {
        return classicUsesSmashRules() ? 1 : SMASH_STARTING_STOCKS;
    }

    private void applyClassicEncounterStockOverrides() {
        if (!classicModeActive || classicEncounter == null) {
            return;
        }
        int authoredRoundIndex = authoredClassicRoundIndex(classicEncounter);
        if (classicSelectedBird == BirdType.PENGUIN
                && classicEncounter.style != ClassicEncounterStyle.ICE_ARCHITECT) {
            // The Iceworks route is built around holding and rebuilding a
            // position. Two stocks keep its uneven battles from ending before
            // that mechanic can matter, while the single giant duel stays a
            // clean one-stock test and the finale uses all three lives.
            scores[0] = classicEncounter.style == ClassicEncounterStyle.GIANT ? 1
                    : classicEncounter.style == ClassicEncounterStyle.LAST_SUN_BOSS ? 3 : 2;
        }
        if (classicSelectedBird == BirdType.ROADRUNNER
                && classicRoundIndex == 0
                && classicEncounter.style == ClassicEncounterStyle.MINIATURE_FLOCK) {
            scores[0] = 2;
        }
        if (classicSelectedBird == BirdType.PIGEON) {
            scores[0] = switch (authoredRoundIndex) {
                case 2, 3 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.EAGLE) {
            scores[0] = switch (authoredRoundIndex) {
                case 3 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.FALCON) {
            scores[0] = switch (authoredRoundIndex) {
                case 3, 5 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.PHOENIX) {
            scores[0] = switch (authoredRoundIndex) {
                case 0, 1, 3, 4, 5 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.HUMMINGBIRD) {
            scores[0] = switch (authoredRoundIndex) {
                case 1, 2, 3, 4 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.TURKEY) {
            scores[0] = switch (authoredRoundIndex) {
                case 0 -> 3;
                case 1, 2, 4, 5 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.ROOSTER) {
            scores[0] = switch (authoredRoundIndex) {
                case 0, 1, 2, 3, 5 -> 2;
                case 4, 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.ROADRUNNER) {
            scores[0] = switch (authoredRoundIndex) {
                case 0, 1 -> 2;
                case 3, 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.SHOEBILL
                && (classicEncounter.style == ClassicEncounterStyle.GIANT
                || classicEncounter.style == ClassicEncounterStyle.SHOEBILL_TRAIL)) {
            scores[0] = 2;
        }
        if (classicSelectedBird == BirdType.SHOEBILL
                && (classicEncounter.style == ClassicEncounterStyle.MARSH_GAUNTLET
                || classicEncounter.style == ClassicEncounterStyle.MIRE_ORACLE_BOSS)) {
            // These encounters ask one fighter to clear consecutive waves or
            // a multi-phase boss. The extra stock belongs to the route rules,
            // not Shoebill's ordinary fighter data.
            scores[0] = 3;
        }
        if (classicSelectedBird == BirdType.MOCKINGBIRD
                && classicEncounter.twist == ClassicTwist.AUDITION_ORDER
                && classicRoundIndex >= 0 && classicRoundIndex <= 3) {
            // The four auditions are learning fights. Charles gets a second
            // stock while the opponent line-up remains at one, avoiding an
            // opening-route wall without changing his normal fighter data.
            scores[0] = 2;
        }
        if (classicSelectedBird == BirdType.MOCKINGBIRD
                && classicEncounter.style == ClassicEncounterStyle.CHARLES_UNDERSTUDIES) {
            scores[0] = 2;
        }
        if (classicSelectedBird == BirdType.MOCKINGBIRD
                && classicEncounter.style == ClassicEncounterStyle.HOLLOW_MAESTRO_BOSS) {
            scores[0] = 3;
        }
        if (classicSelectedBird == BirdType.RAZORBILL
                && classicEncounter.style != ClassicEncounterStyle.BETWEEN_LINES) {
            scores[0] = switch (classicRoundIndex) {
                case 2, 4 -> 2;
                case 6 -> 3;
                case 7 -> 3;
                default -> 1;
            };
        }
        if (classicSelectedBird == BirdType.GRINCHHAWK) {
            scores[0] = switch (classicRoundIndex) {
                case 1, 2, 3, 4 -> 2;
                case 5, 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.VULTURE) {
            scores[0] = switch (classicRoundIndex) {
                case 0 -> 2;
                case 3 -> 3;
                case 7 -> 3;
                default -> scores[0];
            };
            if (classicRoundIndex == 0) {
                for (Bird bird : players) {
                    if (bird != null && getEffectiveTeam(bird.playerIndex) == 2) scores[bird.playerIndex] = 2;
                }
            }
        }
        if (classicSelectedBird == BirdType.OPIUMBIRD) {
            scores[0] = switch (classicRoundIndex) {
                // Opium Bird's opening forecasts are deliberately 2-on-1 or
                // multi-phase learning fights. A second stock keeps those
                // matchups readable without changing ordinary fighter data.
                case 0 -> 2;
                case 1, 2, 3 -> 2;
                // Eleven Dead Ends opens as a one-stock precision duel. Its
                // route-specific wave controller awards a foresight reserve
                // only after the first vision is cleared.
                case 5 -> 1;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.HEISENBIRD) {
            scores[0] = switch (classicRoundIndex) {
                case 0, 4 -> 2;
                case 2 -> 1;
                case 5, 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.TITMOUSE) {
            scores[0] = switch (classicRoundIndex) {
                case 1 -> 1;
                case 4 -> 3;
                case 2, 3, 7 -> 2;
                case 0, 5 -> 1;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.BAT) {
            // Bat's route emphasizes uneven night encounters and a two-stock
            // storm boss. These route lives keep the multi-enemy rounds fair
            // without changing Bat's normal battle durability or moveset.
            scores[0] = switch (classicRoundIndex) {
                case 0, 2, 3 -> 2;
                case 1, 4, 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.PELICAN) {
            // Unequal teams and armored holds are authored around Pelican's
            // deliberate cargo rhythm, not extra normal-mode armor.
            scores[0] = switch (classicRoundIndex) {
                case 0, 1, 3, 6 -> 1;
                case 4 -> 2;
                case 2, 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.RAVEN) {
            scores[0] = switch (classicRoundIndex) {
                case 0, 1, 2, 3, 6 -> 1;
                case 5 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        if (classicSelectedBird == BirdType.GOOSE) {
            scores[0] = switch (classicRoundIndex) {
                case 0, 1, 4, 6 -> 1;
                case 2, 3 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
            if (classicRoundIndex == 4) {
                // The Canyon Interceptor is a genuine giant raid: Goose's
                // formation has numbers, while Falcon has a second stock.
                for (Bird bird : players) {
                    if (bird != null && getEffectiveTeam(bird.playerIndex) == 2) {
                        scores[bird.playerIndex] = 2;
                    }
                }
            }
        }
        if (classicSelectedBird == BirdType.KIWI) {
            scores[0] = switch (classicRoundIndex) {
                case 0, 1, 6 -> 1;
                case 2, 3, 4 -> 2;
                case 7 -> 3;
                default -> scores[0];
            };
        }
        int enemyStocks = switch (classicEncounter.style) {
            case STORM_TYRANT_BOSS, PHOENIX_REBIRTH, BLIGHTWING_BOSS, ICEWORKS_MIRROR -> 2;
            case NULL_ROC_BOSS, STILL_KING_BOSS -> 2;
            case LONG_WINTER_BOSS, DEVOURER_BOSS, BROODBREAKER_BOSS,
                    LAST_SUN_BOSS, HOARDMASTER_BOSS, RAVEN_LAST_DAWN_BOSS,
                    GOOSE_BORDER_KING_BOSS, KIWI_ZENITH_BOSS -> 3;
            default -> 0;
        };
        if (classicSelectedBird == BirdType.ROADRUNNER && authoredRoundIndex == 3) {
            enemyStocks = 2;
        }
        if (enemyStocks <= 0) return;
        for (Bird bird : players) {
            if (bird != null && getEffectiveTeam(bird.playerIndex) == 2) {
                boolean mireEcho = classicEncounter.style == ClassicEncounterStyle.MIRE_ORACLE_BOSS
                        && (bird.name == null || !bird.name.startsWith("Boss:"));
                scores[bird.playerIndex] = mireEcho ? 1 : enemyStocks;
            }
        }
    }

    double smashSuddenDeathPercent() {
        return SMASH_SUDDEN_DEATH_PERCENT;
    }

    double displayedDamageForBird(Bird bird) {
        if (bird == null) {
            return 0.0;
        }
        return usesSmashCombatRules() ? bird.smashDamagePercent() : Math.max(0.0, bird.health);
    }

    int compareBirdPlacements(Bird a, Bird b) {
        if (a == b) return 0;
        if (a == null) return 1;
        if (b == null) return -1;
        if (!usesSmashCombatRules()) {
            int scoreA = eliminations[a.playerIndex] * 100 + damageDealt[a.playerIndex] + (int) a.health;
            int scoreB = eliminations[b.playerIndex] * 100 + damageDealt[b.playerIndex] + (int) b.health;
            return Integer.compare(scoreB, scoreA);
        }

        int scoreCompare = Integer.compare(matchScoreForPlayer(b.playerIndex), matchScoreForPlayer(a.playerIndex));
        if (scoreCompare != 0) return scoreCompare;

        int damagePercentCompare = Double.compare(displayedDamageForBird(a), displayedDamageForBird(b));
        if (damagePercentCompare != 0) return damagePercentCompare;

        int damageCompare = Integer.compare(damageDealt[b.playerIndex], damageDealt[a.playerIndex]);
        if (damageCompare != 0) return damageCompare;

        return Integer.compare(falls[a.playerIndex], falls[b.playerIndex]);
    }

    int compareTeamPlacements(int teamA, int teamB) {
        if (!usesSmashCombatRules()) {
            return Integer.compare(legacyTeamPlacementScore(teamB), legacyTeamPlacementScore(teamA));
        }

        int scoreCompare = Integer.compare(teamMatchScore(teamB), teamMatchScore(teamA));
        if (scoreCompare != 0) return scoreCompare;

        int damagePercentCompare = Double.compare(teamDisplayedDamage(teamA), teamDisplayedDamage(teamB));
        if (damagePercentCompare != 0) return damagePercentCompare;

        int damageCompare = Integer.compare(teamDamageDealt(teamB), teamDamageDealt(teamA));
        if (damageCompare != 0) return damageCompare;

        return Integer.compare(teamFalls(teamA), teamFalls(teamB));
    }

    int matchScoreForPlayer(int playerIndex) {
        return playerIndex >= 0 && playerIndex < scores.length ? scores[playerIndex] : 0;
    }

    boolean playerHasStocksRemaining(int playerIndex) {
        return matchScoreForPlayer(playerIndex) > 0;
    }

    int teamMatchScore(int teamId) {
        int total = 0;
        for (int i = 0; i < activePlayers; i++) {
            if (players[i] != null && getEffectiveTeam(i) == teamId) {
                total += matchScoreForPlayer(i);
            }
        }
        return total;
    }

    double teamDisplayedDamage(int teamId) {
        double total = 0.0;
        for (int i = 0; i < activePlayers; i++) {
            Bird bird = players[i];
            if (bird != null && getEffectiveTeam(i) == teamId) {
                total += displayedDamageForBird(bird);
            }
        }
        return total;
    }

    int teamDamageDealt(int teamId) {
        int total = 0;
        for (int i = 0; i < activePlayers; i++) {
            if (players[i] != null && getEffectiveTeam(i) == teamId) {
                total += Math.max(0, damageDealt[i]);
            }
        }
        return total;
    }

    int teamFalls(int teamId) {
        int total = 0;
        for (int i = 0; i < activePlayers; i++) {
            if (players[i] != null && getEffectiveTeam(i) == teamId) {
                total += Math.max(0, falls[i]);
            }
        }
        return total;
    }

    void clearDockShipBomb() {
        dockShipBomb = null;
    }

    private int legacyTeamPlacementScore(int teamId) {
        int total = 0;
        for (int i = 0; i < activePlayers; i++) {
            Bird bird = players[i];
            if (bird != null && getEffectiveTeam(i) == teamId) {
                total += eliminations[i] * 100 + damageDealt[i] + (int) bird.health;
            }
        }
        return total;
    }

    private void applyMatchModeRuntimeEffects() {
        applyPeregrineRunJetstreams();
        applyCharlesArenaRuntimeEffects();
        applyRazorbillArenaRuntimeEffects();
        applyGrinchHawkArenaRuntimeEffects();
        applyVultureArenaRuntimeEffects();
        applyStormglassRefineryRuntimeEffects();
        if (classicModeActive && !bossRushModeActive && !ashfallTrialModeActive) {
            applyStormTyrantRuntimeEffects();
            applyFalconClassicRuntimeEffects();
            applyPhoenixClassicRuntimeEffects();
            applyHummingbirdClassicRuntimeEffects();
            applyTurkeyClassicRuntimeEffects();
            applyRoosterClassicRuntimeEffects();
            applyRoadrunnerClassicRuntimeEffects();
            applyPenguinClassicRuntimeEffects();
            applyShoebillClassicRuntimeEffects();
            applyCharlesClassicRuntimeEffects();
            applyRazorbillClassicRuntimeEffects();
            applyGrinchHawkClassicRuntimeEffects();
            applyVultureClassicRuntimeEffects();
            applyOpiumBirdClassicRuntimeEffects();
            applyHeisenbirdClassicRuntimeEffects();
            applyTitmouseClassicRuntimeEffects();
        }
        if (bossRushModeActive && classicModeActive) {
            applyBossRushRuntimeEffects();
        }
        if (adventureModeActive) {
            applyAdventureBattleRuntimeEffects();
        }
        if (campaignModeActive) {
            applyCampaignMissionRuntimeEffects();
        }
        matchController.applyMatchModeRuntimeEffects();
    }

    void applyCharlesArenaRuntimeEffects() {
        if (matchEnded) return;
        switch (selectedMap) {
            case RESONANCE_HALL -> applyResonanceHallAcousticPlates();
            case SIGNAL_SPIRE -> applySignalSpirePowerLines();
            case SILENT_AMPHITHEATER -> applySilentAmphitheaterStillnessField();
            default -> {
            }
        }
    }

    void applyGrinchHawkArenaRuntimeEffects() {
        if (matchEnded || selectedMap != MapType.MIDNIGHT_WORKSHOP
                || activeArenaGeometryVariant != MapVariant.STANDARD) return;
        int cycle = Math.floorMod((int) simTick, 420);
        boolean active = cycle >= 340 && cycle < 368;
        for (int slot = 0; slot < activePlayers; slot++) {
            if (midnightPressHitCooldowns[slot] > 0) midnightPressHitCooldowns[slot]--;
            Bird bird = players[slot];
            if (!active || bird == null || bird.health <= 0.0 || bird.classicBonusTarget
                    || midnightPressHitCooldowns[slot] > 0) continue;
            double cx = bird.bodyCenterX();
            double cy = bird.bodyCenterY();
            for (double pressX : MIDNIGHT_PRESS_X) {
                if (Math.abs(cx - pressX) > 145.0 || cy < 430.0 || cy > GROUND_Y - 230.0) continue;
                double dealt = bird.receiveExternalDamage(9.0);
                bird.applyExternalDamageScaledLaunch(Math.signum(cx - pressX) * 8.0, -8.0, dealt);
                midnightPressHitCooldowns[slot] = 42;
                shakeIntensity = Math.max(shakeIntensity, 13.0);
                break;
            }
        }
    }

    static boolean carrionMagnetActiveAtTick(long tick) {
        int cycle = Math.floorMod((int) tick, 360);
        return cycle >= 290 && cycle < 326;
    }

    void applyVultureArenaRuntimeEffects() {
        if (matchEnded || selectedMap != MapType.CARRION_EXCHANGE
                || activeArenaGeometryVariant == MapVariant.RECLAMATION_CORE) return;
        boolean active = carrionMagnetActiveAtTick(simTick);
        for (int slot = 0; slot < activePlayers; slot++) {
            if (carrionMagnetHitCooldowns[slot] > 0) carrionMagnetHitCooldowns[slot]--;
            Bird bird = players[slot];
            if (!active || bird == null || bird.health <= 0.0 || bird.classicBonusTarget) continue;
            double nearestX = CARRION_MAGNET_X[0];
            double nearestDistance = Math.abs(bird.bodyCenterX() - nearestX);
            for (int index = 1; index < CARRION_MAGNET_X.length; index++) {
                double distance = Math.abs(bird.bodyCenterX() - CARRION_MAGNET_X[index]);
                if (distance < nearestDistance) {
                    nearestDistance = distance;
                    nearestX = CARRION_MAGNET_X[index];
                }
            }
            if (nearestDistance > 700.0 || bird.bodyCenterY() > battlefieldIslandY + 80.0) continue;
            double pull = Math.clamp((nearestX - bird.bodyCenterX()) * 0.0028, -1.55, 1.55);
            bird.vx = Math.clamp(bird.vx + pull, -18.0, 18.0);
            bird.vy = Math.max(-16.0, bird.vy - 0.08);
            if (carrionMagnetHitCooldowns[slot] == 0 && nearestDistance < 125.0) {
                bird.stunTime = Math.max(bird.stunTime, 5.0);
                carrionMagnetHitCooldowns[slot] = 24;
                playManagedSfxVaried(bonkClip, 0.20, 1.55, 0.0);
            }
        }
    }

    private void applyResonanceHallAcousticPlates() {
        double stageSurfaceY = GROUND_Y - 220.0;
        for (int i = 0; i < activePlayers; i++) {
            if (resonancePlateReuseFrames[i] > 0) resonancePlateReuseFrames[i]--;
            Bird bird = players[i];
            if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget) {
                resonancePlateHoldFrames[i] = 0;
                resonancePlateIndex[i] = -1;
                continue;
            }

            int plate = -1;
            double bottom = bird.y + bird.bodyHeight();
            if (bird.isOnGround() && Math.abs(bottom - stageSurfaceY) <= 32.0) {
                double centerX = bird.bodyCenterX();
                for (int candidate = 0; candidate < RESONANCE_PLATE_X.length; candidate++) {
                    if (Math.abs(centerX - RESONANCE_PLATE_X[candidate]) <= 155.0) {
                        plate = candidate;
                        break;
                    }
                }
            }
            if (plate < 0) {
                resonancePlateHoldFrames[i] = 0;
                resonancePlateIndex[i] = -1;
                continue;
            }
            if (resonancePlateIndex[i] != plate) {
                resonancePlateIndex[i] = plate;
                resonancePlateHoldFrames[i] = 0;
            }
            resonancePlateHoldFrames[i] = Math.min(RESONANCE_PLATE_HOLD_FRAMES,
                    resonancePlateHoldFrames[i] + 1);
            if (resonancePlateHoldFrames[i] < RESONANCE_PLATE_HOLD_FRAMES
                    || resonancePlateReuseFrames[i] > 0) {
                continue;
            }

            resonancePlateHoldFrames[i] = 0;
            resonancePlateReuseFrames[i] = RESONANCE_PLATE_REUSE_FRAMES;
            bird.y -= 5.0;
            bird.vy = Math.min(bird.vy, -13.6);
            bird.canDoubleJump = true;
            for (int note = -2; note <= 2; note++) {
                Particle spark = new Particle(
                        RESONANCE_PLATE_X[plate] + note * 34.0,
                        stageSurfaceY - 12.0,
                        note * 0.34,
                        -3.8 - Math.abs(note) * 0.22,
                        Color.web("#FFE082"));
                spark.life = 28;
                particles.add(spark);
            }
        }
    }

    enum SignalPowerLineState {
        DORMANT, WARNING, LIVE
    }

    enum StormglassArcState {
        DORMANT, WARNING, LIVE
    }

    static long stormglassArcPhase(long tick, int lineIndex) {
        long localTick = tick - STORMGLASS_ARC_START_DELAY_FRAMES
                - Math.max(0, lineIndex) * (long) STORMGLASS_ARC_STAGGER_FRAMES;
        return localTick < 0L ? -1L : Math.floorMod(localTick, STORMGLASS_ARC_CYCLE_FRAMES);
    }

    static StormglassArcState stormglassArcState(long tick, int lineIndex) {
        long phase = stormglassArcPhase(tick, lineIndex);
        if (phase < 0L) return StormglassArcState.DORMANT;
        if (phase < STORMGLASS_ARC_WARNING_FRAMES) return StormglassArcState.WARNING;
        if (phase < STORMGLASS_ARC_WARNING_FRAMES + STORMGLASS_ARC_LIVE_FRAMES) {
            return StormglassArcState.LIVE;
        }
        return StormglassArcState.DORMANT;
    }

    void applyStormglassRefineryRuntimeEffects() {
        if (matchEnded || selectedMap != MapType.STORMGLASS_REFINERY) return;
        for (int slot = 0; slot < stormglassArcHitCooldowns.length; slot++) {
            if (stormglassArcHitCooldowns[slot] > 0) stormglassArcHitCooldowns[slot]--;
        }
        boolean supercell = activeArenaGeometryVariant == MapVariant.EYE_OF_THE_SUPERCELL;
        for (int line = 0; line < STORMGLASS_ARC_Y.length; line++) {
            long phase = stormglassArcPhase(simTick, line);
            if (phase == 0L) playManagedSfxVaried(fightReadyClip, 0.20, 1.34, 0.018);
            if (stormglassArcState(simTick, line) != StormglassArcState.LIVE) continue;
            double lineY = STORMGLASS_ARC_Y[line] - (supercell ? 28.0 : 0.0);
            for (int slot = 0; slot < activePlayers; slot++) {
                Bird bird = players[slot];
                if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget
                        || stormglassArcHitCooldowns[slot] > 0) continue;
                boolean touches = bird.x + bird.bodyWidth() >= STORMGLASS_ARC_MIN_X[line]
                        && bird.x <= STORMGLASS_ARC_MAX_X[line]
                        && bird.y + bird.bodyHeight() >= lineY - STORMGLASS_ARC_HALF_THICKNESS
                        && bird.y <= lineY + STORMGLASS_ARC_HALF_THICKNESS;
                if (!touches) continue;
                stormglassArcHitCooldowns[slot] = STORMGLASS_ARC_HIT_COOLDOWN_FRAMES;
                double dealt = bird.receiveExternalDamage(STORMGLASS_ARC_DAMAGE);
                if (dealt <= 0.0) continue;
                double centerX = (STORMGLASS_ARC_MIN_X[line] + STORMGLASS_ARC_MAX_X[line]) * 0.5;
                double direction = Math.signum(bird.bodyCenterX() - centerX);
                if (direction == 0.0) direction = (line & 1) == 0 ? -1.0 : 1.0;
                bird.applyExternalDamageScaledLaunch(direction * 7.2, -8.4, dealt);
                bird.applyStun(16);
                shakeIntensity = Math.max(shakeIntensity, 13.0);
                playManagedSfxVaried(bonkClip, 0.28, 1.54, 0.018);
            }
        }
    }

    static long signalPowerLinePhase(long tick, int lineIndex) {
        long localTick = tick - SIGNAL_POWER_LINE_START_DELAY_FRAMES
                - Math.max(0, lineIndex) * (long) SIGNAL_POWER_LINE_STAGGER_FRAMES;
        return localTick < 0L ? -1L : Math.floorMod(localTick, SIGNAL_POWER_LINE_CYCLE_FRAMES);
    }

    static SignalPowerLineState signalPowerLineState(long tick, int lineIndex) {
        long phase = signalPowerLinePhase(tick, lineIndex);
        if (phase < 0L) return SignalPowerLineState.DORMANT;
        if (phase < SIGNAL_POWER_LINE_WARNING_FRAMES) return SignalPowerLineState.WARNING;
        if (phase < SIGNAL_POWER_LINE_WARNING_FRAMES + SIGNAL_POWER_LINE_LIVE_FRAMES) {
            return SignalPowerLineState.LIVE;
        }
        return SignalPowerLineState.DORMANT;
    }

    private void applySignalSpirePowerLines() {
        for (int i = 0; i < signalPowerLineHitCooldowns.length; i++) {
            if (signalPowerLineHitCooldowns[i] > 0) signalPowerLineHitCooldowns[i]--;
        }
        for (int line = 0; line < SIGNAL_LANE_Y.length; line++) {
            long phase = signalPowerLinePhase(simTick, line);
            if (phase == 0L) {
                playManagedSfxVaried(fightReadyClip, 0.22, 1.28, 0.018);
            }
            if (signalPowerLineState(simTick, line) != SignalPowerLineState.LIVE) continue;

            double lineY = SIGNAL_LANE_Y[line];
            for (int slot = 0; slot < activePlayers; slot++) {
                Bird bird = players[slot];
                if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget
                        || signalPowerLineHitCooldowns[slot] > 0) {
                    continue;
                }
                double birdLeft = bird.x;
                double birdRight = bird.x + bird.bodyWidth();
                double birdTop = bird.y;
                double birdBottom = bird.y + bird.bodyHeight();
                boolean touchesWire = birdRight >= SIGNAL_POWER_LINE_MIN_X
                        && birdLeft <= SIGNAL_POWER_LINE_MAX_X
                        && birdBottom >= lineY - SIGNAL_POWER_LINE_HALF_THICKNESS
                        && birdTop <= lineY + SIGNAL_POWER_LINE_HALF_THICKNESS;
                if (!touchesWire) continue;

                signalPowerLineHitCooldowns[slot] = SIGNAL_POWER_LINE_HIT_COOLDOWN_FRAMES;
                double dealt = bird.receiveExternalDamage(SIGNAL_POWER_LINE_DAMAGE);
                if (dealt <= 0.0) continue;
                double launchDirection = Math.signum(bird.bodyCenterX() - 3_000.0);
                if (launchDirection == 0.0) launchDirection = (line & 1) == 0 ? -1.0 : 1.0;
                double damageLaunch = usesDamageScaledKnockback()
                        ? Math.min(4.0, displayedDamageForBird(bird) * 0.022) : 0.0;
                double sizeLaunch = bird.incomingSizeKnockbackMultiplier();
                bird.vx = Math.clamp(bird.vx + launchDirection * (6.5 + damageLaunch) * sizeLaunch,
                        -18.0, 18.0);
                bird.vy = Math.min(bird.vy, -(8.8 + damageLaunch * 0.55) * sizeLaunch);
                bird.applyStun(18);
                shakeIntensity = Math.max(shakeIntensity, 7.0);
                flashAlpha = Math.max(flashAlpha, 0.08);
                playManagedSfxVaried(bonkClip, 0.40, 1.42, 0.035);
                addToKillFeed("LIVE WIRE shocked " + shortName(bird.name)
                        + "! -" + (int) Math.round(dealt) + " DMG");
                if (particleEffectsEnabled) {
                    for (int spark = 0; spark < scaledParticleBurstCount(16); spark++) {
                        double angle = nextParticleRandom() * Math.PI * 2.0;
                        double speed = 3.0 + nextParticleRandom() * 6.0;
                        particles.add(new Particle(
                                bird.bodyCenterX(), bird.bodyCenterY(),
                                Math.cos(angle) * speed,
                                Math.sin(angle) * speed,
                                spark % 3 == 0 ? Color.WHITE : Color.web("#00E5FF")));
                    }
                }
                break;
            }
        }
    }

    private void applySilentAmphitheaterStillnessField() {
        for (Bird bird : players) {
            if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget || bird.stunTime <= 0) continue;
            double dx = (bird.bodyCenterX() - SILENT_FIELD_CENTER_X) / SILENT_FIELD_RADIUS_X;
            double dy = (bird.bodyCenterY() - SILENT_FIELD_CENTER_Y) / SILENT_FIELD_RADIUS_Y;
            if (dx * dx + dy * dy > 1.0) continue;
            bird.vx *= 0.987;
            if (bird.vy < 0.0) bird.vy *= 0.994;
        }
    }

    private void applyPeregrineRunJetstreams() {
        if (activeArenaGeometryVariant != MapVariant.PEREGRINE_RUN || matchEnded) return;
        for (Bird bird : players) {
            if (bird == null || bird.health <= 0.0 || bird.classicBonusTarget || bird.isOnGround()) continue;
            double centerX = bird.bodyCenterX();
            double centerY = bird.bodyCenterY();
            boolean lowerDiveLane = centerY >= GROUND_Y - 820.0
                    && ((centerX >= 900.0 && centerX <= 2140.0)
                    || (centerX >= 3780.0 && centerX <= 5200.0));
            boolean upperDiveLane = centerY >= GROUND_Y - 1450.0
                    && centerY <= GROUND_Y - 760.0
                    && centerX >= 1800.0 && centerX <= 4200.0;
            if (!lowerDiveLane && !upperDiveLane) continue;

            int direction = bird.horizontalInputDirection();
            if (direction == 0 || Math.signum(bird.vx) == -direction) continue;
            bird.vx = Math.clamp(bird.vx + direction * 0.26, -17.5, 17.5);
        }
    }

    private void applyStormTyrantRuntimeEffects() {
        if (classicEncounter == null
                || classicEncounter.style != ClassicEncounterStyle.STORM_TYRANT_BOSS
                || matchEnded) {
            return;
        }
        Bird tyrant = null;
        for (Bird bird : players) {
            if (bird != null && getEffectiveTeam(bird.playerIndex) == 2
                    && bird.type == BirdType.EAGLE) {
                tyrant = bird;
                break;
            }
        }
        if (tyrant == null || matchScoreForPlayer(tyrant.playerIndex) != 1) return;

        boolean phaseAlreadyActive = windVents.stream().anyMatch(vent -> Math.abs(vent.x - 1510.0) < 0.01);
        if (!phaseAlreadyActive) {
            windVents.add(new WindVent(1510, GROUND_Y - 620, 300));
            windVents.add(new WindVent(4190, GROUND_Y - 620, 300));
            addToKillFeed("STORM TYRANT: the shattered crown awakens the crosswinds.");
        }

        tyrant.powerMultiplier = Math.max(tyrant.powerMultiplier, tyrant.basePowerMultiplier * 1.06);
        tyrant.speedMultiplier = Math.max(tyrant.speedMultiplier, tyrant.baseSpeedMultiplier * 1.06);
        if (tyrant.attackCooldown > 0) tyrant.attackCooldown = Math.min(tyrant.attackCooldown, 12);
        if (tyrant.raptorCryReuseTimer > 0) tyrant.raptorCryReuseTimer = Math.min(tyrant.raptorCryReuseTimer, 150);
        if (tyrant.raptorRushReuseTimer > 0) tyrant.raptorRushReuseTimer = Math.min(tyrant.raptorRushReuseTimer, 150);
    }

    private void applyFalconClassicRuntimeEffects() {
        if (classicEncounter == null || matchEnded) return;
        if (classicEncounter.style == ClassicEncounterStyle.PHOENIX_REBIRTH) {
            applyPhoenixRebirthRuntimeEffects();
        } else if (classicEncounter.style == ClassicEncounterStyle.NULL_ROC_BOSS) {
            applyFalconNullRocRuntimeEffects();
        }
    }

    private void applyPhoenixClassicRuntimeEffects() {
        if (classicEncounter == null || matchEnded) return;
        if (classicEncounter.style == ClassicEncounterStyle.BONUS_RELAY
                && "Bonus: Rebirth Relay".equals(classicEncounter.name)) {
            applyRebirthRelayRuntimeEffects();
        } else if (classicEncounter.style == ClassicEncounterStyle.LONG_WINTER_BOSS) {
            applyLongWinterRuntimeEffects();
        }
    }

    private void applyRebirthRelayRuntimeEffects() {
        int collapseStage = simTick >= 2_700 ? 3 : (simTick >= 1_800 ? 2 : (simTick >= 900 ? 1 : 0));
        while (classicPhoenixRelayCollapseStage < collapseStage) {
            int stage = ++classicPhoenixRelayCollapseStage;
            double collapseX = switch (stage) {
                case 1 -> 1_820.0;
                case 2 -> 3_860.0;
                default -> 2_840.0;
            };
            platforms.removeIf(platform -> Math.abs(platform.x - collapseX) < 0.01
                    && Math.abs(platform.w - 320.0) < 0.01);
            addToKillFeed("REBIRTH RELAY: cinder ledge " + stage + " collapsed.");
        }
    }

    private void applyLongWinterRuntimeEffects() {
        Bird winterKing = null;
        for (Bird bird : players) {
            if (bird != null && getEffectiveTeam(bird.playerIndex) == 2
                    && bird.type == BirdType.GRINCHHAWK) {
                winterKing = bird;
                break;
            }
        }
        if (winterKing == null) return;
        int stocks = matchScoreForPlayer(winterKing.playerIndex);

        if (stocks <= 2) {
            cancelLongWinterSleigh(winterKing);
            if (!classicLongWinterBlizzardPhaseActive) {
                classicLongWinterBlizzardPhaseActive = true;
                windVents.add(new WindVent(1_430, GROUND_Y - 420, 300));
                windVents.add(new WindVent(4_270, GROUND_Y - 420, 300));
                addToKillFeed("THE LONG WINTER: the shattered sleigh falls and the blizzard closes in.");
            }
            winterKing.powerMultiplier = Math.max(winterKing.powerMultiplier,
                    winterKing.basePowerMultiplier * 1.04);
            winterKing.speedMultiplier = Math.max(winterKing.speedMultiplier,
                    winterKing.baseSpeedMultiplier * 1.04);
            if (winterKing.attackCooldown > 0) winterKing.attackCooldown = Math.min(winterKing.attackCooldown, 12);
            if (winterKing.specialCooldown > 0) winterKing.specialCooldown = Math.min(winterKing.specialCooldown, 150);
        }

        if (stocks <= 1) {
            cancelLongWinterSleigh(winterKing);
            if (!classicLongWinterFinalPhaseActive) {
                classicLongWinterFinalPhaseActive = true;
                double phasePower = Math.max(winterKing.powerMultiplier,
                        winterKing.basePowerMultiplier * 1.08);
                double phaseSpeed = Math.max(0.92, winterKing.baseSpeedMultiplier * 0.90);
                winterKing.setBaseMultipliers(1.62, phasePower, phaseSpeed);
                addToKillFeed("FINAL THAW: the Winter King armors itself in the last caldera ice.");
            }
            if (winterKing.attackCooldown > 0) winterKing.attackCooldown = Math.min(winterKing.attackCooldown, 9);
            if (winterKing.specialCooldown > 0) winterKing.specialCooldown = Math.min(winterKing.specialCooldown, 110);
        }
    }

    private void cancelLongWinterSleigh(Bird winterKing) {
        if (winterKing == null) return;
        if (winterKing.grinchSleighRiding) {
            GrinchhawkSpecials.dismountSleigh(winterKing, false);
        }
    }

    boolean isLongWinterFinalForm(Bird bird) {
        return bird != null
                && classicModeActive
                && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.LONG_WINTER_BOSS
                && bird.type == BirdType.GRINCHHAWK
                && getEffectiveTeam(bird.playerIndex) == 2
                && matchScoreForPlayer(bird.playerIndex) <= 1;
    }

    private void applyPhoenixRebirthRuntimeEffects() {
        Bird phoenix = null;
        for (Bird bird : players) {
            if (bird != null && getEffectiveTeam(bird.playerIndex) == 2
                    && bird.type == BirdType.PHOENIX) {
                phoenix = bird;
                break;
            }
        }
        if (phoenix == null || matchScoreForPlayer(phoenix.playerIndex) != 1) return;

        if (!classicPhoenixRebirthPhaseActive) {
            classicPhoenixRebirthPhaseActive = true;
            applyPreviewSkinChoiceToBird(phoenix, BirdType.PHOENIX, ASHEN_SOVEREIGN_PHOENIX_SKIN);
            addToKillFeed("ASHEN PHASE: Phoenix returns faster and the cathedral geysers burn hotter.");
            redFlashAlpha = Math.max(redFlashAlpha, 0.24);
        }

        phoenix.powerMultiplier = Math.max(phoenix.powerMultiplier, phoenix.basePowerMultiplier * 1.06);
        phoenix.speedMultiplier = Math.max(phoenix.speedMultiplier, phoenix.baseSpeedMultiplier * 1.08);
        if (phoenix.attackCooldown > 0) phoenix.attackCooldown = Math.min(phoenix.attackCooldown, 10);
        if (phoenix.specialCooldown > 0) phoenix.specialCooldown = Math.min(phoenix.specialCooldown, 42);
        if (phoenix.phoenixNeutralReuseTimer > 0) {
            phoenix.phoenixNeutralReuseTimer = Math.min(phoenix.phoenixNeutralReuseTimer, 42);
        }
        if (phoenix.phoenixFireballReuseTimer > 0) {
            phoenix.phoenixFireballReuseTimer = Math.min(phoenix.phoenixFireballReuseTimer, 52);
        }
        if (phoenix.phoenixLavaReuseTimer > 0) {
            phoenix.phoenixLavaReuseTimer = Math.min(phoenix.phoenixLavaReuseTimer, 34);
        }
    }

    private void applyFalconNullRocRuntimeEffects() {
        Bird nullRoc = null;
        for (Bird bird : players) {
            if (bird != null && getEffectiveTeam(bird.playerIndex) == 2
                    && bird.type == BirdType.VULTURE && bird.isNullRockForm()) {
                nullRoc = bird;
                break;
            }
        }
        if (nullRoc == null) return;
        int stocks = matchScoreForPlayer(nullRoc.playerIndex);

        // Null Roc can hover far from ordinary horizontal launch routes. Once
        // Falcon has genuinely broken a phase's shell, send that stock through
        // the nearest side blast zone. This turns accumulated damage into a
        // visible phase break without granting Falcon a route-only attack.
        if (nullRoc.smashDamagePercent() >= 300.0) {
            Bird falcon = players[0];
            double direction = falcon == null || nullRoc.bodyCenterX() >= falcon.bodyCenterX() ? 1.0 : -1.0;
            nullRoc.vx = direction * Math.max(52.0, Math.abs(nullRoc.vx));
            nullRoc.vy = Math.min(nullRoc.vy, -6.0);
            nullRoc.stunTime = Math.max(nullRoc.stunTime, 36.0);
        }

        if (stocks <= 2) {
            if (!classicNullRocAscentPhaseActive) {
                classicNullRocAscentPhaseActive = true;
                nullRoc.setTrailerSmashDamagePercent(125.0);
                windVents.add(new WindVent(1880, GROUND_Y - 1180, 300));
                windVents.add(new WindVent(3830, GROUND_Y - 1260, 300));
                addToKillFeed("NULL ROC: the hunt climbs into the shattered Crown's upper winds.");
            }
            // Stock loss and respawn complete after the phase edge is seen.
            // Reapply the authored launch percent until the fresh phase has it;
            // otherwise respawn silently resets the boss to 0% and makes all
            // later stocks much harder than the opening one.
            if (nullRoc.smashDamagePercent() < 125.0) {
                nullRoc.setTrailerSmashDamagePercent(125.0);
            }
            nullRoc.speedMultiplier = Math.max(nullRoc.speedMultiplier, nullRoc.baseSpeedMultiplier * 1.04);
        }

        if (stocks <= 1) {
            if (!classicNullRocFinalPhaseActive) {
                classicNullRocFinalPhaseActive = true;
                nullRoc.setTrailerSmashDamagePercent(132.0);
                addToKillFeed("CORNERED PREY: Null Roc attacks faster, but every special keeps its cooldown.");
                redFlashAlpha = Math.max(redFlashAlpha, 0.20);
            }
            if (nullRoc.smashDamagePercent() < 132.0) {
                nullRoc.setTrailerSmashDamagePercent(132.0);
            }
            nullRoc.powerMultiplier = Math.max(nullRoc.powerMultiplier, nullRoc.basePowerMultiplier * 1.08);
            nullRoc.speedMultiplier = Math.max(nullRoc.speedMultiplier, nullRoc.baseSpeedMultiplier * 1.08);
            if (nullRoc.attackCooldown > 0) nullRoc.attackCooldown = Math.min(nullRoc.attackCooldown, 10);
            if (nullRoc.specialCooldown > 0) nullRoc.specialCooldown = Math.min(nullRoc.specialCooldown, 210);
        }
    }

    private void applyCampaignMissionRuntimeEffects() {
        if (isCrownDuelArena()) {
            applyCrownDuelRuntimeEffects();
        }
        if (isNullRockCampaign()) {
            applyNullRockRuntimeEffects();
        }
    }

    private boolean isNullRockCampaign() {
        return campaignModeActive && currentCampaignMission != null
                && currentCampaignMission.arenaVariant() == StoryCampaign.ArenaVariant.NULL_ROCK;
    }

    boolean permitsNullRockVoidRecovery(Bird bird) {
        // Null Rock's story boss keeps its signature refusal of the void. The
        // Falcon route's Null Roc is a separate two-stock hunt on a vertical
        // arena, where bottom launch must count or the encounter has no
        // reliable completion path.
        return bird != null && !(classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.NULL_ROC_BOSS);
    }

    private boolean isNullRockDuelPhase() {
        if (!isNullRockCampaign()) return false;
        if (campaignMissionController != null) {
            return campaignMissionController.currentPhase().objective()
                    == StoryCampaign.ObjectiveType.BOSS_PHASES;
        }
        int startPhase = Math.clamp(campaignRetryPhaseIndex, 0,
                Math.max(0, currentCampaignMission.phases().size() - 1));
        return currentCampaignMission.phases().get(startPhase).objective()
                == StoryCampaign.ObjectiveType.BOSS_PHASES;
    }

    boolean isCampaignNullRockDuelBoss(Bird bird) {
        if (classicModeActive && classicEncounter != null
                && classicEncounter.style == ClassicEncounterStyle.NULL_ROCK_BOSS
                && bird != null && getEffectiveTeam(bird.playerIndex) == 2
                && bird.isNullRockForm()) {
            return true;
        }
        return isNullRockDuelPhase() && bird != null && activePlayers > 1
                && bird == players[1] && campaignTeams[1] == 2
                && campaignBossSlots[1] && bird.isNullRockForm();
    }

    /**
     * The true form is an arena-scale commander, not another oversized fighter.
     * Fixed tick gates keep its flock calls deterministic while the authored
     * objective controller owns all phase advancement.
     */
    private void applyNullRockRuntimeEffects() {
        if (campaignMissionController == null || campaignMissionController.complete()
                || campaignMissionController.failed()) {
            return;
        }
        if (isNullRockDuelPhase()) {
            applyCampaignNullRockDuelRuntimeEffects();
            return;
        }
        int phase = campaignMissionController.phaseIndex();
        if (phase > campaignNullRockPhaseAnnounced) {
            campaignNullRockPhaseAnnounced = phase;
            campaignNullRockWave = 0;
            crowMinions.clear();
            String message = switch (phase) {
                case 0 -> "NULL ROCK: Break the roosts that command its shadow flock.";
                case 1 -> "ALL WINGS: Hold the center while every signature joins the counter-pulse.";
                default -> "FINAL CHARGE: Reach the exposed cavern heart and arm the breach.";
            };
            addToKillFeed(message);
            shakeIntensity = Math.max(shakeIntensity, 18.0 + phase * 5.0);
            playManagedSfxVaried(hugewaveClip, 0.64 + phase * 0.07, 0.72 - phase * 0.06, 0.018);
        }

        long interval = Math.max(210L, 430L - phase * 70L);
        if (simTick > 0 && simTick % interval == 0L && crowMinions.size() < 12) {
            int count = 2 + phase;
            for (int i = 0; i < count; i++) {
                double lane = (campaignNullRockWave * 977.0 + i * 1381.0) % 4800.0;
                double x = 600.0 + lane;
                double y = 260.0 + ((campaignNullRockWave + i) % 4) * 150.0;
                int variant = phase >= 2 && i == 0
                        ? CrowMinion.VARIANT_GIANT_CROW
                        : CrowMinion.VARIANT_VOID_RAVEN;
                crowMinions.add(new CrowMinion(x, y, players[0])
                        .withVariant(variant)
                        .withSpeedMultiplier(1.02 + phase * 0.08));
            }
            campaignNullRockWave++;
            addToKillFeed("THE NULL ROCK CALLS SHADOW WING " + campaignNullRockWave + ".");
        }
    }

    private void applyCampaignNullRockDuelRuntimeEffects() {
        Bird boss = activePlayers > 1 ? players[1] : null;
        if (boss == null || boss.health <= 0.0) return;

        int stage = campaignMissionController.bossSegment();
        if (stage <= campaignNullRockDuelStage) return;
        campaignNullRockDuelStage = stage;
        boss.specialCooldown = 0;
        boss.crowSwarmCooldown = 0;
        shakeIntensity = Math.max(shakeIntensity, 18.0 + stage * 5.0);

        switch (stage) {
            case 1 -> {
                boss.overchargeAttackTimer = Math.max(boss.overchargeAttackTimer, 180);
                addToKillFeed("NULL ROCK PHASE II: The broken shell starts hunting.");
            }
            case 2 -> {
                boss.rageTimer = Math.max(boss.rageTimer, 220);
                boss.overchargeAttackTimer = Math.max(boss.overchargeAttackTimer, 210);
                windVents.clear();
                windVents.add(new WindVent(battlefieldIslandX + 260.0,
                        battlefieldIslandY - 170.0, 330.0));
                windVents.add(new WindVent(battlefieldIslandX + battlefieldIslandW - 590.0,
                        battlefieldIslandY - 170.0, 330.0));
                addToKillFeed("NULL ROCK PHASE III: The cavern starts breathing with it.");
            }
            case 3 -> {
                boss.rageTimer = Math.max(boss.rageTimer, 300);
                boss.overchargeAttackTimer = Math.max(boss.overchargeAttackTimer, 270);
                windVents.clear();
                windVents.add(new WindVent(battlefieldIslandX + battlefieldIslandW * 0.5 - 270.0,
                        battlefieldIslandY - 330.0, 540.0));
                addToKillFeed("NULL ROCK PHASE IV: The living meteor tears free.");
            }
            default -> {
                boss.rageTimer = Math.max(boss.rageTimer, 420);
                boss.overchargeAttackTimer = Math.max(boss.overchargeAttackTimer, 360);
                windVents.clear();
                addToKillFeed("FINAL PHASE: No flock. No shield. Finish it.");
            }
        }
        playManagedSfxVaried(hugewaveClip, 0.74 + Math.min(0.16, stage * 0.035),
                0.68 - Math.min(0.18, stage * 0.035), 0.014);
    }

    /**
     * Turns Cut the Lock into a staged command-bridge duel without adding
     * wall-clock or random simulation decisions. Each threshold is one-shot,
     * so replay and headless runs see the same hazards and Eagle buffs.
     */
    private void applyCrownDuelRuntimeEffects() {
        Bird eagle = null;
        int eagleSlot = -1;
        for (int slot = 1; slot < activePlayers; slot++) {
            Bird candidate = players[slot];
            if (candidate != null && candidate.health > 0.0
                    && campaignTeams[slot] == 2 && campaignBossSlots[slot]
                    && candidate.type == BirdType.EAGLE) {
                eagle = candidate;
                eagleSlot = slot;
                break;
            }
        }
        if (eagle == null) {
            return;
        }

        double startingHealth = campaignStartingHealth[eagleSlot] > 0.0
                ? campaignStartingHealth[eagleSlot]
                : Math.max(1.0, eagle.health);
        double healthRatio = Math.clamp(eagle.health / startingHealth, 0.0, 1.0);
        int nextStage = healthRatio <= 0.25 ? 4
                : healthRatio <= 0.50 ? 3
                : healthRatio <= 0.75 ? 2
                : 1;
        if (nextStage <= campaignCrownDuelStage) {
            return;
        }
        campaignCrownDuelStage = nextStage;

        switch (nextStage) {
            case 1 -> {
                addToKillFeed("DUEL: Eagle has sealed the command bridge.");
                shakeIntensity = Math.max(shakeIntensity, 8.0);
            }
            case 2 -> {
                windVents.clear();
                windVents.add(new WindVent(
                        CROWN_DUEL_BRIDGE_X + 170.0,
                        CROWN_DUEL_BRIDGE_Y - 120.0,
                        330.0));
                windVents.add(new WindVent(
                        CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W - 500.0,
                        CROWN_DUEL_BRIDGE_Y - 120.0,
                        330.0));
                eagle.specialCooldown = 0;
                eagle.overchargeAttackTimer = Math.max(eagle.overchargeAttackTimer, 100);
                addToKillFeed("EAGLE: Command crosswinds released.");
                shakeIntensity = Math.max(shakeIntensity, 14.0);
                playManagedSfxVaried(hugewaveClip, 0.58, 0.82, 0.018);
            }
            case 3 -> {
                windVents.clear();
                windVents.add(new WindVent(
                        CROWN_DUEL_BRIDGE_X + 80.0,
                        CROWN_DUEL_BRIDGE_Y - 130.0,
                        390.0));
                windVents.add(new WindVent(
                        CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W * 0.5 - 165.0,
                        CROWN_DUEL_BRIDGE_Y - 180.0,
                        430.0));
                windVents.add(new WindVent(
                        CROWN_DUEL_BRIDGE_X + CROWN_DUEL_BRIDGE_W - 410.0,
                        CROWN_DUEL_BRIDGE_Y - 130.0,
                        390.0));
                eagle.specialCooldown = 0;
                eagle.rageTimer = Math.max(eagle.rageTimer, 160);
                eagle.overchargeAttackTimer = Math.max(eagle.overchargeAttackTimer, 180);
                eagle.powerMultiplier = Math.max(
                        eagle.powerMultiplier, eagle.basePowerMultiplier * 1.08);
                eagle.speedMultiplier = Math.max(
                        eagle.speedMultiplier, eagle.baseSpeedMultiplier * 1.06);
                addToKillFeed("EAGLE: The bridge is still mine.");
                shakeIntensity = Math.max(shakeIntensity, 20.0);
                playManagedSfxVaried(hugewaveClip, 0.70, 0.68, 0.016);
            }
            case 4 -> {
                eagle.specialCooldown = 0;
                eagle.rageTimer = Math.max(eagle.rageTimer, 300);
                eagle.overchargeAttackTimer = Math.max(eagle.overchargeAttackTimer, 260);
                eagle.powerMultiplier = Math.max(
                        eagle.powerMultiplier, eagle.basePowerMultiplier * 1.15);
                eagle.speedMultiplier = Math.max(
                        eagle.speedMultiplier, eagle.baseSpeedMultiplier * 1.10);
                addToKillFeed("FINAL COMMAND: Eagle abandons restraint.");
                shakeIntensity = Math.max(shakeIntensity, 26.0);
                playManagedSfxVaried(hugewaveClip, 0.82, 0.56, 0.014);
            }
            default -> {
            }
        }
    }

    private void updateMatchTimerState() {
        matchController.updateTimerAndSuddenDeath();
    }

    private void checkForMatchCompletion() {
        matchController.checkForMatchCompletion();
    }

    void checkCampaignMissionCompletion() {
        if (!campaignModeActive || matchEnded || currentCampaignMission == null
                || campaignMissionController == null) {
            return;
        }
        enforcePermanentCampaignEnemyEliminations();
        updateCampaignFrontlineRotation(false);
        updateCampaignSignatureAssist();
        List<StoryMissionController.Participant> snapshot = new ArrayList<>();
        for (int i = 0; i < activePlayers; i++) {
            Bird bird = players[i];
            if (bird == null) continue;
            snapshot.add(new StoryMissionController.Participant(
                    i,
                    getEffectiveTeam(i),
                    bird.bodyCenterX(),
                    bird.bodyCenterY(),
                    bird.health,
                    campaignStartingHealth[i] > 0.0 ? campaignStartingHealth[i] : Math.max(1.0, bird.health)
            ));
        }

        StoryMissionController.TickResult result = campaignMissionController.tick(snapshot);
        int bossSegment = campaignMissionController.bossSegment();
        if (bossSegment > campaignBossSegmentAnnounced) {
            campaignBossSegmentAnnounced = bossSegment;
            if (!isNullRockDuelPhase()) {
                addToKillFeed("BOSS PHASE " + (bossSegment + 1) + ": the Crown changes its attack pattern.");
                shakeIntensity = Math.max(shakeIntensity, 14 + bossSegment * 3);
            }
        }
        if (result.outcome() == StoryMissionController.Outcome.PHASE_ADVANCED) {
            if (isNullRockDuelPhase()) {
                enterCampaignNullRockDuel();
            } else {
                spawnReservedCampaignBossesForCurrentPhase();
            }
            campaignBossSegmentAnnounced = 0;
            addToKillFeed("CHECKPOINT: " + result.message());
            if (stillSkyProgress.difficulty.bonusHealthPickup) {
                powerUps.add(new PowerUp(3000, GROUND_Y - 650, PowerUpType.HEALTH));
            }
            playCampaignMidMissionCutscene(result.message());
            return;
        }
        if (result.outcome() == StoryMissionController.Outcome.COMPLETE) {
            campaignMissionWon = true;
            Bird winner = players[0];
            matchController.triggerMatchEnd(winner);
            return;
        }
        if (result.outcome() == StoryMissionController.Outcome.FAILED) {
            campaignMissionWon = false;
            campaignRetryPhaseIndex = campaignMissionController.checkpointPhaseIndex();
            Bird winner = null;
            for (int i = 0; i < activePlayers; i++) {
                if (players[i] != null && players[i].health > 0 && getEffectiveTeam(i) == 2) {
                    winner = players[i];
                    break;
                }
            }
            matchController.triggerMatchEnd(winner);
        }
    }

    /**
     * Campaign opponents are authored encounters, not stock fighters. Once an
     * enemy is defeated, its slot stays retired across objective handoffs and
     * temporary cutscenes. This also guards against character-specific rebirth
     * mechanics restoring an encounter actor after its defeat was recorded.
     */
    private void enforcePermanentCampaignEnemyEliminations() {
        for (int slot = 1; slot < activePlayers; slot++) {
            if (campaignTeams[slot] != 2 || campaignReservedBossSlots[slot]) {
                continue;
            }
            Bird enemy = players[slot];
            if (enemy == null) {
                continue;
            }
            if (enemy.health <= 0.0) {
                campaignEnemyEliminated[slot] = true;
            }
            if (!campaignEnemyEliminated[slot]) {
                continue;
            }
            enemy.health = 0.0;
            enemy.vx = 0.0;
            enemy.vy = 0.0;
            enemy.x = -2_400.0 - slot * 180.0;
            enemy.y = WORLD_HEIGHT + 900.0;
            isAI[slot] = false;
        }
    }

    boolean campaignEnemyEliminationIsPermanent(int playerIndex) {
        return campaignModeActive
                && playerIndex > 0
                && playerIndex < activePlayers
                && campaignTeams[playerIndex] == 2
                && !campaignReservedBossSlots[playerIndex];
    }

    void markCampaignEnemyEliminated(int playerIndex) {
        if (campaignEnemyEliminationIsPermanent(playerIndex)) {
            campaignEnemyEliminated[playerIndex] = true;
        }
    }

    double campaignObjectiveAssistTargetX(Bird ally) {
        if (!campaignModeActive || campaignMissionController == null || ally == null
                || ally.health <= 0.0 || ally.playerIndex <= 0
                || ally.playerIndex >= activePlayers || !isAI[ally.playerIndex]
                || getEffectiveTeam(ally.playerIndex) != 1) {
            return Double.NaN;
        }
        for (int i = 0; i < activePlayers; i++) {
            Bird candidate = players[i];
            if (candidate != null && candidate.health > 0.0 && getEffectiveTeam(i) == 2) {
                return Double.NaN;
            }
        }
        return campaignMissionController.objectiveAssistTargetX();
    }

    private void updateCampaignFrontlineRotation(boolean force) {
        if (!campaignModeActive || currentCampaignMission == null
                || currentCampaignMission.arenaVariant() != StoryCampaign.ArenaVariant.NULL_ROCK
                || isNullRockDuelPhase()
                || activePlayers < 3) {
            return;
        }
        int supportEnd = activePlayers;
        int supportCount = Math.max(1, supportEnd - 1);
        int window = (int) (simTick / (5L * 60L));
        if (!force && window == campaignFrontlineWindow) {
            return;
        }
        campaignFrontlineWindow = window;
        int start = (window * 4) % supportCount;
        for (int slot = 1; slot < supportEnd; slot++) {
            int relative = slot - 1;
            int distance = Math.floorMod(relative - start, supportCount);
            boolean frontline = distance < Math.min(4, supportCount);
            isAI[slot] = frontline && players[slot] != null && players[slot].health > 0;
        }
        addToKillFeed("FRONTLINE ROTATION " + (window + 1) + ": four coalition signatures are live.");
    }

    private void updateCampaignSignatureAssist() {
        if (!campaignModeActive || currentCampaignMission == null
                || currentCampaignMission.arenaVariant() != StoryCampaign.ArenaVariant.NULL_ROCK
                || isNullRockDuelPhase()
                || simTick <= 0 || simTick % 75L != 0L) {
            return;
        }
        int supportEnd = activePlayers;
        int supportCount = Math.max(1, supportEnd - 1);
        int supportSlot = 1 + (int) (((simTick / 75L) - 1L) % supportCount);
        Bird support = players[supportSlot];
        if (support == null || support.health <= 0) return;
        isAI[supportSlot] = true;
        support.specialCooldown = 0;
        support.overchargeAttackTimer = Math.max(support.overchargeAttackTimer, 90);
        addToKillFeed("SIGNATURE ASSIST: " + support.type.name + " enters with a charged special.");
    }

    private void spawnReservedCampaignBossesForCurrentPhase() {
        if (currentCampaignMission == null || campaignMissionController == null
                || campaignMissionController.currentPhase().objective()
                != StoryCampaign.ObjectiveType.BOSS_PHASES) {
            return;
        }
        int slot = 1 + currentCampaignMission.allies().size();
        int spawned = 0;
        for (StoryCampaign.Fighter fighter : currentCampaignMission.enemies()) {
            if (slot >= activePlayers) {
                break;
            }
            if (campaignReservedBossSlots[slot]) {
                double centerX = battlefieldIslandW > 0.0
                        ? battlefieldIslandX + battlefieldIslandW * 0.70
                        : WORLD_WIDTH * 0.70;
                double floorY = battlefieldIslandW > 0.0 ? battlefieldIslandY : GROUND_Y;
                Bird boss = createCampaignFighter(fighter, slot, centerX, true);
                campaignEnemyEliminated[slot] = false;
                boss.x = centerX - boss.bodyWidth() * 0.5;
                boss.y = floorY - boss.bodyHeight();
                boss.prevX = boss.x;
                boss.prevY = boss.y;
                boss.vx = 0.0;
                boss.vy = 0.0;
                campaignStartingHealth[slot] = boss.health;
                campaignReservedBossSlots[slot] = false;
                spawned++;
            }
            slot++;
        }
        if (spawned > 0) {
            addToKillFeed(spawned == 1
                    ? "BOSS ENTERS: the commander takes the field."
                    : "BOSSES ENTER: the commanders take the field.");
            shakeIntensity = Math.max(shakeIntensity, 18.0);
            playManagedSfxVaried(hugewaveClip, 0.62, 0.76, 0.02);
        }
    }

    private void showCampaignPhaseBanner(String message) {
        if (gameRoot == null || message == null || message.isBlank()) return;
        Label banner = new Label(message.toUpperCase(Locale.ROOT));
        banner.setFont(Font.font("Arial Black", FontWeight.BOLD, 30));
        banner.setTextFill(Color.WHITE);
        banner.setPadding(new Insets(14, 30, 14, 30));
        banner.setStyle("-fx-background-color: rgba(4,13,24,0.88);"
                + "-fx-border-color: #80DEEA; -fx-border-width: 2;"
                + "-fx-background-radius: 14; -fx-border-radius: 14;");
        StackPane.setAlignment(banner, Pos.TOP_CENTER);
        StackPane.setMargin(banner, new Insets(120, 0, 0, 0));
        gameRoot.getChildren().add(banner);
        PauseTransition pause = new PauseTransition(Duration.seconds(2.25));
        pause.setOnFinished(event -> {
            if (gameRoot != null) gameRoot.getChildren().remove(banner);
        });
        pause.play();
    }

    private void playCampaignMidMissionCutscene(String nextObjective) {
        if (currentStage == null || gameplayScene == null || timer == null
                || currentCampaignMission == null) {
            showCampaignPhaseBanner(nextObjective);
            return;
        }
        AnimationTimer gameplayTimer = timer;
        gameplayTimer.stop();
        hitstopFrames = 0;
        dramaticSlowMoTicks = 0;
        accumulator = 0L;
        Scene resumeScene = parkGameplaySceneForTemporaryFullscreenSwap(currentStage);
        String speaker = campaignSelectedBird == BirdType.MOCKINGBIRD
                ? "Charles"
                : campaignSelectedBird.name;
        int phase = campaignMissionController == null ? 0 : campaignMissionController.phaseIndex();
        StoryCampaign.Cutscene beat;
        if (isNullRockDuelPhase()) {
            beat = new StoryCampaign.Cutscene(
                    currentCampaignMission.id() + "_final_duel",
                    "The Last Wing",
                    selectedMap,
                    "music-null-rock.mp3",
                    StoryCampaignContent.nullRockDuelDialogue(speaker, campaignSelectedBird),
                    List.of(campaignSelectedBird),
                    false,
                    true
            );
        } else {
            beat = new StoryCampaign.Cutscene(
                    currentCampaignMission.id() + "_phase_" + phase,
                    "Phase Break: " + nextObjective,
                    selectedMap,
                    "campaign_phase",
                    StoryCampaignContent.campaignPhaseDialogue(
                            speaker,
                            campaignSelectedBird,
                            nextObjective
                    ),
                    List.of(campaignSelectedBird),
                    false,
                    false
            );
        }
        storyCutscenePlayer.play(currentStage, beat, campaignSelectedBird, campaignSelectedSkinKey, () -> {
            setCampaignScene(currentStage, resumeScene);
            resetAfterCampaignCutscene();
            gameplayTimer.start();
            if (gameRoot != null) gameRoot.requestFocus();
        });
    }

    private void prepareMatchStart(Stage stage) {
        matchController.prepareMatchStart(stage);
    }

    private void spawnPowerUp() {
        if (competitionModeEnabled && !storyModeActive && !adventureModeActive && !classicModeActive) return;
        if (isCrownDuelArena()) return;
        if (simTick - lastPowerUpSpawnTime < activePowerUpSpawnInterval) return;
        double spawnChance = 0.8;
        if (random.nextDouble() < spawnChance) {
            double[] spawn = pickPowerUpSpawnPoint();
            double x = spawn[0];
            double y = spawn[1];
            PowerUpType type;
            if (selectedMap == MapType.SKYCLIFFS && random.nextDouble() < 0.35) {
                type = PowerUpType.THERMAL;
            } else if (selectedMap == MapType.CITY && random.nextDouble() < 0.4) {
                type = PowerUpType.NEON;
            } else if (selectedMap == MapType.VIBRANT_JUNGLE && random.nextDouble() < 0.4) {
                type = PowerUpType.VINE_GRAPPLE;                                    // NEW
            } else {
                PowerUpType[] common = {
                        PowerUpType.HEALTH, PowerUpType.SPEED, PowerUpType.RAGE, PowerUpType.SHRINK,
                        PowerUpType.OVERCHARGE, PowerUpType.TITAN
                };
                type = common[random.nextInt(common.length)];
            }
            powerUps.add(new PowerUp(x, y, type));
        }
        lastPowerUpSpawnTime = simTick;
    }

    private double[] pickPowerUpSpawnPoint() {
        boolean battlefield = (usesIslandBoundsForCurrentArena()
                || selectedMap == MapType.DOCK)
                && battlefieldIslandW > 0;
        double battlefieldMinX = 0;
        double battlefieldMaxX = 0;
        if (battlefield) {
            double margin = Math.clamp(battlefieldIslandW * 0.08, 80.0, 140.0);
            battlefieldMinX = battlefieldIslandX + margin;
            battlefieldMaxX = battlefieldIslandX + battlefieldIslandW - margin;
            if (battlefieldMaxX <= battlefieldMinX) {
                battlefieldMinX = battlefieldIslandX;
                battlefieldMaxX = battlefieldIslandX + battlefieldIslandW;
            }
        }

        // Prefer platform tops so pickups are reachable and visible.
        if (!platforms.isEmpty() && random.nextDouble() < 0.72) {
            List<Platform> candidates = new ArrayList<>();
            for (Platform p : platforms) {
                if (battlefield && (p.x + p.w < battlefieldMinX || p.x > battlefieldMaxX)) continue;
                if (p.w >= 140 && p.y <= GROUND_Y - 30 && p.y > 120) {
                    candidates.add(p);
                }
            }
            if (!candidates.isEmpty()) {
                Platform p = candidates.get(random.nextInt(candidates.size()));
                double x = p.x + 40 + random.nextDouble() * Math.max(20, p.w - 80);
                double y = Math.max(120, p.y - 45);
                if (battlefield) {
                    x = Math.clamp(x, battlefieldMinX, battlefieldMaxX);
                }
                return new double[]{x, y};
            }
        }

        double x;
        if (battlefield) {
            x = battlefieldMinX + random.nextDouble() * Math.max(1, battlefieldMaxX - battlefieldMinX);
        } else {
            x = 200 + random.nextDouble() * (WORLD_WIDTH - 400);
        }
        // Clamp to above ground so power-ups never spawn beneath the floor.
        double y = 260 + random.nextDouble() * (GROUND_Y - 520);
        y = Math.min(y, GROUND_Y - 120);
        return new double[]{x, y};
    }

    private void handleGameplayKeyPress(Stage stage, KeyEvent e) {
        KeyCode code = e.getCode();
        if (replayPlaybackActive) {
            if (code == KeyCode.ESCAPE) {
                endReplayPlayback(stage);
            } else if (code == KeyCode.F11) {
                fullscreenEnabled = !fullscreenEnabled;
                applyDisplaySettings(stage);
            }
            return;
        }
        if (lanModeActive && lanIsClient) {
            handleLanKeyPress(stage, e);
            return;
        }
        if (code == KeyCode.F11) {
            fullscreenEnabled = !fullscreenEnabled;
            applyDisplaySettings(stage);
            saveAchievements();
            return;
        }
        if (code == KeyCode.F3) {
            debugHudEnabled = !debugHudEnabled;
            addToKillFeed(debugHudEnabled ? "DEBUG HUD: ON" : "DEBUG HUD: OFF");
            return;
        }
        if (trainingModeActive && handleTrainingHotkey(code)) {
            return;
        }
        if (lanModeActive) {
            if (code == KeyCode.ESCAPE) {
                confirmLeaveLanMatch(stage);
                return;
            }
            if (lanIsHost && isGameplayKeyForPlayer(code)) {
                return;
            }
        }
        boolean alreadyDown = pressedKeys.contains(code);
        pressedKeys.add(code);
        setLocalActionsForKey(code, true);
        if (code != null && !alreadyDown) {
            registerDashTapForKey(code);
        }
        if (!lanModeActive && e.getCode() == KeyCode.ESCAPE) {
            handleGameplayPauseRequest(stage);
        }
    }

    private void handleGameplayKeyRelease(KeyEvent e) {
        KeyCode code = e.getCode();
        if (replayPlaybackActive) {
            pressedKeys.remove(code);
            return;
        }
        if (lanModeActive && lanIsClient) {
            handleLanKeyRelease(e);
            return;
        }
        if (lanModeActive && lanIsHost && isGameplayKeyForPlayer(code)) {
            return;
        }
        pressedKeys.remove(code);
        setLocalActionsForKey(code, false);
    }

    private void registerDashTapForKey(KeyCode code) {
        if (lanModeActive && lanIsHost) {
            if (code != leftKeyForPlayer(0) && code != rightKeyForPlayer(0)) return;
        }
        for (int i = 0; i < activePlayers; i++) {
            if (players[i] == null || isAI[i]) continue;
            ControlAction action = effectiveKeyboardActionForKey(i, code);
            if (action == ControlAction.LEFT) {
                registerLiveDashTap(players[i], -1);
            } else if (action == ControlAction.RIGHT) {
                registerLiveDashTap(players[i], 1);
            }
        }
    }

    /**
     * Registers a direction edge read directly from this machine's controls.
     * Lockstep direction edges are registered later by {@link #applyLockstepBundle(int[])}
     * on every machine; applying one here would give the host an extra, zero-delay tap.
     */
    private void registerLiveDashTap(Bird bird, int direction) {
        if (bird == null || lockstepMatchActive()) return;
        bird.registerDashTap(direction);
    }

    private void handleGameplayPauseRequest(Stage stage) {
        if (stage == null) {
            return;
        }
        if (lanModeActive) {
            confirmLeaveLanMatch(stage);
            return;
        }
        togglePause(stage);
    }

    private boolean movePauseMenuFocus(Scene scene, VBox pauseMenu, KeyCode direction) {
        scene = activeSceneFor(scene);
        if (pauseMenu == null) {
            return false;
        }
        List<Button> buttons = new ArrayList<>();
        collectPauseMenuButtons(pauseMenu, buttons);
        if (buttons.isEmpty()) {
            return false;
        }
        int delta = switch (direction) {
            case UP, LEFT -> -1;
            case DOWN, RIGHT -> 1;
            default -> 0;
        };
        if (delta == 0) {
            return false;
        }
        int currentIndex = -1;
        for (Node focus = scene == null ? null : scene.getFocusOwner(); focus != null; focus = focus.getParent()) {
            if (focus instanceof Button button) {
                currentIndex = buttons.indexOf(button);
                break;
            }
        }
        int nextIndex;
        if (currentIndex < 0) {
            nextIndex = delta > 0 ? 0 : buttons.size() - 1;
        } else {
            nextIndex = Math.clamp(currentIndex + delta, 0, buttons.size() - 1);
        }
        Button next = buttons.get(nextIndex);
        next.requestFocus();
        if (scene != null) {
            setConsoleHighlightActive(true, scene);
        }
        return true;
    }

    private void collectPauseMenuButtons(Node node, List<Button> buttons) {
        if (node == null || buttons == null) {
            return;
        }
        if (node instanceof Button button) {
            if (button.isVisible() && !button.isDisabled()) {
                buttons.add(button);
            }
            return;
        }
        if (node instanceof Parent parent) {
            for (Node child : parent.getChildrenUnmodifiable()) {
                collectPauseMenuButtons(child, buttons);
            }
        }
    }

    private VBox currentPauseMenu() {
        if (gameRoot == null) {
            return null;
        }
        for (Node child : gameRoot.getChildren()) {
            if (child instanceof VBox box && "pauseMenu".equals(box.getId())) {
                return box;
            }
        }
        return null;
    }

