    boolean isStandingOnFrostbiteSnowbank(Bird bird) {
        return !Double.isNaN(frostbiteSnowbankLandingY(bird, true));
    }

    double frostbiteSnowbankLandingY(Bird bird, boolean currentFrameOnly) {
        if (!isFrostbiteFjordActive() || bird == null || frostbiteSnowbanks.isEmpty()) {
            return Double.NaN;
        }
        double bodyW = 80.0 * bird.sizeMultiplier;
        double bodyH = 80.0 * bird.sizeMultiplier;
        double centerX = bird.x + bodyW * 0.5;
        double bottom = bird.y + bodyH;
        for (FrostbiteSnowbank bank : frostbiteSnowbanks) {
            if (bank.health <= 0) {
                continue;
            }
            if (centerX < bank.x + 8.0 || centerX > bank.x + bank.w - 8.0) {
                continue;
            }
            if (currentFrameOnly) {
                if (bottom >= bank.y && bottom <= bank.y + Math.max(12.0, bank.h * 0.32)
                        && bird.y <= bank.y + 2.0) {
                    return bank.y;
                }
            } else if (bottom >= bank.y && bird.y < bank.y + bank.h && bird.vy >= 0.0 && bird.y <= bank.y) {
                return bank.y;
            }
        }
        return Double.NaN;
    }

    void resolveFrostbiteSnowbankCollision(Bird bird, double prevX, double prevY) {
        if (!isFrostbiteFjordActive() || bird == null || bird.health <= 0 || frostbiteSnowbanks.isEmpty()) {
            return;
        }
        double bodyW = 80.0 * bird.sizeMultiplier;
        double bodyH = 80.0 * bird.sizeMultiplier;
        double left = bird.x;
        double right = bird.x + bodyW;
        double top = bird.y;
        double bottom = bird.y + bodyH;
        double prevRight = prevX + bodyW;
        double prevBottom = prevY + bodyH;

        for (FrostbiteSnowbank bank : frostbiteSnowbanks) {
            if (bank.health <= 0) {
                continue;
            }
            double overlapX = Math.min(right, bank.x + bank.w) - Math.max(left, bank.x);
            double overlapY = Math.min(bottom, bank.y + bank.h) - Math.max(top, bank.y);
            if (overlapX <= 0 || overlapY <= 0) {
                continue;
            }
            if (prevBottom <= bank.y + 8.0 && bottom > bank.y && bird.vy >= 0.0) {
                bird.y = bank.y - bodyH;
                bird.vy = Math.min(0.0, bird.vy);
                continue;
            }
            if (prevRight <= bank.x && bird.vx > 0.0) {
                bird.x = bank.x - bodyW - 0.5;
                bird.vx = Math.min(0.0, bird.vx) * 0.35;
            } else if (prevX >= bank.x + bank.w && bird.vx < 0.0) {
                bird.x = bank.x + bank.w + 0.5;
                bird.vx = Math.max(0.0, bird.vx) * 0.35;
            } else if (overlapX < overlapY) {
                double bankCenter = bank.centerX();
                if (bird.x + bodyW * 0.5 < bankCenter) {
                    bird.x -= overlapX + 0.5;
                    bird.vx = Math.min(0.0, bird.vx) * 0.35;
                } else {
                    bird.x += overlapX + 0.5;
                    bird.vx = Math.max(0.0, bird.vx) * 0.35;
                }
            }
        }
    }

    void damageFrostbiteSnowbanks(Bird attacker, double attackCenterX, double attackCenterY,
                                  double horizontalReach, double verticalReach, int rawDamage) {
        if (!isFrostbiteFjordActive() || attacker == null || frostbiteSnowbanks.isEmpty()) {
            return;
        }
        for (Iterator<FrostbiteSnowbank> it = frostbiteSnowbanks.iterator(); it.hasNext(); ) {
            FrostbiteSnowbank bank = it.next();
            double halfW = bank.w * 0.5;
            double halfH = bank.h * 0.5;
            if (Math.abs(bank.centerX() - attackCenterX) > halfW + horizontalReach
                    || Math.abs(bank.centerY() - attackCenterY) > halfH + verticalReach) {
                continue;
            }
            int damage = Math.max(7, (int) Math.round(rawDamage * 0.72));
            bank.health = Math.max(0, bank.health - damage);
            bank.damageFlash = 10;
            emitFrostbiteSnowbankChips(bank.centerX(), bank.y + bank.h * 0.36,
                    Math.signum(bank.centerX() - attackCenterX), 12, Color.web("#E1F5FE"));
            shakeIntensity = Math.max(shakeIntensity, 3.5);
            if (bank.health <= 0) {
                shatterFrostbiteSnowbank(it, bank, false, 0);
            }
        }
    }

    boolean hitFrostbiteSnowbankWithIce(double x, double y, double radius, int direction, boolean ultimate) {
        if (!isFrostbiteFjordActive() || frostbiteSnowbanks.isEmpty()) {
            return false;
        }
        for (Iterator<FrostbiteSnowbank> it = frostbiteSnowbanks.iterator(); it.hasNext(); ) {
            FrostbiteSnowbank bank = it.next();
            if (Math.abs(bank.centerX() - x) > bank.w * 0.5 + radius
                    || Math.abs(bank.centerY() - y) > bank.h * 0.5 + radius) {
                continue;
            }
            shatterFrostbiteSnowbank(it, bank, true, direction == 0 ? 1 : direction);
            shakeIntensity = Math.max(shakeIntensity, ultimate ? 8.0 : 5.5);
            return true;
        }
        return false;
    }

    private void shatterFrostbiteSnowbank(Iterator<FrostbiteSnowbank> iterator, FrostbiteSnowbank bank,
                                          boolean iceImpact, int direction) {
        emitFrostbiteSnowbankChips(bank.centerX(), bank.y + bank.h * 0.4,
                direction == 0 ? 1.0 : direction, iceImpact ? 34 : 24,
                iceImpact ? Color.web("#B3E5FC") : Color.WHITE);
        iterator.remove();
    }

    private void emitFrostbiteSnowbankChips(double x, double y, double direction, int count, Color color) {
        double dir = direction == 0.0 ? 1.0 : Math.signum(direction);
        for (int i = 0; i < Math.max(1, count); i++) {
            double spray = -Math.PI * 0.62 + (nextParticleRandom() - 0.5) * 1.2;
            double speed = 2.0 + nextParticleRandom() * 6.2;
            particles.add(new Particle(
                    x + (nextParticleRandom() - 0.5) * 46.0,
                    y + (nextParticleRandom() - 0.5) * 28.0,
                    Math.cos(spray) * speed * dir + (nextParticleRandom() - 0.5) * 1.2,
                    Math.sin(spray) * speed - 1.8,
                    color.deriveColor(0, 1, 1, 0.78)
            ));
        }
    }

    private void positionBattlefieldSpawns() {
        List<Bird> active = new ArrayList<>();
        for (Bird b : players) {
            if (b != null) active.add(b);
        }
        if (active.isEmpty()) return;

        if (selectedMap == MapType.DESERT && activeArenaGeometryVariant != MapVariant.REDLINE_CANYON) {
            double[] spawnCenters = buildSpawnCenters(active.size(), 360.0, WORLD_WIDTH - 360.0);
            for (int i = 0; i < active.size(); i++) {
                Bird b = active.get(i);
                double center = spawnCenters[Math.min(i, spawnCenters.length - 1)];
                double halfWidth = 40 * b.sizeMultiplier;
                double spawnY = desertSpawnYForCenter(center, b.sizeMultiplier);
                b.x = center - halfWidth;
                b.y = spawnY;
                b.vx = 0;
                b.vy = 0;
                b.prevX = b.x;
                b.prevY = b.y;
            }
            return;
        }

        if (selectedMap == MapType.DOCK && activeArenaGeometryVariant != MapVariant.TITAN_DOCK) {
            int leftDockCount = (active.size() + 1) / 2;
            int bridgeCount = active.size() - leftDockCount;
            double[] leftDockCenters = evenlySpacedCenters(leftDockCount, 1080.0, 2200.0);
            double[] bridgeCenters = evenlySpacedCenters(bridgeCount, 3400.0, 4600.0);
            for (int i = 0; i < active.size(); i++) {
                Bird b = active.get(i);
                boolean leftDockSpawn = i < leftDockCount;
                int sideIndex = leftDockSpawn ? i : i - leftDockCount;
                double[] sideCenters = leftDockSpawn ? leftDockCenters : bridgeCenters;
                double center = sideCenters[Math.min(sideIndex, sideCenters.length - 1)];
                double surfaceY = leftDockSpawn ? GROUND_Y - 140.0 : GROUND_Y - 220.0;
                b.x = center - b.bodyWidth() / 2.0;
                b.y = surfaceY - b.bodyHeight();
                b.vx = 0;
                b.vy = 0;
                b.prevX = b.x;
                b.prevY = b.y;
            }
            return;
        }

        if (positionWideCourseSpawns(active)) {
            return;
        }

        if (!usesAuthoredIslandSpawnForCurrentArena()) {
            double[] spawnCenters = buildSpawnCenters(active.size(), 420.0, WORLD_WIDTH - 420.0);
            for (int i = 0; i < active.size(); i++) {
                Bird b = active.get(i);
                double center = spawnCenters[Math.min(i, spawnCenters.length - 1)];
                b.x = center - b.bodyWidth() * 0.5;
                b.y = GROUND_Y - b.bodyHeight();
                b.vx = 0;
                b.vy = 0;
                b.prevX = b.x;
                b.prevY = b.y;
            }
            return;
        }

        double margin = Math.clamp(battlefieldIslandW * 0.15, 120.0, 220.0);
        double[] spawnCenters = buildIslandSpawnCenters(active.size(),
                battlefieldIslandX + margin,
                battlefieldIslandX + battlefieldIslandW - margin);

        for (int i = 0; i < active.size(); i++) {
            Bird b = active.get(i);
            double center = spawnCenters[Math.min(i, spawnCenters.length - 1)];
            b.x = center - b.bodyWidth() * 0.5;
            b.y = battlefieldIslandY - b.bodyHeight();
            b.vx = 0;
            b.vy = 0;
            b.prevX = b.x;
            b.prevY = b.y;
        }
    }

    /**
     * Long traversal arenas should begin as a readable formation, not a pile
     * of bodies on the platform marked as the AI's home surface.  Rooftop
     * Relay authors six large, named roofs in traversal order, so opposing
     * teams can occupy separate buildings (and free-for-all fighters can each
     * take a roof) without guessing at collision geometry or spawning near a
     * blast boundary.
     */
    private boolean positionWideCourseSpawns(List<Bird> active) {
        if (activeArenaGeometryVariant != MapVariant.ROOFTOP_RELAY || active.size() < 2) {
            return false;
        }
        List<Platform> roofs = platforms.stream()
                .filter(platform -> platform.signText != null
                        && !platform.signText.isBlank()
                        && platform.w >= 560.0)
                .sorted(Comparator.comparingDouble(platform -> platform.x))
                .toList();
        if (roofs.size() < active.size()) {
            return false;
        }
        Map<Integer, List<Bird>> teamGroups = new LinkedHashMap<>();
        for (Bird bird : active) {
            teamGroups.computeIfAbsent(getEffectiveTeam(bird.playerIndex), ignored -> new ArrayList<>())
                    .add(bird);
        }
        if (teamGroups.size() >= 2 && teamGroups.size() < active.size()
                && roofs.size() >= teamGroups.size()) {
            int groupIndex = 0;
            for (List<Bird> team : teamGroups.values()) {
                Platform roof = roofs.get(groupIndex);
                double edgeMargin = Math.min(110.0, roof.w * 0.16);
                double[] centers = evenlySpacedCenters(team.size(),
                        roof.x + edgeMargin, roof.x + roof.w - edgeMargin);
                for (int member = 0; member < team.size(); member++) {
                    Bird bird = team.get(member);
                    positionBirdOnAuthoredSurface(bird, centers[member], roof.y,
                            groupIndex < teamGroups.size() * 0.5);
                }
                groupIndex++;
            }
            return true;
        }
        for (int i = 0; i < active.size(); i++) {
            Bird bird = active.get(i);
            Platform roof = roofs.get(i);
            positionBirdOnAuthoredSurface(bird, roof.x + roof.w * 0.5, roof.y,
                    i < (active.size() - 1) * 0.5);
        }
        return true;
    }

    private void positionBirdOnAuthoredSurface(Bird bird, double centerX,
                                                 double surfaceY, boolean facingRight) {
        bird.x = centerX - bird.bodyWidth() * 0.5;
        bird.y = surfaceY - bird.bodyHeight();
        bird.vx = 0.0;
        bird.vy = 0.0;
        bird.prevX = bird.x;
        bird.prevY = bird.y;
        bird.facingRight = facingRight;
    }

    private boolean usesAuthoredIslandSpawnForCurrentArena() {
        if (battlefieldIslandW <= 0.0) {
            return false;
        }
        // Rooftop Relay spans almost the entire world, so it deliberately keeps
        // full-course blast bounds. It still needs to spawn on its authored
        // HOME roof instead of the removed City ground plane.
        return usesIslandBoundsForCurrentArena()
                || activeArenaGeometryVariant == MapVariant.ROOFTOP_RELAY;
    }

    private double[] buildSpawnCenters(int count, double left, double right) {
        if (count <= 0) {
            return new double[0];
        }
        if (count == 1) {
            return new double[]{(left + right) / 2.0};
        }
        double[] centers = new double[count];
        double span = Math.max(0.0, right - left);
        double inset = Math.clamp(span * 0.34, 140.0, span * 0.45);
        double innerLeft = left + inset;
        double innerRight = right - inset;
        double usableSpan = Math.max(0.0, innerRight - innerLeft);
        double spacing = usableSpan / Math.max(1, count - 1);
        for (int i = 0; i < count; i++) {
            centers[i] = innerLeft + spacing * i;
        }
        return centers;
    }

    private double[] buildIslandSpawnCenters(int count, double left, double right) {
        if (count <= 2) {
            return buildSpawnCenters(count, left, right);
        }
        double span = Math.max(0.0, right - left);
        double inset = Math.min(180.0, span * 0.04);
        return evenlySpacedCenters(count, left + inset, right - inset);
    }

    private double[] evenlySpacedCenters(int count, double left, double right) {
        if (count <= 0) {
            return new double[0];
        }
        if (count == 1) {
            return new double[]{(left + right) / 2.0};
        }
        double[] centers = new double[count];
        double spacing = Math.max(0.0, right - left) / (count - 1.0);
        for (int i = 0; i < count; i++) {
            centers[i] = left + spacing * i;
        }
        return centers;
    }

    private double desertSpawnYForCenter(double center, double sizeMultiplier) {
        double bodyHeight = 80 * sizeMultiplier;
        if (center >= DESERT_CLIFF_SUMMIT_X) {
            return DESERT_CLIFF_SUMMIT_Y - bodyHeight;
        }
        if (center >= DESERT_CLIFF_HIGH_X) {
            return DESERT_CLIFF_HIGH_Y - bodyHeight;
        }
        if (center >= DESERT_CLIFF_TOP_X) {
            return DESERT_CLIFF_TOP_Y - bodyHeight;
        }
        if (center >= DESERT_CLIFF_MID_X) {
            return DESERT_CLIFF_MID_Y - bodyHeight;
        }
        if (center >= DESERT_CLIFF_LOW_X) {
            return DESERT_CLIFF_LOW_Y - bodyHeight;
        }
        return GROUND_Y - bodyHeight;
    }

    double battlefieldSpawnCenterX() {
        if (selectedMap == MapType.DOCK && activeArenaGeometryVariant != MapVariant.TITAN_DOCK) {
            return 1760;
        }
        if (selectedMap == MapType.FROSTBITE_FJORD) {
            return FROSTBITE_MAIN_X + FROSTBITE_MAIN_W / 2.0;
        }
        if (selectedMap == MapType.ASHFALL_CATHEDRAL) {
            return ASHFALL_MAIN_X + ASHFALL_MAIN_W / 2.0;
        }
        if (battlefieldIslandW > 0) {
            return battlefieldIslandX + battlefieldIslandW / 2.0;
        }
        return WORLD_WIDTH / 2.0;
    }

    double battlefieldSpawnY(double sizeMultiplier) {
        if (selectedMap == MapType.DOCK && activeArenaGeometryVariant != MapVariant.TITAN_DOCK) {
            return GROUND_Y - 220 * sizeMultiplier;
        }
        if (selectedMap == MapType.FROSTBITE_FJORD && battlefieldIslandW > 0) {
            return battlefieldIslandY - 80 * sizeMultiplier;
        }
        if (selectedMap == MapType.ASHFALL_CATHEDRAL && battlefieldIslandW > 0) {
            return battlefieldIslandY - 80 * sizeMultiplier;
        }
        if (battlefieldIslandW > 0) {
            return battlefieldIslandY - 80 * sizeMultiplier;
        }
        return GROUND_Y - 300;
    }

    double battlefieldVoidFloorY() {
        if (battlefieldIslandW > 0) {
            return battlefieldIslandY + 120.0;
        }
        return GROUND_Y;
    }

    boolean usesIslandBoundsForCurrentArena() {
        return selectedMap == MapType.BATTLEFIELD
                || selectedMap == MapType.BEACON_CROWN
                || selectedMap == MapType.FROSTBITE_FJORD
                || selectedMap == MapType.ASHFALL_CATHEDRAL
                || selectedMap == MapType.PRISON
                || selectedMap == MapType.RESONANCE_HALL
                || selectedMap == MapType.SIGNAL_SPIRE
                || selectedMap == MapType.SILENT_AMPHITHEATER
                || selectedMap == MapType.GLASSWIND_CAUSEWAY
                || selectedMap == MapType.WORLDSEAM
                || selectedMap == MapType.MIDNIGHT_WORKSHOP
                || selectedMap == MapType.CARRION_EXCHANGE
                || selectedMap == MapType.ONEIRIC_OBSERVATORY
                || selectedMap == MapType.STORMGLASS_REFINERY
                || activeArenaGeometryVariant == MapVariant.TITAN_DOCK
                || activeArenaGeometryVariant == MapVariant.PARLIAMENT_ROOFTOPS
                || activeArenaGeometryVariant == MapVariant.PEREGRINE_RUN
                || activeArenaGeometryVariant == MapVariant.TEMPEST_SUMMIT
                || activeArenaGeometryVariant == MapVariant.HEARTBLOOM_SANCTUARY
                || activeArenaGeometryVariant == MapVariant.HARVEST_TRIBUNAL
                || activeArenaGeometryVariant == MapVariant.REDLINE_CANYON
                || activeArenaGeometryVariant == MapVariant.STILLWATER_MARSH
                || isCrownDuelArena();
    }

    /**
     * Most non-island maps use GROUND_Y as an implicit collision floor. The
     * long Rooftop Relay course is the exception: its authored roofs are the
     * only solid ground, and every gap between them is open sky.
     */
    boolean hasImplicitGroundFloorForCurrentArena() {
        return activeArenaGeometryVariant != MapVariant.ROOFTOP_RELAY
                && !usesIslandBoundsForCurrentArena();
    }

    /**
     * Returns the platform that owns the arena's authored island bounds.
     *
     * <p>Several large arenas deliberately contain side decks that are a few
     * pixels wider than the central fighting platform. Width alone therefore
     * is not a reliable way for CPU recovery and navigation to identify home.
     * Keep the geometry metadata as the source of truth and let callers fall
     * back to their legacy heuristic when an arena has no authored island.</p>
     */
    Platform authoredAiMainStagePlatform() {
        if (battlefieldIslandW <= 0.0) {
            return null;
        }
        Platform closest = null;
        double closestError = Double.POSITIVE_INFINITY;
        for (Platform platform : platforms) {
            double xError = Math.abs(platform.x - battlefieldIslandX);
            double widthError = Math.abs(platform.w - battlefieldIslandW);
            double yError = Math.abs(platform.y - battlefieldIslandY);
            double error = xError + widthError + yError * 2.0;
            if (error < closestError) {
                closestError = error;
                closest = platform;
            }
            if (xError <= 0.5 && widthError <= 0.5 && yError <= 0.5) {
                return platform;
            }
        }
        // Custom stage construction can round coordinates by a fraction. Only
        // accept a near match here; otherwise the CPU's old widest-platform
        // fallback is safer than binding recovery to unrelated geometry.
        return closestError <= 12.0 ? closest : null;
    }

    Platform authoredAiMainStagePlatform(double worldCenterX) {
        if (selectedMap == MapType.WORLDSEAM && battlefieldIslandW > 0.0) {
            // Worldseam deliberately has two equal main landmasses separated by
            // the central rift. Treating the first (left) platform as the only
            // mainland made grounded CPUs on the right repeatedly recover toward
            // the rift. Resolve the floor nearest the fighter instead; entering a
            // gate naturally transfers recovery ownership to the opposite side.
            Platform nearestLandmass = null;
            double nearestDistance = Double.POSITIVE_INFINITY;
            for (Platform platform : platforms) {
                if (Math.abs(platform.y - battlefieldIslandY) > 0.5 || platform.w < 1_000.0) {
                    continue;
                }
                double distance = worldCenterX < platform.x
                        ? platform.x - worldCenterX
                        : (worldCenterX > platform.x + platform.w
                        ? worldCenterX - (platform.x + platform.w)
                        : 0.0);
                if (distance < nearestDistance) {
                    nearestDistance = distance;
                    nearestLandmass = platform;
                }
            }
            if (nearestLandmass != null) {
                return nearestLandmass;
            }
        }
        return authoredAiMainStagePlatform();
    }

    private double battlefieldBoundsMargin() {
        if (selectedMap == MapType.PRISON) {
            return 0.0;
        }
        if (activeArenaGeometryVariant == MapVariant.PARLIAMENT_ROOFTOPS) {
            return 2300.0;
        }
        if (activeArenaGeometryVariant == MapVariant.PEREGRINE_RUN) {
            return 2500.0;
        }
        if (activeArenaGeometryVariant == MapVariant.REDLINE_CANYON) {
            return 600.0;
        }
        if (activeArenaGeometryVariant == MapVariant.LAST_ICE_SHELF) {
            return 850.0;
        }
        if (activeArenaGeometryVariant == MapVariant.STILLWATER_MARSH) {
            return 900.0;
        }
        if (activeArenaGeometryVariant == MapVariant.VOID_CROWN) {
            return 1600.0;
        }
        return Math.max(500, battlefieldIslandW * 0.7);
    }

    double battlefieldLeftBound() {
        if (battlefieldIslandW > 0) {
            return battlefieldIslandX - battlefieldBoundsMargin();
        }
        return 0;
    }

    double battlefieldRightBound() {
        if (battlefieldIslandW > 0) {
            return battlefieldIslandX + battlefieldIslandW + battlefieldBoundsMargin();
        }
        return WORLD_WIDTH;
    }

    boolean isDockWaterActive() {
        return (selectedMap == MapType.DOCK || selectedMap == MapType.DESERT) && dockWaterW > 0 && dockWaterH > 0;
    }

    boolean isDockWaterAt(double worldX, double worldY) {
        return isDockWaterActive()
                && worldX >= dockWaterX
                && worldX <= dockWaterX + dockWaterW
                && worldY >= dockWaterY
                && worldY <= dockWaterY + dockWaterH;
    }

    double dockWaterSurfaceY() {
        return dockWaterY;
    }

    double dockWaterStartX() {
        return dockWaterX;
    }

    double dockWaterWidth() {
        return dockWaterW;
    }

    double dockDrownDepthY() {
        return dockDrownY > 0 ? dockDrownY : WORLD_HEIGHT + 1;
    }

    double dockWaterMidY() {
        return dockWaterY + Math.min(220.0, dockWaterH * 0.42);
    }

    private boolean isDockSkiffPlatform(Platform p) {
        if (p == null || selectedMap != MapType.DOCK) return false;
        double centerX = p.x + p.w / 2.0;
        return centerX >= dockWaterX - 40
                && centerX <= dockWaterX + 1100
                && p.y >= dockWaterY - 48
                && p.y <= dockWaterY + 18
                && p.w <= 320
                && p.h <= 28;
    }

    private double dockShipVisualX() {
        return WORLD_WIDTH * 0.5 - 448.0 * DOCK_SHIP_SCALE;
    }

    private double dockShipVisualY() {
        return dockWaterSurfaceY() - 360.0;
    }

    private double dockShipCannonMuzzleX() {
        return dockShipVisualX() + 120.0 * DOCK_SHIP_SCALE;
    }

    private double dockShipCannonMuzzleY() {
        return dockShipVisualY() + 146.0 * DOCK_SHIP_SCALE;
    }

    private double dockBombTargetX(Bird target) {
        if (target == null) {
            return Math.clamp(battlefieldSpawnCenterX(), 120.0, WORLD_WIDTH - 120.0);
        }
        return Math.clamp(target.x + 40 * target.sizeMultiplier, 120.0, WORLD_WIDTH - 120.0);
    }

    private double dockBombTargetY(Bird target) {
        if (target == null) {
            return Math.clamp(GROUND_Y - 80.0, 120.0, dockDrownDepthY() - 90.0);
        }
        return Math.clamp(target.y + 40 * target.sizeMultiplier, 120.0, dockDrownDepthY() - 90.0);
    }

