    private void stopMatchSummaryBackgroundTimer() {
        AnimationTimer backgroundTimer = matchSummaryBackgroundTimer;
        matchSummaryBackgroundTimer = null;
        if (backgroundTimer != null) {
            backgroundTimer.stop();
        }
    }

    private void restartCurrentMatch(Stage stage) {
        if (stage == null || matchRestartQueued) {
            return;
        }
        matchRestartQueued = true;
        closePauseMenuWithoutResuming();
        stopGameplayTimer();
        resetMatchStats();
        if (classicModeActive && classicEncounter != null) {
            try {
                if (dailyChallengeModeActive || ashfallTrialModeActive || bossRushModeActive) {
                    handleClassicMatchEnd(stage, null);
                } else {
                    applyClassicRestartPenalty();
                    saveAchievements();
                    showClassicContinuePrompt(stage);
                }
            } finally {
                matchRestartQueued = false;
            }
            return;
        }
        javafx.application.Platform.runLater(() -> {
            try {
                startMatch(stage);
            } finally {
                matchRestartQueued = false;
            }
        });
    }

    void startMatch(Stage stage) {
        stopGameplayTimer();
        isPaused = false;
        if (replayPlaybackActive && activeReplay != null) {
            currentMatchSeed = activeReplay.seed;
        } else {
            currentMatchSeed = lanModeActive ? lanMatchSeed : System.nanoTime();
        }
        resolveStandardRandomMapForMatchStart();
        SimRng.reseed(currentMatchSeed);
        reseedParticleRandom(currentMatchSeed);
        simTick = 0L;
        dramaticSlowMoTicks = 0;
        matchEndFocusBird = null;
        musicDuckLevel = 1.0;
        replayFrameCursor = 0;
        replayDashCursor = 0;
        replayRecording = null;
        clearReplayInputs();
        lockstepSession = lanModeActive ? new LockstepSession(lanSlotConnected, networkInputDelayTicks) : null;
        lockstepDesyncReported = false;
        lastPowerUpSpawnTime = 0L;
        lastWindBurstTime = 0L;
        lastMutatorHazardTime = 0L;
        prepareMatchStart(stage);
        boolean[] menuAI = Arrays.copyOf(isAI, isAI.length);
        Arrays.fill(players, null);
        Arrays.fill(isAI, false);
        StoryCampaign.Mission campaignMission = null;
        StoryChapter storyChapter = null;
        AdventureBattle adventureBattle = null;
        ClassicEncounter classicRound = null;
        if (dailyChallengeModeActive && classicModeActive) {
            if (classicRun.isEmpty()) {
                DailyChallengePlan plan = buildDailyChallengePlan(classicSelectedBird);
                dailyChallengeRunKey = plan.key();
                dailyChallengeSeed = plan.seed();
                classicRunCodename = plan.codename();
                classicSelectedBird = plan.birdType();
                classicRun.addAll(plan.encounters());
                classicRoundIndex = 0;
            }
            long roundSeed = dailyChallengeSeed ^ ((long) (classicRoundIndex + 1) * 0x94D049BB133111EBL);
            currentMatchSeed = roundSeed;
            SimRng.reseed(roundSeed);
            reseedParticleRandom(roundSeed);
            renderRandom.setSeed(roundSeed ^ 0x369DEA0F31A53F85L);
        }
        if (trainingModeActive) {
            resetTrainingLabState();
            setupTrainingRoster();
        } else if (classicModeActive) {
            if (classicRun.isEmpty()) {
                if (ashfallTrialModeActive) {
                    classicSelectedBird = BirdType.PHOENIX;
                    classicRunCodename = ASHFALL_TRIAL_CODENAME;
                    classicRun.addAll(buildAshfallTrialRun());
                } else if (bossRushModeActive) {
                    classicRunCodename = "BOSS RUSH";
                    classicRun.addAll(buildBossRushRun());
                } else {
                    classicRun.addAll(buildClassicRun(classicSelectedBird));
                }
                classicRoundIndex = 0;
            }
            if (classicRoundIndex < 0 || classicRoundIndex >= classicRun.size()) {
                classicRoundIndex = 0;
            }
            classicRound = classicRun.get(classicRoundIndex);
            classicEncounter = classicRound;
            setupClassicEncounterRoster(classicRound);
        } else if (campaignModeActive) {
            campaignMission = currentCampaignMission != null
                    ? currentCampaignMission
                    : stillSkyCampaign.mission(stillSkyProgress.currentMissionId);
            if (campaignMission == null) {
                campaignMission = stillSkyCampaign.firstMission();
            }
            currentCampaignMission = campaignMission;
            setupCampaignMissionRoster(campaignMission);
        } else if (storyModeActive) {
            StoryChapter[] chapters = activeStoryChapters();
            if (storyChapterIndex < 0 || storyChapterIndex >= chapters.length) {
                storyChapterIndex = 0;
            }
            storyChapter = chapters[storyChapterIndex];
            setupStoryChapterRoster(storyChapter);
        } else if (adventureModeActive) {
            adventureBattle = currentAdventureBattle != null ? currentAdventureBattle : activeAdventureBattle();
            setupAdventureBattleRoster(adventureBattle);
        } else {
            // LAN random picks must resolve identically on every machine, so
            // they draw from the full roster; local picks respect unlocks.
            List<BirdType> pool = lanModeActive ? List.of(BirdType.values()) : unlockedBirdPool();
            int slots = lanModeActive ? LAN_MAX_PLAYERS : activePlayers;
            // Setup randomness (random bird picks, random skins) uses its own
            // seed-derived stream so it never shifts the sim RNG. Replays store
            // the RESOLVED roster, so playback must not depend on these draws.
            Random setupRandom = new Random(currentMatchSeed ^ 0x5EED_B17D_5E7BL);
            for (int i = 0; i < slots; i++) {
                if (lanModeActive && !lanSlotConnected[i]) {
                    players[i] = null;
                    isAI[i] = false;
                    continue;
                }
                if (replayPlaybackActive && activeReplay != null && activeReplay.slotBirdTypes != null
                        && i < activeReplay.slotBirdTypes.length && activeReplay.slotBirdTypes[i] == null) {
                    // Replays of matches with empty slots (e.g. 2-player LAN)
                    // must leave those slots empty on playback too.
                    players[i] = null;
                    isAI[i] = false;
                    continue;
                }
                BirdType type = lanModeActive ? lanSelectedBirds[i] : fightSetupSelection.selectedBird(i);
                boolean randomPick = lanModeActive ? lanRandomBirds[i] : fightSetupSelection.isRandomSelected(i);
                if (type == null || (lanModeActive && randomPick) || (!lanModeActive && (randomPick || !isBirdUnlocked(type)))) {
                    type = pool.get(setupRandom.nextInt(pool.size()));
                    if (lanModeActive) {
                        lanSelectedBirds[i] = type;
                        lanRandomBirds[i] = false;
                    }
                }
                double startX = 300 + i * (WIDTH - 600) / (double) Math.max(1, slots - 1);
                isAI[i] = !lanModeActive && menuAI[i];
                players[i] = new Bird(startX, type, i, this);
                if (lanModeActive) {
                    String skinKey = randomPick ? randomAdventureSkinChoice(type, setupRandom) : lanSelectedSkinKeys[i];
                    applyPreviewSkinChoiceToBird(players[i], type, skinKey);
                } else {
                    String skinKey = randomPick ? randomAdventureSkinChoice(type, setupRandom) : fightSetupSelection.selectedSkinKey(i);
                    skinKey = normalizeAdventureSkinChoice(type, skinKey);
                    fightSetupSelection.setSelectedSkinKey(i, skinKey);
                    applySkinChoiceToBird(players[i], type, skinKey);
                }

                applyAdaptiveBalance(players[i]);
            }
        }

        smashCombatRulesActive = (!trainingModeActive && !campaignModeActive
                && !storyModeActive && !adventureModeActive && !classicModeActive)
                || classicUsesSmashRules();
        if (smashCombatRulesActive) {
            Arrays.fill(scores, 0);
            for (int i = 0; i < activePlayers; i++) {
                if (players[i] != null) {
                    scores[i] = smashStartingStocks();
                }
            }
            applyClassicEncounterStockOverrides();
        }

        beginReplayRecordingForMatch();

        if (tournamentModeActive) {
            applyTournamentSlotNames();
        }

        setupMatchArenaGeometry();
        applySelectedMapVariantArena();

        if (campaignModeActive && campaignMission != null) {
            applyCampaignMissionArenaModifiers(campaignMission);
            setupCampaignMissionController(campaignMission);
            if (campaignMatchTimerOverride > 0) {
                matchTimer = campaignMatchTimerOverride;
            }
        }
        if (storyModeActive && storyChapter != null) {
            applyStoryChapterArenaModifiers();
            if (storyMatchTimerOverride > 0) {
                matchTimer = storyMatchTimerOverride;
            }
        }
        if (adventureModeActive && adventureBattle != null) {
            applyAdventureBattleArenaModifiers(adventureBattle);
            if (adventureMatchTimerOverride > 0) {
                matchTimer = adventureMatchTimerOverride;
            }
        }
        if (classicModeActive && classicRound != null) {
            applyClassicEncounterArenaModifiers(classicRound);
            if (classicRound.timerFrames > 0) {
                matchTimer = classicRound.timerFrames;
            }
        }
        configureMatchModes();
        positionBattlefieldSpawns();
        if (classicModeActive && classicRound != null) {
            positionClassicEncounterSpawns(classicRound);
        }
        if (trainingModeActive) {
            captureTrainingSpawns();
        }
        resetFightHudStateForMatchStart();

        if (gameplayRenderSurface == null) {
            gameplayRenderSurface = new GameplayRenderSurface(WIDTH, HEIGHT);
        }
        GameplayRenderSurface renderSurface = gameplayRenderSurface;
        Canvas canvas = renderSurface.canvas();
        GraphicsContext g = renderSurface.worldGraphics();
        StackPane root = renderSurface.attachToFreshRoot();
        gameRoot = root;
        root.setStyle(selectedMap == MapType.DOCK
                ? "-fx-background-color: linear-gradient(to bottom, #0F3047 0%, #1E5D78 55%, #0A171F 100%);"
                : selectedMap == MapType.ASHFALL_CATHEDRAL
                ? "-fx-background-color: linear-gradient(to bottom, #09050A 0%, #3B0713 58%, #F4511E 100%);"
                : selectedMap == MapType.FROSTBITE_FJORD
                ? "-fx-background-color: linear-gradient(to bottom, #08142C 0%, #13436A 52%, #AEEBFF 100%);"
                : selectedMap == MapType.DESERT
                ? "-fx-background-color: linear-gradient(to bottom, #F3A85A 0%, #F7D28B 48%, #D59A52 100%);"
                : selectedMap == MapType.BATTLEFIELD
                ? "-fx-background-color: linear-gradient(to bottom, #10283E 0%, #315B73 48%, #D5D7B6 100%);"
                : selectedMap == MapType.PRISON
                ? "-fx-background-color: linear-gradient(to bottom, #071018 0%, #172733 52%, #05090D 100%);"
                : selectedMap == MapType.FOREST
                ? "-fx-background-color: linear-gradient(to bottom, #87CEEB 0%, #B3E5FC 50%, #E0F2F1 100%);"
                : "-fx-background-color: #000011;");
        Scene scene = new Scene(root, WIDTH, HEIGHT);
        gameplayScene = scene;
        makeSceneResponsive(scene);
        // Arena and HUD are sequential passes on the same Canvas. A second
        // full-HD Canvas costs another Prism RTTexture and made rapid story
        // restarts fail inside NGCanvas when the GPU pool had not reclaimed
        // the previous scene yet.
        uiCanvas = canvas;
        ui = renderSurface.hudGraphics();

        pressedKeys.clear();
        scene.setOnKeyPressed(e -> handleGameplayKeyPress(stage, e));
        scene.setOnKeyReleased(this::handleGameplayKeyRelease);

        lastUpdate = 0;
        accumulator = 0;
        renderSnapshotTaken = false;
        resetRenderTimer();
        gameplayFrameExceptionReported = false;

        timer = new AnimationTimer() {
            @Override
            public void handle(long now) {
                framePerformance.beginFrame();
                try {
                    gameTick();
                    updateMusicDucking();
                    if (lanModeActive && lanIsHost) {
                        boolean hasClients = lanHost != null && lanHost.hasClients();
                        // Lockstep clients run the sim themselves; state snapshots
                        // are only for the legacy view-only path.
                        if (hasClients && lockstepSession == null
                                && now - lastLanSnapshotNs >= LAN_SNAPSHOT_INTERVAL_NS) {
                            if (lanHost != null) {
                                lanHost.broadcastState(buildLanState());
                            }
                            lastLanSnapshotNs = now;
                        }
                        if (lanHost != null) {
                            if (now - lastLanCompanionSnapshotNs >= LAN_COMPANION_SNAPSHOT_INTERVAL_NS) {
                                publishLanCompanionSnapshot();
                                lastLanCompanionSnapshotNs = now;
                            }
                        }
                    }
                    if (!shouldRenderFrame(now)) {
                        recordFrameEntityCounts();
                        framePerformance.finishFrame();
                        return;
                    }
                    renderSurface.beginLogicalFrame();
                    applyRenderInterpolation(computeRenderAlpha());
                    try {
                        FightHudLayout hudLayout = buildFightHudLayout();
                        currentFightHudOcclusionRects = hudLayout.occlusionRects();
                        long drawWorldStart = System.nanoTime();
                        drawGame(g);
                        framePerformance.recordDrawWorld(System.nanoTime() - drawWorldStart);

                        long drawHudStart = System.nanoTime();
                        drawFightHud(ui, hudLayout);
                        if (trainingModeActive) {
                            drawTrainingLabHud(ui);
                        }
                        framePerformance.recordDrawHud(System.nanoTime() - drawHudStart);
                        if (replayPlaybackActive) {
                            drawReplayOverlay(ui);
                        }
                        drawDebugTelemetryHud(ui);
                        drawFightFlashOverlay(ui);
                        framePerformance.recordDrawHud(System.nanoTime() - drawHudStart);
                    } finally {
                        restoreRenderPositions();
                    }
                    recordFrameEntityCounts();
                    framePerformance.finishFrame();
                } catch (RuntimeException ex) {
                    framePerformance.finishFrame();
                    handleGameplayFrameException(ex);
                }
            }
        };

        setScenePreservingFullscreen(stage, scene);
        timer.start();
        startMusic();
        canvas.requestFocus();

        zoom = 0.6;
        camX = 1000;
        camY = 800;
        syncTrackedCameraToCurrentView();
    }

    private void drawUnitedFinaleRaidHud(GraphicsContext g) {
        Bird player = players[0];
        Bird boss = unitedFinaleBoss();
        if (player != null && player.health > 0) {
            drawHealthBar(g, player, 24);
        }
        if (boss != null) {
            drawHealthBar(g, boss, WIDTH - 424);
        }

        int livingAllies = 0;
        int totalAllies = 0;
        for (Bird b : players) {
            if (b == null || b.playerIndex == 0) continue;
            if (getEffectiveTeam(b.playerIndex) != 1) continue;
            totalAllies++;
            if (b.health > 0) livingAllies++;
        }

        g.setFill(Color.BLACK.deriveColor(0, 1, 1, 0.72));
        g.fillRoundRect(WIDTH / 2.0 - 250, (double) 82 - 4, 500, 62, 18, 18);
        g.setStroke(Color.web("#FFF59D"));
        g.setLineWidth(2);
        g.strokeRoundRect(WIDTH / 2.0 - 250, (double) 82 - 4, 500, 62, 18, 18);
        g.setFill(Color.web("#FFF9C4"));
        g.setFont(HUD_CLASSIC_TITLE_FONT);
        g.fillText("ALL WINGS ENGAGED", WIDTH / 2.0 - 150, (double) 82 + 22);
        g.setFill(Color.web("#B3E5FC"));
        g.setFont(HUD_CLASSIC_RULES_FONT);
        g.fillText("ALLIES AIRBORNE: " + livingAllies + "/" + totalAllies, WIDTH / 2.0 - 145, (double) 82 + 48);
    }

    private void drawTrainingLabHud(GraphicsContext g) {
        if (trainingAcademyMode != TrainingAcademyMode.NONE) {
            drawTrainingAcademyHud(g);
            drawTrainingLiveSpecialOverlay(g);
            return;
        }

        double panelX = 22;
        double panelY = 220;
        double panelW = 560;
        double panelH = 282;
        Bird trainingPlayer = players != null && players.length > 0 ? players[0] : null;

        g.save();
        g.setFill(Color.web("#08151D", 0.86));
        g.fillRoundRect(panelX, panelY, panelW, panelH, 18, 18);
        g.setStroke(Color.web("#80DEEA", 0.78));
        g.setLineWidth(1.6);
        g.strokeRoundRect(panelX, panelY, panelW, panelH, 18, 18);
        g.setFill(Color.web("#80DEEA", 0.13));
        g.fillRoundRect(panelX + 1, panelY + 1, panelW - 2, 40, 17, 17);

        g.setFill(Color.web("#B2EBF2"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 18));
        g.fillText("TRAINING LAB", panelX + 14, panelY + 27);

        g.setFill(Color.web("#EDF7F8"));
        g.setFont(Font.font("Consolas", 13));
        double leftX = panelX + 14;
        double rightX = panelX + 300;
        double rowY = panelY + 61;
        double rowGap = 23;
        String comboText = trainingComboHits > 0
                ? trainingComboHits + " hits  |  " + (int) Math.round(trainingComboDamage) + " dmg"
                : "No active combo";
        g.fillText("COMBO  " + comboText, leftX, rowY);
        rowY += rowGap;
        g.fillText(String.format(Locale.ROOT, "DPS    %.1f", trainingComboDps()), leftX, rowY);
        rowY += rowGap;
        g.fillText(String.format(Locale.ROOT, "LAST   %.1f", trainingLastHitDamage), leftX, rowY);
        rowY += rowGap;
        g.fillText(String.format(Locale.ROOT, "TOTAL  %.1f", trainingSessionDamage), leftX, rowY);

        rowY = panelY + 61;
        g.fillText("DUMMY  " + trainingDummyBehavior.label.toUpperCase(Locale.ROOT), rightX, rowY);
        rowY += rowGap;
        g.fillText("BOXES  " + (trainingCombatOverlayEnabled ? "ON" : "OFF"), rightX, rowY);
        rowY += rowGap;
        g.fillText("SLOMO  " + (trainingSlowMotionEnabled ? "ON" : "OFF"), rightX, rowY);
        rowY += rowGap;
        g.fillText("FREEZE " + (trainingFrameAdvancePause ? "ON" : "OFF"), rightX, rowY);

        double framePanelY = panelY + 164;
        g.setStroke(Color.web("#80DEEA", 0.34));
        g.setLineWidth(1.0);
        g.strokeLine(panelX + 14, framePanelY - 10, panelX + panelW - 14, framePanelY - 10);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 13));
        if (trainingPlayer != null && trainingPlayer.debugNormalAttackTimelineActive()) {
            String phase = trainingPlayer.debugNormalAttackPhaseLabel();
            Color phaseColor = switch (phase) {
                case "ACTIVE" -> Color.web("#FF6B6B");
                case "RECOVERY" -> Color.web("#FFD166");
                default -> Color.web("#72E6F2");
            };
            g.setFill(Color.web("#EDF7F8"));
            g.fillText("MOVE   " + trainingPlayer.debugNormalAttackMoveName(), leftX, framePanelY + 9);
            g.setFill(phaseColor);
            g.fillText("PHASE  " + phase + "  "
                            + trainingPlayer.debugNormalAttackFrame() + "/"
                            + trainingPlayer.debugNormalAttackTotalFrames(),
                    leftX, framePanelY + 31);
            g.setFill(Color.web("#CFD8DC"));
            g.fillText("DATA   " + trainingPlayer.debugNormalAttackStartupFrames() + " startup  |  "
                            + trainingPlayer.debugNormalAttackActiveFrames() + " active  |  "
                            + trainingPlayer.debugNormalAttackRecoveryFrames() + " recovery",
                    leftX, framePanelY + 53);
            g.setFill(trainingPlayer.debugNormalAttackConnected()
                    ? Color.web("#A5D6A7") : Color.web("#B0BEC5"));
            g.fillText(trainingPlayer.debugNormalAttackConnected() ? "CONTACT" : "NO CONTACT YET",
                    rightX, framePanelY + 31);
        } else if (trainingPlayer != null && trainingPlayer.debugNormalAttackCooldownFrames() > 0) {
            g.setFill(Color.web("#FFD166"));
            g.fillText("REATTACK  " + trainingPlayer.debugNormalAttackCooldownFrames()
                    + "f — MOVEMENT READY", leftX, framePanelY + 31);
        } else {
            g.setFill(Color.web("#90A4AE"));
            g.fillText("FRAME DATA  READY — ATTACK TO INSPECT", leftX, framePanelY + 31);
        }
        if (trainingShieldAdvantageAvailable) {
            String sign = trainingLastShieldAdvantageFrames > 0 ? "+" : "";
            g.setFill(trainingLastShieldAdvantageFrames >= 0
                    ? Color.web("#A5D6A7") : Color.web("#FFAB91"));
            g.fillText((trainingLastShieldParry ? "PARRY" : "ON SHIELD") + "  "
                            + sign + trainingLastShieldAdvantageFrames + "f",
                    rightX, framePanelY + 53);
        }
        if (trainingPlayer != null) {
            g.setFill(Color.web("#B2EBF2"));
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 12));
            g.fillText("STATE  " + trainingPlayer.debugUniversalActionLabel(), rightX, framePanelY + 9);
        }

        g.setFill(Color.web("#FFE082"));
        g.setFont(Font.font("Consolas", 11));
        double tipsY = panelY + panelH - 39;
        g.fillText("F4 DUMMY   F5 RESET   F6 REFILL", panelX + 14, tipsY);
        g.fillText("F7 BOXES   F8 SLOMO   F9 FREEZE   F10 STEP", panelX + 14, tipsY + 17);
        g.restore();
        drawTrainingLiveSpecialOverlay(g);
    }

    private void drawTrainingLiveSpecialOverlay(GraphicsContext g) {
        if (!trainingModeActive || players == null || players.length == 0) {
            return;
        }
        Bird player = players[0];
        if (player == null || player.type == null) {
            return;
        }

        Bird.DirectionalSpecialInput input = player.selectDirectionalSpecialInput();
        int selectedIndex = directionalSpecialInputIndex(input);
        String[] moves = specialMoveNames(player.type);
        String inputLabel = directionalSpecialInputLabel(input);
        String moveName = moves[Math.clamp(selectedIndex, 0, moves.length - 1)];
        String status = player.specialHeld() ? "SPECIAL HELD" : "INPUT PREVIEW";
        String note = trainingLiveSpecialNote(player);
        boolean academySpecialLesson = isGuidedDirectionalSpecialLesson();

        double panelW = 420;
        double panelX = WIDTH - panelW - 22;
        double panelY = 220;
        double textX = panelX + 15;
        double maxTextW = panelW - 30;
        Font noteFont = Font.font("Consolas", 13);
        List<String> noteLines = wrapTextToLines(note, noteFont, maxTextW);
        double panelH = 153 + noteLines.size() * 17.0;
        Color accent = player.type.color == null ? Color.web("#80DEEA") : player.type.color;

        g.save();
        g.setFill(Color.BLACK.deriveColor(0, 1, 1, 0.74));
        g.fillRoundRect(panelX, panelY, panelW, panelH, 18, 18);
        g.setStroke(accent.interpolate(Color.WHITE, 0.35));
        g.setLineWidth(2.0);
        g.strokeRoundRect(panelX, panelY, panelW, panelH, 18, 18);

        g.setFill(Color.web("#FFF59D"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 15));
        g.fillText("LIVE SPECIAL", textX, panelY + 25);

        g.setFill(Color.web("#CFD8DC"));
        g.setFont(Font.font("Consolas", 13));
        g.fillText(shortName(player.name).toUpperCase(Locale.ROOT) + "  |  " + status, textX, panelY + 46);

        g.setFill(accent.deriveColor(0, 1, 1.18, 0.22));
        g.fillRoundRect(textX, panelY + 58, panelW - 30, 38, 12, 12);
        g.setStroke(accent.interpolate(Color.WHITE, 0.25));
        g.setLineWidth(1.4);
        g.strokeRoundRect(textX, panelY + 58, panelW - 30, 38, 12, 12);
        g.setFill(Color.WHITE);
        g.setFont(Font.font("Arial Black", 16));
        g.fillText(inputLabel + " SPECIAL: " + moveName, textX + 12, panelY + 83);

        double pillY = panelY + 107;
        double pillW = 91;
        double pillGap = 6;
        String[] labels = {"N", "S", "U", "D"};
        for (int i = 0; i < labels.length; i++) {
            drawTrainingSpecialInputPill(g, labels[i], moves[i], i == selectedIndex,
                    academySpecialLesson && trainingSpecialInputCompleted(i),
                    textX + i * (pillW + pillGap), pillY, pillW, 28, accent);
        }

        g.setFill(Color.web("#B2EBF2"));
        g.setFont(noteFont);
        double rowY = panelY + 153;
        for (String line : noteLines) {
            g.fillText(line, textX, rowY);
            rowY += 17;
        }
        g.restore();
    }

    private void drawTrainingSpecialInputPill(GraphicsContext g, String label, String moveName, boolean selected,
                                              boolean completed,
                                              double x, double y, double w, double h, Color accent) {
        Color fill = selected
                ? accent.deriveColor(0, 1, 1.10, 0.90)
                : completed ? Color.web("#2E7D32", 0.88) : Color.web("#263238", 0.82);
        Color stroke = selected
                ? Color.WHITE.deriveColor(0, 1, 1, 0.82)
                : completed ? Color.web("#A5D6A7", 0.86) : Color.web("#90A4AE", 0.48);
        Color text = selected ? Color.web("#111111") : Color.web("#ECEFF1");
        g.setFill(fill);
        g.fillRoundRect(x, y, w, h, 10, 10);
        g.setStroke(stroke);
        g.setLineWidth(selected ? 1.8 : 1.1);
        g.strokeRoundRect(x, y, w, h, 10, 10);
        g.setFill(text);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 12));
        String shortMove = moveName == null ? "-" : moveName;
        if (shortMove.length() > 11) {
            shortMove = shortMove.substring(0, 10) + ".";
        }
        g.fillText(completed && !selected ? label + " OK" : label + " " + shortMove, x + 8, y + 21);
    }

    private int directionalSpecialInputIndex(Bird.DirectionalSpecialInput input) {
        return switch (input) {
            case SIDE -> 1;
            case UP -> 2;
            case DOWN -> 3;
            default -> 0;
        };
    }

    private String directionalSpecialInputLabel(Bird.DirectionalSpecialInput input) {
        return switch (input) {
            case SIDE -> "SIDE";
            case UP -> "UP";
            case DOWN -> "DOWN";
            default -> "NEUTRAL";
        };
    }

    private String trainingLiveSpecialNote(Bird player) {
        if (isGuidedDirectionalSpecialLesson()) {
            return trainingDirectionalSpecialProgressText();
        }
        if (trainingAcademyMode == TrainingAcademyMode.GUIDED_TUTORIAL) {
            return switch (currentGuidedTutorialLesson()) {
                case PIGEON_DRILL -> trainingPigeonDrillProgressText();
                case EAGLE_DRILL -> trainingEagleDrillProgressText();
                case GOOSE_DRILL -> trainingGooseDrillProgressText(player);
                case TITMOUSE_DRILL -> trainingTitmouseDrillProgressText();
                case OPIUM_DRILL -> trainingOpiumDrillProgressText();
                case HEISEN_DRILL -> trainingHeisenDrillProgressText();
                case BAT_DRILL -> trainingBatDrillProgressText();
                case RAVEN_DRILL -> trainingRavenDrillProgressText();
                case VULTURE_DRILL -> trainingVultureDrillProgressText();
                case FALCON_DRILL -> trainingFalconDrillProgressText();
                case PHOENIX_DRILL -> trainingPhoenixDrillProgressText();
                case ROADRUNNER_DRILL -> trainingRoadrunnerDrillProgressText(player);
                case ROOSTER_DRILL -> trainingRoosterDrillProgressText(player);
                case PELICAN_DRILL -> trainingPelicanDrillProgressText(player);
                case HUMMINGBIRD_DRILL -> trainingHummingbirdDrillProgressText();
                case TURKEY_DRILL -> trainingTurkeyDrillProgressText();
                case PENGUIN_DRILL -> trainingPenguinDrillProgressText();
                case SHOEBILL_DRILL -> trainingShoebillDrillProgressText();
                case MOCKINGBIRD_DRILL -> trainingMockingbirdDrillProgressText(player);
                case RAZORBILL_DRILL -> trainingRazorbillDrillProgressText();
                case GRINCHHAWK_DRILL -> trainingGrinchhawkDrillProgressText();
                case KIWI_DRILL -> trainingDirectionalSpecialProgressText();
                default -> specialMoveGuideNote(player.type);
            };
        }
        return switch (player.type) {
            case TITMOUSE -> "MARK improves follow-ups. STASH count: "
                    + player.titmouseSeedStashes.size() + "/" + Bird.TITMOUSE_MAX_STASHES + ".";
            case OPIUMBIRD -> "DROWSY slows targets. OPIUM: "
                    + Math.round(player.getOpiumResourceRatio() * 100.0) + "%. PATCH refuels it.";
            case HEISENBIRD -> "BRITTLE boosts crystal damage. CRYSTAL: "
                    + Math.round(player.getOpiumResourceRatio() * 100.0) + "%. NODE refuels it.";
            default -> specialMoveGuideNote(player.type);
        };
    }

    private boolean isGuidedDirectionalSpecialLesson() {
        return trainingAcademyMode == TrainingAcademyMode.GUIDED_TUTORIAL
                && currentGuidedTutorialLesson() == GuidedTutorialLesson.DIRECTIONAL_SPECIALS;
    }

    private boolean trainingSpecialInputCompleted(int index) {
        return switch (index) {
            case 1 -> trainingAcademySideSpecialSeen;
            case 2 -> trainingAcademyUpSpecialSeen;
            case 3 -> trainingAcademyDownSpecialSeen;
            default -> trainingAcademyNeutralSpecialSeen;
        };
    }

    private String trainingDirectionalSpecialProgressText() {
        int completed = 0;
        for (int i = 0; i < 4; i++) {
            if (trainingSpecialInputCompleted(i)) {
                completed++;
            }
        }
        String[] directionNames = {"Neutral", "Side", "Up", "Down"};
        String next = "complete";
        for (int i = 0; i < directionNames.length; i++) {
            if (!trainingSpecialInputCompleted(i)) {
                next = directionNames[i];
                break;
            }
        }
        return "Academy goal: use every direction. Progress: " + completed + "/4. Next: " + next + ".";
    }

