    private record FightHudPanelLayout(Bird bird, Rectangle2D panelRect, Rectangle2D portraitRect) {}

    record FightHudMeterLayout(Font damageFont, Font percentFont, double damageRightInset,
                               double percentRightInset, double damageBaselineOffset,
                               double healthBarYOffset, double healthBarHeight,
                               double healthBarRightInset, double ultimateBarInset,
                               double ultimateBarHeight, double ultimateBottomInset) {
        double healthBarBottomOffset() {
            return healthBarYOffset + healthBarHeight;
        }

        double ultimateBarYOffset(double panelHeight) {
            return panelHeight - ultimateBottomInset - ultimateBarHeight;
        }

        double ultimateLabelBaselineOffset(double panelHeight) {
            return ultimateBarYOffset(panelHeight) + ultimateBarHeight - 2.5;
        }
    }

    private record FightHudLayout(List<FightHudPanelLayout> panels, Rectangle2D minimapRect, Rectangle2D infoRect,
                                  List<String> infoLines, Rectangle2D timerRect, List<Rectangle2D> occlusionRects) {}

    private void resetFightHudStateForMatchStart() {
        fightHudPortraitCache.clear();
        currentFightHudOcclusionRects = List.of();
        currentRenderShakeX = 0.0;
        currentRenderShakeY = 0.0;
        matchIntroLastAnnouncedPhase = Integer.MIN_VALUE;
        if (trainingModeActive) {
            matchIntroOverlayFrames = 0;
            matchStartNano = System.nanoTime();
        } else {
            matchIntroOverlayFrames = MATCH_INTRO_COUNTDOWN_FRAMES + MATCH_INTRO_GO_FRAMES;
            matchStartNano = 0L;
        }
    }

    private void updateMatchIntroCountdown() {
        if (trainingModeActive) {
            matchIntroOverlayFrames = 0;
            if (matchStartNano == 0L) {
                matchStartNano = System.nanoTime();
            }
            matchIntroLastAnnouncedPhase = -1;
            return;
        }
        if (matchIntroOverlayFrames <= 0) {
            if (matchStartNano == 0L) {
                matchStartNano = System.nanoTime();
            }
            matchIntroLastAnnouncedPhase = -1;
            return;
        }
        matchIntroOverlayFrames--;
        if (matchIntroOverlayFrames == MATCH_INTRO_GO_FRAMES && matchStartNano == 0L) {
            matchStartNano = System.nanoTime();
        }
        maybePlayMatchIntroSfx();
    }

    boolean isMatchIntroLocked() {
        return !trainingModeActive && matchIntroOverlayFrames > MATCH_INTRO_GO_FRAMES;
    }

    private boolean isMatchIntroVisible() {
        return !trainingModeActive && matchIntroOverlayFrames > 0;
    }

    private String currentMatchIntroLabel() {
        if (!isMatchIntroVisible()) {
            return null;
        }
        if (matchIntroOverlayFrames > MATCH_INTRO_GO_FRAMES) {
            int count = (int) Math.ceil((matchIntroOverlayFrames - MATCH_INTRO_GO_FRAMES) / 60.0);
            return Integer.toString(Math.max(1, count));
        }
        return "GO!";
    }

    private int currentMatchIntroAnnouncementPhase() {
        String label = currentMatchIntroLabel();
        if (label == null || label.isBlank()) {
            return -1;
        }
        return "GO!".equals(label) ? 0 : Integer.parseInt(label);
    }

    private void maybePlayMatchIntroSfx() {
        int phase = currentMatchIntroAnnouncementPhase();
        if (phase == matchIntroLastAnnouncedPhase) {
            return;
        }
        matchIntroLastAnnouncedPhase = phase;
        if (phase >= 1 && phase <= 3) {
            playMatchIntroCountSfx();
        } else if (phase == 0) {
            playMatchIntroGoSfx();
        }
    }

    private Rectangle2D fightHudCountdownRect() {
        String label = currentMatchIntroLabel();
        if (label == null || label.isBlank()) {
            return null;
        }
        boolean go = "GO!".equals(label);
        double plateWidth = go ? 560 : 340;
        double plateHeight = go ? 176 : 196;
        return new Rectangle2D(WIDTH / 2.0 - plateWidth / 2.0, 116, plateWidth, plateHeight);
    }

    private FightHudLayout buildFightHudLayout() {
        List<FightHudPanelLayout> panels = buildFightHudPanels();
        List<String> infoLines = fightHudInfoLines();
        boolean academyActive = trainingAcademyMode != TrainingAcademyMode.NONE;
        Rectangle2D minimapRect = academyActive ? null : new Rectangle2D(24, 24, 190, 138);
        Rectangle2D infoRect = buildFightHudInfoRect(infoLines, minimapRect);
        Rectangle2D timerRect = academyActive ? null : new Rectangle2D(WIDTH - 274, 28, 240, 102);

        List<Rectangle2D> occlusionRects = new ArrayList<>();
        for (FightHudPanelLayout panel : panels) {
            occlusionRects.add(panel.panelRect());
        }
        if (minimapRect != null) {
            occlusionRects.add(minimapRect);
        }
        if (infoRect != null) {
            occlusionRects.add(infoRect);
        }
        if (timerRect != null) {
            occlusionRects.add(timerRect);
        }
        if (academyActive) {
            occlusionRects.add(new Rectangle2D((WIDTH - 820.0) / 2.0, 28, 820, 326));
        }
        Rectangle2D countdownRect = fightHudCountdownRect();
        if (countdownRect != null) {
            occlusionRects.add(countdownRect);
        }
        return new FightHudLayout(panels, minimapRect, infoRect, infoLines, timerRect, List.copyOf(occlusionRects));
    }

    private List<FightHudPanelLayout> buildFightHudPanels() {
        List<Bird> hudBirds = new ArrayList<>();
        for (int i = 0; i < activePlayers; i++) {
            if (players[i] != null) {
                hudBirds.add(players[i]);
            }
        }
        if (hudBirds.isEmpty() || hudBirds.size() > 6 || (isUnitedFinaleMassBattleContext() && activePlayers > 6)) {
            return List.of();
        }

        int count = hudBirds.size();
        double panelHeight = count >= 5 ? 126 : 146;
        double gap = count >= 5 ? 14 : 24;
        double panelWidth;
        List<Double> xPositions = new ArrayList<>();

        if (count == 1) {
            panelWidth = 460;
            xPositions.add((WIDTH - panelWidth) / 2.0);
        } else if (count == 2) {
            panelWidth = 430;
            xPositions.add(42.0);
            xPositions.add(WIDTH - 42.0 - panelWidth);
        } else {
            double minWidth = count >= 5 ? 250 : 285;
            double maxWidth = count >= 5 ? 300 : 360;
            panelWidth = Math.clamp((WIDTH - 120.0 - gap * (count - 1)) / count, minWidth, maxWidth);
            double totalWidth = panelWidth * count + gap * (count - 1);
            double startX = (WIDTH - totalWidth) / 2.0;
            for (int i = 0; i < count; i++) {
                xPositions.add(startX + i * (panelWidth + gap));
            }
        }

        double panelY = HEIGHT - panelHeight - 22;
        double portraitSize = count >= 5 ? 72 : 88;
        List<FightHudPanelLayout> layouts = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            double panelX = xPositions.get(i);
            Rectangle2D panelRect = new Rectangle2D(panelX, panelY, panelWidth, panelHeight);
            Rectangle2D portraitRect = new Rectangle2D(
                    panelX + 18,
                    panelY + Math.max(14, (panelHeight - portraitSize) / 2.0 - 4),
                    portraitSize,
                    portraitSize
            );
            layouts.add(new FightHudPanelLayout(hudBirds.get(i), panelRect, portraitRect));
        }
        return List.copyOf(layouts);
    }

    private Rectangle2D buildFightHudInfoRect(List<String> infoLines, Rectangle2D minimapRect) {
        if (infoLines == null || infoLines.isEmpty()) {
            return null;
        }
        double maxWidth = 0.0;
        for (String line : infoLines) {
            maxWidth = Math.max(maxWidth, measureTextWidth(line, FIGHT_HUD_STATUS_FONT));
        }
        double paddingX = 22;
        double paddingY = 16;
        double lineHeight = measureTextHeight(FIGHT_HUD_STATUS_FONT) * 1.16;
        double width = Math.clamp(maxWidth + paddingX * 2, 320.0, 780.0);
        double height = paddingY * 2 + lineHeight * infoLines.size();
        double y = minimapRect == null ? 28 : minimapRect.getMaxY() + 16;
        return new Rectangle2D(24, y, width, height);
    }

    private List<String> fightHudInfoLines() {
        List<String> lines = new ArrayList<>();
        if (campaignModeActive && currentCampaignMission != null && campaignMissionController != null) {
            StoryCampaign.Act act = stillSkyCampaign.actForMission(currentCampaignMission.id());
            int actNumber = Math.max(1, stillSkyCampaign.actIndexForMission(currentCampaignMission.id()) + 1);
            lines.add("THE STILL SKY  ACT " + actNumber
                    + (act == null ? "" : "  " + act.title().replaceFirst("^Act [^:]+:\\s*", "").toUpperCase(Locale.ROOT)));
            lines.add(currentCampaignMission.title().toUpperCase(Locale.ROOT)
                    + "  |  " + stillSkyProgress.difficulty.label.toUpperCase(Locale.ROOT));
            StoryCampaign.MissionPhase phase = campaignMissionController.currentPhase();
            int percent = (int) Math.round(campaignMissionController.objectiveProgressRatio() * 100.0);
            lines.add("OBJECTIVE " + (campaignMissionController.phaseIndex() + 1)
                    + "/" + currentCampaignMission.phases().size()
                    + "  " + phase.label().toUpperCase(Locale.ROOT) + "  " + percent + "%");
            return lines;
        }
        if (classicModeActive && classicEncounter != null) {
            String classicModeLabel = dailyChallengeModeActive ? "DAILY"
                    : (ashfallTrialModeActive ? "ASHFALL TRIAL" : (bossRushModeActive ? "BOSS RUSH" : "CLASSIC"));
            lines.add(classicModeLabel + " " + (classicRoundIndex + 1) + "/" + classicRun.size()
                    + "  " + classicEncounter.name.toUpperCase(Locale.ROOT));
            lines.add("RULES  " + classicEncounter.mutator.label + " | " + classicEncounter.twist.label);
            int livesLeft = Math.max(0, 3 - classicDeaths);
            if (classicEncounter.style == ClassicEncounterStyle.BONUS_RELAY
                    || classicEncounter.style == ClassicEncounterStyle.RIPPLE_HUNT) {
                long targetsRemaining = Arrays.stream(players)
                        .filter(Objects::nonNull)
                        .filter(bird -> bird.classicBonusTarget && bird.health > 0.0)
                        .count();
                lines.add("TARGETS " + targetsRemaining + "/3  BONUS COINS +" + classicBonusCoins
                        + "  FALLING DOES NOT COST A LIFE");
            } else if (classicEncounter.style == ClassicEncounterStyle.PERFECT_PITCH) {
                lines.add((classicPitchRevealFrames > 0 ? "WATCH" : "PLAY") + " THE SCORE  NOTES "
                        + classicPitchSequenceIndex + "/" + classicPitchSequence.length
                        + "  BONUS COINS +" + classicBonusCoins);
            } else if (classicEncounter.style == ClassicEncounterStyle.NECTAR_DASH) {
                lines.add("FLOWER GATES " + classicNectarRingIndex + "/" + classicNectarRings.size()
                        + "  BLOSSOMS " + classicHummingbirdBlossomCount() + "/7"
                        + "  FALLING RESETS POSITION");
            } else if (classicEncounter.style == ClassicEncounterStyle.HARVEST_DEFENSE) {
                int waveCount = classicEncounter.waves == null ? 0 : classicEncounter.waves.length;
                lines.add("HARVEST " + classicTurkeyDefenseHealth + "%  WAVE "
                        + Math.min(waveCount, classicTurkeyDefenseWaveIndex + 1) + "/" + waveCount
                        + "  BONUS COINS +" + classicBonusCoins);
            } else if (classicEncounter.style == ClassicEncounterStyle.DAWN_MUSTER) {
                String[] commands = {"CALL", "TOSS", "LIFT", "RECALL", "COMPLETE"};
                lines.add("COMMAND " + Math.min(4, classicRoosterMusterStep + 1) + "/4  "
                        + commands[Math.clamp(classicRoosterMusterStep, 0, 4)]
                        + "  MORALE " + classicRoosterMorale + "/3");
            } else if (classicEncounter.style == ClassicEncounterStyle.REDLINE_RUN) {
                Bird runner = players[0];
                double runnerX = runner == null ? REDLINE_RUN_START_X : runner.bodyCenterX();
                lines.add("NEXT SPLIT " + (int) nextRedlineCheckpointAfter(runnerX)
                        + "  FINISH " + (int) REDLINE_RUN_FINISH_X
                        + "  BOLTS " + classicRoadrunnerBoltCount() + "/7");
            } else {
                lines.add(dailyChallengeModeActive
                    ? "LIVES " + livesLeft + "/3  SEED " + formatDailyChallengeSeed(dailyChallengeSeed)
                    : ashfallTrialModeActive
                    ? "LIVES " + livesLeft + "/3  REBIRTH ROUTE"
                    : bossRushModeActive
                    ? "REPAIR STOCKS " + livesLeft + "/3"
                    : "DIFFICULTY " + String.format(Locale.US, "%.1f", classicDifficulty)
                    + "  SCORE " + String.format(Locale.US, "%,d", classicRunScore)
                    + (classicSelectedBird == BirdType.HUMMINGBIRD
                    ? "  BLOSSOMS " + classicHummingbirdBlossomCount() + "/7"
                    : (classicEncounter.style == ClassicEncounterStyle.FEAST_GAUNTLET
                    ? "  COURSE " + (classicTurkeyWaveIndex + 1) + "/"
                    + (classicEncounter.waves == null ? 1 : classicEncounter.waves.length)
                    + (classicTurkeyFeastDecisionActive ? "  CHOOSE: FEAST OR BLOCK" : "")
                    : (classicEncounter.style == ClassicEncounterStyle.DEVOURER_BOSS
                    ? "  DEVOURER MEALS " + classicDevourerMeals : ""))));
            }
            if (classicSelectedBird == BirdType.ROOSTER
                    && classicEncounter.style != ClassicEncounterStyle.DAWN_MUSTER) {
                String detail = classicEncounter.style == ClassicEncounterStyle.BROOD_RESCUE
                        ? "  CAGES " + classicRoosterCagesRescued + "/3"
                        : (classicEncounter.style == ClassicEncounterStyle.BROOD_HUNT
                        ? "  CAPTURES " + classicRoosterHunterCaptures
                        : (classicEncounter.style == ClassicEncounterStyle.BROODBREAKER_BOSS
                        ? "  DAWN BELLS " + litDawnBellCount() + "/3" : ""));
                lines.add("BROOD MORALE " + classicRoosterMorale + "/3" + detail);
            }
            if (classicSelectedBird == BirdType.ROADRUNNER
                    && classicEncounter.style != ClassicEncounterStyle.REDLINE_RUN) {
                int meter = (int) Math.round(Math.clamp(classicRoadrunnerRedline / 420.0, 0.0, 1.0) * 100.0);
                lines.add("REDLINE " + meter + "%  BOLTS " + classicRoadrunnerBoltCount() + "/7"
                        + (classicEncounter.style == ClassicEncounterStyle.STILL_KING_BOSS
                        ? "  CONTROL FIELD " + Math.max(0, 3 - classicRoadrunnerBoltCount() / 2) + "/3" : ""));
            }
            if (classicSelectedBird == BirdType.PENGUIN) {
                int built = 0;
                for (ClassicIceworkAnchor anchor : classicPenguinIceworks) if (anchor.built()) built++;
                if (classicEncounter.style == ClassicEncounterStyle.ICE_ARCHITECT) {
                    int targets = 0;
                    for (boolean target : classicPenguinArchitectTargets) if (target) targets++;
                    lines.add("ICEWORKS " + built + "/3  TARGETS " + targets + "/3"
                            + (classicPenguinArchitectExitOpen ? "  GATE OPEN" : ""));
                } else if (classicEncounter.style == ClassicEncounterStyle.ICEWORKS_SIEGE) {
                    int waveCount = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add("ICEWORKS " + built + "/3  ASSAULT "
                            + Math.min(waveCount, classicPenguinSiegeWaveIndex + 1) + "/" + waveCount);
                } else {
                    lines.add("ICEWORKS " + built + "/3"
                            + (classicEncounter.style == ClassicEncounterStyle.LAST_SUN_BOSS
                            ? "  MELT PHASE " + classicLastSunPhase + "/2" : ""));
                }
            }
            if (classicSelectedBird == BirdType.MOCKINGBIRD) {
                if (classicEncounter.style == ClassicEncounterStyle.CHARLES_UNDERSTUDIES
                        || classicEncounter.style == ClassicEncounterStyle.CHOIR_MASK_GAUNTLET) {
                    int waveCount = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add((classicEncounter.style == ClassicEncounterStyle.CHARLES_UNDERSTUDIES
                            ? "UNDERSTUDY " : "CHOIR MASK ")
                            + Math.min(waveCount, classicCharlesWaveIndex + 1) + "/" + waveCount);
                } else if (classicEncounter.style == ClassicEncounterStyle.HOLLOW_MAESTRO_BOSS) {
                    lines.add("HOLLOW SCORE  MOVEMENT " + classicStaminaBossMovement() + "/3  "
                            + (classicCharlesBossReversalTimer > 0
                            ? "REVERSAL " + classicCharlesBossReversalTimer
                            : "NEXT CUE " + Math.max(0, classicCharlesBossAttackTimer)));
                }
            }
            if (classicSelectedBird == BirdType.RAZORBILL) {
                int seals = 0;
                for (boolean closed : classicRazorbillSeals) if (closed) seals++;
                if (classicEncounter.style == ClassicEncounterStyle.BETWEEN_LINES) {
                    lines.add(classicRazorbillBonusReady ? "ANCHOR EXPOSED — STRIKE CENTER"
                            : "DIMENSIONAL CUT " + (classicRazorbillBonusPatternIndex + 1) + "/4");
                } else if (classicEncounter.style == ClassicEncounterStyle.SEAM_WARDEN_GAUNTLET) {
                    int count = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add("SEAM WARDEN " + (classicRazorbillWaveIndex + 1) + "/" + count
                            + "  RIFT SEALS " + seals + "/3");
                } else if (classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS) {
                    lines.add("ZERO DIVIDE  DIVISION " + classicStaminaBossMovement() + "/3  "
                            + (classicSeamreaverGuardTimer > 0 ? "GUARD " + classicSeamreaverGuardTimer
                            : "RIFT SEALS " + seals + "/3"));
                } else {
                    lines.add("RIFT SEALS " + seals + "/3");
                }
            }
            if (classicSelectedBird == BirdType.VULTURE) {
                if (classicEncounter.style == ClassicEncounterStyle.FINAL_INVENTORY) {
                    int broken = (int) classicSalvageLocks.stream().filter(lock -> lock.broken).count();
                    lines.add("FINAL INVENTORY  LOCKS " + broken + "/7"
                            + (classicInventoryExitOpen ? "  EXTRACTION OPEN" : ""));
                } else if (classicEncounter.style == ClassicEncounterStyle.DEBT_ENGINE_BOSS) {
                    lines.add("FINAL ACCOUNT  PHASE " + classicStaminaBossMovement() + "/3  "
                            + (classicDebtEngineReversalTimer > 0
                            ? "COLLECTION BURST " + classicDebtEngineReversalTimer
                            : "NEXT AUDIT " + Math.max(0, classicDebtEngineAttackTimer)));
                } else if (classicEncounter.style == ClassicEncounterStyle.VULTURE_FALSE_FLOCK
                        || classicEncounter.style == ClassicEncounterStyle.VULTURE_AUCTION_GAUNTLET) {
                    int count = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add((classicEncounter.style == ClassicEncounterStyle.VULTURE_FALSE_FLOCK
                            ? "FALSE FLOCK " : "LAST AUCTION ")
                            + (classicVultureWaveIndex + 1) + "/" + count);
                }
            }
            if (classicSelectedBird == BirdType.OPIUMBIRD) {
                if (classicEncounter.style == ClassicEncounterStyle.OPIUM_LUCID_DASH) {
                    int fragments = (int) classicOpiumLucidFragments.stream().filter(f -> f.broken).count();
                    lines.add("LUCID FRAGMENTS " + fragments + "/12"
                            + (fragments == 12 ? "  WAKING BELL READY" : "  FOLLOW THE GOLD MARKER"));
                } else if (classicEncounter.style == ClassicEncounterStyle.OPIUM_FORECAST_GAUNTLET) {
                    int count = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add("FORECAST WAVE " + (classicOpiumWaveIndex + 1) + "/" + count
                            + "  SHADOWS SHOW ARRIVAL POINTS");
                } else if (classicEncounter.style == ClassicEncounterStyle.OPIUM_STILL_KING_BOSS) {
                    int seals = (int) classicOpiumCertaintySeals.stream().filter(s -> s.broken).count();
                    lines.add("FIXED FUTURE  CERTAINTY SEALS " + seals + "/3  PROPHECY "
                            + classicStaminaBossMovement() + "/3");
                }
            }
            if (classicSelectedBird == BirdType.HEISENBIRD) {
                if (classicEncounter.style == ClassicEncounterStyle.HEISEN_CALIBRATION) {
                    lines.add("FINAL CALIBRATION  REGULATORS " + classicHeisenRegulatorIndex + "/7"
                            + (classicHeisenRegulatorIndex < 7 ? "  FOLLOW THE CYAN MARKER" : "  COMPLETE"));
                } else if (classicEncounter.style == ClassicEncounterStyle.HEISEN_BATCH_GAUNTLET) {
                    int count = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add("PRODUCTION BATCH " + (classicHeisenWaveIndex + 1) + "/" + count);
                } else if (classicEncounter.style == ClassicEncounterStyle.HEISEN_BLUE_SKY_ENGINE_BOSS) {
                    lines.add("PRODUCT LAUNCH  PHASE " + classicStaminaBossMovement() + "/3  "
                            + (classicBlueSkyOverheatTimer > 0 ? "CORE OPEN " + classicBlueSkyOverheatTimer
                            : "SHELL SEALED"));
                }
            }
            if (classicSelectedBird == BirdType.TITMOUSE) {
                if (classicEncounter.style == ClassicEncounterStyle.TITMOUSE_MEMORY_CACHE) {
                    int found = (int) classicTitmouseMemoryCaches.stream().filter(cache -> cache.broken).count();
                    String state = classicTitmouseMemoryRevealFrames > 0
                            ? "MEMORIZE " + (classicTitmouseMemoryRevealFrames + 59) / 60 + "s"
                            : (classicTitmouseMemoryHintIndex >= 2 ? "FOLLOW THE GOLD CALL" : "REMEMBER THE CACHE PATH");
                    lines.add("HIDDEN CACHES " + found + "/7  " + state);
                } else if (classicEncounter.style == ClassicEncounterStyle.TITMOUSE_VOICE_GAUNTLET) {
                    int count = classicEncounter.waves == null ? 1 : classicEncounter.waves.length;
                    lines.add("ALARM WAVE " + (classicTitmouseWaveIndex + 1) + "/" + count);
                } else if (classicEncounter.style == ClassicEncounterStyle.TITMOUSE_OLD_OWL_BOSS) {
                    lines.add("THE LAST HUSH  PHASE " + classicStaminaBossMovement() + "/3  "
                            + (classicOldOwlReversalTimer > 0 ? "WING BURST " + classicOldOwlReversalTimer
                            : classicOldOwlOpenTimer > 0 ? "LANDING OPEN " + classicOldOwlOpenTimer
                            : "OWL GUARDED"));
                }
            }
            return lines;
        }

        if (competitionModeEnabled && !storyModeActive && !adventureModeActive && !classicModeActive) {
            lines.add("COMPETITION MODE");
            lines.add(competitionScoreLine());
        }

        if (activeMutator != MatchMutator.NONE && !competitionModeEnabled && !storyModeActive && !adventureModeActive && !classicModeActive) {
            lines.add("MUTATOR  " + activeMutator.label.toUpperCase(Locale.ROOT));
        }

        return lines;
    }

    private void drawFightHud(GraphicsContext g, FightHudLayout layout) {
        drawFightHudMinimap(g, layout.minimapRect());
        if (layout.infoRect() != null) {
            drawFightHudInfoBanner(g, layout.infoRect(), layout.infoLines());
        }
        if (layout.timerRect() != null) {
            drawFightHudTimer(g, layout.timerRect());
        }
        drawClassicStaminaBossHud(g);
        if (isUnitedFinaleMassBattleContext() && activePlayers > 6) {
            drawUnitedFinaleRaidHud(g);
        } else {
            for (FightHudPanelLayout panel : layout.panels()) {
                if (isClassicStaminaBoss(panel.bird())) continue;
                drawFightHudPanel(g, panel);
            }
        }
        drawFightStartCountdown(g);
    }

    private void drawClassicStaminaBossHud(GraphicsContext g) {
        Bird boss = firstClassicEnemyWithStocks();
        if (!isClassicStaminaBoss(boss) || boss.health <= 0.0) return;
        boolean seamreaver = classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS;
        boolean bellkeeper = classicEncounter.style == ClassicEncounterStyle.BELLKEEPER_BOSS;
        boolean debtEngine = classicEncounter.style == ClassicEncounterStyle.DEBT_ENGINE_BOSS;
        boolean stillKing = classicEncounter.style == ClassicEncounterStyle.OPIUM_STILL_KING_BOSS;
        boolean blueSkyEngine = classicEncounter.style == ClassicEncounterStyle.HEISEN_BLUE_SKY_ENGINE_BOSS;
        boolean oldOwl = classicEncounter.style == ClassicEncounterStyle.TITMOUSE_OLD_OWL_BOSS;

        double width = Math.min(980.0, WIDTH - 580.0);
        double height = 92.0;
        double x = (WIDTH - width) / 2.0;
        double y = 24.0;
        double maxHealth = Math.max(1.0, boss.getMaxHealth());
        double ratio = classicStaminaBossHealthRatio();
        int shownHealth = Math.max(0, (int) Math.ceil(boss.health));
        int shownMax = Math.max(1, (int) Math.round(maxHealth));
        double pulse = 0.5 + 0.5 * Math.sin(simTick * 0.09);
        Color phaseColor = oldOwl
                ? (classicStaminaBossMovement() == 1 ? Color.web("#FFE082")
                : classicStaminaBossMovement() == 2 ? Color.web("#FFB74D") : Color.web("#FF5252"))
                : blueSkyEngine
                ? (classicStaminaBossMovement() == 1 ? Color.web("#69E6FF")
                : classicStaminaBossMovement() == 2 ? Color.web("#F7E46B") : Color.web("#FF315E"))
                : stillKing
                ? (classicStaminaBossMovement() == 1 ? Color.web("#CE93D8")
                : classicStaminaBossMovement() == 2 ? Color.web("#FFD166") : Color.web("#FF5252"))
                : debtEngine
                ? (classicStaminaBossMovement() == 1 ? Color.web("#6BE7FF")
                : classicStaminaBossMovement() == 2 ? Color.web("#FF9F43") : Color.web("#FF3B30"))
                : bellkeeper
                ? (classicStaminaBossMovement() == 1 ? Color.web("#FFD166")
                : classicStaminaBossMovement() == 2 ? Color.web("#FF8F00") : Color.web("#FF5252"))
                : seamreaver
                ? (classicStaminaBossMovement() == 1 ? Color.web("#00E5FF")
                : classicStaminaBossMovement() == 2 ? Color.web("#EA80FC") : Color.web("#FF1744"))
                : (classicStaminaBossMovement() == 1 ? Color.web("#FFE082")
                : classicStaminaBossMovement() == 2 ? Color.web("#FFB74D") : Color.web("#FF5252"));

        g.save();
        g.setFill(Color.BLACK.deriveColor(0, 1, 1, 0.58));
        g.fillRoundRect(x - 8, y + 8, width + 16, height + 8, 30, 30);
        g.setFill(Color.web("#09060E", 0.96));
        g.fillRoundRect(x, y, width, height, 28, 28);
        g.setStroke(phaseColor.deriveColor(0, 1, 1, 0.82 + pulse * 0.18));
        g.setLineWidth(4.0 + pulse * 1.5);
        g.strokeRoundRect(x, y, width, height, 28, 28);

        if (oldOwl) {
            drawOldOwl(g, x + 52.0, y + 47.0, 0.14, classicOldOwlPhase,
                    classicOldOwlOpenTimer > 0, classicOldOwlReversalTimer > 0);
        } else if (blueSkyEngine) {
            drawBlueSkyEngine(g, x + 52.0, y + 47.0, 0.13, classicBlueSkyPhase,
                    classicBlueSkyOverheatTimer > 0, classicBlueSkyReversalTimer > 0);
        } else if (stillKing) {
            g.setFill(Color.web("#110D20"));
            g.fillOval(x + 22.0, y + 18.0, 60.0, 60.0);
            g.setStroke(phaseColor);
            g.setLineWidth(5.0);
            g.strokeOval(x + 22.0, y + 18.0, 60.0, 60.0);
            for (int ray = 0; ray < 8; ray++) {
                double angle = ray * Math.PI / 4.0;
                g.strokeLine(x + 52.0 + Math.cos(angle) * 33.0, y + 48.0 + Math.sin(angle) * 33.0,
                        x + 52.0 + Math.cos(angle) * 43.0, y + 48.0 + Math.sin(angle) * 43.0);
            }
            g.strokeLine(x + 52.0, y + 48.0, x + 71.0, y + 30.0);
        } else if (debtEngine) {
            drawDebtEngine(g, x + 52.0, y + 47.0, 0.13, classicDebtEnginePhase,
                    classicDebtEngineReversalTimer > 0);
        } else if (bellkeeper) {
            drawClockworkOwl(g, x + 52.0, y + 47.0, 0.24, classicBellkeeperPhase, true);
        } else if (seamreaver) {
            drawSeamConstruct(g, x + 52.0, y + 47.0, 0.22, true, classicSeamreaverPhase);
        } else {
            drawHollowMaestroMask(g, x + 52.0, y + 47.0, 0.24, phaseColor, true);
        }
        g.setTextAlign(TextAlignment.LEFT);
        g.setFill(Color.WHITE);
        g.setFont(Font.font("Arial Black", FontWeight.BOLD, 25));
        g.fillText(oldOwl ? "THE OLD OWL" : blueSkyEngine ? "THE BLUE SKY ENGINE" : stillKing ? "THE STILL KING" : debtEngine ? "THE DEBT ENGINE" : bellkeeper ? "THE BELLKEEPER"
                : seamreaver ? "THE SEAMREAVER" : "THE HOLLOW MAESTRO", x + 105.0, y + 31.0);
        g.setFill(phaseColor);
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 16));
        g.fillText((blueSkyEngine ? "FORECAST " : stillKing ? "PROPHECY " : debtEngine ? "ACCOUNT " : bellkeeper ? "CHIME " : seamreaver ? "DIVISION " : "MOVEMENT ")
                + classicStaminaBossMovement() + " / 3", x + 106.0, y + 53.0);

        double barX = x + 410.0;
        double barY = y + 28.0;
        double barW = width - 560.0;
        double barH = 38.0;
        g.setFill(Color.web("#28070B"));
        g.fillRoundRect(barX, barY, barW, barH, 18, 18);
        g.setFill(phaseColor);
        g.fillRoundRect(barX, barY, barW * ratio, barH, 18, 18);
        g.setFill(Color.WHITE.deriveColor(0, 1, 1, 0.18));
        g.fillRoundRect(barX + 5.0, barY + 5.0, Math.max(0.0, barW * ratio - 10.0), 8.0, 12, 12);
        g.setStroke(Color.web("#FFF3E0", 0.86));
        g.setLineWidth(2.0);
        g.strokeRoundRect(barX, barY, barW, barH, 18, 18);
        for (int section = 1; section <= 2; section++) {
            double dividerX = barX + barW * section / 3.0;
            g.setStroke(Color.web("#09060E", 0.92));
            g.setLineWidth(5.0);
            g.strokeLine(dividerX, barY + 2.0, dividerX, barY + barH - 2.0);
        }

        g.setTextAlign(TextAlignment.RIGHT);
        g.setFill(Color.WHITE);
        g.setFont(Font.font("Arial Black", FontWeight.BOLD, 21));
        g.fillText(shownHealth + " / " + shownMax + " HP", x + width - 24.0, y + 57.0);
        g.setTextAlign(TextAlignment.LEFT);
        g.restore();
    }

    private void drawFightHudMinimap(GraphicsContext g, Rectangle2D rect) {
        if (rect == null) {
            return;
        }

        double mapX = rect.getMinX();
        double mapY = rect.getMinY();
        double mapW = rect.getWidth();
        double mapH = rect.getHeight();
        double innerPad = 10.0;
        double innerX = mapX + innerPad;
        double innerY = mapY + innerPad + 6.0;
        double innerW = mapW - innerPad * 2;
        double innerH = mapH - innerPad * 2 - 8.0;
        double scaleX = innerW / WORLD_WIDTH;
        double scaleY = innerH / WORLD_HEIGHT;

        double hudAlpha = hudAlphaForRect(rect);
        g.save();
        g.setGlobalAlpha(hudAlpha);
        g.setFill(Color.web("#050B11", 0.84));
        g.fillRoundRect(mapX, mapY, mapW, mapH, 24, 24);
        g.setFill(Color.web("#80DEEA", 0.16));
        g.fillRoundRect(mapX, mapY, mapW, 14, 24, 24);
        g.setStroke(Color.web("#90CAF9", 0.94));
        g.setLineWidth(2.2);
        g.strokeRoundRect(mapX, mapY, mapW, mapH, 24, 24);

        g.setFill(Color.web("#09141D", 0.92));
        g.fillRoundRect(innerX, innerY, innerW, innerH, 18, 18);
        g.setStroke(Color.web("#263238", 0.9));
        g.setLineWidth(1.2);
        g.strokeRoundRect(innerX, innerY, innerW, innerH, 18, 18);

        for (Bird b : players) {
            if (b != null && b.health > 0) {
                Color dot = fightHudAccentColor(b);
                g.setFill(dot);
                double mx = innerX + b.x * scaleX;
                double my = innerY + b.y * scaleY;
                g.fillOval(mx - 3.2, my - 3.2, 6.4, 6.4);
            }
        }

        double camViewW = (WIDTH / zoom) * scaleX;
        double camViewH = (HEIGHT / zoom) * scaleY;
        g.setStroke(Color.web("#FFF59D"));
        g.setLineWidth(2.0);
        g.strokeRoundRect(innerX + camX * scaleX, innerY + camY * scaleY, camViewW, camViewH, 8, 8);

        g.setFill(Color.web("#D7E3EA"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 14));
        g.fillText("MAP", mapX + 16, mapY + 22);
        g.restore();
    }

    private void drawFightHudInfoBanner(GraphicsContext g, Rectangle2D rect, List<String> infoLines) {
        if (rect == null || infoLines == null || infoLines.isEmpty()) {
            return;
        }
        Color accent = fightHudAccentColor(null);
        double hudAlpha = hudAlphaForRect(rect);
        g.save();
        g.setGlobalAlpha(hudAlpha);
        g.setFill(Color.web("#050B11", 0.82));
        g.fillRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), rect.getHeight(), 24, 24);
        g.setFill(accent.deriveColor(0, 1, 1, 0.18));
        g.fillRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), 14, 24, 24);
        g.setStroke(accent.deriveColor(0, 1, 1, 0.9));
        g.setLineWidth(2.2);
        g.strokeRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), rect.getHeight(), 24, 24);
        g.restore();

        double lineHeight = measureTextHeight(FIGHT_HUD_STATUS_FONT) * 1.16;
        double textX = rect.getMinX() + 22;
        double textY = rect.getMinY() + 18 + measureTextHeight(FIGHT_HUD_STATUS_FONT) * 0.82;
        g.setFill(Color.WHITE);
        g.setFont(FIGHT_HUD_STATUS_FONT);
        for (int i = 0; i < infoLines.size(); i++) {
            Color lineColor = i == 0 ? accent.brighter() : Color.web("#D7E3EA");
            g.setFill(lineColor);
            g.fillText(infoLines.get(i), textX, textY + i * lineHeight);
        }
    }

    private void drawFightHudTimer(GraphicsContext g, Rectangle2D rect) {
        boolean suddenDeathActive = suddenDeath.isActive();
        Color accent = trainingModeActive
                ? Color.web("#80DEEA")
                : suddenDeathActive
                ? Color.web("#FF7043")
                : matchTimer <= 600
                ? Color.web("#FFD54F")
                : Color.web("#8BC34A");

        double hudAlpha = hudAlphaForRect(rect);
        g.save();
        g.setGlobalAlpha(hudAlpha);
        g.setFill(Color.web("#050B11", 0.86));
        g.fillRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), rect.getHeight(), 28, 28);
        g.setFill(accent.deriveColor(0, 1, 1, 0.18));
        g.fillRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), 16, 28, 28);
        g.setStroke(accent.deriveColor(0, 1, 1, 0.94));
        g.setLineWidth(2.4);
        g.strokeRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), rect.getHeight(), 28, 28);

        double centerX = rect.getMinX() + rect.getWidth() / 2.0;
        g.setTextAlign(TextAlignment.CENTER);
        g.setFill(Color.web("#D7E3EA"));
        g.setFont(FIGHT_HUD_TIMER_LABEL_FONT);
        g.fillText(trainingModeActive ? "MODE" : "TIME", centerX, rect.getMinY() + 32);

        if (trainingModeActive) {
            g.setFill(accent);
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 34));
            g.fillText("TRAINING", centerX, rect.getMinY() + 78);
        } else if (suddenDeathActive) {
            g.setFill(Color.web("#FFE0B2"));
            g.setFont(Font.font("Arial Black", FontWeight.BOLD, 26));
            g.fillText("SUDDEN", centerX, rect.getMinY() + 62);
            g.fillText("DEATH", centerX, rect.getMinY() + 90);
        } else {
            g.setFill(Color.WHITE);
            g.setFont(FIGHT_HUD_TIMER_VALUE_FONT);
            g.fillText(formatFightHudTimer(Math.max(0, matchTimer)), centerX, rect.getMinY() + 84);
        }
        g.setTextAlign(TextAlignment.LEFT);
        g.restore();
    }

    static String ultimateChargeStatusText(double ratio, boolean ready) {
        if (ready) {
            return "READY";
        }
        double clamped = Math.clamp(ratio, 0.0, 1.0);
        int percent = Math.min(99, (int) Math.floor(clamped * 100.0 + 1.0e-9));
        return percent + "%";
    }

    private void drawFightHudPanel(GraphicsContext g, FightHudPanelLayout layout) {
        Bird bird = layout.bird();
        if (bird == null) {
            return;
        }

        Rectangle2D rect = layout.panelRect();
        Rectangle2D portraitRect = layout.portraitRect();
        Color accent = fightHudAccentColor(bird);
        boolean grayOut = shouldGrayOutFightHudPanel(bird);
        double aliveAlpha = grayOut ? 0.62 : bird.health > 0 ? 1.0 : 0.68;
        double panelHudAlpha = hudAlphaForRect(rect);
        g.save();
        g.setGlobalAlpha(aliveAlpha * panelHudAlpha);
        if (grayOut) {
            g.setEffect(ELIMINATED_FIGHTER_HUD_EFFECT);
        }

        g.setFill(Color.web("#000000", 0.34));
        g.fillRoundRect(rect.getMinX(), rect.getMinY() + 7, rect.getWidth(), rect.getHeight(), 30, 30);

        g.setFill(Color.web("#050B11", 0.88));
        g.fillRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), rect.getHeight(), 30, 30);

        g.setFill(accent.deriveColor(0, 1, 1, 0.18));
        g.fillRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), 14, 30, 30);

        g.setFill(accent.deriveColor(0, 1, 1, 0.11));
        g.fillPolygon(
                new double[]{
                        rect.getMaxX() - 150, rect.getMaxX() - 30, rect.getMaxX() - 30, rect.getMaxX() - 220
                },
                new double[]{
                        rect.getMinY() + 24, rect.getMinY() + 24, rect.getMaxY() - 18, rect.getMaxY() - 18
                },
                4
        );

        g.setStroke(accent.deriveColor(0, 1, 1, 0.92));
        g.setLineWidth(2.2);
        g.strokeRoundRect(rect.getMinX(), rect.getMinY(), rect.getWidth(), rect.getHeight(), 30, 30);
        g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.075));
        g.setLineWidth(0.9);
        g.strokeRoundRect(rect.getMinX() + 5, rect.getMinY() + 5,
                rect.getWidth() - 10, rect.getHeight() - 10, 24, 24);

        g.setFill(Color.web("#02060A", 0.96));
        g.fillRoundRect(portraitRect.getMinX(), portraitRect.getMinY(), portraitRect.getWidth(), portraitRect.getHeight(), 22, 22);
        g.setStroke(accent.deriveColor(0, 1, 1, 0.9));
        g.setLineWidth(1.9);
        g.strokeRoundRect(portraitRect.getMinX(), portraitRect.getMinY(), portraitRect.getWidth(), portraitRect.getHeight(), 22, 22);

        WritableImage portrait = fightHudPortraitImage(bird);
        if (portrait != null) {
            g.drawImage(
                    portrait,
                    portraitRect.getMinX() + 6,
                    portraitRect.getMinY() + 6,
                    portraitRect.getWidth() - 12,
                    portraitRect.getHeight() - 12
            );
        }

        String slotLabel = bird.playerIndex >= 0 ? "P" + (bird.playerIndex + 1) : "CPU";
        g.setFill(accent);
        g.fillRoundRect(rect.getMinX() + 14, rect.getMinY() + 10, 50, 24, 14, 14);
        g.setFill(Color.web("#041015"));
        g.setFont(Font.font("Arial Black", FontWeight.BOLD, 15));
        g.fillText(slotLabel, rect.getMinX() + 24, rect.getMinY() + 28);

        double shownDamage = displayedDamageForBird(bird);
        int shownHealth = (int) Math.round(shownDamage);
        String damageText = Integer.toString(shownHealth);
        FightHudMeterLayout meterLayout = fightHudMeterLayout(rect.getHeight());

        String name = shortName(bird.name);
        if (name.isBlank()) {
            name = bird.type != null ? bird.type.name.toUpperCase(Locale.ROOT) : "PLAYER";
        }
        String displayName = name.toUpperCase(Locale.ROOT);
        FightHudNameFit nameFit = fitFightHudNameFont(
                displayName,
                rect.getWidth(),
                portraitRect.getWidth(),
                damageText
        );
        double healthBarX = portraitRect.getMaxX() + 16;
        g.setFill(Color.WHITE);
        g.setFont(nameFit.font());
        // maxWidth is intentional: the font fitter preserves normal proportions
        // whenever possible, while this final guard prevents long authored
        // encounter titles from ever painting underneath the damage percentage.
        g.fillText(displayName, healthBarX, rect.getMinY() + 40, nameFit.maxWidth());

        g.setFill(Color.web("#B0BEC5"));
        g.setFont(Font.font("Consolas", FontWeight.BOLD, 15));
        int score = bird.playerIndex >= 0 && bird.playerIndex < scores.length ? scores[bird.playerIndex] : 0;
        if (usesSmashCombatRules()) {
            g.fillText("STOCKS", healthBarX, rect.getMinY() + 64);
            double iconSize = rect.getWidth() < 330 ? 18.0 : 20.0;
            drawFightHudStockIcons(g, bird, accent, healthBarX + 72, rect.getMinY() + 46, iconSize);
        } else {
            g.fillText("SCORE " + score, healthBarX, rect.getMinY() + 64);
        }

        double maxHealth = Math.max(1.0, bird.getMaxHealth());
        double healthRatio = Math.clamp(bird.health / maxHealth, 0.0, 1.0);
        double barRatio = usesSmashCombatRules()
                ? Math.min(1.0, shownDamage / 180.0)
                : healthRatio;
        Color healthColor = usesSmashCombatRules()
                ? fightHudDamageColor(shownDamage)
                : fightHudHealthColor(healthRatio);
        if (!usesSmashCombatRules() && bird.health <= 0) {
            healthColor = Color.web("#EF5350");
        }

        g.setTextAlign(TextAlignment.RIGHT);
        g.setFill(Color.BLACK.deriveColor(0, 1, 1, 0.42));
        g.setFont(meterLayout.damageFont());
        g.fillText(damageText, rect.getMaxX() - meterLayout.damageRightInset() + 5,
                rect.getMinY() + meterLayout.damageBaselineOffset() + 5);
        g.setFill(healthColor);
        g.fillText(damageText, rect.getMaxX() - meterLayout.damageRightInset(),
                rect.getMinY() + meterLayout.damageBaselineOffset());
        g.setFont(meterLayout.percentFont());
        g.setFill(Color.web("#ECEFF1"));
        g.fillText("%", rect.getMaxX() - meterLayout.percentRightInset(),
                rect.getMinY() + meterLayout.damageBaselineOffset());
        g.setTextAlign(TextAlignment.LEFT);

        double healthBarY = rect.getMinY() + meterLayout.healthBarYOffset();
        double healthBarW = rect.getWidth() - (healthBarX - rect.getMinX())
                - meterLayout.healthBarRightInset();
        double healthBarH = meterLayout.healthBarHeight();
        if (bird.hasOpiumResourceMeter()) {
            drawOpiumResourceHudBar(g, bird, healthBarX, healthBarY - 13, healthBarW, 8, true);
        }
        g.setFill(Color.web("#111A21", 0.95));
        g.fillRoundRect(healthBarX, healthBarY, healthBarW, healthBarH, 12, 12);
        g.setFill(usesSmashCombatRules() ? Color.web("#16242E") : Color.web("#5F1313"));
        g.fillRoundRect(healthBarX, healthBarY, healthBarW, healthBarH, 12, 12);
        g.setFill(healthColor);
        g.fillRoundRect(healthBarX, healthBarY, healthBarW * barRatio, healthBarH, 12, 12);
        if (!usesSmashCombatRules() && bird.health > maxHealth) {
            double overMax = Math.max(1.0, Bird.STARTING_HEALTH - maxHealth);
            double overRatio = Math.min(1.0, (bird.health - maxHealth) / overMax);
            g.setFill(Color.SILVER.deriveColor(0, 1, 1, 0.84));
            g.fillRoundRect(healthBarX, healthBarY, healthBarW * overRatio, healthBarH, 12, 12);
        }
        g.setStroke(Color.web("#D7E3EA", 0.74));
        g.setLineWidth(1.3);
        g.strokeRoundRect(healthBarX, healthBarY, healthBarW, healthBarH, 12, 12);

        if (bird.hasUltimate()) {
            double ultBarX = rect.getMinX() + meterLayout.ultimateBarInset();
            double ultBarY = rect.getMinY() + meterLayout.ultimateBarYOffset(rect.getHeight());
            double ultBarW = rect.getWidth() - meterLayout.ultimateBarInset() * 2.0;
            double ultBarH = meterLayout.ultimateBarHeight();
            double ultRatio = bird.getUltimateRatio();
            Color ultColor = bird.isUltimateReady()
                    ? Color.web("#FFD54F")
                    : Color.web("#4DD0E1");
            g.setFill(Color.web("#071018", 0.96));
            g.fillRoundRect(ultBarX, ultBarY, ultBarW, ultBarH, 12, 12);
            g.setFill(ultColor);
            g.fillRoundRect(ultBarX, ultBarY, ultBarW * ultRatio, ultBarH, 12, 12);
            double labelChipW = 38.0;
            double statusChipW = 50.0;
            g.setFill(Color.web("#02070B", 0.54));
            g.fillRoundRect(ultBarX, ultBarY, labelChipW, ultBarH, 12, 12);
            g.fillRoundRect(ultBarX + ultBarW - statusChipW, ultBarY,
                    statusChipW, ultBarH, 12, 12);
            g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.18));
            g.setLineWidth(0.75);
            g.strokeLine(ultBarX + labelChipW, ultBarY + 2,
                    ultBarX + labelChipW, ultBarY + ultBarH - 2);
            g.strokeLine(ultBarX + ultBarW - statusChipW, ultBarY + 2,
                    ultBarX + ultBarW - statusChipW, ultBarY + ultBarH - 2);
            g.setStroke(Color.WHITE.deriveColor(0, 1, 1, 0.15));
            g.strokeLine(ultBarX + 5, ultBarY + 2,
                    ultBarX + ultBarW - 5, ultBarY + 2);
            g.setStroke(Color.web("#F5F7FA", 0.7));
            g.setLineWidth(1.1);
            g.strokeRoundRect(ultBarX, ultBarY, ultBarW, ultBarH, 12, 12);

            g.setFill(Color.web("#E4EDF2"));
            g.setFont(Font.font("Consolas", FontWeight.BOLD, 9));
            double ultLabelY = rect.getMinY() + meterLayout.ultimateLabelBaselineOffset(rect.getHeight());
            g.fillText("ULT", ultBarX + 8.0, ultLabelY);
            g.setTextAlign(TextAlignment.RIGHT);
            g.setFill(bird.isUltimateReady() ? Color.web("#FFF59D") : Color.web("#B3E5FC"));
            g.fillText(
                    ultimateChargeStatusText(ultRatio, bird.isUltimateReady()),
                    ultBarX + ultBarW - 6.0,
                    ultLabelY
            );
            g.setTextAlign(TextAlignment.LEFT);
        }
        g.restore();
    }

    FightHudMeterLayout fightHudMeterLayout(double panelHeight) {
        boolean compact = panelHeight < 140.0;
        return new FightHudMeterLayout(
                compact ? Font.font("Impact", 46) : FIGHT_HUD_DAMAGE_FONT,
                Font.font("Arial Black", FontWeight.BOLD, compact ? 18 : 22),
                compact ? 43.0 : 48.0,
                20.0,
                compact ? 68.0 : 76.0,
                compact ? 80.0 : 92.0,
                compact ? 11.0 : 14.0,
                34.0,
                18.0,
                12.0,
                13.0
        );
    }

    boolean shouldGrayOutFightHudPanel(Bird bird) {
        if (bird == null || activePlayers <= 2) {
            return false;
        }
        if (usesSmashCombatRules()) {
            return !playerHasStocksRemaining(bird.playerIndex);
        }
        return bird.health <= 0.0;
    }

    private static ColorAdjust createEliminatedFighterHudEffect() {
        ColorAdjust effect = new ColorAdjust();
        effect.setSaturation(-1.0);
        effect.setBrightness(-0.18);
        effect.setContrast(0.10);
        return effect;
    }

    private void drawFightHudStockIcons(GraphicsContext g, Bird bird, Color accent, double startX, double y, double size) {
        if (bird == null) {
            return;
        }
        int stocks = fightHudStockIconCount(bird);
        WritableImage portrait = fightHudPortraitImage(bird);
        double gap = size <= 18.0 ? 5.0 : 6.0;
        for (int i = 0; i < stocks; i++) {
            double x = startX + i * (size + gap);
            g.setFill(Color.web("#02060A", 0.98));
            g.fillRoundRect(x, y, size, size, 8, 8);
            g.setStroke(accent.deriveColor(0, 1, 1, 0.9));
            g.setLineWidth(1.25);
            g.strokeRoundRect(x, y, size, size, 8, 8);
            if (portrait != null) {
                g.drawImage(portrait, x + 1.5, y + 1.5, size - 3.0, size - 3.0);
            } else {
                g.setFill(accent);
                g.fillOval(x + 3.0, y + 3.0, size - 6.0, size - 6.0);
            }
        }
    }

    int fightHudStockIconCount(Bird bird) {
        return bird == null ? 0 : Math.max(0, matchScoreForPlayer(bird.playerIndex));
    }

    private void drawFightStartCountdown(GraphicsContext g) {
        String label = currentMatchIntroLabel();
        if (label == null || label.isBlank()) {
            return;
        }

        boolean go = "GO!".equals(label);
        double plateWidth = go ? 560 : 340;
        double plateHeight = go ? 176 : 196;
        double plateX = WIDTH / 2.0 - plateWidth / 2.0;
        double plateY = 116;
        Color accent = go ? Color.web("#FF7043") : Color.web("#FFD54F");
        Font font = go ? FIGHT_HUD_GO_FONT : FIGHT_HUD_COUNTDOWN_FONT;
        // Center the actual visible glyphs in the plate. Font-metric centering
        // (baseline ratios, VPos.CENTER) drifts because metric boxes include
        // empty headroom; measuring the rendered glyph bounds does not.
        double baselineY = visuallyCenteredTextBaseline(font, label, plateY + plateHeight / 2.0);

        g.setFill(Color.web("#03070B", 0.58));
        g.fillRoundRect(plateX, plateY, plateWidth, plateHeight, 40, 40);
        g.setFill(accent.deriveColor(0, 1, 1, 0.18));
        g.fillRoundRect(plateX, plateY, plateWidth, 18, 40, 40);
        g.setStroke(accent.deriveColor(0, 1, 1, 0.94));
        g.setLineWidth(3.0);
        g.strokeRoundRect(plateX, plateY, plateWidth, plateHeight, 40, 40);

        g.setTextAlign(TextAlignment.CENTER);
        g.setFont(font);
        g.setFill(Color.BLACK.deriveColor(0, 1, 1, 0.4));
        g.fillText(label, WIDTH / 2.0 + 6, baselineY + 6);
        g.setStroke(go ? Color.web("#BF360C") : Color.web("#5D4037"));
        g.setLineWidth(go ? 8.0 : 10.0);
        g.strokeText(label, WIDTH / 2.0, baselineY);
        g.setFill(go ? Color.web("#FFF3E0") : Color.web("#FFF8E1"));
        g.fillText(label, WIDTH / 2.0, baselineY);
        g.setTextAlign(TextAlignment.LEFT);
    }

    /**
     * Baseline y that vertically centers the VISIBLE glyphs of {@code text} on
     * {@code centerY}. Uses visual text bounds, so fonts with tall metric boxes
     * (Impact et al.) center correctly regardless of built-in headroom.
     */
    private static double visuallyCenteredTextBaseline(Font font, String text, double centerY) {
        Text probe = new Text(text);
        probe.setFont(font);
        probe.setBoundsType(javafx.scene.text.TextBoundsType.VISUAL);
        var bounds = probe.getLayoutBounds();
        // With VISUAL bounds, minY/maxY are glyph extents relative to the baseline.
        return centerY - (bounds.getMinY() + bounds.getMaxY()) / 2.0;
    }

    private double hudAlphaForRect(Rectangle2D rect) {
        if (rect == null) return 1.0;
        for (Bird b : players) {
            if (b == null || b.health <= 0) continue;
            Rectangle2D bRect = fightHudScreenBounds(b);
            if (rect.intersects(bRect)) {
                return 0.26;
            }
        }
        return 1.0;
    }

    private Rectangle2D fightHudScreenBounds(Bird bird) {
        double size = Math.max(0.6, bird.sizeMultiplier);
        double width = (bird.type == BirdType.BAT ? 170 : 122) * size * zoom;
        double height = (bird.type == BirdType.BAT ? 120 : 108) * size * zoom;
        double x = (bird.x - 22 * size - camX + currentRenderShakeX) * zoom;
        double y = (bird.y - 18 * size - camY + currentRenderShakeY) * zoom;
        return new Rectangle2D(x, y, width, height);
    }

    private WritableImage fightHudPortraitImage(Bird bird) {
        if (bird == null || bird.type == null) {
            return null;
        }
        String skinKey = skinKeyForBird(bird);
        boolean charlesConstruct = isClassicCharlesConstructBird(bird);
        boolean razorbillConstruct = isClassicRazorbillConstructBird(bird);
        boolean grinchConstruct = isClassicGrinchHawkConstructBird(bird);
        boolean debtEngineConstruct = isClassicDebtEngineConstructBird(bird);
        boolean blueSkyEngineConstruct = isClassicBlueSkyEngineConstructBird(bird);
        boolean oldOwlConstruct = isClassicOldOwlBird(bird);
        boolean charlesBoss = charlesConstruct
                && classicEncounter.style == ClassicEncounterStyle.HOLLOW_MAESTRO_BOSS;
        boolean razorbillBoss = razorbillConstruct
                && classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS;
        String cacheKey = oldOwlConstruct
                ? "CLASSIC_OLD_OWL"
                : blueSkyEngineConstruct
                ? "CLASSIC_BLUE_SKY_ENGINE"
                : debtEngineConstruct
                ? "CLASSIC_DEBT_ENGINE"
                : grinchConstruct
                ? "CLASSIC_BELLKEEPER"
                : razorbillConstruct
                ? (razorbillBoss ? "CLASSIC_SEAMREAVER" : "CLASSIC_SEAM_WARDEN|" + shortName(bird.name))
                : charlesConstruct
                ? (charlesBoss ? "CLASSIC_HOLLOW_MAESTRO" : "CLASSIC_CHOIR_MASK|" + shortName(bird.name))
                : bird.classicBonusTarget
                ? "CLASSIC_BONUS_TARGET"
                : bird.type.name() + "|" + (skinKey == null ? "" : skinKey);
        WritableImage cached = fightHudPortraitCache.get(cacheKey);
        if (cached != null) {
            return cached;
        }
        // Canvas.snapshot is UI-thread-only. Headless balance/state tests draw
        // HUDs directly, so let their existing fallback marker represent a
        // portrait instead of making campaign-only skin keys require FX setup.
        if (!javafx.application.Platform.isFxApplicationThread()) {
            return null;
        }

        Canvas portrait = new Canvas(128, 128);
        if (oldOwlConstruct) {
            drawOldOwl(portrait.getGraphicsContext2D(), 64.0, 63.0,
                    0.21, classicOldOwlPhase, classicOldOwlOpenTimer > 0,
                    classicOldOwlReversalTimer > 0);
        } else if (blueSkyEngineConstruct) {
            drawBlueSkyEngine(portrait.getGraphicsContext2D(), 64.0, 63.0,
                    0.19, classicBlueSkyPhase, classicBlueSkyOverheatTimer > 0,
                    classicBlueSkyReversalTimer > 0);
        } else if (debtEngineConstruct) {
            drawDebtEngine(portrait.getGraphicsContext2D(), 64.0, 63.0,
                    0.19, classicDebtEnginePhase, classicDebtEngineReversalTimer > 0);
        } else if (grinchConstruct) {
            drawClockworkOwl(portrait.getGraphicsContext2D(), 64.0, 63.0,
                    0.36, classicBellkeeperPhase, true);
        } else if (razorbillConstruct) {
            drawSeamConstruct(portrait.getGraphicsContext2D(), 64.0, 63.0,
                    razorbillBoss ? 0.31 : 0.34, razorbillBoss,
                    razorbillBoss ? classicSeamreaverPhase : classicRazorbillWaveIndex);
        } else if (charlesConstruct) {
            drawHollowMaestroMask(portrait.getGraphicsContext2D(), 64.0, 63.0,
                    charlesBoss ? 0.39 : 0.34,
                    charlesBoss ? Color.web("#FFE082") : Color.web("#80DEEA"), charlesBoss);
        } else if (bird.classicBonusTarget) {
            drawClassicBonusTargetPortrait(portrait);
        } else {
            drawRosterSprite(portrait, bird.type, skinKey, false, true);
        }
        SnapshotParameters params = new SnapshotParameters();
        params.setFill(Color.TRANSPARENT);
        WritableImage image = portrait.snapshot(params, null);
        fightHudPortraitCache.put(cacheKey, image);
        return image;
    }

