    private StackPane buildVictoryPortraitNode(Bird bird, double size, boolean winnerPose) {
        double portraitSize = Math.max(140, size);
        Canvas sprite = new Canvas(portraitSize, portraitSize);
        boolean constructPortrait = drawClassicConstructVictoryPortrait(sprite, bird);
        if (!constructPortrait) {
            String skinKey = bird == null ? null : skinKeyForBird(bird);
            drawVictoryRosterSprite(sprite, bird == null ? null : bird.type, skinKey, winnerPose);
        }

        Canvas overlay = new Canvas(portraitSize, portraitSize);
        if (winnerPose && bird != null && !constructPortrait) {
            drawVictoryPoseOverlay(overlay, bird);
        }

        StackPane art = new StackPane(sprite, overlay);
        art.setAlignment(Pos.CENTER);

        StackPane frame = new StackPane(art);
        frame.setAlignment(Pos.CENTER);
        frame.setPrefSize(portraitSize, portraitSize);
        frame.setMinSize(portraitSize, portraitSize);
        frame.setMaxSize(portraitSize, portraitSize);
        installRegionClip(frame, 34, 34);
        return frame;
    }

    boolean usesClassicConstructVictoryPortrait(Bird bird) {
        return isClassicOldOwlBird(bird)
                || isClassicBlueSkyEngineConstructBird(bird)
                || isClassicDebtEngineConstructBird(bird)
                || isClassicGrinchHawkConstructBird(bird)
                || isClassicRazorbillConstructBird(bird)
                || isClassicCharlesConstructBird(bird);
    }

    private boolean drawClassicConstructVictoryPortrait(Canvas canvas, Bird bird) {
        if (!usesClassicConstructVictoryPortrait(bird)) return false;
        if (isClassicOldOwlBird(bird)) {
            drawClassicOldOwlPortrait(canvas);
        } else if (isClassicBlueSkyEngineConstructBird(bird)) {
            drawClassicBlueSkyEnginePortrait(canvas);
        } else if (isClassicDebtEngineConstructBird(bird)) {
            drawClassicDebtEnginePortrait(canvas);
        } else if (isClassicGrinchHawkConstructBird(bird)) {
            drawClassicBellkeeperPortrait(canvas);
        } else if (isClassicRazorbillConstructBird(bird)) {
            boolean boss = classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS;
            drawClassicRazorbillConstructPortrait(canvas, boss, matchSummaryBirdLabel(bird));
        } else {
            boolean boss = classicEncounter.style == ClassicEncounterStyle.HOLLOW_MAESTRO_BOSS;
            drawClassicCharlesConstructPortrait(canvas, boss, matchSummaryBirdLabel(bird));
        }
        return true;
    }

    record VictoryPortraitLayout(double extentFactor, double minScale, double maxScale, double xBias, double yBias) {
    }

    VictoryPortraitLayout victoryPortraitLayout(BirdType type, String skinKey, boolean winnerPose) {
        double extentFactor = winnerPose ? 0.92 : 1.00;
        double minScale = winnerPose ? 1.45 : 1.10;
        double maxScale = winnerPose ? 2.15 : 1.70;
        double xBias = 0.03;
        double yBias = winnerPose ? 0.12 : 0.10;
        VictoryPortraitLayout victoryPortraitLayout = new VictoryPortraitLayout(extentFactor, minScale, maxScale, xBias, yBias);
        if (type == null) {
            return victoryPortraitLayout;
        }
        final VictoryPortraitLayout victoryPortraitLayout1 = new VictoryPortraitLayout(winnerPose ? 0.96 : 1.04,
                winnerPose ? 1.40 : 1.08,
                winnerPose ? 2.00 : 1.60,
                0.00,
                0.00);
        VictoryPortraitLayout baseLayout = switch (type) {
            case BAT -> new VictoryPortraitLayout(winnerPose ? 1.48 : 1.60,
                    winnerPose ? 1.05 : 0.92,
                    winnerPose ? 1.60 : 1.28,
                    0.00,
                    0.00);
            case PIGEON -> new VictoryPortraitLayout(winnerPose ? 0.98 : 1.04,
                    winnerPose ? 1.35 : 1.02,
                    winnerPose ? 1.95 : 1.52,
                    0.00,
                    0.00);
            case EAGLE -> new VictoryPortraitLayout(winnerPose ? 0.90 : 0.98,
                    winnerPose ? 1.35 : 1.05,
                    winnerPose ? 1.90 : 1.55,
                    0.00,
                    0.00);
            case PELICAN -> new VictoryPortraitLayout(winnerPose ? 1.06 : 1.14,
                    winnerPose ? 1.28 : 1.00,
                    winnerPose ? 1.88 : 1.48,
                    0.00,
                    0.00);
            case TURKEY, VULTURE, GOOSE -> new VictoryPortraitLayout(winnerPose ? 1.04 : 1.12,
                    winnerPose ? 1.30 : 1.02,
                    winnerPose ? 1.90 : 1.52,
                    0.00,
                    0.00);
            case FALCON -> new VictoryPortraitLayout(winnerPose ? 0.92 : 1.00,
                    winnerPose ? 1.45 : 1.10,
                    winnerPose ? 2.15 : 1.70,
                    0.00,
                    0.00);
            case PHOENIX -> new VictoryPortraitLayout(winnerPose ? 0.94 : 1.02,
                    winnerPose ? 1.50 : 1.15,
                    winnerPose ? 2.20 : 1.75,
                    0.00,
                    0.00);
            case HUMMINGBIRD -> new VictoryPortraitLayout(winnerPose ? 0.85 : 0.92,
                    winnerPose ? 1.60 : 1.25,
                    winnerPose ? 2.30 : 1.85,
                    -0.04,
                    0.00);
            case ROOSTER -> new VictoryPortraitLayout(winnerPose ? 1.00 : 1.08,
                    winnerPose ? 1.35 : 1.05,
                    winnerPose ? 1.95 : 1.55,
                    0.00,
                    0.00);
            case ROADRUNNER -> new VictoryPortraitLayout(winnerPose ? 1.18 : 1.26,
                    winnerPose ? 1.22 : 0.96,
                    winnerPose ? 1.78 : 1.42,
                    -0.02,
                    0.0);
            case PENGUIN -> new VictoryPortraitLayout(winnerPose ? 1.02 : 1.10,
                    winnerPose ? 1.30 : 1.00,
                    winnerPose ? 1.85 : 1.48,
                    0.00,
                    0.00);
            case SHOEBILL -> new VictoryPortraitLayout(winnerPose ? 1.08 : 1.16,
                    winnerPose ? 1.25 : 0.98,
                    winnerPose ? 1.82 : 1.45,
                    0.00,
                    0.00);
            case MOCKINGBIRD, HEISENBIRD -> victoryPortraitLayout1;
            case RAZORBILL -> new VictoryPortraitLayout(winnerPose ? 0.98 : 1.06,
                    winnerPose ? 1.38 : 1.06,
                    winnerPose ? 1.98 : 1.58,
                    0.00,
                    0.00);
            case GRINCHHAWK, RAVEN -> new VictoryPortraitLayout(winnerPose ? 0.94 : 1.02,
                    winnerPose ? 1.42 : 1.10,
                    winnerPose ? 2.05 : 1.62,
                    0.00,
                    0.00);
            case OPIUMBIRD -> new VictoryPortraitLayout(winnerPose ? 0.92 : 1.00,
                    winnerPose ? 1.45 : 1.12,
                    winnerPose ? 2.10 : 1.68,
                    0.00,
                    0.00);
            case TITMOUSE -> new VictoryPortraitLayout(winnerPose ? 0.88 : 0.96,
                    winnerPose ? 1.55 : 1.20,
                    winnerPose ? 2.25 : 1.80,
                    0.00,
                    0.00);
            case KIWI -> new VictoryPortraitLayout(winnerPose ? 1.08 : 1.14,
                    winnerPose ? 1.32 : 1.04,
                    winnerPose ? 1.92 : 1.52,
                    0.00,
                    0.02);
        };

        double baseExtent = rosterSpriteExtentFactor(type, null);
        double skinExtent = rosterSpriteExtentFactor(type, skinKey);
        double extentRatio = Math.max(0.35, skinExtent / Math.max(0.01, baseExtent));
        double skinXBias = rosterSpriteXBias(type, skinKey) - rosterSpriteXBias(type, null);
        double skinYBias = rosterSpriteYBias(type, skinKey) - rosterSpriteYBias(type, null);
        double surfaceScale = winnerPose ? 1.0 : switch (type) {
            case HUMMINGBIRD, ROOSTER, SHOEBILL, PELICAN -> 0.80;
            default -> 0.88;
        };
        return new VictoryPortraitLayout(
                baseLayout.extentFactor() * extentRatio / surfaceScale,
                baseLayout.minScale() * surfaceScale / extentRatio,
                baseLayout.maxScale() * surfaceScale / extentRatio,
                baseLayout.xBias() + skinXBias,
                baseLayout.yBias() + skinYBias);
    }

    private void drawVictoryPoseOverlay(Canvas canvas, Bird bird) {
        if (bird == null || bird.type == null) return;
        GraphicsContext g = canvas.getGraphicsContext2D();
        double w = canvas.getWidth();
        double h = canvas.getHeight();
        g.clearRect(0, 0, w, h);

        switch (bird.type) {
            case PIGEON -> {
                g.setLineWidth(5);
                g.setStroke(Color.web("#ECEFF1"));
                g.strokeLine(w * 0.52, h * 0.52, w * 0.65, h * 0.49);
                g.setStroke(Color.web("#FF7043"));
                g.strokeLine(w * 0.64, h * 0.49, w * 0.69, h * 0.485);
                drawVictorySmokePuff(g, w * 0.72, h * 0.36, w * 0.075, Color.rgb(220, 225, 230, 0.58));
                drawVictorySmokePuff(g, w * 0.80, h * 0.26, w * 0.055, Color.rgb(240, 245, 248, 0.46));
            }
            case EAGLE -> {
                g.setStroke(Color.web("#FFD54F"));
                g.setLineWidth(10);
                g.strokeArc(w * 0.42, h * 0.48, w * 0.16, h * 0.10, 200, 140, ArcType.OPEN);
                g.strokeLine(w * 0.44, h * 0.51, w * 0.40, h * 0.50);
                g.strokeLine(w * 0.56, h * 0.51, w * 0.60, h * 0.50);
                drawVictorySparkle(g, w * 0.40, h * 0.50, w * 0.03, Color.web("#FFF59D"));
                drawVictorySparkle(g, w * 0.60, h * 0.50, w * 0.03, Color.web("#FFF59D"));
            }
            case FALCON -> {
                g.setLineWidth(10);
                g.setStroke(Color.web("#FF7043"));
                g.strokeLine(w * 0.16, h * 0.58, w * 0.42, h * 0.26);
                g.strokeLine(w * 0.22, h * 0.64, w * 0.50, h * 0.32);
                g.setLineWidth(6);
                g.setStroke(Color.web("#FFD180"));
                g.strokeLine(w * 0.58, h * 0.20, w * 0.82, h * 0.08);
                drawVictorySparkle(g, w * 0.78, h * 0.09, w * 0.032, Color.web("#FFE082"));
            }
            case PHOENIX -> {
                g.setStroke(Color.web("#FF7043"));
                g.setLineWidth(10);
                g.strokeOval(w * 0.23, h * 0.10, w * 0.54, h * 0.48);
                g.setStroke(Color.web("#FFD54F"));
                g.setLineWidth(6);
                g.strokeArc(w * 0.20, h * 0.08, w * 0.60, h * 0.52, 20, 120, ArcType.OPEN);
                g.strokeArc(w * 0.20, h * 0.08, w * 0.60, h * 0.52, 200, 120, ArcType.OPEN);
                drawVictorySparkle(g, w * 0.26, h * 0.22, w * 0.03, Color.web("#FFE082"));
                drawVictorySparkle(g, w * 0.74, h * 0.22, w * 0.03, Color.web("#FFE082"));
            }
            case HUMMINGBIRD -> {
                drawVictoryFlower(g, w * 0.74, h * 0.64, w * 0.08);
                g.setStroke(Color.web("#80DEEA"));
                g.setLineWidth(5);
                g.strokeArc(w * 0.44, h * 0.20, w * 0.28, h * 0.22, 40, 250, ArcType.OPEN);
            }
            case TURKEY -> {
                Color[] fan = new Color[]{Color.web("#D84315"), Color.web("#FFB74D"), Color.web("#8D6E63"), Color.web("#F06292")};
                for (int i = 0; i < fan.length; i++) {
                    g.setFill(fan[i].deriveColor(0, 1.0, 1.0, 0.7));
                    g.fillOval(w * (0.14 + i * 0.1), h * (0.10 + (i % 2) * 0.03), w * 0.26, h * 0.42);
                }
                g.setFill(Color.rgb(0, 0, 0, 0.16));
                g.fillOval(w * 0.28, h * 0.54, w * 0.44, h * 0.13);
            }
            case ROOSTER -> {
                g.setFill(Color.web("#6D4C41"));
                g.fillRoundRect(w * 0.44, h * 0.60, w * 0.09, h * 0.18, 12, 12);
                g.setFill(Color.web("#8D6E63"));
                g.fillRoundRect(w * 0.28, h * 0.71, w * 0.44, h * 0.05, 12, 12);
                g.setStroke(Color.web("#FFEB3B"));
                g.setLineWidth(6);
                g.strokeArc(w * 0.62, h * 0.22, w * 0.17, h * 0.17, 300, 240, ArcType.OPEN);
                g.strokeArc(w * 0.65, h * 0.19, w * 0.24, h * 0.24, 300, 210, ArcType.OPEN);
            }
            case PENGUIN -> {
                g.setFill(Color.rgb(144, 202, 249, 0.85));
                g.fillRoundRect(w * 0.22, h * 0.65, w * 0.56, h * 0.13, 28, 28);
                drawVictoryFish(g, w * 0.70, h * 0.58, w * 0.075, Color.web("#90A4AE"), Color.web("#CFD8DC"));
            }
            case SHOEBILL -> {
                drawVictoryFish(g, w * 0.74, h * 0.42, w * 0.085, Color.web("#42A5F5"), Color.web("#B3E5FC"));
                g.setStroke(Color.rgb(255, 255, 255, 0.35));
                g.setLineWidth(5);
                g.strokeOval(w * 0.30, h * 0.66, w * 0.40, h * 0.09);
            }
            case MOCKINGBIRD -> {
                g.setFill(Color.web("#111827"));
                g.fillRoundRect(w * 0.45, h * 0.29, w * 0.16, h * 0.037, 12, 12);
                g.fillRoundRect(w * 0.59, h * 0.295, w * 0.06, h * 0.024, 8, 8);
                g.setStroke(Color.web("#AB47BC"));
                g.setLineWidth(5);
                g.strokeLine(w * 0.75, h * 0.38, w * 0.75, h * 0.70);
                g.setStroke(Color.web("#EC407A"));
                g.setLineWidth(6);
                g.strokeOval(w * 0.69, h * 0.31, w * 0.13, h * 0.15);
                drawVictorySparkle(g, w * 0.82, h * 0.16, w * 0.03, Color.web("#F48FB1"));
            }
            case RAZORBILL -> {
                g.setStroke(Color.web("#80DEEA"));
                g.setLineWidth(10);
                g.strokeLine(w * 0.20, h * 0.60, w * 0.74, h * 0.14);
                g.strokeLine(w * 0.22, h * 0.14, w * 0.76, h * 0.60);
                g.setStroke(Color.web("#E0F7FA"));
                g.setLineWidth(4);
                g.strokeLine(w * 0.16, h * 0.62, w * 0.70, h * 0.16);
            }
            case GRINCHHAWK -> {
                drawVictoryPresent(g, w * 0.22, h * 0.59, w * 0.16);
                g.setStroke(Color.web("#7CB342"));
                g.setLineWidth(7);
                g.strokeArc(w * 0.16, h * 0.16, w * 0.24, h * 0.18, 70, 220, ArcType.OPEN);
            }
            case VULTURE -> {
                drawVictoryBone(g, w * 0.26, h * 0.69, w * 0.085);
                drawVictoryBone(g, w * 0.66, h * 0.71, w * 0.07);
                drawVictorySmokePuff(g, w * 0.20, h * 0.47, w * 0.07, Color.rgb(70, 58, 92, 0.42));
                drawVictorySmokePuff(g, w * 0.77, h * 0.50, w * 0.06, Color.rgb(70, 58, 92, 0.36));
            }
            case OPIUMBIRD -> {
                g.setStroke(Color.web("#CE93D8"));
                g.setLineWidth(8);
                g.strokeArc(w * 0.20, h * 0.38, w * 0.60, h * 0.24, 180, 180, ArcType.OPEN);
                drawVictorySmokePuff(g, w * 0.28, h * 0.56, w * 0.11, Color.rgb(171, 71, 188, 0.36));
                drawVictorySmokePuff(g, w * 0.46, h * 0.60, w * 0.13, Color.rgb(171, 71, 188, 0.42));
                drawVictorySmokePuff(g, w * 0.64, h * 0.56, w * 0.11, Color.rgb(171, 71, 188, 0.36));
            }
            case TITMOUSE -> {
                g.setStroke(Color.web("#FFEE58"));
                g.setLineWidth(8);
                g.strokePolyline(
                        new double[]{w * 0.18, w * 0.32, w * 0.28, w * 0.46, w * 0.40, w * 0.60},
                        new double[]{h * 0.24, h * 0.16, h * 0.38, h * 0.26, h * 0.52, h * 0.42},
                        6
                );
                drawVictorySparkle(g, w * 0.66, h * 0.22, w * 0.028, Color.web("#FFF59D"));
            }
            case BAT -> {
                g.setStroke(Color.web("#B39DDB"));
                g.setLineWidth(5);
                g.strokeArc(w * 0.20, h * 0.18, w * 0.24, h * 0.18, 40, 240, ArcType.OPEN);
                g.strokeArc(w * 0.54, h * 0.18, w * 0.24, h * 0.18, -100, 240, ArcType.OPEN);
                g.setFill(Color.rgb(255, 255, 255, 0.14));
                g.fillOval(w * 0.16, h * 0.04, w * 0.18, h * 0.18);
                g.setFill(Color.rgb(5, 8, 20, 0.92));
                g.fillOval(w * 0.21, h * 0.04, w * 0.18, h * 0.18);
            }
            case PELICAN -> {
                drawVictoryFish(g, w * 0.74, h * 0.30, w * 0.075, Color.web("#4FC3F7"), Color.web("#E1F5FE"));
                g.setStroke(Color.web("#81D4FA"));
                g.setLineWidth(6);
                g.strokeArc(w * 0.50, h * 0.26, w * 0.26, h * 0.36, 250, 120, ArcType.OPEN);
                g.strokeArc(w * 0.54, h * 0.54, w * 0.16, h * 0.13, 180, 180, ArcType.OPEN);
            }
            case HEISENBIRD -> {
                drawVictoryCrystal(g, w * 0.26, h * 0.64, w * 0.11, Color.web("#4FC3F7"));
                drawVictoryCrystal(g, w * 0.44, h * 0.68, w * 0.09, Color.web("#90CAF9"));
                drawVictoryCrystal(g, w * 0.64, h * 0.63, w * 0.1, Color.web("#29B6F6"));
                drawVictorySmokePuff(g, w * 0.66, h * 0.20, w * 0.06, Color.rgb(144, 202, 249, 0.35));
            }
            case RAVEN -> {
                for (int i = 0; i < 5; i++) {
                    double x = w * (0.22 + i * 0.12);
                    double y = h * (0.10 + Math.abs(2 - i) * 0.04);
                    g.setFill(Color.rgb(28, 31, 38, 0.78));
                    g.fillOval(x, y, w * 0.09, h * 0.17);
                }
                g.setStroke(Color.rgb(176, 190, 197, 0.45));
                g.setLineWidth(4);
                g.strokeArc(w * 0.18, h * 0.12, w * 0.64, h * 0.30, 190, 160, ArcType.OPEN);
            }
            case GOOSE -> {
                g.setStroke(Color.web("#FFF59D"));
                g.setLineWidth(7);
                g.strokeArc(w * 0.20, h * 0.34, w * 0.60, h * 0.24, 190, 160, ArcType.OPEN);
                g.setFill(Color.web("#8D6E63"));
                g.fillOval(w * 0.30, h * 0.66, w * 0.40, h * 0.11);
                g.setFill(Color.web("#FFF8E1"));
                g.fillOval(w * 0.42, h * 0.60, w * 0.08, h * 0.12);
                g.fillOval(w * 0.52, h * 0.60, w * 0.08, h * 0.12);
            }
        }

        drawVictoryCrown(g, w * 0.5, h * 0.34, Math.min(w, h) * 0.16);
    }

    private void drawVictoryCrown(GraphicsContext g, double cx, double cy, double scale) {
        double crownH = scale * 0.58;
        double[] xs = new double[]{
                cx - scale / 2, cx - scale * 0.24, cx, cx + scale * 0.24, cx + scale / 2,
                cx + scale / 2, cx - scale / 2
        };
        double[] ys = new double[]{
                cy + crownH, cy, cy + crownH * 0.34, cy, cy + crownH,
                cy + crownH * 1.22, cy + crownH * 1.22
        };
        g.setFill(Color.web("#FFD54F"));
        g.fillPolygon(xs, ys, xs.length);
        g.setStroke(Color.web("#5D4037"));
        g.setLineWidth(Math.max(2.5, scale * 0.045));
        g.strokePolygon(xs, ys, xs.length);
        drawVictorySparkle(g, cx - scale * 0.18, cy + crownH * 0.16, scale * 0.08, Color.web("#FFF8E1"));
        drawVictorySparkle(g, cx + scale * 0.18, cy + crownH * 0.16, scale * 0.08, Color.web("#FFF8E1"));
    }

    private void drawVictorySparkle(GraphicsContext g, double cx, double cy, double radius, Color color) {
        g.setStroke(color);
        g.setLineWidth(Math.max(2.0, radius * 0.22));
        g.strokeLine(cx - radius, cy, cx + radius, cy);
        g.strokeLine(cx, cy - radius, cx, cy + radius);
        g.strokeLine(cx - radius * 0.65, cy - radius * 0.65, cx + radius * 0.65, cy + radius * 0.65);
        g.strokeLine(cx - radius * 0.65, cy + radius * 0.65, cx + radius * 0.65, cy - radius * 0.65);
    }

    private void drawVictorySmokePuff(GraphicsContext g, double cx, double cy, double size, Color color) {
        g.setFill(color);
        g.fillOval(cx - size * 0.6, cy - size * 0.35, size * 0.85, size * 0.7);
        g.fillOval(cx - size * 0.15, cy - size * 0.5, size * 0.8, size * 0.72);
        g.fillOval(cx + size * 0.26, cy - size * 0.28, size * 0.72, size * 0.62);
    }

    private void drawVictoryFlower(GraphicsContext g, double cx, double cy, double scale) {
        Color[] petals = new Color[]{Color.web("#F06292"), Color.web("#FFB74D"), Color.web("#BA68C8"), Color.web("#4DD0E1"), Color.web("#81C784")};
        for (int i = 0; i < petals.length; i++) {
            double angle = Math.toRadians(i * (360.0 / petals.length));
            double px = cx + Math.cos(angle) * scale * 0.75;
            double py = cy + Math.sin(angle) * scale * 0.75;
            g.setFill(petals[i]);
            g.fillOval(px - scale * 0.34, py - scale * 0.34, scale * 0.68, scale * 0.68);
        }
        g.setFill(Color.web("#FFEE58"));
        g.fillOval(cx - scale * 0.26, cy - scale * 0.26, scale * 0.52, scale * 0.52);
        g.setStroke(Color.web("#81C784"));
        g.setLineWidth(Math.max(2.0, scale * 0.08));
        g.strokeLine(cx, cy + scale * 0.2, cx - scale * 0.45, cy + scale * 1.2);
    }

    private void drawVictoryFish(GraphicsContext g, double cx, double cy, double scale, Color body, Color fin) {
        g.setFill(body);
        g.fillOval(cx - scale * 0.7, cy - scale * 0.34, scale, scale * 0.68);
        g.fillPolygon(
                new double[]{cx + scale * 0.1, cx + scale * 0.7, cx + scale * 0.1},
                new double[]{cy, cy - scale * 0.42, cy + scale * 0.42},
                3
        );
        g.setFill(fin);
        g.fillPolygon(
                new double[]{cx - scale * 0.15, cx + scale * 0.1, cx - scale * 0.02},
                new double[]{cy - scale * 0.02, cy - scale * 0.45, cy - scale * 0.16},
                3
        );
        g.setFill(Color.WHITE);
        g.fillOval(cx - scale * 0.48, cy - scale * 0.12, scale * 0.16, scale * 0.16);
        g.setFill(Color.BLACK);
        g.fillOval(cx - scale * 0.42, cy - scale * 0.09, scale * 0.07, scale * 0.07);
    }

    private void drawVictoryPresent(GraphicsContext g, double x, double y, double size) {
        g.setFill(Color.web("#66BB6A"));
        g.fillRoundRect(x, y, size, size, 12, 12);
        g.setFill(Color.web("#F44336"));
        g.fillRect(x + size * 0.42, y, size * 0.16, size);
        g.fillRect(x, y + size * 0.42, size, size * 0.16);
        g.setStroke(Color.web("#FCE4EC"));
        g.setLineWidth(Math.max(2.5, size * 0.06));
        g.strokeArc(x + size * 0.15, y - size * 0.08, size * 0.24, size * 0.22, 0, 180, ArcType.OPEN);
        g.strokeArc(x + size * 0.6, y - size * 0.08, size * 0.24, size * 0.22, 0, 180, ArcType.OPEN);
    }

    private void drawVictoryBone(GraphicsContext g, double x, double y, double size) {
        g.setFill(Color.web("#F5F5F5"));
        g.fillOval(x - size * 0.7, y - size * 0.42, size * 0.44, size * 0.44);
        g.fillOval(x + size * 0.26, y - size * 0.42, size * 0.44, size * 0.44);
        g.fillOval(x - size * 0.7, y - size * 0.02, size * 0.44, size * 0.44);
        g.fillOval(x + size * 0.26, y - size * 0.02, size * 0.44, size * 0.44);
        g.fillRoundRect(x - size * 0.36, y - size * 0.12, size * 0.72, size * 0.24, 10, 10);
    }

    private void drawVictoryCrystal(GraphicsContext g, double cx, double cy, double scale, Color color) {
        g.setFill(color.deriveColor(0, 1.0, 1.0, 0.88));
        g.fillPolygon(
                new double[]{cx, cx + scale * 0.44, cx + scale * 0.18, cx - scale * 0.22},
                new double[]{cy - scale * 0.7, cy - scale * 0.06, cy + scale * 0.7, cy + scale * 0.18},
                4
        );
        g.setStroke(Color.WHITE.deriveColor(0, 1.0, 1.0, 0.45));
        g.setLineWidth(Math.max(2.0, scale * 0.08));
        g.strokePolygon(
                new double[]{cx, cx + scale * 0.44, cx + scale * 0.18, cx - scale * 0.22},
                new double[]{cy - scale * 0.7, cy - scale * 0.06, cy + scale * 0.7, cy + scale * 0.18},
                4
        );
    }

    private String matchSummaryBirdLabel(Bird bird) {
        if (isClassicOldOwlBird(bird)) {
            return "THE OLD OWL";
        }
        if (isClassicBlueSkyEngineConstructBird(bird)) {
            return "BLUE SKY ENGINE";
        }
        if (classicEncounter != null && classicEncounter.style == ClassicEncounterStyle.OPIUM_STILL_KING_BOSS
                && isClassicStaminaBoss(bird)) {
            return "STILL KING";
        }
        if (classicEncounter != null && classicEncounter.style == ClassicEncounterStyle.DEBT_ENGINE_BOSS
                && isClassicStaminaBoss(bird)) {
            return "DEBT ENGINE";
        }
        if (isClassicGrinchHawkConstructBird(bird)) {
            return "BELLKEEPER";
        }
        if (isClassicRazorbillConstructBird(bird)) {
            return classicEncounter.style == ClassicEncounterStyle.SEAMREAVER_BOSS
                    ? "SEAMREAVER" : "SEAM WARDEN";
        }
        if (isClassicCharlesConstructBird(bird)) {
            return classicEncounter.style == ClassicEncounterStyle.HOLLOW_MAESTRO_BOSS
                    ? "HOLLOW MAESTRO" : "CHOIR MASK";
        }
        if (bird != null && bird.classicBonusTarget) return "BONUS TARGET";
        if (bird == null || bird.type == null || bird.type.name == null) return "MYSTERY BIRD";
        return bird.type.name.toUpperCase(Locale.ROOT);
    }

    private String matchSummaryOwnerLabel(Bird bird) {
        if (bird == null) return "";
        if (bird.classicBonusTarget) return shortName(bird.name).toUpperCase(Locale.ROOT);
        int idx = bird.playerIndex;
        if (idx < 0 || idx >= MAX_COMBATANTS) return bird.name == null ? "" : bird.name.toUpperCase(Locale.ROOT);
        return (isAI[idx] ? "CPU " : "PLAYER ") + (idx + 1);
    }

    private int safeStat(int[] values, Bird bird) {
        if (values == null || bird == null) return 0;
        int idx = bird.playerIndex;
        return (idx >= 0 && idx < values.length) ? values[idx] : 0;
    }

    private String summaryPlaceText(int place) {
        int mod100 = Math.abs(place) % 100;
        int mod10 = Math.abs(place) % 10;
        String suffix = (mod100 >= 11 && mod100 <= 13) ? "TH"
                : switch (mod10) {
                    case 1 -> "ST";
                    case 2 -> "ND";
                    case 3 -> "RD";
                    default -> "TH";
                };
        return place + suffix;
    }

    private Color summaryPlaceColor(int place) {
        return switch (place) {
            case 1 -> Color.GOLD;
            case 2 -> Color.SILVER;
            case 3 -> Color.web("#CD7F32");
            default -> Color.web("#B0BEC5");
        };
    }

    private Color matchSummaryAccent(Bird bird) {
        if (isClassicBlueSkyEngineConstructBird(bird)) return Color.web("#69E6FF");
        if (isClassicDebtEngineConstructBird(bird)) return Color.web("#D6A84A");
        if (isClassicGrinchHawkConstructBird(bird)) return Color.web("#FFD166");
        if (isClassicRazorbillConstructBird(bird)) return Color.web("#00E5FF");
        if (isClassicCharlesConstructBird(bird)) return Color.web("#FFE082");
        if (bird == null || bird.type == null || bird.type.color == null) {
            return Color.web("#90A4AE");
        }
        return bird.type.color.interpolate(Color.WHITE, 0.24);
    }

    private List<Integer> getIntegers(Map<Integer, List<Bird>> teams) {
        List<Integer> ranking = new ArrayList<>(teams.keySet());
        ranking.sort(this::compareTeamPlacements);
        return ranking;
    }

    private VBox buildClassicSummaryPanel(Bird winner) {
        if (!classicModeActive || classicEncounter == null || classicRun.isEmpty()) return null;
        boolean won = didPlayerWinClassic(winner);
        boolean finalRound = classicRoundIndex >= classicRun.size() - 1;
        int livesLeft = Math.max(0, 3 - classicDeaths);
        ClassicEncounter current = classicEncounter;
        ClassicEncounter next = (won && !finalRound && classicRoundIndex + 1 < classicRun.size())
                ? classicRun.get(classicRoundIndex + 1)
                : null;
        boolean daily = dailyChallengeModeActive;
        boolean ashfallTrial = ashfallTrialModeActive && !daily;
        boolean bossRush = bossRushModeActive && !daily && !ashfallTrial;
        boolean exUnlockNext = bossRush && won && finalRound && bossRushPerfectRun && !bossRushExEncounterAdded && !isBossRushExEncounter(current);

        VBox box = new VBox(8);
        box.setAlignment(Pos.CENTER_LEFT);
        box.setPadding(new Insets(18, 26, 18, 26));
        box.setMaxWidth(1500);
        box.setStyle("-fx-background-color: rgba(0,0,0,0.55); -fx-background-radius: 22; -fx-border-color: #FFD54F; -fx-border-width: 3; -fx-border-radius: 22;");

        String headerText = daily
                ? "DAILY CHALLENGE: " + dailyChallengeRunKey + "  |  SEED " + formatDailyChallengeSeed(dailyChallengeSeed)
                : (ashfallTrial
                ? "ASHFALL TRIAL: " + classicRunCodename
                : (bossRush ? "BOSS RUSH: " + classicRunCodename : "CLASSIC RUN: " + classicRunCodename));
        Label header = getLabel(headerText);
        header.setFont(Font.font("Arial Black", 34));
        header.setTextFill(Color.web("#FFE082"));
        applyNoEllipsis(header);

        Label status = new Label(won ? "RESULT: VICTORY" : "RESULT: DEFEAT");
        status.setFont(Font.font("Arial Black", 28));
        status.setTextFill(won ? Color.LIMEGREEN : Color.ORANGE);
        applyNoEllipsis(status);

        Label progress = getLabel(daily
                ? "Round " + (classicRoundIndex + 1) + "/" + classicRun.size()
                  + "  |  Lives " + livesLeft + "/3  |  " + dailyChallengeBonusStatus(dailyChallengeRunKey)
                : ashfallTrial
                  ? "Trial " + (classicRoundIndex + 1) + "/" + classicRun.size()
                    + "  |  Lives " + livesLeft + "/3  |  Completion "
                    + (ashfallTrialCompleted ? "CLEARED" : "UNCLEARED")
                : bossRush
                  ? "Boss " + (classicRoundIndex + 1) + "/" + classicRun.size()
                    + "  |  Repair Stocks " + livesLeft + "/3  |  Perfect Route "
                    + (bossRushPerfectRun ? "LIVE" : "BROKEN")
                  : "Round " + (classicRoundIndex + 1) + "/" + classicRun.size()
                    + "  |  Difficulty " + String.format(Locale.US, "%.1f", classicDifficulty)
                    + "  |  Bird Coins " + birdCoinBalanceText());
        progress.setFont(Font.font("Consolas", 22));
        progress.setTextFill(Color.web("#B3E5FC"));
        progress.setWrapText(true);
        progress.setMaxWidth(1450);
        applyNoEllipsis(progress);

        Label currentLine = new Label("Current: " + current.name + "  |  " + encounterMapDisplayName(current)
                + "  |  " + current.mutator.label + "  |  " + current.twist.label);
        currentLine.setFont(Font.font("Consolas", 22));
        currentLine.setTextFill(Color.web("#E3F2FD"));
        currentLine.setWrapText(true);
        currentLine.setMaxWidth(1450);
        applyNoEllipsis(currentLine);

        box.getChildren().addAll(header, status, progress, currentLine);

        if (next != null) {
            Label nextLine = new Label("Next: " + next.name + "  |  " + encounterMapDisplayName(next)
                    + "  |  " + next.mutator.label + "  |  " + next.twist.label);
            nextLine.setFont(Font.font("Consolas", 21));
            nextLine.setTextFill(Color.web("#C5E1A5"));
            nextLine.setWrapText(true);
            nextLine.setMaxWidth(1450);
            applyNoEllipsis(nextLine);
            box.getChildren().add(nextLine);
        } else if (won && finalRound) {
            Label nextLine = getLabel(daily
                    ? "Next: RETURN TO DAILY BOARD"
                    : (ashfallTrial
                       ? "Next: CLAIM TRIAL REWARD"
                    : (bossRush
                       ? (exUnlockNext ? "Next: UNLOCK EX ROUND" : "Next: CLAIM RANK")
                       : "Next: CLAIM REWARD")));
            nextLine.setFont(Font.font("Consolas", 21));
            nextLine.setTextFill(Color.web("#C8E6C9"));
            applyNoEllipsis(nextLine);
            box.getChildren().add(nextLine);
        } else if (!won) {
            Label nextLine = getLabel(livesLeft > 0
                    ? (ashfallTrial ? "Next: RETRY TRIAL" : (bossRush ? "Next: RETRY BOSS" : "Next: RETRY ENCOUNTER"))
                    : (daily ? "Next: DAILY RUN FAILED" : (ashfallTrial ? "Next: ASHFALL TRIAL FAILED" : (bossRush ? "Next: BOSS RUSH FAILED" : "Next: RUN FAILED"))));
            nextLine.setFont(Font.font("Consolas", 21));
            nextLine.setTextFill(Color.web("#FFCCBC"));
            applyNoEllipsis(nextLine);
            box.getChildren().add(nextLine);
        }
        return box;
    }

    private List<GameplayTelemetry.MoveSnapshot> postMatchTelemetryMoveRows(int limit) {
        List<GameplayTelemetry.MoveSnapshot> rows = new ArrayList<>();
        for (GameplayTelemetry.MoveSnapshot row : gameplayTelemetry.currentMatchTopMoves(24)) {
            if (row == null || isSyntheticTelemetryMove(row.moveName())) continue;
            if (row.damage() <= 0 && row.kos() <= 0 && row.selfKos() <= 0 && row.recoveryFailures() <= 0) continue;
            rows.add(row);
            if (rows.size() >= limit) break;
        }
        return rows;
    }

    private String postMatchMoveName(GameplayTelemetry.MoveSnapshot row) {
        String move = row.moveName();
        String bird = row.birdName();
        if (move == null || move.isBlank()) {
            return bird == null || bird.isBlank() ? "Unknown Move" : bird;
        }
        if (bird == null || bird.isBlank()) {
            return move;
        }
        return move.toLowerCase(Locale.ROOT).contains(bird.toLowerCase(Locale.ROOT))
                ? move
                : bird + " " + move;
    }

    private boolean isSyntheticTelemetryMove(String moveName) {
        return GameplayTelemetry.MATCH_SURVIVAL_MOVE.equals(moveName)
                || GameplayTelemetry.RECOVERY_FAILURE_MOVE.equals(moveName);
    }

    private Label getLabel(String daily) {
        return new Label(daily);
    }

    private Button button(String text, String color) {
        return button(text, color, 520);
    }

    private Button button(String text, String color, double width) {
        Button b = uiFactory.action(text, width, 120, 40, color, 36, null);
        b.setPrefWidth(width);
        b.setMinWidth(width);
        b.setMaxWidth(width);
        b.setAccessibleText(text);
        b.setText("");
        b.setGraphic(buildSummaryButtonGraphic(text, width));
        b.setContentDisplay(ContentDisplay.GRAPHIC_ONLY);
        b.setWrapText(false);
        return b;
    }

    private Node buildSummaryButtonGraphic(String text, double width) {
        Label label = new Label(text);
        label.setFont(Font.font("Arial Black", 36));
        label.setTextFill(Color.WHITE);
        label.setWrapText(false);
        label.setAlignment(Pos.CENTER);
        label.setTextAlignment(TextAlignment.CENTER);
        label.setMouseTransparent(true);
        applyNoEllipsis(label);
        fitLabelSingleLine(label, 36, 20, Math.max(180, width - 76));

        StackPane content = new StackPane(label);
        content.setAlignment(Pos.CENTER);
        lockRegionWidth(content, Math.max(200, width - 36));
        content.setMouseTransparent(true);
        return content;
    }

    private HBox buildSummaryButtons(Stage stage, Bird winner) {
        HBox buttons = new HBox(44);
        buttons.setAlignment(Pos.CENTER);
        if (lanModeActive) {
            if (lanIsHost) {
                Button backLobby = button("BACK TO LOBBY", "#00C853");
                Button exit = button("EXIT TO HUB", "#D32F2F");
                backLobby.setOnAction(e -> requestLanResultsAction(
                        LAN_RESULTS_ACTION_LOBBY, stage, backLobby, exit));
                exit.setOnAction(e -> confirmLeaveLanSession(stage,
                        () -> requestLanResultsAction(LAN_RESULTS_ACTION_EXIT, stage, backLobby, exit)));
                backLobby.setDisable(true);
                exit.setDisable(true);
                PauseTransition unlock = new PauseTransition(Duration.millis(LAN_RESULTS_MIN_SHOW_MS));
                unlock.setOnFinished(e -> {
                    backLobby.setDisable(false);
                    exit.setDisable(false);
                    backLobby.requestFocus();
                });
                unlock.play();
                buttons.getChildren().addAll(backLobby, exit);
            } else {
                Label waiting = cinematicResultsLabel(
                        "WAITING FOR HOST TO CONTINUE...", 26, Color.web("#B8C7E8"), true);
                lanResultsStatusLabel = waiting;
                buttons.getChildren().add(waiting);
            }
        } else if (dailyChallengeModeActive && classicModeActive) {
            boolean wonRound = didPlayerWinClassic(winner);
            boolean finalRound = classicRoundIndex >= classicRun.size() - 1;
            String advanceText = wonRound
                    ? (finalRound ? "CLAIM DAILY RESULT" : "NEXT ENCOUNTER")
                    : "RETRY ENCOUNTER";

            Button continueDaily = button(advanceText, "#1565C0");
            continueDaily.setOnAction(e -> {
                resetMatchStats();
                handleDailyChallengeMatchEnd(stage, winner);
            });

            Button restartDaily = button("RESTART TODAY'S RUN", "#00897B");
            restartDaily.setOnAction(e -> {
                resetMatchStats();
                showDailyChallengeSetup(stage);
            });

            Button menu = button("BACK TO HUB", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showMenu(stage);
            });
            buttons.getChildren().addAll(continueDaily, restartDaily, menu);
        } else if (ashfallTrialModeActive && classicModeActive) {
            boolean wonRound = didPlayerWinClassic(winner);
            boolean finalRound = classicRoundIndex >= classicRun.size() - 1;
            String advanceText = wonRound
                    ? (finalRound ? "CLAIM TRIAL" : "NEXT TRIAL")
                    : "RETRY TRIAL";

            Button continueTrial = button(advanceText, "#E65100");
            continueTrial.setOnAction(e -> {
                resetMatchStats();
                handleAshfallTrialMatchEnd(stage, winner);
            });

            Button restartTrial = button("RESTART TRIAL", "#00897B");
            restartTrial.setOnAction(e -> {
                resetMatchStats();
                showAshfallTrialBriefing(stage);
            });

            Button menu = button("BACK TO MODES", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showClassicMoreMenu(stage);
            });
            buttons.getChildren().addAll(continueTrial, restartTrial, menu);
        } else if (bossRushModeActive && classicModeActive) {
            boolean wonRound = didPlayerWinClassic(winner);
            boolean finalRound = classicRoundIndex >= classicRun.size() - 1;
            boolean exUnlockNext = wonRound && finalRound && bossRushPerfectRun && !bossRushExEncounterAdded && !isBossRushExEncounter(classicEncounter);
            String advanceText = wonRound
                    ? (finalRound ? (exUnlockNext ? "UNLOCK EX ROUND" : "CLAIM RANK") : "NEXT BOSS")
                    : "RETRY BOSS";

            Button continueRush = button(advanceText, "#1565C0");
            continueRush.setOnAction(e -> {
                resetMatchStats();
                handleBossRushMatchEnd(stage, winner);
            });

            Button restartRush = button("RESTART BOSS RUSH", "#00897B");
            restartRush.setOnAction(e -> {
                resetMatchStats();
                showClassicRunBriefing(stage, classicSelectedBird);
            });

            Button menu = button("BACK TO MODES", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showClassicMoreMenu(stage);
            });
            buttons.getChildren().addAll(continueRush, restartRush, menu);
        } else if (classicModeActive) {
            boolean wonRound = didPlayerWinClassic(winner);
            boolean finalRound = classicRoundIndex >= classicRun.size() - 1;
            String advanceText = wonRound
                    ? (finalRound ? "CLAIM REWARD" : "NEXT ENCOUNTER")
                    : "RETRY ENCOUNTER";

            Button continueClassic = button(advanceText, "#1565C0");
            continueClassic.setOnAction(e -> {
                resetMatchStats();
                handleClassicMatchEnd(stage, winner);
            });

            Button restartRun = button("RESTART RUN", "#00897B");
            restartRun.setOnAction(e -> {
                resetMatchStats();
                showClassicRunBriefing(stage, classicSelectedBird);
            });

            Button menu = button("BACK TO HUB", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showMenu(stage);
            });
            buttons.getChildren().addAll(continueClassic, restartRun, menu);
        } else if (campaignModeActive) {
            double campaignButtonWidth = campaignMissionWon ? 520 : 400;
            Button continueCampaign = button(
                    campaignMissionWon ? "CONTINUE STORY" : "RETRY CHECKPOINT",
                    "#1565C0",
                    campaignButtonWidth
            );
            continueCampaign.setOnAction(e -> {
                resetMatchStats();
                handleCampaignMatchEnd(stage);
            });
            Button retryMission = button("RESTART MISSION", "#00897B", campaignButtonWidth);
            retryMission.setOnAction(e -> {
                resetMatchStats();
                campaignRetryPhaseIndex = 0;
                startCampaignMission(stage, currentCampaignMission);
            });
            Button hub = button("STORY HUB", "#6A1B9A", campaignButtonWidth);
            hub.setOnAction(e -> {
                resetMatchStats();
                showCampaignHub(stage);
            });
            if (!campaignMissionWon) {
                Button difficulty = button("CHANGE DIFFICULTY", "#EF6C00", campaignButtonWidth);
                difficulty.setOnAction(e -> {
                    StoryCampaign.Difficulty[] values = StoryCampaign.Difficulty.values();
                    stillSkyProgress.difficulty =
                            values[(stillSkyProgress.difficulty.ordinal() + 1) % values.length];
                    saveAchievements();
                    resetMatchStats();
                    startCampaignMission(stage, currentCampaignMission);
                });
                buttons.getChildren().addAll(continueCampaign, difficulty, retryMission, hub);
            } else {
                buttons.getChildren().addAll(continueCampaign, retryMission, hub);
            }
        } else if (storyModeActive) {
            Button continueStory = button("CONTINUE EPISODE", "#1565C0");
            continueStory.setOnAction(e -> {
                resetMatchStats();
                handleStoryMatchEnd(stage, winner);
            });
            Button menu = button("LEGACY STORIES", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showLegacyStories(stage);
            });
            buttons.getChildren().addAll(continueStory, menu);
        } else if (adventureModeActive) {
            Button continueAdventure = button("CONTINUE ADVENTURE", "#1565C0", 560);
            continueAdventure.setOnAction(e -> {
                resetMatchStats();
                handleAdventureMatchEnd(stage, winner);
            });
            Button hub = button("ADVENTURE HUB", "#00897B");
            hub.setOnAction(e -> {
                resetMatchStats();
                showAdventureHub(stage);
            });
            Button menu = button("LEGACY STORIES", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showLegacyStories(stage);
            });
            buttons.getChildren().addAll(continueAdventure, hub, menu);
        } else if (tournamentModeActive) {
            Button bracket = button("VIEW BRACKET", "#1565C0");
            bracket.setOnAction(e -> {
                resetMatchStats();
                showTournamentBracket(stage);
            });
            Button exit = button("EXIT TO HUB", "#9C27B0");
            exit.setOnAction(e -> {
                resetMatchStats();
                resetTournamentRun();
                showMenu(stage);
            });
            buttons.getChildren().addAll(bracket, exit);
        } else {
            Button rematch = button("REMATCH", "#FF1744");
            rematch.setOnAction(e -> {
                resetMatchStats();
                competitionSeriesActive = false;
                Arrays.fill(competitionRoundWins, 0);
                Arrays.fill(competitionTeamWins, 0);
                competitionRoundNumber = 1;
                startMatch(stage);
            });
            Button menu = button("BACK TO HUB", "#D32F2F");
            menu.setOnAction(e -> {
                resetMatchStats();
                showMenu(stage);
            });
            if (lastMatchReplay != null) {
                Button watchReplay = button("WATCH REPLAY", "#1565C0");
                watchReplay.setOnAction(e -> {
                    resetMatchStats();
                    startReplayPlayback(stage);
                });
                buttons.getChildren().addAll(rematch, watchReplay, menu);
            } else {
                buttons.getChildren().addAll(rematch, menu);
            }
        }
        return buttons;
    }

