    private void applyAdaptiveBalance(Bird bird) {
        if (bird == null) return;
        // Replays apply the multipliers recorded at match time; live adaptive
        // balance drifts as win/loss stats change, which would desync playback.
        if (replayPlaybackActive && activeReplay != null && activeReplay.slotBaseSize != null) {
            int idx = bird.playerIndex;
            if (idx >= 0 && idx < activeReplay.slotBaseSize.length && activeReplay.slotBirdTypes[idx] != null) {
                bird.setBaseMultipliers(activeReplay.slotBaseSize[idx],
                        activeReplay.slotBasePower[idx], activeReplay.slotBaseSpeed[idx]);
            }
            return;
        }
        if (!ADAPTIVE_BALANCE_ENABLED) return;
        if (bird.isNullRockForm()) return;

        int idx = bird.type.ordinal();
        int picks = typePicks[idx];
        if (picks < BALANCE_MIN_SAMPLE) return;

        double winRate = typeWins[idx] / (double) picks;
        double powerScale = 1.0;
        double speedScale = 1.0;

        if (winRate >= BALANCE_HIGH_WINRATE) {
            powerScale = winRate >= 0.70 ? 0.90 : 0.94;
            speedScale = winRate >= 0.70 ? 0.95 : 0.97;
        } else if (winRate <= BALANCE_LOW_WINRATE) {
            powerScale = winRate <= 0.30 ? 1.10 : 1.06;
            speedScale = winRate <= 0.30 ? 1.05 : 1.03;
        }

        bird.setBaseMultipliers(
                bird.baseSizeMultiplier,
                bird.basePowerMultiplier * powerScale,
                bird.baseSpeedMultiplier * speedScale
        );
    }

    void recordBalanceOutcome(Bird winner) {
        if (balanceOutcomeRecorded) return;
        balanceOutcomeRecorded = true;

        recordTelemetryMatchSurvival();

        if (campaignModeActive || storyModeActive || adventureModeActive || trainingModeActive) return;

        for (int i = 0; i < activePlayers; i++) {
            Bird b = players[i];
            if (b == null) continue;
            int typeIdx = b.type.ordinal();
            typePicks[typeIdx]++;
            typeDamage[typeIdx] += Math.max(0, damageDealt[i]);
            typeElims[typeIdx] += Math.max(0, eliminations[i]);
        }
        if (winner != null) {
            typeWins[winner.type.ordinal()]++;
        }
    }

    private void recordTelemetryMatchSurvival() {
        int elapsedFrames = matchStartNano > 0L
                ? (int) Math.max(0L, (System.nanoTime() - matchStartNano) / 16_666_666L)
                : Math.max(0, MATCH_DURATION_FRAMES - matchTimer);
        String mode = currentMatchHistoryMode();
        for (int i = 0; i < activePlayers; i++) {
            Bird b = players[i];
            if (b == null) continue;
            gameplayTelemetry.recordSurvival(b.type, isTelemetryCpu(i), mode, selectedMap, elapsedFrames);
        }
    }

