    private void loadAchievements() {
        profileProgressLoaded = false;
        Preferences prefs = saveRepository.globalPrefs();
        Preferences profilePrefs = saveRepository.activeProfilePrefs();
        loadGlobalSettings(prefs);
        loadProfileProgress(profilePrefs);
        profileProgressLoaded = true;
    }

    private void loadGlobalSettings(Preferences prefs) {
        applyGlobalSettingsState(BirdGame3GlobalSettingsState.load(
                prefs,
                CONTROL_ACTION_PREF_KEYS,
                playerKeyBindings.length
        ));
    }

    private void loadProfileProgress(Preferences prefs) {
        birdCoinLedger.load(prefs);
        applyProfileProgressState(BirdGame3ProfileProgressState.load(prefs, profileProgressSchema()));
    }

    void requestProgressSave() {
        saveAchievements();
    }

    private void saveAchievements() {
        if (!javafx.application.Platform.isFxApplicationThread()) {
            persistAchievements(false);
            return;
        }
        achievementSaveQueued = true;
        if (achievementSaveDebounce == null) {
            achievementSaveDebounce = new PauseTransition(ACHIEVEMENT_SAVE_DEBOUNCE);
            achievementSaveDebounce.setOnFinished(event -> flushQueuedAchievementSave());
        }
        achievementSaveDebounce.playFromStart();
    }

    private void flushQueuedAchievementSave() {
        if (!achievementSaveQueued) {
            return;
        }
        achievementSaveQueued = false;
        persistAchievements(false);
    }

    private void flushAchievementsNow() {
        if (achievementSaveDebounce != null) {
            achievementSaveDebounce.stop();
        }
        achievementSaveQueued = false;
        persistAchievements(true);
    }

    private void persistAchievements(boolean flush) {
        if (!profileProgressLoaded) {
            return;
        }
        Preferences prefs = saveRepository.globalPrefs();
        Preferences profilePrefs = saveRepository.activeProfilePrefs();
        saveRepository.touchActiveProfile();
        persistAchievements(prefs, profilePrefs, flush);
    }

    void persistAchievements(Preferences prefs) {
        persistAchievements(prefs, prefs, false);
    }

    private void persistAchievements(Preferences globalPrefs, Preferences profilePrefs, boolean flush) {
        saveGlobalSettings(globalPrefs);
        saveProfileProgress(profilePrefs);
        if (!flush) {
            return;
        }
        flushPreferences(globalPrefs);
        if (!samePreferences(globalPrefs, profilePrefs)) {
            Preferences profileRoot = profilePrefs.parent();
            flushPreferences(profileRoot == null ? profilePrefs : profileRoot);
        }
    }

    private void saveGlobalSettings(Preferences prefs) {
        captureGlobalSettingsState().saveTo(prefs, CONTROL_ACTION_PREF_KEYS);
    }

    private void saveProfileProgress(Preferences prefs) {
        birdCoinLedger.save(prefs);
        captureProfileProgressState().saveTo(prefs, profileProgressSchema());
    }

