    private boolean shouldShowAchievementRewardOwnedOverlay(int index) {
        ShopPreview preview = achievementRewardPreview(index);
        return isShopPreviewOwned(preview);
    }

    private StackPane wrapOwnedAchievementRewardTile(Node baseIcon) {
        StackPane wrapper = new StackPane(baseIcon);
        wrapper.setPickOnBounds(false);

        Label owned = new Label("OWNED");
        owned.setFont(Font.font("Arial Black", 13));
        owned.setTextFill(Color.WHITE);
        owned.setPadding(new Insets(3, 10, 3, 10));
        owned.setRotate(-10);
        owned.setMouseTransparent(true);
        owned.setStyle("-fx-background-color: rgba(18, 80, 28, 0.92);"
                + " -fx-border-color: rgba(214, 255, 220, 0.95);"
                + " -fx-border-width: 1.5;"
                + " -fx-background-radius: 12;"
                + " -fx-border-radius: 12;");
        StackPane.setAlignment(owned, Pos.TOP_RIGHT);
        StackPane.setMargin(owned, new Insets(8, 8, 0, 0));
        wrapper.getChildren().add(owned);
        return wrapper;
    }

    private Node buildAchievementRewardTileIcon(int index) {
        AchievementReward reward = achievementRewardFor(index);
        if (reward == null) {
            return buildLockedTileIcon(Color.web("#607D8B"));
        }
        if (reward.isCoins()) {
            return buildCoinTileIcon();
        }
        if (reward.isContinue()) {
            return buildContinueTileIcon();
        }
        ShopPreview preview = achievementRewardPreview(index);
        if (preview == null) {
            return buildLockedTileIcon(Color.web("#607D8B"));
        }
        Node baseIcon;
        if (isShopPreviewMap(preview)) {
            MapType map = mapTypeForPreview(preview);
            baseIcon = map != null ? buildMapTileIcon(map) : buildLockedTileIcon(achievementAccentColor(index));
            return shouldShowAchievementRewardOwnedOverlay(index) ? wrapOwnedAchievementRewardTile(baseIcon) : baseIcon;
        }
        if (preview.type() != null) {
            String skinKey = isShopPreviewCharacter(preview) ? null : preview.skinKey();
            baseIcon = buildBirdTileIcon(preview.type(), skinKey, originMapForBird(preview.type()));
            return shouldShowAchievementRewardOwnedOverlay(index) ? wrapOwnedAchievementRewardTile(baseIcon) : baseIcon;
        }
        return buildLockedTileIcon(achievementAccentColor(index));
    }

    private StackPane achievementTabButton(Stage stage, BirdGame3AchievementCategory current, BirdGame3AchievementCategory tab) {
        int claimable = countClaimableAchievementRewards(tab);
        boolean selected = current == tab;
        Button button = uiFactory.action(tab.label.toUpperCase(Locale.ROOT), 230, 78, 24,
                selected ? "#FFD54F" : "#37474F",
                18,
                () -> showAchievements(stage, tab));
        button.setStyle(MenuTheme.buttonStyle(selected ? "#FFD54F" : "#37474F", 18, selected ? "#111111" : "white"));
        StackPane wrapper = new StackPane(button);
        wrapper.setPickOnBounds(false);
        if (claimable > 0) {
            StackPane badge = buildAchievementAlertBadge();
            StackPane.setAlignment(badge, Pos.TOP_RIGHT);
            StackPane.setMargin(badge, new Insets(-6, -8, 0, 0));
            wrapper.getChildren().add(badge);
        }
        return wrapper;
    }

    private StackPane buildAchievementCard(Stage stage, int index, BirdGame3AchievementCategory currentCategory) {
        boolean unlocked = isAchievementUnlocked(index);
        boolean claimable = isAchievementRewardClaimable(index);
        boolean claimed = unlocked && isAchievementRewardClaimed(index);
        Color accent = achievementAccentColor(index);
        String border = claimable ? "#FFE082" : (unlocked ? "#66BB6A" : toHex(accent));

        VBox cardContent = new VBox(12);
        cardContent.setPadding(new Insets(20, 22, 20, 22));
        cardContent.setMaxWidth(1500);
        cardContent.setStyle(MenuTheme.panelStyle(border, 20));

        Canvas icon = buildAchievementIcon(index, 92);

        Label nameLabel = new Label(achievementForIndex(index).displayName.toUpperCase(Locale.ROOT));
        nameLabel.setFont(Font.font("Impact", 36));
        nameLabel.setTextFill(unlocked ? Color.web("#F1F8E9") : Color.WHITE);

        String statusText = claimable ? "COMPLETED - REWARD READY"
                : claimed ? "COMPLETED - REWARD CLAIMED"
                : unlocked ? "COMPLETED"
                : "LOCKED";
        Label statusLabel = getLabel(statusText);
        statusLabel.setFont(Font.font("Consolas", 18));
        statusLabel.setTextFill(claimable ? Color.web("#FFF59D")
                : claimed ? Color.web("#B9F6CA")
                : unlocked ? Color.web("#C8E6C9")
                : Color.web("#90A4AE"));

        HBox header = new HBox(14, nameLabel, statusLabel);
        header.setAlignment(Pos.CENTER_LEFT);

        Label descLabel = getLabel(sanitizeAchievementText(achievementForIndex(index).description));
        descLabel.setFont(Font.font("Consolas", 20));
        descLabel.setTextFill(unlocked ? Color.web("#E8F5E9") : Color.web("#B0BEC5"));
        descLabel.setWrapText(true);
        descLabel.setMaxWidth(900);

        Label progressLabel = getLabel(achievementProgressText(index));
        progressLabel.setFont(Font.font("Consolas", 18));
        progressLabel.setTextFill(unlocked ? Color.web("#A5D6A7") : Color.web("#90CAF9"));
        progressLabel.setWrapText(true);
        progressLabel.setMaxWidth(900);

        VBox textBox = new VBox(8, header, descLabel, progressLabel);
        textBox.setAlignment(Pos.CENTER_LEFT);
        HBox.setHgrow(textBox, Priority.ALWAYS);

        VBox rewardBox = new VBox(8);
        rewardBox.setAlignment(Pos.CENTER_LEFT);
        rewardBox.setPrefWidth(360);
        rewardBox.setMaxWidth(360);
        rewardBox.setPadding(new Insets(12));
        rewardBox.setStyle(MenuTheme.insetPanelStyle(border, 18));

        Label rewardHeader = getLabel("REWARD");
        rewardHeader.setFont(Font.font("Consolas", FontWeight.BOLD, 18));
        rewardHeader.setTextFill(accent.brighter());

        Label rewardLabel = new Label(achievementRewardLabel(index));
        rewardLabel.setFont(Font.font("Arial Black", 22));
        rewardLabel.setTextFill(Color.web("#FFF8E1"));
        rewardLabel.setWrapText(true);
        rewardLabel.setMaxWidth(300);

        Label rewardDetail = getLabel(achievementRewardDetail(index));
        rewardDetail.setFont(Font.font("Consolas", 16));
        rewardDetail.setTextFill(Color.web("#CFD8DC"));
        rewardDetail.setWrapText(true);
        rewardDetail.setMaxWidth(300);

        Node rewardIcon = buildAchievementRewardTileIcon(index);

        rewardBox.getChildren().addAll(rewardHeader, rewardIcon, rewardLabel, rewardDetail);

        if (claimable) {
            Button claimButton = uiFactory.action("CLAIM REWARD", 250, 74, 24, "#2E7D32", 18,
                    () -> claimAchievementReward(index, stage, currentCategory));
            rewardBox.getChildren().add(claimButton);
        } else {
            Label rewardState = getLabel(claimed ? "Already claimed" : (unlocked ? "Reward ready next visit" : "Unlock this achievement to claim"));
            rewardState.setFont(Font.font("Consolas", 16));
            rewardState.setTextFill(claimed ? Color.web("#A5D6A7") : Color.web("#90A4AE"));
            rewardState.setWrapText(true);
            rewardState.setMaxWidth(300);
            rewardBox.getChildren().add(rewardState);
        }

        HBox row = new HBox(22, icon, textBox, rewardBox);
        row.setAlignment(Pos.CENTER_LEFT);
        cardContent.getChildren().add(row);

        StackPane card = new StackPane(cardContent);
        card.setMaxWidth(1500);
        if (unlocked) {
            Label completedStamp = new Label("COMPLETED");
            completedStamp.setMouseTransparent(true);
            completedStamp.setFont(Font.font("Arial Black", FontWeight.BOLD, 76));
            completedStamp.setTextFill(Color.rgb(232, 245, 233, 0.16));
            completedStamp.setRotate(-13);
            StackPane.setAlignment(completedStamp, Pos.CENTER);
            card.getChildren().add(completedStamp);
        }
        return card;
    }

    private StackPane buildAchievementAlertBadge() {
        Circle badge = new Circle(10, Color.web("#FF5252"));
        badge.setStroke(Color.web("#FFF8E1"));
        badge.setStrokeWidth(2);

        Text mark = new Text("!");
        mark.setFont(Font.font("Arial Black", FontWeight.BOLD, 14));
        mark.setFill(Color.WHITE);

        StackPane badgePane = new StackPane(badge, mark);
        badgePane.setMouseTransparent(true);
        badgePane.setPrefSize(22, 22);
        badgePane.setMinSize(22, 22);
        badgePane.setMaxSize(22, 22);
        return badgePane;
    }

    private void showAchievements(Stage stage) {
        showAchievements(stage, preferredAchievementCategory());
    }

    private void showAchievements(Stage stage, BirdGame3AchievementCategory category) {
        playMenuMusic();

        BorderPane root = new BorderPane();
        root.setPadding(new Insets(28, 36, 28, 36));
        root.setStyle(MenuTheme.pageBackground());

        Button back = uiFactory.action("BACK TO HUB", 320, 84, 30, "#D32F2F", 22, () -> showMenu(stage));
        StackPane title = buildMenuTitleBanner("ACHIEVEMENTS", 620, 74, 34);

        int unlockedCount = achievementProfile.unlockedCount();
        int claimableCount = 0;
        for (int i = 0; i < ACHIEVEMENT_COUNT; i++) {
            if (isAchievementRewardClaimable(i)) {
                claimableCount++;
            }
        }

        Label subtitle = new Label("Unlock challenges, claim rewards, and convert duplicate cosmetic rewards into Bird Coins.");
        subtitle.setFont(Font.font("Consolas", 20));
        subtitle.setTextFill(Color.web("#CFD8DC"));
        subtitle.setWrapText(true);
        subtitle.setMaxWidth(1180);
        applyNoEllipsis(subtitle);

        Label summary = new Label("UNLOCKED " + unlockedCount + " / " + ACHIEVEMENT_COUNT
                + "   |   CLAIMABLE REWARDS " + claimableCount);
        summary.setFont(Font.font("Consolas", 22));
        summary.setTextFill(claimableCount > 0 ? Color.web("#FFF59D") : Color.web("#80DEEA"));
        applyNoEllipsis(summary);

        StackPane summaryChip = buildMenuChip(
                claimableCount > 0 ? "REWARDS READY  " + claimableCount : "UNLOCKED  " + unlockedCount,
                claimableCount > 0 ? "#FFE082" : "#80DEEA",
                "#FFF8E1"
        );
        StackPane header = buildMenuTopStrip(back, title, summaryChip);

        HBox tabs = new HBox(14);
        tabs.setAlignment(Pos.CENTER);
        for (BirdGame3AchievementCategory tab : BirdGame3AchievementCategory.values()) {
            tabs.getChildren().add(achievementTabButton(stage, category, tab));
        }
        StackPane tabsShell = new StackPane(tabs);
        tabsShell.setPadding(new Insets(16, 18, 16, 18));
        tabsShell.setStyle(MenuTheme.panelStyle("#607D8B", 24));

        VBox list = new VBox(18);
        list.setAlignment(Pos.TOP_CENTER);
        for (int index : achievementDisplayOrder(category)) {
            list.getChildren().add(buildAchievementCard(stage, index, category));
        }

        ScrollPane scroll = new ScrollPane(list);
        scroll.setFitToWidth(true);
        scroll.setStyle("-fx-background: transparent; -fx-background-color: transparent;");
        scroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
        StackPane listShell = new StackPane(scroll);
        listShell.setPadding(new Insets(14));
        listShell.setStyle(MenuTheme.panelStyle("#64B5F6", 28));

        VBox infoBox = new VBox(6, subtitle, summary);
        infoBox.setAlignment(Pos.CENTER_LEFT);
        infoBox.setPadding(new Insets(14, 18, 14, 18));
        infoBox.setStyle(MenuTheme.insetPanelStyle("#80DEEA", 22));

        VBox top = new VBox(16, header, infoBox, tabsShell);
        root.setTop(top);
        root.setCenter(listShell);

        Scene scene = new Scene(root, WIDTH, HEIGHT);
        bindEscape(scene, back);
        setupKeyboardNavigation(scene);
        applyConsoleHighlight(scene);
        root.setStyle(root.getStyle() + ";-fx-focus-color:transparent;-fx-faint-focus-color:transparent;");
        setScenePreservingFullscreen(stage, scene);
        back.requestFocus();
    }

    private String sanitizeAchievementText(String text) {
        if (text == null) return "";
        String cleaned = text;
        // Normalize common punctuation and encoding noise.
        cleaned = cleaned
                .replace("–", " - ")
                .replace("—", " - ")
                .replace("―", " - ")
                .replace("−", "-")
                .replace("“", "\"")
                .replace("”", "\"")
                .replace("‘", "'")
                .replace("’", "'")
                .replace("•", "-")
                .replace("✓", "")
                .replace("\uFFFD", "");
        // Common UTF-8 -> CP1252 mojibake sequences.
        cleaned = cleaned
                .replace("Ã¢â‚¬â€œ", " - ")
                .replace("Ã¢â‚¬â€”", " - ")
                .replace("Ã¢â€\u009D", "\"")
                .replace("Ã¢â€œ", "\"")
                .replace("Ã¢Å“â€œ", "")
                .replace("Ã¢â€\u0090", "-");
        return cleaned;
    }

    private Node buildPauseSpecialMoveGuide() {
        int count = Math.min(activePlayers, players.length);
        FlowPane cards = new FlowPane(12, 10);
        cards.setAlignment(Pos.CENTER);
        cards.setPrefWrapLength(1320);

        for (int i = 0; i < count; i++) {
            Bird bird = players[i];
            if (bird == null || bird.type == null) {
                continue;
            }
            cards.getChildren().add(buildPauseSpecialMoveGuideCard(i, bird));
        }

        if (cards.getChildren().isEmpty()) {
            return null;
        }

        Label title = new Label("SPECIAL MOVE GUIDE");
        title.setFont(Font.font("Arial Black", 22));
        title.setTextFill(Color.web("#FFF59D"));
        title.setAlignment(Pos.CENTER);
        title.setMaxWidth(Double.MAX_VALUE);
        applyNoEllipsis(title);

        Label hint = new Label("Press Special alone, with left/right, with up/jump, or with down/block.");
        hint.setFont(Font.font("Consolas", 16));
        hint.setTextFill(Color.web("#CFD8DC"));
        hint.setAlignment(Pos.CENTER);
        hint.setTextAlignment(TextAlignment.CENTER);
        hint.setMaxWidth(Double.MAX_VALUE);
        applyNoEllipsis(hint);

        VBox guide = new VBox(8, title, hint, cards);
        guide.setAlignment(Pos.CENTER);
        guide.setMaxWidth(1360);
        guide.setPadding(new Insets(14, 18, 16, 18));
        guide.setStyle("-fx-background-color: rgba(7, 12, 18, 0.88); -fx-background-radius: 18; "
                + "-fx-border-color: rgba(255, 245, 157, 0.34); -fx-border-width: 2; "
                + "-fx-border-radius: 18;");
        return guide;
    }

    private Node buildPauseSpecialMoveGuideCard(int playerIdx, Bird bird) {
        Color accent = switch (playerIdx) {
            case 0 -> Color.web("#F44336");
            case 1 -> Color.web("#42A5F5");
            case 2 -> Color.web("#FDD835");
            default -> Color.web("#66BB6A");
        };
        String accentHex = toHex(accent);
        String[][] moves = specialMoveGuideRows(bird.type);
        double cardWidth = activePlayers >= 4 ? 306.0 : 330.0;

        Label header = new Label("P" + (playerIdx + 1) + "  " + shortName(bird.name).toUpperCase(Locale.ROOT));
        header.setFont(Font.font("Arial Black", activePlayers >= 4 ? 15 : 17));
        header.setTextFill(playerIdx == 2 ? Color.web("#111111") : Color.WHITE);
        header.setAlignment(Pos.CENTER);
        header.setTextAlignment(TextAlignment.CENTER);
        header.setMaxWidth(Double.MAX_VALUE);
        StackPane headerBar = new StackPane(header);
        headerBar.setPadding(new Insets(6, 10, 7, 10));
        headerBar.setStyle("-fx-background-color: " + accentHex + "; -fx-background-radius: 12;");

        GridPane moveGrid = new GridPane();
        moveGrid.setHgap(8);
        moveGrid.setVgap(6);
        moveGrid.setAlignment(Pos.CENTER);
        ColumnConstraints inputCol = new ColumnConstraints(74);
        inputCol.setMinWidth(74);
        inputCol.setMaxWidth(74);
        ColumnConstraints moveCol = new ColumnConstraints(cardWidth - 118);
        moveCol.setHgrow(Priority.ALWAYS);
        moveGrid.getColumnConstraints().addAll(inputCol, moveCol);

        for (int row = 0; row < moves.length; row++) {
            Label input = new Label(moves[row][0]);
            input.setFont(Font.font("Arial Black", 12));
            input.setTextFill(accent.interpolate(Color.WHITE, 0.26));
            input.setAlignment(Pos.CENTER_RIGHT);
            input.setMaxWidth(Double.MAX_VALUE);
            applyNoEllipsis(input);

            Label move = new Label(moves[row][1]);
            move.setFont(Font.font("Consolas", FontWeight.BOLD, activePlayers >= 4 ? 13 : 14));
            move.setTextFill(Color.WHITE);
            move.setWrapText(true);
            move.setMaxWidth(cardWidth - 118);
            fitWrappedLabelText(move, moves[row][1], cardWidth - 118, 34, 10);

            moveGrid.add(input, 0, row);
            moveGrid.add(move, 1, row);
        }

        Label note = new Label(specialMoveGuideNote(bird.type));
        note.setFont(Font.font("Consolas", activePlayers >= 4 ? 11 : 12));
        note.setTextFill(Color.web("#B0BEC5"));
        note.setWrapText(true);
        note.setTextAlignment(TextAlignment.CENTER);
        note.setAlignment(Pos.CENTER);
        note.setMaxWidth(cardWidth - 28);
        fitWrappedLabelText(note, note.getText(), cardWidth - 28, 34, 9);

        VBox card = new VBox(8, headerBar, moveGrid, note);
        card.setAlignment(Pos.TOP_CENTER);
        card.setPadding(new Insets(10));
        card.setPrefWidth(cardWidth);
        card.setMinWidth(cardWidth);
        card.setMaxWidth(cardWidth);
        card.setStyle("-fx-background-color: rgba(14, 19, 26, 0.94); -fx-background-radius: 16; "
                + "-fx-border-color: " + accentHex + "; -fx-border-width: 2; -fx-border-radius: 16;");
        return card;
    }

    private String[][] specialMoveGuideRows(BirdType type) {
        String[] names = specialMoveNames(type);
        return new String[][]{
                {"Neutral", names[0]},
                {"Side", names[1]},
                {"Up", names[2]},
                {"Down", names[3]}
        };
    }

    private String[] specialMoveNames(BirdType type) {
        if (type == null) {
            return new String[]{"-", "-", "-", "-"};
        }
        return switch (type) {
            case VULTURE -> new String[]{"Summon Crows", "Carrion Glide", "Thermal Lift", "Bone Offering"};
            case BAT -> new String[]{"Echo Lance", "Wingcut", "Moonrise", "Silent Descent + Ceiling Hang"};
            case RAVEN -> new String[]{"Black Quill", "Shadow Warp", "Murder Lift", "Nevermore"};
            case GOOSE -> new String[]{"Threatening Honk", "Bite and Barge", "V-Formation Lift", "Nest Guard"};
            case KIWI -> new String[]{"Rapid Probe", "Burrow Charge", "Spring Kick", "Earth Stomp"};
            case FALCON -> splitSpecialAbility("Egg Scatter / Charged Razor Rush / Jet Climb / Meteor Strike");
            case HEISENBIRD -> splitSpecialAbility("Crystal Cloud / Blue Rush / Crystal Column / Glass Cook");
            default -> splitSpecialAbility(type.ability);
        };
    }

    private String[] splitSpecialAbility(String ability) {
        String source = ability == null ? "" : ability;
        int colon = source.indexOf(':');
        if (colon >= 0 && colon + 1 < source.length()) {
            source = source.substring(colon + 1).trim();
        }
        String[] parts = source.contains("/")
                ? source.split("\\s*/\\s*")
                : source.split("\\s*\\+\\s*");
        String[] moves = {"-", "-", "-", "-"};
        for (int i = 0; i < moves.length && i < parts.length; i++) {
            moves[i] = parts[i].trim().isEmpty() ? "-" : parts[i].trim();
        }
        return moves;
    }

    private String specialMoveGuideNote(BirdType type) {
        if (type == null) {
            return "";
        }
        return switch (type) {
            case TITMOUSE -> "MARK improves follow-ups. STASH can be detonated after arming.";
            case OPIUMBIRD -> "DROWSY slows targets. PATCH refuels the opium meter.";
            case HEISENBIRD -> "BRITTLE boosts crystal damage. NODE refuels the crystal meter.";
            case VULTURE -> "Ultimate: Black Sky Feast floods the arena with crown crows before a final feast launch.";
            case RAVEN -> "Marks and routes set up larger follow-ups, including the ultimate.";
            case GOOSE -> "Territory empowers the next special. Nest Guard counters hits near the nest.";
            case KIWI -> "No meter or setup. Ultimate: Midnight Stampede chains three charges into one broad eruption.";
            case HUMMINGBIRD -> "Ultimate: Needleheart Overdrive locks on, chains three flash pierces, then detonates a nectar final stab.";
            case MOCKINGBIRD -> "Ultimate: Shadow Court summons three fragile dark copies from the Lounge.";
            case ROOSTER -> "Ultimate: Dawn Stampede floods the stage with fast flying swarm chicks.";
            case TURKEY -> "Ultimate: Harvest Tribunal summons a feast altar, pulls enemies in, stuffs them, then delivers a gold verdict slash.";
            case ROADRUNNER -> "Ultimate: Redline Execution zips forward. Whiffing ends fast; catching enemies triggers a speed cutscene and huge launch.";
            case PENGUIN -> "Air down special drops a straight-down iceberg. Ultimate creates an invulnerable ice throne.";
            case SHOEBILL -> "Ultimate: Final Stillness drains the screen, silences music, and fires an ancient locked beam.";
            case RAZORBILL -> "Ultimate: Guillotine Wake marks dodgeable cut-lines, chains slashes, then leaves a damaging razor wake.";
            case GRINCHHAWK -> "Ultimate: Midnight Giftstorm rains trap presents, then sends a stolen sleigh across the stage for a final gift-box slam.";
            case PELICAN -> "Ultimate: Maelstrom Gullet opens a stage vortex, pulls enemies into the pouch zone, then erupts in a tidal launch.";
            case BAT -> "Ceiling Hang gives the down special a second movement state.";
            case PHOENIX -> "Snap Fire travels farther and fizzles harmlessly. Air Snap Fire angles down; air Faultfire can be held.";
            default -> "Directional input changes the special before startup.";
        };
    }

